export interface AgentKindDef {
  kind: AgentKind;
  /** 滑鼠移上去顯示的精準識別文字（如 'Claude Code'）。 */
  label: string;
  /** Logo 檔名（media/icons/ 下）。 */
  logo: string;
  /** 預設 model 清單；空陣列＝沒有現成清單、＋成員時讓 user 自填示範。 */
  models: string[];
  /** 內建綁定：agentKind / model 不可被 /profile 指令改。 */
  locked?: boolean;
  /** 外部種類：＋成員「邀請外部 AI」時列入種類選單。 */
  external?: boolean;
}

export const AGENT_KINDS: AgentKindDef[] = [
  // ── 內建（綁定不可改；沿用既有圖示）──
  { kind: 'base', label: 'Base Agent', logo: 'base.svg', models: [], locked: true },
  { kind: 'aiking', label: 'AI King Agent', logo: 'aiking-gold.svg', models: [], locked: true },
  { kind: 'psycheforge', label: 'PsycheForge', logo: 'kind-psycheforge.png', models: [], locked: true },
  // ── 外部（＋成員「邀請外部 AI」時選、/profile 可改）──
  // [2026-06-19 user] 外部 AI 一律共用同一個圖標 external.svg（不分 claude/codex/各家）；
  //   label 仍各自保留（hover 精準識別）、只統一圖示。供應商真 logo 由「供應商位」另顯示。
  {
    kind: 'claude',
    label: 'Claude Code',
    logo: 'external.svg',
    external: true,
    models: ['Fable 5', 'Opus 4.8', 'Sonnet 4.6', 'Haiku 4.5'],
  },
  {
    kind: 'codex',
    label: 'Codex',
    logo: 'external.svg',
    external: true,
    models: ['GPT-5.5'],
  },
  // OpenClaw / Hermes 的型號清單留空＝給 user 自填示範（偵測不到、各家命名未定）。
  { kind: 'openclaw', label: 'OpenClaw', logo: 'external.svg', external: true, models: [] },
  { kind: 'hermes', label: 'Hermes', logo: 'agent-hermes.png', external: true, models: [] },
  // [v3 2026-06-21 user] 外部 ACP 代理（在對話/群組裡用 ACP 協定接的 Claude Code/Codex…）
  //   ＝機器人頭 ai.svg，跟「邀請進群組的泛稱其他 AI（external.svg ↗）」區分開。
  { kind: 'acp', label: 'ACP', logo: 'ai.svg', external: true, models: [] },
  { kind: 'other', label: '其他 AI', logo: 'external.svg', external: true, models: [] },
  // ── 人類 ──
  { kind: 'human', label: '人類', logo: 'badge-human.svg', models: [] },
];

export function agentKindDef(kind?: string): AgentKindDef | undefined {
  return kind ? BY_KIND.get(kind) : undefined;
}

export function labelForAgentKind(kind?: string): string {
  return agentKindDef(kind)?.label || '其他 AI';
}

export function logoForAgentKind(kind?: string): string {
  return agentKindDef(kind)?.logo || 'ai.svg';
}

export function modelsForAgentKind(kind?: string): string[] {
  return (agentKindDef(kind)?.models || []).slice();
}

export function externalAgentKinds(): AgentKindDef[] {
  return AGENT_KINDS.filter((d) => d.external);
}

export function agentKindForStack(stack?: string): AgentKind {
  if (stack === 'sancio') return 'aiking';
  if (stack === 'digital-human') return 'psycheforge';
  if (stack && stack.startsWith('acp')) return 'acp'; // [v3] 外部 ACP 代理 → 機器人頭 ai.svg（非 external.svg ↗）
  return 'base';
}

export function isAgentKindLocked(kind?: string): boolean {
  return !!agentKindDef(kind)?.locked;
}

export function isValidAgentKind(kind?: string): kind is AgentKind {
  return !!kind && BY_KIND.has(kind);
}

export function parseAgentKind(input?: string): AgentKind | undefined {
  if (!input) return undefined;
  const norm = input.trim().toLowerCase().replace(/\s+/g, '');
  for (const d of AGENT_KINDS) {
    if (d.kind === norm) return d.kind;
    if (d.label.toLowerCase().replace(/\s+/g, '') === norm) return d.kind;
  }
  return undefined;
}

export function aikingAgentSkillFolder(): string {
  try {
    const raw = vscode.workspace
      .getConfiguration('aiKing')
      .get<Array<{ path?: string; locked?: boolean }>>('skillFolders');
    if (Array.isArray(raw)) {
      const locked = raw.find((f) => f && f.locked && typeof f.path === 'string' && f.path.trim());
      if (locked && locked.path) return locked.path;
      if (raw[0] && typeof raw[0].path === 'string' && raw[0].path.trim()) return raw[0].path;
    }
  } catch {
    /* 設定讀失敗 → 退預設 */
  }
  return path.join(os.homedir(), '.aiking', 'skills');
}

export function loadAikingSkillsForPrompt(skillsDir: string, capChars = 8000): string {
  let out = '';
  try {
    if (!skillsDir || !fs.existsSync(skillsDir)) return '';
    for (const name of fs.readdirSync(skillsDir)) {
      const full = path.join(skillsDir, name);
      let body = '';
      let title = name;
      try {
        const st = fs.statSync(full);
        if (st.isDirectory()) {
          const md = path.join(full, 'SKILL.md');
          if (fs.existsSync(md)) body = fs.readFileSync(md, 'utf8');
        } else if (st.isFile() && /\.md$/i.test(name)) {
          body = fs.readFileSync(full, 'utf8');
          title = name.replace(/\.md$/i, '');
        }
      } catch {
        continue; // 單一 skill 讀失敗不影響其餘
      }
      if (!body) continue;
      // 去掉 YAML frontmatter（--- … ---），只留技能正文。
      const stripped = body.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, '').trim();
      if (!stripped) continue;
      out += (out ? '\n\n' : '') + `## ${title}\n${stripped}`;
      if (out.length >= capChars) {
        out = out.slice(0, capChars);
        break;
      }
    }
  } catch {
    return '';
  }
  return out;
}

export function ensureAikingSkillsDir(): void {
  try {
    fs.mkdirSync(aikingAgentSkillFolder(), { recursive: true });
  } catch {
    /* best-effort：建不出來就算了，注入端遇到不存在的資料夾會回 '' */
  }
}

export interface AuthUser {
  id: number;
  username: string;
  created_at: number;
  updated_at: number;
}

export interface LoginResponse {
  token: string;
  token_type: string;
  expires_in: number;
  user: AuthUser;
}

export class AuthError extends Error {
  constructor(
    public readonly status: number,
    message: string,
    public readonly detail?: string,
  ) {
    super(message);
    this.name = 'AuthError';
  }
}

constructor(
  public readonly status: number,
  message: string,
  public readonly detail?: string,
) {
  super(message);
  this.name = 'AuthError';
}

export function resolveAuthEndpoint(): string {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const explicit = cfg.get<string>('authServerEndpoint');
  if (explicit && explicit.length > 0) return explicit;
  const stacks = cfg.get<Record<string, string>>('stackEndpoints') || {};
  if (stacks.sancio) return stacks.sancio;
  return cfg.get<string>('sancioEndpoint') || 'https://account.ai-king.dev';
}

async function parseJsonSafe(resp: Response): Promise<any> {
  try {
    return await resp.json();
  } catch {
    return null;
  }
}

async function authFetch(
  path: string,
  init: RequestInit,
  token?: string,
): Promise<any> {
  const endpoint = resolveAuthEndpoint();
  // Reuse the Sancio SSRF allow-list — auth server host must be trusted.
  assertSancioEndpointAllowed(endpoint);
  const url = new URL(path, endpoint).toString();
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...((init.headers as Record<string, string>) || {}),
  };
  if (token) headers.Authorization = `Bearer ${token}`;
  let resp: Response;
  try {
    resp = await fetch(url, { ...init, headers });
  } catch (e: any) {
    log.error('auth:network', { path, detail: String(e?.message || e) });
    throw new AuthError(0, `network error: ${String(e?.message || e)}`);
  }
  const body = await parseJsonSafe(resp);
  if (!resp.ok) {
    const detail = (body && (body.detail || body.error)) || resp.statusText;
    throw new AuthError(resp.status, `HTTP ${resp.status}: ${detail}`, detail);
  }
  return body;
}

export async function login(
  username: string,
  password: string,
): Promise<LoginResponse> {
  return (await authFetch('/v1/auth/login', {
    method: 'POST',
    body: JSON.stringify({ username, password }),
  })) as LoginResponse;
}

export async function whoami(token: string): Promise<AuthUser> {
  const r = await authFetch('/v1/auth/me', { method: 'GET' }, token);
  return r.user as AuthUser;
}

export async function checkUsernameExists(
  username: string,
): Promise<boolean | undefined> {
  const u = username.trim();
  if (!u) return undefined;
  try {
    const r = await authFetch(
      `/v1/auth/exists?username=${encodeURIComponent(u)}`,
      { method: 'GET' },
    );
    if (r && typeof r.exists === 'boolean') return r.exists;
    return undefined;
  } catch (e) {
    // 端點未上線(404)/網路/任何錯 → 無法判定，不阻斷登入（graceful fallback）。
    log.warn('auth:exists-precheck', {
      detail: String((e as any)?.message || e),
    });
    return undefined;
  }
}

export async function logout(token: string): Promise<void> {
  await authFetch('/v1/auth/logout', { method: 'POST' }, token);
}

export async function getRemoteConfig(token: string): Promise<Record<string, unknown>> {
  const r = await authFetch('/v1/config', { method: 'GET' }, token);
  return (r.config as Record<string, unknown>) || {};
}

export async function putRemoteConfig(
  token: string,
  config: Record<string, unknown>,
): Promise<void> {
  await authFetch(
    '/v1/config',
    { method: 'PUT', body: JSON.stringify({ config }) },
    token,
  );
}

export async function changePassword(
  token: string,
  oldPw: string,
  newPw: string,
): Promise<void> {
  await authFetch(
    '/v1/auth/change-password',
    { method: 'POST', body: JSON.stringify({ old: oldPw, new: newPw }) },
    token,
  );
}

export async function getStoredToken(
  ctx: vscode.ExtensionContext,
): Promise<string | undefined> {
  return ctx.secrets.get(AUTH_TOKEN_SECRET);
}

export async function setStoredToken(
  ctx: vscode.ExtensionContext,
  token: string | undefined,
  username: string | undefined,
  // [1.14.0 帳號線 P1a] 第 4 參＝穩定 account id。與 token/username 同「給值就存、
  // undefined 就清」獨立語意：登出(三者皆 undefined)＝全清；重登失敗(只留 username)＝
  // token+id 清、username 留供下次靜默重登。漏傳 id 不會誤清 token，但登入務必傳齊。
  accountId?: number | string,
): Promise<void> {
  if (token) await ctx.secrets.store(AUTH_TOKEN_SECRET, token);
  else await ctx.secrets.delete(AUTH_TOKEN_SECRET);
  if (username) await ctx.secrets.store(AUTH_USERNAME_SECRET, username);
  else await ctx.secrets.delete(AUTH_USERNAME_SECRET);
  if (accountId !== undefined && accountId !== null && `${accountId}` !== '') {
    await ctx.secrets.store(AUTH_ACCOUNT_ID_SECRET, `${accountId}`);
  } else {
    await ctx.secrets.delete(AUTH_ACCOUNT_ID_SECRET);
  }
}

export async function getStoredUsername(
  ctx: vscode.ExtensionContext,
): Promise<string | undefined> {
  return ctx.secrets.get(AUTH_USERNAME_SECRET);
}

export async function getStoredAccountId(
  ctx: vscode.ExtensionContext,
): Promise<string | undefined> {
  return ctx.secrets.get(AUTH_ACCOUNT_ID_SECRET);
}

export async function getStoredPassword(
  ctx: vscode.ExtensionContext,
): Promise<string | undefined> {
  return ctx.secrets.get(AUTH_PASSWORD_SECRET);
}

export async function setStoredPassword(
  ctx: vscode.ExtensionContext,
  password: string | undefined,
): Promise<void> {
  if (password) await ctx.secrets.store(AUTH_PASSWORD_SECRET, password);
  else await ctx.secrets.delete(AUTH_PASSWORD_SECRET);
}

export async function attemptAutoLogin(
  ctx: vscode.ExtensionContext,
): Promise<boolean> {
  const existing = await getStoredToken(ctx);
  if (existing) {
    try {
      await whoami(existing);
      return true; // token still good
    } catch (e) {
      if (!(e instanceof AuthError) || e.status !== 401) {
        // Network / server issue — don't nuke creds, just bail.
        log.warn('auth:auto-login:whoami-transient', {
          detail: String((e as any)?.message || e),
        });
        return false;
      }
      // 401 → token expired; fall through to re-login below.
    }
  }
  const username = await getStoredUsername(ctx);
  const password = await getStoredPassword(ctx);
  if (!username || !password) return false;
  try {
    const r = await login(username, password);
    await setStoredToken(ctx, r.token, r.user.username, r.user.id);
    log.info('auth:auto-login:success', { username: r.user.username });
    return true;
  } catch (e) {
    log.warn('auth:auto-login:failed', {
      detail: String((e as any)?.message || e),
    });
    // If server told us the password is wrong (401/403), wipe it so we
    // stop retrying with stale creds every startup.
    if (e instanceof AuthError && (e.status === 401 || e.status === 403)) {
      await setStoredPassword(ctx, undefined);
      await setStoredToken(ctx, undefined, username);
    }
    return false;
  }
}

export const SYNC_FIELDS: ReadonlyArray<string> = [
  'stackEndpoints',
  'sancioAllowedHosts',
  'digitalHumanCharacterName',
  'digitalHumanChatPath',
  'digitalHumanTrial',
  'sancioEndpoint',
  'digitalHumanUserId',
  // 0.17.0 — mm9319 is seeded with `autoApproveAll: true` on the server,
  // so signing in pulls it down and the permission gate silently passes.
  'autoApproveAll',
];

export async function syncConfigFromRemote(
  ctx: vscode.ExtensionContext,
): Promise<number> {
  const token = await getStoredToken(ctx);
  if (!token) throw new Error('not signed in');
  const remote = await getRemoteConfig(token);
  const cfg = vscode.workspace.getConfiguration('aiKing');
  let applied = 0;
  for (const key of SYNC_FIELDS) {
    if (!(key in remote)) continue;
    try {
      await cfg.update(key, remote[key], vscode.ConfigurationTarget.Global);
      applied += 1;
    } catch (e: any) {
      log.warn('auth:sync-from-remote:apply', {
        key,
        detail: String(e?.message || e),
      });
    }
  }
  log.info('auth:sync-from-remote:done', { applied });
  return applied;
}

export async function pushConfigToRemote(
  ctx: vscode.ExtensionContext,
): Promise<number> {
  const token = await getStoredToken(ctx);
  if (!token) throw new Error('not signed in');
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const payload: Record<string, unknown> = {};
  for (const key of SYNC_FIELDS) {
    const value = cfg.get<unknown>(key);
    if (value === undefined) continue;
    payload[key] = value;
  }
  await putRemoteConfig(token, payload);
  log.info('auth:push-to-remote:done', { fields: Object.keys(payload).length });
  return Object.keys(payload).length;
}

export async function trySyncOnStartup(
  ctx: vscode.ExtensionContext,
): Promise<void> {
  try {
    const token = await getStoredToken(ctx);
    if (!token) return;
    const n = await syncConfigFromRemote(ctx);
    log.info('auth:startup-sync', { applied: n });
  } catch (e: any) {
    log.warn('auth:startup-sync:failed', { detail: String(e?.message || e) });
  }
}

export interface MdImportResult {
  filePath: string;
  found: { provider: string; keyPreview: string }[];
  missing: string[];
}

const KEY_PATTERNS: Array<{
  /** Provider slug used by setProviderKey + BUILTIN_PROVIDERS. */
  providerId: string;
  /** Human label for messages. */
  label: string;
  /** Regex pinning the key — anchored to the canonical prefix. */
  pattern: RegExp;
  /** Extra provider slots that should receive the same value. */
  mirrors?: string[];
}> = [
  {
    providerId: 'anthropic',
    label: 'Anthropic',
    // sk-ant-api03-... standard Anthropic prefix. Avoid capturing trailing
    // backticks / pipes / whitespace from the markdown table cell.
    pattern: /sk-ant-[A-Za-z0-9_\-]+/,
    mirrors: ['ai-king-backend'],
  },
  {
    providerId: 'openai',
    label: 'OpenAI',
    // sk-proj-... or legacy sk-... (≥20 chars after).
    pattern: /sk-proj-[A-Za-z0-9_\-]{20,}/,
  },
];

export function resolveMdPath(filePath?: string): string | undefined {
  if (filePath && filePath.length > 0) return filePath;
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const configured = cfg.get<string>('keyMdFilePath');
  if (configured && configured.length > 0) return configured;
  // Fall back to a per-workspace file the user controls. We don't stat here —
  // the caller tries to read and surfaces a clean error if it's missing.
  const folders = vscode.workspace.workspaceFolders;
  if (folders && folders.length > 0) {
    return path.join(folders[0].uri.fsPath, '所有API.md');
  }
  return undefined;
}

export function parseKeysFromMd(md: string): Record<string, string> {
  const found: Record<string, string> = {};
  for (const spec of KEY_PATTERNS) {
    const m = md.match(spec.pattern);
    if (m) found[spec.providerId] = m[0];
  }
  return found;
}

export async function importKeysFromMd(
  ctx: vscode.ExtensionContext,
  filePath?: string,
): Promise<MdImportResult> {
  const resolved = resolveMdPath(filePath);
  if (!resolved) {
    throw new Error('No md path resolved (set aiKing.keyMdFilePath).');
  }
  let md: string;
  try {
    md = await fs.readFile(resolved, 'utf8');
  } catch (e: any) {
    throw new Error(`讀 md 失敗 (${resolved}): ${String(e?.message || e)}`);
  }
  const keys = parseKeysFromMd(md);
  const found: MdImportResult['found'] = [];
  const missing: string[] = [];
  for (const spec of KEY_PATTERNS) {
    const k = keys[spec.providerId];
    if (!k) {
      missing.push(spec.label);
      continue;
    }
    await setProviderKey(ctx, spec.providerId, k);
    if (spec.mirrors) {
      for (const m of spec.mirrors) {
        await setProviderKey(ctx, m, k);
      }
    }
    const preview =
      k.length <= 16 ? k : `${k.slice(0, 10)}...${k.slice(-4)}`;
    found.push({ provider: spec.label, keyPreview: preview });
  }
  log.info('auth:md-import:done', {
    filePath: resolved,
    found: found.length,
    missing: missing.length,
  });
  return { filePath: resolved, found, missing };
}

async function fireAuthChanged(ctx: vscode.ExtensionContext): Promise<void> {
  if (!onAuthChanged) return;
  try {
    await onAuthChanged(ctx);
  } catch (e: any) {
    log.warn('auth:onAuthChanged', { detail: String(e?.message || e) });
  }
}

export async function refreshStatusBar(
  ctx: vscode.ExtensionContext,
): Promise<void> {
  if (!statusBarItem) return;
  const token = await getStoredToken(ctx);
  const username = await getStoredUsername(ctx);
  if (token && username) {
    statusBarItem.text = `$(account) ${username}`;
    statusBarItem.tooltip = `AI King: 已登入為 ${username} (點擊登出)`;
    statusBarItem.command = 'aiKing.auth.signOut';
  } else {
    statusBarItem.text = '$(sign-in) Sign In';
    statusBarItem.tooltip = 'AI King: 尚未登入，點擊登入啟用雲端同步';
    statusBarItem.command = 'aiKing.auth.signIn';
  }
  statusBarItem.show();
}

function toastError(prefix: string, e: unknown): void {
  const msg = e instanceof AuthError
    ? `${prefix} — ${e.detail || e.message}`
    : `${prefix} — ${String((e as any)?.message || e)}`;
  vscode.window.showErrorMessage(msg);
}

async function cmdSignIn(ctx: vscode.ExtensionContext): Promise<void> {
  const rememberedUser = await getStoredUsername(ctx);
  const username = await showInputBoxEsc({
    title: 'AI King: Sign In — Username',
    prompt: '輸入帳號',
    placeHolder: 'username',
    value: rememberedUser ?? '',
    ignoreFocusOut: true,
  });
  if (!username) return;

  // [1.16.0 帳號線 UX] 輸密碼前先 pre-check 帳號是否存在：不存在直接說、不給打密碼
  // （user directive）。undefined＝後端 /v1/auth/exists 未上線或網路問題 → graceful
  // fallback，照常進密碼步驟（登入流程不受影響、退回舊行為）。
  const exists = await checkUsernameExists(username.trim());
  if (exists === false) {
    const pick = await vscode.window.showWarningMessage(
      `AI King: 帳號「${username.trim()}」不存在`,
      '重新輸入',
    );
    if (pick === '重新輸入') await cmdSignIn(ctx);
    return; // 不進密碼步驟
  }

  const password = await showInputBoxEsc({
    title: 'AI King: Sign In — Password',
    prompt: `密碼 for ${username}`,
    password: true,
    ignoreFocusOut: true,
  });
  if (password === undefined) return;
  // 0.22.0 — opt-in remember password for silent 24h re-login.
  const rememberPick = await showQuickPickEsc(
    [
      {
        label: '$(key) 記住密碼 — 自動登入',
        detail:
          '密碼存入 OS keyring (SecretStorage)。24h JWT 過期後靜默重新登入。',
        remember: true,
      },
      {
        label: '$(circle-slash) 不記 — 僅此次',
        detail: 'JWT 24h 後需手動重登。',
        remember: false,
      },
    ],
    {
      title: 'AI King: 要不要記住密碼？',
      placeHolder: '只存本機 keyring，不上傳',
      ignoreFocusOut: true,
    },
  );
  const remember = rememberPick?.remember === true;
  try {
    const r = await login(username.trim(), password);
    await setStoredToken(ctx, r.token, r.user.username, r.user.id);
    if (remember) {
      await setStoredPassword(ctx, password);
    } else {
      // User picked "not remember" — purge any previous cached password.
      await setStoredPassword(ctx, undefined);
    }
    vscode.window.showInformationMessage(
      `AI King: 登入成功 (${r.user.username})${remember ? ' — 已記住密碼' : ''}`,
    );
    // [1.14.0 帳號線 P1a] 切到 <accountId> profile（首次登入彈綁定框）+ reload。必須在
    // accountId 已存（上面 setStoredToken 第 4 參）之後、雲端 config 同步之前。
    await fireAuthChanged(ctx);
    try {
      await syncConfigFromRemote(ctx);
    } catch (e: any) {
      log.warn('auth:pull-after-login', { detail: String(e?.message || e) });
    }
  } catch (e) {
    toastError('AI King: 登入失敗', e);
  } finally {
    await refreshStatusBar(ctx);
  }
}

async function cmdSignOut(ctx: vscode.ExtensionContext): Promise<void> {
  const hasRememberedPw = (await getStoredPassword(ctx)) !== undefined;
  type SignOutItem = vscode.QuickPickItem & {
    action: 'keep' | 'wipe' | 'cancel';
  };
  const items: SignOutItem[] = [];
  items.push({
    label: '登出 (保留記住的密碼)',
    detail: '清 JWT，下次仍可自動重登。適合暫時斷線',
    action: 'keep',
  });
  if (hasRememberedPw) {
    items.push({
      label: '登出 + 忘記密碼',
      detail: '清 JWT + 清記住的密碼。下次需重新輸入',
      action: 'wipe',
    });
  }
  items.push({ label: '取消', detail: '維持登入', action: 'cancel' });
  const pick = await vscode.window.showQuickPick<SignOutItem>(items, {
    title: 'AI King: Sign Out',
  });
  if (!pick || pick.action === 'cancel') return;
  const token = await getStoredToken(ctx);
  if (token) {
    try {
      await logout(token);
    } catch {
      // Best-effort — local state still wins.
    }
  }
  await setStoredToken(ctx, undefined, undefined);
  if (pick.action === 'wipe') {
    await setStoredPassword(ctx, undefined);
  }
  vscode.window.showInformationMessage(
    pick.action === 'wipe' ? 'AI King: 已登出並清除密碼' : 'AI King: 已登出',
  );
  // [1.14.0 帳號線 P1a] 切回訪客 _guest profile + reload（accountId 已隨 setStoredToken 清）。
  await fireAuthChanged(ctx);
  await refreshStatusBar(ctx);
}

