async function cmdChangePassword(ctx: vscode.ExtensionContext): Promise<void> {
  const token = await getStoredToken(ctx);
  if (!token) {
    vscode.window.showWarningMessage('AI King: 尚未登入');
    return;
  }
  const oldPw = await showInputBoxEsc({
    title: 'AI King: Change Password — 舊密碼',
    password: true,
    ignoreFocusOut: true,
  });
  if (oldPw === undefined) return;
  const newPw = await showInputBoxEsc({
    title: 'AI King: Change Password — 新密碼 (至少 4 字元)',
    password: true,
    ignoreFocusOut: true,
  });
  if (newPw === undefined) return;
  if (newPw.length < 4) {
    vscode.window.showErrorMessage('AI King: 新密碼至少 4 字元');
    return;
  }
  try {
    await changePassword(token, oldPw, newPw);
    vscode.window.showInformationMessage('AI King: 密碼已更新，請重新登入');
    await setStoredToken(ctx, undefined, undefined);
    // 0.22.0 — stored password is now stale; wipe so auto-login doesn't
    // keep re-trying with the old creds and trip rate limits.
    await setStoredPassword(ctx, undefined);
    // [1.14.0 帳號線 P1a] 改密碼＝已登出 → 切回 _guest profile。
    await fireAuthChanged(ctx);
    await refreshStatusBar(ctx);
  } catch (e) {
    toastError('AI King: 改密碼失敗', e);
  }
}

