export function registerAutoModeStatusBar(ctx: vscode.ExtensionContext): void {
  // Right-aligned, lower priority than auth (which uses ~100). 50 keeps it
  // visible without crowding the user's existing status bar layout.
  item = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 50);
  item.command = 'aiKing.autoMode.toggle';
  ctx.subscriptions.push(item);

  // Re-render whenever config changes (mode flip, threshold change,
  // showStatusBar toggle).
  ctx.subscriptions.push(
    vscode.workspace.onDidChangeConfiguration((e) => {
      if (
        e.affectsConfiguration('aiKing.lastMode') ||
        e.affectsConfiguration('aiKing.disableAutoMode') ||
        e.affectsConfiguration('aiKing.autoMode.showStatusBar')
      ) {
        refreshAutoModeStatusBar();
      }
    }),
  );

  refreshAutoModeStatusBar();
}

export function refreshAutoModeStatusBar(): void {
  if (!item) return;
  const cfg = vscode.workspace.getConfiguration('aiKing');

  if (cfg.get<boolean>('autoMode.showStatusBar') === false) {
    item.hide();
    return;
  }

  // [A8] fallback 對齊 getLastMode（DEFAULT_MODE='auto'）：全新 user config 未設時，
  // 實際派發走 auto，狀態列也該認 auto（原寫死 'edits' → status bar 對全新 user 不顯示）。
  const mode = cfg.get<string>('lastMode') || DEFAULT_MODE;
  const disabled = cfg.get<string>('disableAutoMode') === 'disable';

  if (mode !== 'auto' || disabled) {
    item.hide();
    return;
  }

  const stats = getStats();
  const verdict = getLastVerdict();

  if (isTripped()) {
    item.text = `$(warning) Auto Paused · ${stats.totalApprovals}✓ ${stats.totalBlocks}✗`;
    item.tooltip = buildTrippedTooltip(stats);
    item.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
  } else {
    item.text = `$(zap) Auto · ${stats.totalApprovals}✓ ${stats.totalBlocks}✗`;
    item.tooltip = buildActiveTooltip(stats, verdict);
    item.backgroundColor = undefined;
  }
  item.show();
}

function buildActiveTooltip(
  stats: ReturnType<typeof getStats>,
  verdict: ReturnType<typeof getLastVerdict>,
): vscode.MarkdownString {
  const md = new vscode.MarkdownString();
  md.isTrusted = false;
  md.appendMarkdown(`**AI King · Auto Mode active**\n\n`);
  md.appendMarkdown(`- ${stats.totalApprovals} auto-approved · ${stats.totalBlocks} blocked\n`);
  md.appendMarkdown(`- Streak: ${stats.consecutiveBlocks}/${stats.thresholdConsecutive} consecutive blocks\n`);
  md.appendMarkdown(`- Pause threshold: ${stats.thresholdConsecutive} in a row or ${stats.thresholdTotal} total\n`);
  if (verdict) {
    const ago = Math.max(0, Math.floor((Date.now() - verdict.at) / 1000));
    md.appendMarkdown(`\n**Last call:** \`${verdict.tool}\` → ${verdict.level} (${ago}s ago)\n`);
    md.appendMarkdown(`> ${verdict.reason}\n`);
  }
  md.appendMarkdown(`\nClick to leave Auto Mode.`);
  return md;
}

function buildTrippedTooltip(stats: ReturnType<typeof getStats>): vscode.MarkdownString {
  const md = new vscode.MarkdownString();
  md.isTrusted = false;
  md.appendMarkdown(`**AI King · Auto Mode paused**\n\n`);
  md.appendMarkdown(`Auto Mode auto-paused after ${stats.totalBlocks} blocked operations`);
  md.appendMarkdown(` (${stats.consecutiveBlocks} in a row, threshold ${stats.thresholdConsecutive}).\n\n`);
  md.appendMarkdown(`The classifier flagged repeated risky tool calls. The gate is back to asking on every call.\n\n`);
  md.appendMarkdown(`Click to re-enter Auto Mode (resets the streak counter).`);
  return md;
}

