interface BootstrapKeys {
  anthropic?: string;
  openai?: string;
}

export async function importBootstrapKeys(ctx: vscode.ExtensionContext): Promise<void> {
  const file = vscode.Uri.joinPath(ctx.globalStorageUri, '.bootstrap-keys.json');
  let buf: Uint8Array;
  try {
    buf = await vscode.workspace.fs.readFile(file);
  } catch (e: any) {
    if (e?.code === 'FileNotFound' || e?.name === 'EntryNotFound (FileSystemError)') {
      return; // nothing to import — normal path
    }
    console.warn(`[ai-king] bootstrap read failed: ${e?.message || e}`);
    return;
  }

  let parsed: BootstrapKeys;
  try {
    parsed = JSON.parse(new TextDecoder().decode(buf));
  } catch (e: any) {
    console.warn(`[ai-king] bootstrap parse failed: ${e?.message || e}`);
    return;
  }

  let imported = 0;
  if (parsed.anthropic && parsed.anthropic.length > 10) {
    // Write to new provider slots (v0.5.0+): both ai-king-backend and direct anthropic.
    await ctx.secrets.store('aiKing.providers.ai-king-backend.apiKey', parsed.anthropic);
    await ctx.secrets.store('aiKing.providers.anthropic.apiKey', parsed.anthropic);
    // Keep legacy slot non-destructive so v0.4.0 downgrade still works.
    await ctx.secrets.store('aiKing.anthropicApiKey', parsed.anthropic);
    imported++;
  }
  if (parsed.openai && parsed.openai.length > 10) {
    await ctx.secrets.store('aiKing.providers.openai.apiKey', parsed.openai);
    await ctx.secrets.store('aiKing.openaiApiKey', parsed.openai);
    imported++;
  }

  try {
    await vscode.workspace.fs.delete(file);
  } catch (e: any) {
    console.warn(`[ai-king] bootstrap delete failed: ${e?.message || e}`);
  }

  if (imported > 0) {
    vscode.window.showInformationMessage(
      `AI King: ${imported} API key(s) imported from bootstrap file.`,
    );
  }
}

function skillVersion(skillMdPath: string): string {
  try {
    const txt = fs.readFileSync(skillMdPath, 'utf8');
    const fm = txt.match(/^---\r?\n([\s\S]*?)\r?\n---/);
    if (!fm) return '';
    const m = fm[1].match(/^version:\s*(.+)\s*$/m);
    return m ? m[1].trim() : '';
  } catch {
    return '';
  }
}

export function ensureBundledSkills(ctx: vscode.ExtensionContext): void {
  try {
    const enabled = vscode.workspace
      .getConfiguration('aiKing')
      .get<boolean>('skillAutoSync', true);
    if (!enabled) return;
    const srcRoot = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'skills').fsPath;
    if (!fs.existsSync(srcRoot)) return;
    const dstRoot = path.join(os.homedir(), '.claude', 'skills');
    for (const name of fs.readdirSync(srcRoot)) {
      const srcDir = path.join(srcRoot, name);
      const srcSkill = path.join(srcDir, 'SKILL.md');
      if (!fs.existsSync(srcSkill)) continue;
      try {
        const dstDir = path.join(dstRoot, name);
        const dstSkill = path.join(dstDir, 'SKILL.md');
        const srcVer = skillVersion(srcSkill) || '0.0.0';
        const dstVer = fs.existsSync(dstSkill) ? skillVersion(dstSkill) || '0.0.0' : '';
        // Install if missing, or bundled version is strictly newer than installed.
        if (dstVer && !semverGt(srcVer, dstVer)) continue; // up to date / user has newer
        copySkillDir(srcDir, dstDir);
        // eslint-disable-next-line no-console
        console.log(`[ai-king] synced bundled skill v${srcVer} -> ~/.claude/skills/${name}`);
      } catch {
        /* per-skill best-effort */
      }
    }
  } catch {
    /* best-effort; a missing bundle just means the skill is installed manually */
  }
}

export function registerSkillInstall(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.skill.install', async () => {
      const srcRoot = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'skills').fsPath;
      if (!fs.existsSync(srcRoot)) {
        void vscode.window.showErrorMessage('AI King：找不到打包的 Skill 來源。');
        return;
      }
      // 先問是「哪一種 AI」—— 每種 AI 的讀取方式不同，下面再分流到對應轉接器。
      const pick = await showQuickPickEsc(SKILL_TARGET_ITEMS, {
        placeHolder: '把 AI King Skill 安裝給哪一種 AI？（按 ESC 取消）',
        ignoreFocusOut: true,
      });
      if (!pick) return;
      try {
        let msg: string | undefined;
        switch (pick.target) {
          case 'aiking-builtin':
            msg = installForAiKingBuiltin();
            break;
          case 'claude':
            msg = installForClaude(srcRoot);
            break;
          case 'codex':
            msg = installForCodex(srcRoot);
            break;
          case 'copy-pick':
            msg = await installForCopyPick(srcRoot); // user 取消 → undefined
            break;
          case 'open':
            msg = installOpenSource(srcRoot);
            break;
        }
        if (msg) void vscode.window.showInformationMessage(`AI King：${msg}`);
      } catch (e) {
        void vscode.window.showErrorMessage(
          `AI King：Skill 安裝失敗 — ${e instanceof Error ? e.message : String(e)}`,
        );
      }
    }),
  );
}

function sessAllowSet(sessionId: string): Set<string> {
  let s = sessionAllow.get(sessionId);
  if (!s) {
    s = new Set<string>();
    sessionAllow.set(sessionId, s);
  }
  return s;
}

