function isWriteClass(kind: string): boolean {
  return !READ_ONLY_KINDS.has((kind || '').toLowerCase());
}

interface AcpOption {
  optionId?: string;
  name?: string;
  kind?: string;
}

function pickOutcome(options: AcpOption[], want: 'allow' | 'reject'): unknown {
  const wantKinds =
    want === 'allow' ? ['allow_once', 'allow_always'] : ['reject_once', 'reject_always'];
  for (const k of wantKinds) {
    const o = options.find((x) => (x.kind || '').toLowerCase() === k);
    if (o?.optionId) return { outcome: { outcome: 'selected', optionId: o.optionId } };
  }
  // fallback：用 optionId/name 文字猜（不同代理 options 命名不一）。
  const re = want === 'allow' ? /allow|yes|approve|accept|grant/i : /reject|deny|\bno\b|cancel/i;
  const o = options.find((x) => re.test(x.optionId || '') || re.test(x.name || ''));
  if (o?.optionId) return { outcome: { outcome: 'selected', optionId: o.optionId } };
  if (want === 'reject') return { outcome: { outcome: 'cancelled' } };
  return options[0]?.optionId
    ? { outcome: { outcome: 'selected', optionId: options[0].optionId } }
    : { outcome: { outcome: 'cancelled' } };
}

const KIND_LABEL: Record<string, string> = {
  edit: '寫入／編輯檔案',
  delete: '刪除檔案',
  move: '移動／改名檔案',
  execute: '執行命令',
  fetch: '連網抓取',
  other: '工具操作',
};

function kindLabel(kind: string): string {
  return KIND_LABEL[(kind || '').toLowerCase()] || `工具操作（${kind || '未知'}）`;
}

export interface AcpPermissionRequest {
  ctx: vscode.ExtensionContext;
  mode: ChatMode;
  sessionId: string;
  agentLabel: string;
  toolKind: string;
  toolTitle: string;
  options: AcpOption[];
}

export async function decideAcpPermission(req: AcpPermissionRequest): Promise<unknown> {
  const { ctx, mode, sessionId, agentLabel, toolKind, toolTitle, options } = req;
  const write = isWriteClass(toolKind);

  // Auto：完全放行（守門員之後再上）。
  if (mode === 'auto') return pickOutcome(options, 'allow');

  // Chat / Plan：唯讀放行、寫入/執行一律擋（純聊天/計畫＝不改檔不跑命令）。
  if (mode === 'chat' || mode === 'plan') {
    if (!write) return pickOutcome(options, 'allow');
    log.info('acp:perm:deny:readonly-mode', { mode, toolKind, toolTitle });
    return pickOutcome(options, 'reject');
  }

  // Edits：唯讀直接放行（讀檔不擋，業界做法）。
  if (!write) return pickOutcome(options, 'allow');

  // Edits + 寫入/執行：查兩層放行清單 → 命中放行。
  const key = (toolKind || 'other').toLowerCase();
  if (sessAllowSet(sessionId).has(key)) return pickOutcome(options, 'allow');
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const persisted = cfg.get<string[]>(PERSIST_KEY) || [];
  if (persisted.includes(key)) return pickOutcome(options, 'allow');

  // 未放行 → 彈窗問（業界主流 4 選項）。
  const label = kindLabel(toolKind);
  const ONCE = '✓ 允許這次';
  const SESS = `✓ 本對話都允許「${label}」`;
  const ALWAYS = `★ 永久允許「${label}」（寫入設定、之後不再問）`;
  const DENY = '✗ 拒絕';
  const choice = await showQuickPickEsc(
    [
      { label: ONCE, detail: toolTitle },
      { label: SESS, detail: '這個對話視窗內，之後同類操作不再問' },
      { label: ALWAYS, detail: `寫進 aiKing.acp.allowedKinds（${key}）` },
      { label: DENY, detail: 'ESC 也等於拒絕' },
    ],
    {
      title: `「${agentLabel}」要求${label}`,
      placeHolder: `${toolTitle}`,
      ignoreFocusOut: true,
    },
  );
  if (!choice || choice.label === DENY) {
    log.info('acp:perm:user-deny', { toolKind, toolTitle });
    return pickOutcome(options, 'reject');
  }
  if (choice.label === SESS) sessAllowSet(sessionId).add(key);
  if (choice.label === ALWAYS && !persisted.includes(key)) {
    await cfg.update(PERSIST_KEY, [...persisted, key], vscode.ConfigurationTarget.Global);
  }
  return pickOutcome(options, 'allow');
}

export function getAcpAllowedKinds(): string[] {
  return vscode.workspace.getConfiguration('aiKing').get<string[]>(PERSIST_KEY) || [];
}

export async function resetAcpAllowedKinds(): Promise<void> {
  await vscode.workspace
    .getConfiguration('aiKing')
    .update(PERSIST_KEY, [], vscode.ConfigurationTarget.Global);
}

export interface ACPRunRequest {
  ctx: vscode.ExtensionContext;
  store: SessionStore;
  sessionId: string;
  mode: ChatMode;
  /** 要起哪個 ACP 代理、怎麼起（由 resolveAcpLaunch 從設定取得）。 */
  launch: AcpLaunchSpec;
  /** 顯示／log 用的代理名（claude / gemini / hermes…）。 */
  agentLabel: string;
  userMessage: string;
  /** 看圖輸入：圖片附件（base64 + mime），映射成 ACP image content block 送給代理看。 */
  images?: Array<{ data: string; mimeType: string }>;
  /** AI King 保有 canonical 歷史；ACP 代理自己在 session 裡保有脈絡（跨輪重用連線）。 */
  history: ChatMessage[];
  signal: vscode.CancellationToken;
  emit: (event: RunnerEvent) => void;
}

function mapUpdate(update: any, state: { text: string }, emit: (e: RunnerEvent) => void): void {
  switch (update?.sessionUpdate) {
    case 'agent_message_chunk': {
      const c = update.content;
      if (c?.type === 'text' && typeof c.text === 'string' && c.text.length > 0) {
        state.text += c.text;
        emit({ type: 'text', value: c.text });
      }
      break;
    }
    case 'agent_thought_chunk': {
      const c = update.content;
      if (c?.type === 'text' && typeof c.text === 'string' && c.text.length > 0) {
        emit({ type: 'thinking', value: c.text });
      }
      break;
    }
    case 'tool_call':
      emit({
        type: 'tool_start',
        name: String(update.title ?? update.toolCallId ?? 'tool'),
        preview: String(update.status ?? ''),
        args: update.rawInput ?? update.input,
      });
      break;
    case 'tool_call_update':
      if (update.status === 'completed' || update.status === 'failed') {
        emit({
          type: 'tool_result',
          name: String(update.toolCallId ?? 'tool'),
          ok: update.status === 'completed',
          output: '',
        });
      }
      break;
    default:
      // plan / available_commands_update / 其他：MVP 先略過、不渲染（不崩）。
      break;
  }
}

export async function runViaACP(req: ACPRunRequest): Promise<void> {
  if (req.signal.isCancellationRequested) {
    req.emit({ type: 'error', message: 'request cancelled before start' });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  // 1. 落盤 user 這輪（AI King canonical 紀錄，獨立於代理自己的 session）。
  await req.store.append(req.sessionId, {
    role: 'user',
    content: req.userMessage,
    ts: Date.now(),
  });

  const state = { text: '' };

  // [事件驅動超時 2026-06-21] 單輪結算守衛：error/done 至多發一次。讓「子進程死亡 onAbort」與
  // 「prompt() 正常 resolve/reject」競態時只結算第一個、不雙發（雙 error 泡泡 / 重複 done）。
  let settled = false;
  const finish = (errorMsg?: string): void => {
    if (settled) return;
    settled = true;
    if (errorMsg) req.emit({ type: 'error', message: errorMsg });
    req.emit({ type: 'done', mode: 'primary' });
  };

  // 2. 取得／建立這場對話的 ACP 連線（冪等：跨輪重用）。
  let conn: Awaited<ReturnType<typeof ensureAcpConnection>>;
  try {
    conn = await ensureAcpConnection(req.sessionId, req.launch);
  } catch (e: any) {
    log.error('acp:ensure:fail', { sessionId: req.sessionId, msg: e?.message });
    req.emit({
      type: 'error',
      message: `ACP 代理起動失敗（${req.agentLabel}）：${e?.message ?? e}`,
    });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  // 3. 把這一輪的更新導向 emit；並依當輪模式接上工具權限決策（Chat/Plan 擋寫入、Edits
  //    彈窗問、Auto 全放行）——解「Chat 純聊天卻能改檔跑命令」。
  conn.sink = (update: unknown) => mapUpdate(update, state, req.emit);
  conn.permission = (preq) =>
    decideAcpPermission({
      ctx: req.ctx,
      mode: req.mode,
      sessionId: req.sessionId,
      agentLabel: req.agentLabel,
      toolKind: preq.toolKind,
      toolTitle: preq.toolTitle,
      options: preq.options as Array<{ optionId?: string; name?: string; kind?: string }>,
    });
  // [事件驅動超時] 子進程「對話進行中」死亡 → 強制中斷這一輪出 log（acp-process child.on 觸發）。
  conn.onAbort = (reason: string) => {
    log.error('acp:child:died-midturn', { sessionId: req.sessionId, agent: req.agentLabel, reason });
    finish(`ACP 代理連線中斷（${req.agentLabel}）：${reason}。已強制中斷這一輪，請查看診斷紀錄。`);
  };
  const cancelSub = req.signal.onCancellationRequested(() => {
    try {
      void conn.conn.cancel({ sessionId: conn.acpSessionId } as any);
    } catch {
      /* ignore */
    }
  });

  try {
    log.info('acp:prompt', { sessionId: req.sessionId, agent: req.agentLabel });
    // 組 prompt：文字 +（看圖輸入）image content block。代理不吃圖時頂多忽略該 block，不影響文字。
    const promptBlocks: any[] = [];
    if (req.userMessage) promptBlocks.push({ type: 'text', text: req.userMessage });
    for (const img of req.images || []) {
      promptBlocks.push({ type: 'image', data: img.data, mimeType: img.mimeType });
    }
    if (promptBlocks.length === 0) promptBlocks.push({ type: 'text', text: '' });
    const res = await conn.conn.prompt({
      sessionId: conn.acpSessionId,
      prompt: promptBlocks,
    } as any);
    if (state.text) {
      await req.store.append(req.sessionId, {
        role: 'assistant',
        content: state.text,
        ts: Date.now(),
      });
    }
    log.info('acp:prompt:done', {
      sessionId: req.sessionId,
      stop: (res as any)?.stopReason,
      chars: state.text.length,
    });
    finish();
  } catch (e: any) {
    const cancelled = req.signal.isCancellationRequested;
    const msg = cancelled ? 'cancelled' : e?.message ?? String(e);
    log.error('acp:prompt:fail', { sessionId: req.sessionId, msg });
    if (state.text) {
      await req.store.append(req.sessionId, {
        role: 'assistant',
        content: state.text,
        ts: Date.now(),
      });
    }
    finish(String(msg));
  } finally {
    conn.sink = null;
    conn.permission = null;
    conn.onAbort = null;
    cancelSub.dispose();
  }
}

export interface CoreMsg {
  seq: number;
  from: string;
  text?: string;
  type?: string;
  role?: string;
}

export interface CoreMember {
  id: string;
  name?: string;
  backend?: string;
}

export interface DriveBaseAgentDeps {
  ctx: vscode.ExtensionContext;
  /** 原始房名（= 面板 this.channel）。⚠ 必須與 linkedSessionId 用的 channel 一致，否則記憶分裂。 */
  room: string;
  member: CoreMember;
  src: CoreMsg;
  /** 近期群組訊息（呼叫端備好；core 自行 filter/slice）。 */
  buffer: CoreMsg[];
  /** 共用 namespace-aware SessionStore（登入/登出已被 setNamespace 切到正確 profile）。 */
  sessionStore: SessionStore;
  /** 取該成員連結的私聊 Session id（私聊長期記憶）；無連結回 undefined。 */
  linkedSessionId: (memberId: string) => string | undefined;
  /** 把回覆代發回房（面板＝postAs；背景＝bgPostAs：sid 代發 + E2E 加密 + replyTo 去重）。 */
  authoritySend: (memberId: string, text: string, replyTo: number) => void;
  /** 每分鐘最大呼叫數（限頻）。 */
  maxCallsPerMin: number;
  /** 給 AI 的群組上下文則數（aiKing.group.aiContextMessages；0=只給 Session 記憶）。 */
  contextMessages: number;
  /** 工具能力：背景一律 false（純對話、無 run_bash/讀寫檔）。 */
  toolsEnabled: boolean;
  /** 工具閘（toolsEnabled 時面板提供；背景 undefined）。 */
  toolGate?: (tool: string, args: Record<string, unknown>) => Promise<boolean>;
  maxToolIters?: number;
  /** 強制在 system prompt 注入「我無工具能力、禁聲稱已執行」段。背景＝true（防幻覺）；面板＝false（維持原行為，只在 toolsDegraded 時告知）。 */
  announceNoTools: boolean;
  glog: (msg: string) => void;
  /** 使用者可見的警告（面板＝彈窗；背景＝寫 output channel，不彈窗）。 */
  warn: (msg: string) => void;
  /** 一次互動成功完成後的回呼（面板＝autoRateInteraction 評分；背景第一版傳 undefined）。 */
  onAnswered?: (fromId: string, memberId: string) => void;
}

function driveKey(room: string, memberId: string): string {
  return `${room} ${memberId}`;
}

function inflightHas(key: string): boolean {
  const started = inflightMap.get(key);
  if (started === undefined) return false;
  if (Date.now() - started >= INFLIGHT_TIMEOUT_MS) { inflightMap.delete(key); return false; }
  return true;
}

function rateTake(key: string, maxPerMin: number): boolean {
  const now = Date.now();
  const prev = (rateMap.get(key) || []).filter((t) => now - t < 60_000);
  if (prev.length >= maxPerMin) { rateMap.set(key, prev); return false; }
  prev.push(now);
  rateMap.set(key, prev);
  return true;
}

export async function resolveBaseAgentBackend(
  ctx: vscode.ExtensionContext,
  member: { backend?: string },
): Promise<{ provider: Provider | undefined; model: string; apiKey: string }> {
  const backend = (member.backend || '').trim();
  let providerId = '';
  let model = '';
  if (backend) {
    const sep = backend.search(/[:/]/);
    if (sep > 0) {
      providerId = backend.slice(0, sep).trim();
      model = backend.slice(sep + 1).trim();
    } else {
      model = backend;
    }
  }
  const providers = loadProviders();
  let provider = providerId ? providers.find((p) => p.id === providerId) : undefined;
  if (!provider) {
    const activeId = getActiveProviderId(ctx);
    provider = providers.find((p) => p.id === activeId) || providers[0];
  }
  if (!model) model = getActiveModel(ctx) || provider?.models?.[0] || '';
  let apiKey = '';
  if (provider) {
    try {
      apiKey = (await getProviderKey(ctx, provider.id)) || '';
    } catch {
      /* no stored key — provider may be keyless (e.g. local Ollama) */
    }
  }
  return { provider, model, apiKey };
}

export async function driveBaseAgentCore(deps: DriveBaseAgentDeps): Promise<void> {
  const { ctx, room, member, src, glog } = deps;
  // [觀測性] 兩個「靜默 return」是不回應的嫌疑：inflight 卡住（上次沒清乾淨）或限頻擋下。
  const key = driveKey(room, member.id);
  if (inflightHas(key)) { glog(`callBaseAgent:skip inflight id="${member.id}"`); return; }
  if (!rateTake(key, deps.maxCallsPerMin)) { glog(`callBaseAgent:skip ratelimit id="${member.id}"`); return; }
  inflightAdd(key);
  try {
    const { provider, model, apiKey } = await resolveBaseAgentBackend(ctx, member);
    glog(`callBaseAgent:resolve id="${member.id}" backend="${member.backend || ''}" provider="${provider?.id || '-'}" model="${model}" hasKey=${!!apiKey}`);
    if (!provider) {
      deps.warn(`基礎 Agent「${member.name || member.id}」：找不到可用的 provider，請到設定加一個 LLM 後端。`);
      return;
    }
    // [統一記憶] 記憶＝連結的私聊 Session（同一個 AI、同一本記憶）＋近期群組上下文。
    const histCount = deps.contextMessages;
    const groupCtx = histCount > 0
      ? deps.buffer
          .filter((m) => m.seq !== src.seq && (m.type || 'msg') === 'msg' && m.role !== 'system' && !!(m.text && m.text.trim()))
          .slice(-histCount)
          .map((m) => m.from === member.id
            ? { role: 'assistant' as const, content: m.text || '' }
            : { role: 'user' as const, content: `${m.from}：${m.text || ''}` })
      : [];
    const linkedSid = deps.linkedSessionId(member.id);
    let sessionMem: Array<{ role: 'user' | 'assistant'; content: string }> = [];
    if (linkedSid) {
      try {
        const sess = await deps.sessionStore.load(linkedSid);
        if (sess) {
          sessionMem = sess.messages
            .filter((m) => (m.role === 'user' || m.role === 'assistant') && !!(m.content && m.content.trim()))
            .map((m) => ({ role: m.role as 'user' | 'assistant', content: m.content }));
        }
      } catch { /* 記憶讀失敗 → 降級成只用群組上下文 */ }
    }
    const history = [...sessionMem, ...groupCtx];
    glog(`callBaseAgent:history id="${member.id}" mem=${sessionMem.length} group=${groupCtx.length} linked=${linkedSid ? 'y' : 'n'}`);
    // [1.9.21] 注入 AI King 自己的技能（~/.aiking/skills）。空資料夾 → '' → 提示詞不變、零副作用。
    const aikingSkills = loadAikingSkillsForPrompt(aikingAgentSkillFolder());
    // toolsEnabled 由呼叫端決定：面板讀 group.baseAgentTools.enabled；背景一律 false。
    // openai-compat（deepseek 等）路 base-agent 退化成無工具（function-calling loop 待金鑰 PoC）。
    const toolsDegraded = deps.toolsEnabled && provider.kind !== 'anthropic-direct';
    if (deps.toolsEnabled) {
      glog(`callBaseAgent:tools-enabled id="${member.id}" providerKind="${provider.kind}"`);
      if (toolsDegraded) {
        glog(`callBaseAgent:tools-degraded id="${member.id}" providerKind="${provider.kind}" reason="走 chat/completions 線、function-calling loop 未實作（待金鑰 PoC）→ 無工具單輪"`);
      }
    }
    // [紅藍 M4 / 步驟11] 無工具能力時明告模型，禁語言層幻覺「已執行」（命中「禁假裝工具結果」鐵律）。
    // 背景一律 announceNoTools=true；面板維持原行為（只在 toolsDegraded 時告知）。
    const announceNoTools = toolsDegraded || deps.announceNoTools;
    if (deps.announceNoTools) glog(`callBaseAgent:tools-forced-off id="${member.id}"`);
    const answer = await runBaseAgentOnce({
      provider,
      apiKey,
      model,
      toolsEnabled: deps.toolsEnabled,
      maxToolIters: deps.maxToolIters ?? 8,
      toolGate: deps.toolGate,
      systemPrompt:
        `你是 AI 群組「${room}」的成員「${member.name || member.id}」。這是多人協作群組，發言規則最重要：\n` +
        '**群組只發精煉結論、最多 1～3 句**。先在心裡想清楚，但**思考過程不要寫進群組**——只丟「結論／進度／要問的一件事」。' +
        '⛔ 不要展開推理過程、不要分點長篇、不要客套鋪陳、不要把草稿或思路貼出來。深入的長討論留到跟使用者的私下對話。\n' +
        '你的長期記憶來自你跟使用者的私聊與過往群組互動；歷史以「某人：內容」標明發話者，你自己的發言是 assistant 回合。' +
        '用繁體中文、直接、不自稱 AI 助理、不加多餘客套。' +
        (aikingSkills ? `\n\n# 你具備的技能（來自設定的 Skill 資料夾 ~/.aiking/skills，需要時運用）\n${aikingSkills}` : '') +
        (announceNoTools ? '\n\n⚠ 重要：你在此群組【沒有任何工具／執行能力】（無法 run_bash 跑指令、無法讀寫檔案）。被要求執行操作時，要明說「我在此群組無法實際執行，請改派有工具的成員、或請使用者在本機自己跑」，⛔ 絕不可聲稱「已執行／已完成／已跑好」——那是假裝工具結果。' : ''),
      userMessage: `${src.from}：${src.text}`,
      history,
      maxTokens: 1024,
    });
    glog(`callBaseAgent:answer id="${member.id}" len=${answer ? answer.length : 0}`);
    if (answer) {
      deps.authoritySend(member.id, answer, src.seq);
      // [評分] 一次互動成功完成 → 回呼（面板＝自動評分；背景第一版不評）。
      if (deps.onAnswered) deps.onAnswered(src.from, member.id);
      // [統一記憶] 寫回連結 Session（這次群組互動，私聊也記得）。best-effort、原子寫（SessionStore.writeAtomic）。
      if (linkedSid) {
        try {
          const now = Date.now();
          await deps.sessionStore.append(linkedSid, { role: 'user', content: `${src.from}：${src.text}`, ts: now });
          await deps.sessionStore.append(linkedSid, { role: 'assistant', content: answer, ts: now });
        } catch { /* 寫回失敗不影響已貼出的回覆 */ }
      }
    } else {
      deps.warn(`基礎 Agent「${member.id}」沒有產生回覆。`);
    }
  } catch (e: unknown) {
    glog(`callBaseAgent:error id="${member.id}" err=${e instanceof Error ? e.message : String(e)}`);
    deps.warn(`基礎 Agent 呼叫失敗 — ${e instanceof Error ? e.message : String(e)}`);
  } finally {
    inflightDelete(key);
  }
}

export interface BaseAgentTurn {
  role: BaseAgentRole;
  content: string;
}

export interface BaseAgentRequest {
  provider: Provider;
  apiKey: string;
  model: string;
  /** 最少提示詞：caller 給最小 system（或留空）。 */
  systemPrompt?: string;
  /** 本輪要回應的訊息（通常是 @ 它的那句）。 */
  userMessage: string;
  /** 近期上下文（會依模型 context window 自動裁到塞得下）。 */
  history?: BaseAgentTurn[];
  /** 回覆上限 token；預設 1024（probe）/ caller 回覆時可給大一點。 */
  maxTokens?: number;
  /** 連線逾時毫秒，預設 60s。 */
  timeoutMs?: number;
  /**
   * [1.13.x 群組工具] 啟用工具能力（read_file/list_files/write_file/run_bash）。
   * ⚠ 目前只有 anthropic-direct 路真有 tool loop；openai-compat（deepseek 等）的
   * OpenAI function-calling 格式不同、且 DeepSeek v4-flash 非串流端點 tools 支援待金鑰
   * PoC 驗證 → 暫時退化成「無工具單輪」（不報錯、也不假裝有工具）。預設關（caller 控）。
   */
  toolsEnabled?: boolean;
  /**
   * [1.13.x 群組工具] 每個工具呼叫前的權限閘門：回 false ⇒ 拒絕該次（回 is_error 的
   * tool_result、不中斷整個 loop）。caller（bridge-view）用它接 askPermissionAllowed，
   * 對 run_bash / write_file 強制 QuickPick（forcePrompt，不吃 autoApproveAll 短路）。
   * 未提供 ⇒ 視為全允許（僅在 caller 確認情境安全時才該如此）。
   */
  toolGate?: (tool: string, args: Record<string, unknown>) => Promise<boolean>;
  /**
   * [1.13.x 群組工具] tool_use agent loop 最大迭代輪數（每輪可跑多個工具）。預設 8。
   * caller 從 switch aiKing.group.baseAgentTools.maxToolIters 帶入（L0 鐵律#6 可調）。
   */
  maxToolIters?: number;
}

export function modelContextWindow(model: string): number {
  const m = (model || '').toLowerCase();
  // Anthropic Claude（3.5 起、4.x）皆 200K
  if (/claude|opus-4|sonnet-4|haiku-4|claude-3[.-]5/.test(m)) return 200_000;
  // OpenAI
  if (/gpt-4\.1|gpt-4o|o1|o3|o4/.test(m)) return 128_000;
  if (/gpt-4-turbo|gpt-4-1106|gpt-4-0125/.test(m)) return 128_000;
  if (/gpt-4(?![o.])/.test(m)) return 8_192;
  if (/gpt-3\.5/.test(m)) return 16_385;
  // Google Gemini
  if (/gemini-2|gemini-1\.5/.test(m)) return 1_000_000;
  if (/gemini/.test(m)) return 32_768;
  // 常見開源/本地
  if (/llama-?3|llama3/.test(m)) return 8_192;
  if (/mixtral/.test(m)) return 32_768;
  if (/mistral/.test(m)) return 32_768;
  if (/qwen2|qwen-2/.test(m)) return 32_768;
  if (/deepseek/.test(m)) return 64_000;
  // 冷門 / 自製 / 認不得 → user 指定的 200K fallback
  return FALLBACK_CONTEXT_WINDOW;
}

function estimateTokens(text: string): number {
  if (!text) return 0;
  // 含 CJK → 每字約 1 token，較保守用 /1.5；純拉丁 ~ /4。取中間 /2.5。
  const cjk = (text.match(/[　-鿿＀-￯]/g) || []).length;
  const rest = text.length - cjk;
  return Math.ceil(cjk + rest / 4);
}

function fitHistory(
  history: BaseAgentTurn[],
  model: string,
  systemPrompt: string,
  userMessage: string,
  maxTokens: number,
): BaseAgentTurn[] {
  if (!history || history.length === 0) return [];
  const window = modelContextWindow(model);
  const reserve = estimateTokens(systemPrompt) + estimateTokens(userMessage) + maxTokens + 256;
  let budget = Math.max(0, Math.floor(window * 0.6) - reserve);
  const kept: BaseAgentTurn[] = [];
  for (let i = history.length - 1; i >= 0; i--) {
    const cost = estimateTokens(history[i].content) + 8;
    if (cost > budget) break;
    budget -= cost;
    kept.unshift(history[i]);
  }
  return kept;
}

export async function runBaseAgentOnce(req: BaseAgentRequest): Promise<string> {
  const maxTokens = req.maxTokens ?? 1024;
  const timeoutMs = req.timeoutMs ?? 60_000;
  const system = req.systemPrompt ?? '';
  const history = fitHistory(req.history || [], req.model, system, req.userMessage, maxTokens);

  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    // [1.13.x 安全 invariant] 「有工具必有閘門」升級成程式強制：toolsEnabled=true 卻沒帶
    // toolGate（未來新 caller 易漏）= 危險組合 → 退化成無工具（fail-closed），絕不無閘門放行。
    const useTools = !!req.toolsEnabled && !!req.toolGate;
    if (req.provider.kind === 'anthropic-direct') {
      // [1.13.x 群組工具] 開了工具且走 Anthropic → 非串流 tool_use agent loop；否則純單輪。
      return useTools
        ? await callAnthropicWithTools(req, system, history, maxTokens, ctl.signal)
        : await callAnthropic(req, system, history, maxTokens, ctl.signal);
    }
    if (
      req.provider.kind === 'openai-compat' ||
      req.provider.kind === 'ai-king-backend' ||
      req.provider.kind === 'custom'
    ) {
      // [1.13.x 群組工具] openai-compat（deepseek 等）的 function-calling loop 尚未實作
      //（格式與 Anthropic 不同、DeepSeek v4-flash 非串流 tools 支援待金鑰 PoC）→ 即使
      // toolsEnabled 也退化成無工具單輪，不報錯、不假裝有工具（caller 已記 log）。
      return await callOpenAICompat(req, system, history, maxTokens, ctl.signal);
    }
    throw new Error(`基礎 Agent 不支援 provider kind=${req.provider.kind}（請換可用後端）`);
  } finally {
    clearTimeout(timer);
  }
}

async function callAnthropic(
  req: BaseAgentRequest,
  system: string,
  history: BaseAgentTurn[],
  maxTokens: number,
  signal: AbortSignal,
): Promise<string> {
  const base = req.provider.endpoint.replace(/\/+$/, '');
  const url = `${base}/v1/messages`;
  const messages = [...history.map((h) => ({ role: h.role, content: h.content })), {
    role: 'user',
    content: req.userMessage,
  }];
  const body: Record<string, unknown> = { model: req.model, max_tokens: maxTokens, messages };
  if (system) body.system = system;
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'anthropic-version': '2023-06-01',
  };
  if (req.apiKey && req.apiKey !== 'none') headers['x-api-key'] = req.apiKey;

  const resp = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body), signal });
  if (!resp.ok) {
    const t = await resp.text().catch(() => '');
    throw new Error(`Anthropic HTTP ${resp.status}: ${t.slice(0, 200)}`);
  }
  const data = (await resp.json()) as { content?: Array<{ type?: string; text?: string }> };
  const out = (data.content || [])
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text as string)
    .join('');
  return out.trim();
}

function extractText(content: Array<{ type?: string; text?: string }>): string {
  return content
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text as string)
    .join('');
}

async function callAnthropicWithTools(
  req: BaseAgentRequest,
  system: string,
  history: BaseAgentTurn[],
  maxTokens: number,
  signal: AbortSignal,
): Promise<string> {
  const base = req.provider.endpoint.replace(/\/+$/, '');
  const url = `${base}/v1/messages`;
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'anthropic-version': '2023-06-01',
  };
  if (req.apiKey && req.apiKey !== 'none') headers['x-api-key'] = req.apiKey;

  // content 用陣列以容納 tool_use / tool_result blocks（單輪 callAnthropic 用純字串即可）。
  const messages: Array<{ role: string; content: unknown }> = [
    ...history.map((h) => ({ role: h.role, content: h.content })),
    { role: 'user', content: req.userMessage },
  ];

  const maxIters = Math.max(1, req.maxToolIters ?? DEFAULT_MAX_TOOL_ITERS);
  let progressText = ''; // 工具回合的中途文字（非最終答案；只在達上限收尾時當墊底）
  let hitLimit = false;

  type MsgResp = {
    content?: Array<{ type?: string; text?: string; id?: string; name?: string; input?: unknown }>;
    stop_reason?: string;
  };
  const postOnce = async (withTools: boolean): Promise<MsgResp> => {
    const body: Record<string, unknown> = { model: req.model, max_tokens: maxTokens, messages };
    if (withTools) body.tools = CLEAN_TOOLS;
    if (system) body.system = system;
    const resp = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body), signal });
    if (!resp.ok) {
      const t = await resp.text().catch(() => '');
      throw new Error(`Anthropic HTTP ${resp.status}: ${t.slice(0, 200)}`);
    }
    return (await resp.json()) as MsgResp;
  };

  for (let iter = 0; iter < maxIters; iter++) {
    if (signal.aborted) break;
    const data = await postOnce(true);
    const content = data.content || [];
    const text = extractText(content);

    const toolUses = content.filter(
      (b) => b && b.type === 'tool_use' && typeof b.name === 'string' && typeof b.id === 'string',
    );
    // 收尾輪（模型不再叫工具）→ 這輪的 text 就是最終答案，定案返回。
    if (data.stop_reason !== 'tool_use' || toolUses.length === 0) {
      return (text || progressText || '').trim();
    }
    if (text) progressText = text; // 中途文字只當 progress，不當最終答案
    if (iter === maxIters - 1) hitLimit = true; // 最後一輪卻還要跑工具 → 達上限

    // assistant 回合（含 text + tool_use）原樣放回。
    messages.push({ role: 'assistant', content });

    const toolResults: unknown[] = [];
    for (const tu of toolUses) {
      const name = tu.name as string;
      const input: Record<string, unknown> =
        tu.input && typeof tu.input === 'object' ? (tu.input as Record<string, unknown>) : {};
      // [安全 invariant] 走到這裡 req.toolGate 一定存在（runBaseAgentOnce 的 useTools 保證）；
      // 萬一缺失 → fail-closed（視為拒絕），絕不無閘門放行。
      let allowed = false;
      if (req.toolGate) {
        try { allowed = await req.toolGate(name, input); } catch { allowed = false; }
      }
      if (!allowed) {
        toolResults.push({
          type: 'tool_result',
          tool_use_id: tu.id,
          content: '使用者拒絕了這次工具呼叫（permission denied）。改用別的方式或先說明原因。',
          is_error: true,
        });
        continue;
      }
      const r = await executeTool(name, input);
      toolResults.push({
        type: 'tool_result',
        tool_use_id: tu.id,
        content: r.content,
        ...(r.isError ? { is_error: true } : {}),
      });
    }
    messages.push({ role: 'user', content: toolResults });
  }

  // [紅藍 H3] 達迭代上限退出（最後一批 tool_results 已 push 進 messages 但還沒給模型作答）：
  // 補一次「無 tools」收尾請求，逼模型對最後批工具結果產出最終回覆，別靜默丟棄/回開場白。
  if (hitLimit && !signal.aborted) {
    try {
      const data = await postOnce(false);
      const text = extractText(data.content || []);
      if (text) return text.trim();
    } catch { /* 收尾請求失敗 → 落到下方明確告知 */ }
    return (progressText
      ? `${progressText}\n\n（已達工具呼叫上限 ${maxIters} 輪，可能未完成；請縮小任務或調高設定 aiKing.group.baseAgentTools.maxToolIters。）`
      : `（已達工具呼叫上限 ${maxIters} 輪、未產生最終回覆；請縮小任務或調高設定 aiKing.group.baseAgentTools.maxToolIters。）`
    ).trim();
  }
  return (progressText || '').trim();
}

type MsgResp = {
  content?: Array<{ type?: string; text?: string; id?: string; name?: string; input?: unknown }>;
  stop_reason?: string;
};

async function callOpenAICompat(
  req: BaseAgentRequest,
  system: string,
  history: BaseAgentTurn[],
  maxTokens: number,
  signal: AbortSignal,
): Promise<string> {
  const base = req.provider.endpoint.replace(/\/+$/, '');
  const url = `${base}/chat/completions`;
  const messages: Array<{ role: string; content: string }> = [];
  if (system) messages.push({ role: 'system', content: system });
  for (const h of history) messages.push({ role: h.role, content: h.content });
  messages.push({ role: 'user', content: req.userMessage });

  const body: Record<string, unknown> = {
    model: req.model,
    messages,
    max_tokens: maxTokens,
    stream: false,
  };
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (req.apiKey && req.apiKey !== 'none') headers.Authorization = `Bearer ${req.apiKey}`;

  const resp = await fetch(url, { method: 'POST', headers, body: JSON.stringify(body), signal });
  if (!resp.ok) {
    const t = await resp.text().catch(() => '');
    throw new Error(`${req.provider.name} HTTP ${resp.status}: ${t.slice(0, 200)}`);
  }
  const data = (await resp.json()) as {
    choices?: Array<{ message?: { content?: string } }>;
  };
  const out = data.choices?.[0]?.message?.content || '';
  return out.trim();
}

export interface CleanAttachment {
  kind: 'image' | 'document';
  /** data URL: `data:image/png;base64,...` */
  dataUrl: string;
  mimeType: string;
  name: string;
}

export interface CleanRunRequest {
  ctx: vscode.ExtensionContext;
  store: SessionStore;
  sessionId: string;
  mode: ChatMode;
  provider: Provider;
  apiKey: string;
  model: string;
  systemPrompt: string;
  userMessage: string;
  history: ChatMessage[];
  /** v0.16.0: optional image/document attachments on the current user turn. */
  attachments?: CleanAttachment[];
  thinking?: { enabled: boolean; budgetTokens: number };
  effort?: 'low' | 'medium' | 'high';
  /** 當前 Agent 類型（決定 per-stack 工具開關，見 tool-config.ts）。預設 'clean'。 */
  stack?: string;
  signal: vscode.CancellationToken;
  /** [F 授權抽屜 1.24.32] 對話面板注入的 webview 抽屜提示器；不傳＝gate 走原生 QuickPick。 */
  prompter?: (r: PermissionRequest) => Promise<PermissionDecision>;
  emit: (event: RunnerEvent) => void;
}

function splitDataUrl(dataUrl: string): { mime: string; data: string } | null {
  const m = /^data:([^;]+);base64,(.+)$/i.exec(dataUrl);
  if (!m) return null;
  return { mime: m[1], data: m[2] };
}

const OpenAIDeltaSchema = z.object({
  choices: z
    .array(
      z.object({
        delta: z
          .object({
            content: z.string().nullable().optional(),
            // [1.8.6] DeepSeek reasoner / deepseek-v4-flash 思考模式把思考鏈放在
            // reasoning_content（不是 content）。舊 schema 沒收這欄 → 被 zod 預設
            // 剝除 → 思考型模型整段輸出被忽略 = 使用者看到「沒回應」。收進來。
            reasoning_content: z.string().nullable().optional(),
            // [tool loop 2026-06-22] OpenAI function-calling 串流增量。tool_calls 分多幀送：
            // 同一 index 的 id/function.name 可能晚到（每幀 set-if-present），arguments 永遠
            // append。沿用既有教訓（DeepSeek 每幀送 usage:null）全欄 .nullable().optional()。
            tool_calls: z
              .array(
                z.object({
                  index: z.number(),
                  id: z.string().nullable().optional(),
                  type: z.string().nullable().optional(),
                  function: z
                    .object({
                      name: z.string().nullable().optional(),
                      arguments: z.string().nullable().optional(),
                    })
                    .nullable()
                    .optional(),
                }),
              )
              .nullable()
              .optional(),
          })
          .optional(),
        finish_reason: z.string().nullable().optional(),
      }),
    )
    .optional(),
  // [1.9.2] ⛔致命 bug 修：DeepSeek 串流時**每一幀都送 `usage: null`**（不是省略、是
  // 明確 null）。舊 schema `usage` 只 `.optional()`（允許 undefined 不允許 null）→
  // 每一幀 zod 驗證失敗 → 整幀被丟（含 content/reasoning_content）→ chars:0 = 完全
  // 沒回應。加 `.nullable()` 即修。這就是 Base Agent 對 DeepSeek 沉默的真兇（log 實證
  // 數百行 clean:openai:invalid-frame path:["usage"] expected object received null）。
  usage: z
    .object({
      prompt_tokens: z.number().optional(),
      completion_tokens: z.number().optional(),
    })
    .nullable()
    .optional(),
});

const AnthropicEventSchema = z.object({
  type: z.string(),
  index: z.number().optional(),
  content_block: z
    .object({
      type: z.string().optional(),
      id: z.string().optional(),
      name: z.string().optional(),
      text: z.string().optional(),
    })
    .optional(),
  delta: z
    .object({
      type: z.string().optional(),
      text: z.string().optional(),
      partial_json: z.string().optional(),
      stop_reason: z.string().optional(),
    })
    .optional(),
  message: z
    .object({
      usage: z
        .object({
          input_tokens: z.number().optional(),
          output_tokens: z.number().optional(),
        })
        .optional(),
    })
    .optional(),
  usage: z
    .object({
      input_tokens: z.number().optional(),
      output_tokens: z.number().optional(),
    })
    .optional(),
});

function genRequestId(): string {
  return `clean-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

type WireMsg = {
  role: string;
  content: unknown;
  // [tool loop 2026-06-22] OpenAI function-calling 多輪需要的可選欄位：
  //   tool_call_id  — role:'tool' 訊息回填某次工具呼叫的結果用
  //   tool_calls    — assistant 回合帶出的工具呼叫清單
  //   reasoning_content — ⚠ 命門：DeepSeek 發 tool_calls 的回合會帶 reasoning_content，
  //                       後續輪必須原樣回送，否則 HTTP 400 "Missing reasoning_content"。
  tool_call_id?: string;
  tool_calls?: unknown;
  reasoning_content?: string;
};

function toOpenAITools(tools: ToolDef[]): unknown[] {
  return tools.map((t) => ({
    type: 'function',
    function: { name: t.name, description: t.description, parameters: t.input_schema },
  }));
}

interface CollectedOpenAIToolCall {
  id: string;
  name: string;
  arguments: string;
}

interface OpenAICompatResult {
  toolCalls: CollectedOpenAIToolCall[];
  finishReason: string;
}

function buildMessages(req: CleanRunRequest): WireMsg[] {
  const msgs: WireMsg[] = [];
  for (const m of req.history) {
    if (m.role === 'tool') continue; // clean stack has no tool loop
    msgs.push({ role: m.role, content: m.content });
  }
  // v0.16.0: if the current user turn has attachments, promote `content` to a
  // multimodal array. Shape is provider-specific and written by the caller.
  msgs.push({ role: 'user', content: req.userMessage });
  return msgs;
}

function buildAnthropicUserContent(
  text: string,
  attachments: CleanAttachment[] | undefined,
): unknown {
  const atts = attachments || [];
  if (atts.length === 0) return text;
  const blocks: unknown[] = [];
  for (const a of atts) {
    const parts = splitDataUrl(a.dataUrl);
    if (!parts) continue;
    if (a.kind === 'image') {
      blocks.push({
        type: 'image',
        source: { type: 'base64', media_type: parts.mime, data: parts.data },
      });
    } else {
      // Anthropic document block (PDF) — requires the documents beta header;
      // we ship it best-effort, the caller can switch to clean+vision later.
      blocks.push({
        type: 'document',
        source: { type: 'base64', media_type: parts.mime, data: parts.data },
      });
    }
  }
  if (text) blocks.push({ type: 'text', text });
  return blocks;
}

function buildOpenAIUserContent(
  text: string,
  attachments: CleanAttachment[] | undefined,
): unknown {
  const atts = attachments || [];
  if (atts.length === 0) return text;
  const blocks: unknown[] = [];
  if (text) blocks.push({ type: 'text', text });
  for (const a of atts) {
    if (a.kind !== 'image') continue; // OpenAI chat.completions: images only
    blocks.push({ type: 'image_url', image_url: { url: a.dataUrl } });
  }
  return blocks;
}

async function persistAssistant(
  store: SessionStore,
  sessionId: string,
  text: string,
  reasoning?: string,
  thinkingMs?: number,
): Promise<void> {
  if (!text && !(reasoning && reasoning.trim())) return;
  // [thinking 落盤 2026-06-22] reasoning_content（DeepSeek 等思考型）原本只 emit 給 webview
  // 即時顯示、沒進落盤 content → done 後 renderMessages 重繪靠 extractInlineThinking 解析 <think>
  // 找不到 → thinking 整塊消失（跟「展開思考過程」開關無關，那只控展開/收起）。改：落盤時把
  // reasoning 包成 <think> 前綴併入 content。webview 重繪時還原顯示；stripThinkingForWire 在組
  // wire history 時剝離（不回送 LLM、不污染下一輪、省 token）。THINKING_BLOCK_RE 為單一真相源。
  const body = reasoning && reasoning.trim()
    ? `<think>${reasoning}</think>\n${text}`
    : text;
  // [D thinking 秒數 1.24.31] thinkingMs 與 content 解耦另存欄位（renderStaticMessage 顯真實秒數、
  //   不再硬編碼 0）；只在 >0 寫（舊訊息/無思考＝undefined→顯 0.0 相容）。
  await store.append(sessionId, {
    role: 'assistant',
    content: body,
    ts: Date.now(),
    ...(thinkingMs && thinkingMs > 0 ? { thinkingMs } : {}),
  });
}

function parseSSEBlock(block: string): { event?: string; data: string } | null {
  const lines = block.split('\n');
  let event: string | undefined;
  const dataLines: string[] = [];
  for (const line of lines) {
    const trimmed = line.replace(/\r$/, '');
    if (!trimmed || trimmed.startsWith(':')) continue;
    if (trimmed.startsWith('event:')) event = trimmed.slice(6).trim();
    else if (trimmed.startsWith('data:')) dataLines.push(trimmed.slice(5).trim());
  }
  if (dataLines.length === 0) return null;
  return { event, data: dataLines.join('\n') };
}

async function streamOpenAICompat(
  req: CleanRunRequest,
  requestId: string,
  state: { text: string; reasoning: string; doneMode: 'primary' | 'fallback'; thinkingMsAccum: number; roundReasonStart: number },
  abort: AbortController,
  idleReset: () => void,
  messages: WireMsg[],
  tools?: unknown[],
): Promise<OpenAICompatResult> {
  const base = req.provider.endpoint.replace(/\/+$/, '');
  const url = `${base}/chat/completions`;
  // [tool loop 2026-06-22] messages + attachments 改由外層（runViaCleanProvider）一次組好
  // 傳入，這裡不再內部 buildMessages/套 attachments，loop 各輪共用同一陣列累積上下文。
  const body: Record<string, unknown> = {
    model: req.model,
    messages: [{ role: 'system', content: req.systemPrompt }, ...messages],
    stream: true,
    // [1.8.0 §14.4] ask the OpenAI-compatible stream to emit a final usage
    // chunk so we can show a real per-reply token total. OpenAI / DeepSeek /
    // xAI / Mistral honour it; Gemini's compat layer silently ignores unknown
    // params; Ollama returns usage from its own eval_count — same path, so
    // local models get the total too.
    stream_options: { include_usage: true },
  };
  if (req.effort) body.reasoning_effort = req.effort;
  // [tool loop 2026-06-22] 有工具就掛上，不設 tool_choice（讓模型自己決定是否呼叫工具，
  // 這樣「無工具呼叫＝答完」的退化路徑自然成立、不強迫模型一定要叫工具）。
  if (tools && tools.length > 0) body.tools = tools;

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    Accept: 'text/event-stream',
    'X-Request-Id': requestId,
  };
  if (req.apiKey && req.apiKey !== 'none') {
    headers.Authorization = `Bearer ${req.apiKey}`;
  }

  const resp = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
    signal: abort.signal,
  });
  if (!resp.ok) {
    const errText = await resp.text().catch(() => '');
    let host = req.provider.endpoint;
    try { host = new URL(url).host; } catch { /* keep endpoint */ }
    log.error('clean:openai:non-2xx', {
      requestId,
      status: resp.status,
      statusText: resp.statusText,
      host,
      model: req.model,
      preview: errText.slice(0, 200),
    });
    // [1.8.4] 白話錯誤：含 HTTP 狀態 + 主機 + 模型 + 上游原文，讓使用者一眼知道是
    // 什麼問題（金鑰錯/模型不存在/伺服器忙）。完整內容也在「AI King」診斷頻道。
    req.emit({
      type: 'error',
      message: `${req.provider.name} 回 HTTP ${resp.status} ${resp.statusText}（${host} · 模型 ${req.model}）${errText ? '：' + errText.slice(0, 300) : ''}`,
    });
    return { toolCalls: [], finishReason: 'stop' };
  }
  if (!resp.body) {
    req.emit({ type: 'error', message: `${req.provider.name}: empty response body` });
    return { toolCalls: [], finishReason: 'stop' };
  }
  // [1.9.1] 記 HTTP 200 的回應型別到診斷頻道：若 content-type 不是 text/event-stream
  // （例如 application/json）= 上游沒在串流、可能整包回了非 SSE 內容，解析器收不到
  // 任何 frame = 使用者看到「回應中一直跳卻沒內容」。這行讓真因一眼可辨。
  log.info('clean:openai:200', {
    requestId,
    model: req.model,
    contentType: resp.headers.get('content-type') || '(none)',
  });
  const reader = resp.body.getReader();
  let sawFirstFrame = false;
  // [tool loop 2026-06-22] tool_calls 增量累積：key 用 d.index（**不是陣列位置**），因為
  // 同一輪可能有多個工具呼叫、各幀只帶部分欄位。name 可能晚到（每幀 set-if-present）、
  // arguments 永遠 append、不在串流中途 JSON.parse（碎片 JSON 解不了）。
  const acc = new Map<number, CollectedOpenAIToolCall>();
  let finish = '';
  try {
    for await (const frame of iterateFrames(reader, req.signal, idleReset)) {
      if (frame.data === '[DONE]') break;
      let json: unknown;
      try {
        json = JSON.parse(frame.data);
      } catch {
        continue;
      }
      // [1.8.6] 觀測性：把上游第一個 frame 的原始 delta 鍵記到診斷頻道，一眼看出
      // 是 content 還是 reasoning_content（或別的格式），不用再憑空臆測。
      if (!sawFirstFrame) {
        sawFirstFrame = true;
        const d = (json as { choices?: Array<{ delta?: Record<string, unknown> }> })?.choices?.[0]?.delta;
        log.info('clean:openai:first-frame', { requestId, model: req.model, deltaKeys: d ? Object.keys(d) : [] });
      }
      const parsed = OpenAIDeltaSchema.safeParse(json);
      if (!parsed.success) {
        log.warn('clean:openai:invalid-frame', { requestId, zod: parsed.error.issues });
        continue;
      }
      const choice = parsed.data.choices?.[0];
      // [1.8.6] DeepSeek 思考模型先吐 reasoning_content（思考）再吐 content（答案）。
      // 兩個都要處理，否則思考型模型整段被忽略 = 沒回應。
      const reasoning = choice?.delta?.reasoning_content;
      if (typeof reasoning === 'string' && reasoning.length > 0) {
        // [D thinking 秒數 1.24.33 累加] 記該輪首個 reasoning frame 時刻（每輪結算後 reset、多輪累加）。
        if (!state.roundReasonStart) state.roundReasonStart = Date.now();
        state.reasoning += reasoning;
        req.emit({ type: 'thinking', value: reasoning });
      }
      const delta = choice?.delta?.content;
      if (typeof delta === 'string' && delta.length > 0) {
        // [D thinking 秒數 1.24.33 累加] 該輪首個 content frame＝該輪思考結束 → 累加該輪思考時長、reset
        //   roundReasonStart（排除 tool 等待）。多輪 tool loop 每輪思考都累加（user：迴圈要累加）。
        if (state.roundReasonStart) { state.thinkingMsAccum += Date.now() - state.roundReasonStart; state.roundReasonStart = 0; }
        state.text += delta;
        req.emit({ type: 'text', value: delta });
      }
      const usage = parsed.data.usage;
      if (usage) {
        req.emit({
          type: 'usage',
          inputTokens: usage.prompt_tokens,
          outputTokens: usage.completion_tokens,
        });
      }
      // [tool loop 2026-06-22] 累積 tool_calls 增量。
      const toolDeltas = choice?.delta?.tool_calls;
      if (toolDeltas && toolDeltas.length > 0) {
        for (const d of toolDeltas) {
          let e = acc.get(d.index);
          if (!e) {
            e = { id: '', name: '', arguments: '' };
            acc.set(d.index, e);
          }
          if (d.id) e.id = d.id;
          if (d.function?.name) e.name = d.function.name; // name 可能晚到、set-if-present
          if (d.function?.arguments) e.arguments += d.function.arguments; // 永遠 append
        }
      }
      if (choice?.finish_reason) finish = choice.finish_reason;
    }
  } finally {
    try {
      reader.releaseLock();
    } catch {
      /* ignore */
    }
  }
  return {
    toolCalls: [...acc.values()].filter((t) => t.name),
    finishReason: finish || 'stop',
  };
}

interface CollectedToolUse {
  id: string;
  name: string;
  inputJson: string;
}

interface AnthropicStreamResult {
  toolUses: CollectedToolUse[];
}

async function streamAnthropicDirect(
  req: CleanRunRequest,
  requestId: string,
  state: { text: string; doneMode: 'primary' | 'fallback' },
  abort: AbortController,
  idleReset: () => void,
  messages: WireMsg[],
  tools?: unknown[],
): Promise<AnthropicStreamResult> {
  const base = req.provider.endpoint.replace(/\/+$/, '');
  const url = `${base}/v1/messages`;
  // [prompt cache 2026-06-16] system 通常是整串請求裡最穩定、最長的一塊（AI King 的系統提示
  // ＋skills＋人格設定），標 cache_control:ephemeral 讓 Anthropic 快取這段前綴：往後相同 system
  // 的請求命中 cache，input 只付約 1/10 價、且首字更快（user：cache 機制本來邏輯同一套、該有）。
  // <1024 token 的 system 不夠長 → API 自動略過 cache（無害）。env AIKING_PROMPT_CACHE=0 可整個關。
  // 對話歷史前綴 cache（省最多那塊）＋與壓縮永動機協同（壓縮改前綴會讓 cache 失效，要設計協同）
  // 屬「改良」，見大願景設計文件願景 1，這裡先上最穩的 system cache。
  // [快取 UI 開關 2026-06-21] 主開關＝設定 aiKing.promptCache.enabled（☰ 選單「快取」勾選，
  // 預設開）；env AIKING_PROMPT_CACHE=0 仍可「強制整個關」（優先於設定，給命令列/排程用）。
  const cacheCfgOn =
    vscode.workspace.getConfiguration('aiKing').get<boolean>('promptCache.enabled') !== false;
  const cacheOn = cacheCfgOn && process.env.AIKING_PROMPT_CACHE !== '0';
  const body: Record<string, unknown> = {
    model: req.model,
    max_tokens: 4096,
    stream: true,
    system: (cacheOn && req.systemPrompt)
      ? [{ type: 'text', text: req.systemPrompt, cache_control: { type: 'ephemeral' } }]
      : req.systemPrompt,
    messages,
  };
  if (tools && tools.length > 0) body.tools = tools;
  if (req.thinking && req.thinking.enabled) {
    // 0.21.0: Opus 4.7 dropped the `budget_tokens` knob — extended thinking
    // is now an opaque adaptive budget picked by the model. Sending the old
    // `{type:'enabled', budget_tokens:N}` shape against 4.7 returns HTTP 400.
    // `display:'summarized'` keeps thinking content visible to callers that
    // expect it (4.7 default is omit).
    const isOpus47 = /^anthropic\/claude-opus-4-7|^claude-opus-4-7/i.test(req.model);
    body.thinking = isOpus47
      ? { type: 'adaptive', display: 'summarized' }
      : { type: 'enabled', budget_tokens: req.thinking.budgetTokens };
  }

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    Accept: 'text/event-stream',
    'anthropic-version': '2023-06-01',
    'X-Request-Id': requestId,
  };
  const hasAttachments = !!req.attachments && req.attachments.length > 0;
  if (hasAttachments && (req.attachments || []).some((a) => a.kind === 'document')) {
    headers['anthropic-beta'] = 'pdfs-2024-09-25';
  }
  if (req.apiKey && req.apiKey !== 'none') {
    headers['x-api-key'] = req.apiKey;
  }

  const resp = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
    signal: abort.signal,
  });
  if (!resp.ok) {
    const errText = await resp.text().catch(() => '');
    log.error('clean:anthropic:non-2xx', { requestId, status: resp.status, preview: errText.slice(0, 200) });
    req.emit({ type: 'error', message: `Anthropic HTTP ${resp.status}: ${errText.slice(0, 300)}` });
    return { toolUses: [] };
  }
  if (!resp.body) {
    req.emit({ type: 'error', message: 'Anthropic: empty response body' });
    return { toolUses: [] };
  }

  // Track active content blocks by index for tool_use accumulation.
  const activeBlocks = new Map<number, { type: string; id: string; name: string; json: string }>();
  const toolUses: CollectedToolUse[] = [];

  const reader = resp.body.getReader();
  try {
    for await (const frame of iterateFrames(reader, req.signal, idleReset)) {
      let json: unknown;
      try { json = JSON.parse(frame.data); } catch { continue; }
      const parsed = AnthropicEventSchema.safeParse(json);
      if (!parsed.success) continue;
      const ev = parsed.data;

      if (ev.type === 'content_block_start') {
        const cb = ev.content_block;
        const idx = ev.index ?? 0;
        if (cb?.type === 'tool_use' && cb.id && cb.name) {
          activeBlocks.set(idx, { type: 'tool_use', id: cb.id, name: cb.name, json: '' });
        } else {
          activeBlocks.set(idx, { type: 'text', id: '', name: '', json: '' });
        }
      } else if (ev.type === 'content_block_delta') {
        const idx = ev.index ?? 0;
        const block = activeBlocks.get(idx);
        if (block?.type === 'tool_use' && ev.delta?.partial_json) {
          block.json += ev.delta.partial_json;
        } else if (ev.delta?.text) {
          state.text += ev.delta.text;
          req.emit({ type: 'text', value: ev.delta.text });
        }
      } else if (ev.type === 'content_block_stop') {
        const idx = ev.index ?? 0;
        const block = activeBlocks.get(idx);
        if (block?.type === 'tool_use') {
          toolUses.push({ id: block.id, name: block.name, inputJson: block.json });
        }
        activeBlocks.delete(idx);
      } else if (ev.type === 'message_stop' || ev.type === 'message_delta') {
        const usage = ev.usage ?? ev.message?.usage;
        if (usage) {
          req.emit({ type: 'usage', inputTokens: usage.input_tokens, outputTokens: usage.output_tokens });
        }
      }
    }
  } finally {
    try { reader.releaseLock(); } catch { /* ignore */ }
  }
  return { toolUses };
}

function getMaxAgentIterations(): number {
  const raw = vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('autoMode.maxIterations', DEFAULT_MAX_AGENT_ITERATIONS);
  const n = typeof raw === 'number' && Number.isFinite(raw)
    ? Math.floor(raw)
    : DEFAULT_MAX_AGENT_ITERATIONS;
  return Math.min(200, Math.max(1, n));
}

export async function runViaCleanProvider(req: CleanRunRequest): Promise<void> {
  const requestId = genRequestId();

  if (req.signal.isCancellationRequested) {
    log.info('clean:precancelled', { requestId });
    // [C 黏一起根治 1.24.31] 送出瞬間取消也先落盤 user turn：否則 done/error 的 forceRender 終態
    //   重建會從 store 找不到 user 正本→樂觀泡泡被清成空白＝user 訊息憑空消失（比現況更糟）。
    await req.store.append(req.sessionId, { role: 'user', content: req.userMessage, ts: Date.now() });
    req.emit({ type: 'error', message: 'request cancelled before start' });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  // Record user turn locally.
  await req.store.append(req.sessionId, {
    role: 'user',
    content: req.userMessage,
    ts: Date.now(),
  });

  const abort = new AbortController();
  const cancelSub = req.signal.onCancellationRequested(() => abort.abort());
  const state = { text: '', reasoning: '', doneMode: 'primary' as 'primary' | 'fallback', thinkingMsAccum: 0, roundReasonStart: 0 };

  // [1.8.7] 逾時可調（深度思考模型首字可能慢、思考可能數分鐘）。預設：首字 60s、
  // chunk 間 idle 120s。connectHandle 從前只在串流「結束後」才清 = 變成總時間上限，
  // 會把幾分鐘的深度思考中途砍掉；現改成**首個 chunk 一到就清**（真連線逾時），
  // 之後只靠 idle 計時，總回覆時間不設限。
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const firstByteMs = Math.max(5, cfg.get<number>('timeout.firstByteSeconds') ?? 60) * 1000;
  const idleMs = Math.max(10, cfg.get<number>('timeout.idleSeconds') ?? 120) * 1000;

  let connectHandle: NodeJS.Timeout | undefined = setTimeout(() => {
    log.error('clean:timeout:connect', { requestId, ms: firstByteMs });
    abort.abort();
  }, firstByteMs);

  let idleHandle: NodeJS.Timeout | undefined;
  const resetIdle = () => {
    // 首個 chunk 到 = 連線成功 → 停掉首字逾時（否則它變總時間上限砍深度思考）。
    if (connectHandle) { clearTimeout(connectHandle); connectHandle = undefined; }
    if (idleHandle) clearTimeout(idleHandle);
    idleHandle = setTimeout(() => {
      log.error('clean:timeout:idle', { requestId, ms: idleMs });
      abort.abort();
    }, idleMs);
  };

  try {
    // 注意：不在這裡 resetIdle()——首字逾時(connectHandle)負責「等第一個 byte」，
    // idle 計時器要等真的有 chunk(resetIdle 由 iterateFrames 每 chunk 呼叫)才起算。
    log.info('clean:request:start', {
      requestId,
      provider: req.provider.id,
      kind: req.provider.kind,
      model: req.model,
    });

    // Non-Anthropic providers.
    if (req.provider.kind !== 'anthropic-direct') {
      const oaiCompat =
        req.provider.kind === 'openai-compat' ||
        req.provider.kind === 'ai-king-backend' ||
        req.provider.kind === 'custom';
      if (!oaiCompat) {
        req.emit({
          type: 'error',
          message: `Provider kind ${req.provider.kind} is not supported on stack=clean`,
        });
        return;
      }

      // ---- OpenAI-compat agent loop with function-calling tool_calls ----
      // [tool loop 2026-06-22] 對齊 Anthropic loop 的多輪結構：每輪串流 → 若無 tool_calls
      // 就 break（退化成單發）→ 否則組 assistant 回合（含 reasoning_content round-trip 命門）
      // → 逐一 permission gate + executeTool → 以 role:'tool' 回填 → 下一輪。無工具開關時
      //（oaiTools 空陣列、body 不掛 tools）模型不會發 tool_calls，第一輪就 break＝既有單發。
      const oaiTools = toOpenAITools(enabledToolsForStack(req.stack || 'clean'));
      const msgs = buildMessages(req);
      // attachments：只第一輪、且最後一則是 user 時套用（沿用原單發版 buildOpenAIUserContent 邏輯）。
      if (req.attachments && req.attachments.length > 0 && msgs.length > 0) {
        const last = msgs[msgs.length - 1];
        if (last.role === 'user') {
          last.content = buildOpenAIUserContent(req.userMessage, req.attachments);
        }
      }

      const maxIter = getMaxAgentIterations();
      // [thinking 落盤修 2026-06-22 紅藍CBUA] 跨輪累積每輪 reasoning/text、loop 結束全部落盤
      //（非只最後一輪殘值）。每輪 reset 前封存本輪、break/結束後封存最後一輪。重繪時還原全部
      // 思考（呈現為單一合併折疊塊，因 extractInlineThinking 會 merge 成一塊——不假裝分輪）。
      // stripThinkingForWire（chat-panel）組 wire history 時剝光所有 <think>，多塊落盤不污染
      // 下一輪 round-trip；本輪 loop 內的 reasoning_content round-trip 走未落盤的 state 獨立路徑。
      const reasoningSegs: string[] = [];
      const textSegs: string[] = [];
      for (let iter = 0; iter < maxIter; iter++) {
        if (req.signal.isCancellationRequested) break;

        const result = await streamOpenAICompat(
          req, requestId, state, abort, resetIdle, msgs, oaiTools,
        );

        // No tool calls — assistant is done (single-shot 退化路徑也走這裡 break)。
        if (result.toolCalls.length === 0) break;

        // Build the assistant turn (OpenAI 格式：content + tool_calls)。
        const assistantMsg: WireMsg = { role: 'assistant', content: state.text || null };
        assistantMsg.tool_calls = result.toolCalls.map((tc) => ({
          id: tc.id,
          type: 'function',
          function: { name: tc.name, arguments: tc.arguments },
        }));
        // ⚠ 命門：DeepSeek 發 tool_calls 的回合帶 reasoning_content，後續輪必須原樣回送，
        // 否則 HTTP 400 "Missing reasoning_content"。
        if (state.reasoning) assistantMsg.reasoning_content = state.reasoning;
        msgs.push(assistantMsg);

        // Execute each tool and build role:'tool' messages (OpenAI 用獨立 tool 角色 + tool_call_id)。
        for (const tc of result.toolCalls) {
          let parsedInput: Record<string, unknown> = {};
          try { parsedInput = JSON.parse(tc.arguments || '{}'); } catch { /* keep empty */ }

          req.emit({
            type: 'tool_start',
            name: tc.name,
            preview: (tc.arguments || '').slice(0, 200),
            args: parsedInput,
          });

          // [1.13.x 安全] permission gate（對齊 Anthropic 路徑）：deny 不中斷 loop，回一則
          // tool 訊息讓模型知道被拒、可改走別的方式。
          const allowed = await askPermissionAllowed(req.ctx, {
            tool: tc.name,
            args: parsedInput,
            context: '對話分頁 AI 工具呼叫',
            signal: req.signal, // [權限卡死修] 對話取消時授權窗一起關、視同 deny，不卡死 loop
            prompter: req.prompter, // [F 授權抽屜] 對話面板＝webview 抽屜、無＝QuickPick
          });
          if (!allowed) {
            log.warn('clean:openai:tool:denied', { requestId, iter, tool: tc.name });
            req.emit({
              type: 'tool_result',
              name: tc.name,
              ok: false,
              output: '使用者拒絕了這次工具呼叫（permission denied）。',
            });
            msgs.push({
              role: 'tool',
              tool_call_id: tc.id,
              content: '使用者拒絕了這次工具呼叫（permission denied）。改用別的方式或先說明原因。',
            });
            continue;
          }

          const toolResult = await executeTool(tc.name, parsedInput, {
            tavilyApiKey: tavilyApiKey(),
            signal: abort.signal,
          });
          log.info('clean:openai:tool:result', {
            requestId, iter, tool: tc.name,
            isError: !!toolResult.isError, len: toolResult.content.length,
          });
          req.emit({
            type: 'tool_result',
            name: tc.name,
            ok: !toolResult.isError,
            output: toolResult.content.slice(0, 500),
          });
          msgs.push({ role: 'tool', tool_call_id: tc.id, content: toolResult.content });
        }

        // [thinking 落盤修] reset 前先封存本輪（含 tool call 的中間輪也要留給落盤，不只最後一輪）。
        if (state.reasoning.trim()) reasoningSegs.push(state.reasoning);
        if (state.text) textSegs.push(state.text);
        // Reset accumulators for the next iteration's output.
        state.text = '';
        state.reasoning = '';

        log.info('clean:openai:agent:iter', { requestId, iter: iter + 1, tools: result.toolCalls.length });

        if (iter === maxIter - 1) {
          req.emit({ type: 'iteration_limit' });
          log.warn('clean:openai:agent:max-iterations', { requestId, max: maxIter });
        }
      }

      clearTimeout(connectHandle);
      // [thinking 落盤修] 封存最後一輪（break 那輪未經 reset），再把全部輪 join 落盤。
      if (state.reasoning.trim()) reasoningSegs.push(state.reasoning);
      if (state.text) textSegs.push(state.text);
      const fullText = textSegs.join('\n\n');
      // [D thinking 秒數 1.24.33 累加] 思考耗時＝所有輪「首 reasoning→首 content」累加（排除 tool 等待）。
      const thinkingMs = state.thinkingMsAccum;
      await persistAssistant(req.store, req.sessionId, fullText, reasoningSegs.join('\n\n'), thinkingMs);
      log.info('clean:request:end', { requestId, chars: fullText.length, segs: textSegs.length });
      req.emit({ type: 'done', mode: state.doneMode });
      return;
    }

    // ---- Anthropic agent loop with tool_use ----
    // Build the initial message list for the Anthropic API.
    const msgs = buildMessages(req).filter((m) => m.role !== 'system');
    // Apply multimodal attachments to the final user turn.
    const hasAttachments = !!req.attachments && req.attachments.length > 0;
    if (hasAttachments && msgs.length > 0) {
      const last = msgs[msgs.length - 1];
      if (last.role === 'user') {
        last.content = buildAnthropicUserContent(req.userMessage, req.attachments);
      }
    }

    // Read once per run so the cap stays consistent for the whole loop.
    const maxAgentIterations = getMaxAgentIterations();
    // [thinking 落盤修 2026-06-22 紅藍CBUA] 對稱比照 openai-compat：累積每輪 text、loop 結束
    // 全部落盤（非只最後一輪）。Anthropic 路徑目前不解析 thinking blocks→無 reasoning 可累積，
    // 故只累積 text；日後接 extended thinking 顯示再補 reasoning。
    const textSegs: string[] = [];

    for (let iter = 0; iter < maxAgentIterations; iter++) {
      if (req.signal.isCancellationRequested) break;

      const result = await streamAnthropicDirect(
        req, requestId, state, abort, resetIdle, msgs,
        enabledToolsForStack(req.stack || 'clean'),
      );

      // No tool calls — assistant is done.
      if (result.toolUses.length === 0) break;

      // Build the assistant content blocks for the conversation.
      // We need both the text (if any) and the tool_use blocks.
      const assistantContent: unknown[] = [];
      if (state.text) {
        // Only include text accumulated in this iteration (delta from last persist).
        assistantContent.push({ type: 'text', text: state.text });
      }
      for (const tu of result.toolUses) {
        let parsedInput: unknown = {};
        try { parsedInput = JSON.parse(tu.inputJson || '{}'); } catch { /* keep empty */ }
        assistantContent.push({ type: 'tool_use', id: tu.id, name: tu.name, input: parsedInput });
      }
      msgs.push({ role: 'assistant', content: assistantContent });

      // Execute each tool and build tool_result messages.
      const toolResults: unknown[] = [];
      for (const tu of result.toolUses) {
        let parsedInput: Record<string, unknown> = {};
        try { parsedInput = JSON.parse(tu.inputJson || '{}'); } catch { /* keep empty */ }

        // Emit tool_start event to the UI.
        req.emit({
          type: 'tool_start',
          name: tu.name,
          preview: tu.inputJson.slice(0, 200),
          args: parsedInput,
        });

        // [1.13.x 安全] 對話分頁工具呼叫補上 permission gate。過去 executeTool 直接跑＝
        // run_bash / write_file 完全無確認的 RCE/誤刪面（既存洞、比群組功能更早存在）。
        // 尊重 auto mode / autoApproveAll 短路（使用者自己機器、自己的 AI、自己設的信任 →
        // 無感）；未開信任則 QuickPick 確認、Esc=deny。deny 不中斷整個迴圈，回一則
        // is_error 的 tool_result 讓模型知道被拒、可改走別的方式。
        const toolAllowed = await askPermissionAllowed(req.ctx, {
          tool: tu.name,
          args: parsedInput,
          context: '對話分頁 AI 工具呼叫',
          signal: req.signal, // [權限卡死修] 對話取消時授權窗一起關、視同 deny，不卡死 loop
          prompter: req.prompter, // [F 授權抽屜] 對話面板＝webview 抽屜、無＝QuickPick
        });
        if (!toolAllowed) {
          log.warn('clean:tool:denied', { requestId, iter, tool: tu.name });
          req.emit({
            type: 'tool_result',
            name: tu.name,
            ok: false,
            output: '使用者拒絕了這次工具呼叫（permission denied）。',
          });
          toolResults.push({
            type: 'tool_result',
            tool_use_id: tu.id,
            content: '使用者拒絕了這次工具呼叫（permission denied）。改用別的方式或先說明原因。',
            is_error: true,
          });
          continue;
        }

        const toolResult = await executeTool(tu.name, parsedInput, {
          tavilyApiKey: tavilyApiKey(),
          signal: abort.signal,
        });
        log.info('clean:tool:result', {
          requestId, iter, tool: tu.name,
          isError: !!toolResult.isError, len: toolResult.content.length,
        });

        // Emit tool_result event to the UI.
        req.emit({
          type: 'tool_result',
          name: tu.name,
          ok: !toolResult.isError,
          output: toolResult.content.slice(0, 500),
        });

        toolResults.push({
          type: 'tool_result',
          tool_use_id: tu.id,
          content: toolResult.content,
          ...(toolResult.isError ? { is_error: true } : {}),
        });
      }
      msgs.push({ role: 'user', content: toolResults });

      // [thinking 落盤修] reset 前先封存本輪 text（中間輪也要留給落盤）。
      if (state.text) textSegs.push(state.text);
      // Reset text accumulator for the next iteration's text output.
      state.text = '';

      log.info('clean:agent:iter', { requestId, iter: iter + 1, tools: result.toolUses.length });

      if (iter === maxAgentIterations - 1) {
        req.emit({ type: 'iteration_limit' });
        log.warn('clean:agent:max-iterations', { requestId, max: maxAgentIterations });
      }
    }

    clearTimeout(connectHandle);
    // [thinking 落盤修] 封存最後一輪（break 那輪未經 reset），再把全部輪 join 落盤。
    if (state.text) textSegs.push(state.text);
    const fullText = textSegs.join('\n\n');
    await persistAssistant(req.store, req.sessionId, fullText);
    log.info('clean:request:end', { requestId, chars: fullText.length, segs: textSegs.length });
    req.emit({ type: 'done', mode: state.doneMode });
  } catch (e: any) {
    const aborted = abort.signal.aborted;
    // [1.8.4] 白話化：逾時/取消 給人看得懂的字，不是 'connection/idle timeout'。
    let host = req.provider.endpoint;
    try { host = new URL(req.provider.endpoint).host; } catch { /* keep endpoint */ }
    // [1.8.7] connectHandle 還在 = 第一個位元組從沒到（首字逾時）；已 undefined =
    // 串流開始後中途停太久（idle 逾時）。給不同白話訊息。
    const msg = aborted
      ? req.signal.isCancellationRequested
        ? '已取消'
        : connectHandle
          ? `連線逾時（${Math.round(firstByteMs / 1000)} 秒內 ${host} 沒回第一個位元組）— 請檢查網路 / 端點 / 金鑰；深度思考模型首字較慢可到設定調大「首字等待秒數」`
          : `回應中斷（串流停了超過 ${Math.round(idleMs / 1000)} 秒沒有新內容）— 上游可能斷線`
      : e?.message || String(e);
    log.error('clean:request:fail', { requestId, aborted, host, model: req.model, detail: msg });
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
  } finally {
    clearTimeout(connectHandle);
    if (idleHandle) clearTimeout(idleHandle);
    cancelSub.dispose();
  }
}

