function resolvePath(p: string): vscode.Uri {
  // On Windows, absolute paths start with drive letter or UNC.
  const isAbsolute = /^([a-zA-Z]:[/\\]|[/\\]{2})/.test(p) || p.startsWith('/');
  if (isAbsolute) {
    return vscode.Uri.file(p);
  }
  const folders = vscode.workspace.workspaceFolders;
  if (!folders || folders.length === 0) {
    return vscode.Uri.file(p);
  }
  return vscode.Uri.joinPath(folders[0].uri, p);
}

function getWorkspaceCwd(): string | undefined {
  const folders = vscode.workspace.workspaceFolders;
  return folders && folders.length > 0 ? folders[0].uri.fsPath : undefined;
}

export interface ToolResult {
  content: string;
  isError?: boolean;
}

async function execReadFile(input: { path?: string }): Promise<ToolResult> {
  if (!input.path) return { content: 'Error: missing required parameter "path"', isError: true };
  try {
    const uri = resolvePath(input.path);
    const bytes = await vscode.workspace.fs.readFile(uri);
    return { content: new TextDecoder().decode(bytes) };
  } catch (e: any) {
    return { content: `Error reading file: ${e?.message || String(e)}`, isError: true };
  }
}

async function execListFiles(input: { path?: string }): Promise<ToolResult> {
  try {
    const target = input.path ? resolvePath(input.path) : resolvePath('.');
    const entries = await vscode.workspace.fs.readDirectory(target);
    const lines = entries.map(([name, type]) => {
      const tag = type === vscode.FileType.Directory ? '[dir]' : '[file]';
      return `${tag} ${name}`;
    });
    return { content: lines.join('\n') || '(empty directory)' };
  } catch (e: any) {
    return { content: `Error listing directory: ${e?.message || String(e)}`, isError: true };
  }
}

async function execWriteFile(input: { path?: string; content?: string }): Promise<ToolResult> {
  if (!input.path) return { content: 'Error: missing required parameter "path"', isError: true };
  try {
    const uri = resolvePath(input.path);
    const data = new TextEncoder().encode(input.content ?? '');
    await vscode.workspace.fs.writeFile(uri, data);
    return { content: `Wrote ${data.length} bytes to ${uri.fsPath}` };
  } catch (e: any) {
    return { content: `Error writing file: ${e?.message || String(e)}`, isError: true };
  }
}

async function execEditFile(input: {
  path?: string;
  old_string?: string;
  new_string?: string;
  replace_all?: boolean;
}): Promise<ToolResult> {
  if (!input.path) return { content: 'Error: missing required parameter "path"', isError: true };
  if (typeof input.old_string !== 'string' || typeof input.new_string !== 'string') {
    return { content: 'Error: edit_file requires string "old_string" and "new_string"', isError: true };
  }
  if (input.old_string === '') {
    return { content: 'Error: "old_string" must not be empty (use write_file to create a file).', isError: true };
  }
  try {
    const uri = resolvePath(input.path);
    const text = new TextDecoder().decode(await vscode.workspace.fs.readFile(uri));
    const count = text.split(input.old_string).length - 1;
    if (count === 0) {
      return {
        content: `Error: old_string not found in ${uri.fsPath}. It must match exactly, including whitespace.`,
        isError: true,
      };
    }
    if (count > 1 && !input.replace_all) {
      return {
        content: `Error: old_string is not unique (${count} matches) in ${uri.fsPath}. Add more surrounding context to make it unique, or set replace_all=true.`,
        isError: true,
      };
    }
    // split/join = literal replace (avoids String.replace's $-pattern interpretation in new_string).
    const updated = text.split(input.old_string).join(input.new_string);
    await vscode.workspace.fs.writeFile(uri, new TextEncoder().encode(updated));
    return { content: `Edited ${uri.fsPath} (${count} occurrence${count > 1 ? 's' : ''} replaced).` };
  } catch (e: any) {
    return { content: `Error editing file: ${e?.message || String(e)}`, isError: true };
  }
}

async function execGrep(input: {
  pattern?: string;
  path?: string;
  glob?: string;
  ignore_case?: boolean;
}): Promise<ToolResult> {
  if (!input.pattern) return { content: 'Error: missing required parameter "pattern"', isError: true };
  let re: RegExp;
  try {
    re = new RegExp(input.pattern, input.ignore_case ? 'i' : '');
  } catch (e: any) {
    return { content: `Error: invalid regex: ${e?.message || String(e)}`, isError: true };
  }
  try {
    const includeGlob = input.glob || '**/*';
    const pattern: vscode.GlobPattern = input.path
      ? new vscode.RelativePattern(resolvePath(input.path), includeGlob)
      : includeGlob;
    const exclude = '**/{node_modules,.git,dist,out,build,.vscode-test}/**';
    const MAX_FILES = 2000;
    const MAX_MATCHES = 300;
    const files = await vscode.workspace.findFiles(pattern, exclude, MAX_FILES);
    const lines: string[] = [];
    let matchCount = 0;
    let truncated = false;
    for (const file of files) {
      if (matchCount >= MAX_MATCHES) {
        truncated = true;
        break;
      }
      let text: string;
      try {
        const bytes = await vscode.workspace.fs.readFile(file);
        if (bytes.length > 2 * 1024 * 1024) continue; // skip files > 2 MB
        text = new TextDecoder('utf-8', { fatal: false }).decode(bytes);
      } catch {
        continue;
      }
      const fileLines = text.split(/\r?\n/);
      for (let i = 0; i < fileLines.length; i++) {
        if (re.test(fileLines[i])) {
          lines.push(`${file.fsPath}:${i + 1}:${fileLines[i].slice(0, 300)}`);
          if (++matchCount >= MAX_MATCHES) {
            truncated = true;
            break;
          }
        }
      }
    }
    if (lines.length === 0) {
      return { content: `No matches for /${input.pattern}/${input.ignore_case ? 'i' : ''}.` };
    }
    const header = `${matchCount} match(es)${truncated ? ` (truncated at ${MAX_MATCHES})` : ''}:`;
    return { content: `${header}\n${lines.join('\n')}` };
  } catch (e: any) {
    return { content: `Error during grep: ${e?.message || String(e)}`, isError: true };
  }
}

function execRunBash(input: { command?: string }): Promise<ToolResult> {
  if (!input.command) {
    return Promise.resolve({ content: 'Error: missing required parameter "command"', isError: true });
  }
  const cwd = getWorkspaceCwd();
  return new Promise((resolve) => {
    exec(
      input.command!,
      { timeout: 30_000, maxBuffer: 1024 * 1024, cwd },
      (err, stdout, stderr) => {
        const out = [stdout, stderr].filter(Boolean).join('\n');
        if (err) {
          resolve({ content: out || err.message, isError: true });
        } else {
          resolve({ content: out || '(no output)' });
        }
      },
    );
  });
}

