export async function executeTool(
  name: string,
  input: Record<string, unknown>,
  ctx?: ToolExecContext,
): Promise<ToolResult> {
  log.info('clean:tool:exec', { name, inputKeys: Object.keys(input) });
  switch (name) {
    case 'read_file':
      return execReadFile(input as { path?: string });
    case 'list_files':
      return execListFiles(input as { path?: string });
    case 'write_file':
      return execWriteFile(input as { path?: string; content?: string });
    case 'edit_file':
      return execEditFile(
        input as { path?: string; old_string?: string; new_string?: string; replace_all?: boolean },
      );
    case 'grep':
      return execGrep(input as { pattern?: string; path?: string; glob?: string; ignore_case?: boolean });
    case 'run_bash':
      return execRunBash(input as { command?: string });
    case 'web_search':
      return execWebSearch(input as { query?: string }, ctx);
    case 'web_fetch':
      return execWebFetch(input as { url?: string }, ctx);
    default:
      return { content: `Unknown tool: ${name}`, isError: true };
  }
}

const ConsoleChatResponseSchema = z.object({
  ok: z.boolean().optional(),
  answer: z.string().optional(),
  mode: z.string().optional(),
  cost: z.number().optional(),
  slowReply: z.boolean().optional(),
  error: z.union([z.string(), z.object({}).catchall(z.unknown())]).optional(),
  message: z.string().optional(),
}).catchall(z.unknown());

export interface DigitalHumanRunRequest {
  ctx: vscode.ExtensionContext;
  store: SessionStore;
  sessionId: string;
  mode: ChatMode;
  endpoint: string;
  chatPath: string;
  model: string;
  systemPrompt: string;
  userMessage: string;
  history: ChatMessage[];
  thinking?: { enabled: boolean; budgetTokens: number };
  effort?: 'low' | 'medium' | 'high';
  signal: vscode.CancellationToken;
  emit: (event: RunnerEvent) => void;
  // 0.13.3: character routing + trial flag (from config).
  characterName?: string;
  trial?: boolean;
  userId?: string;
}

interface SSEFrame {
  event?: string;
  data: string;
}

function genRequestId(): string {
  return `dh-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function buildUrl(endpoint: string, chatPath: string): string {
  const base = endpoint.replace(/\/+$/, '');
  const path = chatPath.startsWith('/') ? chatPath : `/${chatPath}`;
  return `${base}${path}`;
}

function buildConsoleBody(req: DigitalHumanRunRequest): Record<string, unknown> {
  const body: Record<string, unknown> = {
    characterName: req.characterName || 'default',
    message: req.userMessage,
  };
  if (req.userId) body.userId = req.userId;
  if (req.trial) body.trial = true;
  return body;
}

function parseSSEBlock(block: string): SSEFrame | null {
  const lines = block.split('\n');
  let event: string | undefined;
  const dataLines: string[] = [];
  for (const line of lines) {
    const trimmed = line.replace(/\r$/, '');
    if (!trimmed || trimmed.startsWith(':')) continue;
    if (trimmed.startsWith('event:')) event = trimmed.slice(6).trim();
    else if (trimmed.startsWith('data:')) dataLines.push(trimmed.slice(5).trim());
  }
  if (dataLines.length === 0) return null;
  return { event, data: dataLines.join('\n') };
}

function extractLegacyText(json: unknown): string {
  const parsed = LegacyChunkSchema.safeParse(json);
  if (!parsed.success) return '';
  const d = parsed.data;
  if (typeof d.delta === 'string' && d.delta) return d.delta;
  if (typeof d.text === 'string' && d.text) return d.text;
  if (typeof d.value === 'string' && d.value) return d.value;
  if (typeof d.content === 'string' && d.content) return d.content;
  if (typeof d.answer === 'string' && d.answer) return d.answer;
  if (Array.isArray(d.choices) && d.choices.length > 0) {
    for (const c of d.choices) {
      const v = c?.delta?.content ?? c?.message?.content;
      if (typeof v === 'string' && v) return v;
    }
  }
  return '';
}

async function persistAssistant(
  store: SessionStore,
  sessionId: string,
  text: string,
): Promise<void> {
  if (!text) return;
  await store.append(sessionId, { role: 'assistant', content: text, ts: Date.now() });
}

export async function runViaDigitalHuman(req: DigitalHumanRunRequest): Promise<void> {
  const requestId = genRequestId();

  if (req.signal.isCancellationRequested) {
    log.info('digital-human:precancelled', { requestId });
    req.emit({ type: 'error', message: 'request cancelled before start' });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  try {
    assertSancioEndpointAllowed(req.endpoint);
  } catch (e: unknown) {
    const msg = e instanceof EndpointNotAllowedError ? e.message : String(e);
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  const token = await req.ctx.secrets.get(DIGITAL_HUMAN_TOKEN_SECRET);
  if (!token) {
    const msg =
      'Digital Human bearer token not set. Run command "AI King: Set Digital Human Bearer Token" (Ctrl+Shift+P) to configure.';
    log.error('digital-human:no-token', { requestId });
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  await req.store.append(req.sessionId, {
    role: 'user',
    content: req.userMessage,
    ts: Date.now(),
  });

  const url = buildUrl(req.endpoint, req.chatPath);
  const abort = new AbortController();
  const cancelSub = req.signal.onCancellationRequested(() => {
    log.info('digital-human:cancel', { requestId });
    abort.abort();
  });

  let assistantText = '';
  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  let idleHandle: NodeJS.Timeout | undefined;
  const resetIdle = () => {
    if (idleHandle) clearTimeout(idleHandle);
    idleHandle = setTimeout(() => {
      log.error('digital-human:timeout:idle', { requestId, ms: IDLE_TIMEOUT_MS });
      abort.abort();
    }, IDLE_TIMEOUT_MS);
  };
  const connectTimer = setTimeout(() => {
    if (!reader) {
      log.error('digital-human:timeout:connect', { requestId, ms: CONNECT_TIMEOUT_MS });
      abort.abort();
    }
  }, CONNECT_TIMEOUT_MS);

  try {
    log.info('digital-human:request:start', {
      requestId,
      url,
      characterName: req.characterName || 'default',
      trial: !!req.trial,
    });
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json, text/event-stream',
        Authorization: `Bearer ${token}`,
        'X-Request-Id': requestId,
      },
      body: JSON.stringify(buildConsoleBody(req)),
      signal: abort.signal,
    });
    clearTimeout(connectTimer);

    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      log.error('digital-human:http:non-2xx', {
        requestId,
        status: resp.status,
        preview: text.slice(0, 200),
      });
      const hint =
        resp.status === 401
          ? ' (token invalid or expired — run "AI King: Set Digital Human Bearer Token")'
          : resp.status === 404
            ? ' (chatPath mismatch — check aiKing.digitalHumanChatPath; expected /api/console/chat)'
            : '';
      req.emit({
        type: 'error',
        message: `Digital Human HTTP ${resp.status}${hint}: ${text.slice(0, 300)}`,
      });
      req.emit({ type: 'done', mode: 'primary' });
      return;
    }

    const contentType = resp.headers.get('content-type') || '';
    const isSSE = contentType.includes('text/event-stream');
    // [1.9.3] 對照 clean:openai:200 — 一眼看出上游回的是 JSON 主路徑還是 SSE fallback。
    log.info('digital-human:http:200', { requestId, contentType, isSSE });

    // --- Primary path: application/json single-shot (0.13.3 contract) ---
    if (!isSSE) {
      const raw = await resp.text();
      let json: unknown;
      try {
        json = JSON.parse(raw);
      } catch {
        if (raw) {
          assistantText += raw;
          req.emit({ type: 'text', value: raw });
        }
        await persistAssistant(req.store, req.sessionId, assistantText);
        req.emit({ type: 'done', mode: 'primary' });
        return;
      }

      const parsed = ConsoleChatResponseSchema.safeParse(json);
      if (parsed.success && (parsed.data.answer !== undefined || parsed.data.ok !== undefined)) {
        const d = parsed.data;
        if (d.ok === false) {
          const errMsg =
            (typeof d.error === 'string' && d.error) ||
            (typeof d.message === 'string' && d.message) ||
            'digital-human: ok:false with no error message';
          log.error('digital-human:ok-false', { requestId, errMsg });
          req.emit({ type: 'error', message: errMsg });
          req.emit({ type: 'done', mode: 'primary' });
          return;
        }
        if (typeof d.answer === 'string' && d.answer) {
          assistantText = d.answer;
          req.emit({ type: 'text', value: d.answer });
          log.info('digital-human:console:ok', {
            requestId,
            chars: d.answer.length,
            mode: d.mode,
            cost: d.cost,
            slowReply: d.slowReply,
          });
        } else {
          log.warn('digital-human:console:empty-answer', {
            requestId,
            preview: raw.slice(0, 200),
          });
        }
      } else {
        // Fallback to legacy extractor (dify-ish shapes) for backward compat.
        const v = extractLegacyText(json);
        if (v) {
          assistantText += v;
          req.emit({ type: 'text', value: v });
        } else {
          log.warn('digital-human:unknown-shape', {
            requestId,
            preview: raw.slice(0, 200),
          });
        }
      }

      await persistAssistant(req.store, req.sessionId, assistantText);
      req.emit({ type: 'done', mode: 'primary' });
      return;
    }

    // --- Fallback path: SSE stream (legacy dify-style) ---
    if (!resp.body) {
      req.emit({ type: 'error', message: 'Digital Human: empty response body' });
      req.emit({ type: 'done', mode: 'primary' });
      return;
    }

    reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let done = false;
    // [1.9.3] 對照 clean:openai:first-frame — legacy SSE 收不到任何欄位（畸形/未知
    // shape）時真因現形。旗標宣告在 while 迴圈外，別放迴圈內（每幀重置就失去語意）。
    let sawFirstFrame = false;
    resetIdle();

    while (!req.signal.isCancellationRequested && !done) {
      const chunk = await reader.read();
      if (chunk.done) break;
      resetIdle();
      buffer += decoder.decode(chunk.value, { stream: true });
      let idx: number;
      while ((idx = buffer.indexOf('\n\n')) !== -1) {
        const block = buffer.slice(0, idx);
        buffer = buffer.slice(idx + 2);
        const frame = parseSSEBlock(block);
        if (!frame) continue;
        if (frame.data === '[DONE]') {
          done = true;
          break;
        }
        let json: unknown;
        try {
          json = JSON.parse(frame.data);
        } catch {
          if (frame.data) {
            assistantText += frame.data;
            req.emit({ type: 'text', value: frame.data });
          }
          continue;
        }
        if (!sawFirstFrame) {
          sawFirstFrame = true;
          log.info('digital-human:sse:first-frame', {
            requestId,
            keys: json && typeof json === 'object' ? Object.keys(json as object) : [],
          });
        }
        const v = extractLegacyText(json);
        if (v) {
          assistantText += v;
          req.emit({ type: 'text', value: v });
        }
      }
    }

    await persistAssistant(req.store, req.sessionId, assistantText);
    // [1.9.3] sse:end 區分「走 SSE fallback 結束」vs JSON 主路徑（request:end 不分）。
    log.info('digital-human:sse:end', { requestId, chars: assistantText.length });
    if (!assistantText) log.warn('digital-human:sse:empty', { requestId });
    log.info('digital-human:request:end', { requestId, chars: assistantText.length });
    req.emit({ type: 'done', mode: 'primary' });
  } catch (e: any) {
    const aborted = abort.signal.aborted;
    const msg = aborted
      ? req.signal.isCancellationRequested
        ? 'cancelled'
        : 'connection/idle timeout'
      : e?.message || String(e);
    log.error('digital-human:request:fail', { requestId, aborted, detail: msg });
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
  } finally {
    clearTimeout(connectTimer);
    if (idleHandle) clearTimeout(idleHandle);
    cancelSub.dispose();
    if (reader) {
      try {
        reader.releaseLock();
      } catch {
        /* ignore */
      }
    }
  }
}

export interface ImageGenRequest {
  /** Active provider — endpoint + auth come from here. */
  provider: Provider;
  apiKey: string;
  /** Image model id, e.g. "gpt-image-2". */
  model: string;
  /** Text prompt — the only input this version supports. */
  prompt: string;
  signal: vscode.CancellationToken;
}

export interface ImageGenResult {
  /** `data:image/png;base64,...` — ready for markdown embedding. */
  dataUrl: string;
}

function imagesUrl(endpoint: string): string {
  return `${endpoint.replace(/\/+$/, '')}/images/generations`;
}

function friendlyHttpError(status: number, bodyPreview: string): Error {
  if (status === 401) {
    return new Error('API 金鑰無效（401）— 請到設定頁檢查這家 provider 的金鑰');
  }
  if (status === 403) {
    return new Error(
      '沒有權限使用此圖像模型（403）— OpenAI 可能要求先完成組織驗證' +
        '（Organization Verification，到 platform.openai.com 的組織設定完成身分驗證）',
    );
  }
  if (status === 429) {
    return new Error('請求被限流（429）— 請稍等一下再試');
  }
  return new Error(`圖像生成失敗（HTTP ${status}）：${bodyPreview.slice(0, 300)}`);
}

async function urlToDataUrl(url: string, abort: AbortController): Promise<string> {
  const resp = await fetch(url, { signal: abort.signal });
  if (!resp.ok) {
    throw new Error(`圖像下載失敗（HTTP ${resp.status}）— API 回了 url 但抓不下來`);
  }
  const mime = resp.headers.get('content-type') || 'image/png';
  const buf = Buffer.from(await resp.arrayBuffer());
  return `data:${mime};base64,${buf.toString('base64')}`;
}

export async function runImageGeneration(req: ImageGenRequest): Promise<ImageGenResult> {
  const url = imagesUrl(req.provider.endpoint);
  const abort = new AbortController();
  const timeout = setTimeout(() => abort.abort(), IMAGE_TIMEOUT_MS);
  const cancelSub = req.signal.onCancellationRequested(() => abort.abort());

  try {
    log.info('image-gen:start', { url, model: req.model });
    let resp: Response;
    try {
      resp = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${req.apiKey}`,
        },
        body: JSON.stringify({ model: req.model, prompt: req.prompt }),
        signal: abort.signal,
      });
    } catch (e: any) {
      if (req.signal.isCancellationRequested) throw new Error('已取消');
      if (abort.signal.aborted) {
        throw new Error('圖像生成逾時（120 秒）— 伺服器沒有在時限內回應，請再試一次');
      }
      throw new Error(`連不上圖像 API（${e?.message || String(e)}）`);
    }

    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      log.error('image-gen:http', { status: resp.status, preview: text.slice(0, 200) });
      throw friendlyHttpError(resp.status, text);
    }

    const json = (await resp.json().catch(() => null)) as {
      data?: Array<{ b64_json?: string; url?: string }>;
    } | null;
    const first = json?.data?.[0];
    if (first?.b64_json) {
      log.info('image-gen:done', { via: 'b64_json', bytes: first.b64_json.length });
      return { dataUrl: `data:image/png;base64,${first.b64_json}` };
    }
    if (first?.url) {
      // Some servers return a hosted URL instead of base64 — inline it so the
      // webview CSP (img-src data: only) can still render the picture.
      const dataUrl = await urlToDataUrl(first.url, abort);
      log.info('image-gen:done', { via: 'url' });
      return { dataUrl };
    }
    throw new Error('圖像 API 回應裡沒有圖片（缺 data[0].b64_json / url）');
  } finally {
    clearTimeout(timeout);
    cancelSub.dispose();
  }
}

const TokenEventSchema = z.object({
  text: z.string().optional(),
  value: z.string().optional(),
  delta: z.string().optional(),
});

const ToolCallEventSchema = z.object({
  id: z.string().optional(),
  tool: z.string().optional(),
  name: z.string().optional(),
  input: z.unknown().optional(),
  args: z.unknown().optional(),
  preview: z.string().optional(),
});

const ToolResultEventSchema = z.object({
  id: z.string().optional(),
  name: z.string().optional(),
  output: z.string().optional(),
  error: z.union([z.boolean(), z.string(), z.null()]).optional(),
  ok: z.boolean().optional(),
});

const IterationEventSchema = z.object({
  n: z.number().optional(),
  state: z.string().optional(),
});

const UsageEventSchema = z.object({
  input_tokens: z.number().optional(),
  output_tokens: z.number().optional(),
  cache_read_input_tokens: z.number().optional(),
  cache_creation_input_tokens: z.number().optional(),
  inputTokens: z.number().optional(),
  outputTokens: z.number().optional(),
  cacheReadInputTokens: z.number().optional(),
  cacheCreationInputTokens: z.number().optional(),
});

const DoneEventSchema = z.object({
  mode: z.string().optional(),
  usage: z.unknown().optional(),
  request_id: z.string().optional(),
  stop_reason: z.string().optional(),
  total_tokens: z.number().optional(),
});

const ErrorEventSchema = z.object({
  message: z.string().optional(),
  error: z.string().optional(),
  code: z.string().optional(),
  detail: z.string().optional(),
});

const PermissionAskEventSchema = z.object({
  /** Correlation id used when we reply via the caller's emit contract. */
  id: z.string().optional(),
  /** Tool name — normalized client-side before the user sees it. */
  tool: z.string().optional(),
  name: z.string().optional(),
  /** Raw tool arguments; shown in the prompt detail (truncated). */
  args: z.unknown().optional(),
  input: z.unknown().optional(),
  /** Free-form reason shown under the tool name. */
  context: z.string().optional(),
  reason: z.string().optional(),
});

export type RunnerEvent =
  | { type: 'text'; value: string }
  // [1.8.6] streamed reasoning/thinking content (DeepSeek reasoner / v4 思考模式
  // 的 reasoning_content)。webview 已有對應 handler（chat.js e.type==='thinking'
  // → appendThinkingDelta），顯示成可折疊的思考區塊。
  | { type: 'thinking'; value: string }
  | { type: 'tool_start'; name: string; preview: string; args: unknown }
  | { type: 'tool_result'; name: string; ok: boolean; output: string }
  | {
      type: 'usage';
      inputTokens?: number;
      outputTokens?: number;
      cacheReadInputTokens?: number;
      cacheCreationInputTokens?: number;
    }
  | { type: 'iteration_limit' }
  | { type: 'error'; message: string }
  // 0.17.0 — server-driven permission prompt. The panel shows QuickPick
  // via src/permission/gate.ts and POSTs the answer back to the server
  // out-of-band (we don't block the stream here — /v1/agent/run keeps
  // sending tokens and the caller correlates by `id`).
  | {
      type: 'permission_ask';
      id: string;
      tool: string;
      args: unknown;
      context?: string;
    }
  | { type: 'done'; mode: 'primary' | 'fallback' };

export interface SancioRunRequest {
  ctx: vscode.ExtensionContext;
  store: SessionStore;
  sessionId: string;
  mode: ChatMode;
  sancioEndpoint: string;
  apiKey: string;
  /**
   * [1.7.0 §10.7] Active provider id ("openai" / "anthropic" / …). The local
   * Sancio /v1/agent/run contract wants a provider-qualified model
   * (`provider:model`) plus the key in `provider_extra` — parity with the
   * bridge-view callAIKingAgent contract (bridge-view.ts).
   */
  providerId: string;
  model: string;
  stack: string;
  systemPrompt: string;
  userMessage: string;
  history: ChatMessage[];
  /** Thinking toggle. `budgetTokens` is REQUIRED when `enabled=true`. */
  thinking?: { enabled: boolean; budgetTokens: number };
  effort?: 'low' | 'medium' | 'high';
  signal: vscode.CancellationToken;
  emit: (event: RunnerEvent) => void;
}

interface SSEFrame {
  event?: string;
  data: string;
}

interface StreamState {
  assistantText: string;
  done: boolean;
  doneMode: 'primary' | 'fallback';
}

function normalizeEndpoint(endpoint: string): string {
  const trimmed = endpoint.replace(/\/+$/, '');
  if (trimmed.endsWith('/v1')) return trimmed;
  if (/\/v1\/agent\/run$/.test(trimmed)) return trimmed.replace(/\/agent\/run$/, '');
  return `${trimmed}/v1`;
}

function parseSSEBlock(block: string): SSEFrame | null {
  const lines = block.split('\n');
  let event: string | undefined;
  const dataLines: string[] = [];
  for (const line of lines) {
    const trimmed = line.replace(/\r$/, '');
    if (!trimmed || trimmed.startsWith(':')) continue;
    if (trimmed.startsWith('event:')) {
      event = trimmed.slice(6).trim();
    } else if (trimmed.startsWith('data:')) {
      dataLines.push(trimmed.slice(5).trim());
    }
  }
  if (dataLines.length === 0) return null;
  return { event, data: dataLines.join('\n') };
}

function buildRequestBody(req: SancioRunRequest): Record<string, unknown> {
  // Convert ChatMessage[] to Sancio /v1/agent/run schema (role+content only
  // for user/assistant — tool messages dropped server-side). We ship the
  // full history as 'messages' and the system prompt as a separate
  // 'system' field to keep the server contract simple.
  const messages: Array<{ role: string; content: string }> = [];
  if (req.systemPrompt) {
    messages.push({ role: 'system', content: req.systemPrompt });
  }
  for (const m of req.history) {
    messages.push({ role: m.role, content: m.content });
  }
  messages.push({ role: 'user', content: req.userMessage });

  // [1.7.0 §10.7] Local-Sancio contract (parity with bridge-view.ts
  // callAIKingAgent): model is provider-qualified ("openai:gpt-5.5") and the
  // provider API key rides in provider_extra — never as the Bearer header
  // (local server runs SANCIO_REQUIRE_AUTH=0; the old code leaked the
  // provider key as a JWT-slot Bearer).
  const providerExtra: Record<string, string> = {};
  if (req.apiKey && req.apiKey !== 'none') {
    providerExtra.api_key = req.apiKey;
  }
  const body: Record<string, unknown> = {
    stack: req.stack,
    model: req.providerId ? `${req.providerId}:${req.model}` : req.model,
    messages,
    provider_extra: providerExtra,
  };
  if (req.thinking && req.thinking.enabled) {
    // Caller owns the budget — this module no longer has a local default
    // (Opus review HIGH: single source of truth for thinking budget).
    body.thinking_budget = req.thinking.budgetTokens;
  }
  if (req.effort) body.effort = req.effort;
  return body;
}

function buildHeaders(requestId: string): Record<string, string> {
  // [1.7.0 §10.7] No Authorization header: the local Sancio runs with
  // SANCIO_REQUIRE_AUTH=0 (no JWT needed) and the provider key now travels
  // in the body's provider_extra instead of being mis-sent as a Bearer.
  return {
    'Content-Type': 'application/json',
    Accept: 'text/event-stream',
    'X-Request-Id': requestId,
  };
}

function genRequestId(): string {
  return `ext-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

async function persistAssistant(
  store: SessionStore,
  sessionId: string,
  text: string,
): Promise<void> {
  if (!text) return;
  await store.append(sessionId, { role: 'assistant', content: text, ts: Date.now() });
}

function emitTextEvent(
  json: unknown,
  state: StreamState,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = TokenEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:token:invalid', { requestId, zod: parsed.error.issues });
    return;
  }
  const v = parsed.data.text ?? parsed.data.value ?? parsed.data.delta;
  if (typeof v === 'string' && v.length > 0) {
    state.assistantText += v;
    emit({ type: 'text', value: v });
  }
}

function emitToolStart(
  json: unknown,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = ToolCallEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:tool_call:invalid', { requestId, zod: parsed.error.issues });
    return;
  }
  const d = parsed.data;
  emit({
    type: 'tool_start',
    name: String(d.tool ?? d.name ?? ''),
    preview: String(d.preview ?? ''),
    args: d.input ?? d.args,
  });
}

function emitToolResult(
  json: unknown,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = ToolResultEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:tool_result:invalid', { requestId, zod: parsed.error.issues });
    return;
  }
  const d = parsed.data;
  const isError = d.error != null && d.error !== false;
  emit({
    type: 'tool_result',
    name: String(d.name ?? ''),
    ok: d.ok != null ? !!d.ok : !isError,
    output: String(d.output ?? ''),
  });
}

function emitUsageEvent(
  json: unknown,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = UsageEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:usage:invalid', { requestId, zod: parsed.error.issues });
    return;
  }
  const d = parsed.data;
  emit({
    type: 'usage',
    inputTokens: d.input_tokens ?? d.inputTokens,
    outputTokens: d.output_tokens ?? d.outputTokens,
    cacheReadInputTokens: d.cache_read_input_tokens ?? d.cacheReadInputTokens,
    cacheCreationInputTokens: d.cache_creation_input_tokens ?? d.cacheCreationInputTokens,
  });
}

function handleIteration(json: unknown, state: StreamState, requestId: string): void {
  const parsed = IterationEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:iteration:invalid', { requestId, zod: parsed.error.issues });
    return;
  }
  if (parsed.data.state === 'max_iterations') {
    // Surface through the shared event — we emit in the caller via state.
    state.doneMode = 'fallback';
  }
}

function handleDone(
  json: unknown,
  state: StreamState,
  requestId: string,
): void {
  const parsed = DoneEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:done:invalid', { requestId, zod: parsed.error.issues });
    // Still mark done — transport-level completion overrides schema gripes.
    state.done = true;
    return;
  }
  state.done = true;
  state.doneMode = parsed.data.mode === 'fallback' ? 'fallback' : state.doneMode;
}

function handleError(
  json: unknown,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = ErrorEventSchema.safeParse(json);
  if (!parsed.success) {
    log.error('sancio:event:error:invalid', { requestId, zod: parsed.error.issues });
    emit({ type: 'error', message: 'unknown error' });
    return;
  }
  const d = parsed.data;
  const msg = d.message ?? d.error ?? d.detail ?? d.code ?? 'unknown error';
  log.error('sancio:event:error', { requestId, code: d.code, message: msg });
  emit({ type: 'error', message: String(msg) });
}

function emitPermissionAsk(
  json: unknown,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  const parsed = PermissionAskEventSchema.safeParse(json);
  if (!parsed.success) {
    log.warn('sancio:event:permission_ask:invalid', {
      requestId,
      zod: parsed.error.issues,
    });
    return;
  }
  const d = parsed.data;
  const tool = String(d.tool ?? d.name ?? '');
  if (!tool) {
    log.warn('sancio:event:permission_ask:missing-tool', { requestId });
    return;
  }
  emit({
    type: 'permission_ask',
    id: String(d.id ?? ''),
    tool,
    args: d.args ?? d.input,
    context: d.context ?? d.reason,
  });
}

function dispatchJsonFrame(
  kind: string,
  json: unknown,
  state: StreamState,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  if (kind === 'text' || kind === 'delta' || kind === 'token') {
    emitTextEvent(json, state, emit, requestId);
  } else if (kind === 'tool_call' || kind === 'tool_start') {
    emitToolStart(json, emit, requestId);
  } else if (kind === 'tool_result') {
    emitToolResult(json, emit, requestId);
  } else if (kind === 'usage') {
    emitUsageEvent(json, emit, requestId);
  } else if (kind === 'iteration') {
    handleIteration(json, state, requestId);
  } else if (kind === 'iteration_limit') {
    emit({ type: 'iteration_limit' });
  } else if (kind === 'permission_ask' || kind === 'permission.ask') {
    emitPermissionAsk(json, emit, requestId);
  } else if (kind === 'error') {
    handleError(json, emit, requestId);
  } else if (kind === 'done') {
    handleDone(json, state, requestId);
  } else {
    // Forward-compat: unknown event names are logged but never crash.
    log.info('sancio:event:unknown', { requestId, kind, raw: String(json).slice(0, 200) });
  }
}

function handleFrame(
  frame: SSEFrame,
  state: StreamState,
  emit: (e: RunnerEvent) => void,
  requestId: string,
): void {
  if (frame.data === '[DONE]') {
    state.done = true;
    return;
  }
  let json: unknown;
  try {
    json = JSON.parse(frame.data);
  } catch {
    // Non-JSON data — still forward as raw text delta, and log once.
    if (frame.data.length > 0) {
      state.assistantText += frame.data;
      emit({ type: 'text', value: frame.data });
      log.warn('sancio:frame:non-json', {
        requestId,
        event: frame.event,
        preview: frame.data.slice(0, 200),
      });
    }
    return;
  }
  const kind: string =
    frame.event ||
    (typeof (json as { type?: unknown })?.type === 'string'
      ? ((json as { type: string }).type)
      : 'text');
  dispatchJsonFrame(kind, json, state, emit, requestId);
}

class IdleTimer {
  private handle: NodeJS.Timeout | undefined;

  constructor(
    private readonly ms: number,
    private readonly onTimeout: () => void,
  ) {}

  reset(): void {
    if (this.handle) clearTimeout(this.handle);
    this.handle = setTimeout(this.onTimeout, this.ms);
  }

  dispose(): void {
    if (this.handle) clearTimeout(this.handle);
    this.handle = undefined;
  }
}

constructor(
  private readonly ms: number,
  private readonly onTimeout: () => void,
) {}

reset(): void {
  if (this.handle) clearTimeout(this.handle);
  this.handle = setTimeout(this.onTimeout, this.ms);
}

dispose(): void {
  if (this.handle) clearTimeout(this.handle);
  this.handle = undefined;
}

async function readStream(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  signal: vscode.CancellationToken,
  state: StreamState,
  emit: (e: RunnerEvent) => void,
  requestId: string,
  idle: IdleTimer,
): Promise<void> {
  const decoder = new TextDecoder();
  let buffer = '';

  idle.reset();
  while (!signal.isCancellationRequested && !state.done) {
    const { done, value } = await reader.read();
    if (done) break;
    idle.reset();
    buffer += decoder.decode(value, { stream: true });

    let idx: number;
    while ((idx = buffer.indexOf('\n\n')) !== -1) {
      const block = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 2);
      const frame = parseSSEBlock(block);
      if (frame) handleFrame(frame, state, emit, requestId);
      if (state.done) return;
    }
  }
}

export async function runViaSancio(req: SancioRunRequest): Promise<void> {
  const requestId = genRequestId();

  // Pre-flight: cancelled before we even start → emit one error + done
  // and return (Opus review HIGH: pre-cancelled signal must short-circuit).
  if (req.signal.isCancellationRequested) {
    log.info('sancio:precancelled', { requestId });
    req.emit({ type: 'error', message: 'request cancelled before start' });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  // Host allow-list (SSRF guard).
  try {
    assertSancioEndpointAllowed(req.sancioEndpoint);
  } catch (e: unknown) {
    const msg =
      e instanceof EndpointNotAllowedError ? e.message : String(e);
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
    return;
  }

  // 1. Append user turn to local session (durable record independent of Sancio).
  await req.store.append(req.sessionId, {
    role: 'user',
    content: req.userMessage,
    ts: Date.now(),
  });

  const url = `${normalizeEndpoint(req.sancioEndpoint)}/agent/run`;
  const abort = new AbortController();
  const cancelSub = req.signal.onCancellationRequested(() => {
    log.info('sancio:cancel', { requestId });
    abort.abort();
  });
  const state: StreamState = { assistantText: '', done: false, doneMode: 'primary' };

  let reader: ReadableStreamDefaultReader<Uint8Array> | undefined;
  const idle = new IdleTimer(IDLE_TIMEOUT_MS, () => {
    log.error('sancio:timeout:idle', { requestId, idleMs: IDLE_TIMEOUT_MS });
    abort.abort();
  });

  // Connection timeout — separate from idle.
  const connectTimer = setTimeout(() => {
    if (!reader) {
      log.error('sancio:timeout:connect', { requestId, ms: CONNECT_TIMEOUT_MS });
      abort.abort();
    }
  }, CONNECT_TIMEOUT_MS);

  try {
    log.info('sancio:request:start', { requestId, url, stack: req.stack, model: req.model });
    const resp = await fetch(url, {
      method: 'POST',
      headers: buildHeaders(requestId),
      body: JSON.stringify(buildRequestBody(req)),
      signal: abort.signal,
    });
    clearTimeout(connectTimer);

    if (!resp.ok) {
      const text = await resp.text().catch(() => '');
      const serverRequestId = resp.headers.get('x-request-id') || '';
      log.error('sancio:http:non-2xx', {
        requestId,
        serverRequestId,
        status: resp.status,
        preview: text.slice(0, 200),
      });
      req.emit({
        type: 'error',
        message: `Sancio HTTP ${resp.status}: ${text.slice(0, 300)}`,
      });
      req.emit({ type: 'done', mode: 'primary' });
      return;
    }
    if (!resp.body) {
      log.error('sancio:http:no-body', { requestId });
      req.emit({ type: 'error', message: 'Sancio: empty response body' });
      req.emit({ type: 'done', mode: 'primary' });
      return;
    }

    reader = resp.body.getReader();
    await readStream(reader, req.signal, state, req.emit, requestId, idle);

    await persistAssistant(req.store, req.sessionId, state.assistantText);
    log.info('sancio:request:end', {
      requestId,
      chars: state.assistantText.length,
      mode: state.doneMode,
    });
    req.emit({ type: 'done', mode: state.doneMode });
  } catch (e: any) {
    const aborted = abort.signal.aborted;
    const msg = aborted
      ? req.signal.isCancellationRequested
        ? 'cancelled'
        : 'connection/idle timeout'
      : e?.message || String(e);
    log.error('sancio:request:fail', { requestId, aborted, detail: msg });
    req.emit({ type: 'error', message: msg });
    req.emit({ type: 'done', mode: 'primary' });
  } finally {
    clearTimeout(connectTimer);
    idle.dispose();
    cancelSub.dispose();
    if (reader) {
      try {
        reader.releaseLock();
      } catch {
        /* ignore */
      }
    }
  }
}

