export function enabledToolIdsForStack(stack: string): ToolId[] {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const defaults = STACK_DEFAULTS[stack] || FALLBACK_DEFAULT;
  const byStack =
    cfg.get<Record<string, Record<string, boolean>>>('tools.byStack') || {};
  const override = byStack[stack] || {};
  return ALL_TOOL_IDS.filter((id) => {
    if (typeof override[id] === 'boolean') return override[id];
    return defaults.includes(id);
  });
