}

export function tavilyApiKey(): string {
  return (
    vscode.workspace.getConfiguration('aiKing').get<string>('webSearch.tavilyApiKey') || ''
  ).trim();
}

export interface WebSearchResult {
  title: string;
  url: string;
  snippet: string;
}

export interface WebSearchOptions {
  maxResults?: number;
  /** BYOK：使用者自己的 Tavily 金鑰（aiKing.webSearch.tavilyApiKey）。空＝走免金鑰 fallback。 */
  tavilyApiKey?: string;
  signal?: AbortSignal;
}

function capOutput(s: string): string {
  if (s.length <= OUTPUT_CHAR_CAP) return s;
  return (
    s.slice(0, OUTPUT_CHAR_CAP) +
    `\n\n…（輸出已截斷至 ${OUTPUT_CHAR_CAP} 字元；如需更完整內容，請用更精確的查詢或對特定 URL 用 web_fetch）`
  );
}

function withTimeout(signal?: AbortSignal): { signal: AbortSignal; done: () => void } {
  const ac = new AbortController();
  const timer = setTimeout(() => ac.abort(), REQUEST_TIMEOUT_MS);
  const onAbort = () => ac.abort();
  if (signal) {
    if (signal.aborted) ac.abort();
    else signal.addEventListener('abort', onAbort, { once: true });
  }
  return {
    signal: ac.signal,
    done: () => {
      clearTimeout(timer);
      if (signal) signal.removeEventListener('abort', onAbort);
    },
  };
}

async function searchTavily(
  query: string,
  apiKey: string,
  maxResults: number,
  signal?: AbortSignal,
): Promise<WebSearchResult[]> {
  const { signal: s, done } = withTimeout(signal);
  try {
    const resp = await fetch('https://api.tavily.com/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: apiKey,
        query,
        max_results: maxResults,
        search_depth: 'basic',
      }),
      signal: s,
    });
    if (!resp.ok) {
      const t = await resp.text().catch(() => '');
      throw new Error(`Tavily HTTP ${resp.status}${t ? ': ' + t.slice(0, 200) : ''}`);
    }
    const json = (await resp.json()) as { results?: Array<{ title?: string; url?: string; content?: string }> };
    return (json.results || []).slice(0, maxResults).map((r) => ({
      title: (r.title || '').trim(),
      url: (r.url || '').trim(),
      snippet: (r.content || '').trim(),
    }));
  } finally {
    done();
  }
}

async function searchDuckDuckGo(
  query: string,
  maxResults: number,
  signal?: AbortSignal,
): Promise<WebSearchResult[]> {
  const { signal: s, done } = withTimeout(signal);
  try {
    const resp = await fetch('https://html.duckduckgo.com/html/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        // 帶個常見 UA，降低被直接擋的機率（DDG html 端點對空 UA 較敏感）。
        'User-Agent':
          'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
      },
      body: `q=${encodeURIComponent(query)}`,
      signal: s,
    });
    if (!resp.ok) {
      throw new Error(`DuckDuckGo HTTP ${resp.status}（免金鑰來源可能被限速；建議在設定填 Tavily 金鑰）`);
    }
    const html = await resp.text();
    const results: WebSearchResult[] = [];
    // 每個結果：<a class="result__a" href="//duckduckgo.com/l/?uddg=<真URL>&...">標題</a>
    const linkRe = /<a[^>]*class="result__a"[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/g;
    const snipRe = /<a[^>]*class="result__snippet"[^>]*>([\s\S]*?)<\/a>/g;
    const snippets: string[] = [];
    let sm: RegExpExecArray | null;
    while ((sm = snipRe.exec(html)) !== null) snippets.push(stripHtml(sm[1]));
    let m: RegExpExecArray | null;
    let i = 0;
    while ((m = linkRe.exec(html)) !== null && results.length < maxResults) {
      let href = m[1];
      // DDG 用 redirect 包真 URL 在 uddg 參數裡。
      const uddg = /[?&]uddg=([^&]+)/.exec(href);
      if (uddg) {
        try { href = decodeURIComponent(uddg[1]); } catch { /* keep raw */ }
      }
      if (href.startsWith('//')) href = 'https:' + href;
      const title = stripHtml(m[2]);
      if (title && href) {
        results.push({ title, url: href, snippet: snippets[i] || '' });
      }
      i++;
    }
    return results;
  } finally {
    done();
  }
}

export async function searchWeb(query: string, opts: WebSearchOptions = {}): Promise<WebSearchResult[]> {
  const maxResults = opts.maxResults && opts.maxResults > 0 ? Math.min(opts.maxResults, 10) : DEFAULT_MAX_RESULTS;
  const key = (opts.tavilyApiKey || '').trim();
  if (key) {
    try {
      log.info('clean:web:search', { engine: 'tavily', q: query.slice(0, 80) });
      return await searchTavily(query, key, maxResults, opts.signal);
    } catch (e: unknown) {
      // BYOK 失敗就退免金鑰，別整個失敗（金鑰過期/額度用完仍能搜）。
      log.warn('clean:web:search:tavily-fail-fallback', { err: String(e) });
    }
  }
  log.info('clean:web:search', { engine: 'duckduckgo', q: query.slice(0, 80) });
  return searchDuckDuckGo(query, maxResults, opts.signal);
}

export async function searchWebFormatted(query: string, opts: WebSearchOptions = {}): Promise<string> {
  const results = await searchWeb(query, opts);
  if (results.length === 0) {
    return `（「${query}」沒有搜到結果。可能是查詢太冷門，或免金鑰來源暫時被限速。）`;
  }
  const lines = results.map((r, i) => {
    const snip = r.snippet ? `\n   ${r.snippet}` : '';
    return `${i + 1}. ${r.title}\n   ${r.url}${snip}`;
  });
  return capOutput(
    `針對「${query}」的網路搜尋結果（共 ${results.length} 筆，請據此回答並標註引用的來源 URL）：\n\n` +
      lines.join('\n\n'),
  );
}

export async function fetchWebPage(url: string, signal?: AbortSignal): Promise<string> {
  const target = url.trim();
  if (!/^https?:\/\//i.test(target)) {
    return `錯誤：web_fetch 需要完整的 http(s) URL，收到「${url}」。`;
  }
  const { signal: s, done } = withTimeout(signal);
  try {
    log.info('clean:web:fetch', { url: target.slice(0, 120) });
    // r.jina.ai/<url> 回乾淨 markdown；免金鑰 20 RPM。
    const resp = await fetch(`https://r.jina.ai/${target}`, {
      headers: { Accept: 'text/plain', 'X-Return-Format': 'markdown' },
      signal: s,
    });
    if (!resp.ok) {
      return `錯誤：抓取「${target}」失敗（HTTP ${resp.status}）。`;
    }
    const text = await resp.text();
    return capOutput(text.trim() || `（「${target}」沒有可讀內容。）`);
  } catch (e: unknown) {
    return `錯誤：抓取「${target}」時發生例外：${String(e)}`;
  } finally {
    done();
  }
}

function cfg() {
  return vscode.workspace.getConfiguration('aiKing');
}

export function codemapEnabled(): boolean {
  return cfg().get<boolean>('codemap.enabled', false) === true;
}

export function codemapPort(): number {
  const p = cfg().get<number>('codemap.port', DEFAULT_PORT);
  return typeof p === 'number' && p > 0 && p < 65536 ? Math.floor(p) : DEFAULT_PORT;
}

export function codemapPkgRoot(): string {
  const c = cfg().get<string>('codemap.pkgRoot');
  return c && c.trim() ? c.trim() : DEFAULT_PKG_ROOT;
}

export function codemapPython(): string {
  const c = cfg().get<string>('codemap.pythonPath');
  if (c && c.trim()) return c.trim();
  if (process.platform === 'win32') {
    const guess = 'C:\\Python311\\python.exe';
    try { if (fs.existsSync(guess)) return guess; } catch { /* fall through */ }
    return 'python';
  }
  return 'python3';
}

export function codemapBaseUrl(): string {
  return `http://${HOST}:${codemapPort()}`;
}

export function codemapHealthy(): Promise<boolean> {
  return new Promise((resolve) => {
    const req = http.get(
      { hostname: HOST, port: codemapPort(), path: '/health', timeout: 2000 },
      (r) => {
        if (r.statusCode !== 200) { r.resume(); resolve(false); return; }
        let d = '';
        r.on('data', (c) => { d += c; });
        r.on('end', () => {
          try {
            const j = JSON.parse(d) as { service?: unknown };
            resolve(!!j && (j.service === 'codemap' || j.service === 'tracemap'));
          } catch { resolve(false); }
        });
      },
    );
    req.on('error', () => resolve(false));
    req.on('timeout', () => { req.destroy(); resolve(false); });
  });
}

export function codemapPackagePresent(): boolean {
  try {
    return fs.existsSync(path.join(codemapPkgRoot(), 'codemap', 'daemon.py'));
  } catch {
    return false;
  }
}

export async function ensureCodemapRunning(): Promise<boolean> {
  if (!codemapEnabled()) return false;
  if (spawning) return spawning;
  spawning = (async () => {
    try {
      if (await codemapHealthy()) return true;
      if (!codemapPackagePresent()) return false;
      const root = codemapPkgRoot();
      const py = codemapPython();
      // `ensure` 子命令：冪等＋自己 DETACHED 拉起常駐 daemon，跑完印 JSON 退出。
      const ensured = await new Promise<boolean>((resolve) => {
        let done = false;
        let timer: ReturnType<typeof setTimeout> | undefined;
        const finish = (v: boolean) => {
          if (done) return;
          done = true;
          if (timer) clearTimeout(timer); // 正常退出後不留懸掛兜底計時器
          resolve(v);
        };
        timer = setTimeout(() => finish(true), 12000); // 兜底：ensure 卡住也不阻死本函數
        try {
          // 只帶 CODEMAP_PORT；daemon 靠 cwd（python -m 把 cwd 進 sys.path）定位 codemap
          // 套件，不讀 CODEMAP_PKG_ROOT（那是 client.py 用的、daemon 端是 no-op）。launcher
          // 是短命 fire-and-forget（真 daemon 由它 DETACHED 拉起獨立存活），detached+unref
          // 讓它不綁 extension host（對齊 openUnified 範式、VS Code 關閉時不掛著它）。
          const child = cp.spawn(py, ['-m', 'codemap.daemon', 'ensure'], {
            cwd: root,
            env: { ...process.env, CODEMAP_PORT: String(codemapPort()) },
            stdio: 'ignore',
            windowsHide: true,
            detached: true,
          });
          child.unref();
          child.on('exit', () => finish(true));
          child.on('error', () => finish(false)); // python 找不到（ENOENT）走這條
        } catch {
          finish(false);
        }
      });
      if (!ensured) return false;
      // ensure 退出 ≠ daemon 必就緒（detached 拉起有延遲），再輪詢 /health 確認 brand。
      for (let i = 0; i < 12; i++) {
        if (await codemapHealthy()) return true;
        await new Promise((r) => setTimeout(r, 400));
      }
      return false;
    } finally {
      spawning = null;
    }
  })();
  return spawning;
}

function buildIframeHtml(port: number): string {
  const host = '127.0.0.1';
  // 防呆：未來設定改動也不能把非本機 host 偷渡進 iframe。
  if (!ALLOWED_HOSTS.has(host)) {
    return '<!DOCTYPE html><html><body><p>blocked non-loopback host</p></body></html>';
  }
  const url = `http://${host}:${port}/`;
  return `<!DOCTYPE html>
<html lang="zh-TW">
  <head>
    <meta charset="UTF-8" />
    <title>代碼地圖 · Tracemap</title>
    <style>
      html, body { height: 100%; margin: 0; padding: 0; background: var(--vscode-editor-background); }
      iframe { border: 0; width: 100%; height: 100vh; }
    </style>
  </head>
  <body>
    <iframe src="${url}" sandbox="allow-scripts allow-forms allow-same-origin"></iframe>
  </body>
</html>`;
}

export async function openCodemapCmd(): Promise<void> {
  if (!codemapEnabled()) {
    const YES = '啟用並開啟';
    const pick = await vscode.window.showInformationMessage(
      '代碼地圖（Tracemap／碼圖）預設關閉。啟用後會在本機拉起一個常駐的代碼地圖服務（127.0.0.1，全代理共用、可離線）。要啟用並開啟嗎？',
      YES,
    );
    if (pick !== YES) return;
    await vscode.workspace
      .getConfiguration('aiKing')
      .update('codemap.enabled', true, vscode.ConfigurationTarget.Global);
  }

  const ok = await ensureCodemapRunning();
  if (!ok) {
    // ensureCodemapRunning 是純邏輯不彈 UI；由這裡（使用者主動觸發點）給精準提示——
    // 分流「package 缺」vs「package 在但 daemon 起不來（多半 Python 缺依賴）」。
    if (!codemapPackagePresent()) {
      void vscode.window.showWarningMessage(
        `AI King 代碼地圖：在 ${codemapPkgRoot()} 找不到 codemap/daemon.py。` +
          '請把設定 aiKing.codemap.pkgRoot 指向你的 Tracemap package 資料夾（內含 codemap/）。',
      );
    } else {
      void vscode.window.showWarningMessage(
        `AI King 代碼地圖：daemon 在 127.0.0.1:${codemapPort()} 起不來。` +
          `請確認 aiKing.codemap.pythonPath（目前：${codemapPython() || '自動'}）指向裝了 ` +
          'tree-sitter / jedi / tree-sitter-language-pack 的 Python。',
      );
    }
    return;
  }

  const port = codemapPort();
  if (panel) {
    panel.reveal(vscode.ViewColumn.Beside);
    panel.webview.html = buildIframeHtml(port);
    return;
  }
  panel = vscode.window.createWebviewPanel(
    'aiKing.codemap',
    '代碼地圖 · Tracemap',
    vscode.ViewColumn.Beside,
    { enableScripts: true, retainContextWhenHidden: true },
  );
  panel.webview.html = buildIframeHtml(port);
  panel.onDidDispose(() => { panel = undefined; });
}

