async function discoverCommandsInDir(
  dir: vscode.Uri,
  displayRoot: string,
): Promise<SlashCommand[]> {
  let entries: [string, vscode.FileType][];
  try {
    entries = await vscode.workspace.fs.readDirectory(dir);
  } catch {
    return [];
  }
  const out: SlashCommand[] = [];
  for (const [name, type] of entries) {
    if (type !== vscode.FileType.File) continue;
    if (!name.toLowerCase().endsWith('.md')) continue;
    const id = name.slice(0, -3);
    const filePath = vscode.Uri.joinPath(dir, name).fsPath;
    out.push({
      // Namespace by root so `.claude/foo.md` and `.ai-king/foo.md` don't collide.
      id: `cmd:${displayRoot}:${id}`,
      label: `/${id}`,
      section: 'command',
      description: `自訂指令（來自 ${displayRoot}/${name}）`,
      filePath,
    });
  }
  return out;
}

async function discoverCommands(workspaceRoot: vscode.Uri): Promise<SlashCommand[]> {
  // 0.14.0: search both CC-convention and extension-native dirs.
  const [a, b] = await Promise.all([
    discoverCommandsInDir(
      vscode.Uri.joinPath(workspaceRoot, '.claude', 'commands'),
      '.claude/commands',
    ),
    discoverCommandsInDir(
      vscode.Uri.joinPath(workspaceRoot, '.ai-king', 'commands'),
      '.ai-king/commands',
    ),
  ]);
  // De-dup by label (same /name in both dirs → prefer .claude/ — matches CC convention).
  const seen = new Set<string>();
  const out: SlashCommand[] = [];
  for (const c of [...a, ...b]) {
    if (seen.has(c.label)) continue;
    seen.add(c.label);
    out.push(c);
  }
  return out;
}

async function discoverSkills(workspaceRoot: vscode.Uri): Promise<SlashCommand[]> {
  const dir = vscode.Uri.joinPath(workspaceRoot, '.claude', 'skills');
  let entries: [string, vscode.FileType][];
  try {
    entries = await vscode.workspace.fs.readDirectory(dir);
  } catch {
    return [];
  }
  const out: SlashCommand[] = [];
  for (const [name, type] of entries) {
    if (type !== vscode.FileType.Directory) continue;
    const skillFile = vscode.Uri.joinPath(dir, name, 'SKILL.md');
    try {
      await vscode.workspace.fs.stat(skillFile);
    } catch {
      continue;
    }
    out.push({
      id: `skill:${name}`,
      label: `/${name}`,
      section: 'skill',
      description: `Skill（來自 .claude/skills/${name}/SKILL.md）`,
      filePath: skillFile.fsPath,
    });
  }
  return out;
}

export async function getSlashCatalog(): Promise<SlashCommand[]> {
  const out: SlashCommand[] = [...BUILTIN_COMMANDS];
  const folders = vscode.workspace.workspaceFolders || [];
  for (const f of folders) {
    const [cmds, skills] = await Promise.all([
      discoverCommands(f.uri),
      discoverSkills(f.uri),
    ]);
    out.push(...cmds);
    out.push(...skills);
  }
  return out;
}

export async function loadSlashBody(filePath: string): Promise<string> {
  const uri = vscode.Uri.file(filePath);
  const buf = await vscode.workspace.fs.readFile(uri);
  return new TextDecoder().decode(buf);
}

function registerPickerCommands(ctx: vscode.ExtensionContext, store: SessionStore): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.mode.pick', async () => {
      const items = CHAT_MODES.map((m) => ({
        label: `$(${MODE_CONFIGS[m].icon}) ${MODE_CONFIGS[m].label}`,
        description: MODE_CONFIGS[m].description,
        mode: m,
      }));
      const pick = await showQuickPickEsc(items, {
        placeHolder: '選擇 chat mode (Pick a mode)',
      });
      if (!pick) return;
      await setLastMode(ctx, pick.mode);
      vscode.window.showInformationMessage(`AI King: mode → ${pick.mode}`);
    }),

    vscode.commands.registerCommand('aiKing.provider.pick', async () => {
      const providers = loadProviders();
      if (providers.length === 0) {
        vscode.window.showWarningMessage('AI King: 尚未設定任何 provider');
        return;
      }
      const items = providers.map((p) => ({
        label: p.name,
        description: p.kind,
        detail: `${p.endpoint} · ${p.models.length} models`,
        providerId: p.id,
      }));
      const pick = await showQuickPickEsc(items, {
        placeHolder: '選擇 provider (Pick a provider)',
        matchOnDescription: true,
        matchOnDetail: true,
      });
      if (!pick) return;
      await setActiveProviderId(ctx, pick.providerId);
      const prov = providers.find((p) => p.id === pick.providerId);
      if (prov && prov.models.length > 0) {
        await setActiveModel(ctx, prov.models[0]);
      }
      vscode.window.showInformationMessage(`AI King: provider → ${pick.label}`);
    }),

    vscode.commands.registerCommand('aiKing.model.pick', async () => {
      const providers = loadProviders();
      const items: vscode.QuickPickItem[] = [];
      for (const p of providers) {
        for (const m of p.models) {
          items.push({
            label: m,
            description: p.name,
          });
        }
      }
      if (items.length === 0) {
        vscode.window.showWarningMessage('AI King: 沒有 model 清單');
        return;
      }
      const pick = await showQuickPickEsc(items, {
        placeHolder: '選擇 model (Pick a model)',
        matchOnDescription: true,
      });
      if (!pick) return;
      await setActiveModel(ctx, pick.label);
      vscode.window.showInformationMessage(`AI King: model → ${pick.label}`);
    }),

    // Activate session (set as active without opening panel) — used by older callers.
    vscode.commands.registerCommand('aiKing.sessions.activate', async (id: string) => {
      if (typeof id !== 'string') return;
      await setActiveSessionId(ctx, id);
    }),

    // Refresh stub (kept for command palette compatibility).
    vscode.commands.registerCommand('aiKing.sessions.refresh', () => {
      // Home view auto-refreshes via store.onDidChange.
    }),
  );

  void store;
}

function registerDigitalHumanTokenCommands(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.setDigitalHumanToken', async () => {
      const existing = await ctx.secrets.get(DIGITAL_HUMAN_TOKEN_SECRET);
      const token = await showInputBoxEsc({
        title: 'AI King: Digital Human Bearer Token',
        prompt: 'Paste the PSYCHEFORGE / psyche-engine bearer token (stored in SecretStorage)',
        password: true,
        ignoreFocusOut: true,
        placeHolder: existing ? '(a token is already set — leave blank to keep)' : '',
