}

function registerPermissionCommands(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.permissions.clearSession', () => {
      clearSessionPermissions();
      vscode.window.showInformationMessage(
        'AI King: session permissions cleared.',
      );
    }),
    vscode.commands.registerCommand(
      'aiKing.permissions.clearTool',
      async () => {
        const n = await clearToolPermissions(ctx);
        vscode.window.showInformationMessage(
          `AI King: cleared ${n} persisted tool permission${n === 1 ? '' : 's'}.`,
        );
      },
    ),
    vscode.commands.registerCommand(
      'aiKing.permissions.toggleAutoApprove',
      async () => {
        const cfg = vscode.workspace.getConfiguration('aiKing');
        const current = cfg.get<boolean>('autoApproveAll') === true;
        const next = !current;
        await cfg.update(
          'autoApproveAll',
          next,
          vscode.ConfigurationTarget.Global,
        );
        // Best-effort cloud sync so the flag travels with the account.
        try {
          await pushConfigToRemote(ctx);
        } catch (e: any) {
          // Not signed in or network hiccup — local setting still flipped.
          console.warn(
            '[ai-king] autoApproveAll cloud push failed',
            e?.message || e,
          );
        }
        vscode.window.showInformationMessage(
          `AI King: autoApproveAll ${next ? 'ON' : 'OFF'}${next ? ' — tool calls will no longer ask' : ''}.`,
        );
      },
    ),
    // 0.19.0: /allowlist → suggest which granted tools to persist. Mirrors
    // CC /less-permission-prompts. Multi-select QuickPick → persistTools().
    vscode.commands.registerCommand(
      'aiKing.permissions.suggestAllowlist',
      async () => {
        const suggestions = collectAllowlistSuggestions(ctx);
        if (suggestions.length === 0) {
          vscode.window.showInformationMessage(
            'AI King: 沒有可建議的工具 — 本 session 尚未授權任何工具 (no tools granted yet this session).',
          );
          return;
        }
        type Item = vscode.QuickPickItem & { tool: string };
        const items: Item[] = suggestions.map((s) => {
          const descMap = {
            'session-granted': 'Session 授權 → 建議永久加入 (promote to persist)',
            'custom-name': 'Custom 名稱 → 建議檢視後再永久加入 (review before persist)',
            'already-persisted': '已永久加入 (already persisted)',
          } as const;
          return {
            label: `${s.persisted ? '$(shield)' : '$(check)'} ${s.tool}`,
            description: descMap[s.reason],
            tool: s.tool,
            picked: s.reason === 'session-granted',
          };
        });
        const picked = await showQuickPickEsc(items, {
          title: 'AI King · 建議 Allowlist (Suggest Permission Allowlist)',
          placeHolder:
            '勾選要永久加入 allowlist 的工具 (check tools to persist)',
          canPickMany: true,
          ignoreFocusOut: true,
        });
        if (!picked || picked.length === 0) return;
        const toPersist = picked
          .filter((p) => {
            const src = suggestions.find((s) => s.tool === p.tool);
            return src && !src.persisted;
          })
          .map((p) => p.tool);
        if (toPersist.length === 0) {
          vscode.window.showInformationMessage(
            'AI King: 勾選的工具都已是永久 allowlist，無變動 (all selected already persisted).',
          );
          return;
        }
        const n = await persistTools(ctx, toPersist);
        vscode.window.showInformationMessage(
          `AI King: ${n} 個工具已加入永久 allowlist (persisted ${n} tool${n === 1 ? '' : 's'}) — ${toPersist.join(', ')}.`,
        );
      },
    ),
    // 0.19.0: /focus → toggle aiKing.viewMode between default and focus.
    //         (Legacy aiKing.focusMode boolean kept in sync for backward-compat.)
    vscode.commands.registerCommand('aiKing.focus.toggle', async () => {
      const cfg = vscode.workspace.getConfiguration('aiKing');
      const current = (cfg.get<string>('viewMode') as ViewMode) || 'default';
      const next: ViewMode = current === 'focus' ? 'default' : 'focus';
      await cfg.update('viewMode', next, vscode.ConfigurationTarget.Global);
      await cfg.update(
        'focusMode',
        next === 'focus',
        vscode.ConfigurationTarget.Global,
      );
      vscode.window.showInformationMessage(
        `AI King: view mode → ${next}${next === 'focus' ? ' (hide verbose)' : ''}.`,
      );
    }),
  );
}

function registerModeAndViewCommands(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    // Shift+Tab → cycle chat → edits → plan → auto (respecting disableAutoMode
    // org policy). 1.7.0: dontAsk folded into Auto.
    vscode.commands.registerCommand('aiKing.mode.cycle', async () => {
      const cfg = vscode.workspace.getConfiguration('aiKing');
      const disableAuto = cfg.get<string>('disableAutoMode') === 'disable';
      // [A8] fallback 對齊 DEFAULT_MODE（'auto'）：全新 user 從 auto 起跳 cycle。
      const current = ((cfg.get<string>('lastMode') as ChatMode) ||
        (cfg.get<string>('defaultMode') as ChatMode) ||
        DEFAULT_MODE) as ChatMode;
      let candidate: ChatMode = isChatMode(current) ? current : DEFAULT_MODE;
      // Step forward, skipping policy-disabled modes — capped at one full
      // cycle so a mis-configured policy can't deadloop.
      for (let i = 0; i < MODE_CYCLE.length; i++) {
        candidate = nextMode(candidate);
        if (candidate === 'auto' && disableAuto) continue;
        break;
      }
      // [權限同源修 2026-06-22 紅藍review] 走 setLastMode 同寫 workspaceState（gate 讀的源頭）+
      //   config 鏡射，否則 Shift+Tab 切 mode 對 gate 無效（gate 改讀 workspaceState）。
      await setLastMode(ctx, candidate);
      const cfgModeEntry = MODE_CONFIGS[candidate];
      vscode.window.showInformationMessage(
        `AI King: mode → ${cfgModeEntry.label} (${cfgModeEntry.dropdownLabel})`,
      );
    }),

    // Cycle viewMode default → focus → verbose → default
    vscode.commands.registerCommand('aiKing.view.cycle', async () => {
      const cfg = vscode.workspace.getConfiguration('aiKing');
      const current = (cfg.get<string>('viewMode') as ViewMode) || 'default';
      const idx = VIEW_MODES.indexOf(isViewMode(current) ? current : 'default');
      const next = VIEW_MODES[(idx + 1) % VIEW_MODES.length];
      await cfg.update('viewMode', next, vscode.ConfigurationTarget.Global);
      // Keep legacy boolean in sync so older code paths still respect focus.
      await cfg.update(
        'focusMode',
        next === 'focus',
        vscode.ConfigurationTarget.Global,
      );
      vscode.window.showInformationMessage(`AI King: view → ${next}`);
    }),
  );
}

function registerSessionExtraCommands(
  ctx: vscode.ExtensionContext,
  store: SessionStore,
): void {
  ctx.subscriptions.push(
    // /rewind — drop last N messages. N is chosen via QuickPick.
    vscode.commands.registerCommand('aiKing.session.rewind', async () => {
      const sid = getActiveSessionId(ctx);
      if (!sid) {
        vscode.window.showWarningMessage('AI King: 沒有 active session');
        return;
      }
      const session = await store.load(sid);
      if (!session || session.messages.length === 0) {
        vscode.window.showInformationMessage('AI King: 沒有訊息可 rewind');
        return;
      }
      const items: Array<vscode.QuickPickItem & { n: number }> = [
        { label: '丟掉最後 1 則', n: 1 },
        { label: '丟掉最後 2 則', n: 2 },
        { label: '丟掉最後 5 則', n: 5 },
        { label: '丟掉最後 10 則', n: 10 },
      ].filter((it) => it.n <= session.messages.length);
      const pick = await showQuickPickEsc(items, {
        title: `AI King · Rewind (${session.messages.length} 則訊息)`,
        placeHolder: '選擇 rewind 多少則',
      });
      if (!pick) return;
      const target = Math.max(0, session.messages.length - pick.n);
      await store.truncate(sid, target);
      vscode.window.showInformationMessage(
        `AI King: rewound ${pick.n} messages (${session.messages.length} → ${target}).`,
      );
    }),

    // /checkpoint — snapshot session json into globalStorage/checkpoints/
    vscode.commands.registerCommand('aiKing.session.checkpoint', async () => {
      const sid = getActiveSessionId(ctx);
      if (!sid) {
        vscode.window.showWarningMessage('AI King: 沒有 active session');
        return;
      }
      const session = await store.load(sid);
      if (!session) return;
      const dir = vscode.Uri.joinPath(ctx.globalStorageUri, 'checkpoints');
      try {
        await vscode.workspace.fs.createDirectory(dir);
      } catch {
        /* exists */
      }
      const stamp = new Date()
        .toISOString()
        .replace(/[:.]/g, '-')
        .slice(0, 19);
      const file = vscode.Uri.joinPath(dir, `${sid}_${stamp}.json`);
      await vscode.workspace.fs.writeFile(
        file,
        new TextEncoder().encode(JSON.stringify(session, null, 2)),
      );
      vscode.window.showInformationMessage(
        `AI King: checkpoint saved → ${file.fsPath}`,
      );
    }),

    // /stats — token / message / tool counts (local, no LLM call)
    vscode.commands.registerCommand('aiKing.session.stats', async () => {
      const sid = getActiveSessionId(ctx);
      if (!sid) {
        vscode.window.showWarningMessage('AI King: 沒有 active session');
        return;
      }
      const session = await store.load(sid);
      if (!session) return;
      const u = session.messages.filter((m) => m.role === 'user').length;
      const a = session.messages.filter((m) => m.role === 'assistant').length;
      const t = session.messages.filter((m) => m.role === 'tool').length;
      // Rough token estimate: 1 token ≈ 4 chars (English / mixed CJK).
      const chars = session.messages.reduce(
        (acc, m) => acc + (m.content || '').length,
        0,
      );
      const tokensEst = Math.round(chars / 4);
      vscode.window.showInformationMessage(
        `AI King · ${session.title}: ${session.messages.length} msgs (user ${u} · assistant ${a} · tool ${t}) · ~${tokensEst} tokens · model ${session.model}`,
      );
    }),

    // /export — dump transcript as markdown via native save dialog
    vscode.commands.registerCommand('aiKing.session.export', async () => {
      const sid = getActiveSessionId(ctx);
      if (!sid) {
        vscode.window.showWarningMessage('AI King: 沒有 active session');
        return;
      }
      const session = await store.load(sid);
      if (!session) return;
      const defaultName = `${session.title.replace(/[^a-zA-Z0-9_\-]+/g, '_')}.md`;
      const target = await vscode.window.showSaveDialog({
        defaultUri: vscode.Uri.file(defaultName),
        filters: { Markdown: ['md'] },
        saveLabel: '匯出 (Export)',
        title: 'AI King · Export Session',
      });
      if (!target) return;
      const md = [
        `# ${session.title}`,
        ``,
        `- Created: ${new Date(session.createdAt).toLocaleString()}`,
        `- Updated: ${new Date(session.updatedAt).toLocaleString()}`,
        `- Model: \`${session.model}\` · Mode: \`${session.mode}\` · Stack: \`${session.stack}\``,
        ``,
        `---`,
        ``,
        ...session.messages.map(
          (m) =>
            `### ${m.role}\n\n${m.content}\n`,
        ),
      ].join('\n');
      await vscode.workspace.fs.writeFile(
        target,
        new TextEncoder().encode(md),
      );
      vscode.window.showInformationMessage(
        `AI King: exported → ${target.fsPath}`,
      );
    }),

    // /branch — duplicate session from current point into a new one
    vscode.commands.registerCommand('aiKing.session.branch', async () => {
      const sid = getActiveSessionId(ctx);
      if (!sid) {
        vscode.window.showWarningMessage('AI King: 沒有 active session');
        return;
      }
      const session = await store.load(sid);
      if (!session) return;
      const title = await showInputBoxEsc({
        prompt: 'Branch session title',
        value: `${session.title} (branch)`,
      });
      if (!title) return;
      const fresh = await store.create(
        title,
        session.model,
        session.stack,
        session.mode,
        session.providerId,
      );
      for (const m of session.messages) {
        await store.append(fresh.id, m);
      }
      await setActiveSessionId(ctx, fresh.id);
      vscode.window.showInformationMessage(
        `AI King: branched → "${title}" (${session.messages.length} msgs copied)`,
      );
    }),
  );
}

