export function activate(ctx: vscode.ExtensionContext): void {
  registerKeyCommands(ctx); // legacy aliases (deprecated wrappers)

  const store = new SessionStore(ctx);

  // [1.14.0 帳號線 P1a] 啟動鏈（單一有序 async）：先把舊扁平 globalStorage/sessions 遷入
  // ~/.aiking/profiles/_guest，再依「上次登入的 accountId」(SecretStorage) 決定 profile 命名
  // 空間，最後才 init→prune。三者必須早於任何 list/load/prune，否則 prune 會對錯命名空間動作、
  // 或讀到空清單。autoLogin 之後在下方 startup IIFE 再校正一次 namespace。
  //
  // [1.14.0 對抗審查 critical#2] 存成具名 Promise（storeReady）讓 WebviewPanelSerializer 的
  // deserializeWebviewPanel 在 store.load 前先 await 它——否則登入使用者的對話檔在 <accountId>
  // profile，serializer 卻可能在 setNamespace 切到帳號前先讀 _guest → 找不到 → dispose 把使用者
  // 上次開著的對話 tab 靜默關掉（reload race）。內含 try/catch、無論成敗都會 resolve（不卡死 serializer）。
  const storeReady = (async () => {
    try {
      await migrateGuestData(ctx);
      await store.setNamespace(await resolveActiveNamespace(ctx));
      await store.init(); // 冪等；setNamespace 無變化(預設 _guest)不 init，這裡確保目錄建好
      await migrateToProviders(ctx);
      await importBootstrapKeys(ctx);
      // [1.8.3] auto-prune conversations on startup (count + inactivity; groups
      // exempt). [1.9.0 紅藍稽核 H1+H2] **資料遺失修**：① 傳 keepId=當前 active session，
      // 否則啟動 prune 可能把使用者正要續聊的對話刪掉(race) ② 被刪的對話跳通知。
      // [1.14.0 對抗審查 high] keepId 必須「在當前 namespace 真實存在」才有保護力：active 指標是
      // workspaceState 全域單鍵、不跟 profile 走，跨 namespace 啟動時可能指向別 profile 的 id、
      // 在當前 list 不存在 ⇒ 保護失效、prune 可能誤刪當前 profile 對話。先 load 驗證、對不上就不傳。
      const rawKeep = getActiveSessionId(ctx);
      const keepId = rawKeep && (await store.load(rawKeep)) ? rawKeep : undefined;
      const deleted = await store.pruneConversations(keepId);
      if (deleted.length > 0) {
        void vscode.window.showInformationMessage(
          `AI King：自動清理了 ${deleted.length} 則舊對話（超過數量上限或太久沒更新；可在設定關閉或調整）。`,
        );
      }
    } catch (e) {
      console.warn(`[ai-king] activation init: ${e}`);
    }
  })();

  registerSessionCommands(ctx, store);
  registerStackPickCommand(ctx);
  registerSettingsPanel(ctx);
  registerPickerCommands(ctx, store);
  registerHomeView(ctx, store);
  registerBridgePanel(ctx, store); // [1.14.0 critical#1] 注入共用 namespace-aware store
  ensureBundledSkills(ctx); // ship the ai-king skill with the extension → ~/.claude/skills
  ensureAikingSkillsDir(); // AI King 自己的技能家 ~/.aiking/skills 開機就在（設定放路徑就能用 Skill）
  registerSkillInstall(ctx); // "安裝 Skill" command — 先問哪種 AI，各家正確安裝
  registerNodeCheck(ctx); // [推廣A 2026-06-19] 偵測沒系統 node → 友善引導（內部仍借 VS Code node、不靜默裝）
  ensureBridgeServer(); // in-extension localhost bridge server
  initRelay(ctx);
  // AUTHORITY MODE: the authority server is the single source of truth and the
  // panel connects to it directly — the relay-mirror bridges are no longer
  // auto-started. The relay code stays for transitional compatibility but is
  // dormant unless explicitly invoked.
  // ensureAllRelayBridges();
  initAuthority(ctx); // bundled authority server (single source of truth)
  ctx.subscriptions.push(vscode.commands.registerCommand('aiKing.acpGuide', () => showAcpGuide()));
  ctx.subscriptions.push(vscode.commands.registerCommand('aiKing.acpSetup', () => acpSetupWizard()));
  // [1.24.23] 測試 ACP 連線：選代理 → 擴充自動啟動+交握+測完關掉 → 報「連上/超時/連不上」（user 完全不必碰命令列、不必賭著開對話）。
  ctx.subscriptions.push(vscode.commands.registerCommand('aiKing.acp.test', async () => {
    const id = await pickAcpAgentInteractive();
    if (!id) return;
    const r = await vscode.window.withProgress(
