  ensureAuthorityServer(); // auto-start LOCAL server when authorityUrl is local (小白/群主本機); skip if user set own VPS
  startAuthorityWatchdog(); // 看門狗：開 VS Code 就保活，伺服器中途死掉 30 秒內自動拉回（不必去開 AI King）
  registerAuthorityCommands(ctx); // 伺服器位置切換指令（本機 / 區網 / 自架 VPS）
  startGroupConnections(ctx); // [1.8.0 §10.1] 群組常連：啟動即對所有已知群組背景 SSE 訂閱 + 25s 心跳，不必開面板
  registerChatPanel(ctx, store, storeReady); // [1.14.0 critical#2] serializer await storeReady 再 load
  registerDigitalHumanTokenCommands(ctx);
  // [1.14.0 帳號線 P1a] profile 切換回呼。靜默版＝只切 namespace + reload（啟動/autoLogin
