            await markBound(c, accountId);
            void vscode.window.showInformationMessage(`AI King：已複製 ${r.copied} 則對話到此帳號`);
          } else {
            // 部分失敗 ⇒ 不鎖、保留重試出口（下次主動登入會再問是否綁定以補齊缺的那幾則）；
            // 原訪客資料原封不動（copyProfileSessions 不覆蓋、不刪來源）。
            void vscode.window.showWarningMessage(
