        }
      } else if (pick === '空帳號') {
        await markBound(c, accountId);
      }
      // 取消（Esc）：不鎖、下次主動登入再問。
    }
    await applyNamespaceSilently(c);
  };
  registerAuthCommands(ctx, onAuthChanged);
  registerPermissionCommands(ctx);
  registerModeAndViewCommands(ctx);
  registerSessionExtraCommands(ctx, store);
  registerAutoModeCommands(ctx);
  registerAutoModeStatusBar(ctx);
  // 0.22.0 — silent re-login (if remembered password exists + JWT 24h
  // expired), then refresh status bar + pull remote config.
  // 0.23.0 — optional startup re-import of keys from the md file.
  void (async () => {
    // [1.9.0 紅藍稽核 H3] 這三個 await 原本無 try-catch — 任一網路/認證/同步錯誤
    // → unhandled rejection → 擴充 host 崩潰。比照下方 importKeysFromMd 包起來。
    try {
      await autoLoginOnStartup(ctx);
      await refreshStatusBar(ctx);
      // [1.14.0 帳號線 P1a] autoLogin 可能刷新 token（accountId 不變）或失敗清掉 accountId；
      // 校正 profile namespace 到真實狀態（靜默，不彈綁定框＝綁定只在主動登入時問）。
      await applyNamespaceSilently(ctx);
      await trySyncOnStartup(ctx);
    } catch (e: any) {
      console.warn(`[ai-king] startup tasks failed: ${e?.message || e}`);
    }
    const cfg = vscode.workspace.getConfiguration('aiKing');
    if (cfg.get<boolean>('importKeysOnStartup') === true) {
      try {
        const r = await importKeysFromMd(ctx);
        if (r.found.length > 0) {
          console.log(
            `[ai-king] md-import: ${r.found.map((f) => f.provider).join(', ')}`,
          );
        }
      } catch (e: any) {
        console.warn(`[ai-king] md-import startup failed: ${e?.message || e}`);
      }
    }
  })();

  // 0.31.0 — GUI iframe webviews for Concinno / Sancio / unified switcher.
  // Spawns the daemon detached (R#9) if not already up; reads bearer token
  // from disk per-backend (W3); fail-soft if daemon unreachable.
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.gui.openUnified', openUnifiedCmd),
    vscode.commands.registerCommand('aiKing.gui.openConcinno', openConcinnoCmd),
    vscode.commands.registerCommand('aiKing.gui.openSancio', openSancioCmd),
