  );

  // [1.15.0] Tracemap（碼圖）代碼地圖整合（opt-in，aiKing.codemap.enabled 預設 false）。
  // daemon 是全代理共用的本機常駐服務：其 ensure 子命令冪等＋自己 DETACHED 拉起、活過
  // VS Code，所以擴充端只「拉起＋探活＋嵌面板」，deactivate 時「不」殺它（別的代理在用，
  // 不同於 authority 是擴充獨佔本機服務）。enabled=false 時 ensureCodemapRunning 直接 no-op。
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.codemap.open', openCodemapCmd),
  );
  void ensureCodemapRunning(); // 開 VS Code 就把共用 daemon 拉起（僅在 enabled 時，否則零動作）

  // aiKing.chat.open is registered in chat-panel.ts; here we add the
