        /* view may not yet be resolved */
      }
    }),
  );

  const statusBar = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
  statusBar.text = '$(eye) AI King';
  statusBar.tooltip = '開啟 AI King Chat (Open AI King Chat)';
