  ctx.subscriptions.push(statusBar);

  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.checkForUpdates', checkForUpdatesCommand(ctx)),
  );
  // 0.22.0 — one-shot Anthropic key setter. Old `aiKing.setAnthropicKey` is
  // deprecated (nags "use settings panel"); this replacement writes the
  // value straight into SecretStorage under the canonical + legacy slugs
  // so both the `anthropic` and `ai-king-backend` providers light up.
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.setAnthropicKeyQuick', async () => {
      const key = await showInputBoxEsc({
