          return null;
        },
      });
      if (!key) return;
      const trimmed = key.trim();
      await setProviderKey(ctx, 'anthropic', trimmed);
      await setProviderKey(ctx, 'ai-king-backend', trimmed);
      vscode.window.showInformationMessage(
        'AI King: Anthropic key 已儲存 (anthropic + ai-king-backend)',
