          vscode.window.showInformationMessage(
            `AI King: refreshed ${changed.length} builtin provider(s) — ${changed.join(', ')}. Reopen Settings panel to see changes.`,
          );
        }
      } catch (e: any) {
        vscode.window.showErrorMessage(
          `AI King: refresh failed — ${String(e?.message || e)}`,
        );
      }
    }),
    // 0.23.0 — read keys from a fixed-format md file into SecretStorage.
    vscode.commands.registerCommand('aiKing.importKeysFromMd', async () => {
      const defaultPath = resolveMdPath();
      const chosen = await showInputBoxEsc({
        title: 'AI King: Import Keys from MD File',
        prompt: '指定要讀的 md 檔絕對路徑 (Enter = 用預設)',
