      });
      if (chosen === undefined) return;
      try {
        const r = await importKeysFromMd(ctx, chosen.trim() || undefined);
        const foundStr =
          r.found.length === 0
            ? '(none)'
            : r.found
                .map((f) => `${f.provider}=${f.keyPreview}`)
                .join(', ');
        const missingStr =
          r.missing.length === 0 ? '' : ` · missing: ${r.missing.join(', ')}`;
        vscode.window.showInformationMessage(
          `AI King: 從 ${r.filePath} 匯入 — ${foundStr}${missingStr}`,
        );
      } catch (e: any) {
        vscode.window.showErrorMessage(
          `AI King: import 失敗 — ${String(e?.message || e)}`,
        );
      }
    }),
  );
  startUpdateChecker(ctx);

  // Silence unused-import lint for ChatPanel (used transitively via command).
  void ChatPanel;
}

export function deactivate(): void {
