interface GuiBackend {
  name: BackendName;
  port: number;
  tokenPath: string;
  daemonCmd: string[];
  panelTitle: string;
}

function getTokenPath(name: BackendName): string {
  // Switcher token shares the concinno directory because the switcher
  // is a flag-mode of the same `concinno gui` daemon (per W2 amendment).
  const isWin = process.platform === 'win32';
  const baseDir = isWin
    ? path.join(
        process.env.LOCALAPPDATA ?? path.join(os.homedir(), 'AppData', 'Local'),
        name === 'sancio' ? 'sancio' : 'concinno',
      )
    : path.join(os.homedir(), name === 'sancio' ? '.sancio' : '.concinno');
  const file = name === 'switcher' ? 'switcher_token' : 'gui_token';
  return path.join(baseDir, file);
}

function buildBackends(): Record<BackendName, GuiBackend> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const portConcinno = cfg.get<number>('guiPort.concinno') ?? 8400;
  const portSancio = cfg.get<number>('guiPort.sancio') ?? 8401;
  const portSwitcher = cfg.get<number>('guiPort.switcher') ?? 8399;
  return {
    concinno: {
      name: 'concinno',
      port: portConcinno,
      tokenPath: getTokenPath('concinno'),
      daemonCmd: ['concinno', 'gui', '--port', String(portConcinno)],
      panelTitle: 'Concinno GUI',
    },
    sancio: {
      name: 'sancio',
      port: portSancio,
      tokenPath: getTokenPath('sancio'),
      daemonCmd: ['sancio', 'gui', '--port', String(portSancio)],
      panelTitle: 'Sancio GUI',
    },
    switcher: {
      name: 'switcher',
      port: portSwitcher,
      tokenPath: getTokenPath('switcher'),
      daemonCmd: ['concinno', 'gui', '--switcher', '--port', String(portSwitcher)],
      panelTitle: 'AI King · Unified GUI',
    },
  };
}

function checkHealth(port: number, timeoutMs = 1500): Promise<boolean> {
  return new Promise((resolve) => {
    const req = http.get(
      { hostname: '127.0.0.1', port, path: '/api/health', timeout: timeoutMs },
      (res) => {
        // Any 2xx-3xx is fine; 401 also means the daemon is alive (auth gate).
        const ok = (res.statusCode ?? 0) > 0 && (res.statusCode ?? 0) < 500;
        res.resume();
        resolve(ok);
      },
    );
    req.on('error', () => resolve(false));
    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });
  });
}

function spawnDaemon(backend: GuiBackend): void {
  // detached + stdio:'ignore' + unref() so the daemon outlives VS Code.
  const [cmd, ...args] = backend.daemonCmd;
  try {
    const proc = spawn(cmd, args, {
      detached: true,
      stdio: 'ignore',
      windowsHide: true,
    });
    proc.unref();
    // Eat the spawn-error event so an ENOENT (binary missing) doesn't
    // crash the extension host. The waitForToken() timeout below will
    // surface this as a user-friendly notification.
    proc.on('error', () => {
      /* swallowed — surfaced via waitForToken timeout */
    });
  } catch {
    /* swallowed */
  }
}

async function waitForToken(tokenPath: string, timeoutMs = 5000): Promise<string | null> {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const buf = await fs.promises.readFile(tokenPath, 'utf8');
      const trimmed = buf.trim();
      if (trimmed.length > 0) return trimmed;
    } catch {
      /* not yet */
    }
    await new Promise((r) => setTimeout(r, 200));
  }
  return null;
}

async function readTokenIfExists(tokenPath: string): Promise<string | null> {
  try {
    const buf = await fs.promises.readFile(tokenPath, 'utf8');
    const trimmed = buf.trim();
    return trimmed.length > 0 ? trimmed : null;
  } catch {
    return null;
  }
}

async function ensureBackendUp(backend: GuiBackend): Promise<{ token: string } | null> {
  // 1. Already up?
  if (await checkHealth(backend.port)) {
    const token = await readTokenIfExists(backend.tokenPath);
    if (token) return { token };
    // Daemon up but token missing — race; wait briefly.
    const t = await waitForToken(backend.tokenPath, 2000);
    return t ? { token: t } : null;
  }
  // 2. Spawn detached daemon, then wait for token (this also implies
  //    the daemon bound the port).
  spawnDaemon(backend);
  const token = await waitForToken(backend.tokenPath, 5000);
  if (!token) return null;
  // 3. One last health probe to be sure.
  if (!(await checkHealth(backend.port, 2000))) return null;
  return { token };
}

function buildIframeHtml(port: number, token: string, panelTitle: string): string {
  // Loopback only — assert in builder so a future setting change can't
  // smuggle in a non-local URL.
  const host = '127.0.0.1';
  if (!ALLOWED_HOSTS.has(host)) {
    return `<!DOCTYPE html><html><body><p>blocked non-loopback host</p></body></html>`;
  }
  const url = `http://${host}:${port}/?bearer=${encodeURIComponent(token)}`;
  // Keep the HTML minimal — VS Code's webview CSP defaults are fine
  // because we only load a same-origin-ish iframe (loopback http).
  return `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <title>${panelTitle}</title>
    <style>
      html, body { height: 100%; margin: 0; padding: 0; background: var(--vscode-editor-background); }
      iframe { border: 0; width: 100%; height: 100vh; }
    </style>
  </head>
  <body>
    <iframe src="${url}" sandbox="allow-scripts allow-forms allow-same-origin"></iframe>
  </body>
</html>`;
}

class GuiPanel {
  private static panels = new Map<BackendName, GuiPanel>();

  static createOrShow(backend: GuiBackend, token: string): void {
    const existing = GuiPanel.panels.get(backend.name);
    if (existing) {
      existing.panel.reveal(vscode.ViewColumn.Beside);
      // Refresh HTML in case token rotated since last open.
      existing.panel.webview.html = buildIframeHtml(backend.port, token, backend.panelTitle);
      return;
    }
    const panel = vscode.window.createWebviewPanel(
      `aiKing.gui.${backend.name}`,
      backend.panelTitle,
      vscode.ViewColumn.Beside,
      { enableScripts: true, retainContextWhenHidden: true },
    );
    panel.webview.html = buildIframeHtml(backend.port, token, backend.panelTitle);
    const inst = new GuiPanel(backend.name, panel);
    GuiPanel.panels.set(backend.name, inst);
    panel.onDidDispose(() => {
      GuiPanel.panels.delete(backend.name);
    });
  }

  private constructor(
    private readonly backendName: BackendName,
    private readonly panel: vscode.WebviewPanel,
  ) {
    void this.backendName;
  }
}

static createOrShow(backend: GuiBackend, token: string): void {
  const existing = GuiPanel.panels.get(backend.name);
  if (existing) {
    existing.panel.reveal(vscode.ViewColumn.Beside);
    // Refresh HTML in case token rotated since last open.
    existing.panel.webview.html = buildIframeHtml(backend.port, token, backend.panelTitle);
    return;
  }
  const panel = vscode.window.createWebviewPanel(
    `aiKing.gui.${backend.name}`,
    backend.panelTitle,
    vscode.ViewColumn.Beside,
    { enableScripts: true, retainContextWhenHidden: true },
  );
  panel.webview.html = buildIframeHtml(backend.port, token, backend.panelTitle);
  const inst = new GuiPanel(backend.name, panel);
  GuiPanel.panels.set(backend.name, inst);
  panel.onDidDispose(() => {
    GuiPanel.panels.delete(backend.name);
  });
}

private constructor(
  private readonly backendName: BackendName,
  private readonly panel: vscode.WebviewPanel,
) {
  void this.backendName;
}

async function openBackend(name: BackendName): Promise<void> {
  const backend = buildBackends()[name];
  const result = await ensureBackendUp(backend);
  if (!result) {
    void vscode.window.showWarningMessage(
      `AI King: ${backend.name} GUI daemon not reachable on 127.0.0.1:${backend.port}. ` +
        `Run \`${backend.daemonCmd.join(' ')}\` in a terminal, then re-run the command. ` +
        `Or use "AI King: Start GUI Daemon (manual)" to spawn it now.`,
    );
    return;
  }
  GuiPanel.createOrShow(backend, result.token);
}

export async function openUnifiedCmd(): Promise<void> {
  // Default to switcher; if switcher is unreachable AND the user has
  // never opted into it, fall back to Concinno (per W2 amendment:
  // switcher is opt-in advanced, default UX is per-layer).
  const backend = buildBackends().switcher;
  if (await checkHealth(backend.port)) {
    await openBackend('switcher');
    return;
  }
  // Switcher down — try Concinno as default.
  void vscode.window.showInformationMessage(
    `AI King: switcher (port ${backend.port}) not running — opening Concinno GUI directly. ` +
      `Run \`concinno gui --switcher\` if you want the unified federation view.`,
  );
  await openBackend('concinno');
}

