export async function startDaemonCmd(): Promise<void> {
  const backends = buildBackends();
  const items: Array<vscode.QuickPickItem & { name: BackendName }> = [
    { label: 'Concinno (port ' + backends.concinno.port + ')', name: 'concinno' },
    { label: 'Sancio (port ' + backends.sancio.port + ')', name: 'sancio' },
    {
      label: 'Unified switcher (port ' + backends.switcher.port + ')',
      name: 'switcher',
    },
  ];
  const pick = await showQuickPickEsc(items, {
    placeHolder: 'Pick a GUI daemon to spawn (detached background process)',
    title: 'AI King: Start GUI Daemon',
  });
  if (!pick) return;
  const backend = backends[pick.name];
  spawnDaemon(backend);
  const token = await waitForToken(backend.tokenPath, 5000);
  if (!token) {
    void vscode.window.showErrorMessage(
      `AI King: ${pick.name} daemon failed to write ${backend.tokenPath} within 5 s. ` +
        `Try running \`${backend.daemonCmd.join(' ')}\` in a terminal to see the error.`,
    );
    return;
  }
  void vscode.window.showInformationMessage(
    `AI King: ${pick.name} daemon spawned on 127.0.0.1:${backend.port}. ` +
      `Use "AI King: Open ${pick.name === 'switcher' ? 'Unified' : pick.name === 'concinno' ? 'Concinno' : 'Sancio'} GUI" to view it.`,
  );
}

