function ensureChannel(): vscode.OutputChannel {
  if (!channel) {
    channel = vscode.window.createOutputChannel('AI King');
  }
  return channel;
}

function fmt(level: string, tag: string, payload?: unknown): string {
  const ts = new Date().toISOString();
  const body = payload === undefined ? '' : ` ${safeStringify(payload)}`;
  return `[${ts}] [${level}] ${tag}${body}`;
}

function safeStringify(value: unknown): string {
  try {
    return JSON.stringify(value, (_k, v) => {
      if (typeof v === 'string' && v.length > 500) return v.slice(0, 500) + '…';
      return v;
    });
  } catch {
    try {
      return String(value);
    } catch {
      return '<unloggable>';
    }
  }
}

export const log = {
  info(tag: string, payload?: unknown): void {
    ensureChannel().appendLine(fmt('INFO', tag, payload));
  },
  warn(tag: string, payload?: unknown): void {
    ensureChannel().appendLine(fmt('WARN', tag, payload));
  },
  error(tag: string, payload?: unknown): void {
    ensureChannel().appendLine(fmt('ERROR', tag, payload));
  },
  /**
   * Surface the channel to the user. Only called on explicit commands
   * or catastrophic failures — never on routine events, because forcing
   * the Output panel open is aggressive UX.
   */
  reveal(): void {
    ensureChannel().show(true);
  },
  dispose(): void {
    channel?.dispose();
    channel = undefined;
  },
};

info(tag: string, payload?: unknown): void {
