function detectSystemNode(): Promise<boolean> {
  if (systemNodePath()) return Promise.resolve(true);
  return new Promise((resolve) => {
    let done = false;
    const finish = (b: boolean) => {
      if (!done) {
        done = true;
        resolve(b);
      }
    };
    try {
      // win32 需 shell 才能從 PATH 解析 'node'(→node.exe)；指令固定無使用者輸入、無注入風險。
      const p = cp.spawn('node', ['-v'], { windowsHide: true, shell: process.platform === 'win32' });
      p.on('error', () => finish(false));
      p.on('close', (code) => finish(code === 0));
      setTimeout(() => {
        try {
          p.kill();
        } catch {
          /* */
        }
        finish(false);
      }, 4000);
    } catch {
      finish(false);
    }
  });
}

function installHint(): { label: string; cmd: string } {
  if (process.platform === 'win32') return { label: 'winget', cmd: 'winget install OpenJS.NodeJS.LTS' };
  if (process.platform === 'darwin') return { label: 'Homebrew', cmd: 'brew install node' };
  return { label: '套件管理器', cmd: 'sudo apt install -y nodejs npm   # 或你的 distro 對應指令' };
}

export function registerNodeCheck(ctx: vscode.ExtensionContext): void {
  // 一鍵安裝 command：開終端機填好平台對應指令（不自動跑、使用者看清楚再按 Enter），或開官網。
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.installNode', async () => {
      const h = installHint();
      const pick = await showQuickPickEsc(
        [
          { label: `用 ${h.label} 安裝（開終端機、你按 Enter 執行）`, detail: h.cmd, action: 'cmd' as const },
          { label: '開 Node.js 官網手動下載', detail: 'https://nodejs.org/', action: 'url' as const },
        ],
        { placeHolder: 'AI King：安裝 Node.js（讓外部 AI 能連你的群組）', ignoreFocusOut: true },
      );
      if (!pick) return;
      if (pick.action === 'url') {
        void vscode.env.openExternal(vscode.Uri.parse('https://nodejs.org/'));
        return;
      }
      const term = vscode.window.createTerminal('AI King — 安裝 Node.js');
      term.show();
      term.sendText(h.cmd, false); // false＝只填指令、不自動 Enter；使用者先看清楚再執行
    }),
  );

  // 啟動背景偵測：沒系統 node → 一次性友善提示（globalState 記住、不每次煩）。
  void (async () => {
    try {
      if (await detectSystemNode()) return; // 有系統 node＝最佳，靜默
      if (ctx.globalState.get<boolean>(SHOWN_KEY)) return; // 提示過一次就不再煩
      await ctx.globalState.update(SHOWN_KEY, true);
      const choice = await vscode.window.showInformationMessage(
        'AI King：這台沒裝 Node.js。聊天／群組核心會自動借 VS Code 內建的 node 跑、不受影響；'
          + '只有要讓「外部 AI（Codex 等在終端機）」連你的群組時才需要系統 Node.js。',
        '一鍵安裝',
        '看官網',
        '不用了',
      );
      if (choice === '一鍵安裝') void vscode.commands.executeCommand('aiKing.installNode');
      else if (choice === '看官網') void vscode.env.openExternal(vscode.Uri.parse('https://nodejs.org/'));
    } catch {
      /* 偵測/提示失敗絕不影響啟動 */
    }
  })();
}

export const NODE_CANDIDATES: readonly string[] =
  process.platform === 'win32'
    ? ['C:\\Program Files\\nodejs\\node.exe', 'C:\\Program Files (x86)\\nodejs\\node.exe']
    : ['/usr/local/bin/node', '/usr/bin/node', '/opt/homebrew/bin/node'];

export function systemNodePath(): string | null {
  for (const c of NODE_CANDIDATES) {
    try {
      if (fs.existsSync(c)) return c;
    } catch {
      /* keep looking */
    }
  }
  return null;
}

export function resolveNode(): { cmd: string; extraEnv: Record<string, string> } {
  const real = systemNodePath();
  if (real) return { cmd: real, extraEnv: {} };
  return { cmd: process.execPath, extraEnv: { ELECTRON_RUN_AS_NODE: '1' } };
}

export function showSystemToast(
  title: string,
  body: string,
  ctx: vscode.ExtensionContext,
): Promise<boolean> {
  if (process.platform !== 'win32') return Promise.resolve(false);
  const logo = ctx.asAbsolutePath(path.join('media', 'icon.png'));
  // 自帶 bundle 的 BurntToast 模組清單檔（隨 vsix）。
  const bundled = ctx.asAbsolutePath(
    path.join('media', 'vendor', 'BurntToast', '1.1.0', 'BurntToast.psd1'),
  );
  // single-quoted PowerShell 字串；'' escape 單引號防注入（body 來自 LLM 回覆、不可信）。
  const esc = (s: string): string => String(s || '').replace(/'/g, "''");
  const ps =
    `$bt='${esc(bundled)}'; ` +
    `if (Test-Path -LiteralPath $bt) { Import-Module $bt } ` + // ① 自帶 bundle 優先
    `elseif (Get-Module -ListAvailable -Name BurntToast) { Import-Module BurntToast } ` + // ② 本機已裝
    `else { exit 3 }; ` + // ③ 都沒有 → 降級信號
    `New-BurntToastNotification -Text '${esc(title)}','${esc(body)}' -AppLogo '${esc(logo)}'; ` +
    `exit 0`;
  return new Promise<boolean>((resolve) => {
    try {
      execFile(
        'powershell.exe',
        ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-Command', ps],
        { timeout: 8000, windowsHide: true },
        (err) => {
          if (err) {
            // exit 3 = BurntToast 未裝（正常降級）；其餘記 log 供診斷。
            const code = (err as { code?: number }).code;
            if (code !== 3) {
              log.info('notify:systemToast:unavailable', { code, msg: err.message });
            }
            resolve(false);
          } else {
            resolve(true);
          }
        },
      );
    } catch (e) {
      log.info('notify:systemToast:spawnFail', {
        error: e instanceof Error ? e.message : String(e),
      });
      resolve(false);
    }
  });
}

export interface ClassifyResult {
  level: RiskLevel;
  /** Why the classifier reached this verdict — surfaced in logs + status bar. */
  reason: string;
  /** Pattern id that matched (for telemetry / user-visible deny reason). */
  pattern?: string;
}

export interface ClassifyInput {
  /** Normalized canonical tool name (already passed through normalizeToolName). */
  tool: string;
  /** Raw arguments the runner is about to execute. */
  args: unknown;
}

const INSPECTABLE_TOOLS = new Set<string>([
  'bash',
  'edit_file',
  'write_file',
  'run_script',
]);

interface DangerousPattern {
  id: string;
  re: RegExp;
  reason: string;
}

const DANGEROUS_BASH: DangerousPattern[] = [
  // Recursive force-delete of root or home — single most destructive pattern.
  {
    id: 'rm-rf-root',
    re: /\brm\s+(?:-[a-zA-Z]*r[a-zA-Z]*f|-[a-zA-Z]*f[a-zA-Z]*r|-rf|-fr|--recursive\s+--force|--force\s+--recursive)\s+(?:--no-preserve-root\s+)?(?:\/(?!\w)|~|\$HOME|\.\s*$|\.\/\s*$)/i,
    reason: 'rm -rf targeting filesystem root, $HOME, or working tree',
  },
  // Force push to protected branches.
  {
    id: 'force-push-main',
    re: /\bgit\s+push\s+(?:--force|--force-with-lease|-f\b)\s+\S+\s+(?:HEAD:)?(?:main|master|trunk|prod|production|release\/\S*)\b/i,
    reason: 'git force-push to a protected branch',
  },
  // Database mass-destruction.
  {
    id: 'sql-mass-destroy',
    re: /\b(?:DROP\s+(?:TABLE|DATABASE|SCHEMA)|TRUNCATE\s+TABLE|DELETE\s+FROM\s+\S+\s+WHERE\s+1\s*=\s*1|DELETE\s+FROM\s+\S+\s*;?\s*$)/i,
    reason: 'mass-destructive SQL statement',
  },
  // Pipe-to-shell from network — supply chain attack surface.
  {
    id: 'curl-pipe-shell',
    re: /\b(?:curl|wget|fetch|http)\b[^|;&\n]*\|\s*(?:bash|sh|zsh|fish|python\d?|node|perl|ruby)\b/i,
    reason: 'piping network download directly into a shell interpreter',
  },
  // Disk overwrite.
  {
    id: 'dd-of-device',
    re: /\bdd\s+(?:[a-zA-Z=0-9_]+\s+)*of\s*=\s*\/dev\/\w+/i,
    reason: 'dd write to a raw device',
  },
  // World-writable on broad targets.
  {
    id: 'chmod-777-recursive',
    re: /\bchmod\s+(?:-R\s+)?(?:0?777|a\+rwx)\s+(?:\/(?!\w)|~|\$HOME|\.\s*$)/i,
    reason: 'recursive chmod 777 on root, $HOME, or working tree',
  },
  // History rewrite that propagates.
  {
    id: 'git-filter-repo-push',
    re: /\bgit\s+(?:filter-repo|filter-branch)\b/i,
    reason: 'git history rewrite (irreversible for collaborators)',
  },
  // Package publish — irreversible distribution.
  {
    id: 'pkg-publish',
    re: /\b(?:twine\s+upload|npm\s+publish(?!\s+--dry-run)|cargo\s+publish(?!\s+--dry-run)|gem\s+push|mvn\s+deploy)\b/i,
    reason: 'package registry publish (irreversible)',
  },
  // Credential exfiltration — POST a credential file body to remote.
  {
    id: 'creds-exfil',
    re: /\b(?:curl|wget)\b[^;\n]*(?:--data-binary|--upload-file|-d\s+@|-F\s+\S+@)\s*[@]?[~/]?(?:\.ssh\/|\.aws\/|\.netrc|\.pypirc|\.env\b|credentials)/i,
    reason: 'uploading a credential file to a remote endpoint',
  },
];

function classifyFileWrite(args: unknown): ClassifyResult | null {
  const path = extractStringField(args, ['path', 'file_path', 'filepath', 'file', 'target']);
  if (!path) return null;
  if (SENSITIVE_PATH_RE.test(path)) {
    return {
      level: 'dangerous',
      pattern: 'sensitive-path-write',
      reason: `write to credential / secret path: ${truncate(path, 80)}`,
    };
  }
  return null;
}

function classifyNetworkFetch(args: unknown): ClassifyResult | null {
  // Pure GETs are safe; POST/PUT with body to non-allowlisted host = exfil risk.
  // host-allowlist is enforced separately (see providers/host-allowlist.ts);
  // here we only flag obviously suspicious shapes.
  const method = (extractStringField(args, ['method']) || 'GET').toUpperCase();
  if (method === 'GET' || method === 'HEAD') return { level: 'safe', reason: 'read-only HTTP method' };
  const body = extractStringField(args, ['body', 'data', 'payload']);
  if (body && /(?:sk-ant-|sk-proj-|ghp_|github_pat_|aws_secret|BEGIN\s+(?:RSA|OPENSSH|PGP)\s+PRIVATE)/.test(body)) {
    return {
      level: 'dangerous',
      pattern: 'creds-in-payload',
      reason: 'request body contains a recognizable credential pattern',
    };
  }
  return { level: 'risky', reason: `bounded ${method} request (host allow-list enforced separately)` };
}

function userDenyPatterns(): string[] {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const raw = cfg.get<unknown>('autoMode.deny');
  if (!Array.isArray(raw)) return [];
  return raw.filter((x): x is string => typeof x === 'string' && x.length > 0);
}

function matchesUserDeny(haystack: string): { matched: true; pattern: string } | null {
  for (const pat of userDenyPatterns()) {
    try {
      if (new RegExp(pat, 'i').test(haystack)) {
        return { matched: true, pattern: pat };
      }
    } catch {
      // Bad regex from user config — ignore that one entry, keep checking.
    }
  }
  return null;
}

export function classifyRisk(input: ClassifyInput): ClassifyResult {
  const { tool, args } = input;

  // 1. User deny — highest priority.
  const haystack = `${tool} ${stringifyArgs(args)}`;
  const userMatch = matchesUserDeny(haystack);
  if (userMatch) {
    return {
      level: 'dangerous',
      pattern: 'user-deny',
      reason: `matched aiKing.autoMode.deny pattern: ${userMatch.pattern}`,
    };
  }

  // 2. Built-in safe tools.
  if (SAFE_TOOLS.has(tool)) {
    return { level: 'safe', reason: `tool ${tool} is read-only by definition` };
  }

  // 3. Inspectable write/exec tools.
  if (tool === 'bash' || tool === 'run_script') {
    const cmd = extractStringField(args, ['command', 'cmd', 'script', 'code']) || '';
    for (const pat of DANGEROUS_BASH) {
      if (pat.re.test(cmd)) {
        return { level: 'dangerous', pattern: pat.id, reason: pat.reason };
      }
    }
    return { level: 'risky', reason: 'bounded shell command (no dangerous pattern matched)' };
  }
  if (tool === 'write_file' || tool === 'edit_file') {
    const fileVerdict = classifyFileWrite(args);
    if (fileVerdict) return fileVerdict;
    return { level: 'risky', reason: `${tool} on workspace path` };
  }
  if (tool === 'network_fetch') {
    const verdict = classifyNetworkFetch(args);
    if (verdict) return verdict;
  }

  // 4. Unknown — opt for risky (auto-approve in Auto mode but logged).
  if (tool.startsWith('custom:')) {
    return { level: 'risky', reason: `unknown custom tool ${tool} — promote via aiKing.autoMode.allow if trusted` };
  }
  if (INSPECTABLE_TOOLS.has(tool)) {
    return { level: 'risky', reason: `${tool} fell through inspection — defaulting to risky` };
  }
  return { level: 'risky', reason: `tool ${tool} not in safe set` };
}

function extractStringField(args: unknown, keys: string[]): string | null {
  if (!args || typeof args !== 'object') return null;
  const obj = args as Record<string, unknown>;
  for (const k of keys) {
    const v = obj[k];
    if (typeof v === 'string' && v.length > 0) return v;
  }
  return null;
}

function stringifyArgs(args: unknown): string {
  try {
    if (!args) return '';
    return typeof args === 'string' ? args : JSON.stringify(args);
  } catch {
    return '';
  }
}

function truncate(s: string, max: number): string {
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}

export function recordVerdict(tool: string, result: ClassifyResult): void {
  lastVerdict = { tool, level: result.level, reason: result.reason, at: Date.now() };
  log.info('auto-classifier:verdict', { tool, level: result.level, reason: result.reason, pattern: result.pattern });
}

export function getLastVerdict(): typeof lastVerdict {
  return lastVerdict;
}

export function resetVerdict(): void {
  lastVerdict = null;
}

interface BreakerState {
  consecutiveBlocks: number;
  totalBlocks: number;
  totalApprovals: number;
  tripped: boolean;
  trippedReason: string | null;
  trippedAt: number | null;
}

const state: BreakerState = {
  consecutiveBlocks: 0,
  totalBlocks: 0,
  totalApprovals: 0,
  tripped: false,
  trippedReason: null,
  trippedAt: null,
};

function maxConsecutive(): number {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const v = cfg.get<number>('autoMode.maxConsecutiveBlocks');
  return typeof v === 'number' && v > 0 ? Math.floor(v) : 3;
}

function maxTotal(): number {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const v = cfg.get<number>('autoMode.maxTotalBlocks');
  return typeof v === 'number' && v > 0 ? Math.floor(v) : 20;
}

export interface BreakerStats {
  consecutiveBlocks: number;
  totalBlocks: number;
  totalApprovals: number;
  tripped: boolean;
  trippedReason: string | null;
  thresholdConsecutive: number;
  thresholdTotal: number;
}

export function getStats(): BreakerStats {
  return {
    consecutiveBlocks: state.consecutiveBlocks,
    totalBlocks: state.totalBlocks,
    totalApprovals: state.totalApprovals,
    tripped: state.tripped,
    trippedReason: state.trippedReason,
    thresholdConsecutive: maxConsecutive(),
    thresholdTotal: maxTotal(),
  };
}

export function recordApproval(): void {
  state.totalApprovals += 1;
  state.consecutiveBlocks = 0; // reset streak — we're in a happy path again
}

export interface RecordBlockResult {
  /** True if recording this block tripped the breaker (caller should fall out of Auto mode). */
  tripped: boolean;
  /** Human reason — surfaced as toast notification if tripped. */
  reason: string | null;
}

export function recordBlock(reasonHint: string): RecordBlockResult {
  state.consecutiveBlocks += 1;
  state.totalBlocks += 1;

  const cMax = maxConsecutive();
  const tMax = maxTotal();

  if (state.consecutiveBlocks >= cMax) {
    return trip(`${state.consecutiveBlocks} risky operations in a row (limit ${cMax}). Last reason: ${reasonHint}`);
  }
  if (state.totalBlocks >= tMax) {
    return trip(`${state.totalBlocks} risky operations this session (limit ${tMax}). Last reason: ${reasonHint}`);
  }
  return { tripped: false, reason: null };
}

function trip(reason: string): RecordBlockResult {
  if (state.tripped) {
    // Already tripped — don't double-fire.
    return { tripped: false, reason: null };
  }
  state.tripped = true;
  state.trippedReason = reason;
  state.trippedAt = Date.now();
  log.info('circuit-breaker:tripped', { reason, stats: getStats() });
  return { tripped: true, reason };
}

export function isTripped(): boolean {
  return state.tripped;
}

export function reset(): void {
  state.consecutiveBlocks = 0;
  state.totalBlocks = 0;
  state.totalApprovals = 0;
  state.tripped = false;
  state.trippedReason = null;
  state.trippedAt = null;
  log.info('circuit-breaker:reset', {});
}

export function rearm(): void {
  state.consecutiveBlocks = 0;
  state.tripped = false;
  state.trippedReason = null;
  state.trippedAt = null;
  log.info('circuit-breaker:rearmed', { stats: getStats() });
}

export type PermissionDecision =
  | 'allow_once'
  | 'allow_tool'
  | 'allow_session'
  | 'deny';

export interface PermissionRequest {
  /** Raw tool name from the caller (will be normalized). */
  tool: string;
  /** Tool arguments for user context; shown truncated in the prompt detail. */
  args: unknown;
  /** Optional free-text explaining *why* this call was triggered. */
  context?: string;
  /**
   * [1.13.x 群組安全] 強制顯示確認、跳過所有信任短路（autoApproveAll / auto mode /
   * 持久化 / session），且只給「允許一次 / 拒絕」（不提供持久化選項）。給「遠端來源」觸發
   * 的工具用——典型是群組 @ 讓內建 Agent 在『本機』跑 run_bash / write_file 的 RCE 面：
   * 本機使用者對自己 AI 設的信任，不該替別人從群組叫起的工具放行。
   */
  forcePrompt?: boolean;
  /**
   * [F 授權抽屜 1.24.32] 自訂提示器：對話面板傳入＝改用 webview 內彈底部抽屜（promise-bridge），
   * 不傳＝fallback 原生 QuickPick（群組 RCE 面刻意不傳＝用 host modal 反更安全、不被 webview 干擾）。
   * 回傳 PermissionDecision；取消/關面板/reload 一律 resolve 'deny'（安全預設、防卡 tool loop）。
   */
  prompter?: (req: PermissionRequest) => Promise<PermissionDecision>;
  /**
   * [權限卡死修 2026-06-22] 對話取消信號。授權 QuickPick 接這個 token：使用者按 Stop /
   * 對話取消時授權窗一起關掉並視同 deny，避免「懸而未答 → tool loop 卡死 → busy 永卡 →
   * 訊息黏一起」（紅藍 CBUA 坐實的串連根因）。
   */
  signal?: vscode.CancellationToken;
}

const TOOL_ALIASES: Record<string, string> = {
  shell: 'bash',
  terminal: 'bash',
  exec: 'bash',
  // [1.13.x 安全] clean-tools 的 run_bash 必須映射到 canonical 'bash'，否則
  // normalizeToolName('run_bash')→'custom:run_bash'，auto-classifier 的 DANGEROUS_BASH
  // 危險正則（rm -rf / curl|sh / DROP TABLE）只認 tool==='bash' → 對 run_bash 完全失效
  // （在 auto mode 下被當 custom:* 判 risky 靜默放行）。對話分頁與群組路徑共用此分類。
  run_bash: 'bash',
  run: 'run_script',
  script: 'run_script',
  edit: 'edit_file',
  patch: 'edit_file',
  str_replace: 'edit_file',
  write: 'write_file',
  create: 'write_file',
  fetch: 'network_fetch',
  http: 'network_fetch',
  curl: 'network_fetch',
  webfetch: 'network_fetch',
  web_fetch: 'network_fetch',
};

export function normalizeToolName(raw: string): string {
  const lower = String(raw || '').trim().toLowerCase();
  if (!lower) return 'unknown';
  if (CANONICAL_TOOLS.has(lower)) return lower;
  if (lower in TOOL_ALIASES) return TOOL_ALIASES[lower];
  // Preserve the user-facing spelling but fence with `custom:` so the
  // prompt makes it obvious we don't know this one.
  return `custom:${lower}`;
}

export function clearSessionPermissions(): void {
  sessionAllowed.clear();
}

function toolKey(tool: string): string {
  return `aiKing.permissions.${tool}`;
}

export async function clearToolPermissions(
  ctx: vscode.ExtensionContext,
): Promise<number> {
  const keys = ctx.workspaceState.keys().filter((k) =>
    k.startsWith('aiKing.permissions.'),
  );
  for (const k of keys) {
    await ctx.workspaceState.update(k, undefined);
  }
  log.info('permission:clear-tool', { cleared: keys.length });
  return keys.length;
}

function isAutoApproveAll(): boolean {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  return cfg.get<boolean>('autoApproveAll') === true;
}

function currentMode(ctx: vscode.ExtensionContext): string {
  // [權限同源修 2026-06-22 紅藍CBUA] 改讀 getLastMode（workspaceState、fallback
  // DEFAULT_MODE='auto'），與 UI 端（chat-panel / registry）同源。舊版讀未在 package.json
  // 註冊的 config `aiKing.lastMode`、缺值 fallback 'edits' → UI 顯示 Auto 但 gate 實際當
  // edits → 工具仍彈 QuickPick（甚至沒人答就卡死）。這是「Auto 預設沒生效 / 授權模式壞 /
  // 訊息黏一起」三症狀的同源根因。setLastMode 對未註冊 config 的鏡射(registry 87-94)
  // 靜默失敗也因此不再有影響。
  return getLastMode(ctx);
}

function isAutoMode(mode: string): boolean {
  if (mode !== 'auto') return false;
  const cfg = vscode.workspace.getConfiguration('aiKing');
  if (cfg.get<string>('disableAutoMode') === 'disable') return false;
  return true;
}

function userAutoAllow(): Set<string> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const raw = cfg.get<unknown>('autoMode.allow');
  if (!Array.isArray(raw)) return new Set();
  return new Set(raw.filter((x): x is string => typeof x === 'string'));
}

function isToolPersistentlyAllowed(
  ctx: vscode.ExtensionContext,
  tool: string,
): boolean {
  return ctx.workspaceState.get<boolean>(toolKey(tool)) === true;
}

interface PickItem extends vscode.QuickPickItem {
  decision: PermissionDecision;
}

function buildItems(tool: string, forceOnce = false): PickItem[] {
  const allowOnce: PickItem = {
    label: '$(check) 允許一次 (Allow once)',
    description: '本次呼叫 / Grant this call only',
    decision: 'allow_once',
  };
  const deny: PickItem = {
    label: '$(x) 拒絕 (Deny)',
    description: '取消這次呼叫 / Abort this call',
    decision: 'deny',
  };
  // [1.13.x 群組安全] forceOnce（遠端來源的 RCE 面）：只給「允許一次 / 拒絕」，不提供
  // 持久化選項——避免一次「永遠允許」之後遠端 @ 都靜默放行。
  if (forceOnce) return [allowOnce, deny];
  return [
    allowOnce,
    {
      label: `$(shield) 永遠允許 ${tool} (Allow always for this tool)`,
      description: '永久記住 (workspaceState) / Persist forever',
      decision: 'allow_tool',
    },
    {
      label: '$(clock) 本 Session 全允許 (Allow always for this session)',
      description: '重開 VSCode 會問 / Cleared on reload',
      decision: 'allow_session',
    },
    deny,
  ];
}

function formatDetail(req: PermissionRequest): string {
  const parts: string[] = [];
  if (req.context) parts.push(req.context);
  try {
    const argsStr = JSON.stringify(req.args);
    if (argsStr && argsStr !== '{}' && argsStr !== 'null') {
      parts.push(
        `args: ${argsStr.length > 200 ? argsStr.slice(0, 200) + '…' : argsStr}`,
      );
    }
  } catch {
    /* args not serializable — skip */
  }
  return parts.join(' · ');
}

export async function askPermission(
  ctx: vscode.ExtensionContext,
  req: PermissionRequest,
): Promise<PermissionDecision> {
  const tool = normalizeToolName(req.tool);

  // [1.13.x 群組安全] forcePrompt（遠端來源的 RCE 面，如群組 @ 觸發內建 Agent 在本機跑
  // run_bash）→ 跳過 autoApproveAll / auto mode / 持久化 / session 全部信任短路，每次都確認，
  // 只給「允許一次 / 拒絕」。本機對自己 AI 的信任設定不該替別人從群組叫起的工具放行。
  if (req.forcePrompt) {
    // [F 授權抽屜 1.24.32] 有 prompter（對話面板）走 webview 抽屜、只認 allow_once/deny；否則原生
    //   QuickPick。群組 RCE 面刻意不傳 prompter＝走下方 QuickPick（host modal 更安全）。
    if (req.prompter) {
      const d = await req.prompter(req).catch(() => 'deny' as PermissionDecision);
      if (d === 'deny') { log.warn('permission:group-force-deny', { tool }); return 'deny'; }
      log.info('permission:group-force-allow', { tool });
      return 'allow_once';
    }
    const pick = await showQuickPickEsc(buildItems(tool, true), {
      title: `AI King · 群組工具呼叫權限 (Group Tool Permission) — ${tool}`,
      placeHolder: formatDetail(req) || '遠端成員要在你本機跑這個工具，是否允許？',
      ignoreFocusOut: true,
      matchOnDescription: true,
    }, req.signal);
    if (!pick || pick.decision === 'deny') {
      log.warn('permission:group-force-deny', { tool });
      return 'deny';
    }
    log.info('permission:group-force-allow', { tool });
    return 'allow_once';
  }

  if (isAutoApproveAll()) {
    log.info('permission:auto-approve-all', { tool });
    return 'allow_once';
  }
  const mode = currentMode(ctx);
  if (isAutoMode(mode)) {
    // Breaker tripped in this session → Auto Mode is paused; behave like
    // edits/chat (ask on every call) until user explicitly re-enters Auto.
    if (!breakerIsTripped()) {
      // 1.7.0: Auto absorbed bypass. There are only two outcomes here —
      //   • the user's deny regex matched → HARD DENY (no prompt, ever).
      //   • anything else → auto-approve (dangerous verdicts are logged).
      // The QuickPick is never shown in Auto mode.

      // User-defined per-tool allowlist short-circuits the classifier so the
      // user can promote a known-safe `custom:*` tool to no-prompt without
      // editing classifier source.
      if (userAutoAllow().has(tool)) {
        breakerRecordApproval();
        refreshAutoModeStatusBar();
        log.info('permission:mode-auto-user-allow', { tool });
        return 'allow_once';
      }

      const verdict = classifyRisk({ tool, args: req.args });
      recordVerdict(tool, verdict);

      // Hard deny: the user's `aiKing.autoMode.deny` regex set is the ONLY
      // thing Auto blocks. Record a breaker block; if that trips the breaker,
      // demote mode back to `edits` so subsequent calls ask again.
      if (verdict.pattern === 'user-deny') {
        const tripped = breakerRecordBlock(verdict.reason);
        refreshAutoModeStatusBar();
        if (tripped.tripped && tripped.reason) {
          await demoteFromAutoMode(ctx, tripped.reason);
        }
        log.warn('permission:mode-auto-hard-deny', { tool, reason: verdict.reason });
        return 'deny';
      }

      // Everything else auto-approves. A built-in `dangerous` verdict (rm -rf
      // not in the user deny set, sensitive-path write, etc.) is approved but
      // written to the output channel log so there's an audit trail — this is
      // the absorbed-bypass behavior the user asked for (Auto = loop to the
      // end without prompting; only the deny regex stops it).
      if (verdict.level === 'dangerous') {
        log.warn('permission:mode-auto-approve-dangerous', {
          tool,
          reason: verdict.reason,
          pattern: verdict.pattern,
        });
      } else {
        log.info('permission:mode-auto-allow', {
          tool,
          level: verdict.level,
          reason: verdict.reason,
        });
      }
      breakerRecordApproval();
      refreshAutoModeStatusBar();
      return 'allow_once';
    }
  }
  if (isToolPersistentlyAllowed(ctx, tool)) {
    log.info('permission:cached-tool', { tool });
    return 'allow_once';
  }
  if (sessionAllowed.has(tool)) {
    log.info('permission:cached-session', { tool });
    return 'allow_once';
  }

  // [F 授權抽屜 1.24.32] 有 prompter（對話面板）→ webview 底部抽屜取代原生 QuickPick；回 decision
  //   直接走與 QuickPick 一致的落地（allow_session→Set / allow_tool→workspaceState）。
  if (req.prompter) {
    const d = await req.prompter(req).catch(() => 'deny' as PermissionDecision);
    switch (d) {
      case 'allow_session':
        sessionAllowed.add(tool);
        log.info('permission:allow-session', { tool });
        return 'allow_session';
      case 'allow_tool':
        await ctx.workspaceState.update(toolKey(tool), true);
        log.info('permission:allow-tool', { tool });
        return 'allow_tool';
      case 'deny':
        log.info('permission:deny', { tool });
        return 'deny';
      default:
        log.info('permission:allow-once', { tool });
        return 'allow_once';
    }
  }

  const detail = formatDetail(req);
  const pick = await showQuickPickEsc(buildItems(tool), {
    title: `AI King · 工具呼叫權限 (Tool Permission) — ${tool}`,
    placeHolder: detail || '選擇如何處理這次工具呼叫 (choose how to handle this call)',
    ignoreFocusOut: true,
    matchOnDescription: true,
  }, req.signal);

  // User dismissed (Esc) → deny by default. Safer than implicit allow.
  if (!pick) {
    log.info('permission:dismissed', { tool });
    return 'deny';
  }

  switch (pick.decision) {
    case 'allow_session':
      sessionAllowed.add(tool);
      log.info('permission:allow-session', { tool });
      return 'allow_session';
    case 'allow_tool':
      await ctx.workspaceState.update(toolKey(tool), true);
      log.info('permission:allow-tool', { tool });
      return 'allow_tool';
    case 'deny':
      log.info('permission:deny', { tool });
      return 'deny';
    case 'allow_once':
    default:
      log.info('permission:allow-once', { tool });
      return 'allow_once';
  }
}

export async function askPermissionAllowed(
  ctx: vscode.ExtensionContext,
  req: PermissionRequest,
): Promise<boolean> {
  const decision = await askPermission(ctx, req);
  return decision !== 'deny';
}

export interface AllowlistSuggestion {
  tool: string;
  /** Why this tool is on the suggestion list. */
  reason: 'session-granted' | 'custom-name' | 'already-persisted';
  /** True if workspaceState already has `aiKing.permissions.<tool>=true`. */
  persisted: boolean;
}

export function collectAllowlistSuggestions(
  ctx: vscode.ExtensionContext,
): AllowlistSuggestion[] {
  const out = new Map<string, AllowlistSuggestion>();

  const persistedKeys = ctx.workspaceState
    .keys()
    .filter((k) => k.startsWith('aiKing.permissions.'));
  for (const k of persistedKeys) {
    if (ctx.workspaceState.get<boolean>(k) !== true) continue;
    const tool = k.slice('aiKing.permissions.'.length);
    out.set(tool, { tool, reason: 'already-persisted', persisted: true });
  }

  for (const tool of sessionAllowed) {
    const existing = out.get(tool);
    if (existing) continue;
    out.set(tool, {
      tool,
      reason: tool.startsWith('custom:') ? 'custom-name' : 'session-granted',
      persisted: false,
    });
  }

  const order: Record<AllowlistSuggestion['reason'], number> = {
    'session-granted': 0,
    'custom-name': 1,
    'already-persisted': 2,
  };
  return [...out.values()].sort((a, b) => order[a.reason] - order[b.reason]);
}

export async function persistTools(
  ctx: vscode.ExtensionContext,
  tools: string[],
): Promise<number> {
  let n = 0;
  for (const tool of tools) {
    if (!tool) continue;
    await ctx.workspaceState.update(toolKey(tool), true);
    sessionAllowed.delete(tool);
    n++;
  }
  log.info('permission:allowlist-promoted', { count: n, tools });
  return n;
}

async function demoteFromAutoMode(ctx: vscode.ExtensionContext, reason: string): Promise<void> {
  try {
    // [權限同源修 2026-06-22 紅藍review] 用 setLastMode 同寫 workspaceState（gate 讀的源頭）+
    //   config 鏡射，否則降級到 edits 對 gate 無效（gate 讀 workspaceState、仍是舊 auto、breaker 白跳）。
    await setLastMode(ctx, 'edits');
  } catch (e) {
    log.warn('permission:auto-demote-failed', { error: String(e) });
  }
  vscode.window.showWarningMessage(
    `AI King · Auto Mode paused: ${reason}. Switched to Edits mode (asks on every call). Re-enter Auto from the status bar to retry.`,
  );
  log.info('permission:auto-demoted', { reason });
}

export function resolveAikingHome(): vscode.Uri {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const explicit = cfg.get<string>('dataHome');
  if (explicit && explicit.trim()) return vscode.Uri.file(explicit.trim());
  const env = process.env.AIKING_HOME;
  if (env && env.trim()) return vscode.Uri.file(env.trim());
  return vscode.Uri.file(path.join(os.homedir(), '.aiking'));
}

export function sanitizeNs(ns: string | undefined): string {
  if (!ns || ns === PROFILE_GUEST) return PROFILE_GUEST;
  if (/^[0-9]+$/.test(ns)) return ns;
  const clean = ns.replace(/[^a-zA-Z0-9_-]/g, '');
  return clean || PROFILE_GUEST;
}

export function profileDir(ns: string): vscode.Uri {
  return vscode.Uri.joinPath(resolveAikingHome(), 'profiles', sanitizeNs(ns));
}

export function sessionsDir(ns: string): vscode.Uri {
  return vscode.Uri.joinPath(profileDir(ns), 'sessions');
}

export function profileSwitchEnabled(): boolean {
  return (
    vscode.workspace
      .getConfiguration('aiKing')
      .get<boolean>('account.profileSwitch.enabled') !== false
  );
}

export async function resolveActiveNamespace(
  ctx: vscode.ExtensionContext,
): Promise<string> {
  if (!profileSwitchEnabled()) return PROFILE_GUEST;
  const id = await getStoredAccountId(ctx);
  return id ? sanitizeNs(id) : PROFILE_GUEST;
}

export function isBound(ctx: vscode.ExtensionContext, accountId: string): boolean {
  return ctx.globalState.get<boolean>(BOUND_PREFIX + sanitizeNs(accountId)) === true;
}

export async function markBound(
  ctx: vscode.ExtensionContext,
  accountId: string,
): Promise<void> {
  await ctx.globalState.update(BOUND_PREFIX + sanitizeNs(accountId), true);
}

async function dirEntries(uri: vscode.Uri): Promise<[string, vscode.FileType][]> {
  try {
    return await vscode.workspace.fs.readDirectory(uri);
  } catch {
    return [];
  }
}

function isSessionJson(name: string): boolean {
  return name.endsWith('.json') && !name.endsWith('.tmp');
}

export interface CopyResult {
  /** 實際複製成功的對話數。 */
  copied: number;
  /** 帳號已有同名、刻意不覆蓋而略過的數。 */
  skipped: number;
  /** 讀取/parse/寫入失敗的數（>0 表示綁定不完整、不可落鎖）。 */
  failed: number;
}

export async function copyProfileSessions(
  fromNs: string,
  toNs: string,
): Promise<CopyResult> {
  const src = sessionsDir(fromNs);
  const dest = sessionsDir(toNs);
  await vscode.workspace.fs.createDirectory(dest).then(undefined, () => {});
  const dec = new TextDecoder();
  let copied = 0;
  let skipped = 0;
  let failed = 0;
  for (const [name, type] of await dirEntries(src)) {
    if (type !== vscode.FileType.File || !isSessionJson(name)) continue;
    const destFile = vscode.Uri.joinPath(dest, name);
    try {
      await vscode.workspace.fs.stat(destFile);
      skipped++;
      continue; // 帳號已有同名，不覆蓋
    } catch {
      /* 不存在 → 複製 */
    }
    try {
      const buf = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(src, name));
      JSON.parse(dec.decode(buf)); // verify source
      await vscode.workspace.fs.writeFile(destFile, buf);
      copied++;
    } catch (e: any) {
      failed++;
      log.warn('profile:copy-session:skip', { name, detail: String(e?.message || e) });
    }
  }
  return { copied, skipped, failed };
}

export function isGuestMigrated(ctx: vscode.ExtensionContext): boolean {
  return ctx.globalState.get<boolean>(GUEST_MIGRATED_KEY) === true;
}

export function legacyGuestSessionsDir(ctx: vscode.ExtensionContext): vscode.Uri {
  return vscode.Uri.joinPath(ctx.globalStorageUri, 'sessions');
}

export async function migrateGuestData(ctx: vscode.ExtensionContext): Promise<void> {
  if (ctx.globalState.get<boolean>(GUEST_MIGRATED_KEY) === true) return;
  const oldDir = vscode.Uri.joinPath(ctx.globalStorageUri, 'sessions');
  const jsons = (await dirEntries(oldDir)).filter(
    ([n, t]) => t === vscode.FileType.File && isSessionJson(n),
  );
  if (jsons.length === 0) {
    // 新安裝、無舊資料 → 直接標記，免得每次啟動重掃。
    await ctx.globalState.update(GUEST_MIGRATED_KEY, true);
    return;
  }
  const dest = sessionsDir(PROFILE_GUEST);
  await vscode.workspace.fs.createDirectory(dest).then(undefined, () => {});
  const dec = new TextDecoder();
  let ok = 0;
  let failed = 0;
  for (const [name] of jsons) {
    const destFile = vscode.Uri.joinPath(dest, name);
    try {
      const buf = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(oldDir, name));
      JSON.parse(dec.decode(buf)); // verify source parseable
      await vscode.workspace.fs.writeFile(destFile, buf);
      const back = await vscode.workspace.fs.readFile(destFile);
      JSON.parse(dec.decode(back)); // verify dest written + parseable
      ok++;
    } catch (e: any) {
      failed++;
      log.warn('profile:migrate:fail', { name, detail: String(e?.message || e) });
    }
  }
  if (failed === 0) {
    await ctx.globalState.update(GUEST_MIGRATED_KEY, true);
    // 原檔刻意保留在 globalStorage 當備份（零遺失）；rootDir 已指 _guest 不會再讀它。
    log.info('profile:migrate:done', { migrated: ok, kept: 'globalStorage backup' });
  } else {
    // 不設 flag → 下次啟動重試（已成功的被「不重要」跳過、原檔全留）。
    log.warn('profile:migrate:partial', { ok, failed });
  }
}

export function getSystemPrompt(modeOrCommand: string): string {
  // Normalize legacy '/edit' command alias to 'edits'.
  const normalized = modeOrCommand === 'edit' ? 'edits' : modeOrCommand;
  if (isChatMode(normalized)) {
    return MODE_CONFIGS[normalized as ChatMode].systemPrompt;
  }
  return MODE_CONFIGS.chat.systemPrompt;
}

export interface ModelCapabilities {
  /** Anthropic extended thinking (claude-opus-4/sonnet-4-5/... family). */
  thinking: boolean;
  /**
   * [E 1.24.31] thinking 存在但「內建恆開、不可關」＝DeepSeek/openai-compat reasoning_content
   * 模型（API 不讀 req.thinking）。UI 顯示為唯讀資訊態（disabled+checked），避免假開關。
   * Anthropic extended thinking＝false（真開關、使用者可開可關）。
   */
  thinkingReadonly: boolean;
  /** OpenAI-style reasoning_effort (o1/o3/o4 reasoning models). */
  effort: boolean;
  /** Supports tool_use / function calling. */
  tools: boolean;
  /** Rough max_tokens cap (for budget clamping). */
  maxTokens: number;
}

const DEFAULT: ModelCapabilities = {
  thinking: false,
  thinkingReadonly: false,
  effort: false,
  tools: true,
  maxTokens: 8192,
};

const THINKING_PATTERNS: RegExp[] = [
  /^claude-opus-4([-.]|$)/i, // claude-opus-4, claude-opus-4-6, etc
  /^claude-sonnet-4([-.]|$)/i,
  /^claude-haiku-4([-.]|$)/i,
];

const REASONING_THINKING_PATTERNS: RegExp[] = [
  /^deepseek-reasoner/i,
  /^deepseek-v4-(pro|flash)/i,
  /(^|[-/])r1([-.]|$)/i, // DeepSeek-R1 系列
];

const NO_TOOLS_PATTERNS: RegExp[] = [
  /^o1-mini/i, // o1-mini doesn't support tools
  /^gpt-3\.5/i,
];

function stripPrefix(model: string): string {
  return model.replace(/^(anthropic|openai|gemma|ollama|deepseek)\//i, '');
}

export function getModelCapabilities(
  provider: Provider | undefined,
  model: string,
): ModelCapabilities {
  if (!provider || !model) return { ...DEFAULT };
  const bare = stripPrefix(model);

  // ai-king-backend routes on prefix — the real model lives under anthropic/ openai/ etc.
  // For backend, inspect the prefix to decide which feature set.
  const isBackend = provider.kind === 'ai-king-backend';
  const looksAnthropic =
    provider.kind === 'anthropic-direct' ||
    (isBackend && /^anthropic\//i.test(model));
  const looksOpenAI =
    (provider.kind === 'openai-compat' || provider.kind === 'custom') &&
    !/^anthropic\//i.test(model) ||
    (isBackend && /^(openai|deepseek)\//i.test(model)); // [E 1.24.31] backend deepseek 走 reasoning thinking

  const caps: ModelCapabilities = { ...DEFAULT };

  if (looksAnthropic) {
    caps.thinking = THINKING_PATTERNS.some((p) => p.test(bare));
    caps.tools = true;
    caps.maxTokens = /opus|sonnet/i.test(bare) ? 64000 : 8192;
  } else if (looksOpenAI) {
    caps.effort = EFFORT_PATTERNS.some((p) => p.test(bare));
    // [E 1.24.31] DeepSeek/openai-compat 思考型→thinking 顯示、但唯讀（內建恆開、API 不讀開關）。
    caps.thinking = REASONING_THINKING_PATTERNS.some((p) => p.test(bare));
    caps.thinkingReadonly = caps.thinking;
    caps.tools = !NO_TOOLS_PATTERNS.some((p) => p.test(bare));
    caps.maxTokens = caps.effort ? 32000 : 16384;
  } else {
    // Custom / ollama-local / unknown — conservative defaults.
    caps.tools = !NO_TOOLS_PATTERNS.some((p) => p.test(bare));
  }

  return caps;
}

const BUILTIN_ALLOW: ReadonlyArray<string> = [
  // 0.13.0 per-stack subdomains
  'account.ai-king.dev',   // 2026-06-17 帳號後端乾淨域名（user 換 sancio→account）
  'sancio.ai-king.dev',    // 向後相容：舊設定／數位人格 chat fallback 仍可能指這
  'ccc.ai-king.dev',
  'redigo.ai-king.dev',
  'perpetuo.ai-king.dev',
  'digital-human.ai-king.dev',
  // Backward compat (<=0.12.x)
  'sancio.mm9319.com',
  // Loopback / dev
  'localhost',
  '127.0.0.1',
  '::1',
  '[::1]',
];

export class EndpointNotAllowedError extends Error {
  constructor(
    public readonly host: string,
    message: string,
  ) {
    super(message);
    this.name = 'EndpointNotAllowedError';
  }
}

constructor(
  public readonly host: string,
  message: string,
) {
  super(message);
  this.name = 'EndpointNotAllowedError';
}

function loadUserHosts(): string[] {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const raw = cfg.get<unknown>('sancioAllowedHosts');
  if (!Array.isArray(raw)) return [];
  return raw.filter((h): h is string => typeof h === 'string' && h.length > 0);
}

function isLoopback(host: string): boolean {
  return (
    host === 'localhost' ||
    host === '127.0.0.1' ||
    host === '::1' ||
    host === '[::1]'
  );
}

export function assertSancioEndpointAllowed(endpoint: string): URL {
  let url: URL;
  try {
    url = new URL(endpoint);
  } catch (e: any) {
    const msg = `Sancio endpoint is not a valid URL: ${endpoint}`;
    log.error('sancio:endpoint:invalid', { endpoint, detail: String(e?.message || e) });
    throw new EndpointNotAllowedError(endpoint, msg);
  }

  const host = url.hostname;
  if (!host) {
    throw new EndpointNotAllowedError(endpoint, `Sancio endpoint has no host: ${endpoint}`);
  }

  // Scheme policy: https everywhere, except http on loopback for dev.
  if (url.protocol !== 'https:' && !(url.protocol === 'http:' && isLoopback(host))) {
    const msg =
      `Sancio endpoint scheme must be https (or http on loopback). Got ${url.protocol}//${host}`;
    log.error('sancio:endpoint:scheme', { endpoint, host, protocol: url.protocol });
    throw new EndpointNotAllowedError(host, msg);
  }

  const allow = new Set<string>([...BUILTIN_ALLOW, ...loadUserHosts()]);
  if (!allow.has(host)) {
    const msg =
      `Sancio endpoint host is not on the allow-list: ${host}. ` +
      `Add it to aiKing.sancioAllowedHosts if this is intentional.`;
    log.error('sancio:endpoint:host-denied', {
      host,
      allowedBuiltin: BUILTIN_ALLOW,
      allowedUser: loadUserHosts(),
    });
    throw new EndpointNotAllowedError(host, msg);
  }

  return url;
}

interface ModelFamily {
  /** 比對用：model id 轉小寫後 includes 任一即命中。 */
  match: string[];
  bio: string;
}

export function defaultProfileForModel(model?: string, providerName?: string): string {
  const id = String(model || '').toLowerCase();
  let bio = GENERIC;
  if (id) {
    for (const fam of FAMILIES) {
      if (fam.match.some((k) => id.includes(k))) { bio = fam.bio; break; }
    }
  }
  return bio;
}

export function defaultProfileForMember(backend?: string, type?: string): string {
  if (type === 'human') return '群組成員。';
  const slug = String(backend || '');
  if (!slug) return GENERIC;
  const model = slug.includes(':') ? slug.split(':').slice(1).join(':') : slug;
  return defaultProfileForModel(model);
}

export function loadProviders(): Provider[] {
  const config = vscode.workspace.getConfiguration('aiKing');
  const raw = config.get<unknown>('providers');
  if (!Array.isArray(raw)) return [];
  const out: Provider[] = [];
  for (const item of raw) {
    if (isProvider(item)) {
      out.push(item);
    }
  }
  return out;
}

export async function saveProviders(providers: Provider[]): Promise<void> {
  const config = vscode.workspace.getConfiguration('aiKing');
  await config.update('providers', providers, vscode.ConfigurationTarget.Global);
}

export function getActiveProviderId(ctx: vscode.ExtensionContext): string {
  return ctx.workspaceState.get<string>(ACTIVE_PROVIDER_KEY) || DEFAULT_PROVIDER_ID;
}

export async function setActiveProviderId(
  ctx: vscode.ExtensionContext,
  id: string,
): Promise<void> {
  await ctx.workspaceState.update(ACTIVE_PROVIDER_KEY, id);
}

export function getActiveModel(ctx: vscode.ExtensionContext): string {
