}

export function getLastMode(ctx: vscode.ExtensionContext): ChatMode {
  const v = ctx.workspaceState.get<string>(LAST_MODE_KEY);
  return isChatMode(v) ? v : DEFAULT_MODE;
}

export async function setLastMode(
  ctx: vscode.ExtensionContext,
  mode: ChatMode,
): Promise<void> {
  await ctx.workspaceState.update(LAST_MODE_KEY, mode);
  // 1.7.0: mirror into config so config-side readers (permission gate's
  // currentMode(), the auto-mode status bar listener) see UI mode switches.
  // The gate deliberately reads config to keep askPermission's signature
  // stable; without this mirror, picking Auto from the UI never reaches the
  // gate on the server-driven permission_ask path.
  try {
    await vscode.workspace
      .getConfiguration('aiKing')
      .update('lastMode', mode, vscode.ConfigurationTarget.Global);
  } catch {
    // Unregistered-key writes can fail on some builds — non-fatal; the
    // workspaceState value above stays the source of truth for the UI.
  }
}

export function findProvider(id: string, providers?: Provider[]): Provider | undefined {
  const list = providers || loadProviders();
  return list.find((p) => p.id === id);
}

export function getActiveProvider(
  ctx: vscode.ExtensionContext,
  providers?: Provider[],
): Provider | undefined {
  return findProvider(getActiveProviderId(ctx), providers);
}

export async function getProviderKey(
  ctx: vscode.ExtensionContext,
  providerId: string,
): Promise<string> {
  const v = await ctx.secrets.get(providerKeySecretName(providerId));
  return v || '';
}

export async function setProviderKey(
  ctx: vscode.ExtensionContext,
  providerId: string,
  key: string,
): Promise<void> {
  await ctx.secrets.store(providerKeySecretName(providerId), key);
}

export async function clearProviderKey(
  ctx: vscode.ExtensionContext,
  providerId: string,
): Promise<void> {
  await ctx.secrets.delete(providerKeySecretName(providerId));
}

export async function hasProviderKey(
  ctx: vscode.ExtensionContext,
  providerId: string,
): Promise<boolean> {
  const v = await ctx.secrets.get(providerKeySecretName(providerId));
  return !!v && v.length > 0;
}

export async function upsertProvider(patch: Provider): Promise<void> {
  const list = loadProviders();
  const idx = list.findIndex((p) => p.id === patch.id);
  if (idx >= 0) {
    // Preserve isBuiltin flag — user cannot toggle it via CRUD.
    const preserved = { ...patch, isBuiltin: list[idx].isBuiltin };
    list[idx] = preserved;
  } else {
    list.push({ ...patch, isBuiltin: false });
  }
  await saveProviders(list);
}

export async function patchProvider(
  id: string,
  patch: Partial<Provider>,
): Promise<void> {
  const list = loadProviders();
  const idx = list.findIndex((p) => p.id === id);
  if (idx < 0) throw new Error(`provider not found: ${id}`);
  const current = list[idx];
  const merged: Provider = {
    ...current,
    ...patch,
    id: current.id,
    isBuiltin: current.isBuiltin,
  };
  list[idx] = merged;
  await saveProviders(list);
}

export async function deleteProvider(
  ctx: vscode.ExtensionContext,
  id: string,
): Promise<void> {
  const list = loadProviders();
  const idx = list.findIndex((p) => p.id === id);
  if (idx < 0) return;
  if (list[idx].isBuiltin) {
    throw new Error(`cannot delete builtin provider: ${id}`);
  }
  list.splice(idx, 1);
  await saveProviders(list);
  await clearProviderKey(ctx, id);
}

function forceRefreshBuiltinFields(list: Provider[]): {
  next: Provider[];
  changedIds: string[];
} {
  const byId: Record<string, Provider> = {};
  for (const p of list) byId[p.id] = p;
  const changedIds: string[] = [];
  for (const b of BUILTIN_PROVIDERS) {
    const cur = byId[b.id];
    if (!cur) {
      byId[b.id] = { ...b };
      changedIds.push(b.id);
      continue;
    }
    // [b 2026-06-19 review LOW] 不覆寫使用者自訂的同 id 列：1.16.6 新增 groq/openrouter/moonshot/
    // alibaba/zhipu 五個 builtin，若使用者先前手動建了同 id 的自訂供應商（指向自架 proxy 等），
    // 不可被官方 endpoint/models 靜默改寫（金鑰仍 keyed by id、會被送去不同 host）。保留其設定。
    if (cur && !cur.isBuiltin) continue;
    // Only replace drift-prone fields. Keep isBuiltin true.
    const nextProv: Provider = {
      ...cur,
      name: b.name,
      kind: b.kind,
      endpoint: b.endpoint,
      authType: b.authType,
      models: [...b.models],
      notes: b.notes,
      // [b 2026-06-19] capabilities 為 builtin 定義欄，refresh 對齊 BUILTIN_PROVIDERS。
      capabilities: b.capabilities ? [...b.capabilities] : undefined,
      isBuiltin: true,
    };
    if (
      JSON.stringify(nextProv) !== JSON.stringify(cur)
    ) {
      byId[b.id] = nextProv;
      changedIds.push(b.id);
    }
  }
  return { next: Object.values(byId), changedIds };
}

export async function refreshBuiltinProviders(): Promise<string[]> {
  const list = loadProviders();
  const { next, changedIds } = forceRefreshBuiltinFields(list);
  if (changedIds.length > 0) await saveProviders(next);
  return changedIds;
}

async function scrubKeyMdFilePath(): Promise<void> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const inspected = cfg.inspect<string>('keyMdFilePath');
  // An explicit user-layer value (global or workspace) means the user already
  // chose a path — never override it.
  const hasExplicit =
    !!(inspected?.globalValue && inspected.globalValue.length > 0) ||
    !!(inspected?.workspaceValue && inspected.workspaceValue.length > 0) ||
    !!(inspected?.workspaceFolderValue && inspected.workspaceFolderValue.length > 0);
  if (hasExplicit) return;
  // [M15] No author path configured (the default build) → nothing to seed.
  if (!AUTHOR_KEY_MD_PATH) return;
  // Only the author's machine has this file → only there do we seed the path.
  if (!fs.existsSync(AUTHOR_KEY_MD_PATH)) return;
  await cfg.update('keyMdFilePath', AUTHOR_KEY_MD_PATH, vscode.ConfigurationTarget.Global);
}

export async function migrateToProviders(
  ctx: vscode.ExtensionContext,
): Promise<void> {
  const already = ctx.workspaceState.get<boolean>(MIGRATION_DONE_KEY);
  const existing = loadProviders();

  // If providers config is empty, seed with builtins.
  if (existing.length === 0) {
    await saveProviders(BUILTIN_PROVIDERS);
  } else {
    // 0.25.0 one-shot: drop the old Ollama builtin slot so the next
    // block can seed `gemma-4-local` cleanly.
    const v25done = ctx.workspaceState.get<boolean>(MIGRATION_V0_25_KEY);
    let working = existing;
    if (!v25done) {
      const before = working.length;
      working = working.filter((p) => p.id !== 'ollama-local');
      if (working.length !== before) {
        await clearProviderKey(ctx, 'ollama-local');
      }
      // Re-set active if user was pointing at the removed slot.
      const curActive = ctx.workspaceState.get<string>(ACTIVE_PROVIDER_KEY);
      if (curActive === 'ollama-local') {
        await ctx.workspaceState.update(
          ACTIVE_PROVIDER_KEY,
          DEFAULT_PROVIDER_ID,
        );
      }
      if (working.length !== before) await saveProviders(working);
      await ctx.workspaceState.update(MIGRATION_V0_25_KEY, true);
    }
    // Ensure all builtins exist (user may have deleted config; re-seed missing).
    const merged = [...working];
    let changed = false;
    for (const b of BUILTIN_PROVIDERS) {
      if (!merged.find((p) => p.id === b.id)) {
        merged.push(b);
        changed = true;
      }
    }
    if (changed) await saveProviders(merged);

    // 0.26.0 one-shot — force refresh drift-prone fields on all
    // builtins so ancient 0.5.0-seeded configs finally pick up the
    // current model lists / endpoints / notes.
    const v26done = ctx.workspaceState.get<boolean>(MIGRATION_V0_26_KEY);
    if (!v26done) {
      const refreshed = await refreshBuiltinProviders();
      if (refreshed.length > 0) {
        // Re-seed lost secret keys? No — SecretStorage is untouched.
      }
      await ctx.workspaceState.update(MIGRATION_V0_26_KEY, true);
    }

    // 1.6.11 one-shot — re-run forceRefresh so users already past v0_26
    // pick up the new DeepSeek builtin + refreshed model lists. The
    // "ensure builtins exist" loop above adds DeepSeek; this also rewrites
    // anthropic/openai/ai-king-backend model arrays to the new catalog.
    const v1611done = ctx.workspaceState.get<boolean>(MIGRATION_V1_6_11_KEY);
    if (!v1611done) {
      await refreshBuiltinProviders();
      await ctx.workspaceState.update(MIGRATION_V1_6_11_KEY, true);
    }

    // 1.7.0 one-shot — DeepSeek v4 rename + AI King Backend de-listing.
    const v170done = ctx.workspaceState.get<boolean>(MIGRATION_V1_7_0_KEY);
    if (!v170done) {
      // ① pull in DeepSeek v4 names (refreshBuiltinFields rewrites builtin rows).
      await refreshBuiltinProviders();
      // ② drop the user-config ai-king-backend row. Its SecretStorage key is
      //    intentionally LEFT in place so the provider can be revived later.
      const cur = loadProviders();
      const withoutBackend = cur.filter((p) => p.id !== 'ai-king-backend');
      if (withoutBackend.length !== cur.length) {
        await saveProviders(withoutBackend);
      }
      // ③ retarget active selection if it pointed at the removed backend.
      const curActiveProv = ctx.workspaceState.get<string>(ACTIVE_PROVIDER_KEY);
      const wasBackend = curActiveProv === 'ai-king-backend';
      if (wasBackend) {
        await ctx.workspaceState.update(ACTIVE_PROVIDER_KEY, DEFAULT_PROVIDER_ID);
      }
      const curActiveModel = ctx.workspaceState.get<string>(ACTIVE_MODEL_KEY);
      // Backend model ids carried an `anthropic/…`-style prefix. Reset ONLY
      // when the active provider really was the backend — a custom
      // openai-compat provider may legitimately serve slashed model ids
      // (e.g. `org/model`), and those must survive the upgrade untouched.
      if (wasBackend && typeof curActiveModel === 'string' && curActiveModel.includes('/')) {
        await ctx.workspaceState.update(ACTIVE_MODEL_KEY, DEFAULT_MODEL);
      }
      // ④ keyMdFilePath privacy scrub (PLAN §9.1). The package.json default was
      //    the author's private path `E:/Cursor/所有API.md`; it is now `""` so
      //    no private path ships in the vsix. To keep the AUTHOR's machine
      //    behaving identically, write that path into the user-level settings
      //    once — but ONLY if (a) the user layer has no explicit value AND
      //    (b) the file actually exists on this disk (= this is the author's
      //    box). Everyone else's machine lacks the file → skipped → never gets
      //    this path written into their settings.
      await scrubKeyMdFilePath();
      await ctx.workspaceState.update(MIGRATION_V1_7_0_KEY, true);
    }

    // 1.8.0 one-shot — seven-vendor builtin catalog (PLAN §10.5b). The
    // "ensure builtins exist" loop above already appends the brand-new
    // gemini / xai / mistral rows; this refresh additionally rewrites the
    // drift-prone fields of existing builtin rows so users who upgraded get
    // the new openai gpt-5.x seed list (their modelNotes / keys stay put).
    const v180done = ctx.workspaceState.get<boolean>(MIGRATION_V1_8_0_KEY);
    if (!v180done) {
      await refreshBuiltinProviders();
      await ctx.workspaceState.update(MIGRATION_V1_8_0_KEY, true);
    }

    // 1.8.0b one-shot — builtin display names lost the "(direct)/(local)"
    // suffixes (user: 懂得都懂，無用資訊). Same refresh push for installs
    // that already consumed v1_8_0 before the rename landed.
    const v180bDone = ctx.workspaceState.get<boolean>('aiKing.providers.migrated.v1_8_0b');
    if (!v180bDone) {
      await refreshBuiltinProviders();
      await ctx.workspaceState.update('aiKing.providers.migrated.v1_8_0b', true);
    }

    // 1.8.2 one-shot — DeepSeek drops its Chinese suffix（'DeepSeek 深度求索'
    // → 'DeepSeek'，user: 品牌有英文就好）. Force one more name refresh for
    // installs that already consumed v1_8_0b before this rename.
    const v182Done = ctx.workspaceState.get<boolean>('aiKing.providers.migrated.v1_8_2');
    if (!v182Done) {
      await refreshBuiltinProviders();
      await ctx.workspaceState.update('aiKing.providers.migrated.v1_8_2', true);
    }

    // [b 2026-06-19] 1.16.6 one-shot — 全供應商擴充（groq / openrouter / moonshot /
    // alibaba(Qwen) / zhipu(GLM)）＋ capabilities 欄。上面「ensure builtins exist」迴圈會
    // 把新家補進名冊；此 refresh 另把 capabilities 對齊 BUILTIN_PROVIDERS。既有使用者升級即得，
    // 不必重裝；modelNotes / SecretStorage 金鑰不動。
    const v1166Done = ctx.workspaceState.get<boolean>('aiKing.providers.migrated.v1_16_6');
    if (!v1166Done) {
      await refreshBuiltinProviders();
      await ctx.workspaceState.update('aiKing.providers.migrated.v1_16_6', true);
    }
  }

  // Migrate legacy secrets to new provider key slots.
  // Non-destructive: legacy keys are NOT deleted.
  if (!already) {
    const legacyAnthropic = await ctx.secrets.get(LEGACY_ANTHROPIC_SECRET);
    if (legacyAnthropic && legacyAnthropic.length > 0) {
      // Same key works for both ai-king-backend (BYOK forwarding) and direct anthropic.
      await setProviderKey(ctx, 'ai-king-backend', legacyAnthropic);
      await setProviderKey(ctx, 'anthropic', legacyAnthropic);
    }
    const legacyOpenai = await ctx.secrets.get(LEGACY_OPENAI_SECRET);
    if (legacyOpenai && legacyOpenai.length > 0) {
      await setProviderKey(ctx, 'openai', legacyOpenai);
    }

    // Seed active selection if missing.
    const curProvider = ctx.workspaceState.get<string>(ACTIVE_PROVIDER_KEY);
    if (!curProvider) {
      await setActiveProviderId(ctx, DEFAULT_PROVIDER_ID);
    }
    const curModel = ctx.workspaceState.get<string>(ACTIVE_MODEL_KEY);
    if (!curModel) {
      await setActiveModel(ctx, DEFAULT_MODEL);
    }
    const curMode = ctx.workspaceState.get<string>(LAST_MODE_KEY);
    if (!isChatMode(curMode)) {
      await setLastMode(ctx, DEFAULT_MODE);
    }

    await ctx.workspaceState.update(MIGRATION_DONE_KEY, true);
  }
}

export function resolveOnWireModel(provider: Provider, uiModel: string): string {
  if (provider.kind === 'ai-king-backend') {
    return uiModel;
  }
  // Strip any known provider prefix.
  return uiModel.replace(/^(anthropic|openai|gemma|ollama)\//, '');
}

export function providerLabel(provider: Provider): string {
  switch (provider.kind) {
    case 'ai-king-backend':
      return 'AI King Backend';
    case 'anthropic-direct':
      return 'Anthropic Direct';
    case 'openai-compat':
      return provider.name;
    case 'custom':
      return provider.name;
  }
}

export function providerRequiresKey(provider: Provider): boolean {
  return provider.authType !== 'none';
}

export interface ProbeResult {
  ok: boolean;
  message: string; // 人話 zh-TW（例 "HTTP 401 金鑰無效"）
  detectedModels?: string[]; // GET /v1/models 成功時的上游 model id 清單
  checkedAt: number; // Date.now()
}

function probeUrl(p: Provider): string {
  const base = p.endpoint.replace(/\/$/, '');
  const baseNoV1 = base.replace(/\/v1\/?$/, '');
  if (p.kind === 'ai-king-backend') {
    // Backend probe: prefer /v1/models, fall back to /health (PLAN §1.2).
    return `${baseNoV1}/v1/models`;
  }
  if (p.kind === 'anthropic-direct') {
    return `${base}/v1/models`;
  }
  // openai-compat + custom — base may already end in /v1 (OpenAI, xAI,
  // Mistral, Ollama), or be a versioned compat layer that serves /models
  // directly off its root, like Gemini's …/v1beta/openai/ (PLAN §10.5:
  // 七家 probe 端點全走 GET {base}/models). Bare hosts get /v1/models.
  if (base.endsWith('/v1') || /\/v\d+[a-z]*\/openai$/i.test(base)) {
    return `${base}/models`;
  }
  return `${base}/v1/models`;
}

function authHeaders(p: Provider, apiKey: string): Record<string, string> {
  const headers: Record<string, string> = {};
  if (p.authType === 'bearer' && apiKey) {
    headers['Authorization'] = `Bearer ${apiKey}`;
  }
  if (p.authType === 'x-api-key' && apiKey) {
    headers['x-api-key'] = apiKey;
    // api.anthropic.com/v1/models requires the version header.
    headers['anthropic-version'] = '2023-06-01';
  }
  return headers;
}

function parseDetectedModels(body: unknown): string[] | undefined {
  if (!body || typeof body !== 'object') return undefined;
  const data = (body as Record<string, unknown>).data;
  if (!Array.isArray(data)) return undefined;
  const ids: string[] = [];
  for (const item of data) {
    if (item && typeof item === 'object') {
      const id = (item as Record<string, unknown>).id;
      if (typeof id === 'string') ids.push(id);
    }
  }
  return ids.length > 0 ? ids : undefined;
}

function humanMessage(status: number, ok: boolean, url: string): string {
  if (!ok) return `HTTP ${status}（端點不通：${url}）`;
  if (status === 401) return `HTTP 401 金鑰無效`;
  if (status === 403) return `HTTP 403 金鑰無權限`;
  return `HTTP ${status} 連線正常`;
}

export async function probeProvider(p: Provider, apiKey: string): Promise<ProbeResult> {
  const checkedAt = Date.now();
  const url = probeUrl(p);
  try {
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), PROBE_TIMEOUT_MS);
    let resp: Response;
    try {
      resp = await fetch(url, {
        method: 'GET',
        headers: authHeaders(p, apiKey),
        signal: ctl.signal,
      });
    } finally {
      clearTimeout(t);
    }
    const ok = resp.ok || resp.status === 401 || resp.status === 403;
    let detectedModels: string[] | undefined;
    if (resp.ok) {
      try {
        const json = await resp.json();
        detectedModels = parseDetectedModels(json);
      } catch {
        // body not JSON (e.g. Ollama "Ollama is running") — still reachable.
      }
    }
    return { ok, message: humanMessage(resp.status, ok, url), detectedModels, checkedAt };
  } catch (e: any) {
    const raw = e?.message || String(e);
    const message = /abort/i.test(raw) ? `逾時（${PROBE_TIMEOUT_MS / 1000}s 無回應）` : raw;
    return { ok: false, message, checkedAt };
  }
}

export class ProviderStatusStore {
  private cache = new Map<string, ProbeResult>();
  private inflight = new Map<string, Promise<ProbeResult>>();
  private readonly _onDidChange = new vscode.EventEmitter<string>();
  readonly onDidChange: vscode.Event<string> = this._onDidChange.event;

  get(providerId: string): ProbeResult | undefined {
    return this.cache.get(providerId);
  }

  /** Probe a provider; returns cached result if within TTL (unless force). */
  async probe(provider: Provider, apiKey: string, force = false): Promise<ProbeResult> {
    const id = provider.id;
    const cached = this.cache.get(id);
    if (!force && cached && Date.now() - cached.checkedAt < TTL_MS) {
      return cached;
    }
    // Coalesce concurrent probes for the same provider.
    const existing = this.inflight.get(id);
    if (existing && !force) return existing;

    const run = probeProvider(provider, apiKey).then((res) => {
      this.cache.set(id, res);
      this.inflight.delete(id);
      this._onDidChange.fire(id);
      return res;
    });
    this.inflight.set(id, run);
    return run;
  }

  /** Drop cached status for a provider (call on key / endpoint change). */
  invalidate(providerId: string): void {
    this.cache.delete(providerId);
    this.inflight.delete(providerId);
    this._onDidChange.fire(providerId);
  }

  dispose(): void {
    this._onDidChange.dispose();
  }
}

get(providerId: string): ProbeResult | undefined {
  return this.cache.get(providerId);
}

async probe(provider: Provider, apiKey: string, force = false): Promise<ProbeResult> {
  const id = provider.id;
  const cached = this.cache.get(id);
  if (!force && cached && Date.now() - cached.checkedAt < TTL_MS) {
    return cached;
  }
  // Coalesce concurrent probes for the same provider.
  const existing = this.inflight.get(id);
  if (existing && !force) return existing;

  const run = probeProvider(provider, apiKey).then((res) => {
    this.cache.set(id, res);
    this.inflight.delete(id);
    this._onDidChange.fire(id);
    return res;
  });
  this.inflight.set(id, run);
  return run;
}

invalidate(providerId: string): void {
  this.cache.delete(providerId);
  this.inflight.delete(providerId);
  this._onDidChange.fire(providerId);
}

dispose(): void {
  this._onDidChange.dispose();
}

export interface AvailableModel {
  providerId: string;
  providerName: string;
  model: string;
  note?: string; // provider.modelNotes[model]
  display: string; // note ? `${model} (${note})` : 撞名 `${model} (${providerName})` : model
  verified: boolean; // from detectedModels → true; seed fallback (no list) → true（無從驗）
  // [1.8.0] 聊天/圖像分流（PLAN §10.5）：image 模型保留給圖像功能（§10.8），
  // 不進聊天 Model 選單；非聊天模型（embed/whisper/tts…）整個剔除不會出現。
  kind: 'chat' | 'image';
}

function classifyModel(id: string, isOllama: boolean): 'chat' | 'image' | null {
  if (IMAGE_MODEL_RE.test(id)) return 'image';
  if (isOllama) return 'chat';
  if (NON_CHAT_MODEL_RE.test(id)) return null;
  return 'chat';
}

function isOllamaProvider(p: Provider): boolean {
  return p.id === 'ollama-local' || /:11434(\/|$)/.test(p.endpoint);
}

interface AvailableModelsCtx {
  ctx: vscode.ExtensionContext;
  store: ProviderStatusStore;
  /**
   * [1.8.4] 本地優先：false = 首屏快路徑，**不發網路 probe**，只讀已快取結果；
   * 沒快取的 keyed provider 直接樂觀顯示其 curated 模型（不等 5s timeout）。
   * 之後背景再用 allowNetwork=true 重跑精修（移除離線的、補上 detected）。
   * 預設 true（維持舊行為）。
   */
  allowNetwork?: boolean;
}

export async function getAvailableModels(args: AvailableModelsCtx): Promise<AvailableModel[]> {
  const { ctx, store } = args;
  const allowNetwork = args.allowNetwork !== false;
  const providers = loadProviders();

  // Pass 1: probe every provider that has a key (or needs none).
  // [1.8.4] allowNetwork=false（首屏）→ 不發網路：用已快取的 probe；沒快取就
  // 樂觀當「已連線、無偵測清單」(Pass 2 會 fall 到 curated 全列)，讓下拉首屏即填。
  const probes = new Map<string, ProbeResult>();
  for (const p of providers) {
    const keyless = p.authType === 'none';
    const hasKey = keyless ? true : await hasProviderKey(ctx, p.id);
    if (!hasKey) continue;
    if (allowNetwork) {
      const apiKey = keyless ? '' : await getProviderKey(ctx, p.id);
      const res = await store.probe(p, apiKey);
      if (res.ok) probes.set(p.id, res);
    } else {
      const cached = store.get(p.id);
      if (cached) {
        if (cached.ok) probes.set(p.id, cached);
      } else {
        // 沒快取 → 樂觀顯示 curated（不等網路）。標 checkedAt:0 = 未驗證。
        probes.set(p.id, { ok: true, message: '本機（未即時驗證）', checkedAt: 0 });
      }
    }
  }

  // Pass 2: resolve each connected provider's candidate models.
  interface Candidate {
    model: string;
    kind: 'chat' | 'image';
    verified: boolean;
  }
  const candidates = new Map<string, Candidate[]>();
  for (const p of providers) {
    const probe = probes.get(p.id);
    if (!probe) continue;
    const ollama = isOllamaProvider(p);
    const list: Candidate[] = [];
    const detected = probe.detectedModels;
    const detectedSet = new Set(detected || []);
    // [1.8.2] 統一母版：CONNECTED 的 provider 一律列出**全部 curated（勾選）模型**。
    // 偵測（detectedModels）只當「輔助驗證標記」(settings 標 ✓/？)，**永不當過濾器**
    // ——否則 curated 名稱跟上游 /v1/models 對不上時（2026 placeholder 名、本地模型、
    // 端點不乾淨吐 /models）整組 provider 會從選單神隱（OpenAI 案：5 個可見模型、
    // 已連線，選單卻沒這組）。舊的「curated ∩ detected」硬過濾正是這 bug。
    // 對 ALL provider 一致：有 curated → 列 curated；無 curated → 退偵測清單
    //（Ollama / 新 custom）；連偵測都沒 → builtin 種子保底。
    let chosen: string[];
    if (p.models.length > 0) {
      chosen = p.models;
    } else if (detected && detected.length > 0) {
      chosen = [...detected].sort((a, b) => a.localeCompare(b));
    } else if (p.isBuiltin) {
      const seedProvider = BUILTIN_PROVIDERS.find((b) => b.id === p.id);
      chosen = seedProvider ? seedProvider.models : [];
    } else {
      chosen = [];
    }
    // [A9 圖像槽位補列] image 模型是獨立槽位（/image 指令用），不該被「curated 只放 chat
    // 模型」過濾掉。把 detected 裡分類為 image、卻不在 chosen 的補進來——解 Gemini/Grok 等
    // curated 無圖像模型的 provider 連線了、☰ 選單圖像下拉卻空白（OpenAI 的 gpt-image-2 已
    // 在 curated 故本就出現；此補列救的是 curated 沒列圖像模型的家）。concat 建新陣列、不
    // 污染 p.models 引用。
    if (detected && detected.length > 0) {
      const extraImages = detected.filter(
        (dm) => classifyModel(dm, ollama) === 'image' && !chosen.includes(dm),
      );
      if (extraImages.length > 0) chosen = chosen.concat(extraImages);
    }
    const seen = new Set<string>();
    for (const m of chosen) {
      if (seen.has(m)) continue;
      seen.add(m);
      const kind = classifyModel(m, ollama);
      // verified = 上游 /v1/models 確實列出此 model（純資訊，不影響是否顯示）。
      if (kind) list.push({ model: m, kind, verified: detectedSet.has(m) });
    }
    candidates.set(p.id, list);
  }

  // Pass 3: count model-name occurrences across connected providers so the
  // display string can disambiguate cross-provider clashes.
  const nameCount = new Map<string, number>();
  for (const list of candidates.values()) {
    for (const c of list) {
      nameCount.set(c.model, (nameCount.get(c.model) || 0) + 1);
    }
  }

  // Pass 4: emit.
  const out: AvailableModel[] = [];
  for (const p of providers) {
    const list = candidates.get(p.id);
    if (!list) continue;
    for (const c of list) {
      const rawNote = p.modelNotes?.[c.model];
      const note = rawNote && rawNote.trim().length > 0 ? rawNote : undefined;
      let display: string;
      if (note) {
        display = `${c.model} (${note})`;
      } else if ((nameCount.get(c.model) || 0) > 1) {
        display = `${c.model} (${p.name})`;
      } else {
        display = c.model;
      }
      if (c.kind === 'image') display = `🖼 ${display}`;
      out.push({
        providerId: p.id,
        providerName: p.name,
        model: c.model,
        note,
        display,
        verified: c.verified,
        kind: c.kind,
      });
    }
  }
  return out;
}

interface Candidate {
  model: string;
  kind: 'chat' | 'image';
  verified: boolean;
}

export function currentSelection(ctx: vscode.ExtensionContext): {
  providerId: string;
  model: string;
} {
  return { providerId: getActiveProviderId(ctx), model: getActiveModel(ctx) };
}

export interface Provider {
  id: string; // slug, e.g. "anthropic", "my-ollama"
  name: string; // display name
  kind: ProviderKind;
  endpoint: string; // full base URL
  authType: AuthType;
  models: string[]; // user-curated model ids
  isBuiltin: boolean; // builtin cannot be deleted, but can be edited
  notes?: string; // provider-level note (existing — kept)
  // [1.7.0] per-model note, key = model id. User data — NEVER overwritten by
  // forceRefreshBuiltinFields(). Surfaced in the model picker as `model (note)`.
  modelNotes?: Record<string, string>;
  // [b 2026-06-19] 能力標籤（過濾用）。未標時視為 ['chat']。
  capabilities?: ProviderCapability[];
}

export function isProvider(v: unknown): v is Provider {
  if (!v || typeof v !== 'object') return false;
  const p = v as Record<string, unknown>;
  // modelNotes is optional; if present it must be a plain object.
  if (
    p.modelNotes !== undefined &&
    (typeof p.modelNotes !== 'object' || p.modelNotes === null || Array.isArray(p.modelNotes))
  ) {
    return false;
  }
  // [b] capabilities optional; if present it must be an array.
  if (p.capabilities !== undefined && !Array.isArray(p.capabilities)) {
    return false;
  }
  return (
    typeof p.id === 'string' &&
    typeof p.name === 'string' &&
    typeof p.kind === 'string' &&
    typeof p.endpoint === 'string' &&
    typeof p.authType === 'string' &&
    Array.isArray(p.models) &&
    typeof p.isBuiltin === 'boolean'
  );
}

