    name: 'Zhipu (GLM)',
    kind: 'openai-compat',
    // ⛔ 非標準路徑：GLM OpenAI 相容層在 /api/paas/v4（已含在 endpoint）。
    endpoint: 'https://open.bigmodel.cn/api/paas/v4',
    authType: 'bearer',
    models: ['glm-4.6', 'glm-4-plus'],
    isBuiltin: true,
    notes: '智譜 GLM。中文對話、推理、工具調用。Key from open.bigmodel.cn/usercenter/apikeys。',
    capabilities: ['chat', 'vision', 'tools'],
  },
];

export function providerKeySecretName(id: string): string {
  return `aiKing.providers.${id}.apiKey`;
}

export interface SessionMessage {
  role: 'system' | 'user' | 'assistant' | 'tool';
  content: string;
  /** For tool role messages, the tool_call_id that produced this result. */
  toolCallId?: string;
  /** For assistant messages that requested tool calls. */
  toolCalls?: Array<{
    id: string;
    name: string;
    arguments: string; // JSON string
  }>;
  /** Wall-clock timestamp (ms since epoch). */
  ts: number;
  // ── [身分凍結 A] 只對 role==='assistant' 寫；在 append 那一刻凍結，永不回改 ──
  /**
   * 凍結身分指針。決定 `color(authorId)` 與暱稱查找 key。一個對話 = 一個 authorId
   * （= `local:<agentUid>`，對話建立時定、整個對話不變）。換 model / 換 Agent 都
   * **不動** authorId → 歷史訊息身分凍結、改名只動 agentNicknames[authorId] 套全歷史。
   */
  authorId?: string;
  /** 凍結預設名（無暱稱時的 fallback；ACP 對話 host 會 stamp 成代理 label）。 */
  authorName?: string;
  /** 凍結引擎副標（灰色 `· gpt-4o`）。歷史保真：模型下架後仍顯示當時引擎。 */
  authorSub?: string;
  /**
   * [D thinking 秒數 1.24.31] 該 assistant 訊息的思考耗時（毫秒）。與 content 解耦、不污染
   * `<think>` 文字（零正則風險）。DeepSeek/openai-compat reasoning_content 路徑量測（首個
   * reasoning frame → 首個 content frame）。舊訊息無此欄＝undefined→顯 0.0 秒（向後相容）；
   * Anthropic clean 棧目前不產 thinking 區塊、不寫此欄（另開單）。
   */
  thinkingMs?: number;
  /**
   * [統一母版] 凍結「種類圖示」檔名（media/icons/ 下，如 external.svg / base.svg）。
   * 對齊群組三段式 `[種類圖示][供應商logo][model]`——換 Agent 後舊訊息圖示不跳。
   */
  authorKindLogo?: string;
  /**
   * [統一母版] 凍結「供應商 logo」檔名（如 provider-anthropic.svg）。內建走 provider.logo、
   * ACP 走 acpProviderLogo；host 才有 catalog 故由 host stamp。空＝不顯示（render fallback）。
   */
  authorProvLogo?: string;
}

export interface AuthorStamp {
  authorId: string;
  authorName: string;
  authorSub: string;
  /** [統一母版] 種類圖示檔名（resolveCurrentAuthor 由 stack 算）。 */
  kindLogo: string;
  /** [統一母版] 供應商 logo 檔名（host 用 catalog/acpProviderLogo 覆蓋；預設空）。 */
  provLogo: string;
}

export interface Session {
  id: string;
  title: string;
  createdAt: number;
  updatedAt: number;
  model: string;
  stack: string;
  /** v0.5.0+: per-session chat mode (chat/edits/plan). Defaults to 'edits'. */
  mode: ChatMode;
  /** v0.5.0+: provider id that this session was created against. */
  providerId?: string;
  /**
   * @deprecated [身分凍結 A] 被 `agentNicknames` 取代。保留「讀」供 migration 遷移；
   * 首次寫 agentNicknames 時把它搬進 `agentNicknames[authorId]` 並刪除（禁新舊並存，
   * 紅隊 S-3 / memory「過時情報三防」）。新代碼一律不寫 aiName。
   */
  aiName?: string;
  /**
   * [身分凍結 A] 對話級穩定身分種子。session 建立時生成一次，**整個對話不 rotate**
   * （user directive：換 model / 換 Agent 都「下一個對話才換身分」，當前對話身分完全
   * 凍結；要換身分＝開新對話＝新 agentUid＝新 color）。authorId = `local:<agentUid>`。
   * ⚠ 對 artifact「換 stack 大類就當場 rotate」的調整：當場 rotate 會讓同一對話前後段
   * 變兩色兩名，違反 user「換 Agent 也不在當前對話換身分」。Sources 優先序：user 當場
   * 明說 > artifact 設計。
   */
  agentUid?: string;
  /**
   * [身分凍結 A] `authorId → 暱稱` 活查找表。改名只動這裡（同 authorId 全歷史套新名）。
   * 只增不刪會在長壽 session 累積孤兒 → load / 改名時 prune（只留仍被訊息引用 ∪ 當前
   * authorId，紅隊 MF-4 + user 反熵鐵律）。
   */
  agentNicknames?: Record<string, string>;
  /**
   * [1.8.2] per-conversation AI avatar — a 'store:<rel>' marker (file under
   * globalStorage/avatars) or a URL/data URI. Resolved by chat-panel before
   * postState. Empty ⇒ the master falls back to the hashed robot.
   */
  aiAvatar?: string;
  /**
   * [1.9.3] per-conversation AI 簡介（個資）。空 ⇒ chat-panel postState 以模型本身的
   * 角色/特長當預設帶出（defaultProfileForModel）。只有使用者真的編輯過才寫進這裡。
   */
  aiBio?: string;
  messages: SessionMessage[];
}

export interface SessionSummary {
  id: string;
  title: string;
  updatedAt: number;
  messageCount: number;
  model: string;
  stack: string;
  mode: ChatMode;
  providerId?: string;
}

function genId(): string {
  // 12 hex chars from timestamp + 8 from crypto random. No npm deps.
  const t = Date.now().toString(16).padStart(12, '0');
  const r = Math.floor(Math.random() * 0xffffffff).toString(16).padStart(8, '0');
  return `${t}-${r}`;
}

function authorIdFor(session: Pick<Session, 'id' | 'agentUid'>): string {
  return `local:${session.agentUid || session.id}`;
}

function pruneAgentNicknames(session: Session): void {
  if (!session.agentNicknames) return;
  const live = new Set<string>([authorIdFor(session)]);
  for (const m of session.messages) {
    if (m.role === 'assistant' && m.authorId) live.add(m.authorId);
  }
  for (const key of Object.keys(session.agentNicknames)) {
    if (!live.has(key)) delete session.agentNicknames[key];
  }
}

function migrateIdentity(s: Session): void {
  if (!s.agentUid) s.agentUid = s.id;
  if (!s.agentNicknames) s.agentNicknames = {};
  const authorId = authorIdFor(s);
  if (s.aiName && s.aiName.trim()) {
    if (!s.agentNicknames[authorId]) s.agentNicknames[authorId] = s.aiName.trim();
    delete s.aiName;
  }
  const sub = s.model || '';
  const fallbackName = s.agentNicknames[authorId] || s.model || '';
  // [統一母版] 舊訊息回推種類圖示用「當前 stack」（多數對話 stack 不變、合理降級）；
  // 供應商 logo 舊訊息當時沒記、無從精準回推 → 留空（render 自動隱藏，歷史保真不亂掰）。
  const fallbackKindLogo = logoForAgentKind(agentKindForStack(s.stack));
  for (const m of s.messages) {
    if (m.role === 'assistant' && !m.authorId) {
      m.authorId = authorId;
      m.authorName = fallbackName;
      m.authorSub = sub;
      if (!m.authorKindLogo && fallbackKindLogo) m.authorKindLogo = fallbackKindLogo;
    }
  }
  pruneAgentNicknames(s);
}

function autoTitle(firstUserMessage: string): string {
  const firstLine = firstUserMessage
    .trim()
    .split(/\r?\n/, 1)[0]
    .replace(/\s+/g, ' ')
    .trim();
  if (!firstLine) return 'Untitled session';
  let width = 0;
  let out = '';
  for (const ch of firstLine) {
    width += CJK_RE.test(ch) ? 1 : 0.5;
    if (width > TITLE_WIDTH_CAP) return `${out.trimEnd()}…`;
    out += ch;
  }
  return out;
}

async function ensureDir(uri: vscode.Uri): Promise<void> {
  try {
    await vscode.workspace.fs.createDirectory(uri);
  } catch (e: any) {
    // createDirectory is idempotent on modern VS Code builds; swallow EEXIST.
    if (e?.code !== 'FileExists' && e?.code !== 'EEXIST') {
      // Some fs providers throw generic errors; log but don't abort.
      console.warn(`[ai-king] ensureDir failed: ${e?.message || String(e)}`);
    }
  }
}

export class SessionStore {
  // [1.14.0 帳號線 P1a] rootDir 改成可隨 profile 命名空間切換（不再 readonly 寫死
  // globalStorage）。資料根統一到 ~/.aiking/profiles/<ns>/sessions（ns 預設訪客
  // _guest；登入後 setNamespace(<accountId>) 切到帳號 profile）。
  private rootDir: vscode.Uri;
  private namespace: string = PROFILE_GUEST;
  private readonly textEncoder = new TextEncoder();
  private readonly textDecoder = new TextDecoder();
  private readonly _onDidChange = new vscode.EventEmitter<void>();
  readonly onDidChange = this._onDidChange.event;

  constructor(private readonly ctx: vscode.ExtensionContext) {
    this.rootDir = sessionsDir(this.namespace);
  }

  /** 當前 profile 命名空間（_guest 或 <accountId>）。 */
  getNamespace(): string {
    return this.namespace;
  }

  /**
   * [1.14.0 帳號線 P1a] 切換 profile 命名空間：重算 rootDir → 建目錄 → fire onDidChange
   * 讓 home-view / 各 ChatPanel 重繪（store 無記憶體快取，換 rootDir 即生效）。登入呼
   * setNamespace(<accountId>)、登出呼 setNamespace('_guest')。
   *
   * [1.14.0 對抗審查 critical#3] 回傳「是否真的切換了 namespace」：呼叫端（啟動校正）只在
   * true 時才 closeAll 對話面板＋校正 active 指標——namespace 沒變時 serializer 剛 revive 的
   * 面板必須保留，否則每次開 VS Code 對話視窗會閃一下就被無條件 closeAll 關掉。
   */
  async setNamespace(ns: string): Promise<boolean> {
    const next = sanitizeNs(ns);
    if (next === this.namespace) return false;
    this.namespace = next;
    this.rootDir = sessionsDir(next);
    await this.init();
    this._onDidChange.fire();
    return true;
  }

  /**
   * [1.14.0 對抗審查 high — fail-safe] 訪客 namespace 且一次性遷移尚未成功時，舊扁平
   * globalStorage/sessions 仍是真實來源 → 回傳它當影子來源讓 list()/load() 回退讀。
   * 遷移成功或已切到帳號 profile ⇒ null（rootDir 是唯一真相，不回退避免讀到重複/過期）。
   * 沒有這條，當 ~/.aiking 寫不了（權限/磁碟滿/dataHome 唯讀）遷移失敗時，rootDir 指向空的
   * 新目錄、list() 只讀它 ⇒ 使用者看到空清單＝「對話全消失」（檔其實還在舊目錄、只是讀不到）。
   */
  private guestFallbackDir(): vscode.Uri | null {
    if (this.namespace !== PROFILE_GUEST) return null;
    if (isGuestMigrated(this.ctx)) return null;
    return legacyGuestSessionsDir(this.ctx);
  }

  /** Must be called once at activation (creates storage dir if missing). */
  async init(): Promise<void> {
    // globalStorageUri 仍是頭像 / compact-archive / checkpoints 的父目錄（P1a 未搬），保留。
    await ensureDir(this.ctx.globalStorageUri);
    // rootDir = ~/.aiking/profiles/<ns>/sessions；createDirectory 遞迴建中間層。
    await ensureDir(this.rootDir);
  }

  private fileFor(id: string): vscode.Uri {
    return vscode.Uri.joinPath(this.rootDir, `${id}.json`);
  }

  private tmpFor(id: string): vscode.Uri {
    return vscode.Uri.joinPath(this.rootDir, `${id}.json.tmp`);
  }

  /** Lightweight list; reads each file but skips message content for speed. */
  async list(): Promise<SessionSummary[]> {
    await this.init();
    const seen = new Set<string>();
    const summaries: SessionSummary[] = [];
    const scan = async (dir: vscode.Uri): Promise<void> => {
      let entries: [string, vscode.FileType][];
      try {
        entries = await vscode.workspace.fs.readDirectory(dir);
      } catch {
        return;
      }
      for (const [name, type] of entries) {
        if (type !== vscode.FileType.File) continue;
        if (!name.endsWith('.json') || name.endsWith('.tmp')) continue;
        const id = name.slice(0, -5);
        if (seen.has(id)) continue; // rootDir 先掃、優先；fallback 同 id 跳過
        try {
          const session = await this.load(id);
          if (session) {
            seen.add(id);
            summaries.push({
              id: session.id,
              title: session.title,
              updatedAt: session.updatedAt,
              messageCount: session.messages.length,
              model: session.model,
              stack: session.stack,
              mode: session.mode || DEFAULT_MODE,
              providerId: session.providerId,
            });
          }
        } catch (e) {
          console.warn(`[ai-king] skip corrupt session ${id}: ${e}`);
        }
      }
    };
    await scan(this.rootDir);
    // [1.14.0 fail-safe] 訪客且遷移未成功時，補掃舊扁平 globalStorage/sessions（影子來源），
    // 保證遷移失敗仍看得到舊對話、不會空清單像消失。
    const fb = this.guestFallbackDir();
    if (fb) await scan(fb);
    summaries.sort((a, b) => b.updatedAt - a.updatedAt);
    return summaries;
  }

  async load(id: string): Promise<Session | null> {
    const primary = await this.loadFrom(this.rootDir, id);
    if (primary) return primary;
    // [1.14.0 fail-safe] rootDir 找不到 + 訪客且遷移未成功 → 回退讀舊扁平 globalStorage/sessions。
    const fb = this.guestFallbackDir();
    if (fb) return this.loadFrom(fb, id);
    return null;
  }

  private async loadFrom(dir: vscode.Uri, id: string): Promise<Session | null> {
    try {
      const buf = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(dir, `${id}.json`));
      const text = this.textDecoder.decode(buf);
      const parsed = JSON.parse(text) as Session;
      // Minimal shape validation; tolerate missing optional fields.
      if (!parsed || typeof parsed.id !== 'string' || !Array.isArray(parsed.messages)) {
        return null;
      }
      // Migration: legacy sessions have no `mode` field — default to 'edits'.
      // 1.7.0: the retired 'dontAsk' mode maps explicitly to 'auto' (which now
      // absorbs the no-prompt loop) so the UI doesn't render a blank mode.
      const rawMode = (parsed as { mode?: unknown }).mode;
      if (rawMode === 'dontAsk') {
        (parsed as Session).mode = 'auto';
      } else if (!isChatMode(rawMode)) {
        (parsed as Session).mode = DEFAULT_MODE;
      }
      // [身分凍結 A] 補 agentUid/agentNicknames、遷移 aiName、回填舊 assistant 訊息身分。
      migrateIdentity(parsed);
      return parsed;
    } catch (e: any) {
      if (e?.code === 'FileNotFound' || e?.name === 'EntryNotFound (FileSystemError)') return null;
      throw e;
    }
  }

  private async writeAtomic(session: Session): Promise<void> {
    await this.init();
    const bytes = this.textEncoder.encode(JSON.stringify(session, null, 2));
    const tmp = this.tmpFor(session.id);
    const dest = this.fileFor(session.id);
    await vscode.workspace.fs.writeFile(tmp, bytes);
    // vscode fs.rename supports overwrite:true, which is the atomic path on local disks.
    try {
      await vscode.workspace.fs.rename(tmp, dest, { overwrite: true });
    } catch (e) {
      // [M7] rename failed → drop the spool file so it doesn't linger as an
      // orphan (list() skips .tmp, but they'd accumulate silently otherwise).
      try { await vscode.workspace.fs.delete(tmp); } catch { /* already gone */ }
      throw e;
    }
    this._onDidChange.fire();
  }

  async create(
    // 1.7.0: default model aligned with registry DEFAULT_MODEL ('claude-opus-4-8').
    // The old 'anthropic/claude-haiku-4-5' carried the de-listed AI King Backend
    // 'provider/model' prefix; that format is dead post-§1.6.
    title?: string,
    model = DEFAULT_MODEL,
    stack = 'clean',
    mode: ChatMode = DEFAULT_MODE,
    providerId?: string,
  ): Promise<Session> {
    const now = Date.now();
    const id = genId();
    const session: Session = {
      id,
      title: title || 'New session',
      createdAt: now,
      updatedAt: now,
      model,
      stack,
      mode,
      providerId,
      // [身分凍結 A] 對話建立時定種子 = id（整個對話不 rotate）；新對話＝新身分＝新色。
      agentUid: id,
      agentNicknames: {},
      messages: [],
    };
    await this.writeAtomic(session);
    return session;
  }

  // ── [身分凍結 A] host 端權威身分計算 + pending stamp ──────────────────────

  /**
   * dispatch 前 host 算好的 author stamp，鍵＝sessionId。append 一個 assistant 訊息時
   * 取出蓋上去（用完即刪）。host 一律用 `resolveCurrentAuthor` 算，webview 永不回傳
   * authorId（紅隊 MF-6）。
   */
  private pendingAuthor = new Map<string, AuthorStamp>();

  /** host 在 handleSend dispatch **之前**呼叫（值由 resolveCurrentAuthor 算、ACP 可覆蓋 name）。 */
  setPendingAuthor(sessionId: string, stamp: AuthorStamp): void {
    this.pendingAuthor.set(sessionId, stamp);
  }

  /**
   * host 端權威算當前 author。authorId 純由 session 欄位推（對話內恆定）；authorName/
   * authorSub 預設用 model，ACP 對話由 host 覆蓋成代理 label（host 才有 acpAgentProfile）。
   */
  resolveCurrentAuthor(session: Session): AuthorStamp {
    return {
      authorId: authorIdFor(session),
      authorName: session.model || '',
      authorSub: session.model || '',
      // [統一母版] 種類圖示由 stack 推（純函數可算）；供應商 logo 需 provider catalog
      // （只有 host 有），故預設空、由 chat-panel 在 postState/dispatch 覆蓋。
      kindLogo: logoForAgentKind(agentKindForStack(session.stack)),
      provLogo: '',
    };
  }

  /**
   * 改名：寫 `agentNicknames[authorId] = name`（同 authorId 全歷史套新名）。authorId 由
   * host 端算傳入（不信 webview，MF-6）。空名＝清除暱稱（回 fallback authorName）。寫後
   * prune 孤兒。
   */
  async setAgentNickname(id: string, authorId: string, name: string): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    if (!session.agentNicknames) session.agentNicknames = {};
    const trimmed = (name || '').trim();
    if (trimmed) session.agentNicknames[authorId] = trimmed;
    else delete session.agentNicknames[authorId];
    pruneAgentNicknames(session);
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  async setMode(id: string, mode: ChatMode): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    session.mode = mode;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  /**
   * [1.13.x 群組連動] 對話視窗改了 Agent(stack) 或 LLM(model/providerId) → 回寫進這個
   * session。這是「對話視窗改身份 → 群組同一個 AI 連動」整條資料流的起點：bridge-view 的
   * syncBuiltinIdentitiesFromSessions 讀的就是 session.stack/model/providerId，過去因為
   * 這兩個值從沒被回寫（stack:set 只寫全域 config、model:set 只寫 workspaceState）、session
   * 自 create() 後永久凍結，連動形同斷線。只更新有傳入、非空、且與現值不同的欄位（空值不覆蓋
   * 既有，避免清掉好資料；無變化則不寫盤、不 fire onDidChange）。
   */
  async setIdentity(
    id: string,
    patch: { stack?: string; model?: string; providerId?: string },
  ): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    let changed = false;
    if (typeof patch.stack === 'string' && patch.stack && patch.stack !== session.stack) {
      session.stack = patch.stack;
      changed = true;
    }
    if (typeof patch.model === 'string' && patch.model && patch.model !== session.model) {
      session.model = patch.model;
      changed = true;
    }
    if (
      typeof patch.providerId === 'string' &&
      patch.providerId &&
      patch.providerId !== session.providerId
    ) {
      session.providerId = patch.providerId;
      changed = true;
    }
    if (!changed) return;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  /** [1.8.0 §15] set this conversation's AI nickname (empty ⇒ clear). */
  async setAiName(id: string, aiName: string): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    const trimmed = (aiName || '').trim();
    if (trimmed) session.aiName = trimmed;
    else delete session.aiName;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  /** [1.9.3] set this conversation's AI 簡介（個資；empty ⇒ clear → 回到模型預設）。 */
  async setAiBio(id: string, bio: string): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    const trimmed = (bio || '').trim();
    if (trimmed) session.aiBio = trimmed;
    else delete session.aiBio;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  /** [1.8.2] set this conversation's AI avatar marker (empty ⇒ clear). */
  async setAiAvatar(id: string, marker: string): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    const trimmed = (marker || '').trim();
    if (trimmed) session.aiAvatar = trimmed;
    else delete session.aiAvatar;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  async append(id: string, message: SessionMessage): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    // [身分凍結 A] assistant 訊息在 append 那一刻凍結身分（紅隊 MF-6 凍結時機）。pendingAuthor
    // 由 host 在 dispatch 前設；缺則 host 權威即時算。已帶 authorId 的不覆蓋（重入/重試安全）。
    // 14 個 append 站點全不動，新後端自動繼承（方案 B 單點收斂）。
    if (message.role === 'assistant' && !message.authorId) {
      const stamp = this.pendingAuthor.get(id) ?? this.resolveCurrentAuthor(session);
      message.authorId = stamp.authorId;
      message.authorName = stamp.authorName;
      message.authorSub = stamp.authorSub;
      // [統一母版] 凍結三段式徽章來源（種類圖示 + 供應商 logo）。空字串不寫（保持訊息精簡）。
      if (stamp.kindLogo) message.authorKindLogo = stamp.kindLogo;
      if (stamp.provLogo) message.authorProvLogo = stamp.provLogo;
    }
    session.messages.push(message);
    session.updatedAt = Date.now();
    // Auto-title on first user message if still default.
    if (
      (session.title === 'New session' || session.title === 'Untitled session') &&
      message.role === 'user'
    ) {
      session.title = autoTitle(message.content);
    }
    await this.writeAtomic(session);
  }

  async rename(id: string, title: string): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    session.title = title;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  async delete(id: string): Promise<void> {
    this.pendingAuthor.delete(id); // [身分凍結 A] 清掉 pending stamp，不殘留
    // [1.9.0 紅藍稽核 M8] 連帶刪這個對話的自訂頭像檔（否則 avatars/ 目錄只增不減、
    // 長期漲到數 GB）。best-effort，刪頭像失敗不擋刪對話。
    try {
      const s = await this.load(id);
      const marker = s?.aiAvatar;
      if (marker && marker.startsWith('store:')) {
        const rel = marker.slice('store:'.length);
        if (!rel.includes('..') && !rel.startsWith('/') && !rel.startsWith('\\')) {
          await vscode.workspace.fs.delete(
            vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', rel),
          ).then(undefined, () => { /* 頭像不在就算了 */ });
        }
      }
    } catch { /* 載入失敗就略過頭像清理 */ }
    try {
      await vscode.workspace.fs.delete(this.fileFor(id));
      this._onDidChange.fire();
    } catch (e: any) {
      if (e?.code !== 'FileNotFound') throw e;
    }
  }

  /**
   * [1.8.3] Auto-prune CONVERSATIONS by count + inactivity. This store holds
   * 1-on-1 conversations only — GROUPS live in a separate bridge store and are
   * never touched here (user: 群組除外). Closing a tab does NOT delete; pruning
   * only happens by these rules + manual delete from history. The currently
   * open session (keepId) is always spared. Both rules have a switch + param
   * (aiKing.conversation.*). Returns the ids actually deleted.
   */
  async pruneConversations(keepId?: string): Promise<string[]> {
    const cfg = vscode.workspace.getConfiguration('aiKing');
    const byCount = cfg.get<boolean>('conversation.pruneByCountEnabled') !== false;
    const maxCount = Math.max(1, cfg.get<number>('conversation.maxCount') ?? 20);
    const byInactivity = cfg.get<boolean>('conversation.pruneByInactivityEnabled') !== false;
    const days = Math.max(1, cfg.get<number>('conversation.inactivityDays') ?? 30);
    if (!byCount && !byInactivity) return [];

    const sorted = (await this.list()).sort((a, b) => b.updatedAt - a.updatedAt);
    const toDelete = new Set<string>();
    if (byInactivity) {
      const cutoff = Date.now() - days * 86_400_000;
      for (const s of sorted) if (s.updatedAt < cutoff) toDelete.add(s.id);
    }
    if (byCount && sorted.length > maxCount) {
      for (const s of sorted.slice(maxCount)) toDelete.add(s.id);
    }
    if (keepId) toDelete.delete(keepId);

    const deleted: string[] = [];
    for (const id of toDelete) {
      try {
        await this.delete(id);
        deleted.push(id);
      } catch {
        /* ignore individual failures */
      }
    }
    return deleted;
  }

  /** Truncate to first `messageIndex` messages (exclusive). Used for edit/retry. */
  async truncate(id: string, messageIndex: number): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    session.messages = session.messages.slice(0, Math.max(0, messageIndex));
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }

  /**
   * [願景 1 PoC 2026-06-17] 一次性以新陣列取代全部訊息，單次 writeAtomic。
   * 取代壓縮舊路徑的「truncate(0) + 迴圈 append」——那條會在「已清空、未寫回」的
   * 失敗窗（truncate 落盤後到第一個 append 落盤前）被任何中斷（crash／關視窗／斷電）
   * 整段全滅。本方法把磁碟上的 session 從「舊全文」直接原子換成「新陣列」，
   * 不存在中間清空態。呼叫端（壓縮）必須先把舊全文落地 archive、驗成功後才呼叫本方法。
   */
  async replaceAll(id: string, messages: SessionMessage[]): Promise<void> {
    const session = await this.load(id);
    if (!session) throw new Error(`session not found: ${id}`);
    session.messages = messages;
    session.updatedAt = Date.now();
    await this.writeAtomic(session);
  }
}

constructor(private readonly ctx: vscode.ExtensionContext) {
  this.rootDir = sessionsDir(this.namespace);
}

getNamespace(): string {
  return this.namespace;
}

async setNamespace(ns: string): Promise<boolean> {
  const next = sanitizeNs(ns);
  if (next === this.namespace) return false;
  this.namespace = next;
  this.rootDir = sessionsDir(next);
  await this.init();
  this._onDidChange.fire();
  return true;
}

private guestFallbackDir(): vscode.Uri | null {
  if (this.namespace !== PROFILE_GUEST) return null;
  if (isGuestMigrated(this.ctx)) return null;
  return legacyGuestSessionsDir(this.ctx);
}

async init(): Promise<void> {
  // globalStorageUri 仍是頭像 / compact-archive / checkpoints 的父目錄（P1a 未搬），保留。
  await ensureDir(this.ctx.globalStorageUri);
  // rootDir = ~/.aiking/profiles/<ns>/sessions；createDirectory 遞迴建中間層。
  await ensureDir(this.rootDir);
}

private fileFor(id: string): vscode.Uri {
  return vscode.Uri.joinPath(this.rootDir, `${id}.json`);
}

private tmpFor(id: string): vscode.Uri {
  return vscode.Uri.joinPath(this.rootDir, `${id}.json.tmp`);
}

async list(): Promise<SessionSummary[]> {
  await this.init();
  const seen = new Set<string>();
  const summaries: SessionSummary[] = [];
  const scan = async (dir: vscode.Uri): Promise<void> => {
    let entries: [string, vscode.FileType][];
    try {
      entries = await vscode.workspace.fs.readDirectory(dir);
    } catch {
      return;
    }
    for (const [name, type] of entries) {
      if (type !== vscode.FileType.File) continue;
      if (!name.endsWith('.json') || name.endsWith('.tmp')) continue;
      const id = name.slice(0, -5);
      if (seen.has(id)) continue; // rootDir 先掃、優先；fallback 同 id 跳過
      try {
        const session = await this.load(id);
        if (session) {
          seen.add(id);
          summaries.push({
            id: session.id,
            title: session.title,
            updatedAt: session.updatedAt,
            messageCount: session.messages.length,
            model: session.model,
            stack: session.stack,
            mode: session.mode || DEFAULT_MODE,
            providerId: session.providerId,
          });
        }
      } catch (e) {
        console.warn(`[ai-king] skip corrupt session ${id}: ${e}`);
      }
    }
  };
  await scan(this.rootDir);
  // [1.14.0 fail-safe] 訪客且遷移未成功時，補掃舊扁平 globalStorage/sessions（影子來源），
  // 保證遷移失敗仍看得到舊對話、不會空清單像消失。
  const fb = this.guestFallbackDir();
  if (fb) await scan(fb);
  summaries.sort((a, b) => b.updatedAt - a.updatedAt);
  return summaries;
}

async load(id: string): Promise<Session | null> {
  const primary = await this.loadFrom(this.rootDir, id);
  if (primary) return primary;
  // [1.14.0 fail-safe] rootDir 找不到 + 訪客且遷移未成功 → 回退讀舊扁平 globalStorage/sessions。
  const fb = this.guestFallbackDir();
  if (fb) return this.loadFrom(fb, id);
  return null;
}

private async loadFrom(dir: vscode.Uri, id: string): Promise<Session | null> {
  try {
    const buf = await vscode.workspace.fs.readFile(vscode.Uri.joinPath(dir, `${id}.json`));
    const text = this.textDecoder.decode(buf);
    const parsed = JSON.parse(text) as Session;
    // Minimal shape validation; tolerate missing optional fields.
    if (!parsed || typeof parsed.id !== 'string' || !Array.isArray(parsed.messages)) {
      return null;
    }
    // Migration: legacy sessions have no `mode` field — default to 'edits'.
    // 1.7.0: the retired 'dontAsk' mode maps explicitly to 'auto' (which now
    // absorbs the no-prompt loop) so the UI doesn't render a blank mode.
    const rawMode = (parsed as { mode?: unknown }).mode;
    if (rawMode === 'dontAsk') {
      (parsed as Session).mode = 'auto';
    } else if (!isChatMode(rawMode)) {
      (parsed as Session).mode = DEFAULT_MODE;
    }
    // [身分凍結 A] 補 agentUid/agentNicknames、遷移 aiName、回填舊 assistant 訊息身分。
    migrateIdentity(parsed);
    return parsed;
  } catch (e: any) {
    if (e?.code === 'FileNotFound' || e?.name === 'EntryNotFound (FileSystemError)') return null;
    throw e;
  }
}

private async writeAtomic(session: Session): Promise<void> {
  await this.init();
  const bytes = this.textEncoder.encode(JSON.stringify(session, null, 2));
  const tmp = this.tmpFor(session.id);
  const dest = this.fileFor(session.id);
  await vscode.workspace.fs.writeFile(tmp, bytes);
  // vscode fs.rename supports overwrite:true, which is the atomic path on local disks.
  try {
    await vscode.workspace.fs.rename(tmp, dest, { overwrite: true });
  } catch (e) {
    // [M7] rename failed → drop the spool file so it doesn't linger as an
    // orphan (list() skips .tmp, but they'd accumulate silently otherwise).
    try { await vscode.workspace.fs.delete(tmp); } catch { /* already gone */ }
    throw e;
  }
  this._onDidChange.fire();
}

async create(
  // 1.7.0: default model aligned with registry DEFAULT_MODEL ('claude-opus-4-8').
  // The old 'anthropic/claude-haiku-4-5' carried the de-listed AI King Backend
  // 'provider/model' prefix; that format is dead post-§1.6.
  title?: string,
  model = DEFAULT_MODEL,
  stack = 'clean',
  mode: ChatMode = DEFAULT_MODE,
  providerId?: string,
): Promise<Session> {
  const now = Date.now();
  const id = genId();
  const session: Session = {
    id,
    title: title || 'New session',
    createdAt: now,
