export function resolveSessionProviderId(
  ctx: vscode.ExtensionContext,
  storedProviderId: string | undefined,
): string | undefined {
  const providers = loadProviders();
  if (storedProviderId && findProvider(storedProviderId, providers)) {
    return storedProviderId;
  }
  // Stored id is gone (e.g. ai-king-backend after §1.6 de-listing) — fall back
  // to whatever the user currently has active, then to the first existing one.
  const active = getActiveProvider(ctx, providers);
  if (active) return active.id;
  return providers.length > 0 ? providers[0].id : undefined;
}

export function getActiveSessionId(ctx: vscode.ExtensionContext): string | undefined {
  return ctx.workspaceState.get<string>(ACTIVE_SESSION_KEY);
}

export async function setActiveSessionId(
  ctx: vscode.ExtensionContext,
  id: string | undefined,
): Promise<void> {
  await ctx.workspaceState.update(ACTIVE_SESSION_KEY, id);
}

export function registerSessionCommands(
  ctx: vscode.ExtensionContext,
  store: SessionStore,
): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.sessions.new', async () => {
      // v0.9.0: CC-style — no title prompt. Auto-title from first user
      // message (see store.append's autoTitle logic). Rename via
      // aiKing.sessions.rename if the user wants a custom title.
      //
      // 1.7.0 default chain (PLAN §5.3) — a new chat inherits the sidebar
      // CHAT 預設區 selections:
      //   · model / provider ← workspaceState (sidebar Model picker writes these)
      //   · mode             ← getLastMode (sidebar mode buttons write this)
      //   · effort / thinking← aiKing config (sidebar Effort picker writes effort;
      //                         chat-panel reads both from config at render time)
      // providerId is resolved through resolveSessionProviderId so a session is
      // never stamped with a provider that has been removed (e.g. ai-king-backend).
      const config = vscode.workspace.getConfiguration('aiKing');
      const providerId = resolveSessionProviderId(ctx, getActiveProvider(ctx)?.id);
      const model = getActiveModel(ctx);
      const stack = config.get<string>('stack') || 'clean';
      const mode = getLastMode(ctx);
      // [1.9.3] 開新對話全鏈 log（home:newChat → home:session-new → 這裡 → openSession
      // → 面板 init → webview first-state）。建錯/掉 provider 一眼看出停在哪。
      log.info('session:new:resolve', { providerId, model, stack, mode });
      try {
        const session = await store.create(
          undefined,
          model,
          stack,
          mode,
          providerId,
        );
        log.info('session:new:created', { sessionId: session.id });
        await setActiveSessionId(ctx, session.id);
        await setLastMode(ctx, mode);
        try {
          log.info('session:new:open-dispatch', { sessionId: session.id });
          await vscode.commands.executeCommand('aiKing.chat.openSession', session.id);
        } catch {
          /* chat panel command may not yet be registered */
        }
      } catch (e: any) {
        log.error('session:new:fail', { detail: e?.message || String(e) });
        throw e;
      }
    }),

    vscode.commands.registerCommand('aiKing.sessions.pick', async () => {
      const summaries = await store.list();
      if (summaries.length === 0) {
        vscode.window.showInformationMessage('AI King: 尚無已儲存的對話 (No saved sessions)');
        return;
      }
      const items = summaries.map((s) => ({
        label: s.title,
        description: `${s.messageCount} msgs · ${s.model}`,
        detail: `${new Date(s.updatedAt).toLocaleString()} · stack: ${s.stack}`,
        sessionId: s.id,
      }));
      const pick = await showQuickPickEsc(items, {
        placeHolder: '選擇要開啟的對話 (Pick a session)',
        matchOnDescription: true,
        matchOnDetail: true,
      });
      if (pick) {
        await setActiveSessionId(ctx, pick.sessionId);
        vscode.window.showInformationMessage(`AI King: 已切換到「${pick.label}」`);
      }
    }),

    vscode.commands.registerCommand('aiKing.sessions.rename', async () => {
      const activeId = getActiveSessionId(ctx);
      if (!activeId) {
        vscode.window.showWarningMessage('AI King: 沒有活躍的對話 (No active session)');
        return;
      }
      const session = await store.load(activeId);
      if (!session) {
        vscode.window.showWarningMessage('AI King: 對話已遺失 (Session missing)');
        return;
      }
      const title = await showInputBoxEsc({
        prompt: '新標題 (New title)',
        value: session.title,
        ignoreFocusOut: true,
      });
      if (title) {
        await store.rename(activeId, title);
        vscode.window.showInformationMessage('AI King: 已重新命名');
      }
    }),

    vscode.commands.registerCommand('aiKing.sessions.delete', async () => {
      const summaries = await store.list();
      if (summaries.length === 0) {
        vscode.window.showInformationMessage('AI King: 尚無已儲存的對話');
        return;
      }
      const items = summaries.map((s) => ({
        label: s.title,
        description: `${s.messageCount} msgs`,
        detail: new Date(s.updatedAt).toLocaleString(),
        sessionId: s.id,
      }));
      const pick = await showQuickPickEsc(items, {
        placeHolder: '選擇要刪除的對話 (Pick to delete)',
      });
      if (!pick) return;
      // [1.13.x] 刪對話＝一併刪掉「連結它的群組內建 AI」的長期記憶 → 偵測到連結就加警告標語；
      // 沒連任何群組則維持原本單純的確認文字（user 2026-06-17 指示）。反查 globalState 的
      // groupMemberSession.* key（前綴對齊 bridge-view.ts memberSessionKey，改前綴要同步兩處）。
      let linkedToGroup = false;
      for (const key of ctx.globalState.keys()) {
        if (key.startsWith('aiKing.groupMemberSession.')
          && ctx.globalState.get<string>(key) === pick.sessionId) {
          linkedToGroup = true;
          break;
        }
      }
      const confirm = await vscode.window.showWarningMessage(
        linkedToGroup
          ? `確定刪除「${pick.label}」？\n⚠ 這個對話是某個群組 AI 的長期記憶，刪掉會一併清除它的記憶、無法復原。 (Delete — also wipes a group AI's memory)`
          : `確定刪除「${pick.label}」？ (Delete this session?)`,
        { modal: true },
        '刪除 (Delete)',
      );
      if (confirm === '刪除 (Delete)') {
        await store.delete(pick.sessionId);
        if (getActiveSessionId(ctx) === pick.sessionId) {
          await setActiveSessionId(ctx, undefined);
        }
        vscode.window.showInformationMessage('AI King: 已刪除');
      }
    }),
  );
}

export interface AIKingSettings {
  apiBase: string;
  defaultModel: string;
  stack: string;
  provider: Provider | undefined;
  apiKey: string;
  getKeyForModel(model: string): string;
}

export async function getSettings(ctx: vscode.ExtensionContext): Promise<AIKingSettings> {
  const config = vscode.workspace.getConfiguration('aiKing');
  const providers = loadProviders();
  const provider = getActiveProvider(ctx, providers);
  const model = getActiveModel(ctx);
  const stack = config.get<string>('stack') || 'clean';
  const apiKey = provider ? await getProviderKey(ctx, provider.id) : '';

  return {
    apiBase: provider?.endpoint || 'https://chat.ai-king.dev/v1',
    defaultModel: model,
    stack,
    provider,
    apiKey,
    getKeyForModel(_m: string): string {
      // Legacy callers may pass any model id; we just return the key of the active provider.
      return apiKey || 'none';
    },
  };
}

getKeyForModel(_m: string): string {
  // Legacy callers may pass any model id; we just return the key of the active provider.
  return apiKey || 'none';
