export function copySkillDir(srcDir: string, dstDir: string): void {
  fs.mkdirSync(dstDir, { recursive: true });
  for (const entry of fs.readdirSync(srcDir, { withFileTypes: true })) {
    if (!entry.isFile()) continue; // skill 目前是平的（SKILL.md + 腳本），無巢狀子夾
    fs.copyFileSync(path.join(srcDir, entry.name), path.join(dstDir, entry.name));
  }
}

function copyOneFile(srcFile: string, dstFile: string): void {
  fs.mkdirSync(path.dirname(dstFile), { recursive: true });
  fs.copyFileSync(srcFile, dstFile);
}

function copyAllSkills(srcRoot: string, dstRoot: string): number {
  let n = 0;
  for (const name of fs.readdirSync(srcRoot)) {
    const srcDir = path.join(srcRoot, name);
    const srcSkill = path.join(srcDir, 'SKILL.md');
    if (!fs.existsSync(srcSkill)) continue;
    copySkillDir(srcDir, path.join(dstRoot, name));
    n++;
  }
  return n;
}

