interface StackInfo {
  id: string;
  description: string;
  layers: string[];
}

const FALLBACK_STACKS: StackInfo[] = [
  { id: 'clean', description: 'Direct LLM, no cognitive layers', layers: ['LLM'] },
  { id: 'concinno', description: 'Concinno cognitive layer', layers: ['LLM', 'CCC'] },
];

async function fetchStacks(apiBase: string): Promise<StackInfo[]> {
  // apiBase ends with /v1 in our settings, so drop the /v1 segment to hit /v1/stacks.
  // Backend contract: base URL is https://chat.ai-king.dev, /v1/stacks is the listing.
  const normalized = apiBase.replace(/\/$/, '');
  const url = normalized.endsWith('/v1')
    ? `${normalized}/stacks`
    : `${normalized}/v1/stacks`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const resp = await fetch(url, {
      method: 'GET',
      headers: { Accept: 'application/json' },
      signal: controller.signal,
    });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = (await resp.json()) as unknown;
    if (!Array.isArray(data)) throw new Error('invalid response shape');
    const stacks: StackInfo[] = [];
    for (const item of data) {
      if (
        item &&
        typeof (item as any).id === 'string' &&
        typeof (item as any).description === 'string' &&
        Array.isArray((item as any).layers)
      ) {
        stacks.push({
          id: (item as any).id,
          description: (item as any).description,
          layers: (item as any).layers,
        });
      }
    }
    if (stacks.length === 0) throw new Error('empty stack list');
    return stacks;
  } finally {
    clearTimeout(timeout);
  }
}

export function registerStackPickCommand(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.stack.pick', async () => {
      const config = vscode.workspace.getConfiguration('aiKing');
      const apiBase = (config.get<string>('apiBase') || 'https://chat.ai-king.dev/v1').replace(/\/$/, '');

      let stacks: StackInfo[];
      let usedFallback = false;
      try {
        stacks = await fetchStacks(apiBase);
      } catch (e: any) {
        usedFallback = true;
        stacks = FALLBACK_STACKS;
        vscode.window.showWarningMessage(
          `AI King: Backend 不可達 (${e?.message || 'unknown'})，顯示預設 stacks (Backend unreachable, showing defaults)`,
        );
      }

      const items = stacks.map((s) => ({
        label: s.id,
        description: s.description,
        detail: `layers: ${s.layers.join(' + ')}`,
        stackId: s.id,
      }));
      const pick = await showQuickPickEsc(items, {
        placeHolder: usedFallback
          ? '選擇 stack (fallback 模式 / fallback mode)'
          : '選擇 stack (Pick a stack)',
        matchOnDescription: true,
        matchOnDetail: true,
      });
      if (pick) {
        await config.update('stack', pick.stackId, vscode.ConfigurationTarget.Global);
        vscode.window.showInformationMessage(`AI King: stack 已設為「${pick.stackId}」`);
      }
    }),
  );
}

interface Manifest {
  version: string;
  url: string;
  sha256: string;
  released: string;
  changelog?: string;
}

export function semverGt(a: string, b: string): boolean {
  const normalize = (v: string): number[] => {
    const [core] = v.split('-');
    return core.split('.').map((s) => parseInt(s, 10) || 0);
  };
  const aa = normalize(a);
  const bb = normalize(b);
  for (let i = 0; i < Math.max(aa.length, bb.length); i++) {
    const x = aa[i] || 0;
    const y = bb[i] || 0;
    if (x > y) return true;
    if (x < y) return false;
  }
  return false;
}

async function fetchManifest(): Promise<Manifest | null> {
  try {
    const ctrl = new AbortController();
    const timeout = setTimeout(() => ctrl.abort(), 10_000);
    const resp = await fetch(MANIFEST_URL, {
      method: 'GET',
      headers: { Accept: 'application/json' },
      signal: ctrl.signal,
    });
    clearTimeout(timeout);
    if (!resp.ok) return null;
    const data = (await resp.json()) as unknown;
    if (
      data &&
      typeof (data as any).version === 'string' &&
      typeof (data as any).url === 'string' &&
      typeof (data as any).sha256 === 'string' &&
      typeof (data as any).released === 'string'
    ) {
      return data as Manifest;
    }
    return null;
  } catch {
    return null;
  }
}

async function downloadAndInstall(manifest: Manifest): Promise<void> {
  try {
    const resp = await fetch(manifest.url, { method: 'GET' });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const bytes = new Uint8Array(await resp.arrayBuffer());

    const hash = createHash('sha256').update(bytes).digest('hex');
    if (hash.toLowerCase() !== manifest.sha256.toLowerCase()) {
      throw new Error(`sha256 mismatch: expected ${manifest.sha256}, got ${hash}`);
    }

    const filename = `ai-king-${manifest.version}.vsix`;
    const targetPath = join(tmpdir(), filename);
    await writeFile(targetPath, bytes);

    await vscode.commands.executeCommand(
      'workbench.extensions.installExtension',
      vscode.Uri.file(targetPath),
    );
    // [1.24.35] 此路徑用 VS Code API（workbench.extensions.installExtension）安裝＝VS Code 自己裝、
    //   會更新內部擴充清單，故「重新載入視窗」對這條足夠。但若用「命令列 code --install-extension」
    //   裝（一鍵更新.bat），Reload Window 不夠、要「完全關閉 VS Code 再重開」才會重新掃描到新版——
    //   故文案兜底提醒，避免 user 按了 reload 沒變又困惑（這正是先前「Ctrl+R 沒效」的根因）。
    vscode.window.showInformationMessage(
      `AI King: v${manifest.version} 已安裝。點「重新載入」生效；萬一沒變，請「完全關閉 VS Code 再重開」（不只 Ctrl+R）。`,
      '重新載入 (Reload)',
    ).then((choice) => {
      if (choice === '重新載入 (Reload)') {
        vscode.commands.executeCommand('workbench.action.reloadWindow');
      }
    });
  } catch (e: any) {
    vscode.window.showErrorMessage(`AI King 更新失敗 (Update failed): ${e?.message || String(e)}`);
  }
}

function getAutoUpdateSetting(): AutoUpdateMode {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const raw = cfg.get<boolean | string>('autoUpdate', true);
  if (raw === 'silent') return 'silent';
  return raw !== false;
}

async function doCheck(ctx: vscode.ExtensionContext, opts?: { manual?: boolean }): Promise<void> {
  const mode = getAutoUpdateSetting();
  // If disabled and not a manual trigger, skip
  if (mode === false && !opts?.manual) return;

  const manifest = await fetchManifest();
  if (!manifest) {
    if (opts?.manual) {
      vscode.window.showInformationMessage('AI King: 無法取得更新資訊 (Could not fetch update manifest)');
    }
    return;
  }

  const currentVersion = ctx.extension.packageJSON.version as string;
  if (!semverGt(manifest.version, currentVersion)) {
    if (opts?.manual) {
      vscode.window.showInformationMessage(`AI King: 已是最新版本 v${currentVersion} (Already up to date)`);
    }
    return;
  }

  // Silent mode: auto download + install without asking
  if (mode === 'silent' && !opts?.manual) {
    await downloadAndInstall(manifest);
    return;
  }

  // Interactive: show notification with buttons
  const choice = await vscode.window.showInformationMessage(
    `AI King v${manifest.version} 可用 (當前 v${currentVersion})` +
      (manifest.changelog ? ` — ${manifest.changelog}` : ''),
    '立即更新 (Update Now)',
    '稍後 (Later)',
  );
  if (choice === '立即更新 (Update Now)') {
    await downloadAndInstall(manifest);
  }
}

export function startUpdateChecker(ctx: vscode.ExtensionContext): void {
  // Initial check, delayed 30s
  const initial = setTimeout(() => {
    doCheck(ctx).catch(() => { /* silent */ });
  }, 30_000);

  intervalHandle = setInterval(() => {
    doCheck(ctx).catch(() => { /* silent */ });
  }, INTERVAL_MS);

  ctx.subscriptions.push({
    dispose: () => {
      clearTimeout(initial);
      if (intervalHandle) clearInterval(intervalHandle);
    },
  });
}

export function checkForUpdatesCommand(ctx: vscode.ExtensionContext): () => Promise<void> {
  return async () => {
    await doCheck(ctx, { manual: true });
  };
}

export function withEsc(text?: string): string {
  const base = (text || '').trim();
  return base ? `${base}　·　${ESC_HINT}` : ESC_HINT;
}

export function showInputBoxEsc(
  options: vscode.InputBoxOptions,
  token?: vscode.CancellationToken,
): Thenable<string | undefined> {
  return vscode.window.showInputBox({ ...options, prompt: withEsc(options.prompt) }, token);
}

export function showQuickPickEsc(
  items: readonly vscode.QuickPickItem[] | readonly string[] | Thenable<readonly (vscode.QuickPickItem | string)[]>,
  options?: vscode.QuickPickOptions,
  token?: vscode.CancellationToken,
): Thenable<vscode.QuickPickItem | vscode.QuickPickItem[] | string | string[] | undefined> {
  const merged: vscode.QuickPickOptions = { ...(options || {}), placeHolder: withEsc(options?.placeHolder) };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return vscode.window.showQuickPick(items as any, merged, token);
}

export interface AcpLaunchSpec {
  /** 完整啟動指令，如 "npx -y @agentclientprotocol/claude-agent-acp"。 */
  command: string;
  /** 併進 process.env 的額外環境變數（如 { HERMES_HOME: "..." }）。 */
  env?: Record<string, string>;
  /** 代理工作目錄（預設＝第一個 workspace 資料夾）。 */
  cwd?: string;
}

interface AcpConnection {
  child: cp.ChildProcess;
  conn: any; // acp.ClientSideConnection（動態 import，型別在邊界鬆綁）
  command: string; // 起這條連線的啟動指令；對話中切換代理時用來判斷要不要殺舊起新
  acpSessionId: string;
  /** 可變 sink — runViaACP 每輪 prompt 前設定，把代理更新導向當輪的 emit。 */
  sink: ((update: unknown) => void) | null;
  /**
   * 可變權限決策器 — runViaACP 每輪 prompt 前設定（帶當輪 mode）。代理每次要動工具，
   * requestPermission 會問它。null＝fallback 放行（相容無接線的舊路徑，如群組）。
   */
  permission:
    | ((req: { toolKind: string; toolTitle: string; options: unknown[] }) => Promise<unknown>)
    | null;
  /**
   * [事件驅動超時 2026-06-21] 可變「當輪中斷」回呼 — runViaACP 每輪設定。子進程在「對話進行中
   *（sink 還在）」異常死亡時呼叫，讓那一輪強制中斷出 error（不必空等到前端 3 分鐘軟提示）。
   * 正常 dispose（切換/關閉對話）時 sink 已是 null → 不觸發。null＝無接線的舊路徑（如群組）。
   */
  onAbort: ((reason: string) => void) | null;
}

