export function acpAgentHasCommand(id: string): boolean {
  const agents =
    vscode.workspace.getConfiguration('aiKing').get<Record<string, { command?: string }>>('acpAgents') || {};
  const c = agents[id]?.command;
  return !!(DEFAULT_ACP_COMMANDS[id] || (c && c.trim()));
}

export function acpAgentList(): Array<{ id: string; label: string }> {
  const agents = vscode.workspace.getConfiguration('aiKing').get<Record<string, unknown>>('acpAgents') || {};
  const ids = Array.from(
    new Set([...Object.keys(ACP_AGENT_LABELS), ...Object.keys(DEFAULT_ACP_COMMANDS), ...Object.keys(agents)]),
  );
  return ids.map((id) => ({ id, label: ACP_AGENT_LABELS[id] || id }));
}

function resolveCwd(spec: AcpLaunchSpec): string {
  if (spec.cwd && spec.cwd.trim()) return spec.cwd;
  return vscode.workspace.workspaceFolders?.[0]?.uri.fsPath || process.cwd();
}

function buildEnv(spec: AcpLaunchSpec): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...process.env, ...(spec.env || {}) };
  // 清掉會讓「被起動的代理」誤判環境的變數（Claude Code 設了 CLAUDECODE 就擋巢狀 session）。
  delete env.CLAUDECODE;
  delete env.CLAUDE_CODE_ENTRYPOINT;
  return env;
}

class PanelAcpClient {
  constructor(private readonly key: string) {}

  // 串流更新 → 導向當輪 sink（再映射成 RunnerEvent，由 acp-stream 處理）。
  async sessionUpdate(params: any): Promise<void> {
    const sink = connections.get(this.key)?.sink;
    if (sink) sink(params?.update);
  }

  // 工具授權：依當輪對話模式決策（resolver 由 runViaACP 每輪注入、acp-permission.ts 算）。
  // Chat/Plan 擋寫入、Edits 彈窗問、Auto 全放行。無 resolver（如群組路徑）→ fallback 放行。
  async requestPermission(params: any): Promise<any> {
    const opt = params?.options?.[0];
    const resolver = connections.get(this.key)?.permission;
    if (resolver) {
      try {
        return await resolver({
          toolKind: params?.toolCall?.kind || '',
          toolTitle: params?.toolCall?.title || 'tool',
          options: params?.options || [],
        });
      } catch (e: any) {
        log.warn('acp:permission:resolver-fail', { conn: this.key, msg: e?.message || String(e) });
      }
    }
    // fallback（無 resolver 或出錯）：准第一個選項（相容舊行為）。
    log.info('acp:permission:fallback-allow', {
      conn: this.key,
      tool: params?.toolCall?.title,
      opt: opt?.name,
    });
    if (!opt) return { outcome: { outcome: 'cancelled' } };
    return { outcome: { outcome: 'selected', optionId: opt.optionId } };
  }

  async readTextFile(params: any): Promise<any> {
    try {
      return { content: fs.readFileSync(params.path, 'utf8') };
    } catch {
      log.warn('acp:readTextFile:fail', { path: params?.path });
      return { content: '' };
    }
  }

  async writeTextFile(params: any): Promise<any> {
    try {
      fs.writeFileSync(params.path, params.content, 'utf8');
    } catch {
      log.warn('acp:writeTextFile:fail', { path: params?.path });
    }
    return {};
  }
}

async sessionUpdate(params: any): Promise<void> {
  const sink = connections.get(this.key)?.sink;
  if (sink) sink(params?.update);
}

async requestPermission(params: any): Promise<any> {
  const opt = params?.options?.[0];
  const resolver = connections.get(this.key)?.permission;
  if (resolver) {
    try {
      return await resolver({
        toolKind: params?.toolCall?.kind || '',
        toolTitle: params?.toolCall?.title || 'tool',
        options: params?.options || [],
      });
    } catch (e: any) {
      log.warn('acp:permission:resolver-fail', { conn: this.key, msg: e?.message || String(e) });
    }
  }
  // fallback（無 resolver 或出錯）：准第一個選項（相容舊行為）。
  log.info('acp:permission:fallback-allow', {
    conn: this.key,
    tool: params?.toolCall?.title,
    opt: opt?.name,
  });
  if (!opt) return { outcome: { outcome: 'cancelled' } };
  return { outcome: { outcome: 'selected', optionId: opt.optionId } };
}

async readTextFile(params: any): Promise<any> {
  try {
    return { content: fs.readFileSync(params.path, 'utf8') };
  } catch {
    log.warn('acp:readTextFile:fail', { path: params?.path });
    return { content: '' };
  }
}

async writeTextFile(params: any): Promise<any> {
  try {
    fs.writeFileSync(params.path, params.content, 'utf8');
  } catch {
    log.warn('acp:writeTextFile:fail', { path: params?.path });
  }
  return {};
}

export async function ensureAcpConnection(
  sessionId: string,
  spec: AcpLaunchSpec,
): Promise<AcpConnection> {
  const existing = connections.get(sessionId);
  if (existing && !existing.child.killed) {
    if (existing.command === spec.command) return existing; // 同一代理 → 重用既有連線
    // 對話中切換到不同 ACP 代理 → 殺舊進程、重起新的（解「切了不生效、還跑舊代理」）。
    try {
      existing.child.kill();
    } catch {
      /* ignore */
    }
    connections.delete(sessionId);
  }

  // 動態載入 ESM SDK（見檔頭註解）。esbuild 會 bundle 進 dist。
  const acp: any = await import('@agentclientprotocol/sdk');

  const parts = spec.command.trim().split(/\s+/);
  const cmd = parts[0];
  const args = parts.slice(1);
  const cwd = resolveCwd(spec);
  log.info('acp:spawn', { sessionId, command: spec.command, cwd });

  const child = cp.spawn(cmd, args, {
    stdio: ['pipe', 'pipe', 'ignore'], // 代理自己的 log 走 stderr，先忽略（之後可導 log）
    shell: process.platform === 'win32', // Windows 解析 .cmd shim（npx.cmd / gemini.cmd 等）
    cwd,
    env: buildEnv(spec),
  });
  child.on('error', (e) => {
    log.error('acp:child:error', { sessionId, msg: e.message });
    // [事件驅動超時] 對話進行中（sink 還在）才死＝真斷線 → 通知當輪強制中斷出 log，別讓前端空等。
    const r = connections.get(sessionId);
    if (r?.sink && r.onAbort) r.onAbort(`子進程錯誤：${e.message}`);
  });
  child.on('exit', (code) => {
    log.info('acp:child:exit', { sessionId, code });
    // 進行中就 exit＝異常中斷（正常 dispose 時 sink 已清為 null）→ 強制中斷該輪、surface 診斷。
    const r = connections.get(sessionId);
    if (r?.sink && r.onAbort) r.onAbort(`子進程結束（code=${code ?? 'null'}）`);
    connections.delete(sessionId);
  });
  if (!child.stdin || !child.stdout) {
    try {
      child.kill();
    } catch {
      /* ignore */
    }
    throw new Error(`ACP 代理沒有 stdio 管道：${spec.command}`);
  }

  // 子進程 stdin/stdout → Web 串流 → ndJsonStream（換行分隔 JSON over stdio）。
  const stream = acp.ndJsonStream(
    Writable.toWeb(child.stdin) as any,
    Readable.toWeb(child.stdout) as any,
  );

  // 先把記錄放進 map（handler 透過 key 讀 sink；conn/acpSessionId 稍後補）。
  const record: AcpConnection = {
    child,
    conn: undefined as any,
    command: spec.command,
    acpSessionId: '',
    sink: null,
    permission: null,
    onAbort: null,
  };
  connections.set(sessionId, record);

  const handler = new PanelAcpClient(sessionId);
  const conn = new acp.ClientSideConnection((() => handler) as any, stream);
  record.conn = conn;

  // 初始交握 ＋ 開一個 ACP 對話（每場對話只一次）。
  const init = await conn.initialize({
    protocolVersion: acp.PROTOCOL_VERSION,
    clientCapabilities: { fs: { readTextFile: true, writeTextFile: true } },
  } as any);
  log.info('acp:initialized', { sessionId, protocol: (init as any)?.protocolVersion });

  const sess = await conn.newSession({ cwd, mcpServers: [] } as any);
  record.acpSessionId = (sess as any).sessionId;
  log.info('acp:session:new', { sessionId, acpSessionId: record.acpSessionId });
  return record;
}

export function disposeAcpConnection(sessionId: string): void {
  const c = connections.get(sessionId);
  if (!c) return;
  try {
    c.child.kill();
  } catch {
    /* ignore */
  }
  connections.delete(sessionId);
  log.info('acp:dispose', { sessionId });
}

export async function testAcpConnection(
  agentId: string,
): Promise<{ ok: boolean; label: string; detail: string; timedOut?: boolean }> {
  const resolved = resolveAcpLaunch(agentId);
  if (!resolved) {
    return { ok: false, label: agentId, detail: '找不到啟動指令——先用「設定＋登入 ACP 代理」精靈設定好這家。' };
  }
  const key = `__acptest__:${agentId}:${Date.now()}`;
  // [1.24.40] 冷啟動（npx 下載 adapter／代理初始化）正常就要 ~90 秒，逾時從 45 秒拉到 180 秒；
  // 逾時不報「失敗」而報「超時 180 秒無回應」（timedOut 旗標讓上層用中性文案、不嚇到 user）。
  let timedOut = false;
  try {
    await Promise.race([
      ensureAcpConnection(key, resolved.launch),
      new Promise<never>((_, rej) =>
        setTimeout(() => {
          timedOut = true;
          rej(
            new Error(
              '超時 180 秒無回應——這家代理冷啟動較慢、或要先登入（如 Gemini 登 Google、Hermes 惰性裝 boto3），可再試一次；看 AI King 輸出頻道 acp:spawn 軌跡判斷卡在哪段。',
            ),
          );
        }, 180000),
      ),
    ]);
    return { ok: true, label: resolved.label, detail: 'ACP 交握成功、已開測試對話（協定 v1）。這家代理可正常嵌入使用。' };
  } catch (e: unknown) {
    return { ok: false, label: resolved.label, timedOut, detail: String((e as { message?: string })?.message || e) };
  } finally {
    disposeAcpConnection(key); // 殺測試子進程、不殘留
  }
}

export function disposeAllAcp(): void {
  for (const c of connections.values()) {
    try {
      c.child.kill();
    } catch {
      /* ignore */
    }
  }
  connections.clear();
}

export async function promptAcpOnce(
  key: string,
  spec: AcpLaunchSpec,
  promptText: string,
): Promise<string> {
  const conn = await ensureAcpConnection(key, spec);
  let text = '';
  conn.sink = (u: any) => {
    if (u?.sessionUpdate === 'agent_message_chunk' && u.content?.type === 'text') {
      text += String(u.content.text || '');
    }
  };
  try {
    await conn.conn.prompt({
      sessionId: conn.acpSessionId,
      prompt: [{ type: 'text', text: promptText }],
    } as any);
  } finally {
    conn.sink = null;
  }
  return text;
}

