    loginArgs?: string; loginHint?: string; custom?: boolean;
  }> = [
    { id: 'claude', label: 'Claude Code（零設定）', npx: 'npx -y @agentclientprotocol/claude-agent-acp', loginHint: '用既有 Claude 登入（訂閱可用）' },
    { id: 'codex', label: 'Codex（零設定）', npx: 'npx -y @zed-industries/codex-acp', loginHint: '用既有 ~/.codex 登入' },
    { id: 'gemini', label: 'Gemini CLI（零設定）', npx: 'npx -y @google/gemini-cli --acp', loginHint: '首次先在終端機 npx @google/gemini-cli 登入 Google，之後重用' },
    { id: 'qwen', label: 'Qwen Code（零設定）', npx: 'npx -y @qwen-code/qwen-code --acp', loginHint: '依 Qwen Code 文件登入（重用既有登入）' },
    { id: 'opencode', label: 'OpenCode（零設定·最紅開源）', npx: 'npx -y opencode-ai acp', loginHint: '依 OpenCode 文件登入' },
    { id: 'hermes', label: 'Hermes（Nous Research）', exeHint: 'hermes.exe', acpFlag: 'acp', loginArgs: 'setup', loginHint: 'hermes setup 設模型供應商' },
    { id: 'goose', label: 'Goose（Block 開源）', exeHint: 'goose.exe', acpFlag: 'acp', loginArgs: 'configure', loginHint: 'goose configure 設供應商/金鑰（exe 在 E:\\MyWorld\\My\\AI\\agent\\goose\\goose-package\\）' },
    { id: '__custom__', label: '自訂（自己命名）…', custom: true },
  ];
  // 從 composer/側欄下拉選了某個已知代理（如 goose）但它還沒設定 → 直接跳它的設定步驟，免再選一次。
  const preset = preselectId ? AGENTS.find((x) => x.id === preselectId) : undefined;
  let a: (typeof AGENTS)[number];
  if (preset) {
    a = preset;
  } else {
    const pick0 = await showQuickPickEsc(
      AGENTS.map((x) => ({ label: x.label, a: x })),
      { placeHolder: '要設定／登入哪個 ACP 代理？', ignoreFocusOut: true },
    );
    if (!pick0) return undefined;
    a = pick0.a;
  }

  // 決定 id 與顯示名（自訂＝自己打名字）。
  let id = a.id;
  let label = a.label;
  if (a.custom) {
    const name = await showInputBoxEsc({
      prompt: '幫這個自訂 ACP 代理取個名字（顯示在選單，如 my-agent）',
      ignoreFocusOut: true,
      validateInput: (v) => (v && /^[\w.-]+$/.test(v.trim()) ? null : '只用英數與 . - _，不要空白'),
    });
    if (!name || !name.trim()) return undefined;
    id = name.trim();
    label = id;
  }

  // 取啟動指令：npx 內建（claude/codex）零路徑；其他選執行檔＋可編輯指令。
  let command: string;
  let env: Record<string, string> | undefined;
  let loginCmd: string | undefined;
  if (a.npx) {
    command = a.npx;
  } else {
    const picked = await vscode.window.showOpenDialog({
      canSelectFiles: true,
      canSelectFolders: false,
      canSelectMany: false,
      openLabel: `選 ${label} 的執行檔`,
      title: `選 ${label} 執行檔（${a.exeHint || '它的 CLI'}）`,
    });
    if (!picked || !picked.length) return undefined;
    const exe = picked[0].fsPath;
    const draft = `${exe} ${a.acpFlag || 'acp'}`.trim();
    const edited = await showInputBoxEsc({
      prompt: `${label} 的 ACP 啟動指令（可改；常見 flag＝acp 或 --experimental-acp）`,
      value: draft,
      ignoreFocusOut: true,
    });
    if (!edited || !edited.trim()) return undefined;
    command = edited.trim();
    if (id === 'hermes') env = { HERMES_HOME: path.dirname(path.dirname(path.dirname(path.dirname(exe)))) };
    loginCmd = `${exe} ${a.loginArgs || ''}`.trim();
  }

  // 寫進 aiKing.acpAgents ＋ 設為當前 acpAgent。
  const map: Record<string, { command?: string; env?: Record<string, string>; cwd?: string }> = {
    ...(cfg.get<Record<string, { command?: string; env?: Record<string, string>; cwd?: string }>>('acpAgents') || {}),
  };
  map[id] = { command, ...(env ? { env } : {}) };
  await cfg.update('acpAgents', map, vscode.ConfigurationTarget.Global);
  await cfg.update('acpAgent', id, vscode.ConfigurationTarget.Global);

  // 需互動登入的（非 npx）→ 開終端機。
  if (loginCmd) {
    const term = vscode.window.createTerminal(`ACP 登入：${label}`);
    term.show();
    term.sendText(loginCmd);
  }
  void vscode.window.showInformationMessage(
    a.npx
      ? `已設定 ${label}（零設定、用既有登入）。AGENT 下拉/＋成員 已可選它。`
      : `已設定 ${label}；終端機已開、請完成登入（${a.loginHint || ''}）。AGENT 下拉/＋成員 已可選它。`,
  );
  return id;
}

export async function pickAcpAgentInteractive(): Promise<string | undefined> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const list = acpAgentList();
  const items: Array<vscode.QuickPickItem & { id?: string; add?: boolean }> = list.map((a) => ({
    label: a.label,
    description: DEFAULT_ACP_COMMANDS[a.id] ? '零設定可用' : '已設定',
    id: a.id,
  }));
  items.push({
    label: '＋ 新增／設定其他 ACP 代理…',
    detail: 'Gemini／Hermes／Goose／OpenCode／Qwen… 或自訂命名（選執行檔→填指令→登入）',
    add: true,
  });
  const current = (cfg.get<string>('acpAgent') || 'claude').trim();
  const pick = await showQuickPickEsc(items, {
    placeHolder: `選哪個外部 ACP 代理？（目前：${ACP_AGENT_LABELS[current] || current}）`,
    ignoreFocusOut: true,
  });
  if (!pick) return undefined;
  if (pick.add) {
    return await acpSetupWizard(); // 精靈設定完回傳新代理 id
  }
  if (pick.id) {
    await cfg.update('acpAgent', pick.id, vscode.ConfigurationTarget.Global);
    void vscode.window.showInformationMessage(`已選外部 ACP 代理：${ACP_AGENT_LABELS[pick.id] || pick.id}。新對話／＋成員 用它。`);
    return pick.id;
  }
  return undefined;
}

export function resolveAcpLaunch(agentId?: string): { launch: AcpLaunchSpec; label: string } | undefined {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  // 代理 id 優先序：stack 解析出的（acp:<id>）→ 設定 aiKing.acpAgent → claude。
  const id = (agentId || cfg.get<string>('acpAgent') || 'claude').trim();
  const agents = cfg.get<Record<string, { command?: string; env?: Record<string, string>; cwd?: string }>>(
    'acpAgents',
  ) || {};
  const spec = agents[id];
  const command = (spec?.command && spec.command.trim()) || DEFAULT_ACP_COMMANDS[id];
  if (!command) return undefined;
  return { launch: { command, env: spec?.env, cwd: spec?.cwd }, label: id };
}

export interface CompactHandoff {
  /** 索引: 一句話路由 — 這段對話在幹嘛。 */
  index: string;
  /** 摘要: 現狀 / 關鍵決策 / 待辦，中等長度；壓縮塊放進 active 取代舊訊息。 */
  summary: string;
}

export interface ArchiveEntry {
  /** archive entry 唯一 id。 */
  id: string;
  /** 來源對話 session id。 */
  sessionId: string;
  /** 壓縮時間（ms since epoch）。 */
  ts: number;
  /** LLM 生成的三層交接（索引 + 摘要）；全文層 = messages。 */
  handoff: CompactHandoff;
  /** 被壓掉的原始訊息全文（可召回回 active）。 */
  messages: SessionMessage[];
  /** 壓縮當下保留在 active 的訊息數（記錄用）。 */
  keptCount: number;
}

function genArchiveId(): string {
  // 12 hex from timestamp + 8 from random — 與 sessions.ts genId 同形，無 npm 依賴。
  const t = Date.now().toString(16).padStart(12, '0');
  const r = Math.floor(Math.random() * 0xffffffff).toString(16).padStart(8, '0');
  return `${t}-${r}`;
}

export class ArchiveStore {
  private readonly rootDir: vscode.Uri;
  private readonly textEncoder = new TextEncoder();
  private readonly textDecoder = new TextDecoder();

  constructor(private readonly ctx: vscode.ExtensionContext) {
    this.rootDir = vscode.Uri.joinPath(ctx.globalStorageUri, 'compact-archive');
  }

  /** 冪等：建好 globalStorage 與 archive 目錄。 */
  async init(): Promise<void> {
    for (const dir of [this.ctx.globalStorageUri, this.rootDir]) {
      try {
        await vscode.workspace.fs.createDirectory(dir);
      } catch (e: any) {
        if (e?.code !== 'FileExists' && e?.code !== 'EEXIST') {
          console.warn(`[ai-king] ArchiveStore.init: ${e?.message || String(e)}`);
        }
      }
    }
  }

  /** 檔名安全的 sessionId 前綴（只留 [A-Za-z0-9_-]、防路徑穿越）。 */
  private safeSid(sessionId: string): string {
    return sessionId.replace(/[^A-Za-z0-9_-]/g, '_');
  }

  private fileFor(entry: ArchiveEntry): vscode.Uri {
    const name = `${this.safeSid(entry.sessionId)}__${entry.ts}__${entry.id}.json`;
    return vscode.Uri.joinPath(this.rootDir, name);
  }

  /**
   * 寫一個 archive entry，tmp → rename 原子落盤。
   * ⛔ 壓縮永動機鐵則: 呼叫端必須「本方法 resolve（落盤成功）後才動 active session」——
   * 全文先安全落地，active 才可真刪，中斷也不丟（work-loss bug 的根治對策）。
   * 失敗 throw（呼叫端據此中止壓縮、保留 active 原文）。
   * @returns 落盤成功的 entry（含生成的 id）。
   */
  async archive(
    sessionId: string,
    handoff: CompactHandoff,
    messages: SessionMessage[],
    keptCount: number,
  ): Promise<ArchiveEntry> {
    await this.init();
    const entry: ArchiveEntry = {
      id: genArchiveId(),
      sessionId,
      ts: Date.now(),
      handoff,
      messages,
      keptCount,
    };
    const bytes = this.textEncoder.encode(JSON.stringify(entry, null, 2));
    const dest = this.fileFor(entry);
    const tmp = vscode.Uri.joinPath(this.rootDir, `.${entry.id}.tmp`);
    await vscode.workspace.fs.writeFile(tmp, bytes);
    try {
      await vscode.workspace.fs.rename(tmp, dest, { overwrite: true });
    } catch (e) {
      // rename 失敗 → 清掉孤兒 tmp，再把錯誤拋給呼叫端（壓縮中止、active 不動）。
      try { await vscode.workspace.fs.delete(tmp); } catch { /* already gone */ }
      throw e;
    }
    return entry;
  }

  /** 列某對話的所有 archive entry（新 → 舊），只讀檔名不讀內容（快）。 */
  async listForSession(
    sessionId: string,
  ): Promise<{ id: string; ts: number; file: vscode.Uri }[]> {
    await this.init();
    const prefix = `${this.safeSid(sessionId)}__`;
    let entries: [string, vscode.FileType][];
    try {
      entries = await vscode.workspace.fs.readDirectory(this.rootDir);
    } catch {
      return [];
    }
    const out: { id: string; ts: number; file: vscode.Uri }[] = [];
    for (const [name, type] of entries) {
      if (type !== vscode.FileType.File) continue;
      if (!name.startsWith(prefix) || !name.endsWith('.json')) continue;
      // <sid>__<ts>__<id>.json
      const parts = name.slice(0, -5).split('__');
      const ts = Number(parts[1]) || 0;
      const id = parts[2] || '';
      out.push({ id, ts, file: vscode.Uri.joinPath(this.rootDir, name) });
    }
    out.sort((a, b) => b.ts - a.ts);
    return out;
  }

  async load(file: vscode.Uri): Promise<ArchiveEntry | null> {
    try {
      const buf = await vscode.workspace.fs.readFile(file);
      const parsed = JSON.parse(this.textDecoder.decode(buf)) as ArchiveEntry;
      if (!parsed || !Array.isArray(parsed.messages)) return null;
      return parsed;
    } catch {
      return null;
    }
  }

  /** 召回某對話最近一次壓縮的全文（可召回的核心入口）。 */
  async latestForSession(sessionId: string): Promise<ArchiveEntry | null> {
    const list = await this.listForSession(sessionId);
    if (list.length === 0) return null;
    return this.load(list[0].file);
  }
}

