export interface AuthorityEvent {
  type: string;
  [k: string]: unknown;
}

function roomKey(room: string, token: string): Buffer {
  return crypto.createHash('sha256').update(`${room}:${token}`).digest(); // 32 bytes
}

export function encryptText(room: string, token: string, plain: string): string {
  if (!token) return plain; // no key material → passthrough (local-only edge)
  const key = roomKey(room, token);
  const iv = crypto.randomBytes(12);
  const c = crypto.createCipheriv('aes-256-gcm', key, iv);
  const ct = Buffer.concat([c.update(plain, 'utf8'), c.final()]);
  const tag = c.getAuthTag();
  return 'e1:' + Buffer.concat([iv, tag, ct]).toString('base64');
}

export function decryptText(room: string, token: string, blob: string): string {
  if (!blob || typeof blob !== 'string') return blob;
  if (!blob.startsWith('e1:')) {
    // A non-e1: blob is plaintext. In a keyed room (non-empty token) that means a
    // message was sent without E2E — do NOT render it as a normal message; flag it.
    return token ? PLAINTEXT_IN_ENCRYPTED_ROOM : blob;
  }
  if (!token) return blob;
  try {
    const raw = Buffer.from(blob.slice(3), 'base64');
    const iv = raw.subarray(0, 12);
    const tag = raw.subarray(12, 28);
    const ct = raw.subarray(28);
    const d = crypto.createDecipheriv('aes-256-gcm', roomKey(room, token), iv);
    d.setAuthTag(tag);
    return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
  } catch {
    return '🔒（無法解密：房間鑰匙不符）';
  }
}

function toHttp(url: string): string {
  return url.replace(/^ws:/i, 'http:').replace(/^wss:/i, 'https:').replace(/\/+$/, '');
}

function httpJson(method: string, urlStr: string, body?: unknown): Promise<{ status: number; json: Record<string, unknown> }> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try { u = new URL(urlStr); } catch { reject(new Error('bad url')); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const data = body !== undefined ? JSON.stringify(body) : undefined;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === 'https:' ? 443 : 80),
        path: u.pathname + u.search,
        method,
        headers: data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {},
      },
      (res) => {
        let d = '';
        res.on('data', (c) => { d += c; });
        res.on('end', () => { try { resolve({ status: res.statusCode || 0, json: JSON.parse(d || '{}') }); } catch { resolve({ status: res.statusCode || 0, json: {} }); } });
      },
    );
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

export class AuthorityClient {
  private base: string;
  private es?: http.ClientRequest;
  private closed = false;
  // Per-connection identity binding secret minted by the server in the state
  // frame. Required on every mutating POST so the server can prove "who is
  // speaking" (the room token only proves "I hold the key"). Refreshed on each
  // (re)subscribe; cleared on close.
  private sid = '';

  // Optional hook: the server now gates /sub to roster members (anti-eavesdrop).
  // A fresh joiner subscribes BEFORE the server knows them → 403 'not a member'.
  // When that happens we invoke this hook (the panel wires it to joinSelf) to
  // register, then retry the subscribe quickly instead of waiting a full cycle.
  private onNeedJoin?: () => Promise<void> | void;
  // [1.6.4] 致命錯回呼：連線收到無法靠重連解決的錯（bad token＝鑰匙跟伺服器不符）時觸發，
  // 讓上層明確提示＋引導，而非靜默無限重連（同名群組重建撞舊 token 的烏龍根治）。
  private onFatal?: (kind: string) => void;
  // [1.9.3] 診斷回呼：/sub 收到的每個 4xx 閘門結果（403 not-a-member / bad token /
  // 其他狀態）原本全被 client 內部吞掉，邀人最容易卡的身分閘/token 閘完全不可觀測。
  // panel 把它接到 glog，一次測試就看得出「卡在連線中」到底是哪道閘。
  private onDiag?: (tag: string, detail: string) => void;
  private needJoinRetries = 0;
  private readonly maxNeedJoinRetries = 6;
  // [never-blank] 連線狀態回呼：SSE 斷線 / 530 / 串流中斷時觸發 'reconnecting'，讓面板
  // 顯示「重新連線中」而非卡在假「已連線」（主流聊天 app 斷線必這樣提示）。
  private onStatus?: (state: string) => void;
  // 重連退避計數（指數退避＋jitter，主流做法，避免多客戶端同步雪崩重連）。
  private reconnectAttempts = 0;
  // [互踢止血 2026-06-16] 「連線穩定存活夠久才重置退避」的計時器。同一個身分在多台/多視窗連同房時，
  // 伺服器會互踢（一身分一連線的舊規則）；舊版「一連上就重置退避」→ 每次被踢前的短暫連線都把退避歸零
  // →永遠停在 2 秒狂閃。改成撐滿 STABLE_MS 才重置：撐不到（被踢）退避就遞增（2s→20s），風暴大減。
  // ⛔這只是減緩風暴的純客戶端止血；真正「一帳號多裝置多通道並存」要伺服器放行同 id 多連線（authority.mjs）。
  private stableTimer: ReturnType<typeof setTimeout> | undefined;
  private readonly STABLE_MS = 10000;
  // [1.24.22 業界對齊] 重連通知寬限：斷線後「不立刻」喊「重新連線中」。主流做法是短暫斷線
  //   （Reload／SSE 重建／伺服器互踢瞬斷，通常 1-3 秒就連回）靜默恢復、不閃 UI；寬限期過了
  //   還沒連上才通知。連上（subscribe 拿到真 stream）時清掉這個待發計時器＝瞬斷完全不顯示。
  private reconnectingNotice: ReturnType<typeof setTimeout> | undefined;
  private readonly RECONNECT_GRACE_MS = 4000;

  constructor(
    base: string,
    private readonly room: string,
    private readonly token: string,
    private readonly me: string,
    private readonly id: string,
    private readonly onEvent: (ev: AuthorityEvent) => void,
    onNeedJoin?: () => Promise<void> | void,
    onFatal?: (kind: string) => void,
    onDiag?: (tag: string, detail: string) => void,
    onStatus?: (state: string) => void,
  ) {
    this.base = toHttp(base);
    this.onNeedJoin = onNeedJoin;
    this.onFatal = onFatal;
    this.onDiag = onDiag;
    this.onStatus = onStatus;
  }

  connect(): void { this.subscribe(); }

  private subscribe(): void {
    if (this.closed) return;
    // A new SSE connection mints a fresh sid; the old one is dead. Drop it so we
    // never POST a stale sid (the server would reject it) before the new state
    // frame arrives with the replacement.
    this.sid = '';
    const url = `${this.base}/sub?room=${encodeURIComponent(this.room)}&token=${encodeURIComponent(this.token)}&me=${encodeURIComponent(this.me)}&id=${encodeURIComponent(this.id)}`;
    let u: URL;
    try { u = new URL(url); } catch { return; }
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.get(
      { hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search, headers: { Accept: 'text/event-stream' } },
      (res) => {
        // Non-2xx → not an SSE stream. The body is a JSON error. The common case
        // for a fresh joiner is 403 'not a member' (the server gates /sub to the
        // roster): register via onNeedJoin then retry quickly. Other errors fall
        // back to the slow reconnect cycle.
        if (res.statusCode && res.statusCode >= 400) {
          let body = '';
          res.on('data', (c) => { body += c.toString(); });
          res.on('end', () => {
            if (this.closed) return;
            let reason = '';
            try { reason = (JSON.parse(body || '{}') as { error?: string }).error || ''; } catch { /* */ }
            if (res.statusCode === 403 && /not a member/i.test(reason) && this.onNeedJoin && this.needJoinRetries < this.maxNeedJoinRetries) {
              this.needJoinRetries++;
              this.onDiag?.('sub:403', `not-a-member retry=${this.needJoinRetries}/${this.maxNeedJoinRetries} me="${this.me}"`);
              void (async () => {
                try { await this.onNeedJoin?.(); } catch { /* */ }
                if (!this.closed) setTimeout(() => this.subscribe(), 400);
              })();
              return;
            }
            // [1.6.4] bad token＝本機鑰匙跟伺服器上同名房間不符（多半刪了同名群組重建）。
            // 靜默無限重連對 user 就是「連不上、零頭緒」。改成觸發 onFatal（上層提示＋引導），
            // 並停止重連——避免無謂洗連線、也讓 user 知道該怎麼修。
            if (/bad token/i.test(reason)) {
              this.onDiag?.('sub:fatal', `bad-token me="${this.me}"`);
              this.onFatal?.('bad-token');
              return;
            }
            // [1.9.3] 其他 4xx（403 not-a-member 但 retry 已用盡、400、409 dissolved…）
            // 以前完全靜默→「卡在連線中」零線索。吐出狀態碼與 reason 再走慢重連。
            // [never-blank] 5xx（含 Cloudflare 530 隧道斷）也走這裡：scheduleReconnect 通知
            // 面板「重新連線中」而非繼續假裝已連線，並退避重連。
            this.onDiag?.('sub:status', `${res.statusCode} ${reason || '(no reason)'} me="${this.me}"`);
            this.scheduleReconnect();
          });
          res.on('error', () => this.scheduleReconnect());
          return;
        }
        this.needJoinRetries = 0; // a real stream → reset the join-retry budget
        // [互踢止血 2026-06-16] 不再「一連上就重置退避」（互踢時每次短暫連上都歸零→永遠 2s 狂閃）；
        // 改成撐滿 STABLE_MS 還連著才重置退避。連線一斷（含被踢）scheduleReconnect 先清掉這計時器。
        if (this.stableTimer) clearTimeout(this.stableTimer);
        this.stableTimer = setTimeout(() => { this.reconnectAttempts = 0; }, this.STABLE_MS);
        // [1.24.22] 連上了（真 stream）→ 取消「待發的重新連線中」通知（寬限期內連回＝靜默、不閃）。
        if (this.reconnectingNotice) { clearTimeout(this.reconnectingNotice); this.reconnectingNotice = undefined; }
        let buf = '';
        res.on('data', (c) => {
          buf += c.toString();
          let i: number;
          while ((i = buf.indexOf('\n\n')) >= 0) {
            const block = buf.slice(0, i);
            buf = buf.slice(i + 2);
            const m = block.match(/data: (.+)/);
            if (m) { try { this.handle(JSON.parse(m[1]) as AuthorityEvent); } catch { /* keepalive / partial */ } }
          }
        });
        res.on('end', () => this.scheduleReconnect());
        res.on('error', () => this.scheduleReconnect());
      },
    );
    req.on('error', () => this.scheduleReconnect());
    this.es = req;
  }

  /**
   * Reconnect after a drop, telling the panel we're reconnecting (so it shows
   * "重新連線中" instead of a stale "已連線"), with exponential backoff + jitter
   * (mainstream practice — avoids many clients retrying in lock-step). Reset to 0
   * the moment a real stream opens.
   */
  private scheduleReconnect(): void {
    if (this.closed) return;
    if (this.stableTimer) { clearTimeout(this.stableTimer); this.stableTimer = undefined; }
    // [1.24.22 業界對齊] 不立刻喊「重新連線中」——排一個寬限計時器，RECONNECT_GRACE_MS 後仍未
    //   連上才通知面板（短暫瞬斷靜默恢復、不閃 UI）；連上時 subscribe 會清掉它。已排過就不重排。
    if (!this.reconnectingNotice) {
      this.reconnectingNotice = setTimeout(() => {
        this.reconnectingNotice = undefined;
        if (!this.closed) this.onStatus?.('reconnecting');
      }, this.RECONNECT_GRACE_MS);
    }
    const n = Math.min(this.reconnectAttempts++, 5);
    const base = Math.min(2000 * Math.pow(1.6, n), 20000); // 2s → 20s cap
    const jitter = Math.floor(base * 0.25 * Math.random());
    setTimeout(() => { if (!this.closed) this.subscribe(); }, base + jitter);
  }

  /**
   * Offline-capable local page: read the room's channel.jsonl mirror (ciphertext
   * verbatim), decrypt, newest-last — SAME shape as history(). Lets the panel show
   * the last known conversation instantly on open and survive a server outage
   * (530) without ever blanking. Synchronous local file read; never throws.
   */
  localHistory(limit = 20): Array<Record<string, unknown>> {
    let rows: Array<Record<string, unknown>>;
    try { rows = readMirrorTail(this.room, limit) as unknown as Array<Record<string, unknown>>; }
    catch { return []; }
    for (const m of rows) {
      if (typeof m.text === 'string') m.text = decryptText(this.room, this.token, m.text as string);
    }
    return rows;
  }

  /** Decrypt message content before handing the event up to the panel. */
  private handle(ev: AuthorityEvent): void {
    // Capture the per-connection identity-binding secret from the state frame.
    if (ev.type === 'state' && typeof (ev as { sid?: unknown }).sid === 'string') {
      this.sid = (ev as unknown as { sid: string }).sid;
    }
    if (ev.type === 'msg' && ev.message && typeof (ev.message as { text?: unknown }).text === 'string') {
      // [1.8.0 §10.3-1] 鏡像必須在解密「之前」做：本機 channel.jsonl 存的是密文原樣
      // （跟伺服器同格式），伺服器資料丟失時 POST /room/<r>/import 原樣搬回即自救。
      appendMirror(this.room, ev.message as Record<string, unknown>);
      (ev.message as { text: string }).text = decryptText(this.room, this.token, (ev.message as { text: string }).text);
    }
    this.onEvent(ev);
  }

  /** True once the server has minted our identity-binding sid (state frame seen). */
  hasSession(): boolean { return !!this.sid; }

  // [1.9.26] signalKind = PLAINTEXT control-signal label (metadata, never encrypted).
  // The server uses it to drop PURELY TRANSIENT signals (read receipts) from history
  // while still broadcasting them live — it can't peek the encrypted `read:` prefix
  // itself. Empty for normal chat. Only 'read' is acted on server-side today.
  // [訊息層去重 2026-06-16] replyTo＝觸發訊息 seq。內建 AI 回覆帶上後，伺服器對 (from, replyTo)
  // 去重：多開 VS Code 視窗各驅動同一 AI、對同一個 @ 只會落地第一條回覆、不雙回。0＝不去重（向後相容）。
  async send(from: string, text: string, senderKind = '', signalKind = '', replyTo = 0): Promise<Record<string, unknown>> {
    const ct = encryptText(this.room, this.token, text);
    const body: Record<string, unknown> = { token: this.token, sid: this.sid, from, text: ct, senderKind, signalKind };
    if (replyTo > 0) body.replyTo = replyTo;
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/msg`, body);
    return r.json;
  }
  async join(member: unknown): Promise<Record<string, unknown>> {
    // sid may be empty on a cold-start self-join (before the state frame lands);
    // the server allows a sid-less SELF join, so this is safe.
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/join`, { token: this.token, sid: this.sid, member });
    return r.json;
  }
  /**
   * [10.2] 心跳：刷新本成員在伺服器上的 lastSeen（在線判定）。回傳完整 {status,json}
   * 讓呼叫端辨識「舊伺服器沒有這個 action（4xx）」並靜默降級——舊伺服器收到未知 action
   * 回 404 {error:'unknown action'}，呼叫端吞掉即可，其餘行為完全不變（相容鐵律）。
   */
  async heartbeat(name?: string, ids?: string[]): Promise<{ status: number; json: Record<string, unknown> }> {
    // [1.9.16] ids = 本機驅動的 AI 成員 id 清單；伺服器逐一刷新它們的 lastSeen＝在線
    // （解「AI 成員沒自己連線、心跳只刷使用者 → AI 永遠離線」）。
    return httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/heartbeat`, {
      token: this.token, sid: this.sid, ...(name ? { name } : {}), ...(ids && ids.length ? { ids } : {}),
    });
  }
  async leave(id: string): Promise<Record<string, unknown>> {
    // Self-leave only — the server derives the caller from the sid-bound socket
    // and removes ONLY that id. Removing someone else goes through kick().
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/leave`, { token: this.token, sid: this.sid, id });
    return r.json;
  }
  async kick(id: string): Promise<Record<string, unknown>> {
    // Force-remove another member — owner/admin only (server-gated by sid role).
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/kick`, { token: this.token, sid: this.sid, id });
    return r.json;
  }
  /** Mute a member (owner/admin). durationSec: seconds; -1 = permanent. Server clamps [60,86400]. */
  async mute(id: string, durationSec: number, reason?: string): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/mute`, { token: this.token, sid: this.sid, id, durationSec, reason });
    return r.json;
  }
  async unmute(id: string): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/unmute`, { token: this.token, sid: this.sid, id });
    return r.json;
  }
  /** Rename the group's DISPLAY name (owner only). Does not touch the room key, so
   *  the E2E key (sha256(room:token)) and all ciphertext history stay valid. */
  async rename(name: string): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/rename`, { token: this.token, sid: this.sid, name });
    return r.json;
  }
  async dissolve(): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/dissolve`, { token: this.token, sid: this.sid });
    return r.json;
  }
  /** [2026-06-18 user 權限細分] 群主把群主原子轉讓給一位真人成員（目標升 owner、自己降 admin）；轉讓後可離開群組。 */
  async transferOwner(id: string): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/transfer-owner`, { token: this.token, sid: this.sid, id });
    return r.json;
  }
  async clear(): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/clear`, { token: this.token, sid: this.sid });
    return r.json;
  }
  async memberUpdate(id: string, patch: Record<string, unknown>): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/member-update`, { token: this.token, sid: this.sid, id, patch });
    return r.json;
  }
  /** [2026-06-16] 刪單則訊息（按 seq）：伺服器移除歷史該行＋廣播 msg.delete；權限階層由伺服器判。 */
  async deleteMessage(seq: number): Promise<Record<string, unknown>> {
    const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/delete-message`, { token: this.token, sid: this.sid, seq });
    return r.json;
  }
  /** Cursor pagination: before=0 → newest page; pass returned nextCursor to page up. */
  async history(before = 0, limit = 20): Promise<{ messages: Array<Record<string, unknown>>; nextCursor: number | null; hasMore: boolean }> {
    const r = await httpJson('GET', `${this.base}/room/${encodeURIComponent(this.room)}/history?token=${encodeURIComponent(this.token)}&before=${before}&limit=${limit}`);
    const j = r.json as { messages?: Array<Record<string, unknown>>; nextCursor?: number | null; hasMore?: boolean };
    const messages = Array.isArray(j.messages) ? j.messages : [];
    for (const m of messages) {
      // [1.8.0 §10.3-1] 歷史分頁回放也鏡像（解密前、密文原樣；seq 去重在 appendMirror）
      // —— 這樣首次連線拉回的舊訊息也補得進本機鏡像。
      appendMirror(this.room, m);
      if (typeof m.text === 'string') m.text = decryptText(this.room, this.token, m.text as string);
    }
    return { messages, nextCursor: j.nextCursor ?? null, hasMore: !!j.hasMore };
  }
  async state(): Promise<Record<string, unknown>> {
    const r = await httpJson('GET', `${this.base}/room/${encodeURIComponent(this.room)}/state?token=${encodeURIComponent(this.token)}`);
    return r.json;
  }

  close(): void { this.closed = true; this.sid = ''; try { this.es?.destroy(); } catch { /* */ } }
}

constructor(
  base: string,
  private readonly room: string,
  private readonly token: string,
  private readonly me: string,
  private readonly id: string,
  private readonly onEvent: (ev: AuthorityEvent) => void,
  onNeedJoin?: () => Promise<void> | void,
  onFatal?: (kind: string) => void,
  onDiag?: (tag: string, detail: string) => void,
  onStatus?: (state: string) => void,
) {
  this.base = toHttp(base);
  this.onNeedJoin = onNeedJoin;
  this.onFatal = onFatal;
  this.onDiag = onDiag;
  this.onStatus = onStatus;
}

