          if (res.statusCode === 403 && /not a member/i.test(reason) && this.onNeedJoin && this.needJoinRetries < this.maxNeedJoinRetries) {
            this.needJoinRetries++;
            this.onDiag?.('sub:403', `not-a-member retry=${this.needJoinRetries}/${this.maxNeedJoinRetries} me="${this.me}"`);
            void (async () => {
              try { await this.onNeedJoin?.(); } catch { /* */ }
              if (!this.closed) setTimeout(() => this.subscribe(), 400);
            })();
            return;
          }
          // [1.6.4] bad token＝本機鑰匙跟伺服器上同名房間不符（多半刪了同名群組重建）。
          // 靜默無限重連對 user 就是「連不上、零頭緒」。改成觸發 onFatal（上層提示＋引導），
          // 並停止重連——避免無謂洗連線、也讓 user 知道該怎麼修。
          if (/bad token/i.test(reason)) {
