private scheduleReconnect(): void {
  if (this.closed) return;
  if (this.stableTimer) { clearTimeout(this.stableTimer); this.stableTimer = undefined; }
  // [1.24.22 業界對齊] 不立刻喊「重新連線中」——排一個寬限計時器，RECONNECT_GRACE_MS 後仍未
