async heartbeat(name?: string, ids?: string[]): Promise<{ status: number; json: Record<string, unknown> }> {
  // [1.9.16] ids = 本機驅動的 AI 成員 id 清單；伺服器逐一刷新它們的 lastSeen＝在線
  // （解「AI 成員沒自己連線、心跳只刷使用者 → AI 永遠離線」）。
  return httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/heartbeat`, {
    token: this.token, sid: this.sid, ...(name ? { name } : {}), ...(ids && ids.length ? { ids } : {}),
  });
}

async leave(id: string): Promise<Record<string, unknown>> {
  // Self-leave only — the server derives the caller from the sid-bound socket
  // and removes ONLY that id. Removing someone else goes through kick().
  const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/leave`, { token: this.token, sid: this.sid, id });
  return r.json;
}

async kick(id: string): Promise<Record<string, unknown>> {
  // Force-remove another member — owner/admin only (server-gated by sid role).
  const r = await httpJson('POST', `${this.base}/room/${encodeURIComponent(this.room)}/kick`, { token: this.token, sid: this.sid, id });
  return r.json;
}

