  return r.json;
}

async history(before = 0, limit = 20): Promise<{ messages: Array<Record<string, unknown>>; nextCursor: number | null; hasMore: boolean }> {
  const r = await httpJson('GET', `${this.base}/room/${encodeURIComponent(this.room)}/history?token=${encodeURIComponent(this.token)}&before=${before}&limit=${limit}`);
  const j = r.json as { messages?: Array<Record<string, unknown>>; nextCursor?: number | null; hasMore?: boolean };
  const messages = Array.isArray(j.messages) ? j.messages : [];
  for (const m of messages) {
    // [1.8.0 §10.3-1] 歷史分頁回放也鏡像（解密前、密文原樣；seq 去重在 appendMirror）
    // —— 這樣首次連線拉回的舊訊息也補得進本機鏡像。
    appendMirror(this.room, m);
    if (typeof m.text === 'string') m.text = decryptText(this.room, this.token, m.text as string);
  }
  return { messages, nextCursor: j.nextCursor ?? null, hasMore: !!j.hasMore };
}

async state(): Promise<Record<string, unknown>> {
  const r = await httpJson('GET', `${this.base}/room/${encodeURIComponent(this.room)}/state?token=${encodeURIComponent(this.token)}`);
  return r.json;
}

export function initAuthority(ctx: vscode.ExtensionContext): void {
  script = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'authority.mjs').fsPath;
}

export function authorityUrl(): string {
  const cfg = vscode.workspace.getConfiguration('aiKing').get<string>('authorityUrl');
  return (cfg && cfg.trim()) || `http://127.0.0.1:${AUTHORITY_PORT}`;
}

export function isLocalUrl(url: string): boolean {
  return /(?:\/\/)?(?:127\.0\.0\.1|localhost)\b/.test(url || '');
}

function isLocalAuthority(): boolean {
  return isLocalUrl(authorityUrl());
}

function isRemoteInsecure(url: string): boolean {
  const u = url.trim().toLowerCase();
  const insecure = u.startsWith('http://') || u.startsWith('ws://');
  if (!insecure) return false;
  const local = /(?:\/\/)?(?:127\.0\.0\.1|localhost|192\.168\.|10\.|172\.(?:1[6-9]|2\d|3[01])\.)/.test(u);
  return !local;
}

export function ensureAuthorityServer(forUrl?: string): void {
  // Per-room aware: a room whose server is REMOTE must not spawn the local one.
  // Default to the global authorityUrl when no specific room url is passed.
  const target = (forUrl && forUrl.trim()) || authorityUrl();
  if (!isLocalUrl(target)) return; // this room is hosted elsewhere → don't spawn
  if (proc && !proc.killed) return;
  if (!script) return;
  // [1.9.0 紅藍稽核 H5+M1] spawn 前先探 port：若已有 authority server 在跑（本 session
  // 或前次 VS Code crash/強殺留下的孤兒），**重用、不再 spawn 重複** → 根治 port 39820
  // 堆積數十個 node.exe + 後續 EADDRINUSE。不盲殺 PID（避免誤殺 PID 被回收後重用的他人
  // 程序）；孤兒服務本就堪用，watchdog 會在它真死掉時才重 spawn。
  void (async () => {
    if (proc && !proc.killed) return;
    if (await probePort()) return; // 已有服務在跑 → 重用，不 spawn 重複
    doSpawnAuthority();
  })();
}

function doSpawnAuthority(): void {
  if (!script) return;
  const home = resolveBridgeHome();
  const bindAll = vscode.workspace.getConfiguration('aiKing').get<boolean>('authorityBindAll', false);
  const args = [
    script,
    '--port', String(AUTHORITY_PORT),
    '--host', bindAll ? '0.0.0.0' : '127.0.0.1',
    '--data', path.join(home, 'data', 'channels'),
  ];
  try {
    const { cmd, extraEnv } = resolveNode();
    let stdio: cp.StdioOptions = 'ignore';
    try {
      const logPath = path.join(home, 'authority.log');
      fs.mkdirSync(path.dirname(logPath), { recursive: true });
      const out = fs.openSync(logPath, 'a');
      stdio = ['ignore', out, out];
    } catch {
      /* fall back to ignoring output */
    }
    proc = cp.spawn(cmd, args, {
      env: { ...process.env, ...extraEnv, BRIDGE_HOME: home },
      stdio,
      windowsHide: true,
    });
    // [1.9.0 H5] 記 PID 到檔，供優雅關閉(deactivate)精準殺自家程序。
    try {
      if (proc.pid) fs.writeFileSync(path.join(home, 'authority.pid'), String(proc.pid), 'utf8');
    } catch { /* best-effort */ }
    proc.on('exit', () => { proc = undefined; });
    proc.on('error', () => { proc = undefined; });
    // eslint-disable-next-line no-console
    console.log(`[ai-king] authority server up on http://127.0.0.1:${AUTHORITY_PORT} via ${cmd}`);
  } catch {
    /* best-effort */
  }
}

function probePort(): Promise<boolean> {
  return new Promise((resolve) => {
    const sock = net.connect(AUTHORITY_PORT, '127.0.0.1');
    let done = false;
    const finish = (alive: boolean) => {
      if (done) return;
      done = true;
      try { sock.destroy(); } catch { /* */ }
      resolve(alive);
    };
    sock.once('connect', () => finish(true));
    sock.once('error', () => finish(false));
    sock.setTimeout(1500, () => finish(false));
  });
}

export function startAuthorityWatchdog(): void {
  if (watchdog) return;
  const tick = async () => {
    if (!isLocalUrl(authorityUrl())) return; // 連別人的 server → 不保活本機
    if (await probePort()) return;            // 還活著 → 沒事
    try { proc?.kill(); } catch { /* */ }     // 死了/殘留 → 清掉再重 spawn
    proc = undefined;
    ensureAuthorityServer();
  };
  void tick(); // 開 VS Code 立即探一次（不必等 30 秒、不必去開 AI King）
  watchdog = setInterval(() => void tick(), 30_000);
  watchdog.unref?.();
}

export function stopAuthorityWatchdog(): void {
  if (watchdog) { clearInterval(watchdog); watchdog = undefined; }
}

export function stopAuthorityServer(): void {
  try { proc?.kill(); } catch { /* already gone */ }
  proc = undefined;
  // [1.9.0 H5] 清自家 PID 檔（優雅關閉路徑；強殺時清不到，靠下次 spawn 前 probePort 重用）。
  try { fs.unlinkSync(path.join(resolveBridgeHome(), 'authority.pid')); } catch { /* */ }
}

export function authorityChosen(ctx: vscode.ExtensionContext): boolean {
  return ctx.globalState.get<boolean>(AUTHORITY_CHOSEN_KEY) === true;
}

export async function runAuthorityPicker(ctx: vscode.ExtensionContext, placeHolder?: string): Promise<boolean> {
  const pick = await showQuickPickEsc(
    [
      { label: '🖥 本機（這台當伺服器）', detail: `http://127.0.0.1:${AUTHORITY_PORT} — 零設定，但只有自己 / 同這台的 AI 能用；別人連不到`, mode: 'local' },
      { label: '🚀 一鍵架到我的 VPS（自動部署＋測通）', detail: '用你存好的 VPS 設定，自動裝伺服器、接上 Cloudflare 隧道、測通後自動填好', mode: 'myvps' },
      { label: '🏠 區網（連群主的電腦）', detail: '同 WiFi 填群主內網 IP；群主端要先開 aiKing.authorityBindAll ＋ 防火牆放行 39820', mode: 'lan' },
      { label: '🌐 連已有的伺服器（填網址）', detail: '伺服器已經架好（你自己 VPS 或別人的），直接貼網址連上', mode: 'vps' },
    ],
    { placeHolder: placeHolder || 'AI 群組伺服器位置（單一真相＋E2E；升級保留）', ignoreFocusOut: true },
  );
  if (!pick) return false;
  // 一鍵架到我的 VPS：自己完成部署 + 測通 + 寫 authorityUrl，不走下面填網址的路徑。
  if (pick.mode === 'myvps') return await deployMyVps(ctx);
  let url = '';
  if (pick.mode === 'lan') {
    const ip = await showInputBoxEsc({
      prompt: '群主電腦的內網 IP（例 192.168.1.20）',
      ignoreFocusOut: true,
      // [1.6.6] 即時驗證：每打一字檢查，IP 對了紅字自動消失。
      validateInput: (v) => {
        const t = (v || '').trim();
        if (!t) return '請輸入 IP';
        if (!/^\d{1,3}(\.\d{1,3}){3}$/.test(t)) return 'IP 格式不正確（例：192.168.1.20）';
        if (t.split('.').some((n) => Number(n) > 255)) return 'IP 每段要 0–255';
        return null;
      },
    });
    if (!ip || !ip.trim()) return false;
    url = `http://${ip.trim()}:${AUTHORITY_PORT}`;
  } else if (pick.mode === 'vps') {
    const v = await showInputBoxEsc({
      prompt: '你的伺服器網址（例 https://chat.你的網域）',
      ignoreFocusOut: true,
      // [1.6.6] 即時驗證：每打一字檢查一次，格式對了紅字自動消失（user 2026-06-12）。
      validateInput: (s) => {
        const t = (s || '').trim();
        if (!t) return '請輸入網址';
        if (!/^(https?|wss?):\/\//i.test(t)) return '網址要以 https:// http:// wss:// 或 ws:// 開頭';
        try { new URL(t); } catch { return '網址格式不正確（例：https://chat.你的網域）'; }
        return null;
      },
    });
    if (!v || !v.trim()) return false;
    url = v.trim();
    // A remote VPS over plain http/ws sends the room token in the clear on the
    // wire (the token derives the E2E key, so this is the worst leak). Warn and
    // let the user confirm rather than silently downgrade transport security.
    if (isRemoteInsecure(url)) {
      const go = await vscode.window.showWarningMessage(
        'AI 群組：你填的遠端伺服器是 http://（非加密）。房間鑰匙會以明文在網路上傳輸，' +
          '可能被中途竊聽。建議改用 https:// 或 wss://（在伺服器前放 TLS）。仍要繼續嗎？',
        { modal: true }, '仍要使用 http',
      );
      if (go !== '仍要使用 http') return false;
    }
  }
  await vscode.workspace.getConfiguration('aiKing').update('authorityUrl', url, vscode.ConfigurationTarget.Global);
  if (pick.mode === 'local') ensureAuthorityServer();
  void vscode.window.showInformationMessage(`AI 群組伺服器位置 → ${url || `本機 127.0.0.1:${AUTHORITY_PORT}`}。重開群組面板生效。`);
  return true;
}

export async function ensureAuthorityChosen(ctx: vscode.ExtensionContext): Promise<void> {
  if (authorityChosen(ctx)) return;
  const done = await runAuthorityPicker(
    ctx,
    '這些群組的對話要存在哪？（之後對話多了想換伺服器要搬資料很麻煩，先選好）',
  );
  if (done) await ctx.globalState.update(AUTHORITY_CHOSEN_KEY, true);
}

export function registerAuthorityCommands(ctx: vscode.ExtensionContext): void {
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.setAuthorityUrl', async () => {
      const done = await runAuthorityPicker(ctx);
      // An explicit invocation of the command IS a deliberate choice — record it
      // so the first-room prompt won't re-ask after the user already set this here.
      if (done) await ctx.globalState.update(AUTHORITY_CHOSEN_KEY, true);
    }),
    vscode.commands.registerCommand('aiKing.bridge.migrateRoom', () => migrateRoom(ctx)),
    vscode.commands.registerCommand('aiKing.bridge.selfHostServer', () => generateSelfHostPackage(ctx)),
    vscode.commands.registerCommand('aiKing.bridge.deployMyVps', () => deployMyVps(ctx)),
  );
}

function readSelfHostVps(): SelfHostVps | null {
  const c = vscode.workspace.getConfiguration('aiKing').get<Partial<SelfHostVps>>('selfHostVps');
  if (c && c.host && c.user && c.sshKey && c.hostname) {
    return { host: c.host.trim(), user: c.user.trim(), sshKey: c.sshKey.trim(), hostname: c.hostname.trim() };
  }
  return null;
}

async function collectSelfHostVps(prev?: SelfHostVps | null): Promise<SelfHostVps | null> {
  const ask = (prompt: string, value = '') =>
    showInputBoxEsc({ prompt, value, ignoreFocusOut: true, validateInput: (v) => (v && v.trim() ? null : '請輸入') });
  const host = await ask('你的 VPS 位址（公網 IP 或網域，例 203.0.113.10 或 vps.example.com）', prev?.host || '');
  if (!host) return null;
  const user = await ask('VPS 登入帳號', prev?.user || 'root');
  if (!user) return null;
  const sshKey = await ask('SSH 私鑰路徑（例 ~/.ssh/vps_deploy）', prev?.sshKey || '~/.ssh/vps_deploy');
  if (!sshKey) return null;
  const hostname = await ask('群組伺服器要用的對外網址（例 group.你的網域）', prev?.hostname || '');
  if (!hostname) return null;
  const cfg: SelfHostVps = { host: host.trim(), user: user.trim(), sshKey: sshKey.trim(), hostname: hostname.trim() };
  await vscode.workspace.getConfiguration('aiKing').update('selfHostVps', cfg, vscode.ConfigurationTarget.Global);
  return cfg;
}

function expandHome(p: string): string {
  return p.startsWith('~') ? path.join(os.homedir(), p.slice(1)) : p;
}

function runCmd(cmd: string, args: string[]): Promise<{ code: number; out: string; err: string }> {
  return new Promise((resolve) => {
    let out = '', err = '';
    let p: cp.ChildProcess;
    try { p = cp.spawn(cmd, args, { windowsHide: true }); }
    catch (e) { resolve({ code: -1, out: '', err: String(e) }); return; }
    p.stdout?.on('data', (d) => { out += d.toString(); });
    p.stderr?.on('data', (d) => { err += d.toString(); });
    p.on('close', (code) => resolve({ code: code ?? -1, out, err }));
    p.on('error', (e) => resolve({ code: -1, out, err: err + String(e) }));
  });
}

function probeHealth(url: string, tries = 8): Promise<'ok' | 'busy' | 'down'> {
  const once = (): Promise<'ok' | 'busy' | 'down'> => new Promise((resolve) => {
    let u: URL;
    try { u = new URL(url.replace(/\/+$/, '') + '/health'); } catch { resolve('down'); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.get(
      { hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: '/health', timeout: 6000 },
      (res) => { let d = ''; res.on('data', (c) => { d += c; }); res.on('end', () => {
        if (res.statusCode !== 200) { resolve('down'); return; }
        resolve(/ai-king-authority/.test(d) ? 'ok' : 'busy');
      }); },
    );
    req.on('error', () => resolve('down'));
    req.on('timeout', () => { req.destroy(); resolve('down'); });
  });
  return (async () => {
    let sawBusy = false;
    for (let i = 0; i < tries; i++) {
      const r = await once();
      if (r === 'ok') return 'ok';
      if (r === 'busy') { sawBusy = true; break; } // occupied → won't self-heal
      await new Promise((res) => setTimeout(res, 3000));
    }
    return sawBusy ? 'busy' : 'down';
  })();
}

export async function deployMyVps(ctx: vscode.ExtensionContext): Promise<boolean> {
  let cfg = readSelfHostVps();
  if (cfg) {
    // Already configured → list it as a CHOICE (confirm / edit), never silently
    // reuse and never make the user retype. This is the「設定過就記住、變成選項」UX.
    const USE = `🚀 用這台：${cfg.hostname}（${cfg.user}@${cfg.host}）`;
    const EDIT = '✏️ 改設定（換 VPS 位址 / 網址 / 金鑰，會帶出現有值）';
    const pick = await showQuickPickEsc([USE, EDIT], {
      placeHolder: '一鍵架到我的 VPS — 用已設定的這台，或改設定', ignoreFocusOut: true,
    });
    if (!pick) return false;
    if (pick === EDIT) {
      const next = await collectSelfHostVps(cfg);
      if (!next) return false;
      cfg = next;
    }
  } else {
    void vscode.window.showInformationMessage('第一次用，先設定你的 VPS（只問這一次，之後就記住變成選項，不用再填）。');
    cfg = await collectSelfHostVps();
    if (!cfg) return false;
  }
  const key = expandHome(cfg.sshKey);
  if (!fs.existsSync(key)) {
    void vscode.window.showErrorMessage(`找不到 SSH 私鑰：${key}。請改 aiKing.selfHostVps.sshKey 後重試。`);
    return false;
  }
  // Windows may lack the OpenSSH client → the scp/ssh spawns below would throw a
  // raw ENOENT. Probe first and give an actionable message.
  const sshProbe = await runCmd('ssh', ['-V']);
  if (sshProbe.code === -1) {
    void vscode.window.showErrorMessage(
      '找不到 ssh / scp（OpenSSH 用戶端）。Windows 請到「設定 → 系統 → 選用功能」安裝「OpenSSH 用戶端」，或確認它在 PATH，再重試一鍵架設。',
    );
    return false;
  }
  const pkgDir = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'self-host').fsPath;
  const target = `${cfg.user}@${cfg.host}`;
  const sshOpts = ['-i', key, '-o', 'StrictHostKeyChecking=no', '-o', 'ConnectTimeout=15'];
  const url = `https://${cfg.hostname}`;
  const vps = cfg; // for closure narrowing

  return await vscode.window.withProgress(
    { location: vscode.ProgressLocation.Notification, title: `架群組伺服器到你的 VPS（${vps.hostname}）`, cancellable: false },
    async (progress): Promise<boolean> => {
      progress.report({ message: '上傳檔案（scp）…' });
      const scp = await runCmd('scp', [
        ...sshOpts,
        path.join(pkgDir, 'authority.mjs'),
        path.join(pkgDir, 'deploy-cloudflared.sh'),
        `${target}:/root/`,
      ]);
      if (scp.code !== 0) {
        void vscode.window.showErrorMessage(`上傳到 VPS 失敗：${(scp.err || scp.out).slice(-300) || '未知錯誤'}`);
        return false;
      }
      progress.report({ message: '安裝 + 接上 Cloudflare 隧道（ssh）…' });
      const ssh = await runCmd('ssh', [...sshOpts, target, `bash /root/deploy-cloudflared.sh '${vps.hostname}'`]);
      if (ssh.code !== 0) {
        void vscode.window.showErrorMessage(`VPS 部署失敗：${(ssh.err || ssh.out).slice(-400) || '未知錯誤'}`);
        return false;
      }
      progress.report({ message: '測試連線（等 DNS / 隧道生效，最多 ~24 秒）…' });
      const health = await probeHealth(url);
      if (health !== 'ok') {
        void vscode.window.showWarningMessage(
          health === 'busy'
            ? `已把群組伺服器裝到 VPS，但網址 ${url} 已經被「別的服務」佔用（它回應的不是群組伺服器）。` +
                `請換一個沒用過的子網域重跑一鍵架（例 group.你的網域），或在 VPS 上把這個網址的隧道改指到群組伺服器的連接埠 39820。`
            : `已把群組伺服器裝到 VPS，但 ${url} 暫時連不上（多半是網域指向 / DNS 還在生效）。` +
                `稍等一兩分鐘，再到「設定 AI 群組伺服器位置 → 連已有的伺服器」手動填 ${url} 即可。`,
        );
        return false;
      }
      await vscode.workspace.getConfiguration('aiKing').update('authorityUrl', url, vscode.ConfigurationTarget.Global);
      await ctx.globalState.update(AUTHORITY_CHOSEN_KEY, true);
      void vscode.window.showInformationMessage(`✅ 群組伺服器已架在你的 VPS：${url}（E2E 加密、隧道對外、測通）。新建 / 搬移的群組都會用它。`);
      return true;
    },
  );
}

export async function generateSelfHostPackage(ctx: vscode.ExtensionContext): Promise<void> {
