function httpPostJson(
  urlStr: string,
  body: unknown,
  timeoutMs = 20000,
): Promise<{ status: number; json: Record<string, unknown> }> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try { u = new URL(urlStr); } catch { reject(new Error('bad url')); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const data = JSON.stringify(body);
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === 'https:' ? 443 : 80),
        path: u.pathname + u.search,
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
      },
      (res) => {
        let d = '';
        res.on('data', (c) => { d += c; });
        res.on('end', () => {
          try { resolve({ status: res.statusCode || 0, json: JSON.parse(d || '{}') }); }
          catch { resolve({ status: res.statusCode || 0, json: {} }); }
        });
      },
    );
    req.on('error', reject);
    req.setTimeout(timeoutMs, () => { req.destroy(new Error('連線逾時')); });
    req.write(data);
    req.end();
  });
}

export async function migrateRoom(ctx: vscode.ExtensionContext): Promise<void> {
  const rooms = listRooms();
  if (!rooms.length) {
    void vscode.window.showInformationMessage('AI 群組：目前沒有任何群組可以搬移。');
    return;
  }
  const roomPick = await showQuickPickEsc(
    rooms.map((r) => ({ label: r, detail: isOnlineRoom(r) ? '🌐 線上' : '🖥 本機' })),
    { placeHolder: '要把哪個群組搬到新伺服器？（對話原封不動帶過去）', ignoreFocusOut: true },
  );
  if (!roomPick) return;
  const room = roomPick.label;

  const dest = await showQuickPickEsc(
    [
      { label: '🏠 區網的另一台電腦', detail: '填那台的內網 IP', mode: 'lan' },
      { label: '🌐 自架 VPS（跨地點 / 長期保存）', detail: '填你的伺服器網址', mode: 'vps' },
    ],
    { placeHolder: `把群組「${room}」搬到哪個新伺服器？`, ignoreFocusOut: true },
  );
  if (!dest) return;
  let target = '';
  if (dest.mode === 'lan') {
    const ip = await showInputBoxEsc({ prompt: '新伺服器（那台電腦）的內網 IP（例 192.168.1.20）', ignoreFocusOut: true, validateInput: (v) => (v && v.trim() ? null : '請輸入 IP') });
    if (!ip || !ip.trim()) return;
    target = `http://${ip.trim()}:${AUTHORITY_PORT}`;
  } else {
    const v = await showInputBoxEsc({ prompt: '新伺服器網址（例 https://chat.你的網域）', ignoreFocusOut: true, validateInput: (s) => (s && s.trim() ? null : '請輸入網址') });
    if (!v || !v.trim()) return;
    target = v.trim();
  }

  const bundle = readRoomBundle(room);
  if (!bundle || !bundle.token) {
    void vscode.window.showErrorMessage(`AI 群組：讀不到群組「${room}」的房間鑰匙，無法搬移。`);
    return;
  }

  const go = await vscode.window.showWarningMessage(
    `把群組「${room}」搬到新伺服器？`,
    {
      modal: true,
      detail: `${bundle.messages.length} 則對話、${bundle.members.length} 位成員 → ${target}\n\n` +
        '對話會複製過去（E2E 加密原樣搬，伺服器看不到明文）。來源這台的資料會保留，' +
        '確認新伺服器沒問題後可自行刪除舊的。搬完會把這台的群組伺服器切到新位置。',
    },
    '開始搬移',
  );
  if (go !== '開始搬移') return;

  const base = target.replace(/^ws:/i, 'http:').replace(/^wss:/i, 'https:').replace(/\/+$/, '');
  const url = `${base}/room/${encodeURIComponent(room)}/import`;
  try {
    const r = await httpPostJson(url, {
      token: bundle.token,
      members: bundle.members,
      messages: bundle.messages,
      maxSeq: bundle.maxSeq,
      by: 'migrator',
    });
    if (r.status === 200 && r.json.ok === true) {
      // Per-room: pin THIS room to the new server via its .relay.json (connectAuthority
      // reads per-room relay first). Also set the global as a convenience default for
      // NEW rooms. Without the per-room write the room would reconnect to the OLD
      // server (its .relay.json still pointed there).
      const existing = readRelayConfig(room);
      writeRelayConfig(room, { relay: target, token: bundle.token, me: existing?.me || '', role: existing?.role || 'owner' });
      await vscode.workspace.getConfiguration('aiKing').update('authorityUrl', target, vscode.ConfigurationTarget.Global);
      await ctx.globalState.update(AUTHORITY_CHOSEN_KEY, true);
      void vscode.window.showInformationMessage(
        `✅ 已把群組「${room}」搬到 ${target}（${(r.json.imported as number) ?? bundle.messages.length} 則對話）。` +
          '這個群組已指向新伺服器——重開它就會接上完整歷史。',
      );
      return;
    }
    if (r.status === 409) {
      void vscode.window.showWarningMessage(
        `AI 群組：新伺服器上已經有群組「${room}」且裡面已有對話（或房間鑰匙不同）。為避免覆蓋已停止搬移。` +
          '請先清空新伺服器上的同名群組，或改用不同群組名。',
      );
      return;
    }
    throw new Error((r.json.error as string) || `伺服器回應 ${r.status}`);
  } catch (e: unknown) {
    await exportRoomForManualMigration(room, target, e instanceof Error ? e.message : String(e));
  }
}

async function exportRoomForManualMigration(room: string, target: string, reason: string): Promise<void> {
  const home = resolveBridgeHome();
  const clean = room.replace(/[^\w-]/g, '');
  const srcDir = path.join(home, 'data', 'channels', clean);
  const outDir = path.join(home, 'migrate-export', clean);
  try {
    fs.mkdirSync(outDir, { recursive: true });
    for (const f of ['channel.jsonl', 'members.json', '.token', 'meta.json']) {
      const s = path.join(srcDir, f);
      if (fs.existsSync(s)) fs.copyFileSync(s, path.join(outDir, f));
    }
  } catch { /* best-effort; the warning below still guides the user */ }
  const pick = await vscode.window.showWarningMessage(
    `AI 群組：連不上新伺服器（${target}）：${reason}。已改成手動搬移——把匯出的資料夾整包複製到` +
      `新伺服器的 data/channels/${clean}/ 底下，重啟對方的 authority.mjs 即可。`,
    '開啟匯出資料夾',
  );
  if (pick === '開啟匯出資料夾') {
    void vscode.commands.executeCommand('revealFileInOS', vscode.Uri.file(outDir));
  }
}

function defaultBridgeHome(): string {
  try { if (fs.existsSync(LEGACY_BRIDGE_HOME)) return LEGACY_BRIDGE_HOME; } catch { /* */ }
  // ~/.aiking/groups：全小寫無空格（Linux/Mac/Windows 三平台慣例），跟 Skill 預設
  // ~/.aiking/skills 同一個根 — AI King 的東西統一住 ~/.aiking/。
  return path.join(os.homedir(), '.aiking', 'groups');
}

export function resolveBridgeHome(): string {
  const cfg = vscode.workspace
    .getConfiguration('aiKing')
    .get<string>('bridgeChannelPath');
  if (cfg && cfg.trim()) return cfg.trim();
  if (process.env.BRIDGE_HOME) return process.env.BRIDGE_HOME;
  if (process.env.BRIDGE_DATA_DIR) return process.env.BRIDGE_DATA_DIR;
  return defaultBridgeHome();
}

function channelsDir(): string {
  return path.join(resolveBridgeHome(), 'data', 'channels');
}

export function sanitizeRoom(s: string): string {
  // [1.6.5] 只擋會壞掉檔案路徑 / URL 的危險字元；繁體中文、空白、一般符號全放行（user
  // 2026-06-12：群組名沒理由限制）。開頭/結尾的點也擋（避免 .. 路徑穿越 / Windows 結尾點）。
  // ⚠ 必須跟 authority.mjs 的 cleanRoom 邏輯「逐字一致」，否則本機房名 ≠ 伺服器房名 → 連不上。
  return (s || '')
    .trim()
    .replace(/[\\/:*?"<>|]/g, '')
    .replace(/^\.+|\.+$/g, '')
    .slice(0, 60);
}

export function bridgeLog(msg: string): void {
  try {
    if (!bridgeLogChannel) bridgeLogChannel = vscode.window.createOutputChannel('AI King 群組');
    const t = new Date();
    const p = (n: number) => String(n).padStart(2, '0');
    bridgeLogChannel.appendLine(`[${p(t.getHours())}:${p(t.getMinutes())}:${p(t.getSeconds())}] ${msg}`);
  } catch { /* logging must never break the caller */ }
}

export function legacySanitizeRoom(s: string): string {
  return (s || '').replace(/[^\w-]/g, '').slice(0, 40);
}

export function resolveRoomId(name: string): string {
  const clean = sanitizeRoom(name);
  const base = channelsDir();
  try {
    if (clean && fs.existsSync(path.join(base, clean))) return clean;
  } catch { /* treat as not found */ }
  const legacy = legacySanitizeRoom(name);
  if (legacy && legacy !== clean) {
    try {
      if (fs.existsSync(path.join(base, legacy, 'channel.jsonl'))) {
        const key = `${name} → ${legacy}`;
        if (!loggedLegacyMappings.has(key)) {
          loggedLegacyMappings.add(key);
          bridgeLog(`legacy 房名映射: ${name} → ${legacy}`);
        }
        return legacy;
      }
    } catch { /* treat as not found */ }
  }
  return clean;
}

export function listRooms(): string[] {
  const base = channelsDir();
  const out: string[] = [];
  try {
    for (const e of fs.readdirSync(base, { withFileTypes: true })) {
      if (
        e.isDirectory() &&
        fs.existsSync(path.join(base, e.name, 'channel.jsonl'))
      ) {
        out.push(e.name);
      }
    }
  } catch {
    /* channels dir may not exist yet */
  }
  // No forced default room — only rooms the user actually created are listed.
  return out.sort((a, b) => a.localeCompare(b));
}

export function createRoom(name: string): boolean {
  const clean = sanitizeRoom(name);
  if (!clean) return false;
  const dir = path.join(channelsDir(), clean);
  try {
    fs.mkdirSync(dir, { recursive: true });
    const f = path.join(dir, 'channel.jsonl');
    if (!fs.existsSync(f)) fs.writeFileSync(f, '', 'utf8');
    return true;
  } catch {
    return false;
  }
}

export function renameRoom(oldName: string, newName: string): boolean {
  const a = sanitizeRoom(oldName);
  const b = sanitizeRoom(newName);
  if (!a || !b || a === 'main' || a === b) return false; // never rename main
  if (isOnlineRoom(a)) return false; // [P0] 線上房改 room id ＝資料脫鉤，硬擋
  const base = channelsDir();
  if (fs.existsSync(path.join(base, b))) return false; // target exists
  try {
    fs.renameSync(path.join(base, a), path.join(base, b));
    return true;
  } catch {
    return false;
  }
}

export function deleteRoom(name: string): boolean {
  // [2026-06-18 fix · user 認可「解散=真刪整房」] 用 resolveRoomId 不是 sanitizeRoom：1.6.4 前建的含中文/
  // 空格房名資料夾是 legacy 清洗名（「PsycheForge 鍛靈」→legacy「PsycheForge」），新 sanitize 算出的路徑不
  // 存在、fs.rmSync(force) 靜默刪空路徑＝真資料夾沒刪 → 解散/離開後重開 listRooms 又掃到。resolveRoomId 解析
  // 到實際存在的資料夾名（新名直接用、legacy fallback）。
  const a = resolveRoomId(name);
  if (!a) return false; // no protected default room anymore
  try {
    fs.rmSync(path.join(channelsDir(), a), { recursive: true, force: true });
    return true;
  } catch {
    return false;
  }
}

export function deleteFromMirror(room: string, seq: number): boolean {
  try {
    const clean = sanitizeRoom(room);
    if (!clean || !(seq > 0)) return false;
    const f = path.join(channelsDir(), clean, 'channel.jsonl');
    if (!fs.existsSync(f)) return false;
    const lines = readLines(clean);
    const kept = lines.filter((m) => (m.seq || 0) !== seq);
    if (kept.length === lines.length) return false; // 鏡像沒這則 → 不動
    fs.writeFileSync(f, kept.length ? kept.map((m) => JSON.stringify(m)).join('\n') + '\n' : '', 'utf8');
    return true;
  } catch { return false; }
}

export function clearMirror(room: string): void {
  try {
    const clean = sanitizeRoom(room);
    if (!clean) return;
    const f = path.join(channelsDir(), clean, 'channel.jsonl');
    if (fs.existsSync(f)) fs.writeFileSync(f, '', 'utf8');
    const sp = mirrorStatePath(clean);
    try { if (fs.existsSync(sp)) fs.unlinkSync(sp); } catch { /* */ }
  } catch { /* best-effort */ }
}

export type MemberType =
  | 'local-agent'
  | 'cloud-persona'
  | 'human'
  | 'external';

export interface Member {
  id: string;
  name: string;
  type: MemberType;
  /** owner=founder (disband + add + remove), admin=add + remove, member=none. */
  role?: MemberRole;
  /** Agent architecture: 'aiking' (AI King Agent, formerly Sancio) | 'hermes' | '' for non-agent/human. */
  architecture?: string;
  /** LLM backend slug in provider/model form, e.g. 'openai/gpt-image-1' or 'anthropic/claude-opus-4-8'. */
  backend?: string;
  /** [1.9.25] Agent 種類（agent-kinds.ts 的 AgentKind）：claude/codex/openclaw/hermes/other
   *  或內建 base/aiking/psycheforge / human。決定顯示哪個 Agent Logo + hover 識別文字。
   *  內建種類綁定不可改；外部種類可用 /profile -& 改。 */
  agentKind?: string;
  /** [1.9.25] 顯示用的模型標籤（如 'Opus 4.8'）。外部 AI 偵測不到、由 user 選/填；
   *  訊息行用人物配色顯示。可用 /profile -% 改（內建綁定者不可）。 */
  modelLabel?: string;
  /** Notify level for an AI member: 'all' | 'mention' (@ only) | 'human' (only human msgs). Default 'mention'. */
  notifyLevel?: string;
  /** Free-text profile / bio for the LINE-style profile card. Written by the member itself or an admin+. */
  bio?: string;
  /** Avatar file name under data/channels/<room>/avatars/, or '' for default. */
  avatar: string;
  joinedAt: number;
  /** Epoch ms of this member's last live SSE presence (server-stamped on connect
   *  AND disconnect). Drives the「離線超過 N 天提示清理」feature. Absent on legacy
   *  rosters → treated as unknown (never auto-flagged for cleanup). */
  lastSeenAt?: number;
  /** cloud-persona: characterName for the digital-human API. */
  persona?: string;
  /** local-agent: optional .md / handoff file that grounds a fresh agent. */
  contextFile?: string;
  /** external: localhost or URL endpoint the member connected from. */
  endpoint?: string;
}

interface MembersFile {
  members: Member[];
}

function membersPath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), 'members.json');
}

export function readMembers(room: string): Member[] {
  return readMembersResult(room).members;
}

export function readMembersResult(room: string): { members: Member[]; corrupt: boolean } {
  let raw: string;
  try {
    raw = fs.readFileSync(membersPath(room), 'utf8');
  } catch {
    return { members: [], corrupt: false }; // no file → genuinely empty room
  }
  if (!raw.trim()) return { members: [], corrupt: false }; // empty file → empty room
  try {
    const data = JSON.parse(raw) as MembersFile;
    return { members: Array.isArray(data.members) ? data.members : [], corrupt: false };
  } catch {
    return { members: [], corrupt: true }; // file exists but is garbage
  }
}

function writeMembers(room: string, members: Member[]): boolean {
  const tmp = membersPath(room) + '.tmp';
  try {
    const p = membersPath(room);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(tmp, JSON.stringify({ members }, null, 2), 'utf8');
    fs.renameSync(tmp, p);
    return true;
  } catch {
    // [M6] best-effort: drop the spool file so a failed write doesn't leave a
    // .tmp orphan behind (rename can fail if the dest is locked mid-crash).
    try { fs.unlinkSync(tmp); } catch { /* already gone */ }
    return false;
  }
}

export function addMember(room: string, member: Member, emitEvent = true): boolean {
  const members = readMembers(room);
  if (members.some((m) => m.id === member.id)) return false; // already in
  members.push(member);
  const ok = writeMembers(room, members);
  // emitEvent=false when seeding a member learned out-of-band (e.g. the owner
  // from an invite blob on join): we must NOT forge a member.add event "from us"
  // for someone else — that owner already announced themselves at create time.
  if (ok && emitEvent) emitMemberEvent(room, 'member.add', member.id, { member });
  return ok;
}

export function removeMember(room: string, id: string): boolean {
  const members = readMembers(room);
  const next = members.filter((m) => m.id !== id);
  if (next.length === members.length) return false;
  const ok = writeMembers(room, next);
  if (ok) emitMemberEvent(room, 'member.remove', id, {});
  return ok;
}

export function setMemberRole(room: string, id: string, role: MemberRole): boolean {
  const members = readMembers(room);
  const m = members.find((x) => x.id === id);
  if (!m) return false;
  m.role = role;
  const ok = writeMembers(room, members);
  if (ok) emitMemberEvent(room, 'member.role', id, { role });
  return ok;
}

export function setMemberNotify(room: string, id: string, level: string): boolean {
  const members = readMembers(room);
  const m = members.find((x) => x.id === id);
  if (!m) return false;
  m.notifyLevel = level;
  const ok = writeMembers(room, members);
  if (ok) emitMemberEvent(room, 'member.notify', id, { notifyLevel: level });
  return ok;
}

export function setMemberBio(room: string, id: string, bio: string): boolean {
  const members = readMembers(room);
  const m = members.find((x) => x.id === id);
  if (!m) return false;
  m.bio = bio;
  return writeMembers(room, members);
}

export function updateMemberAvatar(
  room: string,
  id: string,
  avatar: string,
): boolean {
  const members = readMembers(room);
  const m = members.find((x) => x.id === id);
  if (!m) return false;
  m.avatar = avatar;
  return writeMembers(room, members);
}

export function nextAgentName(room: string, prefix = '代理'): string {
  const used = new Set<string>();
  const res = readMembersResult(room);
  // If the roster file is CORRUPT we can't know which names are taken; returning
  // the default "代理A" would risk a duplicate. Use a random-suffixed name so the
  // new agent is at least collision-safe until the file is repaired.
  if (res.corrupt) {
    return prefix + crypto.randomBytes(2).toString('hex');
  }
  for (const m of res.members) {
    used.add(m.name);
    used.add(m.id);
  }
  // Scan only the most recent slice of history for past sender names (a peer's
  // 代理X is broadcast as a join line near where it joined). Bounding the scan
  // keeps this O(N) cheap on a very large room instead of walking the full log.
  const recent = readLines(room);
  const tail = recent.length > 800 ? recent.slice(-800) : recent;
  for (const msg of tail) {
    if (msg.from) used.add(msg.from);
  }
  for (let i = 0; i < 26; i++) {
    const cand = prefix + String.fromCharCode(65 + i); // 代理A … 代理Z
    if (!used.has(cand)) return cand;
  }
  let n = 27;
  while (used.has(prefix + n)) n++;
  return prefix + n;
}

export type MemberEventType =
  | 'member.add'
  | 'member.remove'
  | 'member.role'
  | 'member.notify';

export interface MemberEvent {
  t: MemberEventType;
  member_id: string;
  payload: Record<string, unknown>;
  from?: string;
  ts: number;
}

export function parseMemberEvent(text: string | undefined): MemberEvent | null {
  if (!text || !text.startsWith(MEMBER_EVENT_SENTINEL)) return null;
  try {
    const json = text.slice(MEMBER_EVENT_SENTINEL.length);
    const d = JSON.parse(json) as MemberEvent;
    if (d && typeof d.t === 'string' && typeof d.member_id === 'string') return d;
  } catch {
    /* malformed → not an event */
  }
  return null;
}

function emitMemberEvent(
  room: string,
  t: MemberEventType,
  memberId: string,
  payload: Record<string, unknown>,
): void {
  if (!isOnlineRoom(room)) return; // local room → members.json is truth
  const ev: MemberEvent = { t, member_id: memberId, payload, ts: Date.now() };
  const from =
    (readIdentity(room)?.me) || (readRelayConfig(room)?.me) || 'user';
  ev.from = from;
  const text = MEMBER_EVENT_SENTINEL + JSON.stringify(ev);
  // role:'agent' + type:'msg' so the relay forwards it (system/non-msg skipped).
  appendMessage(room, { from, text, framework: 'vscode', role: 'agent' });
}

export function replayMemberRoster(room: string, base: Member[]): Member[] {
  const byId = new Map<string, Member>();
  for (const m of base) byId.set(m.id, m);
  const events: Array<{ seq: number; ev: MemberEvent }> = [];
  for (const msg of readLines(room)) {
    const ev = parseMemberEvent(msg.text);
    if (ev) events.push({ seq: msg.seq || 0, ev });
  }
  events.sort((a, b) => a.seq - b.seq);
  for (const { ev } of events) {
    if (ev.t === 'member.add') {
      const m = ev.payload.member as Member | undefined;
      if (m && m.id && !byId.has(m.id)) byId.set(m.id, m);
    } else if (ev.t === 'member.remove') {
      byId.delete(ev.member_id);
    } else if (ev.t === 'member.role') {
      const m = byId.get(ev.member_id);
      const role = ev.payload.role as MemberRole | undefined;
      if (m && role) m.role = role;
    } else if (ev.t === 'member.notify') {
      const m = byId.get(ev.member_id);
      const level = ev.payload.notifyLevel as string | undefined;
      if (m && typeof level === 'string') m.notifyLevel = level;
    }
  }
  return [...byId.values()];
}

export interface ChannelMessage {
  seq: number;
  from: string;
  text: string;
  ts: number;
  framework?: string;
  mentions?: string[];
  type?: string;
  /** Carries room_event (e.g. 'room.dissolve') stamped by appendMessage. */
  meta?: Record<string, unknown>;
  role?: string;
}

function channelFile(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), 'channel.jsonl');
}

function readLines(room: string): ChannelMessage[] {
  try {
    const out: ChannelMessage[] = [];
    for (const ln of fs.readFileSync(channelFile(room), 'utf8').split(/\r?\n/)) {
      const t = ln.trim();
      if (!t) continue;
      try { out.push(JSON.parse(t) as ChannelMessage); } catch { /* skip bad line */ }
    }
    return out;
  } catch {
    return [];
  }
}

export function readSince(room: string, since: number): ChannelMessage[] {
  return readLines(room).filter((m) => (m.seq || 0) > since);
}

export function readMirrorTail(room: string, limit = 20): ChannelMessage[] {
  const all = readLines(room);
  return limit > 0 && all.length > limit ? all.slice(-limit) : all;
}

export function appendMessage(
  room: string,
  msg: {
    from: string;
    text: string;
    framework?: string;
    mentions?: string[];
    role?: string;
    senderKind?: string;
    /**
     * Optional event marker stamped into meta.room_event so a peer replaying the
     * channel can act on it (e.g. 'room.dissolve' → freeze the room read-only).
     */
    roomEvent?: string;
  },
): { seq: number } | null {
  const clean = sanitizeRoom(room);
  if (!clean) return null;
  const dir = path.join(channelsDir(), clean);
  const f = path.join(dir, 'channel.jsonl');
  try {
    fs.mkdirSync(dir, { recursive: true });
    const seq = readLines(clean).reduce((a, m) => Math.max(a, m.seq || 0), 0) + 1;
    const now = Date.now();
    const rec = {
      ts: now / 1000,
      channel: clean,
      from: msg.from || 'anon',
      framework: msg.framework || 'url',
      role: msg.role || 'agent',
      senderKind: msg.senderKind || '',
      type: 'msg',
      to: ['broadcast'],
      mentions: msg.mentions || [],
      reply_to: null,
      pinned: false,
      text: msg.text || '',
      meta: msg.roomEvent ? { room_event: msg.roomEvent } : {},
      id: `${now}.${crypto.randomBytes(3).toString('hex')}.url.${seq}`,
      seq,
    };
    fs.appendFileSync(f, JSON.stringify(rec) + '\n', 'utf8');
    return { seq };
  } catch {
    return null;
  }
}

function mirrorStatePath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), '.mirror-state.json');
}

function isRemoteServedRoom(room: string): boolean {
  const cfg = readRelayConfig(room);
  const relay = cfg?.relay || '';
  if (!/^(?:https?|wss?):\/\//i.test(relay)) return false; // 本機房 / 非 URL → 伺服器自己寫同一檔
  return !/(?:^|\/\/)(?:127\.0\.0\.1|localhost)(?::|\/|$)/i.test(relay);
}

export function appendMirror(room: string, msg: Record<string, unknown>): void {
  try {
    const clean = sanitizeRoom(room);
    if (!clean) return;
    const seq = typeof msg.seq === 'number' ? msg.seq : 0;
    if (!(seq > 0)) return; // 無 seq 的訊息無法去重 → 不鏡像
    if (!isRemoteServedRoom(clean)) return;
    const dir = path.join(channelsDir(), clean);
    if (!fs.existsSync(dir)) return; // 房間已刪 → 不復活
    // 每次重讀 state 檔（不用程序內快取）：兩個 VS Code 視窗同時鏡像同一房時，
    // 後到者讀到前者剛寫的 lastSeq 即跳過，重複行縮到毫秒級競態的極罕見情況。
    const sp = mirrorStatePath(clean);
    let lastSeq = -1;
    try {
      const d = JSON.parse(fs.readFileSync(sp, 'utf8')) as { lastSeq?: number };
      if (typeof d.lastSeq === 'number') lastSeq = d.lastSeq;
    } catch { lastSeq = -1; }
    if (lastSeq < 0) {
      // 首次鏡像：以既有 channel.jsonl 的最大 seq 起算（搬遷過的房本機已有舊歷史，
      // 從 0 起算會把伺服器重發的同段歷史再 append 一份）。
      lastSeq = readLines(clean).reduce((a, m) => Math.max(a, m.seq || 0), 0);
    }
    if (seq <= lastSeq) return;
    fs.appendFileSync(path.join(dir, 'channel.jsonl'), JSON.stringify(msg) + '\n', 'utf8');
    // state-file 更新是 best-effort：訊息已落 channel.jsonl，state 寫失敗也不影響，
    // 下次以既有 channel.jsonl 最大 seq 自我修復去重。詳見 persistMirrorSeq。
    persistMirrorSeq(sp, seq);
  } catch (e) {
    bridgeLog(
      `鏡像寫入失敗 room="${room}" seq=${String((msg && msg.seq) ?? '?')}: ` +
      (e instanceof Error ? e.message : String(e)),
    );
  }
}

function persistMirrorSeq(sp: string, seq: number): void {
  const payload = JSON.stringify({ lastSeq: seq });
  const tmp = sp + '.' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8) + '.tmp';
  try {
    fs.writeFileSync(tmp, payload, 'utf8');
    fs.renameSync(tmp, sp);
    return;
  } catch {
    try { fs.unlinkSync(tmp); } catch { /* already gone */ }
  }
  // fallback：直接覆寫（非原子，但 {lastSeq} 極小；torn write 下次當無效 state 重算）。
  try { fs.writeFileSync(sp, payload, 'utf8'); } catch { /* 靜默降級：state 自我修復 */ }
}

export interface RoomState {
  status: RoomStatus;
  /** Display name of whoever changed the state (owner on dissolve). */
  by?: string;
  ts?: number;
  /** [統一母版 2026-06-16] 群組顯示名（owner 可改、本機亦存一份）。所有顯示點（側邊欄列表/
   *  分頁標題/topbar）統一走 roomLabel() 取此值，改名才會處處同步。⛔不動 room key＝E2E 鑰匙
   *  sha256(room:token) 不變＝改名不影響連線（user 守則：伺服器綁 id 不綁名稱）。 */
  displayName?: string;
}

function roomStatePath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), '.room-state.json');
}

export function readRoomState(room: string): RoomState {
  try {
    const d = JSON.parse(fs.readFileSync(roomStatePath(room), 'utf8')) as RoomState;
    if (d && (d.status === 'active' || d.status === 'frozen' || d.status === 'dissolved')) {
      return d;
    }
  } catch {
    /* no state file ⇒ active */
  }
  return { status: 'active' };
}

export function setRoomState(room: string, state: RoomState): boolean {
  const clean = sanitizeRoom(room);
  if (!clean) return false;
  const tmp = roomStatePath(clean) + '.tmp';
  try {
    const dir = path.join(channelsDir(), clean);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(tmp, JSON.stringify(state, null, 2), 'utf8');
    fs.renameSync(tmp, roomStatePath(clean));
    return true;
  } catch {
    // [M6] drop the spool file on failure (see writeMembers).
    try { fs.unlinkSync(tmp); } catch { /* already gone */ }
    return false;
  }
}

export function isRoomFrozen(room: string): boolean {
  const s = readRoomState(room).status;
  return s === 'frozen' || s === 'dissolved';
}

export function roomLabel(room: string): string {
  const clean = sanitizeRoom(room);
  if (!clean) return room;
  const dn = readRoomState(clean).displayName;
  return (dn && dn.trim()) ? dn.trim() : clean;
}

export function setRoomDisplayName(room: string, displayName: string): boolean {
  const clean = sanitizeRoom(room);
  if (!clean) return false;
  const cur = readRoomState(clean);
  return setRoomState(clean, { ...cur, displayName: displayName.trim() || undefined });
}

export interface RelayStatus {
  state: RelayState;
  ts: number;
}

function relayStatusPath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), '.relay-status.json');
}

export function readRelayStatus(room: string, staleMs = 60_000): RelayStatus {
  try {
    const d = JSON.parse(fs.readFileSync(relayStatusPath(room), 'utf8')) as RelayStatus;
    if (d && typeof d.state === 'string' && typeof d.ts === 'number') {
      if (Date.now() - d.ts > staleMs) return { state: 'unavailable', ts: d.ts };
      return d;
    }
  } catch {
    /* no status file yet */
  }
  return { state: 'unavailable', ts: 0 };
}

export function getRoomToken(room: string): string {
  const clean = sanitizeRoom(room);
  if (!clean) return '';
  const dir = path.join(channelsDir(), clean);
  const tf = path.join(dir, '.token');
  try {
    if (fs.existsSync(tf)) {
      const t = fs.readFileSync(tf, 'utf8').trim();
      if (t) return t;
    }
    fs.mkdirSync(dir, { recursive: true });
    const tok = crypto.randomBytes(12).toString('base64url');
    fs.writeFileSync(tf, tok, 'utf8');
    return tok;
  } catch {
    return '';
  }
}

export function writeRoomToken(room: string, token: string): boolean {
  const clean = sanitizeRoom(room);
  if (!clean || !token) return false;
  try {
    const dir = path.join(channelsDir(), clean);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, '.token'), token, 'utf8');
    return true;
  } catch {
    return false;
  }
}

export function readRoomBundle(room: string): {
  token: string;
  members: Member[];
  messages: Record<string, unknown>[];
  maxSeq: number;
} | null {
  const clean = sanitizeRoom(room);
  if (!clean) return null;
  const dir = path.join(channelsDir(), clean);
  const token = getRoomToken(room); // mints one if absent (never migrate keyless)
  const members = readMembers(room);
  let messages: Record<string, unknown>[] = [];
  try {
    const raw = fs.readFileSync(path.join(dir, 'channel.jsonl'), 'utf8');
    messages = raw
      .split(/\r?\n/)
      .filter((l) => l.trim())
      .map((l) => {
        try { return JSON.parse(l) as Record<string, unknown>; } catch { return null; }
      })
      .filter((x): x is Record<string, unknown> => x !== null);
  } catch {
    messages = [];
  }
  const maxSeq = messages.reduce((a, m) => {
    const s = typeof m.seq === 'number' ? (m.seq as number) : 0;
    return s > a ? s : a;
  }, 0);
  return { token, members, messages, maxSeq };
}

export interface RelayConfig {
  relay: string;
  token: string;
  me: string;
  /** My permission tier in THIS online room: founder→owner, joiner→member. */
  role?: MemberRole;
  /** Schema version for forward-compatible migrations. Absent ⇒ treat as 1. */
  version?: number;
}

function relayConfigPath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), '.relay.json');
}

export function writeRelayConfig(room: string, cfg: RelayConfig): boolean {
  const clean = sanitizeRoom(room);
  if (!clean) return false;
  try {
    const dir = path.join(channelsDir(), clean);
    fs.mkdirSync(dir, { recursive: true });
    const withVersion = { version: RELAY_CONFIG_VERSION, ...cfg };
    fs.writeFileSync(relayConfigPath(clean), JSON.stringify(withVersion, null, 2), 'utf8');
    return true;
  } catch {
    return false;
  }
}

export function readRelayConfig(room: string): RelayConfig | null {
  try {
    const d = JSON.parse(fs.readFileSync(relayConfigPath(room), 'utf8')) as RelayConfig;
    return d && d.relay && d.token ? d : null;
  } catch {
    return null;
  }
}

export function isOnlineRoom(room: string): boolean {
  return readRelayConfig(room) !== null;
}

export interface Identity {
  me: string;
  role?: MemberRole;
  /**
   * Per-room GROUP notify level (decides whether *I*, the user/window, get a
   * desktop notification for new messages in this room). Distinct from a
   * Member.notifyLevel (which decides which messages wake an AI member).
   * 'all' = notify on any new message · 'mention' = only when @-mentioned ·
   * 'off' = never. Unset → fall back to the global aiKing.groupNotifyLevel.
   */
  notifyLevel?: 'all' | 'mention' | 'off';
}

function identityPath(room: string): string {
  return path.join(channelsDir(), sanitizeRoom(room), 'identity.json');
}

export function writeIdentity(room: string, id: Identity): boolean {
  const clean = sanitizeRoom(room);
  if (!clean) return false;
  try {
    fs.mkdirSync(path.join(channelsDir(), clean), { recursive: true });
    fs.writeFileSync(identityPath(clean), JSON.stringify(id, null, 2), 'utf8');
    return true;
  } catch {
    return false;
  }
}

export function readIdentity(room: string): Identity | null {
  try {
    const d = JSON.parse(fs.readFileSync(identityPath(room), 'utf8')) as Identity;
    return d && typeof d.me === 'string' ? d : null;
  } catch {
    return null;
  }
}

export function setGroupNotifyLevel(
  room: string,
  level: 'all' | 'mention' | 'off',
): boolean {
  const clean = sanitizeRoom(room);
  if (!clean) return false;
  const cur = readIdentity(clean) || { me: 'user' };
  return writeIdentity(clean, { ...cur, notifyLevel: level });
}

export function listOnlineRooms(): string[] {
  return listRooms().filter((r) => isOnlineRoom(r));
}

export interface InviteFounder {
  id: string;
  role: string;
}

export function encodeInvite(
  room: string,
  token: string,
  relay: string,
  founder?: InviteFounder,
  authorityUrl?: string,
): string {
  // `authorityUrl` is the new single-source-of-truth server address the joiner
  // should connect to. `relay` is kept for backward compatibility with the
  // legacy relay-mirror path; new invites carry both.
  const json = JSON.stringify({ room: sanitizeRoom(room), token, relay, founder, authorityUrl });
  return INVITE_PREFIX + Buffer.from(json, 'utf8').toString('base64url');
}

export function decodeInvite(
  blob: string,
): { room: string; token: string; relay: string; founder?: InviteFounder; authorityUrl?: string } | null {
  try {
    // Tolerant: pull the AIBRIDGE1 token out of any surrounding text the user
    // may have pasted (a whole instruction message, stray whitespace, etc.).
    const m = (blob || '').match(/AIBRIDGE1:([A-Za-z0-9_-]+)/);
    const s = m ? m[1] : (blob || '').trim();
    const json = Buffer.from(s, 'base64url').toString('utf8');
    const d = JSON.parse(json) as {
      room?: string; token?: string; relay?: string; founder?: InviteFounder; authorityUrl?: string;
    };
    // New authority invites need room + token + authorityUrl. Legacy relay
    // invites need room + token + relay. Accept either so old codes still join.
    if (!d.room || !d.token || (!d.relay && !d.authorityUrl)) return null;
    return {
      room: sanitizeRoom(d.room),
      token: d.token,
      relay: d.relay || '',
      founder: d.founder,
      authorityUrl: d.authorityUrl,
    };
  } catch {
    return null;
  }
}

interface RestartState {
  attempts: number;
  timer?: NodeJS.Timeout;
  /** True once we have deliberately stopped — suppresses auto-restart. */
  stopped: boolean;
}

function relayPollMs(): number {
  const v = vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('relayPollMs', DEFAULT_RELAY_POLL_MS);
  return typeof v === 'number' && v > 0 ? v : DEFAULT_RELAY_POLL_MS;
}

export function initRelay(ctx: vscode.ExtensionContext): void {
  joinScript = vscode.Uri.joinPath(
    ctx.extensionUri,
    'media',
    'bridge-join.mjs',
  ).fsPath;
}

export function isBridged(room: string): boolean {
  return procs.has(room);
}

function spawnBridge(room: string): boolean {
  const cfg = readRelayConfig(room);
  if (!cfg || !joinScript) return false;
  // ROOM_KEY = sha256(room:token) is the relay "constitution". An empty token
  // hashes to a WRONG ROOM_KEY → both sides silently fail to find each other.
  // Refuse to start rather than join a dead room.
  if (!cfg.token || !cfg.token.trim()) {
    // eslint-disable-next-line no-console
    console.warn(
      `[ai-king] relay bridge NOT started for room="${room}": empty token ` +
        `(would compute a wrong ROOM_KEY and silently desync). Re-create / re-join the room.`,
    );
    return false;
  }
  const home = resolveBridgeHome();
  const args = [
    joinScript,
    '--room', room,
    '--me', cfg.me || 'vscode',
    '--token', cfg.token,
    '--relay', cfg.relay,
    '--bridge-home', home,
    '--poll', String(relayPollMs()),
  ];
  try {
    const { cmd, extraEnv } = resolveNode();
    let stdio: cp.StdioOptions = 'ignore';
    try {
      const logPath = path.join(home, 'data', 'channels', room, 'relay.log');
      fs.mkdirSync(path.dirname(logPath), { recursive: true });
      const out = fs.openSync(logPath, 'a');
      stdio = ['ignore', out, out];
    } catch {
      /* fall back to ignoring output */
    }
    const proc = cp.spawn(cmd, args, {
      env: { ...process.env, ...extraEnv },
      stdio,
      windowsHide: true,
    });
    proc.on('error', () => {
      procs.delete(room);
      scheduleRestart(room);
    });
    proc.on('exit', () => {
      procs.delete(room);
      scheduleRestart(room);
    });
    procs.set(room, proc);
    // eslint-disable-next-line no-console
    console.log(`[ai-king] relay bridge up: room="${room}" via ${cmd} -> ${cfg.relay} (poll=${relayPollMs()}ms)`);
    return true;
  } catch {
    /* best-effort; the room simply won't sync until restart */
    return false;
  }
}

function scheduleRestart(room: string): void {
  const st = restartState.get(room);
  if (!st || st.stopped) return; // deliberate stop → do not resurrect
  if ((refcount.get(room) || 0) <= 0) return; // nobody is watching anymore
  if (st.timer) return; // a restart is already pending
  if (st.attempts >= MAX_RESTART_ATTEMPTS) {
    // eslint-disable-next-line no-console
    console.warn(`[ai-king] relay bridge for room="${room}" failed ${st.attempts} times; giving up.`);
    void vscode.window.showWarningMessage(
      `AI 群組「${room}」：中繼橋接連續重啟失敗，已暫停跨機同步。請檢查網路或重開此群組。`,
    );
    return;
  }
  st.attempts += 1;
  const delay = Math.min(30_000, 1000 * 2 ** (st.attempts - 1)); // 1s,2s,4s…cap 30s
  // eslint-disable-next-line no-console
  console.log(`[ai-king] relay bridge for room="${room}" exited; restart #${st.attempts} in ${delay}ms`);
  st.timer = setTimeout(() => {
    st.timer = undefined;
    if (st.stopped || (refcount.get(room) || 0) <= 0) return;
    spawnBridge(room);
  }, delay);
}

export function ensureRelayBridge(room: string, countUse = true): void {
  if (countUse) refcount.set(room, (refcount.get(room) || 0) + 1);
  // Reset/refresh restart bookkeeping: a fresh ensure means we want it alive.
  const st = restartState.get(room) || { attempts: 0, stopped: false };
  st.stopped = false;
  st.attempts = 0;
  restartState.set(room, st);
  if (procs.has(room)) return; // already running — refcount bumped above
  spawnBridge(room);
}

export function stopRelayBridge(room: string): void {
  const next = (refcount.get(room) || 0) - 1;
  if (next > 0) {
    refcount.set(room, next);
    return; // another panel still needs this bridge
  }
  refcount.delete(room);
  const st = restartState.get(room);
  if (st) {
    st.stopped = true;
    if (st.timer) { clearTimeout(st.timer); st.timer = undefined; }
  }
  const p = procs.get(room);
  if (p) {
    try {
      p.kill();
    } catch {
      /* already gone */
    }
    procs.delete(room);
  }
}

export function forceStopRelayBridge(room: string): void {
  refcount.delete(room);
  const st = restartState.get(room);
  if (st) {
    st.stopped = true;
    if (st.timer) { clearTimeout(st.timer); st.timer = undefined; }
  }
  restartState.delete(room);
  const p = procs.get(room);
  if (p) {
    try { p.kill(); } catch { /* already gone */ }
    procs.delete(room);
  }
}

export function ensureAllRelayBridges(): void {
  for (const r of listOnlineRooms()) ensureRelayBridge(r);
}

export function stopAllRelayBridges(): void {
  for (const r of [...procs.keys()]) forceStopRelayBridge(r);
}

export function bridgeServerPort(): number {
  return activePort;
}

export function bridgeJoinUrl(room: string): { base: string; token: string; port: number } {
  const token = getRoomToken(room);
  const port = activePort || PREFERRED_PORT;
  return { base: `http://127.0.0.1:${port}/r/${encodeURIComponent(sanitizeRoom(room))}`, token, port };
}

function send(res: http.ServerResponse, status: number, body: unknown): void {
  const s = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(s) });
  res.end(s);
}

function expandMentions(room: string, text: string): string[] {
  const out: string[] = [];
  const re = /(?:^|\s)@([\w-]+)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text)) !== null) out.push(m[1]);
  if (out.includes('all') || out.includes('everyone') || text.indexOf('@全部') >= 0) {
    for (const mm of readMembers(room)) if (!out.includes(mm.id)) out.push(mm.id);
  }
  return out;
}

function handle(req: http.IncomingMessage, res: http.ServerResponse): void {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, X-Bridge-Token');
  if (req.method === 'OPTIONS') { res.writeHead(204); res.end(); return; }

  let url: URL;
  try { url = new URL(req.url || '/', 'http://127.0.0.1'); } catch { send(res, 400, { error: 'bad url' }); return; }
  const parts = url.pathname.split('/').filter(Boolean);

  if (parts[0] === 'r' && parts[1]) {
    const room = sanitizeRoom(decodeURIComponent(parts[1]));
    const token = url.searchParams.get('token') || (req.headers['x-bridge-token'] as string) || '';
    if (!room || getRoomToken(room) !== token) { send(res, 403, { error: 'bad or missing token' }); return; }

    if (req.method === 'GET') {
      const since = parseInt(url.searchParams.get('since') || '0', 10) || 0;
      const messages = readSince(room, since)
        .filter((m) => !m.type || m.type === 'msg')
        .map((m) => ({ seq: m.seq, from: m.from, text: m.text, ts: m.ts }));
      send(res, 200, { room, messages });
      return;
    }
    if (req.method === 'POST') {
      let body = '';
      req.on('data', (c) => { body += c; if (body.length > MAX_BODY) req.destroy(); });
      req.on('end', () => {
        try {
          const d = JSON.parse(body || '{}');
          if (!d.from || !d.text) { send(res, 400, { error: 'need from + text' }); return; }
          const from = String(d.from).slice(0, 40);
          const text = String(d.text).slice(0, 4000);
          const r = appendMessage(room, { from, text, framework: 'url', mentions: expandMentions(room, text) });
          send(res, r ? 200 : 500, r ? { ok: true, seq: r.seq } : { error: 'append failed' });
        } catch { send(res, 400, { error: 'bad json' }); }
      });
      return;
    }
    send(res, 405, { error: 'method not allowed' });
    return;
  }

  if (url.pathname === '/' || url.pathname === '/health') {
    send(res, 200, { ok: true, service: 'ai-king-bridge', port: activePort });
    return;
  }
  send(res, 404, { error: 'not found' });
}

export function ensureBridgeServer(): void {
  if (server) return;
  const tryPort = (port: number, left: number): void => {
    const s = http.createServer(handle);
    s.on('error', () => {
      s.close();
      if (left > 0) tryPort(port + 1, left - 1);
    });
    s.listen(port, '127.0.0.1', () => {
      server = s;
      activePort = port;
      // eslint-disable-next-line no-console
      console.log(`[ai-king] bridge server on http://127.0.0.1:${port}`);
    });
  };
  tryPort(PREFERRED_PORT, 25);
}

export function stopBridgeServer(): void {
  try { server?.close(); } catch { /* */ }
  server = undefined;
  activePort = 0;
}

