function isReactionText(text: string | undefined): boolean {
  return typeof text === 'string' && text.startsWith(REACTION_PREFIX);
}

function isLabelText(text: string | undefined): boolean {
  return typeof text === 'string' && text.startsWith(LABEL_PREFIX);
}

function isSysText(text: string | undefined): boolean {
  return typeof text === 'string' && text.startsWith(SYS_PREFIX);
}

function isReadText(text: string | undefined): boolean {
  return typeof text === 'string' && text.startsWith(READ_PREFIX);
}

function textHasRoleMention(text: string, target: RoleMentionTarget): boolean {
  if (typeof text !== 'string' || text.indexOf('@') < 0) return false;
  const zh = target === 'owner' ? '群主' : '管理員';
  const en = target; // 'owner' | 'admin'
  // 中文：前面是開頭/空白/非中文字界，後面不可再接 CJK/字母/數字/連字號。
  const zhRe = new RegExp('(^|\\s)@' + zh + '(?![\\u4e00-\\u9fff\\w-])');
  // 英文別名（大小寫不敏感）：比照 @名字 的 `[\w-]` 邊界，避免 `@admins` / `@owners` 誤命中。
  const enRe = new RegExp('(^|\\s)@' + en + '(?=$|\\s|[^\\w-])', 'i');
  return zhRe.test(text) || enRe.test(text);
}

function getNonce(): string {
  const chars =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let out = '';
  for (let i = 0; i < 32; i++) {
    out += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return out;
}

function glog(msg: string): void {
  bridgeLog(msg);
}

export function sessionStoreFor(ctx: vscode.ExtensionContext): SessionStore {
  return sharedSessionStore ?? new SessionStore(ctx);
}

export class BridgePanel {
  public static readonly viewType = 'aiKing.bridgePanel';
  // 0.40.0: one panel PER ROOM (like a normal chat session opens its own
  // window) — keyed by channel, no in-panel room switching.
  private static panels = new Map<string, BridgePanel>();

  private readonly panel: vscode.WebviewPanel;
  private visible = true;

  private home = '';
  private channel = 'main';
  // channel.jsonl path — NOT tailed in authority mode (server is the source of
  // truth). Kept only for: ensureChannel() bootstrap, meta() display, and the
  // 1:1 agent-chat history seed (buildGroupMemorySeed → readSince local read).
  private channelPath = '';

  private lastRelayState = ''; // last state posted to webview (dedup)
  private buffer: ViewMessage[] = []; // in-memory tail (capped)
  private unread = 0;

  // -- authority (single source of truth) -----------------------------------
  // The client is a DISPLAY ONLY surface: it holds ONE live SSE connection to
  // the authority server and renders whatever it pushes (state/presence/member/
  // msg/room.dissolve). It NEVER computes presence/roster/history locally.
  private authority?: AuthorityClient;
  // Server-authoritative caches (raw, as pushed by the server). The webview is
  // fed straight from these — no local re-computation.
  private authMembers: Member[] = []; // server roster (state/member events)
  private authOnline: Array<{ id: string; name: string }> = []; // live SSE set
  private authStatus = 'active'; // active | dissolved
  // [10.2] 伺服器是否給了 per-member online/lastSeen（新伺服器才有）。false（舊伺服器）
  // → 名字旁圓點完全不顯示（不是全灰），避免誤導。每次重連重新偵測。
  private serverPresenceV2 = false;
  private roomDisplayName = ''; // 群組顯示名（owner 可改；不動 room key 保 E2E）。空 = 用 room key
  private oldestSeq = 0; // smallest seq currently held (history cursor)
  private maxSeenSeq = 0; // [1.9.17] 已處理過的最大 seq（appendFromServer 去重，防重播雙回覆）
  private hasMoreHistory = false; // server says older pages exist
  private connectTimer?: NodeJS.Timeout; // escalate 'connecting' → 'unavailable'
  private firstStateSeen = false; // a server state frame has arrived this connect
  private joinedMember?: Member; // who we registered (for SSE-reconnect re-join)
  private selfRejoinInflight = false; // a re-join POST is awaiting confirmation
  private readonly connectTimeoutMs = 8000; // no state frame by then → unavailable
  private warnedDecryptMismatch = false; // one-shot E2E key-mismatch banner
  // -- initial history load (reload-robust) ---------------------------------
  // A reload MUST always re-pull the full newest page. The old fire-and-forget
  // loadInitialHistory swallowed errors → the panel could freeze on a stale or
  // empty buffer ("我發的訊息重載後消失"). These fields drive a retry-until-loaded
  // loop with a visible banner once the retry budget is spent, so the panel is
  // never silently stuck on a half-loaded history.
  private historyLoaded = false; // newest page successfully seeded this connect
  private historyRetryTimer?: NodeJS.Timeout; // pending backoff retry
  private historyRetries = 0; // attempts spent on the current connect
  private readonly maxHistoryRetries = 6; // ~20s of backoff before we surface it
  private staleHinted = false; // one-shot「離線過久成員」hint shown this panel
  private langCfgListener?: vscode.Disposable; // [1.8.0 §13] aiKing.language re-push

  // -- group message notifications (desktop toast on new messages) ----------
  // Throttle so a burst of messages coalesces into one "N 則新訊息" toast
  // instead of spamming one per line (per VS Code UX: combine notifications).
  // [通知 P1-b 2026-06-21] 節流狀態移到 globalState（per-room key `aiKing.notify.groupThrottle.<room>`）
  // ＝跨「重開面板」與「多視窗」持久共享、不再每個 instance 各自歸零（解 user 最討厭的「重開／多視窗
  // 又重複通知」：兩個視窗讀同一把 lastNotifyAt 互相節流、少一份重複）。讀同步 get、寫 fire-and-forget。

  // Persona-member routing (cloud digital persona as a room member).
  private personaInflight = new Set<string>(); // member ids mid-call
  // [身份同步 2026-06-16] 節流：pushMembers 很頻繁（每次 presence tick），不在每次都掃所有
  // linked session。lastIdentitySync 記上次掃描時刻（ms），4 秒內不重掃；inflight 防重入。
  private lastIdentitySync = 0;
  private identitySyncInflight = false;
  // Per-member reply timestamps (epoch ms) for the rate guard. Keyed by member
  // id so 5 personas hit by one message don't share (and blow) a single global
  // 12/min budget — each member gets its own independent cap (cost-bomb guard).
  private personaReplyTimes = new Map<string, number[]>();

  // -- factory --------------------------------------------------------------

  private readonly extensionUri: vscode.Uri;

  static createOrShow(
    ctx: vscode.ExtensionContext,
    channel?: string,
  ): BridgePanel {
    // [1.8.0 §10.3-3] 由房名解析房間：新規則 id 沒有本機資料夾時 fallback 試 legacy
    // id（1.6.4 舊清洗規則），命中 → 沿用 legacy id（含中文/空格的舊房名照樣開得回
    // 原資料夾 / 原伺服器房 / 原 E2E 鑰匙）。對已存在的資料夾名是冪等的。
    const ch = resolveRoomId((channel || 'main').trim() || 'main') || 'main';
    const existing = BridgePanel.panels.get(ch);
    // [user 2026-06-20 觀測] 記原始 channel→解析後 ch→是否命中既有→當前 panels keys，
    // 方便撈「AI King 群組」output channel 確認重複開窗真因（同 key 重用 vs key 沒命中又開新）。
    bridgeLog(
      `bridge:open room="${channel ?? ''}"→ch="${ch}" hit=${!!existing} ` +
        `panels=[${[...BridgePanel.panels.keys()].join(', ')}]`,
    );
    if (existing) {
      // [user 2026-06-20] 已開著就回到它、絕不再開重複分頁；reveal 帶到前景 + 叫它關掉
      // 群組設定抽屜回訊息（reveal 只切分頁、不關面板內 overlay，故另發 focusMessages）。
      existing.panel.reveal(undefined, false);
      existing.focusMessages();
      return existing;
    }
    const column = vscode.window.activeTextEditor
      ? vscode.window.activeTextEditor.viewColumn
      : vscode.ViewColumn.One;
    const panel = vscode.window.createWebviewPanel(
      BridgePanel.viewType,
      '群組 — ' + roomLabel(ch),
      column || vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
        localResourceRoots: [vscode.Uri.joinPath(ctx.extensionUri, 'media')],
      },
    );
    const inst = new BridgePanel(ctx, panel, ch);
    BridgePanel.panels.set(ch, inst);
    return inst;
  }

  /** [1.13.x] 重載恢復：用 VS Code 還回來的既有 panel 重建群組面板（跨擴充更新/reload
   * 保留群組視窗、不必使用者重開）。channel 走同一套 resolveRoomId 還原舊房 id。 */
  static revive(
    ctx: vscode.ExtensionContext,
    channel: string,
    panel: vscode.WebviewPanel,
  ): BridgePanel {
    const ch = resolveRoomId((channel || 'main').trim() || 'main') || 'main';
    const dup = BridgePanel.panels.get(ch);
    bridgeLog(
      `bridge:revive room="${channel}"→ch="${ch}" dup=${!!dup} ` +
        `panels=[${[...BridgePanel.panels.keys()].join(', ')}]`,
    );
    if (dup) {
      // [user 2026-06-20] reload 還原去重：同一房（同 ch key）已有面板——VS Code 對先前
      // 重複的分頁各還原一次、或 createOrShow 時序競爭已先建好——把這個多餘的還原 panel
      // 關掉、回既有，不留重複/殭屍分頁。只用可靠的同 key 比對（不碰 resolveRoomId/E2E）。
      try { panel.dispose(); } catch { /* already gone */ }
      return dup;
    }
    const inst = new BridgePanel(ctx, panel, ch);
    BridgePanel.panels.set(ch, inst);
    return inst;
  }

  /**
   * [user 2026-06-20] 叫 webview「回到訊息列表」：關掉群組設定抽屜（drawer）+ 個資卡
   * overlay。點通知/重進群組（createOrShow 重用既有面板）時呼叫——`panel.reveal()` 只把
   * 分頁帶到前景、不會關面板內的 overlay，故另發這個訊息。webview 沒就緒時 postMessage
   * 無害（沒收到就略過）。
   */
  focusMessages(): void {
    try {
      void this.panel.webview.postMessage({ type: 'focusMessages' });
    } catch {
      /* panel 已 dispose */
    }
  }

  /** Close the open panel for a channel (e.g. before renaming/deleting it). */
  static closeForChannel(channel: string): void {
    const p = BridgePanel.panels.get(channel);
    if (p) p.dispose();
  }

  /**
   * [1.13.x 群組連動] chat-panel 在對話視窗改了某 AI 的 Agent/LLM（已回寫進 session）後
   * 主動觸發：把新身份立即同步進群組名冊，不必等 pushMembers 的 4 秒節流（也涵蓋使用者根本
   * 沒在群組面板互動的情況）。遍歷所有開著的群組面板，解除節流後各跑一次身份同步
   * （best-effort：沒連 authority / 非 owner 收 403 都自動靜默略過）。sessionId 目前僅供
   * 未來精準化用 —— syncBuiltinIdentitiesFromSessions 會自行用 linkedSessionId 掃出對應成員。
   */
  static async syncIdentityForSession(_sessionId?: string): Promise<void> {
    for (const p of BridgePanel.panels.values()) {
      p.lastIdentitySync = 0; // 解除 4s 節流，讓這次改動立即連動
      try { await p.syncBuiltinIdentitiesFromSessions(); } catch { /* best-effort */ }
    }
  }

  /**
   * The panel the user is currently looking at (active first, else any visible,
   * else any open). Used so a palette command like 通知層級 targets the room in
   * front of the user without needing a channel argument.
   */
  static activePanel(): BridgePanel | undefined {
    let visible: BridgePanel | undefined;
    for (const p of BridgePanel.panels.values()) {
      if (p.panel.active) return p;
      if (!visible && p.panel.visible) visible = p;
    }
    if (visible) return visible;
    const it = BridgePanel.panels.values().next();
    return it.done ? undefined : it.value;
  }

  /** Open the notify-level QuickPick for a channel (or the active room). */
  static async pickNotifyLevelFor(channel?: string): Promise<void> {
    const target = channel && channel.trim()
      ? BridgePanel.panels.get(channel.trim())
      : BridgePanel.activePanel();
    if (!target) {
      void vscode.window.showInformationMessage(
        'AI 群組：先開一個群組，再設定它的通知層級。',
      );
      return;
    }
    await target.pickNotifyLevel();
  }

  /**
   * "加入 AI 群組" — the B-side of cross-machine join (AUTHORITY MODE). Paste the
   * invite block, point this machine's authorityUrl at the inviter's server,
   * adopt the inviter's exact room token (so the authority gate + E2E ROOM_KEY
   * match), open the panel, and let it connect to the server + register me. The
   * server is the single source of truth — no relay mirror, no local roster math.
   */
  static async joinFromInvite(ctx: vscode.ExtensionContext): Promise<void> {
    const blob = await showInputBoxEsc({
      prompt: '貼上線上群組邀請碼（AIBRIDGE1:…，按 ESC 取消）',
      placeHolder: 'AIBRIDGE1:eyJyb29tIjoi…',
      ignoreFocusOut: true,
      validateInput: (v) => (v && v.trim() ? null : '請貼上邀請碼'),
    });
    if (!blob || !blob.trim()) return;
    const inv = decodeInvite(blob.trim());
    if (!inv) {
      void vscode.window.showErrorMessage(
        'AI King：邀請碼無法解析（格式不符）。請確認從對方的「邀請 → 線上」整段複製。',
      );
      return;
    }
    // [1.8.0 §10.3-3] 舊房名相容：邀請碼帶的是「原始房名」算出的新規則 id 時，若本機
    // 只有 legacy id 的資料夾（1.6.4 舊清洗規則），沿用 legacy id —— 這樣本機備份、
    // 伺服器房名與 E2E 鑰匙（sha256(room:token)）三者跟舊資料對齊。
    const room = resolveRoomId(inv.room) || inv.room;
    glog(`join-invite:decoded room="${inv.room}"→"${room}" authority=${inv.authorityUrl || '(legacy/none)'} tokenLen=${(inv.token || '').length}`);
    const me = await showInputBoxEsc({
      prompt: `你在群組「${room}」要顯示的名字（讓對方認得你；別跟對方同名，按 ESC 取消）`,
      value: '人類代理A',
      ignoreFocusOut: true,
      validateInput: (v) => (v && v.trim() ? null : '請輸入名稱'),
    });
    if (!me || !me.trim()) return;
    // ROOM_KEY = sha256(room:token); an empty token would silently desync. Bail
    // before we write any half state.
    if (!inv.token || !inv.token.trim()) {
      void vscode.window.showErrorMessage(
        'AI King：邀請碼缺少房間鑰匙（token），無法加入。請向對方重新索取完整邀請碼。',
      );
      return;
    }
    // The invite must name the authority server to connect to (new codes carry
    // it; a legacy relay-only code has none → we can't authority-join it).
    const authority = (inv.authorityUrl || '').trim();
    if (!authority) {
      void vscode.window.showErrorMessage(
        'AI King：這個邀請碼是舊版（只含中繼站、沒有 authority 伺服器位址），無法用新的權威伺服器模式加入。請向對方重新產生一份新版連線碼。',
      );
      return;
    }
    try {
      if (!createRoom(room)) throw new Error('建立本機房間失敗');
      if (!writeIdentity(room, { me: me.trim(), role: 'member' })) {
        throw new Error('寫入身分失敗');
      }
      // Adopt the inviter's EXACT token (authority gate + E2E key derivation).
      if (!writeRoomToken(room, inv.token)) throw new Error('寫入房間鑰匙失敗');
      // Keep .relay.json for back-compat so isOnlineRoom()=true (🌐 title); the
      // relay bridge is NOT started in authority mode.
      if (
        !writeRelayConfig(room, {
          relay: authority,
          token: inv.token,
          me: me.trim(),
          role: 'member',
        })
      ) {
        throw new Error('寫入連線設定失敗');
      }
      glog(`join-invite:fs-written room="${room}" me="${me.trim()}" authority=${authority}`);
      // Per-room (#24 fix): this room is now pinned to the inviter's server via its
      // .relay.json (relay = authority). We deliberately do NOT change the GLOBAL
      // authorityUrl — that would yank every OTHER room on this machine onto the
      // inviter's server. connectAuthority() reads the per-room relay first, so this
      // room reaches the inviter regardless of what the global setting is.
    } catch (e: unknown) {
      glog(`join-invite:fs-fail room="${room}" err=${e instanceof Error ? e.message : String(e)}`);
      if (!isOnlineRoom(room)) {
        try { deleteRoom(room); } catch { /* best-effort */ }
      }
      void vscode.window.showErrorMessage(
        `AI King：加入線上群組「${room}」失敗 — ${e instanceof Error ? e.message : String(e)}。已清理半套狀態，請重試。`,
      );
      return;
    }
    // Open the panel — its constructor connects to the authority SSE stream. Then
    // register myself on the server (broadcasts a member event so the owner sees
    // me). The server is authoritative for the rest of the roster + history.
    // [1.8.0 §10.3-2] 面板若已開著（bad-token 後按「重新索取邀請碼」走到這裡），它握
    // 的還是「舊鑰匙」的死連線 —— token / 伺服器位址剛換過，必須丟掉舊連線重連。
    const existed = BridgePanel.panels.has(room);
    const inst = BridgePanel.createOrShow(ctx, room);
    if (existed) inst.reconnectAuthority();
    void inst.joinSelf({
      id: me.trim(), name: me.trim(), type: 'human',
      role: 'member', avatar: '', joinedAt: Date.now(),
    });
    // Put the joined room on the Home list right away (same fix as create-group) —
    // otherwise a freshly joined room doesn't show until a visibility toggle.
    void vscode.commands.executeCommand('aiKing.home.refresh');
    void vscode.window.showInformationMessage(
      `已加入線上群組「${room}」——已連上權威伺服器，與對方同步對話中（E2E 加密，伺服器看不到明文）。`,
    );
  }

  /**
   * [1.8.0 §10.3-2] 公開的重連入口：房間鑰匙 / 伺服器位址剛被換掉（重新貼邀請碼）
   * 時，舊的 AuthorityClient 還握著舊 token 的死連線 —— 丟掉重建，讓新鑰匙生效。
   */
  reconnectAuthority(): void {
    this.connectAuthority();
  }

  /**
   * Register myself (or any member) on the authority server for THIS room. A
   * freshly-spawned LOCAL server may not be listening yet, so retry a few times
   * with a short backoff before giving up (the SSE stream auto-reconnects too).
   */
  async joinSelf(member: Member): Promise<void> {
    // Remember who we are so an SSE reconnect (or a state frame that doesn't list
    // us, because our cold-start join lost the race) can re-register the same id.
    this.joinedMember = member;
    let lastErr = '';
    if (!this.authority) glog(`joinSelf:no-client room="${this.channel}" id="${member.id}" — 連線尚未建立，靠 8 次重試兜底`);
    for (let attempt = 0; attempt < 8; attempt++) {
      try {
        const r = await this.authority?.join(member);
        if (r && (r.ok === true || Array.isArray(r.members))) {
          glog(`joinSelf:ok room="${this.channel}" id="${member.id}" attempt=${attempt + 1}`);
          return;
        }
        lastErr = r && typeof (r as { error?: string }).error === 'string'
          ? (r as { error: string }).error : '伺服器未確認加入';
      } catch (e) { lastErr = e instanceof Error ? e.message : String(e); }
      // [1.9.3] 每次失敗都記（以前 7 次中間靜默，分不清 cold-start race vs 真連不到）。
      glog(`joinSelf:attempt ${attempt + 1}/8 room="${this.channel}" id="${member.id}" err="${lastErr}"`);
      await new Promise((res) => setTimeout(res, 500));
    }
    // [1.6.2] 連續 8 次都沒註冊成功 → 不再靜默（舊版會讓加入者卡著、卻只覺得「按了沒反應」，
    // 根因無從查；2026-06-12 外網人類進不來的烏龍）。明確跳錯＋給排查方向。
    void vscode.window.showErrorMessage(
      `AI King：加入群組「${this.channel}」失敗——連續向伺服器註冊 8 次都沒成功（${lastErr}）。` +
        `請確認：① 用的是對方「最新」產生的邀請碼（舊碼可能缺伺服器位址）② AI King 是最新版 ` +
        `③ 瀏覽器能開 ${this.roomAuthorityBase()}/health 看到 {"ok":true}。`,
    );
  }

  /**
   * Guarantee my own membership survives a server state frame. The roster is
   * server-authoritative, but if my join lost the cold-start race the pushed
   * `members` won't list me — re-fire the join (idempotent server-side) and
   * splice a local self entry so the UI never flickers me out. No-op once the
   * server confirms me.
   */
  private ensureSelfInRoster(): void {
    const meId = this.selfName();
    if (this.authMembers.some((m) => m.id === meId || m.name === meId)) {
      this.selfRejoinInflight = false; // server confirmed us → stop retrying
      return;
    }
    const self: Member = this.joinedMember || {
      id: meId, name: meId, type: 'human', role: this.selfRole(),
      avatar: '', joinedAt: Date.now(),
    };
    this.authMembers = [self, ...this.authMembers.filter((m) => m.id !== self.id)];
    // Re-register on the server and AWAIT confirmation. The old fire-and-forget
    // join could fail silently, and the next state frame (which doesn't list us)
    // would overwrite our local splice — flickering us out and blocking member
    // actions. We now retry on failure / when a state frame still omits us, until
    // the server's roster contains us. A single-flight guard avoids a re-join
    // storm when several state/presence frames arrive in quick succession.
    if (this.selfRejoinInflight) return;
    this.selfRejoinInflight = true;
    void (async () => {
      try {
        const r = await this.authority?.join(self);
        const confirmed = !!r && (
          r.ok === true ||
          (Array.isArray(r.members) && (r.members as Member[]).some((mm) => mm && mm.id === self.id))
        );
        if (!confirmed) {
          // Leave the flag set so the next state/presence frame re-attempts; the
          // local splice keeps the UI usable meanwhile.
          this.selfRejoinInflight = false;
          return;
        }
        this.selfRejoinInflight = false;
      } catch {
        // Network / server hiccup — clear the flag so a later frame retries.
        this.selfRejoinInflight = false;
      }
    })();
  }

  private constructor(
    private readonly ctx: vscode.ExtensionContext,
    panel: vscode.WebviewPanel,
    channel: string,
  ) {
    this.extensionUri = ctx.extensionUri;
    this.channel = channel;
    this.panel = panel;
    // [1.24.18 user] 分頁圖示＝複合圖標 tab-group.svg（AI King 皇冠 ＋ 右下「群組」角標，用左側欄
    //   同款 group.svg glyph）；標題只接群組名。有未讀時 updateUnreadIcon 換右上紅點版 tab-group-unread.svg。
    this.panel.iconPath = vscode.Uri.joinPath(this.extensionUri, 'media', 'icons', 'tab-crown.svg');

    this.home = BridgePanel.resolveBridgeHome();
    this.setChannelPaths(this.channel);

    this.ensureChannel();

    this.panel.webview.options = {
      enableScripts: true,
      localResourceRoots: [
        vscode.Uri.joinPath(this.extensionUri, 'media'),
        this.ctx.globalStorageUri, // uploaded member avatars live here
      ],
    };
    this.panel.webview.html = this.buildHtml(this.panel.webview);
    this.panel.webview.onDidReceiveMessage((msg) => this.onMessage(msg));
    this.panel.onDidChangeViewState((e) => {
      this.visible = e.webviewPanel.visible;
      if (this.visible) {
        this.unread = 0;
        this.updateUnreadIcon();
        // The SSE stream auto-reconnects internally, but if it was fully torn
        // down (authority undefined) while hidden, re-establish it on unhide so
        // the panel never silently renders stale state. Otherwise just re-pull
        // the newest page to recover anything missed during a transient drop.
        if (!this.authority) {
          this.connectAuthority();
        } else {
          void this.loadInitialHistory();
        }
      }
    });
    this.panel.onDidDispose(() => this.dispose());

    // [1.8.0 §13] re-push the interface language when the setting changes so
    // an open group panel re-renders without reopening.
    this.langCfgListener = vscode.workspace.onDidChangeConfiguration((e) => {
      if (e.affectsConfiguration('aiKing.language')) {
        this.post({ type: 'i18n:lang', lang: uiLang() });
      }
    });

    // [1.8.0 §10.1] 面板開啟 → 這個房的背景訂閱暫停（面板的連線接手，不重複訂閱）。
    // 必須在 connectAuthority() 之前通知，避免兩條 SSE 短暫並存。
    groupPanelOpened(this.channel);

    // AUTHORITY MODE (single source of truth). The panel connects ONE live SSE
    // stream to the authority server and renders whatever it pushes. It no longer
    // tails channel.jsonl, computes presence, or replays the roster locally.
    //   - 本機/群主 (authorityUrl = 127.0.0.1) → auto-spawn the bundled server.
    //   - 自架 VPS / 連別人本機 (authorityUrl set) → spawn nothing, just connect.
    this.connectAuthority();
  }

  /**
   * The authority server base URL for THIS room. An online room records its own
   * server in .relay.json (chosen at create/join); we honour that so the room stays
   * pinned to its server regardless of the GLOBAL authorityUrl (which a later join
   * to someone else's group would change — that was the cross-room break). Local
   * rooms have no relay config → fall back to the global authorityUrl (default 本機).
   */
  private roomAuthorityBase(room: string = this.channel): string {
    const cfg = readRelayConfig(room);
    const r = cfg?.relay;
    if (r && /^(?:https?|wss?):\/\//i.test(r)) return r; // online room: its own server
    // A 本機 room (no relay config) is local by definition — pin it to localhost even
    // if the global authorityUrl points at a VPS (set for online rooms). Otherwise a
    // "只這台" room would silently store its messages on the VPS.
    if (!isOnlineRoom(room)) return `http://127.0.0.1:${AUTHORITY_PORT}`;
    return authorityUrl();
  }

  /**
   * [v1.9.24 防呆] 把這個房的「伺服器類型」分成三類，給 ＋成員 / 邀請外部 的選單做防呆閘門。
   * 看的是 roomAuthorityBase() 回的位址的 host：
   *   - 'local'  本機：127.0.0.1 / localhost（含本機房無 .relay.json）→ 只有「同一台電腦」的 AI 連得到。
   *   - 'lan'    內網：192.168.* / 10.* / 172.16~31.* / *.local 主機名 → 只有「同一個區域網路」連得到。
   *   - 'public' 公開：https 或非上述私有位址的網域 / 公網 IP → 任何人都連得到。
   * 解析失敗（位址壞）一律當成最保守的 'local'（寧可擋住、別讓 user 選了必然失敗的跨機邀請）。
   * 純讀位址、零副作用；判斷邏輯刻意跟 bridge-fs.isRemoteServedRoom 的 127/localhost regex 對齊。
   */
  private roomServerType(room: string = this.channel): 'local' | 'lan' | 'public' {
    const base = this.roomAuthorityBase(room);
    let host = '';
    try {
      host = new URL(base).hostname.toLowerCase();
    } catch {
      glog(`roomServerType:parse-fail room="${room}" base="${base}" → 當本機(最保守)`);
      return 'local';
    }
    // 本機：loopback。
    if (host === '127.0.0.1' || host === 'localhost' || host === '::1') return 'local';
    // 內網 LAN：RFC1918 私有網段 + .local mDNS 主機名。
    const lan =
      /^192\.168\./.test(host) ||
      /^10\./.test(host) ||
      /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(host) ||
      /\.local$/.test(host) ||
      // 127.x.x.x 整段都是 loopback，但前面已收掉 127.0.0.1；其餘 127.* 也算本機。
      /^127\./.test(host);
    if (/^127\./.test(host)) return 'local';
    if (lan) return 'lan';
    // 其餘（公網 IP / 一般網域 / https VPS）→ 任何人連得到。
    return 'public';
  }

  /**
   * Open (or re-open) the authority SSE connection for THIS room. The server is
   * the single source of truth; everything we show comes from its events. For a
   * local room we make sure the bundled server is up first.
   */
  private connectAuthority(): void {
    this.stopMemberHeartbeat(); // [1.9.16] 重連先停舊心跳計時器（連上後重啟）
    try { this.authority?.close(); } catch { /* */ }
    if (this.connectTimer) { clearTimeout(this.connectTimer); this.connectTimer = undefined; }
    this.firstStateSeen = false;
    this.serverPresenceV2 = false; // 重連重新偵測伺服器是否支援 online/lastSeen 欄位
    // Reset the initial-history loader so a (re)connect always re-pulls the full
    // newest page rather than trusting a possibly-stale in-memory buffer.
    this.historyLoaded = false;
    this.historyRetries = 0;
    if (this.historyRetryTimer) { clearTimeout(this.historyRetryTimer); this.historyRetryTimer = undefined; }
    // Per-room server: an online room records its OWN server in .relay.json, so it
    // keeps connecting there even if the GLOBAL authorityUrl later changes (e.g. the
    // user joins someone else's group). Local rooms fall back to the global url.
    const base = this.roomAuthorityBase();
    ensureAuthorityServer(base); // spawn the local server ONLY when THIS room is local
    const token = getRoomToken(this.channel);
    // E2E REQUIRES key material. An empty token would make encryptText() fall
    // back to plaintext passthrough — a silent loss of E2E (and on join it would
    // desync the ROOM_KEY). Refuse to connect and surface the failure instead of
    // quietly running unencrypted. (getRoomToken returns '' on file I/O failure.)
    if (!token || !token.trim()) {
      // token-missing (not generic 'unavailable') drives a sticky webview banner so
      // the user sees a persistent warning, not just a one-shot toast.
      glog(`TOKEN-MISSING room="${this.channel}" — getRoomToken empty (disk/permission?)`);
      this.post({ type: 'relayStatus', state: 'token-missing' });
      this.lastRelayState = 'unavailable';
      void vscode.window.showErrorMessage(
        'AI 群組：房間鑰匙（token）讀取失敗或為空，無法建立 E2E 加密連線。' +
          '請確認磁碟空間與檔案權限，或向對方重新索取邀請碼。',
      );
      return;
    }
    this.authority = new AuthorityClient(
      base,
      this.channel,
      token,
      this.selfName(),
      this.selfName(),
      (ev) => this.onAuthorityEvent(ev),
      // onNeedJoin: the server gates /sub to roster members. A fresh joiner (or a
      // server that lost in-memory state) gets 403 'not a member' on subscribe —
      // register first, then the client retries the subscribe. Idempotent.
      async () => {
        const self: Member = this.joinedMember || {
          id: this.selfName(), name: this.selfName(), type: 'human',
          role: this.selfRole(), avatar: '', joinedAt: Date.now(),
        };
        try { await this.authority?.join(self); } catch { /* retried by subscribe */ }
      },
      // [1.6.4] onFatal: 連線收到無法靠重連解決的致命錯（bad token＝鑰匙跟伺服器不符）→
      // 不再靜默無限重連，明確提示＋引導修復（同名群組重建撞舊 token 的烏龍根治）。
      (kind) => this.onAuthorityFatal(kind),
      // [1.9.3] onDiag: /sub 的 4xx 閘門結果（身分閘 not-a-member / token 閘 bad-token /
      // 其他狀態）以前全被 client 吞掉。接到 glog 後，邀人「卡在連線中」一眼定位是哪道閘。
      (tag, detail) => glog(`${tag} room="${this.channel}" ${detail}`),
      // [never-blank] onStatus: SSE 斷線 / 530（Cloudflare 隧道斷）/ 串流中斷 → 面板顯示
      // 「重新連線中」而非卡在假「已連線」。連回來時 state 幀會把狀態翻回 'connected'
      // （onAuthorityEvent 的 'state' 分支）。本機鏡像已墊底，故斷線時對話不空白。
      (state) => {
        this.lastRelayState = state;
        this.post({ type: 'relayStatus', state });
      },
    );
    glog(`connect room="${this.channel}" → ${base}  (token ${token.length} chars, me="${this.selfName()}")`);
    this.authority.connect();
    // Footer status: in authority mode the SSE stream itself IS the connection;
    // surface it like the old relay status so the user sees 連線中 → 已連線.
    this.post({ type: 'relayStatus', state: 'connecting' });
    this.lastRelayState = 'connecting';
    // Escalate to 'unavailable' if no server state frame lands in time, so the UI
    // never claims "連線中" forever on a wrong URL / token / dead server.
    this.connectTimer = setTimeout(() => {
      this.connectTimer = undefined;
      if (!this.firstStateSeen) {
        this.lastRelayState = 'unavailable';
        glog(`UNAVAILABLE room="${this.channel}" → ${base}  (no state frame in ${this.connectTimeoutMs}ms — wrong url/token or server unreachable)`);

static createOrShow(
  ctx: vscode.ExtensionContext,
  channel?: string,
): BridgePanel {
  // [1.8.0 §10.3-3] 由房名解析房間：新規則 id 沒有本機資料夾時 fallback 試 legacy
  // id（1.6.4 舊清洗規則），命中 → 沿用 legacy id（含中文/空格的舊房名照樣開得回
  // 原資料夾 / 原伺服器房 / 原 E2E 鑰匙）。對已存在的資料夾名是冪等的。
  const ch = resolveRoomId((channel || 'main').trim() || 'main') || 'main';
  const existing = BridgePanel.panels.get(ch);
  // [user 2026-06-20 觀測] 記原始 channel→解析後 ch→是否命中既有→當前 panels keys，
  // 方便撈「AI King 群組」output channel 確認重複開窗真因（同 key 重用 vs key 沒命中又開新）。
  bridgeLog(
    `bridge:open room="${channel ?? ''}"→ch="${ch}" hit=${!!existing} ` +
      `panels=[${[...BridgePanel.panels.keys()].join(', ')}]`,
  );
  if (existing) {
    // [user 2026-06-20] 已開著就回到它、絕不再開重複分頁；reveal 帶到前景 + 叫它關掉
    // 群組設定抽屜回訊息（reveal 只切分頁、不關面板內 overlay，故另發 focusMessages）。
    existing.panel.reveal(undefined, false);
    existing.focusMessages();
    return existing;
  }
  const column = vscode.window.activeTextEditor
    ? vscode.window.activeTextEditor.viewColumn
    : vscode.ViewColumn.One;
  const panel = vscode.window.createWebviewPanel(
    BridgePanel.viewType,
    '群組 — ' + roomLabel(ch),
    column || vscode.ViewColumn.One,
    {
      enableScripts: true,
      retainContextWhenHidden: true,
      localResourceRoots: [vscode.Uri.joinPath(ctx.extensionUri, 'media')],
    },
  );
  const inst = new BridgePanel(ctx, panel, ch);
  BridgePanel.panels.set(ch, inst);
  return inst;
}

static revive(
  ctx: vscode.ExtensionContext,
  channel: string,
  panel: vscode.WebviewPanel,
): BridgePanel {
  const ch = resolveRoomId((channel || 'main').trim() || 'main') || 'main';
  const dup = BridgePanel.panels.get(ch);
  bridgeLog(
    `bridge:revive room="${channel}"→ch="${ch}" dup=${!!dup} ` +
      `panels=[${[...BridgePanel.panels.keys()].join(', ')}]`,
  );
  if (dup) {
    // [user 2026-06-20] reload 還原去重：同一房（同 ch key）已有面板——VS Code 對先前
    // 重複的分頁各還原一次、或 createOrShow 時序競爭已先建好——把這個多餘的還原 panel
    // 關掉、回既有，不留重複/殭屍分頁。只用可靠的同 key 比對（不碰 resolveRoomId/E2E）。
    try { panel.dispose(); } catch { /* already gone */ }
    return dup;
  }
  const inst = new BridgePanel(ctx, panel, ch);
  BridgePanel.panels.set(ch, inst);
  return inst;
}

focusMessages(): void {
  try {
    void this.panel.webview.postMessage({ type: 'focusMessages' });
  } catch {
    /* panel 已 dispose */
  }
}

static closeForChannel(channel: string): void {
  const p = BridgePanel.panels.get(channel);
  if (p) p.dispose();
}

static async syncIdentityForSession(_sessionId?: string): Promise<void> {
  for (const p of BridgePanel.panels.values()) {
    p.lastIdentitySync = 0; // 解除 4s 節流，讓這次改動立即連動
    try { await p.syncBuiltinIdentitiesFromSessions(); } catch { /* best-effort */ }
  }
}

static activePanel(): BridgePanel | undefined {
  let visible: BridgePanel | undefined;
  for (const p of BridgePanel.panels.values()) {
    if (p.panel.active) return p;
    if (!visible && p.panel.visible) visible = p;
  }
  if (visible) return visible;
  const it = BridgePanel.panels.values().next();
  return it.done ? undefined : it.value;
}

static async pickNotifyLevelFor(channel?: string): Promise<void> {
  const target = channel && channel.trim()
    ? BridgePanel.panels.get(channel.trim())
    : BridgePanel.activePanel();
  if (!target) {
    void vscode.window.showInformationMessage(
      'AI 群組：先開一個群組，再設定它的通知層級。',
    );
    return;
  }
  await target.pickNotifyLevel();
}

static async joinFromInvite(ctx: vscode.ExtensionContext): Promise<void> {
  const blob = await showInputBoxEsc({
    prompt: '貼上線上群組邀請碼（AIBRIDGE1:…，按 ESC 取消）',
    placeHolder: 'AIBRIDGE1:eyJyb29tIjoi…',
    ignoreFocusOut: true,
    validateInput: (v) => (v && v.trim() ? null : '請貼上邀請碼'),
  });
  if (!blob || !blob.trim()) return;
  const inv = decodeInvite(blob.trim());
  if (!inv) {
    void vscode.window.showErrorMessage(
      'AI King：邀請碼無法解析（格式不符）。請確認從對方的「邀請 → 線上」整段複製。',
    );
    return;
  }
  // [1.8.0 §10.3-3] 舊房名相容：邀請碼帶的是「原始房名」算出的新規則 id 時，若本機
  // 只有 legacy id 的資料夾（1.6.4 舊清洗規則），沿用 legacy id —— 這樣本機備份、
  // 伺服器房名與 E2E 鑰匙（sha256(room:token)）三者跟舊資料對齊。
  const room = resolveRoomId(inv.room) || inv.room;
  glog(`join-invite:decoded room="${inv.room}"→"${room}" authority=${inv.authorityUrl || '(legacy/none)'} tokenLen=${(inv.token || '').length}`);
  const me = await showInputBoxEsc({
    prompt: `你在群組「${room}」要顯示的名字（讓對方認得你；別跟對方同名，按 ESC 取消）`,
    value: '人類代理A',
    ignoreFocusOut: true,
    validateInput: (v) => (v && v.trim() ? null : '請輸入名稱'),
  });
  if (!me || !me.trim()) return;
  // ROOM_KEY = sha256(room:token); an empty token would silently desync. Bail
  // before we write any half state.
  if (!inv.token || !inv.token.trim()) {
    void vscode.window.showErrorMessage(
      'AI King：邀請碼缺少房間鑰匙（token），無法加入。請向對方重新索取完整邀請碼。',
    );
    return;
  }
  // The invite must name the authority server to connect to (new codes carry
  // it; a legacy relay-only code has none → we can't authority-join it).
  const authority = (inv.authorityUrl || '').trim();
  if (!authority) {
    void vscode.window.showErrorMessage(
      'AI King：這個邀請碼是舊版（只含中繼站、沒有 authority 伺服器位址），無法用新的權威伺服器模式加入。請向對方重新產生一份新版連線碼。',
    );
    return;
  }
  try {
    if (!createRoom(room)) throw new Error('建立本機房間失敗');
    if (!writeIdentity(room, { me: me.trim(), role: 'member' })) {
      throw new Error('寫入身分失敗');
    }
    // Adopt the inviter's EXACT token (authority gate + E2E key derivation).
    if (!writeRoomToken(room, inv.token)) throw new Error('寫入房間鑰匙失敗');
    // Keep .relay.json for back-compat so isOnlineRoom()=true (🌐 title); the
    // relay bridge is NOT started in authority mode.
    if (
      !writeRelayConfig(room, {
        relay: authority,
        token: inv.token,
        me: me.trim(),
        role: 'member',
      })
    ) {
      throw new Error('寫入連線設定失敗');
    }
    glog(`join-invite:fs-written room="${room}" me="${me.trim()}" authority=${authority}`);
    // Per-room (#24 fix): this room is now pinned to the inviter's server via its
    // .relay.json (relay = authority). We deliberately do NOT change the GLOBAL
    // authorityUrl — that would yank every OTHER room on this machine onto the
    // inviter's server. connectAuthority() reads the per-room relay first, so this
    // room reaches the inviter regardless of what the global setting is.
  } catch (e: unknown) {
    glog(`join-invite:fs-fail room="${room}" err=${e instanceof Error ? e.message : String(e)}`);
    if (!isOnlineRoom(room)) {
      try { deleteRoom(room); } catch { /* best-effort */ }
    }
    void vscode.window.showErrorMessage(
      `AI King：加入線上群組「${room}」失敗 — ${e instanceof Error ? e.message : String(e)}。已清理半套狀態，請重試。`,
    );
    return;
  }
  // Open the panel — its constructor connects to the authority SSE stream. Then
  // register myself on the server (broadcasts a member event so the owner sees
  // me). The server is authoritative for the rest of the roster + history.
  // [1.8.0 §10.3-2] 面板若已開著（bad-token 後按「重新索取邀請碼」走到這裡），它握
  // 的還是「舊鑰匙」的死連線 —— token / 伺服器位址剛換過，必須丟掉舊連線重連。
  const existed = BridgePanel.panels.has(room);
  const inst = BridgePanel.createOrShow(ctx, room);
  if (existed) inst.reconnectAuthority();
  void inst.joinSelf({
    id: me.trim(), name: me.trim(), type: 'human',
    role: 'member', avatar: '', joinedAt: Date.now(),
  });
  // Put the joined room on the Home list right away (same fix as create-group) —
  // otherwise a freshly joined room doesn't show until a visibility toggle.
  void vscode.commands.executeCommand('aiKing.home.refresh');
  void vscode.window.showInformationMessage(
    `已加入線上群組「${room}」——已連上權威伺服器，與對方同步對話中（E2E 加密，伺服器看不到明文）。`,
  );
}

reconnectAuthority(): void {
  this.connectAuthority();
}

async joinSelf(member: Member): Promise<void> {
  // Remember who we are so an SSE reconnect (or a state frame that doesn't list
  // us, because our cold-start join lost the race) can re-register the same id.
  this.joinedMember = member;
  let lastErr = '';
  if (!this.authority) glog(`joinSelf:no-client room="${this.channel}" id="${member.id}" — 連線尚未建立，靠 8 次重試兜底`);
  for (let attempt = 0; attempt < 8; attempt++) {
    try {
      const r = await this.authority?.join(member);
      if (r && (r.ok === true || Array.isArray(r.members))) {
        glog(`joinSelf:ok room="${this.channel}" id="${member.id}" attempt=${attempt + 1}`);
        return;
      }
      lastErr = r && typeof (r as { error?: string }).error === 'string'
        ? (r as { error: string }).error : '伺服器未確認加入';
    } catch (e) { lastErr = e instanceof Error ? e.message : String(e); }
    // [1.9.3] 每次失敗都記（以前 7 次中間靜默，分不清 cold-start race vs 真連不到）。
    glog(`joinSelf:attempt ${attempt + 1}/8 room="${this.channel}" id="${member.id}" err="${lastErr}"`);
    await new Promise((res) => setTimeout(res, 500));
  }
  // [1.6.2] 連續 8 次都沒註冊成功 → 不再靜默（舊版會讓加入者卡著、卻只覺得「按了沒反應」，
  // 根因無從查；2026-06-12 外網人類進不來的烏龍）。明確跳錯＋給排查方向。
  void vscode.window.showErrorMessage(
    `AI King：加入群組「${this.channel}」失敗——連續向伺服器註冊 8 次都沒成功（${lastErr}）。` +
      `請確認：① 用的是對方「最新」產生的邀請碼（舊碼可能缺伺服器位址）② AI King 是最新版 ` +
      `③ 瀏覽器能開 ${this.roomAuthorityBase()}/health 看到 {"ok":true}。`,
  );
}

private ensureSelfInRoster(): void {
  const meId = this.selfName();
  if (this.authMembers.some((m) => m.id === meId || m.name === meId)) {
    this.selfRejoinInflight = false; // server confirmed us → stop retrying
    return;
  }
  const self: Member = this.joinedMember || {
    id: meId, name: meId, type: 'human', role: this.selfRole(),
    avatar: '', joinedAt: Date.now(),
  };
  this.authMembers = [self, ...this.authMembers.filter((m) => m.id !== self.id)];
  // Re-register on the server and AWAIT confirmation. The old fire-and-forget
  // join could fail silently, and the next state frame (which doesn't list us)
  // would overwrite our local splice — flickering us out and blocking member
  // actions. We now retry on failure / when a state frame still omits us, until
  // the server's roster contains us. A single-flight guard avoids a re-join
  // storm when several state/presence frames arrive in quick succession.
  if (this.selfRejoinInflight) return;
  this.selfRejoinInflight = true;
  void (async () => {
    try {
      const r = await this.authority?.join(self);
      const confirmed = !!r && (
        r.ok === true ||
        (Array.isArray(r.members) && (r.members as Member[]).some((mm) => mm && mm.id === self.id))
      );
      if (!confirmed) {
        // Leave the flag set so the next state/presence frame re-attempts; the
        // local splice keeps the UI usable meanwhile.
        this.selfRejoinInflight = false;
        return;
      }
      this.selfRejoinInflight = false;
    } catch {
      // Network / server hiccup — clear the flag so a later frame retries.
      this.selfRejoinInflight = false;
    }
  })();
}

private constructor(
  private readonly ctx: vscode.ExtensionContext,
  panel: vscode.WebviewPanel,
  channel: string,
) {
  this.extensionUri = ctx.extensionUri;
  this.channel = channel;
  this.panel = panel;
  // [1.24.18 user] 分頁圖示＝複合圖標 tab-group.svg（AI King 皇冠 ＋ 右下「群組」角標，用左側欄
  //   同款 group.svg glyph）；標題只接群組名。有未讀時 updateUnreadIcon 換右上紅點版 tab-group-unread.svg。
  this.panel.iconPath = vscode.Uri.joinPath(this.extensionUri, 'media', 'icons', 'tab-crown.svg');

  this.home = BridgePanel.resolveBridgeHome();
  this.setChannelPaths(this.channel);

  this.ensureChannel();

  this.panel.webview.options = {
    enableScripts: true,
    localResourceRoots: [
      vscode.Uri.joinPath(this.extensionUri, 'media'),
      this.ctx.globalStorageUri, // uploaded member avatars live here
    ],
  };
  this.panel.webview.html = this.buildHtml(this.panel.webview);
  this.panel.webview.onDidReceiveMessage((msg) => this.onMessage(msg));
  this.panel.onDidChangeViewState((e) => {
    this.visible = e.webviewPanel.visible;
    if (this.visible) {
      this.unread = 0;
      this.updateUnreadIcon();
      // The SSE stream auto-reconnects internally, but if it was fully torn
      // down (authority undefined) while hidden, re-establish it on unhide so
      // the panel never silently renders stale state. Otherwise just re-pull
      // the newest page to recover anything missed during a transient drop.
      if (!this.authority) {
        this.connectAuthority();
      } else {
        void this.loadInitialHistory();
      }
    }
  });
  this.panel.onDidDispose(() => this.dispose());

  // [1.8.0 §13] re-push the interface language when the setting changes so
  // an open group panel re-renders without reopening.
  this.langCfgListener = vscode.workspace.onDidChangeConfiguration((e) => {
    if (e.affectsConfiguration('aiKing.language')) {
      this.post({ type: 'i18n:lang', lang: uiLang() });
    }
  });

  // [1.8.0 §10.1] 面板開啟 → 這個房的背景訂閱暫停（面板的連線接手，不重複訂閱）。
  // 必須在 connectAuthority() 之前通知，避免兩條 SSE 短暫並存。
  groupPanelOpened(this.channel);

  // AUTHORITY MODE (single source of truth). The panel connects ONE live SSE
  // stream to the authority server and renders whatever it pushes. It no longer
  // tails channel.jsonl, computes presence, or replays the roster locally.
  //   - 本機/群主 (authorityUrl = 127.0.0.1) → auto-spawn the bundled server.
  //   - 自架 VPS / 連別人本機 (authorityUrl set) → spawn nothing, just connect.
  this.connectAuthority();
}

private roomAuthorityBase(room: string = this.channel): string {
  const cfg = readRelayConfig(room);
  const r = cfg?.relay;
  if (r && /^(?:https?|wss?):\/\//i.test(r)) return r; // online room: its own server
  // A 本機 room (no relay config) is local by definition — pin it to localhost even
  // if the global authorityUrl points at a VPS (set for online rooms). Otherwise a
  // "只這台" room would silently store its messages on the VPS.
  if (!isOnlineRoom(room)) return `http://127.0.0.1:${AUTHORITY_PORT}`;
  return authorityUrl();
}

private roomServerType(room: string = this.channel): 'local' | 'lan' | 'public' {
  const base = this.roomAuthorityBase(room);
  let host = '';
  try {
    host = new URL(base).hostname.toLowerCase();
  } catch {
    glog(`roomServerType:parse-fail room="${room}" base="${base}" → 當本機(最保守)`);
    return 'local';
  }
  // 本機：loopback。
  if (host === '127.0.0.1' || host === 'localhost' || host === '::1') return 'local';
  // 內網 LAN：RFC1918 私有網段 + .local mDNS 主機名。
  const lan =
    /^192\.168\./.test(host) ||
    /^10\./.test(host) ||
    /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(host) ||
    /\.local$/.test(host) ||
    // 127.x.x.x 整段都是 loopback，但前面已收掉 127.0.0.1；其餘 127.* 也算本機。
    /^127\./.test(host);
  if (/^127\./.test(host)) return 'local';
  if (lan) return 'lan';
  // 其餘（公網 IP / 一般網域 / https VPS）→ 任何人連得到。
  return 'public';
}

private connectAuthority(): void {
  this.stopMemberHeartbeat(); // [1.9.16] 重連先停舊心跳計時器（連上後重啟）
  try { this.authority?.close(); } catch { /* */ }
  if (this.connectTimer) { clearTimeout(this.connectTimer); this.connectTimer = undefined; }
  this.firstStateSeen = false;
  this.serverPresenceV2 = false; // 重連重新偵測伺服器是否支援 online/lastSeen 欄位
  // Reset the initial-history loader so a (re)connect always re-pulls the full
  // newest page rather than trusting a possibly-stale in-memory buffer.
  this.historyLoaded = false;
  this.historyRetries = 0;
  if (this.historyRetryTimer) { clearTimeout(this.historyRetryTimer); this.historyRetryTimer = undefined; }
  // Per-room server: an online room records its OWN server in .relay.json, so it
  // keeps connecting there even if the GLOBAL authorityUrl later changes (e.g. the
  // user joins someone else's group). Local rooms fall back to the global url.
  const base = this.roomAuthorityBase();
  ensureAuthorityServer(base); // spawn the local server ONLY when THIS room is local
  const token = getRoomToken(this.channel);
  // E2E REQUIRES key material. An empty token would make encryptText() fall
  // back to plaintext passthrough — a silent loss of E2E (and on join it would
  // desync the ROOM_KEY). Refuse to connect and surface the failure instead of
  // quietly running unencrypted. (getRoomToken returns '' on file I/O failure.)
  if (!token || !token.trim()) {
    // token-missing (not generic 'unavailable') drives a sticky webview banner so
    // the user sees a persistent warning, not just a one-shot toast.
    glog(`TOKEN-MISSING room="${this.channel}" — getRoomToken empty (disk/permission?)`);
    this.post({ type: 'relayStatus', state: 'token-missing' });
    this.lastRelayState = 'unavailable';
    void vscode.window.showErrorMessage(
      'AI 群組：房間鑰匙（token）讀取失敗或為空，無法建立 E2E 加密連線。' +
        '請確認磁碟空間與檔案權限，或向對方重新索取邀請碼。',
    );
    return;
  }
  this.authority = new AuthorityClient(
    base,
    this.channel,
    token,
    this.selfName(),
    this.selfName(),
    (ev) => this.onAuthorityEvent(ev),
    // onNeedJoin: the server gates /sub to roster members. A fresh joiner (or a
    // server that lost in-memory state) gets 403 'not a member' on subscribe —
    // register first, then the client retries the subscribe. Idempotent.
    async () => {
      const self: Member = this.joinedMember || {
        id: this.selfName(), name: this.selfName(), type: 'human',
        role: this.selfRole(), avatar: '', joinedAt: Date.now(),
      };
      try { await this.authority?.join(self); } catch { /* retried by subscribe */ }
    },
    // [1.6.4] onFatal: 連線收到無法靠重連解決的致命錯（bad token＝鑰匙跟伺服器不符）→
    // 不再靜默無限重連，明確提示＋引導修復（同名群組重建撞舊 token 的烏龍根治）。
    (kind) => this.onAuthorityFatal(kind),
    // [1.9.3] onDiag: /sub 的 4xx 閘門結果（身分閘 not-a-member / token 閘 bad-token /
    // 其他狀態）以前全被 client 吞掉。接到 glog 後，邀人「卡在連線中」一眼定位是哪道閘。
    (tag, detail) => glog(`${tag} room="${this.channel}" ${detail}`),
    // [never-blank] onStatus: SSE 斷線 / 530（Cloudflare 隧道斷）/ 串流中斷 → 面板顯示
    // 「重新連線中」而非卡在假「已連線」。連回來時 state 幀會把狀態翻回 'connected'
    // （onAuthorityEvent 的 'state' 分支）。本機鏡像已墊底，故斷線時對話不空白。
    (state) => {
      this.lastRelayState = state;
      this.post({ type: 'relayStatus', state });
    },
  );
  glog(`connect room="${this.channel}" → ${base}  (token ${token.length} chars, me="${this.selfName()}")`);
  this.authority.connect();
  // Footer status: in authority mode the SSE stream itself IS the connection;
  // surface it like the old relay status so the user sees 連線中 → 已連線.
  this.post({ type: 'relayStatus', state: 'connecting' });
  this.lastRelayState = 'connecting';
  // Escalate to 'unavailable' if no server state frame lands in time, so the UI
  // never claims "連線中" forever on a wrong URL / token / dead server.
  this.connectTimer = setTimeout(() => {
    this.connectTimer = undefined;
    if (!this.firstStateSeen) {
      this.lastRelayState = 'unavailable';
      glog(`UNAVAILABLE room="${this.channel}" → ${base}  (no state frame in ${this.connectTimeoutMs}ms — wrong url/token or server unreachable)`);
      this.post({ type: 'relayStatus', state: 'unavailable' });
      void this.guideOnUnreachable();
    }
  }, this.connectTimeoutMs);
  // Initial newest page of history (decrypted inside AuthorityClient).
  void this.loadInitialHistory();
  this.startMemberHeartbeat(); // [1.9.16] 代「驅動的 AI 成員」打心跳＝讓它們在線（解離線真兇）
}

private startMemberHeartbeat(): void {
  if (this.memberHbTimer) { clearInterval(this.memberHbTimer); this.memberHbTimer = undefined; }
  const tick = () => {
    if (!this.authority) return;
    const ids = this.authMembers
      .filter((m) => m.architecture === 'clean' || m.architecture === 'aiking' || m.architecture === 'hermes' || m.architecture === 'acp' || m.type === 'cloud-persona')
      .map((m) => m.id);
    if (!ids.length) return; // 沒有驅動的 AI 成員＝不必代打
    void this.authority.heartbeat(this.selfName(), ids).catch(() => { /* 心跳失敗無妨，下次再打 */ });
  };
  tick(); // 連上立刻打一次，不等 25s
  this.memberHbTimer = setInterval(tick, 25_000);
}

private stopMemberHeartbeat(): void {
  if (this.memberHbTimer) { clearInterval(this.memberHbTimer); this.memberHbTimer = undefined; }
}

private async guideOnUnreachable(): Promise<void> {
  const url = this.roomAuthorityBase();
  const isLocal = /(?:\/\/)?(?:127\.0\.0\.1|localhost)\b/.test(url);
  const detail = isLocal
    ? `AI 群組「${this.channel}」：本機伺服器沒有回應（它本應自動啟動，可能被防火牆 / 連接埠占用 / Node 環境擋住）。`
    : `AI 群組「${this.channel}」：連不上伺服器（${url}）。`;
  const RETRY = '重試連線';
  const SWITCH = '設定伺服器位置';
  const pick = await vscode.window.showWarningMessage(
    detail + '（房間鑰匙與你發的訊息都正常，只是現在連不上）',
    RETRY, SWITCH,
  );
  if (pick === RETRY) {
    this.connectAuthority();
  } else if (pick === SWITCH) {
    await vscode.commands.executeCommand('aiKing.setAuthorityUrl');
    // Reconnect so the (possibly new) location takes effect without reopening.
    this.connectAuthority();
  }
}

private onAuthorityFatal(kind: string): void {
  glog(`FATAL room="${this.channel}" kind=${kind}`);
  this.lastRelayState = 'unavailable';
  if (kind === 'bad-token') {
    // webview 收到 'bad-token' → footer 紅 pill ＋ sticky banner（白話原因）＋
    // 「重新索取邀請碼」按鈕（postMessage 'rejoinInvite' 回到本面板）。
    this.post({ type: 'relayStatus', state: 'bad-token' });
    return;
  }
  this.post({ type: 'relayStatus', state: 'unavailable' });
}

private onAuthorityEvent(ev: AuthorityEvent): void {
  // Any event means the SSE stream is live → report "connected" once. This
  // also fires after an SSE auto-reconnect (AuthorityClient resubscribes on
  // drop). The server tracks presence by live connection, but a reconnect
  // does NOT re-run join() — so if I dropped out of the roster, re-register.
  const wasConnected = this.lastRelayState === 'connected';
  if (!wasConnected) {
    this.lastRelayState = 'connected';
    this.firstStateSeen = true;
    glog(`CONNECTED room="${this.channel}" ✓`);
    if (this.connectTimer) { clearTimeout(this.connectTimer); this.connectTimer = undefined; }
    this.post({ type: 'relayStatus', state: 'connected' });
    // Re-join after a (re)connection so the server roster recovers my member
    // entry/role even though the SSE layer only restored my presence.
    this.ensureSelfInRoster();
  }
  switch (ev.type) {
    case 'state': {
      const s = ev as unknown as {
        members?: Member[];
        online?: Array<{ id: string; name: string }>;
        status?: string;
        displayName?: string;
      };
      this.authMembers = Array.isArray(s.members) ? s.members : [];
      this.authOnline = Array.isArray(s.online) ? s.online : [];
      void this.maybeNotifyProfileIncomplete(); // [A 個資不全提醒 1.24.39] state 更新後掃 AI 成員缺供應商/型號
      // [10.2] 新伺服器的成員帶 online 布林（伺服器算）→ 開啟名字旁圓點顯示。
      if (this.authMembers.some((m) => typeof (m as { online?: unknown }).online === 'boolean')) {
        this.serverPresenceV2 = true;
      }
      if (typeof s.status === 'string') this.authStatus = s.status;
      if (typeof s.displayName === 'string') {
        this.roomDisplayName = s.displayName;
        // [統一母版 2026-06-16] 連線/重連的 state 帶 displayName → 寫本機 + 更新分頁標題，
        // 讓側邊欄列表（下次 listRooms 讀 roomLabel）與分頁名跟伺服器一致。
        setRoomDisplayName(this.channel, s.displayName);
        try { this.panel.title = '群組 — ' + roomLabel(this.channel); } catch { /* panel disposed */ }
      }
      // A state frame proves the server is reachable → cancel the connect
      // timeout escalation. If our own join lost the cold-start race (server
      // not listening yet), the server roster won't contain us — re-register
      // and 3-way merge a local self entry so the UI never flickers me out.
      this.firstStateSeen = true;
      if (this.connectTimer) { clearTimeout(this.connectTimer); this.connectTimer = undefined; }
      this.ensureSelfInRoster();
      this.pushMembers();
      this.pushPresence();
      this.post({ type: 'meta', meta: this.meta() });
      // The state frame only arrives once the server is reachable. If the
      // initial history pull hasn't SUCCEEDED yet (cold-start race, or it
      // failed and is mid-retry), re-kick it now that we know the server
      // answers. Gating on historyLoaded (not buffer.length) means a stale
      // non-empty buffer from a reload can't suppress the fresh pull.
      if (!this.historyLoaded) void this.loadInitialHistory();
      this.maybeHintStale(); // one-shot「離線超過 N 天」提示（owner/admin）
      break;
    }
    case 'presence': {
      const s = ev as unknown as { online?: Array<{ id: string; name: string }> };
      this.authOnline = Array.isArray(s.online) ? s.online : [];
      this.pushPresence();
      this.pushMembers(); // refresh online dots on avatars
      break;
    }
    case 'member': {
      const s = ev as unknown as { op?: string; member?: Member; id?: string };
      // [10.2] member 廣播也可能帶伺服器算的 online（新伺服器）→ 開啟圓點顯示。
      if (s.member && typeof (s.member as { online?: unknown }).online === 'boolean') {
        this.serverPresenceV2 = true;
      }
      if (s.op === 'add' && s.member && s.member.id) {
        if (!this.authMembers.some((m) => m.id === s.member!.id)) {
          this.authMembers.push(s.member);
        }
      } else if (s.op === 'remove' && s.id) {
        this.authMembers = this.authMembers.filter((m) => m.id !== s.id);
      } else if (s.op === 'update' && s.member && s.member.id) {
        const i = this.authMembers.findIndex((m) => m.id === s.member!.id);
        if (i >= 0) this.authMembers[i] = s.member; else this.authMembers.push(s.member);
      }
      // [1.9.3] 確認本端確實收到成員廣播（邀人後群主端到底有沒有收到加入事件）。
      glog(`member:${s.op || '?'} id="${s.member?.id || s.id || '?'}" total=${this.authMembers.length}`);
      this.pushMembers();
      break;
    }
    case 'cleared': {
      // Owner/admin cleared the room history on the server — wipe our view too.
      this.buffer = [];
      // [2026-06-18 fix · user「刪除要真刪」] 連本地 channel.jsonl 鏡像一起清——否則重開 never-blank
      // 從鏡像 seed（readMirrorTail）又把整房舊訊息撈回顯示（同刪訊息的本地鏡像殘留根）。
      clearMirror(this.channel);
      this.post({ type: 'reset', history: [], meta: this.meta() });
      break;
    }
    case 'msg.delete': {
      // [2026-06-16] 伺服器廣播某則被刪（owner/admin 刪單則）→ 本地 buffer 移除該 seq
      // + 通知 webview 移掉那則 DOM＝伺服器與本地一致、之後任何人/AI 都讀不到。
      const s = ev as unknown as { seq?: number };
      const delSeq = typeof s.seq === 'number' ? s.seq : 0;
      if (delSeq) {
        this.buffer = this.buffer.filter((m) => m.seq !== delSeq);
        // [2026-06-18 fix · user「刪訊息重開又跑出來」] 同步從本地 channel.jsonl 鏡像移除該 seq——否則
        // 重開時 loadInitialHistory 的 never-blank seed（readMirrorTail 讀鏡像）又把這則撈回來顯示。
        deleteFromMirror(this.channel, delSeq);
        this.post({ type: 'msgDelete', seq: delSeq });
      }
      break;
    }
    case 'msg': {
      const s = ev as unknown as { message?: BridgeMessage };
      if (s.message && typeof s.message.text === 'string') {
        const vm = this.norm(s.message); // text already decrypted by AuthorityClient
        this.noteDecryptHealth(vm.text); // detect token mismatch / plaintext
        this.appendFromServer(vm);
      }
      break;
    }
    case 'room.dissolve': {
      this.authStatus = 'dissolved';
      this.post({ type: 'meta', meta: this.meta() });
      break;
    }
    case 'loop.suspect': {
      // 伺服器粗篩偵測到疑似空轉（互@振盪 / 逾時死鎖）。只提示人類群主 / admin，
      // 不自動禁言 —— 紅藍裁決：最終一定由管理員手動拍板。
      // [通知分類] 「空轉」這一類走這條事件路徑（不經 maybeNotify）：主開關關 or
      // 空轉類關 → 不彈這個警告。
      const loopCats = this.notifyCats();
      if (!loopCats.master) { glog('maybeNotify:skip master=off cat=空轉'); break; }
      if (!loopCats.loop) { glog('maybeNotify:skip cat=空轉 off'); break; }
      if (this.canManage()) {
        const s = ev as unknown as { kind?: string; pair?: string[]; rounds?: number; waiting?: string; mentioned?: string[] };
        // [通知根治] 空轉去重（user 第一痛點「空轉通知重複」）：同一空轉狀態指紋只通知一次、
        // 跨重開視窗也不重複（globalState 持久化、原本完全無去重）；同指紋 30 分鐘內不再彈，
        // 持續空轉超過才再提醒一次（狀態型+最小週期，非每次粗篩命中都彈）。24h 清舊鍵防膨脹。
        const fp = s.kind === 'deadlock'
          ? `dl:${s.waiting || ''}:${(s.mentioned || []).slice().sort().join('/')}`
          : `osc:${(s.pair || []).slice().sort().join('|')}`;
        const dkey = `${this.channel}:${fp}`;
        const LOOP_DEDUP_KEY = 'aiKing.notify.loopDedup';
        const lstore = this.ctx.globalState.get<Record<string, number>>(LOOP_DEDUP_KEY) || {};
        const lnow = Date.now();
        if (lnow - (lstore[dkey] || 0) < 30 * 60 * 1000) {
          glog(`loop.suspect:dedup skip key=${dkey}`);
          break;
        }
        lstore[dkey] = lnow;
        for (const k of Object.keys(lstore)) {
          if (lnow - lstore[k] > 24 * 60 * 60 * 1000) delete lstore[k];
        }
        void this.ctx.globalState.update(LOOP_DEDUP_KEY, lstore);
        const who = s.kind === 'deadlock'
          ? `${s.waiting} @ 了 ${(s.mentioned || []).join('/')} 但久無回應（疑似互等死鎖）`
          : `${(s.pair || []).join(' ↔ ')} 互 @ 來回 ${s.rounds || ''} 次、無人介入`;
        void vscode.window.showWarningMessage(
          `AI 群組「${this.channel}」：偵測到疑似空轉 — ${who}。要禁言請點該成員頭像卡 → 🔇。`,
        );
      }
      break;
    }
    case 'room.rename': {
      const s = ev as unknown as { displayName?: string };
      if (typeof s.displayName === 'string') {
        this.roomDisplayName = s.displayName;
        // [統一母版 2026-06-16] 改名同步三顯示點：① 寫本機 displayName（讓側邊欄列表/分頁標題
        // 讀得到、不再只在 topbar 變）② 更新分頁標題 ③ 通知側邊欄列表刷新。topbar 靠下面 post meta。
        setRoomDisplayName(this.channel, s.displayName);
        try { this.panel.title = '群組 — ' + roomLabel(this.channel); } catch { /* panel disposed */ }
        void vscode.commands.executeCommand('aiKing.home.refresh');
      }
      this.post({ type: 'meta', meta: this.meta() });
      break;
    }
  }
}

private noteDecryptHealth(text: string): void {
  if (this.warnedDecryptMismatch) return;
  const failed =
    text === DECRYPT_FAIL_SENTINEL ||
    text === PLAINTEXT_IN_ENCRYPTED_ROOM ||
    text.startsWith(E2E_BLOB_PREFIX);
  if (!failed) return;
  this.warnedDecryptMismatch = true;
  // Sticky webview banner so EVERY subsequent garbled line is framed as "the
  // whole room is unreadable", not a single odd message. The one-shot toast
  // stays as the active interruption; the banner persists in the panel.
  this.post({ type: 'decryptHealth', ok: false });
  void vscode.window.showErrorMessage(
    'AI 群組：訊息無法解密 — 你的房間鑰匙與伺服器上的密文不符。' +
      '通常是邀請碼 / 房間鑰匙或權威伺服器位址（aiKing.authorityUrl）對不上對方。' +
      '請向對方重新索取完整邀請碼後重新加入。',
  );
}

private appendFromServer(vm: ViewMessage): void {
  // [1.9.17] seq 去重：同一則訊息被重複遞送（SSE 重連重播 / 重複事件）→ 以前會重複渲染
  // ＋重複呼叫 routePersonas → AI 對同一句回兩次（user 截圖實證 代理A「在。」兩次）。seq 由
  // 伺服器單調遞增；已處理過（≤已見最大）就整則跳過，不渲染也不路由。
  if (typeof vm.seq === 'number' && vm.seq > 0) {
    if (vm.seq <= this.maxSeenSeq) { glog(`appendFromServer:dup-skip seq=${vm.seq} from="${vm.from}"`); return; }
    this.maxSeenSeq = vm.seq;
  }
  this.buffer.push(vm);
  const max = this.maxRenderLines();
  if (this.buffer.length > max) this.buffer = this.buffer.slice(-max);
  this.post({ type: 'append', msg: vm });
  // [表情反應] 反應訊息（text 以 `react:` sentinel 開頭）走現有 E2E 訊息管道（伺服器
  // 只看到密文、不必改動），但它「不是聊天」：① 不彈通知 ② ⛔絕不丟給 routePersonas
  // （否則 AI 會對一個按讚動作亂回、洗版）。仍 push 進 buffer + post 給 webview，讓 webview
  // 端聚合成徽章（並支援重開歷史回放時重新聚合）；webview 自己負責「不畫成氣泡」。
  if (isReactionText(vm.text)) {
    glog(`appendFromServer:reaction seq=${vm.seq} from="${vm.from}" (skip notify+route)`);
    return;
  }
  // [指令標示] 標示訊息（text 以 `label:` sentinel 開頭）跟反應同理：走現有 E2E 管道，
  // 但「不是聊天」——① 不彈通知 ② ⛔絕不丟給 routePersonas（否則 AI 會對「已讀不回 / 收到」
  // 這種狀態標示亂回、洗版）。仍 push 進 buffer + post 給 webview，讓 webview 端渲染成置中
  // 系統狀態行（並支援重開歷史回放）；webview 自己負責「不畫成氣泡、不計數」。
  // ⚠ 與上面的 react 早退分開判斷（react vs label 各一條），不互相覆蓋。
  if (isLabelText(vm.text)) {
    glog(`appendFromServer:label seq=${vm.seq} from="${vm.from}" (skip notify+route)`);
    return;
  }
  // [系統動作] 系統訊息（text 以 `sys:` sentinel 開頭）跟反應 / 標示同理：走現有 E2E 管道，
  // 但「不是聊天」——① 不彈通知 ② ⛔絕不丟給 routePersonas（否則 AI 會對「群主把代理A移出群組」
  // 這種動作描述亂回、洗版）。仍 push 進 buffer + post 給 webview，讓 webview 端渲染成置中系統行
  // （並支援重開歷史回放）；webview 自己負責「不畫成氣泡、不計數」。
  // ⚠ 與上面的 react / label 早退分開判斷（react vs label vs sys 各一條），不互相覆蓋。
  if (isSysText(vm.text)) {
    glog(`appendFromServer:sys skip seq=${vm.seq} from="${vm.from}" (skip notify+route)`);
    return;
  }
  // [讀取回條] 讀取回條（text 以 `read:` sentinel 開頭）跟反應 / 標示 / 系統動作同理：走現有
  // E2E 管道，但「不是聊天」——⛔不彈通知、⛔不計未讀、⛔絕不丟給 routePersonas（否則 AI 會對
  // 「對方已讀到第 N 則」這種狀態亂回、洗版）。仍 push 進 buffer + post 給 webview，讓 webview 端
  // 聚合「誰已讀到第幾 seq」（並支援重開歷史回放重建已讀狀態）；webview 自己負責「不畫成氣泡、
  // 不計數、不觸發自己再送 read（防自我迴圈）」。⚠ 與 react / label / sys 各一條早退、互不覆蓋。
  if (isReadText(vm.text)) {
    // 解析「對方看到的最大 seq」純為了 log 好定位；真正的聚合在 webview 端做。
    let upto = '?';
    try { const o = JSON.parse(vm.text.slice(READ_PREFIX.length)); if (o && o.s != null) upto = String(o.s); } catch { /* 壞格式：log 用 ? */ }
    glog(`appendFromServer:read skip from="${vm.from}" upto=${upto} seq=${vm.seq} (skip notify+route)`);
    return;
  }
  if (!this.visible) { this.unread++; this.updateUnreadIcon(); }
  this.maybeNotify([vm]);
  // [1.9.11 真修] 路由 @ 訊息給 AI 成員。⛔ 不可用「from === 我就整個跳過」——那會讓
  // 「使用者自己 @ AI」永遠不路由（user 1.9.10 實測 @deepseek-v4-flash 完全沒反應、
  // routePersonas 零 log 的真兇）。「AI 不回自己的訊息」這個 anti-self-loop 已由
  // routePersonas 內 hits() 的 `msg.from !== member.id` 精準處理（只排除「發訊息的那位
  // 成員」、不排除人類使用者），故這裡一律路由、不再用 selfName 粗暴整批擋掉。
  void this.routePersonas([vm]);
}

private async loadInitialHistory(): Promise<void> {
  // This attempt supersedes any pending retry.
  if (this.historyRetryTimer) { clearTimeout(this.historyRetryTimer); this.historyRetryTimer = undefined; }
  if (!this.authority) {
    // connectAuthority() builds the client synchronously right after kicking
    // the first pull; a 'ready' that races ahead just retries momentarily.
    this.scheduleHistoryRetry();
    return;
  }
  // [never-blank] Seed from the LOCAL mirror first so the panel shows the last
  // known conversation INSTANTLY — even offline, before the server answers, or
  // if the server is unreachable (530). The server page below then replaces it
  // with the authoritative copy; if the server fails we KEEP this local seed
  // instead of blanking the conversation (mainstream chat behaviour).
  if (this.buffer.length === 0) {
    try {
      const local = this.authority.localHistory(20);
      if (local.length) {
        this.buffer = local.map((m) => this.norm(m as BridgeMessage));
        this.oldestSeq = this.buffer.length ? this.buffer[0].seq : 0;
        this.maxSeenSeq = this.buffer.reduce((a, m) => (typeof m.seq === 'number' && m.seq > a ? m.seq : a), this.maxSeenSeq);
        this.post({ type: 'reset', history: this.buffer, meta: this.meta() });
      }
    } catch { /* no mirror / disk error → fall through to the server pull */ }
  }
  try {
    const { messages, hasMore } = await this.authority.history(0, 20);
    this.buffer = messages.map((m) => this.norm(m as BridgeMessage));
    // Surface a token mismatch the moment history loads (don't wait for a live
    // message) — every history line would be garbled if the key is wrong.
    for (const vm of this.buffer) this.noteDecryptHealth(vm.text);
    this.oldestSeq = this.buffer.length ? this.buffer[0].seq : 0;
    // [1.9.17] 以歷史最大 seq 起算去重基準＝SSE 重播這些歷史不會被當新訊息再路由一次。
    this.maxSeenSeq = this.buffer.reduce((a, m) => (typeof m.seq === 'number' && m.seq > a ? m.seq : a), this.maxSeenSeq);
    this.hasMoreHistory = hasMore;
    this.historyLoaded = true;
    this.historyRetries = 0;
    this.post({ type: 'historyHealth', ok: true }); // clear any "stuck" banner
    this.post({ type: 'reset', history: this.buffer, meta: this.meta() });
  } catch {
    // Don't strand the panel on a stale/empty buffer: retry with backoff. The
    // SSE state frame ALSO re-kicks this while !historyLoaded, so the two paths
    // race to recover — whichever lands first wins, the other is a cheap no-op.
    this.scheduleHistoryRetry();
  }
}

private scheduleHistoryRetry(): void {
  if (this.historyLoaded) return; // already recovered via another path
  if (this.historyRetryTimer) return; // a retry is already pending
  if (this.historyRetries >= this.maxHistoryRetries) {
    this.post({ type: 'historyHealth', ok: false }); // make the failure visible
    return;
  }
  const attempt = this.historyRetries++;
  const delay = Math.min(400 * 2 ** attempt, 8000); // 400,800,1600,3200,6400,8000ms
  this.historyRetryTimer = setTimeout(() => {
    this.historyRetryTimer = undefined;
    void this.loadInitialHistory();
  }, delay);
}

private async loadMoreHistory(): Promise<void> {
  if (!this.authority || !this.hasMoreHistory || this.oldestSeq <= 0) {
    this.post({ type: 'historyPage', messages: [], hasMore: false, prepend: true });
    return;
  }
  try {
    const { messages, hasMore } = await this.authority.history(this.oldestSeq, 20);
    const older = messages.map((m) => this.norm(m as BridgeMessage));
    // Loop guard: an empty page with hasMore=true (server bug / race) would let
    // the webview keep firing loadMore against the SAME cursor forever. Force
    // hasMore=false when the page is empty so the cursor stalls instead of spins.
    if (!older.length) {
      this.hasMoreHistory = false;
      this.post({ type: 'historyPage', messages: [], hasMore: false, prepend: true });
      return;
    }
    // Sanity: prepended page must be STRICTLY older than what we already hold.
    // If the server returns a non-decreasing cursor (bug), drop it and stop
    // paging rather than corrupt ordering / loop on the same seq.
    const newestOlder = older[older.length - 1].seq;
    if (this.buffer.length && newestOlder >= this.buffer[0].seq) {
      this.hasMoreHistory = false;
      this.post({ type: 'historyPage', messages: [], hasMore: false, prepend: true });
      return;
    }
    this.buffer = [...older, ...this.buffer];
    this.oldestSeq = older[0].seq;
    // Enforce the same memory cap as the append path so repeated scroll-up
    // paging can't grow the buffer unbounded. Trim from the NEWEST end on the
    // in-memory model; the webview keeps the prepended nodes it just rendered.
    const max = this.maxRenderLines();
    if (this.buffer.length > max) {
      this.buffer = this.buffer.slice(0, max);
      this.oldestSeq = this.buffer.length ? this.buffer[0].seq : this.oldestSeq;
    }
    this.hasMoreHistory = hasMore;
    this.post({ type: 'historyPage', messages: older, hasMore, prepend: true });
  } catch {
    this.post({ type: 'historyPage', messages: [], hasMore: this.hasMoreHistory, prepend: true });
  }
}

dispose(): void {
  this.stopMemberHeartbeat(); // [1.9.16] 停 AI 成員代打心跳
  // Close the authority SSE stream → server sees the disconnect and drops my
  // presence (online-1 broadcast to the rest of the room).
  try { this.authority?.close(); } catch { /* */ }
  this.authority = undefined;
  try { this.langCfgListener?.dispose(); } catch { /* */ }
  this.langCfgListener = undefined;
  if (this.historyRetryTimer) { clearTimeout(this.historyRetryTimer); this.historyRetryTimer = undefined; }
  if (this.connectTimer) {
    clearTimeout(this.connectTimer);
    this.connectTimer = undefined;
  }
  // Legacy relay teardown (kept for transitional compat; authority mode does
  // not use the relay bridge, so this is a no-op when none was started).
  if (isOnlineRoom(this.channel)) {
    stopRelayBridge(this.channel);
  }
  BridgePanel.panels.delete(this.channel);
  // [1.8.0 §10.1] 面板關閉 → 背景訂閱恢復（房間若已被刪除，管理器自會移除追蹤）。
  groupPanelClosed(this.channel);
  this.panel.dispose();
}

private static resolveBridgeHome(): string {
  const cfg = vscode.workspace
    .getConfiguration('aiKing')
    .get<string>('bridgeChannelPath');
  if (cfg && cfg.trim()) {
    return cfg.trim();
  }
  if (process.env.BRIDGE_HOME) {
    return process.env.BRIDGE_HOME;
  }
  if (process.env.BRIDGE_DATA_DIR) {
    return process.env.BRIDGE_DATA_DIR;
  }
  return defaultBridgeHome();
}

private cliPath(): string {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  return cfg.get<string>('bridgeCliPath')?.trim() || 'bridge';
}

private userId(): string {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  return cfg.get<string>('bridgeUserId')?.trim() || 'user';
}

private selfName(): string {
  const id = readIdentity(this.channel);
  if (id && id.me && id.me.trim()) return id.me.trim();
  const cfg = readRelayConfig(this.channel);
  return (cfg && cfg.me && cfg.me.trim()) || this.userId();
}

private selfRole(): MemberRole {
  const id = readIdentity(this.channel);
  const base: MemberRole = id && id.role
    ? id.role
    : !isOnlineRoom(this.channel)
      ? 'owner'
      : (readRelayConfig(this.channel)?.role) || 'member';
  // [2026-06-18 必修C 紅藍] local 房 founder 恆 owner（無 peer）；online 房一律採信伺服器 roster——
  // 否則 sticky-owner 短路（base==='owner' 直接 return）會讓「原群主轉讓後本機仍判 owner」→ leave 永遠
  // 被擋＝轉讓後離不開（本批核心功能在原群主機器上失效）。authMembers 未載入時下方 fallback 回 base（連上
  // 前 founder 仍安全判 owner），載入後採信伺服器角色＝自我癒合。
  if (!isOnlineRoom(this.channel)) return base;
  const meId = this.selfName();
  // AUTHORITY MODE: role changes are broadcast by the server (member:update) into
  // authMembers, NOT written to the local channel.jsonl. Prefer the server roster
  // so a promotion to admin reflects in canManage() immediately — reading only the
  // local replay (which never sees the server event) would keep me at 'member' and
  // wrongly block my real admin actions.
  const fromServer = this.authMembers.find((m) => m.id === meId || m.name === meId);
  if (fromServer && (fromServer.role === 'owner' || fromServer.role === 'admin' || fromServer.role === 'member')) {
    return fromServer.role;
  }
  const replayed = replayMemberRoster(this.channel, readMembers(this.channel)).find(
    (m) => m.id === meId,
  );
  if (replayed && (replayed.role === 'admin' || replayed.role === 'member')) {
    return replayed.role;
  }
  return base;
}

private canManage(): boolean {
  const r = this.selfRole();
  return r === 'owner' || r === 'admin';
}

private softLimit(): number {
  return vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('bridgeSoftLimit', 400);
}

private maxRenderLines(): number {
  return vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('bridgeMaxRenderLines', 500);
}

private maxPersonaCallsPerMin(): number {
  const v = vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('bridgeMaxPersonaCallsPerMin', 12);
  return typeof v === 'number' && v >= 1 ? v : 12;
}

private ensureChannel(): void {
  try {
    fs.mkdirSync(path.dirname(this.channelPath), { recursive: true });
    if (!fs.existsSync(this.channelPath)) {
      fs.writeFileSync(this.channelPath, '', 'utf8');
    }
  } catch {
    /* surfaced lazily on first read/write */
  }
}

private setChannelPaths(name: string): void {
  this.channel = name;
  const chanDir = path.join(this.home, 'data', 'channels', name);
  this.channelPath = path.join(chanDir, 'channel.jsonl');
}

private notifyLevel(): 'all' | 'mention' | 'off' {
  const id = readIdentity(this.channel);
  if (id && (id.notifyLevel === 'all' || id.notifyLevel === 'mention' || id.notifyLevel === 'off')) {
    return id.notifyLevel;
  }
  const g = vscode.workspace
    .getConfiguration('aiKing')
    .get<string>('groupNotifyLevel', 'mention');
  return g === 'all' || g === 'off' ? g : 'mention';
}

private notifyThrottleMs(): number {
  const sec = vscode.workspace
    .getConfiguration('aiKing')
    .get<number>('groupNotifyThrottleSec', 8);
  return Math.max(0, sec) * 1000;
}

private notifyCatsKey(): string {
  return `aiKing.groupNotifyCats.${this.channel}`;
}

private notifyCats(): { master: boolean; loop: boolean; mention: boolean; all: boolean } {
  const raw = this.ctx.globalState.get<{ master?: boolean; loop?: boolean; mention?: boolean; all?: boolean }>(
    this.notifyCatsKey(),
  );
  return {
    master: raw?.master !== false, // 預設 on
    loop: raw?.loop !== false,
    mention: raw?.mention !== false,
    all: raw?.all !== false,
  };
}

private mutedMembersKey(): string {
  return `aiKing.groupMutedMembers.${this.channel}`;
}

private mutedMembers(): string[] {
  const raw = this.ctx.globalState.get<string[]>(this.mutedMembersKey());
  return Array.isArray(raw) ? raw : [];
}

private resolveMemberId(from: string): string {
  const m = this.authMembers.find((x) => x.id === from || x.name === from);
  return (m && m.id) || from;
}

private isMemberMuted(memberId: string): boolean {
  return this.mutedMembers().includes(memberId);
}

private async toggleMemberMute(memberId: string): Promise<boolean> {
  const list = this.mutedMembers();
  const idx = list.indexOf(memberId);
  let nowMuted: boolean;
  if (idx >= 0) {
    list.splice(idx, 1);
    nowMuted = false;
  } else {
    list.push(memberId);
    nowMuted = true;
  }
  await this.ctx.globalState.update(this.mutedMembersKey(), list);
  glog(`notify:mute ${nowMuted ? 'set' : 'clear'} member="${memberId}" room="${this.channel}"`);
  return nowMuted;
}

private mentionsMe(vm: ViewMessage): boolean {
  const me = this.selfName();
  if (!me) return false;
  // 1.8.0: @all / @所有人 broadcast-mentions everyone (own messages are
  // already filtered out by the notify caller).
  if (
    // [A3 廣播詞彙統一] @all/@everyone/@全部/@所有人 都是廣播全員，與 extractMentions 的
    // 展開集一致（修 mentionsMe/routePersonas 漏認 everyone/全部 的內部矛盾）。
    vm.mentions.some(
      (m) =>
        m.toLowerCase() === 'all' ||
        m.toLowerCase() === 'everyone' ||
        m === '全部' ||
        m === '所有人',
    ) ||
    /(^|\s)@(all|everyone|全部|所有人)(?=$|\s|[^\w-])/i.test(vm.text)
  ) {
    return true;
  }
  // [身分組 @] 角色點名通知到「擔任該身分的我」：@群主（含 @owner）且我是 owner → 通知；
  // @管理員（含 @admin）且我是 owner/admin → 通知（owner 也算管理員）。這解「群主 / 管理員
  // 被身分組 @ 卻沒收到通知」——以前只比字面名字，群主改名後 @群主 落空。
  const myRole = this.selfRole();
  if (textHasRoleMention(vm.text, 'owner') && myRole === 'owner') {
    glog(`maybeNotify:roleMention 群主→self (role=${myRole})`);
    return true;
  }
  if (textHasRoleMention(vm.text, 'admin') && (myRole === 'owner' || myRole === 'admin')) {
    glog(`maybeNotify:roleMention 管理員→self (role=${myRole})`);
    return true;
  }
  if (vm.mentions.includes(me)) return true;
  // [根治 2026-06-19] @id 或 @顯示名皆命中；用 \p{L}\p{N} 邊界認中文／含空格 id（原 [^\w-] 在中文邊界
  // 不穩、又只認 id）。word-boundary 仍防 '@user' 誤命中 '@username'。不支援 \p 的引擎退回 [^\w-]。
  const meMember = readMembers(this.channel).find((x) => x.id === me);
  const names = [me];
  if (meMember && meMember.name && meMember.name !== me) names.push(meMember.name);
  return names.some((n) => {
    const esc = n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    try {
      return new RegExp('(^|\\s)@' + esc + '(?![\\p{L}\\p{N}_])', 'u').test(vm.text);
    } catch {
      return new RegExp('(^|\\s)@' + esc + '(?=$|\\s|[^\\w-])').test(vm.text);
    }
  });
}

private maybeNotify(parsed: ViewMessage[]): void {
  const level = this.notifyLevel();
  if (level === 'off') return;
  const me = this.selfName();

  // [通知分類] 本機分類：主開關關 = 全靜音。一筆訊息屬「標註（@我）」或「所有」，
  // 該類本機被關 → 不通知。空轉（loop.suspect）走另一條事件路徑、不經 maybeNotify
  // （見 onAuthorityEvent 'loop.suspect'），這裡只分「標註 / 所有」兩類。
  const cats = this.notifyCats();
  if (!cats.master) {
    glog('maybeNotify:skip master=off');
    return;
  }

  // Eligible = a real chat message from someone else that this room's level
  // wants to hear about. (System lines / status frames never notify.)
  // 先過舊 notifyLevel 粗閘，再過本機分類 + 成員靜音細控（任一不過 = 不通知）。
  const eligible = parsed.filter((vm) => {
    if (vm.role === 'system' || vm.type !== 'msg') return false;
    if (!vm.text || !vm.text.trim()) return false;
    if (vm.from === me) return false; // never notify on my own messages
    if (level === 'mention' && !this.mentionsMe(vm)) return false; // 舊粗閘：僅@
    // [通知分類] 這筆屬哪類？@我（含身分組命中）→ 標註；否則 → 所有。
    const isMention = this.mentionsMe(vm);
    if (isMention && !cats.mention) {
      glog(`maybeNotify:skip cat=標註 off from="${vm.from}"`);
      return false;
    }
    if (!isMention && !cats.all) {
      glog(`maybeNotify:skip cat=所有 off from="${vm.from}"`);
      return false;
    }
    // [成員靜音] 發訊者被我本機靜音 → 不通知（@我 也照靜音，這是「我選擇不被這人吵」）。
    const fromId = this.resolveMemberId(vm.from);
    if (this.isMemberMuted(fromId)) {
      glog(`maybeNotify:skip muted from="${vm.from}" id="${fromId}"`);
      return false;
    }
    return true;
  });
  if (!eligible.length) return;

  const mentioned = eligible.filter((vm) => this.mentionsMe(vm));
  const hasMention = mentioned.length > 0;

  // "Don't ping while I'm reading this room" — but @我 overrides (being named
  // is important enough to surface even when the panel is focused).
  if (this.visible && !hasMention) return;

  // Throttle: coalesce a burst into one toast. @我 bypasses the throttle so a
  // direct mention is never silently swallowed by an earlier broad ping.
  // [通知 P1-b] 節流狀態存 globalState（per room）＝跨重開/多視窗持久共享（見欄位宣告處註解）。
  // @我 仍 bypass 節流（被點名不可被早前廣播吞掉）＝多視窗 @我 仍可能各彈一次＝「有界兜底」拍板範圍。
  const tkey = `aiKing.notify.groupThrottle.${this.channel}`;
  const tstate = this.ctx.globalState.get<{ at: number; sup: number }>(tkey) || { at: 0, sup: 0 };
  const now = Date.now();
  const within = now - tstate.at < this.notifyThrottleMs();
  if (within && !hasMention) {
    void this.ctx.globalState.update(tkey, { at: tstate.at, sup: tstate.sup + eligible.length });
    return;
  }

  // Pick the message to headline: the (last) mention if any, else the last.
  const lead = hasMention ? mentioned[mentioned.length - 1] : eligible[eligible.length - 1];
  const extra = eligible.length - 1 + tstate.sup;
  void this.ctx.globalState.update(tkey, { at: now, sup: 0 });

  const room = this.channel;
  const snippet = lead.text.replace(/\s+/g, ' ').trim().slice(0, 40);
  const mark = this.mentionsMe(lead) ? ' 提到你' : '';
  const tail = extra > 0 ? `（外加 ${extra} 則新訊息）` : '';
  const body = `AI 群組「${room}」：${lead.from}${mark}：${snippet}${tail}`;

  // [通知停留策略] 業界二分法：「需要動作」的通知（@我/被點名）不該自動消失。VS Code 的
  // info 通知約 15 秒滑進通知中心、且不開放 API 控制 timeout；warning 通知則永久停留直到
  // 使用者操作。故預設「分級」＝@我 → showWarningMessage（永久、帶 ⚠️ 圖示），一般新訊息 →
  // showInformationMessage（~15 秒自動消失、無圖示）。對齊 ChatGPT / NN-g「行動類永久、
  // 被動類自動消失」。可調：aiKing.groupNotifyPersist = tiered（預設）/ all（全永久）/ none（全消失）。
  const persistMode = vscode.workspace
    .getConfiguration('aiKing')
    .get<string>('groupNotifyPersist', 'tiered');
  const persist = persistMode === 'all' || (persistMode !== 'none' && hasMention);
  const pickP = persist
    ? vscode.window.showWarningMessage(body, '開啟')
    : vscode.window.showInformationMessage(body, '開啟');
  void pickP.then((pick) => {
    if (pick === '開啟') {
      void vscode.commands.executeCommand('aiKing.bridge.open', room);
    }
  });
}

private async maybeNotifyProfileIncomplete(): Promise<void> {
  if (
    vscode.workspace
      .getConfiguration('aiKing')
      .get<boolean>('notify.profileIncomplete', true) === false
  )
    return;
  if (!this.canManage()) return; // 只有能代設（setmeta）的 owner/admin 收到才有意義
  const key = `aiKing.notify.profileIncomplete.${this.channel}`;
  const notified = this.ctx.globalState.get<Record<string, boolean>>(key) || {};
  let changed = false;
  const incomplete: string[] = [];
  for (const m of this.authMembers) {
    if (!m || m.type === 'human') continue; // 只看 AI 成員（真人沒供應商/型號概念）
    const empty = !(m.backend || '').trim(); // backend 空＝沒設供應商:型號
    if (empty && !notified[m.id]) {
      incomplete.push(m.name || m.id);
      notified[m.id] = true;
      changed = true;
    } else if (!empty && notified[m.id]) {
      delete notified[m.id]; // 補了→清標、下次再缺再提醒
      changed = true;
    }
  }
  if (changed) await this.ctx.globalState.update(key, notified);
  if (!incomplete.length) return;
  const names =
    incomplete.slice(0, 3).join('、') +
    (incomplete.length > 3 ? ` 等 ${incomplete.length} 位` : '');
  const body = `AI 群組「${this.channel}」：成員 ${names} 還沒設供應商／型號，點頭像→個資卡可代設。`;
  const ok = await showSystemToast('AI King', body, this.ctx);
  if (!ok)
    void vscode.window.showInformationMessage(body, '開啟').then((p) => {
      if (p === '開啟') void vscode.commands.executeCommand('aiKing.bridge.open', this.channel);
    });
}

async pickNotifyLevel(): Promise<void> {
  const cur = this.notifyLevel();
  const mark = (l: string): string => (l === cur ? '  ✓ 目前' : '');
  const pick = await showQuickPickEsc(
    [
      { label: `🔔 全部${mark('all')}`, detail: '任何新訊息都通知', value: 'all' as const },
      { label: `@ 僅 @我${mark('mention')}`, detail: '只有被點名（@你）時才通知（預設）', value: 'mention' as const },
      { label: `🔕 關${mark('off')}`, detail: '這個群組完全不通知', value: 'off' as const },
    ],
    {
      placeHolder: `群組「${this.channel}」的通知層級（按 ESC 取消）`,
      ignoreFocusOut: true,
    },
  );
  if (!pick) return;
  setGroupNotifyLevel(this.channel, pick.value);
  const label = pick.value === 'all' ? '全部通知' : pick.value === 'mention' ? '僅 @我通知' : '已關閉通知';
  void vscode.window.showInformationMessage(`群組「${this.channel}」通知層級 → ${label}`);
}

async pickNotifyCats(): Promise<void> {
  const c = this.notifyCats();
  type Item = vscode.QuickPickItem & { cat: 'master' | 'loop' | 'mention' | 'all' };
  // [#2 去循環] 一次勾選要開的項目、Enter 一次套用，取代舊「點一項切一個、重開面板」的循環。
  // picked 預帶當前狀態；勾＝開、不勾＝關。主開關不勾＝全靜音（三類設定保留但不生效）。
  const items: Item[] = [
    {
      label: '所有通知（主開關）',
      detail: '取消勾選＝這個群組完全不通知（三類一起靜音）',
      cat: 'master',
      picked: c.master,
    },
    { label: '空轉', detail: '疑似空轉 / 死鎖提示（loop.suspect）', cat: 'loop', picked: c.loop },
    { label: '標註', detail: '有人 @ 我（含身分組 @群主 / @管理員 命中我）', cat: 'mention', picked: c.mention },
    { label: '所有', detail: '所有新訊息都通知', cat: 'all', picked: c.all },
  ];
  const picks = await showQuickPickEsc(items, {
    placeHolder: `群組「${this.channel}」通知分類 — 勾選要開的項目，Enter 一次套用（ESC 取消不變更）`,
    canPickMany: true,
    ignoreFocusOut: true,
  });
  if (!picks) return; // ESC：不變更
  const on = new Set(picks.map((p) => p.cat));
  const next = { master: on.has('master'), loop: on.has('loop'), mention: on.has('mention'), all: on.has('all') };
  await this.ctx.globalState.update(this.notifyCatsKey(), next);
  glog(`notify:settings apply master=${next.master} loop=${next.loop} mention=${next.mention} all=${next.all} room="${this.channel}"`);
  const summary = !next.master
    ? '全靜音（主開關關）'
    : [next.loop && '空轉', next.mention && '標註', next.all && '所有'].filter(Boolean).join(' / ') || '主開關開、三類全關';
  void vscode.window.showInformationMessage(`群組「${this.channel}」通知分類 → ${summary}`);
}

async pickDisplayFields(): Promise<void> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const cur = cfg.get<Record<string, boolean>>('display.groupFields') || {};
  type Item = vscode.QuickPickItem & { field: string };
  const defs: Array<[string, string]> = [
    ['bubble', '對話框（訊息氣泡背景/邊框）'],
    ['avatar', '頭貼'],
    ['name', '名稱'],
    ['agentIcon', 'Agent 種類圖示'],
    ['providerIcon', '供應商圖示'],
    ['modelIcon', '型號'],
    ['time', '時間'],
  ];
  const items: Item[] = defs.map(([field, label]) => ({
    label,
    field,
    picked: cur[field] !== false, // 預設全開
  }));
  const picks = await showQuickPickEsc(items, {
    placeHolder: `群組「${this.channel}」顯示欄位 — 勾選要顯示的，Enter 套用（ESC 取消；與對話分開設定）`,
    canPickMany: true,
    ignoreFocusOut: true,
  });
  if (!picks) return; // ESC：不變更
  const on = new Set(picks.map((p) => p.field));
  const next: Record<string, boolean> = {};
  for (const [field] of defs) next[field] = on.has(field);
  await cfg.update('display.groupFields', next, vscode.ConfigurationTarget.Global);
  this.post({ type: 'displayGroup', fields: next });
}

private pushPresence(): void {
  // Server-authoritative: presence = the live SSE set the server pushed. We
  // do NOT compute it from message activity any more. Drop "me" from the list
  // the topbar shows as agents (the user is implied), matching old behaviour.
  const me = this.selfName();
  const agents = this.authOnline
    .filter((o) => o.id !== me && o.name !== me)
    .map((o) => ({ id: o.id, framework: '', status: 'online' as const }));
  this.post({ type: 'presence', agents });
}

private pushMembers(): void {
  // Server-authoritative roster + presence. The webview is fed straight from
  // what the authority pushed (state/member events for the roster, presence
  // events for who's live) — NO local members.json read, NO event replay.
  // [身份同步 2026-06-16] 趁刷名冊順手把「私聊改過的身份」同步進名冊（節流 4 秒、
  // fire-and-forget 不擋顯示；member-update 成功會 broadcast → 下次 pushMembers 顯示新身份）。
  const nowMs = Date.now();
  if (nowMs - this.lastIdentitySync > 4000) {
    this.lastIdentitySync = nowMs;
    void this.syncBuiltinIdentitiesFromSessions();
  }
  const online = new Set<string>();
  for (const o of this.authOnline) { online.add(o.id); if (o.name) online.add(o.name); }
  const isOnline = (id: string, name: string): boolean =>
    online.has(id) || online.has(name);
  const list = this.authMembers.map((m) => {
    // [10.2] 伺服器算好的 lastSeen（新伺服器欄位；舊伺服器退回 roster 的 lastSeenAt，
    // 兩者皆無 → 0 = 未知）。online 維持既有算法：以伺服器最新 presence 推播為準
    // （onlineList 本來就含心跳寬限成員）——客戶端只顯示、不自己推導。
    const ext = m as Member & { lastSeen?: number };
    return {
      id: m.id,
      name: m.name,
      type: m.type,
      role: m.role || 'member',
      notifyLevel: m.notifyLevel || 'mention',
      architecture: m.architecture || '',
      backend: m.backend || '',
      // [1.9.25] 成員身份顯示層：Agent 種類 + 型號標籤（前端 bridge.js 訊息行/名冊用來決定
      // Agent Logo、hover 精準識別、型號文字）。顯示層需要、之前 pushMembers 漏帶＝顯示鏈斷點。
      // [身份追溯 2026-06-15] 舊成員（加 agentKind 邏輯前創的）缺欄位 → 從 architecture/type/backend
      // 推斷補上（顯示層精準、不改伺服器名冊；user「我創好的也要更新」）。內建三種 base/aiking/
      // psycheforge 推得出；外部 AI 推不出哪家、保持空（可 /profile 設）。
      agentKind: m.agentKind || this.inferAgentKind(m),
      modelLabel: m.modelLabel || this.inferModelLabel(m),
      // [1.9.3] 個資簡介：成員沒設定 → 顯示層用模型本身角色/特長當預設（AI 成員）或
      // 人類通用文案。只在 post 給 webview 時注入，不寫進 members.json（權威狀態不污染、
      // 不跨機同步別人 roster）。一進群組就有個資，符合 user 需求。
      bio: m.bio || defaultProfileForMember(m.backend, m.type),
      avatar: this.resolveAvatar(m.avatar),
      online: isOnline(m.id, m.name),
      lastSeen: typeof ext.lastSeen === 'number' ? ext.lastSeen
        : typeof m.lastSeenAt === 'number' ? m.lastSeenAt : 0,
      // [A2 P1] 別名表透傳：歷史 @舊名 → 當前成員「顯示」用（renderTextInto/memberFor）。伺服器
      //   閘門 AK_MENTION_ALIASES 開才有此欄、關＝undefined（JSON 自動省略）＝webview 別名邏輯 dormant。
      //   ⛔ 別名只走顯示、永不進 extractMentions/routePersonas/mentionsMe 喚醒路徑（防 bill-bomb）。
      ...(Array.isArray((m as { aliases?: string[] }).aliases)
        ? { aliases: (m as { aliases?: string[] }).aliases }
        : {}),
      // [成員靜音] 本機是否靜音此成員（個資卡 toggle 用；不跨機、不進名冊）。
      localMuted: this.isMemberMuted(m.id),
      // [評分] 公開（user 2026-06-15 directive）：三態計數＋能力等第推給所有人（每則訊息時間左邊＋
      // 個資卡顯示）。grade＝Trust §6 簡化版字母等第（A/B/C/D），樣本 0 不給等第（無資料不亂判）。
      // ⚠ 原設計黑箱是防 AI 報復/互捧；改公開後 AI 看得到彼此評分、理論上可操弄，後續出問題再加防線。
      ratingCounts: (() => {
        const c = countsForTarget(this.ctx, this.channel, m.id);
        return { up: c.up, ok: c.ok, down: c.down, total: c.total, grade: c.total > 0 ? trustGrade(trustFromCounts(c)) : '' };
      })(),
    };
  });
  // Always include "me" first so the roster is never empty even before the
  // server's first state frame lands — the user is a member of their own
  // group and is always online (the SSE stream is open while looking).
  const selfM = {
    id: this.selfName(), name: this.selfName(), type: 'human',
    role: this.selfRole(), notifyLevel: '', architecture: '', backend: '',
    agentKind: 'human', modelLabel: '', // [1.9.25] 自己＝人類；型號空（人類無型號、不顯示）
    bio: '', avatar: '', online: true, lastSeen: Date.now(),
    localMuted: false, // 不會靜音自己（自己的訊息本來就不通知）
  };
  this.post({
    type: 'members',
    members: [selfM, ...list.filter((m) => m.id !== selfM.id)],
    selfRole: this.selfRole(),
    selfName: this.selfName(),
    corrupt: false,
    // [10.2] 舊伺服器沒給 online 欄位 → false → 名字旁圓點整批不渲染（相容鐵律）。
    presenceKnown: this.serverPresenceV2,
  });
}

private async postProviderKeyStatus(): Promise<void> {
  try {
    const list = loadProviders();
    const keyed: string[] = [];
    for (const p of list) {
      if (p.authType === 'none') { keyed.push(p.id); continue; }
      const k = await getProviderKey(this.ctx, p.id);
      if (k && k.length > 0) keyed.push(p.id);
    }
    this.post({ type: 'providerKeys', keyed });
  } catch { /* 查金鑰失敗＝不標 ⚠ */ }
}

private async fetchProviderModels(providerId: string): Promise<void> {
  const NON_CHAT =
    /(embed|whisper|tts|audio|dall-e|moderation|realtime|transcri|batch|search|computer-use|ocr|rerank|guard|image|imagen)/i;
  const reply = (models: string[], detected: boolean) =>
    this.post({ type: 'provider:modelsFetched', provider: providerId, models, detected });
  try {
    const p = loadProviders().find((x) => x.id === providerId);
    if (!p) { reply([], false); return; }
    const curated = p.models || [];
    const keyless = p.authType === 'none';
    const apiKey = keyless ? '' : ((await getProviderKey(this.ctx, p.id)) || '');
    if (!keyless && !apiKey) { reply(curated, false); return; } // 沒金鑰 → 靜態
    const store = new ProviderStatusStore();
    const res = await store.probe(p, apiKey);
    store.dispose();
    const detected = (res.detectedModels || []).filter((m) => !NON_CHAT.test(m));
    if (!detected.length) { reply(curated, false); return; } // 端點無 /models → 靜態
    const extra = curated.filter((m) => detected.indexOf(m) === -1);
    reply(detected.slice().sort((a, b) => a.localeCompare(b)).concat(extra), true);
  } catch { reply([], false); }
}

private resolveAvatar(av?: string): string {
  if (!av) return '';
  if (av.startsWith('store:')) {
    const rel = av.slice('store:'.length);
    // [1.9.0 紅藍稽核 M9] 防路徑穿越（同 chat-panel）。
    if (rel.includes('..') || rel.startsWith('/') || rel.startsWith('\\') || /^[a-zA-Z]:/.test(rel)) {
      return '';
    }
    const uri = vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', rel);
    return this.panel.webview.asWebviewUri(uri).toString();
  }
  return av; // already a URL / data URI
}

private norm(m: BridgeMessage): ViewMessage {
  return {
    id: m.id || BridgePanel.genId(),
    seq: typeof m.seq === 'number' ? m.seq : 0,
    from: m.from || 'unknown',
    framework: m.framework || '',
    role: m.role || 'agent',
    type: m.type || 'msg',
    text: m.text || '',
    ts: typeof m.ts === 'number' ? m.ts : Date.now() / 1000,
    mentions: Array.isArray(m.mentions) ? m.mentions : [],
    pinned: !!m.pinned,
    replyTo: m.reply_to ?? null,
    senderKind: m.senderKind || '',
  };
}

private meta(): Record<string, unknown> {
  return {
    count: this.buffer.length,
    softLimit: this.softLimit(),
    channel: this.channelPath,
    channelName: this.roomDisplayName || this.channel,
    online: isOnlineRoom(this.channel),
    selfId: this.selfName(),
    selfRole: this.selfRole(),
    // Room lifecycle is now server-authoritative (room.dissolve event / state
    // frame), not a local state file.
    roomStatus: this.authStatus,
    hasMoreHistory: this.hasMoreHistory,
  };
}

private updateUnreadIcon(): void {
  const name = this.unread > 0 ? 'tab-crown-unread.svg' : 'tab-crown.svg';
  try {
    this.panel.iconPath = vscode.Uri.joinPath(this.extensionUri, 'media', 'icons', name);
  } catch { /* panel disposed — ignore */ }
}

private post(payload: Record<string, unknown>): void {
  void this.panel.webview.postMessage(payload);
}

private onMessage(
  msg: { type?: string; text?: string; room?: string; channel?: string; id?: string; name?: string },
): void {
  if (!msg || typeof msg !== 'object') {
    return;
  }
  if (msg.type === 'log:trace') {
    // [群組 C 可觀測 1.24.34] 群組 webview 的步驟 trace → 診斷頻道，標 webview:group:<tag>
    //   讓 user 在 log 一眼區分群組 vs 對話（chat）。原本群組端完全沒這管道＝「群組 C 沒有」。
    const m = msg as { tag?: string; data?: unknown };
    log.info(`webview:group:${m.tag || '?'}`, m.data);
    return;
  }
  if (msg.type === 'ready') {
    // [1.8.0 §13] language first so init renders in the right language.
    this.post({ type: 'i18n:lang', lang: uiLang() });
    this.post({
      type: 'init',
      selfId: this.selfName(),
      selfRole: this.selfRole(),
      history: this.buffer,
      meta: this.meta(),
      mediaUri: this.panel.webview
        .asWebviewUri(vscode.Uri.joinPath(this.extensionUri, 'media'))
        .toString(),
      // [b 2026-06-19] 供應商→模型 兩級選單目錄：個資卡先選供應商（Logo）→再選模型。
      // 從 loadProviders()（內建七家＋使用者自訂）組 {id,name,logo,models}，webview 端
      // 用它建級聯下拉＋顯示 Logo。隨 init 一次送（供應商清單一個 session 內穩定）。
      providers: providerCatalogForWebview(),
      // [統一母版 顯示欄位] 群組訊息行顯示開關（與對話 display.chatFields 分開設定）。
      displayGroup:
        vscode.workspace.getConfiguration('aiKing').get<Record<string, boolean>>('display.groupFields') || {},
    });
    this.pushPresence();
    this.pushMembers();
    // [b 2026-06-19] 非同步算「已設金鑰的供應商集」→ 個資卡供應商選單對未設金鑰的家標 ⚠
    // （對齊網站 ModelPicker keyedProviders）。secrets 讀取是 async，不阻塞 init。
    void this.postProviderKeyStatus();
    // Server is the source of truth; a stale buffer at 'ready' is replaced as
    // soon as the SSE state frame + initial history land. Kick a fresh pull.
    void this.loadInitialHistory();
    return;
  }
  if (msg.type === 'loadMore') {
    void this.loadMoreHistory();
    return;
  }
  if (msg.type === 'rejoinInvite') {
    // [1.8.0 §10.3-2] footer「重新索取邀請碼」動作鈕：重用既有「貼邀請碼加入」流程
    // （joinFromInvite 會覆寫房間鑰匙＋伺服器位址，並對已開面板強制重連）。
    void BridgePanel.joinFromInvite(this.ctx);
    return;
  }
  if (msg.type === 'member:add') {
    void this.addMember();
    return;
  }
  if (msg.type === 'member:remove') {
    if (!this.canManage()) {
      void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能移除成員。');
      return;
    }
    if (typeof msg.id === 'string') {
      const id = msg.id;
      if (id === this.selfName()) {
        void vscode.window.showWarningMessage('AI 群組：要移除自己請用 ⋮ →「離開群組」。');
        return;
      }
      // Server-authoritative: authority.kick(id) removes the roster entry AND
      // kicks that member's live connection (presence -1); the broadcast
      // member:remove (reason='kicked') updates everyone via onAuthorityEvent.
      // kick (not leave) so the server can never be coaxed into self-removal and
      // the broadcast carries the right reason. Owner/admin gated server-side.
      void this.authority?.kick(id);
      // [系統動作] GUI 移出成員成功 → 額外送一則「誰 把 誰 移出群組」置中系統訊息（用顯示名）。
      void this.sendSystemMessage('kick', this.displayNameOf(id));
      void vscode.window.showInformationMessage(`AI 群組：已移除成員「${id}」。`);
    }
    return;
  }
  if (msg.type === 'member:avatar' && typeof msg.id === 'string') {
    void this.uploadAvatar(msg.id);
    return;
  }
  if (msg.type === 'avatar:crop:done' && typeof msg.id === 'string') {
    // [1.9.3] 群組成員圓形裁切器回傳烤好的 webp → 落檔。dataUri 不在 msg union，cast。
    const dataUri = (msg as { dataUri?: unknown }).dataUri;
    if (typeof dataUri === 'string') void this.saveCroppedMemberAvatar(msg.id, dataUri);
    return;
  }
  if (msg.type === 'member:inherit' && typeof msg.id === 'string') {
    void this.copyInheritCode(msg.id);
    return;
  }
  if (msg.type === 'member:mute' && typeof msg.id === 'string') {
    void this.muteMemberWithPick(msg.id);
    return;
  }
  if (msg.type === 'member:unmute' && typeof msg.id === 'string') {
    // [2026-06-14] 補 host 端 gate（與對稱的 member:mute 一致）。舊版直接送伺服器，
    // 非權限者只會收到伺服器轉回的英文「not allowed」403，違反「無權限要出白話警告」。
    if (!this.canManage()) {
      void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能解除禁言。');
      return;
    }
    const id = msg.id;
    void (async () => {
      const r = await this.authority?.unmute(id);
      if (r && typeof r.error === 'string') void vscode.window.showWarningMessage(`AI 群組：解除禁言失敗 — ${r.error}`);
      else void vscode.window.showInformationMessage(`已解除「${id}」的禁言。`);
    })();
    return;
  }
  if (msg.type === 'member:role' && typeof msg.id === 'string') {
    if (this.selfRole() !== 'owner') {
      void vscode.window.showWarningMessage('AI 群組：只有群主能指派 / 取消管理員。');
      return;
    }
    // Roster is server-authoritative; the server exposes no member-attribute
    // update, so apply optimistically to the pushed cache + persist locally
    // (transitional) so the change shows immediately.
    const m = this.authMembers.find((x) => x.id === msg.id);
    if (m) {
      const next: MemberRole = m.role === 'admin' ? 'member' : 'admin';
      // Server-authoritative: broadcast member:update re-renders for everyone.
      void this.authority?.memberUpdate(m.id, { role: next });
      // [系統動作] GUI 設 / 降管理員成功 → 額外送一則置中系統訊息（extra=next：'admin'=設、'member'=降）。
      void this.sendSystemMessage('role', m.name || m.id, next);
      void vscode.window.showInformationMessage(
        next === 'admin' ? `已把「${m.name}」設為管理員。` : `已取消「${m.name}」的管理員。`,
      );
    }
    return;
  }
  if (msg.type === 'member:transferOwner' && typeof msg.id === 'string') {
    // [2026-06-18 user 權限細分] 成員卡/列選單「轉讓群主」入口（owner 對真人成員）。確認+送出走 transferOwnerTo。
    const m = this.authMembers.find((x) => x.id === msg.id);
    void this.transferOwnerTo(msg.id, m?.name || msg.id);
    return;
  }
  if (msg.type === 'member:notify' && typeof msg.id === 'string') {
    if (!this.canManage()) {
      void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能改成員的通知設定。');
      return;
    }
    const order = NOTIFY_LEVELS_CYCLE;
    const m = this.authMembers.find((x) => x.id === msg.id);
    if (m) {
      // [#2 去循環] 個資卡下拉會帶目標值 level → 一次選定；沒帶 level 的舊呼叫端 → 退回原循環。
      const wanted = (msg as { level?: unknown }).level;
      const cur = m.notifyLevel || 'mention';
      let next: string;
      if (typeof wanted === 'string' && order.includes(wanted)) {
        next = wanted;
      } else {
        const idx = order.indexOf(cur);
        next = order[(idx < 0 ? 1 : idx + 1) % order.length]; // unset → 'mention' base
      }
      if (next === cur) return; // 下拉選了同一個 → 沒變化、不廣播
      void this.authority?.memberUpdate(m.id, { notifyLevel: next });
      const label = next === 'all' ? '全部通知' : next === 'mention' ? '僅 @ 通知' : '僅人類發話通知';
      void vscode.window.showInformationMessage(`「${m.name}」通知設定 → ${label}`);
    }
    return;
  }
  if (msg.type === 'member:bio' && typeof msg.id === 'string') {
    void this.editMemberBio(msg.id);
    return;
  }
  if (msg.type === 'member:rename' && typeof msg.id === 'string' && typeof msg.name === 'string') {
    void this.renameMember(msg.id, msg.name);
    return;
  }
  if (msg.type === 'member:setModel' && typeof msg.id === 'string') {
    const mm = msg as { label?: unknown; provider?: unknown; model?: unknown };
    // [b 2026-06-19] 兩級選單：provider + model 一起送 → 同時寫 backend(provider:model)
    // ＋modelLabel(model)，供應商與模型都持久＋跨機（authority.mjs member-update 同一分支
    // 已支援兩欄、不碰 server）。
    if (typeof mm.provider === 'string' && typeof mm.model === 'string') {
      void this.setMemberProviderModel(msg.id, mm.provider, mm.model);
      return;
    }
    // 純文字自填（無供應商概念）→ 只改顯示型號 modelLabel（沿用舊行為）。
    if (typeof mm.label === 'string') {
      void this.setMemberModelLabel(msg.id, mm.label);
      return;
    }
  }
  if (msg.type === 'provider:fetchModels' && typeof (msg as { provider?: unknown }).provider === 'string') {
    void this.fetchProviderModels((msg as { provider: string }).provider);
    return;
  }
  if (msg.type === 'member:setBio' && typeof msg.id === 'string') {
    const bio = (msg as { bio?: unknown }).bio;
    if (typeof bio === 'string') {
      void this.setMemberBioOnly(msg.id, bio);
      return;
    }
  }
  if (msg.type === 'group:cmd') {
    // [1.9.3] 群組聊天室 slash 指令（成員/管理員權限 + 個資操作）。webview 已先用白名單
    // 攔截 / 開頭、確認是已註冊指令才送來，所以正常聊天的 / 文字不會被吃。
    const raw = (msg as { raw?: unknown }).raw;
    if (typeof raw === 'string') void this.handleGroupCommand(raw);
    return;
  }
  if (msg.type === 'member:chat' && typeof msg.id === 'string') {
    const m = this.authMembers.find((x) => x.id === msg.id)
      || readMembers(this.channel).find((x) => x.id === msg.id);
    if (!m) {
      void vscode.window.showWarningMessage('AI 群組：找不到這位成員。');
      return;
    }
    void this.openAgentChat(m);
    return;
  }
  if (msg.type === 'room:disband') {
    void this.disbandWithConfirm();
    return;
  }
  if (msg.type === 'room:transferOwnerPick') {
    // [2026-06-18 user 防呆按鈕層] 抽屜「轉讓群主」按鈕（群主才顯示）→ QuickPick 選真人成員轉讓。
    void this.transferOwnerWithPick();
    return;
  }
  if (msg.type === 'room:leave') {
    void this.leaveWithConfirm();
    return;
  }
  if (msg.type === 'room:cleanupStale') {
    void this.staleMemberMenu();
    return;
  }
  if (msg.type === 'room:rename') {
    void this.renameGroupWithPrompt();
    return;
  }
  if (msg.type === 'msg:delete') {
    const seq = (msg as { seq?: number }).seq;
    if (typeof seq === 'number' && seq) void this.deleteMessageOnAuthority(seq);
    return;
  }
  if (msg.type === 'room:notify-level') {
    void this.pickNotifyLevel();
    return;
  }
  if (msg.type === 'room:notify-cats') {
    // [通知分類] 群組面板「通知分類」入口 → 開本機分類設定（主開關 + 三類 toggle）。
    void this.pickNotifyCats();
    return;
  }
  if (msg.type === 'room:display-fields') {
    // [統一母版 顯示欄位] 群組面板「顯示欄位」入口 → 開勾選面板（與對話分開）。
    void this.pickDisplayFields();
    return;
  }
  if (msg.type === 'member:localMute' && typeof msg.id === 'string') {
    // [成員靜音] 個資卡 toggle：切換「我本機是否被這個成員的訊息通知」。純本機。
    const id = msg.id;
    void (async () => {
      const nowMuted = await this.toggleMemberMute(id);
      const name = this.displayNameOf(id) || id;
      void vscode.window.showInformationMessage(
        nowMuted ? `已靜音「${name}」的通知（只有你這台、不影響別人）。`
          : `已取消靜音「${name}」的通知。`,
      );
      // 重推名冊，讓個資卡 / 成員列即時反映新的 localMuted 狀態。
      this.pushMembers();
    })();
    return;
  }
  if (msg.type === 'refresh') {
    // Re-pull the newest page from the authority (server is the source of
    // truth; there is no local file to re-tail).
    void this.loadInitialHistory();
    return;
  }
  if (msg.type === 'clear') {
    if (!this.canManage()) {
      void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能清空對話。');
      return;
    }
    void (async () => {
      const ok = await vscode.window.showWarningMessage(
        `確定清空「${this.channel}」的所有對話歷史？會清掉伺服器上的歷史、所有人都看不到（成員與設定保留）。`,
        { modal: true }, '清空',
      );
      if (ok !== '清空') return;
      await this.authority?.clear();
      void vscode.window.showInformationMessage('AI 群組：已清空對話歷史。');
    })();
    return;
  }
  // [評分] 舊「對單則訊息按表情(react)」已移除（user 2026-06-15）：webview 不再送 type:'react'。
  // host 收到伺服器廣播的歷史 react: 訊息仍由 appendFromServer 攔住（不通知、不路由 AI）。
  // [讀取回條] webview 端「群組面板真正取得焦點且可見、且看到的最大 seq 增加」→ 送來
  // { type:'read', text:'read:{"s":<最大 seq>}' }。完全沿用既有 send 路徑（authority.send →
  // E2E 加密 → 伺服器派 seq 並廣播回來），伺服器看到的只是一則密文、不必改動。廣播回來時
  // appendFromServer 會以 read: 前綴辨識並早退（不通知、不路由 AI、不計未讀），webview 端聚合
  // 「誰已讀到第幾 seq」。debounce 在 webview 端做（焦點/新訊息節流）；防自我迴圈也在 webview 端
  // （收到 read 不會再觸發送 read）。這裡只是純轉送（跟 react 一致），不額外做狀態。
  if (msg.type === 'read' && typeof msg.text === 'string' && isReadText(msg.text)) {
    if (this.authStatus === 'dissolved') return; // 已解散：唯讀，不再發任何訊息（含回條）
    if (!this.authority) return; // 未連上權威伺服器：靜默忽略（送了也會被丟，跟 send/react 一致）
    let upto = '?';
    try { const o = JSON.parse(msg.text.slice(READ_PREFIX.length)); if (o && o.s != null) upto = String(o.s); } catch { /* 壞格式：log 用 ? */ }
    glog(`read:send upto=${upto} (focused)`);
    // [1.9.26] signalKind:'read' tells the server this is a PURELY TRANSIENT receipt
    // → broadcast live but NEVER persist to channel.jsonl. Stops `read:{"s":N}` from
    // leaking into history (where an old build with no read: interception would draw
    // it as a chat bubble — the「群主看到自己 read 氣泡」bug).
    this.authority.send(this.selfName(), msg.text, '', 'read').then((r) => {
      if (r && typeof r.error === 'string') glog(`read:send:err err=${r.error}`);
    }).catch((e: unknown) => {
      glog(`read:send:throw err=${e instanceof Error ? e.message : String(e)}`);
    });
    return;
  }
  if (msg.type === 'send' && msg.text && msg.text.trim()) {
    if (this.authStatus === 'dissolved') {
      void vscode.window.showWarningMessage(
        'AI 群組：群主已解散此群組，歷史可讀、無法再發言。請從 ⋮ →「離開群組」移除你這份副本。',
      );
      return;
    }
    const text = msg.text.trim();
    if (!this.authority) {
      // connectAuthority() bailed (e.g. empty room token → no E2E key). Sending
      // would be silently dropped; tell the user the real reason instead.
      void vscode.window.showWarningMessage(
        'AI 群組：尚未連上權威伺服器（房間鑰匙或伺服器位址有問題），訊息未送出。',
      );
      return;
    }
    // E2E: AuthorityClient.send encrypts BEFORE the message leaves this machine.
    // No local append/echo — the server assigns a seq and broadcasts the `msg`
    // event back to us (and everyone), which we render via onAuthorityEvent.
    this.authority.send(this.selfName(), text).then((r) => {
      // httpJson resolves even on a non-2xx (e.g. 409 room dissolved, 403 not
      // authenticated) — the body carries { error }. A silently-dropped send is
      // worse than a visible failure, so surface a server-reported error here.
      if (r && typeof r.error === 'string') {
        const e = r.error;
        const msgText = e === 'room dissolved'
          ? 'AI 群組：群主已解散此群組，訊息未送出。'
          : e === 'from must match authenticated id' || e === 'not authenticated'
            ? 'AI 群組：身分驗證失敗（連線尚未就緒），請稍候重連後再送。訊息未送出。'
            : `AI 群組：訊息送出失敗 — ${e}`;
        void vscode.window.showWarningMessage(msgText);
      }
    }).catch((e: unknown) => {
      // Surface the concrete failure (network / encryption / server) instead of
      // a one-size-fits-all "伺服器未連上" that hides E2E / auth problems.
      const detail = e instanceof Error ? e.message : String(e);
      void vscode.window.showWarningMessage(
        `AI 群組：訊息送出失敗 — ${detail}`,
      );
    });
  }
}

private extractMentions(text: string): string[] {
  // [根治 2026-06-19] 成員 id/name 可含中文與空格（如「數位人格 架構」）。原 /@[\w-]+/ 的 \w 不認
  // 中文、遇空格即斷 → 中文/空格成員（含離線）永遠抽不到 → 不被 tag（通知）。改成：先用「完整名冊
  // id＋name（含離線）貪婪比對最長者」，匹配不到才退回 @[\w-]+（英文 slug 相容）。name 命中轉成員
  // id 存（mentionsMe 比對的是 id）。
  const members = readMembers(this.channel);
  const known: string[] = [];
  for (const mm of members) {
    if (mm.id) known.push(mm.id);
    if (mm.name && mm.name !== mm.id) known.push(mm.name);
  }
  known.push('all', 'everyone', '全部', '所有人', '群主', '管理員', 'owner', 'admin');
  known.sort((a, b) => b.length - a.length); // 長者優先：避免「@數位」先吃掉「@數位人格 架構」
  const out: string[] = [];
  const pushId = (hit: string) => {
    const mem = members.find((x) => x.id === hit || x.name === hit);
    const id = mem ? mem.id : hit;
    if (!out.includes(id)) out.push(id);
  };
  let i = 0;
  while (i < text.length) {
    if (text[i] !== '@') { i++; continue; }
    if (i > 0 && !/\s/.test(text[i - 1])) { i++; continue; } // @ 前須行首或空白（避免 email 誤判）
    const rest = text.slice(i + 1);
    let hit: string | null = null;
    for (const k of known) { if (k && rest.indexOf(k) === 0) { hit = k; break; } }
    if (!hit) { const mm = /^[\w-]+/.exec(rest); if (mm) hit = mm[0]; }
    if (!hit) { i++; continue; }
    pushId(hit);
    i += 1 + hit.length;
  }
  // @all / @everyone / @全部 / @所有人 → expand to every room member (group broadcast).
  const wantsAll =
    out.includes('all') || out.includes('everyone') ||
    text.indexOf('@全部') >= 0 || text.indexOf('@所有人') >= 0;
  if (wantsAll) {
    for (const mm of members) { if (!out.includes(mm.id)) out.push(mm.id); }
  }
  return out;
}

private personaRateTake(memberId: string): boolean {
  const now = Date.now();
  const prev = (this.personaReplyTimes.get(memberId) || []).filter(
    (t) => now - t < 60_000,
  );
  if (prev.length >= this.maxPersonaCallsPerMin()) {
    this.personaReplyTimes.set(memberId, prev);
    return false;
  }
  prev.push(now);
  this.personaReplyTimes.set(memberId, prev);
  return true;
}

private async routePersonas(messages: ViewMessage[]): Promise<void> {
  // Cheap pre-filter: if NO message in the batch contains an '@' at all,
  // nobody is being addressed — skip all roster reads / per-member scans.
  // Keeps the "idle = 0 cost" promise on the local persona path.
  if (!messages.some((m) => typeof m.text === 'string' && m.text.includes('@'))) {
    return;
  }
  // Roster is server-authoritative (authMembers); never re-read members.json.
  const all = this.authMembers;
  const personas = all.filter((m) => m.type === 'cloud-persona');
  const agents = all.filter(
    (m) => m.architecture === 'aiking' || m.architecture === 'hermes',
  );
  // [1.6.0] 「基礎 (Agent)」內建成員 — 由擴充自己用 provider API 直接驅動回覆
  // （不經 Sancio venv）。這是 user「本地跑不動、第一版用 API」的基礎 Agent runtime。
  const baseAgents = all.filter((m) => m.architecture === 'clean');
  // ACP 成員（架構 acp）— AI King 當 ACP client 起動本機外部代理（Claude/Gemini/Hermes）驅動回覆。
  const acpAgents = all.filter((m) => m.architecture === 'acp');
  // [1.9.10 觀測性] 群組 AI 不回應的 runtime bug：先看名冊到底帶不帶 architecture/backend
  //（伺服器來回若被剝掉，baseAgents 就會是空 → 永不呼叫 callBaseAgent → 靜默不回）。
  // 每位成員印 id:architecture，一眼看出 base agent 有沒有被正確識別。
  glog(
    `routePersonas: msgs=${messages.length} roster=[${all
      .map((m) => `${m.id}:${m.architecture || '-'}${m.backend ? '(be)' : ''}`)
      .join(' ')}] base=${baseAgents.length} persona=${personas.length} agent=${agents.length}`,
  );
  if (!personas.length && !agents.length && !baseAgents.length) return;
  for (const msg of messages) {
    if (msg.role === 'system' || msg.type !== 'msg') continue;
    if (!msg.text || !msg.text.trim()) continue;
    // ANTI-ABUSE: never trust relay-supplied msg.mentions for the expensive
    // decision to call a cloud API. A peer can forge mentions:['costly-ai']
    // with no '@' in the text to bill-bomb. Re-derive mentions LOCALLY from
    // the message text; the relay's mentions[] is reference only — log a
    // mismatch but act solely on what we parse here.
    const localMentions = this.extractMentions(msg.text);
    if (
      msg.mentions.length &&
      msg.mentions.some((mm) => !localMentions.includes(mm))
    ) {
      // eslint-disable-next-line no-console
      console.warn(
        `[ai-king] routePersonas: relay mentions ${JSON.stringify(msg.mentions)} ` +
          `disagree with locally-parsed ${JSON.stringify(localMentions)} (from=${msg.from}); ` +
          `acting on local parse only.`,
      );
    }
    // 1.8.0: @all / @所有人 → every AI member counts as mentioned. Locally
    // parsed from text only (same anti-abuse rule as named mentions — the
    // relay's mentions[] can't bill-bomb us into waking every persona).
    // [A3 廣播詞彙統一] 與 extractMentions / mentionsMe 同集：all/everyone/全部/所有人。
    const mentionAll = /(^|\s)@(all|everyone|全部|所有人)(?=$|\s|[^\w-])/i.test(msg.text);
    // [身分組 @] 角色點名：`@群主`/`@owner` → 解析到「擔任 owner 的成員」；
    // `@管理員`/`@admin` → owner + admin 都算（owner 也是管理者）。比文字 id 可靠：
    // 群主改了名字（不再叫「群主」）後 `@群主` 照樣命中，因為我們比的是 member.role 而非名字。
    const mentionOwnerRole = textHasRoleMention(msg.text, 'owner');
    const mentionAdminRole = textHasRoleMention(msg.text, 'admin');
    // Match @id OR @displayName (users naturally @ the visible name, which can
    // differ from the id), with a word boundary so '@bot' doesn't fire '@bot2'.
    const mentioned = (m: Member): boolean => {
      if (mentionAll) return true;
      // 身分組命中：擔任該角色的「AI 成員」也被路由回應（@群主 命中 owner；
      // @管理員 命中 owner+admin）——讓「正好是群主/管理員的那位 AI」會被叫到。
      if (mentionOwnerRole && m.role === 'owner') {
        glog(`routePersonas:roleHit role=owner member=${m.id}`);
        return true;
      }
      if (mentionAdminRole && (m.role === 'owner' || m.role === 'admin')) {
        glog(`routePersonas:roleHit role=admin member=${m.id}(${m.role})`);
        return true;
      }
      for (const cand of [m.id, m.name]) {
        if (!cand) continue;
        if (localMentions.includes(cand)) return true;
        const esc = cand.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        if (new RegExp('(^|\\s)@' + esc + '(?=$|\\s|[^\\w-])').test(msg.text)) return true;
      }
      return false;
    };
    const hits = (member: Member): boolean => msg.from !== member.id && mentioned(member);
    // [1.9.10 觀測性] 每則訊息印「有沒有 @、命中了哪些 base agent」——區分「沒 @ 到」
    // （mentionAll/regex 沒命中）vs「@ 到了但沒呼叫」（後面 callBaseAgent 內部出事）。
    const baseHit = baseAgents.filter((m) => hits(m)).map((m) => m.id);
    glog(
      `routePersonas:msg from="${msg.from}" hasAt=${msg.text.includes('@')} all=${mentionAll} baseHit=[${baseHit.join(',')}]`,
    );
    for (const member of personas) if (hits(member)) void this.callPersona(member, msg);
    for (const member of agents) if (hits(member)) void this.callAIKingAgent(member, msg);
    for (const member of baseAgents) if (hits(member)) void this.callBaseAgent(member, msg);
    for (const member of acpAgents) if (hits(member)) void this.callAcpAgent(member, msg);
  }
}

private async callAIKingAgent(member: Member, src: ViewMessage): Promise<void> {
  if (this.personaInflight.has(member.id)) return;
  // Cap hit → skip SILENTLY. The old per-message toast fired once per hit, so an
  // @all across a message batch turned the cost guard into a notification storm.
  if (!this.personaRateTake(member.id)) return;
  this.personaInflight.add(member.id);
  try {
    const ok = await ensureSancioRunning();
    if (!ok) {
      void vscode.window.showWarningMessage(
        'AI King Agent：本機 Sancio 起不來（需後端 venv 就緒），無法回覆。',
      );
      return;
    }
    // SSRF guard: the AI King Agent always talks to the LOCAL Sancio server.
    // Validate the base before sending the API key + conversation so a hostile
    // config / env can't redirect the request (parity with callPersona).
    const sancioBase = sancioBaseUrl();
    try {
      assertSancioEndpointAllowed(sancioBase);
    } catch (err) {
      void vscode.window.showWarningMessage(
        `AI King Agent：Sancio 端點未通過安全檢查，已中止 — ${err instanceof Error ? err.message : String(err)}`,
      );
      return;
    }
    const model = member.backend || 'anthropic:claude-opus-4-7';
    // Provider prefix may be slash- or colon-delimited; only pull a stored key
    // for KNOWN provider prefixes — never for an arbitrary relay-supplied slug.
    const providerId = model.split(/[:/]/)[0].trim();
    let apiKey = '';
    if (KNOWN_PROVIDER_PREFIXES.includes(providerId)) {
      try { apiKey = (await getProviderKey(this.ctx, providerId)) || ''; } catch { /* none */ }
    } else {
      // eslint-disable-next-line no-console
      console.warn(
        `[ai-king] callAIKingAgent: unknown provider prefix "${providerId}" ` +
          `(member=${member.id}); refusing to forward any API key.`,
      );
    }
    const providerExtra: Record<string, string> = {};
    if (apiKey) providerExtra.api_key = apiKey;
    const body = JSON.stringify({
      stack: 'sancio',
      model,
      messages: [{ role: 'user', content: src.text }],
      provider_extra: providerExtra,
    });
    const resp = await fetch(`${sancioBase}/v1/agent/run`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
    });
    if (!resp.ok) {
      void vscode.window.showWarningMessage(`AI King Agent：/v1/agent/run ${resp.status}`);
      return;
    }
    const raw = await resp.text();
    let answer = '';
    for (const block of raw.split('\n\n')) {
      const ev = /event: (.+)/.exec(block);
      const dm = /data: (.+)/.exec(block);
      if (!dm) continue;
      const type = ev ? ev[1].trim() : '';
      try {
        const f = JSON.parse(dm[1]) as { text?: string; content?: string; delta?: string };
        if (type === 'token') answer += f.text || f.content || f.delta || '';
      } catch { /* skip non-JSON frame */ }
    }
    answer = answer.trim();
    if (answer) {
      this.postAs(member.id, answer, src.seq);
    }
  } catch (e: unknown) {
    void vscode.window.showWarningMessage(
      `AI King Agent 呼叫失敗 — ${e instanceof Error ? e.message : String(e)}`,
    );
  } finally {
    this.personaInflight.delete(member.id);
  }
}

private memberSessionKey(memberId: string): string {
  return `aiKing.groupMemberSession.${this.channel}.${memberId}`;
}

private linkedSessionId(memberId: string): string | undefined {
  return this.ctx.globalState.get<string>(this.memberSessionKey(memberId));
}

private async setLinkedSession(memberId: string, sessionId: string): Promise<void> {
  await this.ctx.globalState.update(this.memberSessionKey(memberId), sessionId);
}

private async syncBuiltinIdentitiesFromSessions(): Promise<void> {
  if (this.identitySyncInflight || !this.authority) return;
  this.identitySyncInflight = true;
  try {
    const store = sessionStoreFor(this.ctx);
    for (const m of this.authMembers) {
      if (m.type === 'human') continue;
      const sid = this.linkedSessionId(m.id);
      if (!sid) continue; // 外部 AI 無私聊連結 → 身份是邀請時設的、不由本機 session 驅動
      let sess;
      try { sess = await store.load(sid); } catch { continue; }
      if (!sess) continue;
      const stack = sess.stack || 'clean';
      const model = sess.model || '';
      const providerId = sess.providerId || '';
      const agentKind = agentKindForStack(stack);
      const architecture = stack === 'sancio' ? 'aiking' : stack === 'clean' ? 'clean' : '';
      const backend = providerId && model ? `${providerId}:${model}` : '';
      // 只送「算得出且與名冊不同」的欄位（空值不覆蓋既有，避免清掉好資料）。
      const patch: Record<string, string> = {};
      if (agentKind && m.agentKind !== agentKind) patch.agentKind = agentKind;
      if (model && m.modelLabel !== model) patch.modelLabel = model;
      if (backend && m.backend !== backend) patch.backend = backend;
      if (architecture && m.architecture !== architecture) patch.architecture = architecture;
      // [1.24.21 A14] bio 也反推同步進群組（對話端改簡介 → 群組成員卡跟著改、雙向母版）。
      if (sess.aiBio && m.bio !== sess.aiBio) patch.bio = sess.aiBio;
      if (Object.keys(patch).length === 0) continue;
      try {
        const res = await this.authority.memberUpdate(m.id, patch);
        // 非 owner 的別台會收到 403/not allowed＝正常（身份由 owner 端私聊驅動），靜默略過。
        if (res && typeof res.error === 'string') glog(`identity-sync:skip id="${m.id}" err=${res.error}`);
        else glog(`identity-sync:ok id="${m.id}" patch=${JSON.stringify(patch)}`);
      } catch (e: any) {
        glog(`identity-sync:throw id="${m.id}" err=${e?.message || String(e)}`);
      }
    }
  } finally {
    this.identitySyncInflight = false;
  }
}

private async callBaseAgent(member: Member, src: ViewMessage): Promise<void> {
  // [內建AI永不斷線 2026-06-18] 改薄 wrapper：組「面板 deps」呼共用 driveBaseAgentCore。
  // 面板與背景（group-connections）呼同一 core ＝杜絕邏輯漂移（紅隊 mustFix）。
  // 防重入/限頻已搬進 core 的全域 Map（key=room+memberId），面板與背景共用同一份。
  const grpCfg = vscode.workspace.getConfiguration('aiKing');
  const groupToolsOn = grpCfg.get<boolean>('group.baseAgentTools.enabled') === true;
  const confirmReadOnly = grpCfg.get<boolean>('group.baseAgentTools.confirmReadOnly') !== false;
  const maxToolIters = (() => {
    const n = grpCfg.get<number>('group.baseAgentTools.maxToolIters');
    return typeof n === 'number' && n >= 1 && n <= 50 ? Math.floor(n) : 8;
  })();
  const ctxN = grpCfg.get<number>('group.aiContextMessages');
  const histCount = typeof ctxN === 'number' ? ctxN : 30;
  const channelName = this.channel;
  const memberLabel = member.name || member.id;
  const fromLabel = src.from;
  const ctxRef = this.ctx;
  await driveBaseAgentCore({
    ctx: this.ctx,
    room: this.channel,
    member,
    src,
    buffer: this.buffer,
    sessionStore: sessionStoreFor(this.ctx),
    linkedSessionId: (id) => this.linkedSessionId(id),
    authoritySend: (id, text, replyTo) => this.postAs(id, text, replyTo),
    maxCallsPerMin: this.maxPersonaCallsPerMin(),
    contextMessages: histCount,
    toolsEnabled: groupToolsOn,
    toolGate: groupToolsOn
      ? async (tool: string, args: Record<string, unknown>): Promise<boolean> => {
          const isMutating = tool === 'run_bash' || tool === 'write_file';
          const forcePrompt = isMutating || confirmReadOnly;
          const allowed = await askPermissionAllowed(ctxRef, {
            tool,
            args,
            context: `群組「${channelName}」成員「${memberLabel}」要在你本機跑工具（發起：${fromLabel}）`,
            forcePrompt,
          });
          glog(`callBaseAgent:toolgate id="${member.id}" tool="${tool}" force=${forcePrompt} allowed=${allowed}`);
          return allowed;
        }
      : undefined,
    maxToolIters,
    announceNoTools: false,
    glog,
    warn: (msg: string) => void vscode.window.showWarningMessage(msg),
    onAnswered: (fromId: string, memberId: string) => void this.autoRateInteraction(fromId, memberId),
  });
}

private async callAcpAgent(member: Member, src: ViewMessage): Promise<void> {
  if (this.personaInflight.has(member.id)) return;
  if (!this.personaRateTake(member.id)) return;
  this.personaInflight.add(member.id);
  try {
    const agentId = (member.backend && member.backend.trim()) || 'claude';
    const sel = resolveAcpLaunch(agentId);
    if (!sel) {
      glog(`callAcpAgent:noconfig id="${member.id}" agent="${agentId}"`);
      this.postAs(
        member.id,
        `（我是「${agentId}」ACP 代理，但還沒設定啟動指令。請在設定 aiKing.acpAgents.${agentId} 填好，或開「AI King: ACP 使用引導」。）`,
        src.seq,
      );
      return;
    }
    const preamble =
      `你是 AI 群組「${this.channel}」的成員「${member.name || member.id}」。多人協作群組，發言規則最重要：\n` +
      '只在被 @你 點名時回應、**最多 1～3 句精煉結論**、別把思考過程或長推理貼進群組、別重複別人說過的、用繁體中文、直接不客套。深入討論留到私聊。\n\n' +
      '以下是群組訊息：\n';
    const promptText = `${preamble}${src.from}：${src.text}`;
    glog(`callAcpAgent:prompt id="${member.id}" agent="${agentId}"`);
    const answer = await promptAcpOnce(member.id, sel.launch, promptText);
    glog(`callAcpAgent:answer id="${member.id}" len=${answer ? answer.length : 0}`);
    if (answer && answer.trim()) {
      this.postAs(member.id, answer.trim(), src.seq);
      void this.autoRateInteraction(src.from, member.id);
    }
  } catch (e) {
    glog(`callAcpAgent:fail id="${member.id}": ${e instanceof Error ? e.message : String(e)}`);
  } finally {
    this.personaInflight.delete(member.id);
  }
}

private async resolveBaseAgentBackend(
  member: Member,
): Promise<{ provider: Provider | undefined; model: string; apiKey: string }> {
  return resolveBaseAgentBackendCore(this.ctx, member);
}

private async callPersona(member: Member, src: ViewMessage): Promise<void> {
  if (this.personaInflight.has(member.id)) return; // one call at a time
  // Cap hit → skip SILENTLY (see callAIKingAgent: avoid the per-message toast storm).
  if (!this.personaRateTake(member.id)) return;
  this.personaInflight.add(member.id);
  try {
    const token = await this.ctx.secrets.get('aiKing.digitalHumanToken');
    if (!token) {
      void vscode.window.showWarningMessage(
        'AI 群組：數位人格 token 未設定 — 執行命令「AI King: Set Digital Human Bearer Token」。',
      );
      return;
    }
    const config = vscode.workspace.getConfiguration('aiKing');
    const stackEndpoints =
      config.get<Record<string, string>>('stackEndpoints') || {};
    // SSRF / token-exfil guard: the persona endpoint comes ONLY from trusted
    // workspace config — NEVER from member.endpoint, which is relay-synced and
    // a hostile peer could point at their own host to harvest the Bearer
    // token. (Previously member.endpoint took priority — that was the hole.)
    const endpoint =
      stackEndpoints['digital-human'] ||
      config.get<string>('sancioEndpoint') ||
      'https://psycheforge.app';
    assertSancioEndpointAllowed(endpoint); // SSRF guard (BUILTIN_ALLOW)
    const chatPath =
      config.get<string>('digitalHumanChatPath') || '/api/console/chat';
    const trial = config.get<boolean>('digitalHumanTrial') || false;
    const base = endpoint.replace(/\/+$/, '');
    const url = `${base}${chatPath.startsWith('/') ? chatPath : '/' + chatPath}`;
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json, text/event-stream',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        characterName: member.persona || member.id,
        message: src.text,
        userId: this.userId(),
        trial,
      }),
    });
    if (!resp.ok) {
      const body = await resp.text().catch(() => '');
      void vscode.window.showWarningMessage(
        `AI 群組：人格 ${member.name} API ${resp.status} — ${body.slice(0, 120)}`,
      );
      return;
    }
    const data = (await resp.json()) as {
      ok?: boolean;
      answer?: string;
      reply?: string;
    };
    if (data.ok === false) return;
    const answer = (data.answer || data.reply || '').toString().trim();
    if (!answer) return;
    this.postAs(member.id, answer, src.seq);
  } catch (e: unknown) {
    void vscode.window.showWarningMessage(
      `AI 群組：人格呼叫失敗 — ${e instanceof Error ? e.message : String(e)}`,
    );
  } finally {
    this.personaInflight.delete(member.id);
  }
}

private postAs(memberId: string, text: string, replyTo: number): void {
  // [1.9.12] 不再靜默吞錯——以前 `.catch(()=>{})` 把伺服器的 403「from must match
  // authenticated id」整個吃掉，導致 AI 明明回了話卻貼不出來、查不到原因（user 實測
  // callBaseAgent:answer len=21 卻沒回話的真兇）。現在 ok/err 都 log。
  // [訊息層去重 2026-06-16] 帶 replyTo＝觸發訊息 seq（呼叫端傳 src.seq）→ 伺服器對 (此 AI, 觸發)
  // 去重，防多開視窗各驅動同一內建 AI 對同一個 @ 雙回。
  this.authority?.send(memberId, text, 'ai', '', replyTo).then((r) => {
    if (r && typeof r.error === 'string') {
      glog(`postAs:err id="${memberId}" err=${r.error}`);
    } else if (r && r.deduped) {
      glog(`postAs:deduped id="${memberId}" replyTo=${replyTo}（重複回應被伺服器擋下＝防雙回生效）`);
    } else {
      glog(`postAs:ok id="${memberId}" len=${text.length}`);
    }
  }).catch((e: unknown) => {
    glog(`postAs:throw id="${memberId}" err=${e instanceof Error ? e.message : String(e)}`);
  });
}

private icon(slug: string): vscode.Uri {
  return vscode.Uri.joinPath(this.extensionUri, 'media', 'icons', `${slug}.svg`);
}

private async addMember(): Promise<void> {
  glog(`addMember:enter room="${this.channel}" role=${this.selfRole()}`);
  if (this.authStatus === 'dissolved') {
    glog('addMember:deny dissolved');
    void vscode.window.showWarningMessage('AI 群組：群主已解散此群組，無法再加入成員。');
    return;
  }
  if (!this.canManage()) {
    glog(`addMember:deny notManager role=${this.selfRole()}`);
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能加成員。');
    return;
  }
  const online = isOnlineRoom(this.channel);
  // [v1.9.24 防呆] 伺服器類型決定「邀請外部（人類/跨機 AI）」能不能做。
  // local=只本機 / lan=只同區網 / public=任何人。先 glog 留痕，再依此標灰/提示選項。
  const serverType = this.roomServerType();
  glog(`addMember:gate serverType=${serverType} online=${online}`);

  // 第一層：人類 / AI
  // 「人類」＝必然走跨機線上邀請：本機/區網伺服器都連不到外面的真人 → 把選項標清楚（不直接消失，
  // 列出但加「（本機群組不適用）」說明，選了給白話提示而非靜默失敗），公開房才真的開放。
  const humanUsable = serverType === 'public';
  const humanLabel = humanUsable ? '人類' : '人類（本機群組不適用）';
  const humanDetail = humanUsable
    ? '邀一個真人進來。產生線上連線碼給對方，對方在自己的 AI King 按「加入群組」貼上即同步'
    : serverType === 'lan'
      ? '⚠ 這是區網群組，連線碼只在同一個區域網路內有效——外網的真人連不進來。要邀外面的人請先把群組搬到公開伺服器'
      : '⚠ 這是本機群組（只在這台電腦），無法邀別台電腦的真人。要邀真人請先把群組搬到公開伺服器';
  const top = await showQuickPickEsc(
    [
      { label: humanLabel, iconPath: this.icon('human'), detail: humanDetail, key: 'human', usable: humanUsable },
      { label: 'AI', iconPath: this.icon('ai'), detail: 'AI King 內建的 Agent（不用邀請詞），或別人提供的外部 AI（邀請詞＋Skill）', key: 'ai', usable: true },
    ],
    { placeHolder: `要加什麼成員到「${this.channel}」？（按 ESC 取消）`, ignoreFocusOut: true },
  );
  if (!top) return;
  glog(`addMember:pick top=${top.key} usable=${top.usable}`);

  if (top.key === 'human') {
    // 防呆：非公開房選了「人類」→ 不執行（避免產生一張外面連不到的死連線碼），給白話原因。
    if (!humanUsable) {
      glog(`addMember:human:blocked serverType=${serverType} (非公開房不能邀真人)`);
      this.warnServerTypeBlocked(serverType, '邀真人（跨機器的真人）');
      return;
    }
    await this.inviteToRoom('online');
    return;
  }

  // 第二層（紅藍重構 2026-06-14 wf_a71d7765）：用「動作」命名取代會誤導的「內建/本地端口/外」。
  // 機制只兩類——擴充自驅(免邀請碼) vs 外部自連(邀請碼+Skill)；地點(本機/區網/外網)跟著房自動走、不進選單。
  // [v1.9.24 防呆] 「邀請外部 AI」的可達範圍跟著 serverType 走：
  //   public → 任何地方的 AI 都連得到（含跨機/別人的）；
  //   lan    → 只同一個區網的 AI 連得到（外網連不到，標警示但仍可用——同機 Claude Code CLI 合法）；
  //   local  → 只「同一台電腦」的 AI（如本機 Claude Code CLI）連得到，跨機 AI 必失敗 → 列出但標
  //            「（本機群組不適用跨機）」並在文案講清楚，選了仍會走 inviteExternalAi（同機 CLI 是合法用途），
  //            但 inviteExternalAi 的成功提示已說明「只有同機連得到」。
  let externalLabel: string;
  let externalDetail: string;
  if (serverType === 'public') {
    externalLabel = '邀請外部 AI 連進來（任何地方·連公開伺服器）';
    externalDetail = '別台電腦／別人的 AI，或同機的 Claude Code CLI——都連這個公開群組的伺服器（一群組一伺服器，不會分裂）。產生邀請詞（含 Skill 下載網址）貼給它';
  } else if (serverType === 'lan') {
    externalLabel = '邀請區網 AI 連進來（僅限同一區網）';
    externalDetail = '⚠ 這是區網群組：只有「同一個區域網路」內的 AI（同機 Claude Code CLI 或區網別台的 AI）連得到——外網的 AI 連不進來。要邀外地／別人的 AI，請先把群組搬到公開伺服器';
  } else {
    externalLabel = '邀請本機 AI 連進來（僅限同一台電腦）';
    externalDetail = '⚠ 這是本機群組：只有「同一台電腦」的 AI（如你的 Claude Code CLI）連得到——別台電腦／別人的 AI 連不進來。要邀跨機 AI，請先把群組搬到公開伺服器';
  }
  const aiKind = await showQuickPickEsc(
    [
      { label: '讓 AI King 建一個 AI（免邀請詞）', iconPath: this.icon('builtin'), detail: 'Base／AI King Agent／PsycheForge，或從左側「對話」挑現有 AI。AI King 自己驅動、會先測它能不能回，確定能跑才建立', key: 'builtin' },
      { label: externalLabel, iconPath: this.icon('external'), detail: externalDetail, key: 'external' },
    ],
    { placeHolder: `加哪種 AI 到「${this.channel}」？（按 ESC 取消）`, ignoreFocusOut: true },
  );
  if (!aiKind) return;

  if (aiKind.key === 'external') {
    // [2026-06-18 ③ docs §五步驟4 同名偵測導向繼承] 群組已有「離線的 AI 成員」時，最可能 user 其實是想讓
    // 那個斷線的 AI 接回(複製繼承詞、用既有 id re-bind、省 token、不重複身分)、而非新建一個。偵測到 → 先彈
    // 「讓它接回 vs 真的新建」，⛔預設導向繼承但永遠保留「真的新建」出口(防紅隊誤導把 token 塞給錯的人)。
    // switch aiKing.invite.guardDuplicateMember 預設 true、可關。
    const dupGuard = vscode.workspace.getConfiguration('aiKing').get<boolean>('invite.guardDuplicateMember', true);
    if (dupGuard) {
      const onlineIds = new Set(this.authOnline.map((o) => o.id));
      const offlineAis = this.authMembers.filter(
        (m) => m.type !== 'human' && m.id !== this.selfName() && !onlineIds.has(m.id),
      );
      if (offlineAis.length) {
        const choice = await showQuickPickEsc(
          [
            { label: '♻ 讓現有的離線 AI 接回（複製繼承詞、省 token）', detail: `群組已有 ${offlineAis.length} 個離線 AI；多半是它斷線了想讓它回來——複製繼承詞貼到新對話即以同一身分接回，不必重建、不浪費 token`, key: 'inherit' },
            { label: '✚ 真的新建一個 AI', detail: '確定要加一個全新的 AI（不是讓現有的離線 AI 接回）', key: 'new' },
          ],
          { placeHolder: `偵測到群組已有 ${offlineAis.length} 個離線 AI——你是想讓它接回，還是新建一個？（按 ESC 取消）`, ignoreFocusOut: true },
        );
        if (!choice) return;
        if (choice.key === 'inherit') {
          const pickAi = offlineAis.length === 1
            ? offlineAis[0]
            : await showQuickPickEsc(
                offlineAis.map((m) => ({ label: m.name || m.id, description: m.id, id: m.id })),
                { placeHolder: '要讓哪個離線 AI 接回？（複製它的繼承詞）', ignoreFocusOut: true },
              );
          if (!pickAi) return;
          await this.copyInheritCode(pickAi.id);
          return;
        }
        // choice.key === 'new' → 落下去走原本的 inviteExternalAi（新建）
      }
    }
    // 統一自適應邀請：buildJoinGuide 依房型自動判同機(本機路徑)/跨機(下載)。
    // 本機房 → 同機 AI 指引（如本機 Claude Code CLI）；線上房 → 跨機下載指引 + token 機密警告。
    // serverType 已傳進 inviteExternalAi 讓它的成功提示講對「能連的範圍」。
    glog(`addMember:external serverType=${serverType}`);
    await this.inviteExternalAi(serverType);
    return;
  }

  // ── AI King 內建 ── 第三層：從對話找 / 新創
  const builtinKind = await showQuickPickEsc(
    [
      { label: '從「對話」找一個', iconPath: this.icon('conv'), detail: '把你左側對話列表裡的某個 AI（用它的 Agent ＋ 模型）加進群組', key: 'from-conversation' },
      { label: '新創一個', iconPath: this.icon('new'), detail: '命名 → 選 Agent → 設後端 → 測會回，確定能跑才建立', key: 'new' },
    ],
    { placeHolder: 'AI King 內建 — 怎麼加？（按 ESC 取消）', ignoreFocusOut: true },
  );
  if (!builtinKind) return;

  if (builtinKind.key === 'from-conversation') {
    await this.addBuiltinFromConversation();
    return;
  }
  await this.addBuiltinNew();
}

private warnNeedsOnline(action: string): void {
  void vscode.window.showWarningMessage(
    `AI 群組：「${this.channel}」是本機群組（只在這台電腦），不能${action}。` +
      '請改建一個「線上群組」，或把現有對話搬到線上群組。',
  );
}

private warnServerTypeBlocked(serverType: 'local' | 'lan' | 'public', action: string): void {
  const where =
    serverType === 'local'
      ? `「${this.channel}」是本機群組（伺服器跑在這台電腦的 127.0.0.1，只有這台電腦上的 AI 能加入）`
      : `「${this.channel}」是區網群組（伺服器在內網 LAN，只有同一個區域網路內連得到）`;
  void vscode.window.showWarningMessage(
    `AI 群組：${where}，無法${action}。要邀請別人／跨機器的 AI，請先把群組搬到「公開伺服器」` +
      '（齒輪 → 伺服器設定，選一個 https 的公開位址），那時任何人都連得到。',
  );
}

private async addBuiltinNew(): Promise<void> {
  const agentPick = await showQuickPickEsc(
    STACKS.map((s) => ({
      label: s.label,
      detail: s.description,
      id: s.id,
      iconPath: this.icon(s.id === 'clean' ? 'base' : s.id === 'sancio' ? 'aiking' : s.id.startsWith('acp') ? 'base' : 'psyche'),
    })),
    { placeHolder: '這個內建 AI 用哪個 Agent？（按 ESC 取消）', ignoreFocusOut: true, matchOnDetail: true },
  );
  if (!agentPick) return;
  const stack = agentPick.id;

  const used = new Set(this.authMembers.map((m) => m.id));
  const uniqName = (base: string): string => {
    const b = (base || 'ai').replace(/[\\/:*?"<>|]/g, '').trim() || 'ai';
    if (!used.has(b)) return b;
    let i = 2; while (used.has(`${b}-${i}`)) i++; return `${b}-${i}`;
  };

  // 先選 LLM（列現有清單，不打字；也讓命名能用模型名當選項）
  // [2026-06-14 user] 只列連得上、有金鑰的 model，不留空 fallback 到沒設好的 active provider
  // （那正是「留空新創→測會回失敗→連視窗都沒開」的根因）。
  let backend = '';
  let modelName = '';
  if (stack === 'clean' || stack === 'sancio') {
    const statusStore = new ProviderStatusStore();
    const models = await vscode.window.withProgress(
      { location: vscode.ProgressLocation.Notification, title: '偵測可用的 LLM…', cancellable: false },
      () => getAvailableModels({ ctx: this.ctx, store: statusStore }),
    );
    statusStore.dispose();
    const chat = models.filter((m) => m.kind === 'chat');
    if (!chat.length) {
      void vscode.window.showWarningMessage(
        '找不到任何「連得上、有金鑰」的 LLM。請先到 AI King 設定加一個有效的 LLM 後端（填 API 金鑰）再來新創。',
      );
      return;
    }
    const mPick = await showQuickPickEsc(
      chat.map((m) => ({ label: m.display, detail: m.providerName, m })),
      { placeHolder: '這個 AI 用哪個 LLM？（只列連得上的，按 ESC 取消）', ignoreFocusOut: true, matchOnDetail: true },
    );
    if (!mPick) return;
    backend = `${mPick.m.providerId}:${mPick.m.model}`;
    modelName = mPick.m.model;
  }
  if (stack === 'acp') {
    // 外部代理（ACP）成員：次級選哪家（與側欄共用同一顆）→ backend 存代理 id（claude/gemini/hermes/自訂）。
    const acpId = await pickAcpAgentInteractive();
    if (!acpId) return; // 取消／走了新增精靈 → 不建成員
    backend = acpId;
  }

  // 命名：給選項（用模型名／自動取名／自訂打字），不只能打字（user 2026-06-14 UX）
  const CUSTOM = '�custom';
  const nameOpts: Array<{ label: string; value: string }> = [];
  if (modelName) nameOpts.push({ label: `用模型名：${uniqName(modelName)}`, value: uniqName(modelName) });
  nameOpts.push({ label: `自動取名：${uniqName(nextAgentName(this.channel))}`, value: uniqName(nextAgentName(this.channel)) });
  nameOpts.push({ label: '自訂（手動輸入）…', value: CUSTOM });
  const namePick = await showQuickPickEsc(nameOpts, {
    placeHolder: '這個 AI 在群組裡叫什麼名字？（按 ESC 取消）', ignoreFocusOut: true,
  });
  if (!namePick) return;
  let id = namePick.value;
  if (id === CUSTOM) {
    const id0 = await showInputBoxEsc({
      prompt: '輸入名字（按 ESC 取消）',
      placeHolder: '例如 畫師小P / 助手1',
      value: uniqName(modelName || nextAgentName(this.channel)),
      ignoreFocusOut: true,
      validateInput: (v) => {
        const t = (v || '').trim();
        if (!t) return '請輸入名字';
        if (used.has(t)) return `「${t}」已是成員，請取個不同的名字`;
        return null;
      },
    });
    if (!id0 || !id0.trim()) return;
    id = id0.trim();
  }

  const probe = await vscode.window.withProgress(
    { location: vscode.ProgressLocation.Notification, title: `測試「${id}」能不能回應…`, cancellable: false },
    () => this.probeAgentReplies(stack, backend, id),
  );
  if (!probe.ok) {
    void vscode.window.showWarningMessage(`無法建立「${id}」：測會回沒過 — ${probe.detail}`);
    return;
  }

  const memberOk = await this.createBuiltinMember(id, stack, backend);
  if (!memberOk) return; // 名冊沒寫成（authority 未連／回錯，registerMemberOnAuthority 已報錯）→ 別假裝成功開對話視窗
  // [2026-06-14 user] 新創內建 AI 同時「誕生」一個對話視窗：左側對話列表多一個、並直接開啟，
  // 以後能單獨跟它聊、不只活在群組裡。用同名/同 Agent/同後端（解析 backend 的 provider:model）。
  let convOpened = false;
  try {
    const store = sessionStoreFor(this.ctx);
    let providerId: string | undefined;
    let model: string | undefined;
    if (backend) {
      const i = backend.indexOf(':');
      if (i > 0) { providerId = backend.slice(0, i); model = backend.slice(i + 1); }
      else { model = backend; }
    }
    const sess = await store.create(id, model, stack, undefined, providerId);
    await this.setLinkedSession(id, sess.id); // [1.9.14] 連結＝統一記憶：群組成員與此私聊同一本記憶
    await vscode.commands.executeCommand('aiKing.chat.openSession', sess.id);
    convOpened = true;
  } catch (e) {
    glog(`addBuiltinNew:conv:fail id="${id}": ${e instanceof Error ? e.message : String(e)}`);
  }
  void vscode.window.showInformationMessage(
    convOpened
      ? `已建立內建 AI「${id}」（${agentPick.label}）＋它的對話視窗（左側多一個，可單獨聊）。群組裡用 @${id} 叫它。`
      : `已建立內建 AI「${id}」（${agentPick.label}）。測會回通過，用 @${id} 跟它說話。`,
  );
}

private async addBuiltinFromConversation(): Promise<void> {
  const store = sessionStoreFor(this.ctx);
  const allSessions = await store.list();
  if (!allSessions.length) {
    void vscode.window.showInformationMessage(
      '左側「對話」目前沒有任何 AI 對話可挑。先在對話分頁跟某個 Agent 聊一下，再回來加。',
    );
    return;
  }
  // [2026-06-15 user] 避免重複邀請：一個對話的 AI 只能進群組一次。排除「已被本群組某成員連結」的
  // 對話（含用「新創一個 AI」連帶建+連結的那個）→ 選單只剩還沒進來過的。
  const linkedIds = new Set(
    this.authMembers.map((m) => this.linkedSessionId(m.id)).filter((x): x is string => !!x),
  );
  const sessions = allSessions.filter((s) => !linkedIds.has(s.id));
  if (!sessions.length) {
    void vscode.window.showInformationMessage(
      '現有對話的 AI 都已經在這個群組裡了（沒有可加的）。要加新的請用「新創一個 AI」。',
    );
    return;
  }
  const toItem = (s: SessionSummary) => {
    const stackLabel = STACKS.find((x) => x.id === s.stack)?.label || s.stack || 'clean';
    return {
      label: s.title || '(未命名對話)',
      detail: `${stackLabel} · ${s.model || '預設模型'} · ${s.messageCount} 則`,
      s,
    };
  };
  const pick = await showQuickPickEsc(sessions.map(toItem), {
    placeHolder: '挑一個對話的 AI 加進群組（按 ESC 取消）',
    ignoreFocusOut: true,
    matchOnDetail: true,
  });
  if (!pick) return;
  const s = pick.s;
  const stack = s.stack || 'clean';
  const backend = s.providerId ? `${s.providerId}:${s.model}` : s.model || '';

  const used = new Set(this.authMembers.map((m) => m.id));
  // [2026-06-14] slice 上限 12→40：原本 12 把 `deepseek-v4-flash`(17) 切成 `deepseek-v4-`
  // （第 12 字剛好是 `-`、`flash` 被砍）＝user 實測的「名字被截斷沒尾字」。40 夠長不切斷
  // 正常模型名、仍有界（這只是預設值，使用者仍可在輸入框改）。
  let defName = (s.title || 'ai').replace(/\s+/g, '').slice(0, 40) || 'ai';
  if (used.has(defName)) { let i = 2; while (used.has(`${defName}-${i}`)) i++; defName = `${defName}-${i}`; }
  const id0 = await showInputBoxEsc({
    prompt: '這個 AI 在群組裡的名字（按 ESC 取消）',
    value: defName,
    ignoreFocusOut: true,
    validateInput: (v) => {
      const t = (v || '').trim();
      if (!t) return '請輸入名字';
      if (used.has(t)) return `「${t}」已是成員，請取個不同的名字`;
      return null;
    },
  });
  if (!id0 || !id0.trim()) return;
  const id = id0.trim();

  const probe = await vscode.window.withProgress(
    { location: vscode.ProgressLocation.Notification, title: `測試「${id}」能不能回應…`, cancellable: false },
    () => this.probeAgentReplies(stack, backend, id),
  );
  if (!probe.ok) {
    void vscode.window.showWarningMessage(`無法建立「${id}」：測會回沒過 — ${probe.detail}`);
    return;
  }

  const memberOk = await this.createBuiltinMember(id, stack, backend);
  if (!memberOk) return; // 名冊沒寫成→別假裝成功（registerMemberOnAuthority 已報錯）
  await this.setLinkedSession(id, s.id); // [1.9.14] 連結到挑的這個對話＝統一記憶（群組與私聊同一本）
  void vscode.window.showInformationMessage(`已把對話 AI「${id}」加入群組（跟它的私聊共用記憶）。用 @${id} 跟它說話。`);
}

private async probeAgentReplies(
  stack: string,
  backend: string,
  name: string,
): Promise<{ ok: boolean; detail: string }> {
  const testMsg = '（系統測試）你好，請用一句話回覆，確認你能正常運作。';
  try {
    if (stack === 'clean') {
      const { provider, model, apiKey } = await this.resolveBaseAgentBackend({ backend } as Member);
      if (!provider) return { ok: false, detail: '找不到可用 provider，請先到設定加一個 LLM 後端' };
      const ans = await runBaseAgentOnce({
        provider, apiKey, model,
        systemPrompt: `你是 AI 群組成員「${name}」。`,
        userMessage: testMsg, maxTokens: 64, timeoutMs: 30_000,
      });
      return ans
        ? { ok: true, detail: ans.slice(0, 40) }
        : { ok: false, detail: '後端沒有回覆內容（可能 API key 無效或模型不可用）' };
    }
    if (stack === 'sancio') {
      const up = await ensureSancioRunning();
      return up
        ? { ok: true, detail: 'AI King Agent 後端已就緒' }
        : { ok: false, detail: '本機 AI King Agent 後端（Sancio）起不來，需後端 venv 就緒' };
    }
    if (stack === 'digital-human') {
      return {
        ok: false,
        detail: 'PsycheForge（數位人格）stack 真連接尚在開發，暫時無法新創數位人格成員。請改用「基礎」Agent，或到 PsycheForge app 建角色',
      };
    }
    if (stack === 'acp') {
      const agentId = (backend && backend.trim()) || 'claude';
      const sel = resolveAcpLaunch(agentId);
      return sel
        ? { ok: true, detail: `ACP 代理「${agentId}」啟動指令已設定` }
        : { ok: false, detail: `尚未設定 ACP 代理「${agentId}」啟動指令（aiKing.acpAgents.${agentId}）。Claude 內建可跑；Gemini/Hermes 請先填、看「ACP 使用引導」` };
    }
    return { ok: false, detail: `未知 Agent：${stack}` };
  } catch (e) {
    return { ok: false, detail: e instanceof Error ? e.message : String(e) };
  }
}

private inferAgentKind(m: Member): string {
  if (m.type === 'cloud-persona') return 'psycheforge';
  if (m.architecture === 'aiking') return 'aiking';
  if (m.architecture === 'clean') return 'base';
  return '';
}

private inferModelLabel(m: Member): string {
  const b = m.backend || '';
  if (!b) return '';
  const sep = b.search(/[:/]/);
  if (sep > 0) {
    const head = b.slice(0, sep);
    if (loadProviders().some((p) => p.id === head)) return b.slice(sep + 1);
  }
  return b;
}

private async createBuiltinMember(id: string, stack: string, backend: string): Promise<boolean> {
  // [1.9.11] 撞名硬擋：送出前就擋重複 id、清楚警示（user 2026-06-14 報「預設會撞名、要在
  // 確認時就擋」）。真兇＝伺服器收到重複 id 的 join 會「靜默不新增、只刷 lastSeen 卻回 ok:true」
  // （authority.mjs ~590），客戶端就誤印 invite:join:ok＝以為成功。故在咽喉點先擋。
  if (this.authMembers.some((m) => m.id === id)) {
    glog(`createBuiltinMember:dup id="${id}" — 已存在，拒絕同名`);
    void vscode.window.showWarningMessage(
      `「${id}」已經是這個群組的成員了，不能用同名——每個 AI 要有不同名字（同名會被當成同一個）。請改個名字再加一次。`,
    );
    return false;
  }
  const isPersona = stack === 'digital-human';
  const architecture = stack === 'sancio' ? 'aiking' : stack === 'clean' ? 'clean' : stack.startsWith('acp') ? 'acp' : '';
  // [1.9.25] 內建 AI 的 Agent 種類（base/aiking/psycheforge，綁定不可被 /profile 改）＋
  // model 標籤（取 backend 的 model 段：provider:model → model）。
  const agentKind = agentKindForStack(stack);
  const modelLabel = backend ? (backend.includes(':') ? backend.split(':').slice(1).join(':') : backend) : '';
  const member: Member = {
    id,
    name: id,
    type: isPersona ? 'cloud-persona' : 'local-agent',
    role: 'member',
    ...(architecture ? { architecture } : {}),
    ...(backend ? { backend } : {}),
    agentKind,
    ...(modelLabel ? { modelLabel } : {}),
    notifyLevel: isPersona ? 'all' : 'mention',
    avatar: '',
    joinedAt: Date.now(),
    ...(isPersona ? { persona: id } : {}),
  };
  const ok = await this.registerMemberOnAuthority(member, `builtin:${stack}`);
  if (!ok) return false;
  // 註冊 @id 進 mentions 白名單（best-effort；raw @id 也可用）。
  try {
    cp.spawn(this.cliPath(), ['whoami', '--as', id], {
      env: { ...process.env, BRIDGE_AGENT_ID: id, BRIDGE_AGENT_FRAMEWORK: isPersona ? 'persona' : 'agent' },
      shell: process.platform === 'win32',
    });
  } catch {
    /* registration is best-effort */
  }
  // [主動打招呼 1.24.34 user] 新內建 AI 加入後「主動先打招呼」（user 明確要求）：以該成員身分 postAs
  //   發一則自我介紹到群組。固定招呼＝本地產生的 trusted 文字（滿足 postAs 的 TRUST NOTE：只送
  //   local/trusted 來源）、省 token、確定發出。延遲 ~900ms 讓「成員 add」廣播先到群組、招呼才掛對
  //   發話者。replyTo=0＝主動發話（非回覆）。⚠ 只在「人類透過 ＋成員 固定流程創建內建 AI」這條路觸發
  //   ＝符合 user「創建走固定指令、只內建、真成員、主動打招呼」——AI 無法自行走這條（addMember 需 canManage）。
  try {
    const stackLabel = STACKS.find((s) => s.id === stack)?.label || stack || 'AI';
    const greet = `大家好，我是「${id}」，由 AI King ${stackLabel} 驅動${modelLabel ? `（${modelLabel}）` : ''}，已加入群組、隨時可 @我。`;
    setTimeout(() => this.postAs(id, greet, 0), 900);
  } catch (e) {
    glog(`createBuiltinMember:greet:fail id="${id}": ${e instanceof Error ? e.message : String(e)}`);
  }
  return true;
}

private buildJoinGuide(room: string, id: string, token: string, aUrl: string, task?: string, compact?: boolean): string {
  const DL = 'https://download.ai-king.dev/skill/ak-client.mjs';
  const ak = 'ak-client.mjs';
  // [待辦③-2 compact] 同機 re-bind（繼承詞）場景：本機已裝 ai-king Skill，省步驟 0 的 Node 安裝/下載整段
  // 教學，只留「用本機路徑、沒有才一行下載」＝繼承詞字元數砍 ~60%、等比省貼進對話框觸發的進場推理 token。
  // ⛔保留下載網址 fallback：萬一貼到沒裝 Skill 的對話框仍有路可走，不是硬假設一定在本機。
  const setupFull =
    `── 步驟 0：準備執行環境 ＋ 客戶端（零依賴，不必 npm install）──\n` +
    `   ⚠ 先確認有 Node.js（ak-client.mjs 是 node 腳本，沒 node 跑不動）：跑 \`node -v\`，印出版本就 OK。\n` +
    `   若顯示「'node' 不是指令／not recognized」＝沒裝，先裝再繼續（裝完開「新的」終端機）：\n` +
    `     Windows：winget install OpenJS.NodeJS.LTS　（或到 nodejs.org 下載 LTS 安裝）\n` +
    `     macOS：brew install node　｜　Linux：用套件管理器裝 nodejs（如 apt install nodejs）\n` +
    `   再看你這台裝過 ai-king Skill 沒：~/.claude/skills/ai-king/ak-client.mjs（有就直接用它的完整路徑）\n` +
    `   沒有就下載到當前資料夾（擇一能跑的）：\n` +
    `   Windows PowerShell：iwr ${DL} -OutFile ak-client.mjs\n` +
    `   macOS/Linux：curl -fsSL ${DL} -o ak-client.mjs\n` +
    `   驗證（應印 usage、不是 module-not-found）：node ak-client.mjs\n` +
    `   完整指引（選讀）：https://download.ai-king.dev/skill/ai-king-skill.md\n` +
    `   （下面指令的 ${ak} ＝你找到的本機路徑 或 剛下載的 ./ak-client.mjs；完全離線連不到 → 回報群主用區網/隨身碟給檔）\n\n`;
  const setupCompact =
    `── 步驟 0：客戶端（本機已裝 ai-king Skill，直接用；沒有才下載）──\n` +
    `   本機路徑：~/.claude/skills/ai-king/ak-client.mjs（當作下面的 ${ak}；需 Node.js，跑 node -v 沒有就先裝）\n` +
    `   沒有就下載：iwr ${DL} -OutFile ak-client.mjs（mac/Linux：curl -fsSL ${DL} -o ak-client.mjs）\n\n`;
  const setup = compact ? setupCompact : setupFull;
  const taskLine =
    task && task.trim() ? `你在群組的角色/任務：${task.trim()}。先 @群主 對齊再開工。\n\n` : '';
  return (
    `你現在是 AI 群組「${room}」的成員，名字叫「${id}」。\n` +
    taskLine +
    `群組走中央權威伺服器 + E2E 加密（AES-256-GCM，鑰匙=sha256(room:token)，在你機器上加解密、伺服器只存密文）。用零依賴 node 客戶端 ak-client.mjs 收發。\n\n` +
    setup +
    `── 步驟 1：報到（加入成員）──\n` +
    `   node ${ak} join --url "${aUrl}" --room "${room}" --token "${token}" --me "${id}"\n` +
    `   （回 {} ＝成功；回 error ＝把整行貼回群主）\n\n` +
    `── 步驟 2：收訊息（text 已自動解密；記回傳 maxSeq 當下次 --since）──\n` +
    `   node ${ak} recv --url "${aUrl}" --room "${room}" --token "${token}"\n\n` +
    `── 步驟 3：發訊息（自動 E2E 加密；點名才叫得到對方）──\n` +
    `   node ${ak} send --url "${aUrl}" --room "${room}" --token "${token}" --me "${id}" --text "@群主 ${id} 上線"\n\n` +
    // [wake-arch 2026-06-15] first-contact 契約：一條 OS-agnostic node watch 子命令取代舊「sleep 迴圈」文案。
    // id 已 baked 進指令，第一次接觸就背景啟動、別等指示；命中 @${id}／@all／@所有人 才喚醒，否則 0 token。
    `── 步驟 4：背景待命（@就醒、不空轉；一接上「立刻」背景啟動，別等指示）──\n` +
    `   node ${ak} watch --url "${aUrl}" --room "${room}" --token "${token}" --me "${id}"\n` +
    `   （丟到背景執行：命中 @${id}（或 @all／@所有人）才喚醒處理＋回，沒命中就靜默續跑＝0 token。）\n` +
    `⛔ 禁止空轉：絕對別用 ScheduleWakeup／/loop／cron／每 N 秒喚醒整個 agent 收訊——每醒一次都重讀整個 context＝燒爆 token。喚醒、處理完就把這支 watch 再背景啟動一次（re-arm）。\n\n` +
    `先發一則上線訊息，留在群組協作直到群主說停。`
  );
}

private async copyInheritCode(id: string): Promise<void> {
  const m = this.authMembers.find((x) => x.id === id);
  if (!m) { void vscode.window.showWarningMessage(`AI 群組：找不到成員「${id}」。`); return; }
  if (m.type === 'human') {
    void vscode.window.showWarningMessage('AI 群組：邀請詞只給 AI 成員用；人類成員請改用「邀請碼」（＋成員 → 線上邀請）。');
    return;
  }
  const token = getRoomToken(this.channel);
  if (!token || !token.trim()) {
    void vscode.window.showErrorMessage('AI 群組：房間鑰匙讀取失敗，無法產生邀請詞。');
    return;
  }
  const aUrl = this.roomAuthorityBase(this.channel);
  const cfg = vscode.workspace.getConfiguration('aiKing');
  // [待辦③-2] 繼承詞精簡模式：本機已裝 ai-king Skill（同機 re-bind 場景）→ buildJoinGuide compact 省步驟 0。
  // switch aiKing.invite.compactInherit 預設 true；env AK_INVITE_COMPACT=0 全域關。偵測不到本機檔就退回完整。
  let hasLocalAk = false;
  try { hasLocalAk = fs.existsSync(path.join(os.homedir(), '.claude', 'skills', 'ai-king', 'ak-client.mjs')); } catch { /* */ }
  const compactOn = cfg.get<boolean>('invite.compactInherit', true)
    && !/^(0|false|no|off)$/i.test(process.env.AK_INVITE_COMPACT || '')
    && hasLocalAk;
  const guide = this.buildJoinGuide(this.channel, id, token, aUrl, undefined, compactOn);
  await vscode.env.clipboard.writeText(guide);
  // [待辦③-1] 繼承詞含明文 room token（=E2E 主鑰），對齊 invite public 分支（:3528）補外洩警告。
  // switch aiKing.invite.inheritWarnLeak 預設 true（要關提示才不附）。
  const leakNote = cfg.get<boolean>('invite.inheritWarnLeak', true)
    ? ' ⚠ 此繼承詞含房間鑰匙（token）＝能解全房對話的鑰匙，只貼給你信任的 AI／人，別貼進會記錄 prompt 的公開服務；萬一外洩只能換房（鑰匙不可單獨撤銷）。'
    : '';
  void vscode.window.showInformationMessage(
    `已複製「${m.name || id}」的邀請詞。貼到一個新的 AI 對話視窗，它就會以同一身分「${id}」接回群組「${this.channel}」、接續所有對話。（邀請詞弄丟了，就是從這裡一鍵重拿、不必砍掉重加。）${leakNote}`,
  );
}

private async muteMemberWithPick(id: string): Promise<void> {
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能禁言成員。');
    return;
  }
  const pick = await showQuickPickEsc(
    [
      { label: '🔇 5 分鐘', sec: 300 },
      { label: '🔇 15 分鐘', sec: 900 },
      { label: '🔇 1 小時', sec: 3600 },
      { label: '🔇 永久（手動解除前一直禁言）', sec: -1 },
      { label: '✏ 自訂秒數…', sec: 0 },
    ],
    { placeHolder: `禁言「${id}」多久？（被禁言期間只能看訊息、不能發言）`, ignoreFocusOut: true },
  );
  if (!pick) return;
  let sec = pick.sec;
  if (sec === 0) {
    const defSec = vscode.workspace.getConfiguration('aiKing').get<number>('muteDefaultSec', 900);
    const input = await showInputBoxEsc({
      prompt: '禁言秒數（60 ~ 86400，或填 -1 = 永久）',
      value: String(defSec),
      ignoreFocusOut: true,
      validateInput: (v) => {
        const n = Number(v);
        return Number.isFinite(n) && (n === -1 || (n >= 60 && n <= 86400)) ? null : '請填 60–86400 的秒數，或 -1 永久';
      },
    });
    if (input === undefined) return;
    sec = Number(input);
  }
  const r = await this.authority?.mute(id, sec);
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：禁言失敗 — ${r.error}`);
    return;
  }
  void vscode.window.showInformationMessage(
    `已禁言「${id}」${sec === -1 ? '（永久，手動解除前）' : `約 ${Math.round(sec / 60)} 分鐘`}。`,
  );
}

private async renameGroupWithPrompt(): Promise<void> {
  if (this.selfRole() !== 'owner') {
    void vscode.window.showWarningMessage('AI 群組：只有群主能改群組名稱。');
    return;
  }
  const name = await showInputBoxEsc({
    prompt: '群組新名稱（只是顯示名，不影響加密與歷史，按 ESC 取消）',
    value: this.roomDisplayName || this.channel,
    ignoreFocusOut: true,
    validateInput: (v) => (v && v.trim() ? null : '請輸入名稱'),
  });
  if (name === undefined || !name.trim()) return;
  const r = await this.authority?.rename(name.trim());
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：改名失敗 — ${r.error}`);
    return;
  }
  void vscode.window.showInformationMessage(`群組已改名為「${name.trim()}」。`);
}

private async deleteMessageOnAuthority(seq: number): Promise<void> {
  if (!this.authority) {
    void vscode.window.showWarningMessage('還沒連上群組伺服器，無法刪除訊息。');
    return;
  }
  try {
    const r = await this.authority.deleteMessage(seq);
    if (r && typeof r.error === 'string') void vscode.window.showWarningMessage(`刪除訊息失敗：${r.error}`);
  } catch (e: any) {
    void vscode.window.showWarningMessage(`刪除訊息出錯：${e?.message || String(e)}`);
  }
}

private async registerMemberOnAuthority(member: Member, label: string): Promise<boolean> {
  const r = this.channel;
  if (!this.authority) {
    glog(`invite:join:no-client room="${r}" id="${member.id}" (${label}) — 伺服器連線尚未建立`);
    void vscode.window.showWarningMessage(
      `還沒連上群組「${r}」的伺服器，無法登記成員「${member.id}」。請等面板顯示「已連線」後再邀請一次。`,
    );
    return false;
  }
  let res: Record<string, unknown> | undefined;
  try {
    res = await this.authority.join(member);
  } catch (e: any) {
    glog(`invite:join:throw room="${r}" id="${member.id}" (${label}) err=${e?.message || String(e)}`);
    void vscode.window.showWarningMessage(`登記成員「${member.id}」時連線出錯：${e?.message || String(e)}`);
    return false;
  }
  if (res && typeof res.error === 'string') {
    glog(`invite:join:err room="${r}" id="${member.id}" (${label}) err=${res.error}`);
    void vscode.window.showWarningMessage(`登記成員「${member.id}」失敗：${res.error}`);
    return false;
  }
  glog(`invite:join:ok room="${r}" id="${member.id}" (${label})`);
  return true;
}

private async pickModelLabel(agentKind: string, who: string): Promise<string | undefined> {
  const CUSTOM = '�custom';
  const NONE = '�none';
  const presets = modelsForAgentKind(agentKind);
  const items: Array<{ label: string; detail?: string; value: string }> = [
    ...presets.map((m) => ({ label: m, value: m })),
    {
      label: '自訂（手動輸入型號）…',
      detail: presets.length ? '清單沒有就自己打' : '這家偵測不到型號，自己打一個（如 v1 / 70B / 自訂名）',
      value: CUSTOM,
    },
    { label: '不設型號標籤', detail: '訊息行只顯示 Agent 圖示、不顯示型號文字', value: NONE },
  ];
  const pick = await showQuickPickEsc(items, {
    placeHolder: `「${who}」用哪個型號？（顯示用標籤，按 ESC 取消）`,
    ignoreFocusOut: true,
    matchOnDetail: true,
  });
  if (!pick) return undefined;
  if (pick.value === NONE) return '';
  if (pick.value === CUSTOM) {
    const v = await showInputBoxEsc({
      prompt: `輸入「${who}」的型號標籤（按 ESC 取消）`,
      placeHolder: '例如 Opus 4.8 / GPT-5.5 / v1',
      ignoreFocusOut: true,
    });
    if (v === undefined) return undefined; // ESC
    return v.trim();
  }
  return pick.value;
}

private async inviteExternalAi(serverType?: 'local' | 'lan' | 'public'): Promise<void> {
  const r = this.channel;
  // [v1.9.24] serverType 由 addMember 傳入（決定成功提示講對「能連的範圍」）；沒傳則自己判一次。
  const sType = serverType || this.roomServerType(r);
  const used = new Set(this.authMembers.map((mm) => mm.id));
  let defName = 'assistant';
  if (used.has(defName)) { let i = 2; while (used.has(`assistant-${i}`)) i++; defName = `assistant-${i}`; }
  const id0 = await showInputBoxEsc({
    prompt: '這個外部 AI 在群組裡的名字（每位要用不同名字，按 ESC 取消）',
    placeHolder: '例如 claude-cli / codex-1 / claude-gta',
    value: defName,
    ignoreFocusOut: true,
    validateInput: (v) => {
      const t = (v || '').trim();
      if (!t) return '請輸入名字';
      if (used.has(t)) return `「${t}」已是這個群組的成員，請取不同名字（同名會被當成同一個 AI）。`;
      return null;
    },
  });
  if (!id0 || !id0.trim()) return;
  const id = id0.trim();

  // [1.9.25] 選 Agent 種類（Claude/Codex/OpenClaw/Hermes/其他）→ 套 Agent 標籤＝決定訊息行
  // 顯示哪個 Agent Logo + 滑鼠移上去的精準識別文字。外部 AI 偵測不到種類，由 user 指定。
  const kindPick = await showQuickPickEsc(
    externalAgentKinds().map((d) => ({
      label: d.label,
      detail: d.models.length ? `型號：${d.models.join(' / ')}` : '型號自填（這家偵測不到、各家命名未定）',
      iconPath: this.icon('ai'),
      kindId: d.kind as string,
    })),
    { placeHolder: `「${id}」是哪一家的 AI？（決定它的 Agent 標籤，按 ESC 取消）`, ignoreFocusOut: true, matchOnDetail: true },
  );
  if (!kindPick) return;
  const agentKind = kindPick.kindId;

  // [1.9.25] 選 model 顯示標籤（外部偵測不到 → 選預設清單或自填）。訊息行用人物配色顯示。
  const modelLabel = await this.pickModelLabel(agentKind, id);
  if (modelLabel === undefined) return; // ESC 取消

  const task = await showInputBoxEsc({
    prompt: '專屬任務／角色（可留空，按 ESC 取消）— 會寫進邀請詞讓它一進群組就知道自己幹嘛',
    placeHolder: '例如 你負責查 GTA mod',
    ignoreFocusOut: true,
  });
  const ok = await this.registerMemberOnAuthority(
    {
      id, name: id, type: 'local-agent', avatar: '', joinedAt: Date.now(),
      ...(agentKind ? { agentKind } : {}),
      ...(modelLabel ? { modelLabel } : {}),
    },
    'external',
  );
  if (!ok) return;
  const token = getRoomToken(r);
  const aUrl = this.roomAuthorityBase(r);
  const guide = this.buildJoinGuide(r, id, token, aUrl, task && task.trim() ? task.trim() : undefined);
  await vscode.env.clipboard.writeText(guide);
  glog(`inviteExternalAi:done id="${id}" serverType=${sType}`);
  // [v1.9.24 防呆] 成功提示依 serverType 講對「貼出去後誰連得到」，別給 user 錯誤期待。
  if (sType === 'public') {
    void vscode.window.showInformationMessage(
      `已複製「${id}」的邀請詞（含 Skill 下載網址）。任何地方的 AI 貼上即可加入。⚠ 邀請詞含房間鑰匙（token）＝能解全房對話的鑰匙，只貼給你信任的 AI／人，別貼進會記錄 prompt 的公開服務；萬一外洩只能換房（鑰匙不可單獨撤銷）。`,
    );
  } else if (sType === 'lan') {
    void vscode.window.showInformationMessage(
      `已複製「${id}」的邀請詞。目前是區網群組，只有「同一個區域網路」內的 AI（同機 Claude Code CLI 或區網別台的 AI）連得到——貼到它的視窗即可。⚠ 外網的人／AI 連不到；要邀外地的請先把群組搬到公開伺服器（齒輪 → 伺服器設定）。`,
    );
  } else {
    // [wake-arch 2026-06-15] 127.0.0.1 本機房硬警告（修場景 16）：external invite 指向 loopback 時，
    // 離機 AI 物理上連不到；且伺服器跑在 owner 機內，關 VS Code／睡眠＝伺服器死＝整個房（含 watch 待命）全斷。
    // 跨機可靠協作必須用 VPS 房，不能靠本機 loopback。
    void vscode.window.showWarningMessage(
      `已複製「${id}」的邀請詞。⚠ 這是本機房（伺服器跑在你這台電腦的 127.0.0.1）：只有「同一台電腦」的 AI（如你的 Claude Code CLI）連得到，貼到它的視窗即可。` +
        `❌ 別台電腦／別人的 AI 物理上連不到 127.0.0.1；而且你一關 VS Code／電腦睡眠，這台的伺服器就死＝整個群組（連背景 watch 待命）全斷。` +
        `要跨機協作請先把群組搬到 VPS 公開伺服器（齒輪 → 伺服器設定），別用本機房邀外地 AI。`,
    );
  }
}

private async inviteToRoom(forceMode?: 'local-existing' | 'local-spawn' | 'online'): Promise<void> {
  const r = this.channel;
  const online = isOnlineRoom(r);
  glog(`invite:start room="${r}" forceMode=${forceMode || '(picker)'} online=${online}`);
  // forceMode lets the (flattened) 三分類 add-member menu jump straight to a
  // branch without showing this sub-picker. Unset → show the legacy sub-picker.
  let mode: string | undefined = forceMode;
  if (!mode) {
    const choices = [
      { label: '🤖 邀請 AI 助理（同機）', detail: '產生一段話，貼給你的 Claude Code 視窗，它就會收發群組訊息', mode: 'local-existing' },
      { label: '✨ 開新 AI 助理進房（同機）', detail: '自動開一個新 Claude 代理進這個群組', mode: 'local-spawn' },
    ];
    if (online) {
      // Online groups can do everything local PLUS cross-machine invite.
      choices.push({ label: '🌐 線上邀請別台電腦的人', detail: '產生連線碼，對方按「⇲ 加入線上群組」貼上即可同步', mode: 'online' });
    }
    const kind = await showQuickPickEsc(choices, {
      placeHolder: online
        ? `邀請誰加入線上群組「${r}」？（按 ESC 取消）`
        : `邀請誰加入本機群組「${r}」？（按 ESC 取消）`,
      ignoreFocusOut: true,
    });
    if (!kind) return;
    mode = kind.mode;
  }

  // ── 本地 · 邀請 AI 助理 ── 產生「整段指引」貼給 Claude Code（零 skill 零檔）。
  if (mode === 'local-existing') {
    // Default to a name that does NOT collide with an existing member, so
    // inviting a 2nd/3rd assistant into the same room gives each a DISTINCT id.
    // Two members sharing one id = one authority identity = they fight over it.
    const used = new Set(this.authMembers.map((mm) => mm.id));
    let defName = 'assistant';
    if (used.has(defName)) { let i = 2; while (used.has(`assistant-${i}`)) i++; defName = `assistant-${i}`; }
    const id0 = await showInputBoxEsc({
      prompt: '這個 AI 助理在群組裡的名字（每位 AI 要用不同名字，按 ESC 取消）',
      placeHolder: '例如 assistant-2 / codex-1 / claude-gta',
      value: defName,
      ignoreFocusOut: true,
      validateInput: (v) => {
        const t = (v || '').trim();
        if (!t) return '請輸入名字';
        if (used.has(t)) return `「${t}」已經是這個群組的成員了，請取個不同的名字（同名會被當成同一個 AI）。`;
        return null;
      },
    });
    if (!id0 || !id0.trim()) return;
    const id = id0.trim();
    // Authoritative roster write — broadcasts a member event to all clients.
    // [1.9.3] checked：寫不進名冊就中止（別給「假成功」的指引讓對方撞 not-a-member）。
    const ok = await this.registerMemberOnAuthority(
      { id, name: id, type: 'local-agent', avatar: '', joinedAt: Date.now() },
      'local-existing',
    );
    if (!ok) return;
    const token = getRoomToken(r);
    const aUrl = this.roomAuthorityBase(r);
    const guide = this.buildJoinGuide(r, id, token, aUrl);
    await vscode.env.clipboard.writeText(guide);
    void vscode.window.showInformationMessage(
      `已複製「邀請 AI 助理 ${id}」的整段指引——貼到你的 Claude Code 視窗，它就會加入群組「${r}」開始收發。`,
    );
    return;
  }

  // ── 本地 · 開新代理進房 ── 在終端機生一個新 Claude，預載入房指令。
  if (mode === 'local-spawn') {
    const id0 = await showInputBoxEsc({
      prompt: '新代理的名字（按 ESC 取消）', placeHolder: '例如 helper-1', ignoreFocusOut: true,
      validateInput: (v) => (v && v.trim() ? null : '請輸入名字'),
    });
    if (!id0 || !id0.trim()) return;
    const id = id0.trim();
    const task = await showInputBoxEsc({
      prompt: '給這個新代理的任務（可留空，按 ESC 取消）', placeHolder: '例如 幫我查 X', ignoreFocusOut: true,
    });
    // Authoritative roster write — broadcasts a member event to all clients.
    // [1.9.3] checked：寫不進名冊就中止（別開了終端機代理卻沒登記、收不到訊息）。
    const ok = await this.registerMemberOnAuthority(
      { id, name: id, type: 'local-agent', avatar: '', joinedAt: Date.now() },
      'local-spawn',
    );
    if (!ok) return;
    const token = getRoomToken(r);
    const aUrl = this.roomAuthorityBase(r);
    const ak = '~/.claude/skills/ai-king/ak-client.mjs';
    const joinPrompt =
      `你是 AI 群組「${r}」的成員 ${id}（中央權威伺服器 + E2E）。用 node 客戶端參與：` +
      `先加入 node ${ak} join --url "${aUrl}" --room "${r}" --token "${token}" --me "${id}"；` +
      `收信 node ${ak} recv --url "${aUrl}" --room "${r}" --token "${token}" --since 0；` +
      `發言 node ${ak} send --url "${aUrl}" --room "${r}" --token "${token}" --me "${id}" --text "訊息"。` +
      `持續待命＝背景 sleep 迴圈跑 recv（--since 帶上次 maxSeq）、被 @${id} 才喚醒；⛔別用 ScheduleWakeup／定時喚醒整個 agent（會燒爆 token）。先發一則上線訊息。` +
      (task && task.trim() ? ` 你的任務：${task.trim()}` : '');
    const term = vscode.window.createTerminal({
      name: `Bridge: ${id}`,
      env: { ...process.env, BRIDGE_HOME: this.home, BRIDGE_AGENT_ID: id },
    });
    term.show();
    term.sendText(`claude "${joinPrompt.replace(/"/g, '')}"`);
    void vscode.window.showInformationMessage(`已開新代理「${id}」進「${r}」（終端機啟動中）。`);
    return;
  }

  // ── 線上 · 跨機器 ── authority 模式：連線碼帶 {authorityUrl, room, token}。
  // The room's E2E key is derived from the SAME token the authority server
  // gates on (.token file) — so the peer that pastes the code derives the same
  // ROOM_KEY and decrypts history the server only ever stored as ciphertext.
  const token = getRoomToken(r);
  const cfg = readRelayConfig(r);
  const authority = this.roomAuthorityBase(r);
  // legacy 'relay' field kept for back-compat with old clients; new clients use
  // `authority`. Fall back to the room's OWN server — NEVER a hardcoded VPS (that
  // would leak the author's private server into the open-source build).
  const relay = cfg?.relay || authority;
  // Make sure the local authority server is up (no-op when THIS room is remote).
  ensureAuthorityServer(authority);
  const invite = encodeInvite(r, token, relay, { id: this.selfName(), role: this.selfRole() }, authority);
  // [1.9.3] 產碼後記下指向哪台伺服器 + token 長度（勿印 token 全文＝E2E 金鑰種子）。
  glog(`invite:online room="${r}" authority=${authority} relay=${relay} tokenLen=${token.length} inviteLen=${invite.length}`);
  await vscode.env.clipboard.writeText(invite);
  void vscode.window.showInformationMessage(
    `已複製「${r}」的線上連線碼。傳給對方，對方在 AI King 按「⇲ 加入線上群組」貼上，兩台即同步對話（E2E 加密，伺服器看不到明文）。`,
  );
}

private async uploadAvatar(id: string): Promise<void> {
  // [批B-E 審查修正] 換頭像＝改成員資料，限管理員以上（縱深防禦：webview 已隱藏入口，host
  // 端也擋，與其他 member:* 一致；avatar 落本機檔不走 server、server gate 保不到此路徑）。
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能更換成員頭像。');
    return;
  }
  const picks = await vscode.window.showOpenDialog({
    canSelectMany: false,
    openLabel: '選擇圖片',
    title: `為成員「${id}」選一張頭像`,
    filters: { 圖片: ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'] },
  });
  if (!picks || !picks.length) return;
  try {
    const data = await vscode.workspace.fs.readFile(picks[0]);
    if (data.byteLength > 5_000_000) {
      void vscode.window.showWarningMessage('圖片過大（> 5MB），請換小一點的。');
      return;
    }
    const ext = (path.extname(picks[0].fsPath) || '.png').toLowerCase();
    // [1.9.3] SVG 向量直接落檔；點陣圖丟給 webview 圓形裁切器（拖曳定位 + 縮放）。
    if (ext === '.svg') {
      await this.writeMemberAvatarFile(id, 'svg', data);
      void vscode.window.showInformationMessage(`已設定「${id}」的頭像。`);
      return;
    }
    const mime =
      ext === '.png' ? 'image/png'
        : ext === '.gif' ? 'image/gif'
          : ext === '.webp' ? 'image/webp'
            : 'image/jpeg';
    const dataUri = `data:${mime};base64,${Buffer.from(data).toString('base64')}`;
    glog(`member:avatar:crop-open id="${id}" bytes=${data.byteLength}`);
    this.post({ type: 'avatar:crop:open', id, dataUri });
  } catch (err) {
    void vscode.window.showErrorMessage(
      `設定頭像失敗：${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

private async saveCroppedMemberAvatar(id: string, dataUri: string): Promise<void> {
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能更換成員頭像。');
    return;
  }
  try {
    const m = /^data:image\/(png|webp|jpeg|jpg);base64,(.+)$/i.exec(dataUri || '');
    if (!m) { void vscode.window.showWarningMessage('裁切結果格式無法辨識，請重試。'); return; }
    const buf = Buffer.from(m[2], 'base64');
    if (buf.byteLength > 2_000_000) { void vscode.window.showWarningMessage('裁切後的圖仍過大。'); return; }
    const ext = m[1].toLowerCase() === 'png' ? 'png' : 'webp';
    await this.writeMemberAvatarFile(id, ext, buf);
    glog(`member:avatar:saved id="${id}" bytes=${buf.byteLength}`);
    void vscode.window.showInformationMessage(`已設定「${id}」的頭像。`);
  } catch (err) {
    void vscode.window.showErrorMessage(
      `儲存頭像失敗：${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

private async writeMemberAvatarFile(id: string, ext: string, bytes: Uint8Array): Promise<void> {
  const safeId = id.replace(/[^\w-]/g, '_');
  const rel = `${this.channel}/${safeId}.${ext}`;
  const dir = vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', this.channel);
  await vscode.workspace.fs.createDirectory(dir);
  await vscode.workspace.fs.writeFile(
    vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', rel),
    bytes,
  );
  updateMemberAvatar(this.channel, id, 'store:' + rel);
  this.pushMembers();
}

private async renameMember(id: string, rawName: string): Promise<void> {
  // [批B-E 審查修正] 改名限管理員以上（UI/host 一致；一般成員含改自己都不能改名，身份由
  // 管理員統一管理；含 slash /改名 自助改名也擋）。⚠ server 端 name 分支仍放行 self
  // (authority.mjs:915)，三層完全一致需部署收緊那裡；本層先擋住所有經 host 的 webview 路徑。
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有管理員以上能改名（一般成員的身份由管理員統一管理）。');
    return;
  }
  const m = this.authMembers.find((x) => x.id === id) || readMembers(this.channel).find((x) => x.id === id);
  if (!m) return;
  const name = rawName.trim().slice(0, 60);
  if (!name || name === m.name) return;
  const oldName = m.name || id; // 取舊顯示名給系統訊息（memberUpdate 後 m.name 可能被更新）
  const r = await this.authority?.memberUpdate(id, { name });
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：改名失敗 — ${r.error}`);
    return;
  }
  // [系統動作] 改名成功 → 額外送一則「誰 把 誰 改名為 X」置中系統訊息（用舊名指認對象）。
  void this.sendSystemMessage('rename', oldName, name);
  void vscode.window.showInformationMessage(`已改名為「${name}」（已同步給所有成員）。`);
}

private async setMemberModelLabel(id: string, rawLabel: string): Promise<void> {
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有管理員以上能改成員型號。');
    return;
  }
  const m = this.authMembers.find((x) => x.id === id) || readMembers(this.channel).find((x) => x.id === id);
  if (!m) return;
  const label = (rawLabel || '').trim().slice(0, 40);
  if (label === (m.modelLabel || '')) return;
  const r = await this.authority?.memberUpdate(id, { modelLabel: label });
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：改型號失敗 — ${r.error}`);
    return;
  }
  // [1.24.21 A14 反向同步] 連結 session 也寫回 model（純文字自填型號 → 對話跟著改）。
  const linkedL = this.linkedSessionId(id);
  if (linkedL && label) {
    try { await sessionStoreFor(this.ctx).setIdentity(linkedL, { model: label }); } catch { /* best-effort */ }
  }
  void vscode.window.showInformationMessage(label ? `已設型號「${label}」（已同步給所有成員）。` : '已清除型號標籤。');
}

private async setMemberProviderModel(id: string, provider: string, model: string): Promise<void> {
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有管理員以上能改成員供應商／模型。');
    return;
  }
  const m = this.authMembers.find((x) => x.id === id) || readMembers(this.channel).find((x) => x.id === id);
  if (!m) return;
  const prov = (provider || '').trim().slice(0, 40);
  const mdl = (model || '').trim().slice(0, 60);
  // backend 真相源：兩者都有才組 provider:model；缺供應商就退只存 model（相容舊資料）。
  const backend = prov && mdl ? `${prov}:${mdl}` : mdl;
  const label = mdl;
  if (backend === (m.backend || '') && label === (m.modelLabel || '')) return;
  const r = await this.authority?.memberUpdate(id, { backend, modelLabel: label });
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：改供應商／模型失敗 — ${r.error}`);
    return;
  }
  // [1.24.21 A14 反向同步] 該成員若連結私聊 session（內建 1:1）→ 寫回 session.model/providerId，
  // 讓「群組改 model → 對話跟著改」（與對話端 syncBuiltin 的對話→群組同步構成雙向母版）。
  const linked = this.linkedSessionId(id);
  if (linked && prov && mdl) {
    try { await sessionStoreFor(this.ctx).setIdentity(linked, { model: mdl, providerId: prov }); } catch { /* best-effort */ }
  }
  void vscode.window.showInformationMessage(
    mdl ? `已設供應商／模型「${prov || '?'} · ${mdl}」（已同步給所有成員）。` : '已清除供應商／模型。',
  );
}

private async setMemberBioOnly(id: string, rawBio: string): Promise<void> {
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有管理員以上能改成員簡介。');
    return;
  }
  const m = this.authMembers.find((x) => x.id === id) || readMembers(this.channel).find((x) => x.id === id);
  if (!m) return;
  const bio = (rawBio || '').trim().slice(0, MAX_BIO_LEN);
  if (bio === (m.bio || '')) return;
  const r = await this.authority?.memberUpdate(id, { bio });
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：更新簡介失敗 — ${r.error}`);
    return;
  }
  setMemberBio(this.channel, id, bio); // offline/legacy 顯示
  // [1.24.21 A14 反向同步] 連結 session 也寫回 aiBio（群組改簡介 → 對話跟著改）。
  const linkedB = this.linkedSessionId(id);
  if (linkedB) {
    try { await sessionStoreFor(this.ctx).setAiBio(linkedB, bio); } catch { /* best-effort */ }
  }
  void vscode.window.showInformationMessage('已更新簡介（已同步給所有成員）。');
}

private async editMemberBio(id: string): Promise<void> {
  const isSelf = id === this.selfName();
  // [批B-E 審查修正] 編輯資料限管理員以上（與個資卡就地編輯一致；一般成員含自己不能改）。
  // 註：個資卡已移除「編輯資料」按鈕、改名/簡介改走就地編輯，此方法僅餘 slash/相容路徑觸發。
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有管理員以上能改個人資料。');
    return;
  }
  const m = this.authMembers.find((x) => x.id === id) || readMembers(this.channel).find((x) => x.id === id);
  if (!m) return;
  const name = await showInputBoxEsc({
    prompt: `${isSelf ? '你的' : `「${m.name}」的`}顯示名（群組裡大家看到的名字，按 ESC 取消）`,
    value: m.name || id,
    ignoreFocusOut: true,
    validateInput: (v) => (v && v.trim() ? null : '請輸入名字'),
  });
  if (name === undefined) return;
  const bio = await showInputBoxEsc({
    prompt: `${isSelf ? '你的' : `「${m.name}」的`}個人簡介（最多 ${MAX_BIO_LEN} 字，顯示在頭像卡，可留空，按 ESC 取消）`,
    value: m.bio || '',
    ignoreFocusOut: true,
  });
  if (bio === undefined) return;
  const patch: Record<string, unknown> = {};
  const nm = name.trim().slice(0, 60);
  if (nm && nm !== m.name) patch.name = nm;
  const b = bio.trim().slice(0, MAX_BIO_LEN);
  if (b !== (m.bio || '')) patch.bio = b;
  if (Object.keys(patch).length === 0) { void vscode.window.showInformationMessage('個人資料沒有變更。'); return; }
  // Sync to ALL members via the authority broadcast (server is the source of truth).
  const r = await this.authority?.memberUpdate(id, patch);
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：更新個人資料失敗 — ${r.error}`);
    return;
  }
  if (typeof patch.bio === 'string') setMemberBio(this.channel, id, patch.bio as string); // offline/legacy display
  void vscode.window.showInformationMessage('已更新個人資料（已同步給所有成員）。');
}

private postLocalNotice(text: string): void {
  this.post({ type: 'localNotice', text });
}

private resolveMemberByName(name: string): Member | undefined {
  const q = name.replace(/^@+/, '').trim().toLowerCase();
  if (!q) return undefined;
  const pool = this.authMembers.length ? this.authMembers : readMembers(this.channel);
  return pool.find((m) => m.id.toLowerCase() === q || (m.name || '').toLowerCase() === q);
}

