      '　/promote <名>　 把某成員設為管理員（限群主）',
      '　/demote <名>　　取消某成員的管理員（限群主）',
      '　/kick <名>　　　把某成員移出群組',
    );
  }
  return lines.join('\n');
}

private groupWhoText(): string {
  const pool = this.authMembers.length ? this.authMembers : readMembers(this.channel);
  const rows = pool.map((m) => {
    const role = m.role === 'owner' ? '👑群主' : m.role === 'admin' ? '🛡管理員' : '成員';
    const kind = m.type === 'human' ? '人類' : 'AI';
    return `　• ${m.name || m.id}（${role}・${kind}）`;
  });
  return `群組成員（${pool.length}）：\n${rows.join('\n')}`;
}

private async setSelfBio(bio: string): Promise<void> {
  const id = this.selfName();
  const b = bio.trim().slice(0, MAX_BIO_LEN);
  const r = await this.authority?.memberUpdate(id, { bio: b });
  if (r && typeof r.error === 'string') {
    this.postLocalNotice(`設定簡介失敗：${r.error}`);
    return;
  }
  setMemberBio(this.channel, id, b); // offline/legacy display
  this.postLocalNotice('已更新你的簡介（已同步給所有成員）。');
}

private async sendAnnouncement(text: string): Promise<void> {
  if (!this.authority) { this.postLocalNotice('尚未連上伺服器，公告未送出。'); return; }
  const r = await this.authority.send(this.selfName(), `📢 公告：${text}`);
  if (r && typeof r.error === 'string') this.postLocalNotice(`公告送出失敗：${r.error}`);
}

private async sendLabel(kind: 'skip' | 'important' | 'ack'): Promise<void> {
  if (this.authStatus === 'dissolved') { this.postLocalNotice('群組已解散，無法再發送標示。'); return; }
  if (!this.authority) { this.postLocalNotice('尚未連上伺服器，標示未送出。'); return; }
  const text = `${LABEL_PREFIX}${JSON.stringify({ k: kind })}`;
  const r = await this.authority.send(this.selfName(), text);
  if (r && typeof r.error === 'string') this.postLocalNotice(`標示送出失敗：${r.error}`);
}

private async sendSystemMessage(
  action: 'rename' | 'kick' | 'role',
  who: string,
  extra?: string,
): Promise<void> {
  if (this.authStatus === 'dissolved') { glog(`sys:send skip dissolved a=${action} who="${who}"`); return; }
  if (!this.authority) { glog(`sys:send skip noauth a=${action} who="${who}"`); return; }
  const by = this.displayNameOf(this.selfName());
  const payload: { a: string; by: string; who: string; extra?: string } = { a: action, by, who };
  if (typeof extra === 'string' && extra) payload.extra = extra;
  const text = `${SYS_PREFIX}${JSON.stringify(payload)}`;
  glog(`sys:send a=${action} by="${by}" who="${who}" extra="${extra || ''}"`);
  const r = await this.authority.send(this.selfName(), text);
  if (r && typeof r.error === 'string') glog(`sys:send:err a=${action} err=${r.error}`);
}

private displayNameOf(id: string): string {
  const m = this.authMembers.find((x) => x.id === id)
    || readMembers(this.channel).find((x) => x.id === id);
  return (m && m.name) ? m.name : id;
}

private async setRoleByName(name: string, role: MemberRole): Promise<void> {
  if (this.selfRole() !== 'owner') { this.postLocalNotice('只有群主能指派／取消管理員。'); return; }
  const m = this.resolveMemberByName(name);
  if (!m) { this.postLocalNotice(`找不到成員「${name}」（用 /who 看名單）。`); return; }
  const r = await this.authority?.memberUpdate(m.id, { role });
  if (r && typeof r.error === 'string') { this.postLocalNotice(`設定失敗：${r.error}`); return; }
  // [系統動作] 設 / 降管理員成功 → 額外送一則「誰 把 誰 設為管理員 / 取消管理員」置中系統訊息。
  // extra=role（'admin'=設、'member'=降），由 webview 端據此挑樣板。
  void this.sendSystemMessage('role', m.name || m.id, role);
  this.postLocalNotice(role === 'admin' ? `已把「${m.name}」設為管理員。` : `已取消「${m.name}」的管理員。`);
}

private async kickByName(name: string): Promise<void> {
  if (!this.canManage()) { this.postLocalNotice('只有群主或管理員能移除成員。'); return; }
  const m = this.resolveMemberByName(name);
  if (!m) { this.postLocalNotice(`找不到成員「${name}」（用 /who 看名單）。`); return; }
  if (m.id === this.selfName()) { this.postLocalNotice('要移除自己請用 ⋮ →「離開群組」。'); return; }
  await this.authority?.kick(m.id);
  // [系統動作] 移出成功 → 額外送一則「誰 把 誰 移出群組」置中系統訊息。
  void this.sendSystemMessage('kick', m.name || m.id);
  this.postLocalNotice(`已移除成員「${m.name}」。`);
}

private async handleGroupCommand(raw: string): Promise<void> {
  const mm = raw.trim().match(/^\/(\S+)\s*([\s\S]*)$/);
  if (!mm) return;
  const cmd = mm[1].toLowerCase();
  const arg = (mm[2] || '').trim();
  const isAdmin = this.canManage();
  glog(`group:cmd cmd="${cmd}" argLen=${arg.length} role=${this.selfRole()}`);
  switch (cmd) {
    case 'help': case '幫助': case '指令':
      this.postLocalNotice(this.groupHelpText(isAdmin)); return;
    case 'who': case '誰': case '成員': case 'members':
      this.postLocalNotice(this.groupWhoText()); return;
    case 'bio': case '簡介': case '介紹': case '自我介紹': case '負責範圍':
      if (!arg) { this.postLocalNotice('用法：/bio <你的簡介文字>'); return; }
      await this.setSelfBio(arg); return;
    case 'rename': case '改名':
      if (!arg) { this.postLocalNotice('用法：/rename <新名字>'); return; }
      await this.renameMember(this.selfName(), arg); return;
    case 'avatar': case '換頭像': case '頭像':
      await this.uploadAvatar(this.selfName()); return;
    case 'announce': case '公告':
      if (!isAdmin) { this.postLocalNotice('只有群主或管理員能發公告。'); return; }
      if (!arg) { this.postLocalNotice('用法：/announce <內容>'); return; }
      await this.sendAnnouncement(arg); return;
    case 'promote': case '設管理員':
      await this.setRoleByName(arg, 'admin'); return;
    case 'demote': case '降級':
      await this.setRoleByName(arg, 'member'); return;
    case 'kick': case '踢':
      await this.kickByName(arg); return;
    // [指令標示] 三個狀態標示指令（含中文別名）。攔截後改送 label 特殊訊息（不送一般聊天、
    // 不路由 AI），webview 收到會渲染成置中系統狀態行。比照反應，靠指令觸發、不自動偵測已讀。
    case 'skip': case '已讀不回':
      await this.sendLabel('skip'); return;
    case 'important': case '重要':
      await this.sendLabel('important'); return;
    case 'ack': case '收到':
      await this.sendLabel('ack'); return;
    // [評分] 同儕互評（讚／平／倒讚）— 對「最近一次與該對象的互動」評分。第一批：
    // rater→target 一票、可改、再按同一個＝取消；互動門檻 / round 精確綁定留後批。
    case '讚': case 'like':
      await this.rateMember(arg, 'up'); return;
    case '平': case 'meh':
      await this.rateMember(arg, 'ok'); return;
    case '倒讚': case 'dislike':
      await this.rateMember(arg, 'down'); return;
    default:
      this.postLocalNotice(`未知指令：/${cmd}（打 /help 看可用指令）`); return;
  }
}

private async rateMember(arg: string, level: 'up' | 'ok' | 'down'): Promise<void> {
  // [評分] 只有 AI 能評分（user 2026-06-15）：webview 使用者＝人類 → 一律擋。AI 評分走
  // AI 自動評（依互動品質）或外部 AI 客戶端，不經這個人類指令入口。
  const selfId = this.resolveMemberId(this.selfName());
  const selfMember = this.authMembers.find((x) => x.id === selfId);
  if (!selfMember || selfMember.type === 'human') {
    this.postLocalNotice('評分系統只開放 AI 成員（人類不參與評分；AI 會依互動品質自動評分）。');
    return;
  }
  const label = level === 'up' ? '讚' : level === 'ok' ? '平' : '倒讚';
  if (!arg) {
    this.postLocalNotice(`用法：/${label} @對象（對最近一次與該成員的互動評分；再按同一個＝取消）`);
    return;
  }
  const target = this.resolveMemberByName(arg);
  if (!target) {
    this.postLocalNotice(`找不到成員「${arg.replace(/^@+/, '')}」。打 /who 看成員名單。`);
    return;
  }
  if (target.id === selfId) {
    this.postLocalNotice('不能評自己（擋自我偏好）。');
    return;
  }
  const { counts, applied } = await setRating(this.ctx, this.channel, selfId, target.id, level);
  const who = target.name || target.id;
  const verb = applied === 'cleared' ? `取消了對「${who}」的${label}`
    : applied === 'changed' ? `把對「${who}」的評分改成${label}`
      : `對「${who}」按了${label}`;
  // 評分公開（user 2026-06-15）：直接回報累計數。
  this.postLocalNotice(`已${verb}。（${who} 目前：${counts.up} 讚 ${counts.ok} 平 ${counts.down} 倒讚）`);
  glog(`peer-rating ${applied} rater="${selfId}" target="${target.id}" level=${level}`);
}

private async autoRateInteraction(raterFrom: string, targetId: string): Promise<void> {
  const raterId = this.resolveMemberId(raterFrom);
  if (raterId === targetId) return; // 不評自己
  const rater = this.authMembers.find((x) => x.id === raterId);
  if (!rater || rater.type === 'human') return; // 只有 AI 能評（發起方是人類 → 不評）
  await setRating(this.ctx, this.channel, raterId, targetId, 'up');
  this.pushMembers(); // 計數更新 → 重推 webview，每則訊息＋個資卡即時反映
  glog(`peer-rating auto up rater="${raterId}" target="${targetId}"`);
}

private normalizeBackend(backend: string): string {
  // [1.9.0 紅藍稽核 M-sec3] member.backend 來自伺服器推送，未驗證即注入 Sancio 請求
  // = SSRF 缺口（攻陷的伺服器可把 backend 設成 URL 把流量導向攻擊者 LLM proxy）。
  // 白名單：只接受 'provider:model' / 'provider/model' 純 slug，含 :// 或空白一律
  // 退回安全預設（不讓任意字串穿到 runtime）。
  const raw = backend.trim();
  if (!raw || raw.includes('://') || /\s/.test(raw) || raw.length > 120) {
    return 'anthropic/claude-opus-4-8';
  }
  // Members may store either 'anthropic:claude-opus-4-8' (colon) or
  // 'anthropic/claude-opus-4-8' (slash). Session.model + getActiveModel use
  // the slash form, so normalize colon → slash.
  return raw.replace(/:/, '/');
}

private resolveProviderId(): string {
  const providers = loadProviders();
  if (providers.some((p) => p.id === 'ai-king-backend')) return 'ai-king-backend';
  return providers[0]?.id || 'ai-king-backend';
}

private buildGroupMemorySeed(): string {
  let history: ChannelMessage[] = [];
  try {
    history = readSince(this.channel, 0);
  } catch {
    history = [];
  }
  const lines = history
    .filter((m) => m && typeof m.text === 'string' && m.text.trim())
    .filter((m) => (m.type || 'msg') === 'msg')
    .map((m) => `${m.from || '（不明）'}：${m.text.trim()}`);
  // Cap the seed so a long room doesn't blow the first turn's context.
  const MAX_LINES = 200;
  const trimmed =
    lines.length > MAX_LINES ? lines.slice(-MAX_LINES) : lines;
  const omitted = lines.length - trimmed.length;
  const head =
    omitted > 0
      ? `（以下是群組「${this.channel}」較近的 ${trimmed.length} 則對話，較早的 ${omitted} 則已略過）`
      : `（以下是群組「${this.channel}」的歷史對話，供你延續脈絡）`;
  if (trimmed.length === 0) {
    return `（群組「${this.channel}」目前還沒有可帶入的歷史對話。）`;
  }
  return `${head}\n\n${trimmed.join('\n')}`;
}

private async openAgentChat(member: Member): Promise<void> {
  // [user 2026-06-21] 內建 AI King Agent（aiking）+ Base Agent（clean）都能開「單獨對話」＝
  // 本機 1:1 私聊（store.create 落本機 session、完全不經 VPS 群組廣播 → 只有這台裝置的人聊得到、
  // 外部群組成員看不到）。解決「群組對話歷史刪了就沒入口再單獨找這位內建 AI」。外部 ACP/Hermes/
  // cloud-persona 仍不支援（它們無本機 clean/sancio 後端可直連）。
  const isAiking = member.architecture === 'aiking';
  const isBase = member.architecture === 'clean';
  if (!isAiking && !isBase) {
    void vscode.window.showWarningMessage(
      'AI 群組：只有內建 AI King Agent / Base Agent 成員能開單獨對話。',
    );
    return;
  }

  // provider / model / stack 依架構決定：
  //   AI King Agent → 本機 Sancio 大腦（providerId=ai-king-backend 持 BYOK key、model verbatim 轉發）。
  //   Base Agent    → 直連 backend 真實 provider 的 clean 純單輪，與「群組回話」同一份解析
  //                   （resolveBaseAgentBackend：從 'provider:model' 拆 provider + 取對應 key），
  //                   故單獨對話用的 provider/key 與它在群組裡回話完全一致、不會解錯成 ai-king-backend。
  let providerId: string;
  let model: string;
  let stack: string;
  if (isAiking) {
    model = this.normalizeBackend(member.backend || '');
    if (!model) {
      void vscode.window.showWarningMessage(
        `AI 群組：「${member.name}」尚未設定 LLM 後端，無法開單獨對話。請先在群組設定它的 LLM 後端。`,
      );
      return;
    }
    providerId = this.resolveProviderId();
    stack = 'sancio';
  } else {
    const resolved = await resolveBaseAgentBackendCore(this.ctx, member);
    if (!resolved.provider || !resolved.model) {
      void vscode.window.showWarningMessage(
        `AI 群組：「${member.name}」找不到可用的 LLM 後端，無法開單獨對話。請先在設定加一個 LLM 後端。`,
      );
      return;
    }
    providerId = resolved.provider.id;
    model = resolved.model;
    stack = 'clean';
  }

  // Pin the active knobs the chat window reads at send time.
  await setActiveProviderId(this.ctx, providerId);
  await setActiveModel(this.ctx, model);
  await vscode.workspace
    .getConfiguration('aiKing')
    .update('stack', stack, vscode.ConfigurationTarget.Global);

  // Create the private session, seeded with the group's memory so the 1:1
  // conversation continues the room's context.
  const store = sessionStoreFor(this.ctx);
  await store.init();
  const session = await store.create(
    `與 ${member.name} 單獨對話`,
    model,
    stack,
    'edits',
    providerId,
  );
  const seed = this.buildGroupMemorySeed();
  await store.append(session.id, {
    role: 'system',
    content: seed,
    ts: Date.now(),
  });

  await setActiveSessionId(this.ctx, session.id);

  try {
    await vscode.commands.executeCommand('aiKing.chat.openSession', session.id);
  } catch (e: unknown) {
    void vscode.window.showErrorMessage(
      `AI 群組：開啟單獨對話失敗 — ${e instanceof Error ? e.message : String(e)}`,
    );
  }
}

private async disbandWithConfirm(): Promise<void> {
  if (this.selfRole() !== 'owner') {
    void vscode.window.showWarningMessage('AI 群組：只有群主能解散群組。');
    return;
  }
  const room = this.channel;
  const ok = await vscode.window.showWarningMessage(
    `確定解散群組「${room}」？`,
    {
      modal: true,
      detail: '這個群組的對話紀錄會永久刪除，無法復原。線上群組的對方仍保有他們自己那一份。',
    },
    '解散群組',
  );
  if (ok !== '解散群組') return;
  // Authoritative dissolve: the server kicks every SSE connection, deletes the
  // room, and broadcasts room.dissolve to all clients. We do NOT mark/append
  // anything locally — the server is the source of truth. AWAIT the POST so the
  // server has finished kicking + broadcasting BEFORE we tear down locally; no
  // hardcoded delay guess (the resolved POST already means peers were notified).
  try {
    await this.authority?.dissolve();
  } catch (e: unknown) {
    // Surface but don't abort: the owner still wants their local copy gone.
    void vscode.window.showWarningMessage(
      `AI 群組：解散請求未確認（${e instanceof Error ? e.message : String(e)}）；仍會移除你本機的副本。`,
    );
  }
  BridgePanel.closeForChannel(room);
  forceStopRelayBridge(room); // legacy no-op in authority mode
  deleteRoom(room);
  try {
    await vscode.commands.executeCommand('aiKing.home.focus');
  } catch {
    /* sidebar will refresh on next open */
  }
}

private async leaveWithConfirm(): Promise<void> {
  const room = this.channel;
  // [2026-06-18 user 防呆按鈕層] 群主不能離開——UI 已讓群主在抽屜看不到「離開」鈕(依身分只顯示「解散群組」
  // ＋「轉讓群主」)，這裡只是 host 防禦：萬一真被呼叫就提示、不做「點了才擋」的引導流程(按鈕層才是主力防呆)。
  if (this.selfRole() === 'owner') {
    void vscode.window.showWarningMessage('AI 群組：群主不能離開群組。請用「解散群組」收掉整個群組，或在群組設定／成員卡「轉讓群主」降為管理員後再離開。');
    return;
  }
  const ok = await vscode.window.showWarningMessage(
    `離開群組「${room}」？`,
    { modal: true, detail: '只移除你這台電腦上的副本，不影響群組其他人。' },
    '離開群組',
  );
  if (ok !== '離開群組') return;
  // Tell the server I'm leaving so it drops me from the roster + broadcasts a
  // member remove to the others, THEN tear down my local copy. If the leave
  // POST fails (server unreachable), do NOT delete locally — otherwise the
  // server still lists me (peers see a ghost) while my data is gone with no way
  // to retry. Offer an explicit "force leave anyway" instead of silent loss.
  let leftOk = false;
  try {
    const r = await this.authority?.leave(this.selfName());
    // (self-leave: the server derives the caller from our sid-bound socket)
    leftOk = !!r && (r.ok === true || Array.isArray(r.members) || r.left === true);
  } catch {
    leftOk = false;
  }
  if (!leftOk) {
    const force = await vscode.window.showWarningMessage(
      'AI 群組：離開請求未送達伺服器（可能離線）。其他人可能仍看得到你。要強制移除本機副本嗎？',
      { modal: true, detail: '強制移除只刪你這台電腦的資料；下次伺服器恢復時請對方手動把你移除。' },
      '強制離開',
    );
    if (force !== '強制離開') return; // keep local data so the user can retry
  }
  BridgePanel.closeForChannel(room);
  forceStopRelayBridge(room); // legacy no-op in authority mode
  deleteRoom(room);
  try {
    await vscode.commands.executeCommand('aiKing.home.focus');
  } catch {
    /* sidebar refresh best-effort */
  }
}

private async transferOwnerWithPick(): Promise<void> {
  if (this.selfRole() !== 'owner') {
    void vscode.window.showWarningMessage('AI 群組：只有群主能轉讓群主。');
    return;
  }
  const candidates = this.authMembers.filter((m) => m.id !== this.selfName() && m.type === 'human');
  if (!candidates.length) {
    void vscode.window.showWarningMessage('AI 群組：沒有可接手的真人成員（群主只能轉給真人）。要直接收掉群組請用「解散群組」。');
    return;
  }
  const pick = await showQuickPickEsc(
    candidates
      .sort((a, b) => ((a.role === 'admin' ? 0 : 1) - (b.role === 'admin' ? 0 : 1)))
      .map((m) => ({
        label: m.name || m.id,
        description: (m.role === 'admin' ? '管理員' : '成員') + (m.name && m.name !== m.id ? ` · ${m.id}` : ''),
        id: m.id,
      })),
    { placeHolder: '把群主轉讓給誰？建議選在線/可靠的成員——轉給已離開的人可能導致沒人能管理群組。轉讓後你降為管理員、即可離開。', ignoreFocusOut: true },
  );
  if (!pick) return;
  await this.transferOwnerTo(pick.id, pick.label);
}

private async transferOwnerTo(id: string, label: string): Promise<void> {
  if (this.selfRole() !== 'owner') {
    void vscode.window.showWarningMessage('AI 群組：只有群主能轉讓群主。');
    return;
  }
  const target = this.authMembers.find((m) => m.id === id);
  if (!target || target.type !== 'human') {
    void vscode.window.showWarningMessage('AI 群組：群主只能轉讓給真人成員（AI 不能當群主）。');
    return;
  }
  const ok = await vscode.window.showWarningMessage(
    `確定把群主轉讓給「${label}」？`,
    { modal: true, detail: '轉讓後對方成為群主（能解散群組、管理成員、轉讓群主），你降為管理員。之後你就能從 ⋮ →「離開群組」離開。' },
    '轉讓群主',
  );
  if (ok !== '轉讓群主') return;
  const r = await this.authority?.transferOwner(id);
  if (r && typeof r.error === 'string') {
    void vscode.window.showWarningMessage(`AI 群組：轉讓群主失敗 — ${r.error}`);
    return;
  }
  void vscode.window.showInformationMessage(`已把群主轉讓給「${label}」。你現在是管理員，可從 ⋮ →「離開群組」離開。`);
}

private staleMemberDays(): number {
  const d = vscode.workspace.getConfiguration('aiKing').get<number>('staleMemberDays', 30);
  // No min/max clamp (user 2026-06-11「自由設定幾日，無 min/max」): any 0+ value is
  // honoured; only a non-number / negative falls back to 30. 0 = flag every offline member.
  return typeof d === 'number' && d >= 0 ? d : 30;
}

private staleCleanupEnabled(): boolean {
  return vscode.workspace.getConfiguration('aiKing').get<boolean>('staleMemberCleanupEnabled', true) !== false;
}

private staleMembers(): Member[] {
  const cutoff = Date.now() - this.staleMemberDays() * 24 * 60 * 60 * 1000;
  const me = this.selfName();
  return this.authMembers.filter(
    (m) =>
      m.id !== me &&
      (m.role || 'member') !== 'owner' &&
      typeof m.lastSeenAt === 'number' &&
      (m.lastSeenAt as number) < cutoff,
  );
}

private maybeHintStale(): void {
  if (this.staleHinted || !this.canManage() || !this.staleCleanupEnabled()) return;
  const stale = this.staleMembers();
  if (!stale.length) return;
  this.staleHinted = true;
  void vscode.window
    .showInformationMessage(
      `AI 群組「${this.channel}」：有 ${stale.length} 位成員超過 ${this.staleMemberDays()} 天沒上線。要清理嗎？`,
      '清理',
      '稍後',
    )
    .then((pick) => { if (pick === '清理') void this.cleanupStaleMembers(); });
}

private async cleanupStaleMembers(): Promise<void> {
  if (this.authStatus === 'dissolved') {
    void vscode.window.showWarningMessage('AI 群組：群組已解散，無法清理成員。');
    return;
  }
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能清理成員。');
    return;
  }
  const days = this.staleMemberDays();
  const stale = this.staleMembers();
  if (!stale.length) {
    void vscode.window.showInformationMessage(
      `AI 群組：沒有超過 ${days} 天沒上線的成員（只算有上線紀錄的成員）。`,
    );
    return;
  }
  const dayOf = (ts: number) => Math.floor((Date.now() - ts) / (24 * 60 * 60 * 1000));
  const picks = await showQuickPickEsc(
    stale.map((m) => ({
      label: m.name || m.id,
      description: `${dayOf(m.lastSeenAt as number)} 天沒上線`,
      detail: m.type === 'human' ? '👤 人類' : m.type === 'cloud-persona' ? '✨ 數位人格' : '🤖 AI',
      id: m.id,
      picked: true,
    })),
    {
      placeHolder: `選要移除哪些離線超過 ${days} 天的成員（預設全選、可多選；按 ESC 取消，不會自動刪）`,
      canPickMany: true,
      ignoreFocusOut: true,
    },
  );
  if (!picks || !picks.length) return;
  const ok = await vscode.window.showWarningMessage(
    `確定移除這 ${picks.length} 位離線過久的成員？`,
    { modal: true, detail: picks.map((p) => p.label).join('、') + '\n\n（只從成員名冊移除；他們過去的訊息仍留在群組歷史裡。）' },
    '移除',
  );
  if (ok !== '移除') return;
  let removed = 0;
  for (const p of picks) {
    try { await this.authority?.kick(p.id); removed++; } catch { /* best-effort; broadcast updates the rest */ }
  }
  void vscode.window.showInformationMessage(`AI 群組：已移除 ${removed} 位離線過久的成員。`);
}

private async staleMemberMenu(): Promise<void> {
  if (this.authStatus === 'dissolved') {
    void vscode.window.showWarningMessage('AI 群組：群組已解散，無法設定。');
    return;
  }
  if (!this.canManage()) {
    void vscode.window.showWarningMessage('AI 群組：只有群主或管理員能設定離線清理。');
    return;
  }
  const enabled = this.staleCleanupEnabled();
  const days = this.staleMemberDays();
  const n = enabled ? this.staleMembers().length : 0;
  const items: Array<{ label: string; detail: string; act: string }> = [
    { label: enabled ? '🟢 功能狀態：開啟' : '⚪ 功能狀態：關閉', detail: '點此切換開／關（關閉後不再提示、不主動清理）', act: 'toggle' },
    { label: `📅 門檻天數：${days} 天`, detail: '點此修改 — 可填任意天數，沒有上下限', act: 'days' },
  ];
  if (enabled) {
    items.push({ label: `🧹 立即清理（目前 ${n} 位超過 ${days} 天沒上線）`, detail: n ? '列出並選擇要移除的成員' : '目前沒有符合的成員', act: 'run' });
  }
  const pick = await showQuickPickEsc(items, {
    placeHolder: `離線過久成員清理 — 設定 / 執行（群組「${this.channel}」）`,
    ignoreFocusOut: true,
  });
  if (!pick) return;
  const cfg = vscode.workspace.getConfiguration('aiKing');
  if (pick.act === 'toggle') {
    await cfg.update('staleMemberCleanupEnabled', !enabled, vscode.ConfigurationTarget.Global);
    void vscode.window.showInformationMessage(`離線清理功能已${!enabled ? '開啟' : '關閉'}。`);
    return;
  }
  if (pick.act === 'days') {
    const input = await showInputBoxEsc({
      prompt: '幾天沒上線就算「過久」？可填任意正整數，沒有上下限（填 0 = 把所有離線成員都列入）',
      value: String(days),
      ignoreFocusOut: true,
      validateInput: (v) => {
        const num = Number(v);
        return (v.trim() !== '' && Number.isFinite(num) && num >= 0) ? null : '請填一個 0 或以上的數字';
      },
    });
    if (input === undefined) return;
    await cfg.update('staleMemberDays', Number(input), vscode.ConfigurationTarget.Global);
    void vscode.window.showInformationMessage(`離線門檻已設為 ${Number(input)} 天。`);
    return;
  }
  if (pick.act === 'run') {
    await this.cleanupStaleMembers();
  }
}

private static genId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
}

