function pickStep<T extends vscode.QuickPickItem>(
  items: T[],
  opts: { title: string; step: number; total: number; placeholder: string; canBack: boolean },
): Promise<T | typeof STEP_BACK | undefined> {
  return new Promise((resolve) => {
    const qp = vscode.window.createQuickPick<T>();
    qp.title = opts.title; qp.step = opts.step; qp.totalSteps = opts.total;
    qp.placeholder = opts.placeholder; qp.items = items; qp.ignoreFocusOut = true;
    qp.buttons = opts.canBack ? [vscode.QuickInputButtons.Back] : [];
    let settled = false;
    qp.onDidTriggerButton((b) => { if (b === vscode.QuickInputButtons.Back) { settled = true; resolve(STEP_BACK); qp.hide(); } });
    qp.onDidAccept(() => { const it = qp.selectedItems[0]; if (it) { settled = true; resolve(it); qp.hide(); } });
    qp.onDidHide(() => { if (!settled) resolve(undefined); qp.dispose(); });
    qp.show();
  });
}

function inputStep(opts: {
  title: string; step: number; total: number; prompt: string; value?: string;
  placeholder?: string; canBack: boolean; validate?: (v: string) => string | undefined;
}): Promise<string | typeof STEP_BACK | undefined> {
  return new Promise((resolve) => {
    const ib = vscode.window.createInputBox();
    ib.title = opts.title; ib.step = opts.step; ib.totalSteps = opts.total;
    ib.prompt = opts.prompt; ib.value = opts.value || ''; ib.placeholder = opts.placeholder || '';
    ib.ignoreFocusOut = true;
    ib.buttons = opts.canBack ? [vscode.QuickInputButtons.Back] : [];
    let settled = false;
    ib.onDidTriggerButton((b) => { if (b === vscode.QuickInputButtons.Back) { settled = true; resolve(STEP_BACK); ib.hide(); } });
    ib.onDidAccept(() => {
      const v = ib.value.trim();
      const err = opts.validate ? opts.validate(v) : (v ? undefined : '請輸入');
      if (err) { ib.validationMessage = err; return; }
      settled = true; resolve(v); ib.hide();
    });
    ib.onDidHide(() => { if (!settled) resolve(undefined); ib.dispose(); });
    ib.show();
  });
}

export function registerBridgePanel(
  ctx: vscode.ExtensionContext,
  store: SessionStore,
): void {
  // [1.14.0 對抗審查 critical#1] 注入共用 namespace-aware store＝群組私聊讀寫對齊當前帳號 profile。
  sharedSessionStore = store;
  // [1.13.x] 跨擴充重載/更新保留群組視窗：註冊 WebviewPanelSerializer，VS Code 重載後
  // 用 webview 存的 room 恢復面板（無 room 則 dispose 空殼、不留死 tab）。
  ctx.subscriptions.push(
    vscode.window.registerWebviewPanelSerializer(BridgePanel.viewType, {
      async deserializeWebviewPanel(panel, state) {
        const raw = (state as { room?: unknown } | undefined)?.room;
        const room = typeof raw === 'string' ? raw : '';
        if (!room) { panel.dispose(); return; }
        BridgePanel.revive(ctx, room, panel);
      },
    }),
  );
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.bridge.open', async (channel?: string) => {
      // With a room name → open it directly.
      if (typeof channel === 'string' && channel.trim()) {
        BridgePanel.createOrShow(ctx, channel.trim());
        return;
      }
      // New-group WIZARD. ESC at ANY step cancels the WHOLE flow (nothing is
      // created); every step after the first has a ← Back button. The room is
      // created only AFTER all steps succeed — so cancelling never leaves a
      // half-built room (the old code ran createRoom before the founder step, so
      // ESC there still left a stray room).
      const TOTAL = 3;
      let isOnline = false;
      let room = '';
      let founder = '群主';
      let step = 0;
      while (step < 4) {
        if (step === 0) {
          const kind = await pickStep(
            [
              { label: '本機群組', detail: '只在這台電腦上，不連網', mode: 'local' },
              { label: '線上群組', detail: '可以邀別台電腦的人一起加入', mode: 'online' },
            ] as Array<vscode.QuickPickItem & { mode: string }>,
            { title: '建立 AI 群組', step: 1, total: TOTAL, placeholder: '要建哪一種群組？（ESC 取消）', canBack: false },
          );
          if (kind === undefined || kind === STEP_BACK) return;
          isOnline = kind.mode === 'online';
          step = 1;
        } else if (step === 1) {
          const r = await inputStep({
            title: '建立 AI 群組', step: 2, total: TOTAL,
            prompt: `新${isOnline ? '線上' : '本機'}群組名稱（什麼語言都行，別用 / \\ : * ? 等符號）`,
            value: room, placeholder: '例如 遊戲開發組 / 行銷作戰室 / 小說創作工作室', canBack: true,
            validate: (v) => (!v || !v.trim() ? '請輸入群組名稱' : (/[\\/:*?"<>|]/.test(v) ? '不能含 / \\ : * ? " < > | 這些符號' : undefined)),
          });
          if (r === undefined) return;
          if (r === STEP_BACK) { step = 0; continue; }
          room = r; step = 2;
        } else if (step === 2) {
          const r = await inputStep({
            title: '建立 AI 群組', step: 3, total: TOTAL,
            prompt: '你是這個群組的群主，要顯示什麼名字？',
            value: founder, canBack: true,
            validate: (v) => (v ? undefined : '請輸入名稱'),
          });
          if (r === undefined) return;
          if (r === STEP_BACK) { step = 1; continue; }
          founder = r; step = 3;
        } else {
          // step 3 — for an ONLINE room, ALWAYS let the user confirm / change the
          // server (they may run several VPSs and want to pick per group). Show the
          // current server + a change option. "current" on a LOCAL url = only-this-
          // machine (others can't reach it), flagged in the detail.
          if (isOnline) {
            const cur = authorityUrl();
            const isLocalCur = /(?:\/\/)?(?:127\.0\.0\.1|localhost)\b/.test(cur);
            const go = await pickStep(
              [
                { label: '✅ 用目前的伺服器', detail: isLocalCur ? '本機（只有自己連得到）— 要拉別人進來請改用遠端' : cur, v: 'current' },
                { label: '⚙ 改用別的伺服器…', detail: '一鍵架我的 VPS ／ 換網址 ／ 區網 ／ 本機', v: 'change' },
              ] as Array<vscode.QuickPickItem & { v: string }>,
              { title: '建立 AI 群組', step: 3, total: TOTAL, placeholder: `線上群組「${room}」要用哪個伺服器？`, canBack: true },
            );
            if (go === undefined) return;
            if (go === STEP_BACK) { step = 2; continue; }
            if (go.v === 'change') {
              const ok = await runAuthorityPicker(ctx, `線上群組「${room}」的伺服器位置`);
              if (!ok) continue; // 取消改伺服器 → 回此步重選
            }
          }
          break; // 所有步驟完成
        }
      }
      // ── All inputs done — create NOW (ESC at any step never reaches here) ──
      // [1.8.0 §10.3-3] 由房名解析房間：user 重打了一個含中文/空格的舊房名（1.6.4
      // 舊清洗規則時代建的）時，新規則 id 沒資料夾 → fallback 命中 legacy id → 沿用
      // 原資料夾 / 原 token / 原伺服器房（不遷移、不改名、只映射）。
      room = resolveRoomId(room) || room;
      createRoom(room);
      writeIdentity(room, { me: founder, role: 'owner' });
      // AUTHORITY MODE create-group:
      //  1) ensure the room's per-room token exists (.token) — gates authority
      //     access AND derives the E2E ROOM_KEY = sha256(room:token).
      //  2) start the LOCAL authority server (no-op if authorityUrl is remote).
      //  3) online rooms also get a .relay.json so isOnlineRoom()=true → 🌐 title
      //     and the cross-machine invite path is offered. The relay BRIDGE is not
      //     started — authority connects directly.
      const token = getRoomToken(room);
      // E2E ROOM_KEY = sha256(room:token). An empty token would make encryptText
      // silently passthrough plaintext (server stores cleartext = E2E defeated).
      // getRoomToken() returns '' on file I/O failure — fail loudly, don't ship a
      // half-built room that runs unencrypted.
      if (!token || !token.trim()) {
        void vscode.window.showErrorMessage(
          `AI 群組：房間鑰匙生成失敗（磁碟空間或檔案權限問題），無法建立「${room}」的 E2E 加密。請排除後重試。`,
        );
        try { deleteRoom(room); } catch { /* best-effort cleanup of the half state */ }
        return;
      }
      ensureAuthorityServer(authorityUrl());
      let onlineOk = true;
      if (isOnline) {
        onlineOk = writeRelayConfig(room, {
          relay: authorityUrl(), token, me: founder, role: 'owner',
        }) && isOnlineRoom(room);
      }
      // Open the panel (its constructor connects to the authority SSE stream),
      // then register the founder on the server — that broadcasts the member add
      // so any peer who joins converges to see the owner. No local roster write.
      const inst = BridgePanel.createOrShow(ctx, room);
      await inst.joinSelf({
        id: founder, name: founder, type: 'human',
        role: 'owner', avatar: '', joinedAt: Date.now(),
      });
      // Push the new room onto the Home list right away (don't wait for a
      // visibility toggle) — fixes "歷史沒這聊天室" after creating a group here.
      void vscode.commands.executeCommand('aiKing.home.refresh');
      if (isOnline) {
        if (!onlineOk) {
          void vscode.window.showErrorMessage(
            `線上群組「${room}」設定寫入失敗，跨機不會生效。請重建。`,
          );
        } else {
          // Be honest about WHICH server: a local authorityUrl means the room is
          // hosted on THIS machine (no VPS is hardcoded anywhere), not a remote one.
          const auth = authorityUrl();
          const localAuth = /(?:\/\/)?(?:127\.0\.0\.1|localhost)\b/.test(auth);
          void vscode.window.showInformationMessage(
            localAuth
              ? `已建立線上群組「${room}」🖥 伺服器跑在你本機（127.0.0.1，沒有寫死任何 VPS）。用「＋成員 → 線上邀請」邀對方；要長期跨機保存可改用自架 VPS。`
              : `已建立線上群組「${room}」🌐 已連上你設定的伺服器（${auth}）。用「＋成員 → 線上邀請」產生連線碼給對方。`,
          );
        }
      } else {
        void vscode.window.showInformationMessage(
          `已建立本機群組「${room}」🖥️ 僅這台電腦、不跨機。要跨機請改建「線上群組」。`,
        );
      }
    }),
    vscode.commands.registerCommand('aiKing.bridge.join', () => {
      void BridgePanel.joinFromInvite(ctx);
    }),
    vscode.commands.registerCommand('aiKing.group.notifyLevel', (channel?: string) => {
      void BridgePanel.pickNotifyLevelFor(typeof channel === 'string' ? channel : undefined);
    }),
    // [1.13.x 群組連動] 對話視窗改 Agent/Model 後由 chat-panel 觸發：把新身份立即同步進群組
    // 名冊（不等 4s 節流）。command 永遠註冊（即使一個群組面板都沒開），handler 遍歷空集合 no-op。
    vscode.commands.registerCommand('aiKing.internal.syncGroupIdentity', (sessionId?: string) => {
      void BridgePanel.syncIdentityForSession(typeof sessionId === 'string' ? sessionId : undefined);
    }),
  );
}

async deserializeWebviewPanel(panel, state) {
  const raw = (state as { room?: unknown } | undefined)?.room;
  const room = typeof raw === 'string' ? raw : '';
  if (!room) { panel.dispose(); return; }
  BridgePanel.revive(ctx, room, panel);
},

function parseHandoff(raw: string): CompactHandoff | null {
  if (!raw) return null;
  let text = raw.trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) text = fence[1].trim();
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    const obj = JSON.parse(text.slice(start, end + 1)) as {
      index?: unknown;
      summary?: unknown;
    };
    const index = typeof obj.index === 'string' ? obj.index.trim() : '';
    const summary = typeof obj.summary === 'string' ? obj.summary.trim() : '';
    if (!index || !summary) return null;
    return { index, summary };
  } catch {
    return null;
  }
}

export interface Attachment {
  kind: 'image' | 'document';
  /** data: URL (base64-encoded content with mime prefix). */
  dataUrl: string;
  mimeType: string;
  name: string;
}

function parseAttachment(raw: unknown): Attachment | null {
  if (!raw || typeof raw !== 'object') return null;
  const r = raw as Record<string, unknown>;
  const kind = r.kind === 'image' || r.kind === 'document' ? r.kind : null;
  const dataUrl = typeof r.dataUrl === 'string' ? r.dataUrl : '';
  const mimeType = typeof r.mimeType === 'string' ? r.mimeType : '';
  const name = typeof r.name === 'string' ? r.name : '';
  if (!kind || !dataUrl.startsWith('data:') || !mimeType) return null;
  return { kind, dataUrl, mimeType, name };
}

function getNonce(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let out = '';
  for (let i = 0; i < 32; i++) {
    out += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return out;
}

function stripThinkingForWire(content: string): string {
  if (typeof content !== 'string' || content.indexOf('<think') === -1) return content;
  const stripped = content.replace(THINKING_BLOCK_RE, '').trim();
  // 純思考無實答（罕見）→ 保留原文，避免送空字串 content 給 provider 報錯。
  return stripped.length > 0 ? stripped : content;
}

function firstSentenceOf(content: string): string {
  const s = String(content || '').replace(THINKING_BLOCK_RE, '').trim();
  if (/^!\[/.test(s)) return '（圖片）'; // image markdown
  const m = s.match(/^[\s\S]*?[。！？.!?\n]/);
  let first = (m ? m[0] : s).replace(/\s+/g, ' ').trim();
  if (first.length > 40) first = first.slice(0, 40) + '…';
  return first || s.slice(0, 40);
}

export class ChatPanel {
  public static readonly viewType = 'aiKing.chat';
  private static readonly panels: Map<string, ChatPanel> = new Map();

  private readonly panel: vscode.WebviewPanel;
  private readonly disposables: vscode.Disposable[] = [];
  private currentCts?: vscode.CancellationTokenSource;
  // [F 授權抽屜 1.24.32] webview 權限抽屜 promise-bridge：reqId → resolver。host 發 permission:ask 存
  //   resolver 回 Promise；webview 回 permission:decision 解決並刪。取消/關面板/reload 全 resolve deny。
  private pendingPermissions = new Map<string, (d: PermissionDecision) => void>();
  private permSeq = 0;
  // [1.7.0] connection probe + available-model resolver (shared probe path).
  private readonly statusStore = new ProviderStatusStore();
  // [C 黏一起根治 1.24.30] 每次 postState 自增的單調序號 + 「權威終態」旗標。webview 端
  // 用 renderSeq 丟棄亂序到達的「非 force」過期 state；done/error 終止時 host 主動推一個
  // forceRender:true 終態（繞過 webview ready 往返——error 回合不發 ready），webview 對
  // forceRender 一律重建（force 免疫序號閘），把樂觀泡泡/live DOM 換成 store 正本。
  // 既有 reconcile 只靠 chat.js 的 busy gate（時序競態）→ 多回合連送/亂序時整個 skip = 黏一起。
  private renderSeq = 0;
  // [未讀紅點修復 1.24.30] 對話分頁未讀計數（對齊群組 bridge-view）：AI 回應終態（done/error）
  //   時若分頁不可見則 +1 → iconPath 換成右上帶紅點的 tab-crown-unread.svg；分頁一被看到
  //   （onDidChangeViewState visible）就清零換回 tab-crown.svg。先前重構分頁圖標時只保留了
  //   群組側，對話側被弄掉（user：「未讀紅點被弄沒了」），這裡補回。
  private unread = 0;

  /**
   * [1.18.9] webview 選項單一真相源。createOrShow 與 serializer 的 deserialize 共用，
   * 確保「reload 後還原」與「首次開啟」拿到完全相同的 enableScripts + localResourceRoots。
   * ⚠ VS Code 還原 serializer 的 panel 時 **不保留** webview.options——deserialize 沒重設
   * 就會 enableScripts=false（script 全擋→卡「載入中」、chat.js 不接線）+ resource root
   * 失效（CSS 載不到→裸版堆疊），正是 reload 後對話面板破版、要關掉重開的根因。
   */
  static webviewOptions(ctx: vscode.ExtensionContext): vscode.WebviewOptions {
    return {
      enableScripts: true,
      localResourceRoots: [vscode.Uri.joinPath(ctx.extensionUri, 'media')],
    };
  }

  static createOrShow(
    ctx: vscode.ExtensionContext,
    store: SessionStore,
    sessionId: string,
  ): ChatPanel {
    const existing = ChatPanel.panels.get(sessionId);
    if (existing) {
      log.info('chat:panel:reuse', { sessionId });
      existing.panel.reveal(undefined, false);
      void existing.postState();
      return existing;
    }
    log.info('chat:panel:create', { sessionId });

    const column = vscode.window.activeTextEditor
      ? vscode.window.activeTextEditor.viewColumn
      : vscode.ViewColumn.One;

    const panel = vscode.window.createWebviewPanel(
      ChatPanel.viewType,
      '對話 —',  // 開窗瞬間的暫定名；postState 後改成「對話 — 名稱」
      column || vscode.ViewColumn.One,
      {
        ...ChatPanel.webviewOptions(ctx),
        retainContextWhenHidden: true,
      },
    );

    const inst = new ChatPanel(ctx, store, sessionId, panel);
    ChatPanel.panels.set(sessionId, inst);
    return inst;
  }

  /** [1.13.x] 重載恢復：用 VS Code 還回來的既有 panel 重建 inst（跨擴充更新/reload
   * 保留對話視窗、不必使用者重開）。VS Code 已保留 tab 位置，這裡只重新接線內容。 */
  static revive(
    ctx: vscode.ExtensionContext,
    store: SessionStore,
    sessionId: string,
    panel: vscode.WebviewPanel,
  ): ChatPanel {
    const inst = new ChatPanel(ctx, store, sessionId, panel);
    ChatPanel.panels.set(sessionId, inst);
    log.info('chat:panel:revive', { sessionId });
    return inst;
  }

  static closeForSession(sessionId: string): void {
    const p = ChatPanel.panels.get(sessionId);
    if (p) p.dispose();
  }

  /**
   * [1.14.0 帳號線 P1a] 關閉所有對話面板。切換 profile 命名空間時呼叫——舊命名空間的
   * sessionId 在新命名空間不存在，留著＝死面板或顯示錯資料。dispose() 會自 panels Map
   * 移除，故先快照 values 再逐一關，避免邊迭代邊刪。
   */
  static closeAll(): void {
    for (const p of [...ChatPanel.panels.values()]) p.dispose();
  }

  private constructor(
    private readonly ctx: vscode.ExtensionContext,
    private readonly store: SessionStore,
    private readonly sessionId: string,
    panel: vscode.WebviewPanel,
  ) {
    this.panel = panel;
    // [1.24.18 user] 分頁圖示＝複合圖標 tab-conv.svg（AI King 皇冠 ＋ 右下「對話」角標，用左側欄
    //   同款 conv.svg glyph）；標題只接對話名（圖標已表意、不再加 emoji/破折號）。群組同理 tab-group.svg。
    this.panel.iconPath = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'icons', 'tab-crown.svg');
    this.panel.webview.html = this.buildHtml();
    this.panel.webview.onDidReceiveMessage(
      (msg) => void this.onMessage(msg),
      null,
      this.disposables,
    );
    this.panel.onDidDispose(() => this.dispose(), null, this.disposables);
    // [未讀紅點修復 1.24.30] 分頁被看到（visible）就清未讀、換回無紅點皇冠（對齊群組面板）。
    this.panel.onDidChangeViewState((e) => {
      if (e.webviewPanel.visible && this.unread > 0) {
        this.unread = 0;
        this.updateUnreadIcon();
      }
    }, null, this.disposables);
    this.disposables.push(store.onDidChange(() => void this.postState()));
    this.disposables.push(
      vscode.workspace.onDidChangeConfiguration((e) => {
        // [1.8.0 §13] interface-language switch → re-push i18n:lang so the
        // webview re-applies its dictionary live (no panel reload needed).
        if (e.affectsConfiguration('aiKing.language')) {
          void this.pushLang();
        }
        if (e.affectsConfiguration('aiKing')) {
          void this.postState();
          void this.pushAvailableModels();
        }
      }),
    );
    // [1.7.0] re-push connStatus when the active provider's probe result lands.
    this.disposables.push(
      this.statusStore.onDidChange((providerId) => {
        if (providerId === getActiveProviderId(this.ctx)) {
          void this.pushConnStatus();
        }
        void this.pushAvailableModels();
      }),
    );

    void setActiveSessionId(ctx, sessionId);
    log.info('chat:panel:init:start', { sessionId });
    // [1.8.0 §13] push the interface language first so dynamic renders that
    // follow (state/models/status) already paint in the right language.
    void this.pushLang();
    void this.postState();
    // [1.7.0] kick off the model list + a live connection probe on open.
    void this.pushAvailableModels();
    void this.refreshConnStatus();
    // [1.9.3] 這串是 async void（pushLang/postState/...），這裡只能記「已派發」；
    // 真正 init 完成由 webview 收到首個 state 後的 webview:first-state trace 界定。
    log.info('chat:panel:init:dispatched', { sessionId });
  }

  /** [1.8.0 §13] Push the current `aiKing.language` to the webview engine. */
  private async pushLang(): Promise<void> {
    await this.panel.webview.postMessage({ type: 'i18n:lang', lang: uiLang() });
  }

  dispose(): void {
    this.currentCts?.cancel();
    this.currentCts = undefined;
    // [F 授權抽屜 1.24.32] 面板關閉清掉所有待決權限＝一律 deny，防 gate 永遠等不到回覆卡死 tool loop。
    for (const r of this.pendingPermissions.values()) { try { r('deny'); } catch { /* ignore */ } }
    this.pendingPermissions.clear();
    this.statusStore.dispose();
    ChatPanel.panels.delete(this.sessionId);
    this.panel.dispose();
    while (this.disposables.length) {
      const d = this.disposables.pop();
      if (d) d.dispose();
    }
  }

