   *  對齊群組 bridge-view.updateUnreadIcon。 */
  private updateUnreadIcon(): void {
    const name = this.unread > 0 ? 'tab-crown-unread.svg' : 'tab-crown.svg';
    try {
      this.panel.iconPath = vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'icons', name);
