  // [F 授權抽屜 1.24.32] 對話面板權限提示器（gate.ts 的 prompter）：postMessage 給 webview 彈底部抽屜
  //   → 回 Promise<decision>。host 先算白話工具名+風險等級（webview 純渲染）。取消（Stop/對話取消）→deny。
  private askPermissionInWebview(req: PermissionRequest): Promise<PermissionDecision> {
    const TOOL_DISPLAY: Record<string, string> = {
      read_file: '讀取檔案', list_dir: '列出目錄', write_file: '寫入檔案',
      run_bash: '執行指令', web_search: '聯網搜尋', web_fetch: '抓取網頁',
    };
    const norm = normalizeToolName(req.tool);
    const bare = norm.replace(/^custom:/, '');
    const label = TOOL_DISPLAY[bare] || bare;
    let risk = 'caution';
    try { risk = classifyRisk({ tool: norm, args: req.args }).level; } catch { /* 預設 caution */ }
    const reqId = 'perm-' + (++this.permSeq);
    return new Promise<PermissionDecision>((resolve) => {
      let settled = false;
      let sub: vscode.Disposable | undefined;
      const done = (d: PermissionDecision) => {
        if (settled) return;
        settled = true;
        this.pendingPermissions.delete(reqId);
        try { sub?.dispose(); } catch { /* ignore */ }
        resolve(d);
      };
      this.pendingPermissions.set(reqId, done);
      sub = this.currentCts?.token.onCancellationRequested(() => done('deny'));
      let argsStr = '';
      try { argsStr = JSON.stringify(req.args, null, 2); } catch { argsStr = String(req.args); }
      if (argsStr.length > 1200) argsStr = argsStr.slice(0, 1200) + '…';
      void this.panel.webview.postMessage({
        type: 'permission:ask',
        reqId,
        tool: req.tool,
        label,
        risk,
        args: argsStr,
        context: req.context || '',
        forcePrompt: !!req.forcePrompt,
      });
    });
  }

  private async postState(opts?: { forceRender?: boolean }): Promise<void> {
