  private readonly ctx: vscode.ExtensionContext,
  private readonly store: SessionStore,
  private readonly sessionId: string,
  panel: vscode.WebviewPanel,
) {
  this.panel = panel;
  // [1.24.18 user] 分頁圖示＝複合圖標 tab-conv.svg（AI King 皇冠 ＋ 右下「對話」角標，用左側欄
  //   同款 conv.svg glyph）；標題只接對話名（圖標已表意、不再加 emoji/破折號）。群組同理 tab-group.svg。
  this.panel.iconPath = vscode.Uri.joinPath(ctx.extensionUri, 'media', 'icons', 'tab-crown.svg');
  this.panel.webview.html = this.buildHtml();
  this.panel.webview.onDidReceiveMessage(
    (msg) => void this.onMessage(msg),
    null,
    this.disposables,
  );
  this.panel.onDidDispose(() => this.dispose(), null, this.disposables);
  // [未讀紅點修復 1.24.30] 分頁被看到（visible）就清未讀、換回無紅點皇冠（對齊群組面板）。
  this.panel.onDidChangeViewState((e) => {
    if (e.webviewPanel.visible && this.unread > 0) {
      this.unread = 0;
      this.updateUnreadIcon();
    }
  }, null, this.disposables);
  this.disposables.push(store.onDidChange(() => void this.postState()));
  this.disposables.push(
    vscode.workspace.onDidChangeConfiguration((e) => {
      // [1.8.0 §13] interface-language switch → re-push i18n:lang so the
      // webview re-applies its dictionary live (no panel reload needed).
      if (e.affectsConfiguration('aiKing.language')) {
        void this.pushLang();
      }
      if (e.affectsConfiguration('aiKing')) {
        void this.postState();
        void this.pushAvailableModels();
      }
    }),
  );
  // [1.7.0] re-push connStatus when the active provider's probe result lands.
  this.disposables.push(
    this.statusStore.onDidChange((providerId) => {
      if (providerId === getActiveProviderId(this.ctx)) {
        void this.pushConnStatus();
      }
      void this.pushAvailableModels();
    }),
  );

  void setActiveSessionId(ctx, sessionId);
  log.info('chat:panel:init:start', { sessionId });
  // [1.8.0 §13] push the interface language first so dynamic renders that
  // follow (state/models/status) already paint in the right language.
  void this.pushLang();
  void this.postState();
  // [1.7.0] kick off the model list + a live connection probe on open.
  void this.pushAvailableModels();
  void this.refreshConnStatus();
  // [1.9.3] 這串是 async void（pushLang/postState/...），這裡只能記「已派發」；
  // 真正 init 完成由 webview 收到首個 state 後的 webview:first-state trace 界定。
  log.info('chat:panel:init:dispatched', { sessionId });
}

private async pushLang(): Promise<void> {
  await this.panel.webview.postMessage({ type: 'i18n:lang', lang: uiLang() });
}

dispose(): void {
  this.currentCts?.cancel();
  this.currentCts = undefined;
  // [F 授權抽屜 1.24.32] 面板關閉清掉所有待決權限＝一律 deny，防 gate 永遠等不到回覆卡死 tool loop。
  for (const r of this.pendingPermissions.values()) { try { r('deny'); } catch { /* ignore */ } }
  this.pendingPermissions.clear();
  this.statusStore.dispose();
  ChatPanel.panels.delete(this.sessionId);
  this.panel.dispose();
  while (this.disposables.length) {
    const d = this.disposables.pop();
    if (d) d.dispose();
  }
}

