private updateUnreadIcon(): void {
  const name = this.unread > 0 ? 'tab-crown-unread.svg' : 'tab-crown.svg';
  try {
    this.panel.iconPath = vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'icons', name);
  } catch { /* panel disposed — ignore */ }
}

private askPermissionInWebview(req: PermissionRequest): Promise<PermissionDecision> {
  const TOOL_DISPLAY: Record<string, string> = {
    read_file: '讀取檔案', list_dir: '列出目錄', write_file: '寫入檔案',
    run_bash: '執行指令', web_search: '聯網搜尋', web_fetch: '抓取網頁',
  };
  const norm = normalizeToolName(req.tool);
  const bare = norm.replace(/^custom:/, '');
  const label = TOOL_DISPLAY[bare] || bare;
  let risk = 'caution';
  try { risk = classifyRisk({ tool: norm, args: req.args }).level; } catch { /* 預設 caution */ }
  const reqId = 'perm-' + (++this.permSeq);
  return new Promise<PermissionDecision>((resolve) => {
    let settled = false;
    let sub: vscode.Disposable | undefined;
    const done = (d: PermissionDecision) => {
      if (settled) return;
      settled = true;
      this.pendingPermissions.delete(reqId);
      try { sub?.dispose(); } catch { /* ignore */ }
      resolve(d);
    };
    this.pendingPermissions.set(reqId, done);
    sub = this.currentCts?.token.onCancellationRequested(() => done('deny'));
    let argsStr = '';
    try { argsStr = JSON.stringify(req.args, null, 2); } catch { argsStr = String(req.args); }
    if (argsStr.length > 1200) argsStr = argsStr.slice(0, 1200) + '…';
    void this.panel.webview.postMessage({
      type: 'permission:ask',
      reqId,
      tool: req.tool,
      label,
      risk,
      args: argsStr,
      context: req.context || '',
      forcePrompt: !!req.forcePrompt,
    });
  });
}

private async postState(opts?: { forceRender?: boolean }): Promise<void> {
  // [未讀紅點修復 1.24.30] 回應終態（done/error 帶 forceRender）時若分頁不可見＝有未讀，
  //   分頁圖標亮紅點。user 正在看（visible）時不計。對齊群組「不可見才累未讀」語意。
  if (opts?.forceRender) {
    try {
      if (!this.panel.visible) { this.unread++; this.updateUnreadIcon(); }
    } catch { /* panel disposed — ignore */ }
  }
  const providers = loadProviders();
  const session = await this.store.load(this.sessionId);
  // [身分凍結 MF-8] live 身分一律讀「這個 session」自己的 provider/model，不讀全域
  // active——否則另一個對話換 model 改了全域 workspaceState，本面板一重繪就被同化
  // （user：「換 model 全部對話被同化」的 live 根因）。session 沒存才退回全域。
  const provider =
    (session?.providerId ? findProvider(session.providerId, providers) : undefined) ||
    getActiveProvider(this.ctx, providers);
  const model = session?.model || getActiveModel(this.ctx);
  const mode: ChatMode = session?.mode || getLastMode(this.ctx);
  const config = vscode.workspace.getConfiguration('aiKing');
  // [per-conversation Agent] 開哪個對話就顯示哪個 agent：以 session.stack 為真相，全域只當「新對話預設」。
  // session.stack 可能是 'acp:<id>'（含選的外部代理）；正規化成 'acp' 給 webview AGENT 下拉/判斷用。
  const rawStack = session?.stack || config.get<string>('stack') || 'clean';
  const isAcpStack = rawStack.startsWith('acp');
  const stack = isAcpStack ? 'acp' : rawStack;
  const acpAgentId =
    isAcpStack && rawStack.includes(':')
      ? rawStack.split(':')[1]
      : (config.get<string>('acpAgent') || 'claude').trim();
  const acpProf = isAcpStack ? acpAgentProfile(acpAgentId) : undefined;
  // [1.9.5] 上下文窗口：ACP 用代理自己的（業界標準 256K，非凍結 LLM 的 64K）；否則偵測當前模型。
  const detectedCtx = isAcpStack ? 256_000 : modelContextWindow(model);
  const ctxOverride = config.get<number>('contextWindowOverride') || 0;
  const thinking = config.get<boolean>('thinking') || false;
  const thinkingBudget = config.get<number>('thinkingBudgetTokens') || 8000;
  const effort = config.get<string>('effort') || '';
  // 0.20.0: viewMode is the canonical knob. Legacy focusMode boolean kept
  // in sync so older callers still see the truthy signal.
  const viewModeRaw = config.get<string>('viewMode') || 'default';
  const viewMode: 'default' | 'focus' | 'verbose' =
    viewModeRaw === 'focus' || viewModeRaw === 'verbose'
      ? viewModeRaw
      : 'default';
  const focusMode =
    viewMode === 'focus' || config.get<boolean>('focusMode') === true;

  if (session) {
    // [1.24.21 user 拍板] 分頁＝單一白皇冠 iconPath（tab-crown.svg）＋標題「對話 —」字樣區分
    // （VS Code 分頁 iconPath 物理上只能一張圖，對話/群組靠標題前綴分）。
    this.panel.title = '對話 — ' + session.title;
  }

  const caps = getModelCapabilities(provider, model);
  const catalog = await getSlashCatalog();
  // [CBUA B+ 名字修正] ACP 對話顯示代理名（Claude Code…）；acpAgentId/acpProf 已於上方算好。
  const acpAgentLabel = acpProf?.label;
  // [v3 2026-06-21] 個資卡/訊息行「種類名」：ACP＝代理 label；內建＝種類 label（Base/AI King/PsycheForge）。
  const kindLabel = isAcpStack
    ? acpProf?.label || 'ACP'
    : labelForAgentKind(agentKindForStack(rawStack));
  // [v3] ACP 供應商/模型＝user 可選的「純標記」（存 session.providerId/model）：選了就顯示該標記，
  //   沒選退回 ACP 代理廠牌（acpProviderLogo/vendor）。內建則一律用真 provider。
  const acpPickedProvider =
    isAcpStack && session?.providerId ? findProvider(session.providerId, providers) : undefined;
  const acpModelLabel = isAcpStack ? (session?.model || '').trim() : '';
  // [身分凍結 A] live author：webview 給「串流中尚未落盤 stamp」的訊息用。authorId 由
  // host 權威算（對話內恆定）；ACP 對話顯示名覆蓋成代理 label（凍結 stamp 在 handleSend
  // 同樣覆蓋）。agentNicknames＝改名活查找表，render 用 nickname[authorId] ?? authorName。
  const liveStamp = session ? this.store.resolveCurrentAuthor(session) : undefined;
  if (liveStamp) {
    // [統一母版／v3] 供應商 logo（三段式中段）：ACP 用 user 選的供應商標記、沒選退 acpProviderLogo；
    // 內建走 provider 目錄。kindLogo（種類圖示）resolveCurrentAuthor 已由 stack 算好（ACP→ai.svg 機器人頭）。
    liveStamp.provLogo = isAcpStack
      ? acpPickedProvider
        ? providerLogoFile(acpPickedProvider.id)
        : acpProviderLogo(acpAgentId)
      : provider?.id
        ? providerLogoFile(provider.id)
        : '';
    if (acpProf) {
      liveStamp.authorName = acpProf.label;
      // [v3] 型號副標：user 選的模型標記優先；沒選退代理廠牌名。
      liveStamp.authorSub = acpModelLabel || acpProf.vendor || liveStamp.authorSub;
    }
  }
  const agentNicknames = session?.agentNicknames || {};
  const liveNick = liveStamp ? agentNicknames[liveStamp.authorId] : undefined;
  // [評分 v2 2026-06-21] 對話 AI 跨群組評分：掃所有 aiKing.peerRating.<room> globalState、sum
  // 這個 AI（liveStamp.authorId）的三態計數。1:1 對話沒同儕評分；AI 若也是某群組成員、id 對得上
  // 才有分，否則 0＝user 拍板的「沒在群組就 0」。個資卡顯示用（對齊群組個資卡的 AI 評分系統列）。
  const aiRatingCounts = { up: 0, ok: 0, down: 0, total: 0 };
  const aiAuthorId = liveStamp?.authorId;
  if (aiAuthorId) {
    for (const k of this.ctx.globalState.keys()) {
      if (!k.startsWith('aiKing.peerRating.')) continue;
      const c = countsForTarget(this.ctx, k.slice('aiKing.peerRating.'.length), aiAuthorId);
      aiRatingCounts.up += c.up;
      aiRatingCounts.ok += c.ok;
      aiRatingCounts.down += c.down;
    }
    aiRatingCounts.total = aiRatingCounts.up + aiRatingCounts.ok + aiRatingCounts.down;
  }

  // [v3 統一母版 1.24.17] composer 底列「供應商」下拉的全部供應商目錄（與側欄 home-view 同款三件）；
  //   含各家靜態 models 當「沒 keyed 真模型」時的退路。keyed 真模型另由 pushAvailableModels 推。
  const providerCatalog = providers.map((p) => ({
    id: p.id,
    name: p.name,
    logo: providerLogoFile(p.id),
    models: (((p as { models?: string[] }).models) || []).filter((m) => !/image/i.test(m)),
  }));
  await this.panel.webview.postMessage({
    type: 'state',
    // [C 黏一起根治 1.24.30] 單調序號 + 權威終態旗標。renderSeq 每次 postState 自增；
    // forceRender 只在 done/error 終止時由 host 主動帶 true（其餘 ~30 個 postState 出口
    // 一律 false）。webview 端 force 免疫序號閘、非 force 過期才丟。
    renderSeq: ++this.renderSeq,
    forceRender: !!opts?.forceRender,
    providerCatalog,
    providerName: isAcpStack
      ? acpPickedProvider?.name || acpProf?.vendor || '(no provider)'
      : provider?.name || '(no provider)',
    providerKind: provider?.kind || 'unknown',
    providerId: provider?.id,
    activeModel: model,
    acpAgent: acpAgentId,
    acpAgentLabel,
    kindLabel,
    aiRatingCounts,
    mode,
    stack,
    thinking,
    thinkingBudget,
    effort,
    focusMode,
    viewMode,
    capabilities: caps,
    slashCatalog: [
      ...catalog.map((c) => ({
        id: c.id,
        label: c.label,
        section: c.section,
        description: c.description,
      })),
      // [1.8.0 §11.3] /image — panel-local entry (needs this panel's image
      // slot), registered here instead of the global BUILTIN_COMMANDS.
      {
        id: 'image',
        label: '/image',
        section: 'action',
        description: '用圖像槽位模型生圖（圖像模型在 ☰ menu 設定）',
      },
    ],
    activeSession: session,
    sessionTitle: session?.title || '(loading)',
    // [1.8.0 §14.2/§15] who the user shows as: explicit display name >
    // signed-in account > 「你」.
    selfName:
      config.get<string>('userDisplayName')?.trim() ||
      (await getStoredUsername(this.ctx)) ||
      '你',
    // [1.8.0 §15 → 身分凍結 A] 當前對話 AI 暱稱：改讀 agentNicknames[liveAuthorId]（活
    // 查找表），向後兼容仍送 aiName 欄位讓未升級的 webview 顯示當前名不破。
    aiName: liveNick || session?.aiName || '',
    // [身分凍結 A] webview render：歷史訊息走訊息自帶的 authorId/authorName/authorSub
    // 凍結值（換 model/Agent 不變）；live 串流訊息走這組 liveAuthor*；改名查
    // agentNicknames[authorId] 套同 authorId 全歷史。
    agentNicknames,
    liveAuthorId: liveStamp?.authorId || '',
    liveAuthorName: liveStamp?.authorName || '',
    liveAuthorSub: liveStamp?.authorSub || '',
    // [統一母版] live 串流訊息的三段式徽章（種類圖示 + 供應商 logo 檔名）。
    liveAuthorKindLogo: liveStamp?.kindLogo || '',
    liveAuthorProvLogo: liveStamp?.provLogo || '',
    // [1.8.0 §15] PsycheForge (digital-human stack) carries a full persona —
    // surface the character name so the AI shows as 小美, not the raw model.
    aiPersona:
      stack === 'digital-human'
        ? config.get<string>('digitalHumanCharacterName') || ''
        : '',
    // [1.8.2] custom avatars (resolved to webview URIs). Empty ⇒ master
    // fallback: user → name badge, AI → hashed robot.
    selfAvatar: this.resolveAvatar(config.get<string>('userAvatar') || ''),
    aiAvatar: this.resolveAvatar(session?.aiAvatar || ''),
    // [1.9.3] 個資簡介：使用者沒設定 → 用模型本身的角色/特長當預設（一進對話就有
    // 個資）。PsycheForge persona 走自己的身分，不套模型特長，留給 persona 名字。
    aiBio:
      session?.aiBio ||
      (acpProf
        ? acpProf.bio
        : stack === 'digital-human'
          ? ''
          : defaultProfileForModel(model, provider?.name)),
    // [1.8.7] 狀態列回應計時開關（預設開）。
    showResponseTimer: config.get<boolean>('showResponseTimer') !== false,
    // [統一母版] 對話訊息行顯示欄位開關（☰ 選單勾選；與群組 display.groupFields 分開）。
    displayChat: config.get<Record<string, boolean>>('display.chatFields') || {},
    // [1.9.5] 上下文窗口（Claude 風格用量圈用）：自動偵測當前模型，user 可在 ☰ 選單
    // 覆寫上限（contextWindowOverride > 0 才用，否則用偵測值；偵測不到時 modelContextWindow
    // 已 fallback 200K）。webview 拿「最近一輪輸入 token / contextWindow」算用量比例。
    contextWindow: ctxOverride > 0 ? ctxOverride : detectedCtx,
    detectedContextWindow: detectedCtx,
    contextWindowAuto: ctxOverride <= 0,
    // [A4] 達閾值自動壓縮：用量比例（最近一輪 input / contextWindow）≥ 此百分比時 webview
    // 自動觸發 /compact（0＝關，opt-in per L0 #6）。webview 端有防重入（壓縮中不重觸發）。
    compactAutoThreshold: config.get<number>('compact.autoThresholdPercent') || 0,
    // [A4·固定值 2026-06-21] 絕對 token 閾值（如 256000）。>0 時優先於百分比：用量 used ≥ 此值就壓縮。
    compactAutoTokens: config.get<number>('compact.autoThresholdTokens') || 0,
    // [強制壓縮 1.24.34 user] 強制安全網：不管使用者自選閾值（含關閉），達 forceThreshold(Claude 標準
    //   95%) 一定壓縮、防爆 context。與使用者自選「先到先觸發」。預設開（對齊 Claude Code 行為＝接近
    //   滿時必 auto-compact）；☰ 選單可關。可調 compact.forceThresholdPercent。
    compactForceEnabled: config.get<boolean>('compact.forceEnabled') !== false,
    compactForceThreshold: config.get<number>('compact.forceThresholdPercent') || 95,
    // [快取] Prompt cache 開關（☰ 選單「快取」；預設開，gate clean-provider 的 cache_control）。
    promptCacheEnabled: config.get<boolean>('promptCache.enabled') !== false,
    expandThinking: config.get<boolean>('expandThinking') === true,
  });
}

private resolveAvatar(av?: string): string {
  if (!av) return '';
  if (av.startsWith('store:')) {
    const rel = av.slice('store:'.length);
    // [1.9.0 紅藍稽核 M9] 防路徑穿越：惡意 session JSON 可塞 store:../../機密檔當頭像
    // → joinPath 逃出 avatars 目錄讀任意檔。拒絕 .. / 絕對路徑 / 反斜線跳脫。
    if (rel.includes('..') || rel.startsWith('/') || rel.startsWith('\\') || /^[a-zA-Z]:/.test(rel)) {
      return '';
    }
    const uri = vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', rel);
    return this.panel.webview.asWebviewUri(uri).toString();
  }
  return av;
}

private async uploadAvatar(who: 'user' | 'ai'): Promise<void> {
  const picks = await vscode.window.showOpenDialog({
    canSelectMany: false,
    openLabel: '選擇圖片',
    title: who === 'user' ? '選一張你的頭像' : '為這個 AI 選一張頭像',
    filters: { 圖片: ['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'] },
  });
  if (!picks || !picks.length) return;
  try {
    const data = await vscode.workspace.fs.readFile(picks[0]);
    // 輸入原圖放寬到 5MB（裁切後輸出是 256 webp，極小）。
    if (data.byteLength > 5_000_000) {
      void vscode.window.showWarningMessage('圖片過大（> 5MB），請換小一點的。');
      return;
    }
    const ext = (require('path').extname(picks[0].fsPath) || '.png').toLowerCase();
    if (ext === '.svg') {
      await this.writeAvatarFile(who, 'svg', data);
      await this.postState();
      void vscode.window.showInformationMessage('已更新頭像。');
      return;
    }
    const mime =
      ext === '.png' ? 'image/png'
        : ext === '.gif' ? 'image/gif'
          : ext === '.webp' ? 'image/webp'
            : 'image/jpeg';
    const dataUri = `data:${mime};base64,${Buffer.from(data).toString('base64')}`;
    log.info('avatar:crop:open', { who, bytes: data.byteLength, ext });
    void this.panel.webview.postMessage({ type: 'avatar:crop:open', who, dataUri });
  } catch (err) {
    void vscode.window.showErrorMessage(
      `設定頭像失敗：${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

private async saveCroppedAvatar(who: 'user' | 'ai', dataUri: string): Promise<void> {
  try {
    const m = /^data:image\/(png|webp|jpeg|jpg);base64,(.+)$/i.exec(dataUri || '');
    if (!m) {
      void vscode.window.showWarningMessage('裁切結果格式無法辨識，請重試。');
      return;
    }
    const buf = Buffer.from(m[2], 'base64');
    if (buf.byteLength > 2_000_000) {
      void vscode.window.showWarningMessage('裁切後的圖仍過大，請換一張或縮小範圍。');
      return;
    }
    const ext = m[1].toLowerCase() === 'png' ? 'png' : 'webp';
    await this.writeAvatarFile(who, ext, buf);
    await this.postState();
    log.info('avatar:crop:saved', { who, bytes: buf.byteLength, ext });
    void vscode.window.showInformationMessage('已更新頭像。');
  } catch (err) {
    void vscode.window.showErrorMessage(
      `儲存頭像失敗：${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

private async writeAvatarFile(who: 'user' | 'ai', ext: string, bytes: Uint8Array): Promise<void> {
  const sub = who === 'user' ? 'user' : 'conv';
  const rel = who === 'user' ? `user/self.${ext}` : `conv/${this.sessionId}.${ext}`;
  const dir = vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', sub);
  await vscode.workspace.fs.createDirectory(dir);
  await vscode.workspace.fs.writeFile(
    vscode.Uri.joinPath(this.ctx.globalStorageUri, 'avatars', rel),
    bytes,
  );
  const marker = 'store:' + rel;
  if (who === 'user') {
    await vscode.workspace
      .getConfiguration('aiKing')
      .update('userAvatar', marker, vscode.ConfigurationTarget.Global);
  } else {
    await this.store.setAiAvatar(this.sessionId, marker);
  }
}

private async pushAvailableModels(): Promise<void> {
  // [1.8.4] 本地優先：先 allowNetwork=false 即填（讀快取/curated，零網路），再背景
  // allowNetwork=true 精修。對話視窗開啟時下拉不再空白等 probe。
  await this.emitAvailableModels(false);
  void this.emitAvailableModels(true);
}

private async emitAvailableModels(allowNetwork: boolean): Promise<void> {
  try {
    const items = await getAvailableModels({
      ctx: this.ctx,
      store: this.statusStore,
      allowNetwork,
    });
    // current = the effective active selection (workspaceState), which is what
    // handleSend/postState actually use. model:set writes here, so the picker
    // stays in sync after a switch (PLAN §3.2 / §3.5).
    const current = currentSelection(this.ctx);
    // [1.8.0 §11.3] 圖像槽位有效值：config 指定且仍可用 → 它；否則自動挑
    // 第一個可用 image 模型；都沒有 → null（menu 顯示「未設定」灰字）。
    const img = resolveImageSlotModel(items);
    await this.panel.webview.postMessage({
      type: 'modelsAvailable',
      items,
      current,
      imageModel: img ? { providerId: img.providerId, model: img.model } : null,
    });
  } catch {
    /* non-fatal — chat still usable without the picker list */
  }
}

private connStateFromProbe(
  provider: ReturnType<typeof getActiveProvider>,
  probe: ProbeResult | undefined,
  hasKey: boolean,
): { state: ConnState; detail?: string } {
  if (this.currentCts) return { state: 'thinking' };
  if (!provider) return { state: 'unset' };
  const keyless = provider.authType === 'none';
  if (!keyless && !hasKey) return { state: 'unset', detail: '未設定金鑰' };
  if (!probe) return { state: 'probing' };
  return probe.ok
    ? { state: 'ready', detail: probe.message }
    : { state: 'offline', detail: probe.message };
}

private async pushConnStatus(): Promise<void> {
  const provider = getActiveProvider(this.ctx);
  const probe = provider ? this.statusStore.get(provider.id) : undefined;
  const hasKey = provider ? await hasProviderKey(this.ctx, provider.id) : false;
  const { state, detail } = this.connStateFromProbe(provider, probe, hasKey);
  await this.panel.webview.postMessage({ type: 'connStatus', state, detail });
}

private async refreshConnStatus(force = false): Promise<void> {
  const provider = getActiveProvider(this.ctx);
  if (!provider) {
    await this.panel.webview.postMessage({ type: 'connStatus', state: 'unset' });
    return;
  }
  const keyless = provider.authType === 'none';
  const hasKey = keyless ? true : await hasProviderKey(this.ctx, provider.id);
  if (!hasKey) {
    await this.panel.webview.postMessage({
      type: 'connStatus',
      state: 'unset',
      detail: '未設定金鑰',
    });
    return;
  }
  await this.panel.webview.postMessage({ type: 'connStatus', state: 'probing' });
  const apiKey = keyless ? '' : await getProviderKey(this.ctx, provider.id);
  await this.statusStore.probe(provider, apiKey, force);
  await this.pushConnStatus();
}

private async onMessage(msg: any): Promise<void> {
  if (!msg || typeof msg !== 'object') return;
  try {
    switch (msg.type) {
      case 'ready':
        await this.pushLang(); // [1.8.0 §13] webview just (re)booted — resync language
        await this.postState();
        await this.pushAvailableModels();
        await this.pushConnStatus();
        return;
      case 'send':
        await this.handleSend(
          String(msg.content || ''),
          msg.mode,
          Array.isArray(msg.attachments) ? msg.attachments : [],
        );
        return;
      case 'stop':
        this.currentCts?.cancel();
        return;
      case 'mode:set':
        if (isChatMode(msg.mode)) {
          await setLastMode(this.ctx, msg.mode);
          try {
            await this.store.setMode(this.sessionId, msg.mode);
          } catch {
            /* session vanished — non-fatal */
          }
          await this.postState();
        }
        return;
      case 'stack:set':
        if (typeof msg.stack === 'string') {
          // [per-conversation Agent] 選哪個 agent 寫進這個對話（session.stack='acp:<id>'），每個對話各自
          // 記住自己的 agent；全域只當「新對話預設」的 base 值。
          const cfgS = vscode.workspace.getConfiguration('aiKing');
          // [v3] 末列「＋新增／設定 ACP 代理」→ 跑精靈、設這個對話用新代理。
          if (msg.stack === '__acp_add__') {
            const chosen = await acpSetupWizard();
            if (chosen) {
              await cfgS.update('acpAgent', chosen, vscode.ConfigurationTarget.Global);
              await cfgS.update('stack', `acp:${chosen}`, vscode.ConfigurationTarget.Global);
              try {
                await this.store.setIdentity(this.sessionId, { stack: `acp:${chosen}` });
                void vscode.commands.executeCommand('aiKing.internal.syncGroupIdentity', this.sessionId);
              } catch {
                /* session vanished — non-fatal */
              }
            }
            await this.postState();
            return;
          }
          let toStore = msg.stack;
          if (msg.stack === 'acp') {
            // 舊泛稱（向後相容）：補當前代理。
            const curAgent = (cfgS.get<string>('acpAgent') || 'claude').trim();
            toStore = `acp:${curAgent}`;
          } else if (msg.stack.startsWith('acp:')) {
            // [v3] Agent 下拉的 ACP 具名選項（選「Claude Code」即 acp:claude）：未設定的代理
            //   （gemini/hermes/goose…）先跑設定精靈、設好本機路徑/登入才切。
            const aid = msg.stack.split(':')[1];
            if (aid) {
              let chosen = aid;
              if (!acpAgentHasCommand(aid)) {
                const c = await acpSetupWizard(aid);
                if (!c) {
                  await this.postState();
                  return;
                } // 取消設定 → 不切回原 Agent
                chosen = c;
              }
              await cfgS.update('acpAgent', chosen, vscode.ConfigurationTarget.Global);
              toStore = `acp:${chosen}`;
              msg.stack = `acp:${chosen}`;
            }
          }
          await cfgS.update('stack', msg.stack, vscode.ConfigurationTarget.Global);
          try {
            await this.store.setIdentity(this.sessionId, { stack: toStore });
            void vscode.commands.executeCommand('aiKing.internal.syncGroupIdentity', this.sessionId);
          } catch {
            /* session vanished — non-fatal */
          }
          await this.postState();
        }
        return;
      case 'acpAgent:set': {
        // [per-conversation Agent] composer/側欄的 ACP 代理下拉 → 設這個對話用哪個外部代理。
        const aid = (msg as { acpAgent?: string }).acpAgent;
        if (typeof aid === 'string') {
          const cfgA = vscode.workspace.getConfiguration('aiKing');
          let chosen: string | undefined;
          if (aid === '__add__') {
            chosen = await acpSetupWizard(); // 自訂命名/設定 → 回新代理 id
          } else if (!acpAgentHasCommand(aid)) {
            // 選了還沒設定的代理（gemini/hermes/goose…）→ 先跳它的設定精靈設好本機路徑/登入。
            chosen = await acpSetupWizard(aid);
          } else {
            chosen = aid; // 零設定內建（claude/codex）或已設定過 → 直接用
          }
          if (chosen) {
            await cfgA.update('acpAgent', chosen, vscode.ConfigurationTarget.Global);
            try {
              await this.store.setIdentity(this.sessionId, { stack: `acp:${chosen}` });
              void vscode.commands.executeCommand('aiKing.internal.syncGroupIdentity', this.sessionId);
            } catch {
              /* session vanished — non-fatal */
            }
          }
          await this.postState();
        }
        return;
      }
      case 'permission:decision': {
        // [F 授權抽屜 1.24.32] webview 抽屜回的決定 → 解決對應 pending promise（gate 在等）。
        const pr = this.pendingPermissions.get(String(msg.reqId));
        if (pr) pr((msg.decision as PermissionDecision) || 'deny');
        return;
      }
      case 'thinking:set':
        await vscode.workspace
          .getConfiguration('aiKing')
          .update('thinking', !!msg.enabled, vscode.ConfigurationTarget.Global);
        await this.postState();
        return;
      case 'session:setAiName':
        // [1.8.0 §15 → 身分凍結 A] 改名套全歷史：寫 agentNicknames[authorId]（同 authorId
        // 的所有歷史訊息一起套新名）。authorId 由 host 端用 session 當場算，不信 webview
        // 傳值（紅隊 MF-6）。webview 只送 name。
        if (typeof msg.name === 'string') {
          const ses = await this.store.load(this.sessionId);
          if (ses) {
            const authorId = this.store.resolveCurrentAuthor(ses).authorId;
            await this.store.setAgentNickname(this.sessionId, authorId, msg.name);
          }
          await this.postState();
        }
        return;
      case 'session:setAiBio':
        // [1.24.21 A14] 個資卡改 AI 簡介：寫 session.aiBio + 連動群組（與 name/model 同母版雙向同步）。
        if (typeof msg.bio === 'string') {
          await this.store.setAiBio(this.sessionId, msg.bio);
          try {
            void vscode.commands.executeCommand('aiKing.internal.syncGroupIdentity', this.sessionId);
          } catch {
            /* session vanished — non-fatal */
          }
          await this.postState();
        }
        return;
      case 'user:setDisplayName':
        // [1.8.0 §15] rename yourself (point-own-avatar → rename).
        await vscode.workspace
          .getConfiguration('aiKing')
          .update(
            'userDisplayName',
            typeof msg.name === 'string' ? msg.name.trim() : '',
            vscode.ConfigurationTarget.Global,
          );
        await this.postState();
        return;
      case 'user:setAvatar':
        // [1.8.2] pick your own avatar image (profile card → 換頭像).
        await this.uploadAvatar('user');
        return;
      case 'session:setAiAvatar':
        // [1.8.2] pick this conversation's AI avatar (profile card → 換頭像).
        await this.uploadAvatar('ai');
        return;
      case 'avatar:crop:done':
        // [1.9.3] webview 圓形裁切器回傳烤好的 webp → 落檔。
        if (typeof msg.dataUri === 'string' && (msg.who === 'user' || msg.who === 'ai')) {
          await this.saveCroppedAvatar(msg.who, msg.dataUri);
        }
        return;
      case 'effort:set':
        await vscode.workspace
          .getConfiguration('aiKing')
          .update(
            'effort',
            typeof msg.value === 'string' ? msg.value : '',
            vscode.ConfigurationTarget.Global,
          );
        await this.postState();
        return;
      case 'openSettings':
      case 'settings:open':
        await vscode.commands.executeCommand('aiKing.settings.open');
        return;
      case 'log:show':
        // [1.8.4] reveal the AI King diagnostic output channel.
        log.reveal();
        return;
      case 'log:trace':
        // [1.9.1] webview-side step trace → diagnostic channel (端到端追蹤)。
        // [可觀測 1.24.34] 標 `chat`（對話視窗）讓 user 在 log 一眼區分對話 vs 群組（group）。
        log.info(`webview:chat:${(msg as { tag?: string }).tag || '?'}`, (msg as { data?: unknown }).data);
        return;
      case 'responseTimer:set':
        // [1.8.7] ☰ menu toggle for the status-bar response timer.
        await vscode.workspace
          .getConfiguration('aiKing')
          .update('showResponseTimer', !!(msg as { enabled?: boolean }).enabled, vscode.ConfigurationTarget.Global);
        await this.postState();
        return;
      case 'displayField:set': {
        // [統一母版] ☰ 選單「顯示欄位」勾選 → 更新對話訊息行該欄位開關（與群組分開）。
        const df = msg as { field?: string; enabled?: boolean };
        if (df.field) {
          const cfg = vscode.workspace.getConfiguration('aiKing');
          const cur = { ...(cfg.get<Record<string, boolean>>('display.chatFields') || {}) };
          cur[df.field] = !!df.enabled;
          await cfg.update('display.chatFields', cur, vscode.ConfigurationTarget.Global);
          await this.postState();
        }
        return;
      }
      case 'ctxwin:set': {
        // [A7] ☰ menu「上下文窗口」→ 下拉常見值（8K~1M）+ 自動 + 自訂（原為純自訂輸入框）。
        const detected = modelContextWindow(getActiveModel(this.ctx));
        const cfgCtx = vscode.workspace.getConfiguration('aiKing');
        const cur = cfgCtx.get<number>('contextWindowOverride') || 0;
        const fmtK = (k: number): string =>
          k >= 1000000 ? `${k / 1000000}M`.replace('.0', '') : `${Math.round(k / 1000)}K`;
        const COMMON = [8000, 16000, 32000, 64000, 128000, 200000, 256000, 512000, 1000000];
        type CtxItem = vscode.QuickPickItem & { ctxValue: number | 'custom' };
        const items: CtxItem[] = [
          {
            label: `自動偵測（${fmtK(detected)}）`,
            description: cur <= 0 ? '目前' : '依當前模型自動',
            ctxValue: 0,
          },
          ...COMMON.map(
            (k): CtxItem => ({
              label: fmtK(k),
              description: cur === k ? '目前' : '',
              ctxValue: k,
            }),
          ),
          { label: '自訂…', description: '手動輸入 token 數', ctxValue: 'custom' },
        ];
        const picked = await showQuickPickEsc(items, {
          title: '上下文窗口上限',
          placeHolder: `自動偵測目前模型為 ${fmtK(detected)}；選常見值或自訂`,
          ignoreFocusOut: true,
        });
        if (!picked) return; // cancelled
        let n: number;
        if (picked.ctxValue === 'custom') {
          const input = await showInputBoxEsc({
            title: '上下文窗口上限（tokens）',
            prompt: `輸入 token 數（例如 200000 或 200k）；清空＝用自動偵測（${fmtK(detected)}）。`,
            value: cur > 0 ? String(cur) : '',
            placeHolder: `留空＝自動（${fmtK(detected)}）`,
            ignoreFocusOut: true,
            validateInput: (v) => {
              const t = (v || '').trim();
              if (!t) return null; // empty = auto
              const m = /^(\d+)\s*[kK]$/.test(t) ? parseInt(t, 10) * 1000 : parseInt(t, 10);
              if (!Number.isFinite(m) || m < 1000) return '請輸入 ≥ 1000 的 token 數（或加 k，如 200k），或清空回到自動。';
              return null;
            },
          });
          if (input === undefined) return; // cancelled
          const t = input.trim();
          n = !t ? 0 : /^(\d+)\s*[kK]$/.test(t) ? parseInt(t, 10) * 1000 : parseInt(t, 10);
        } else {
          n = picked.ctxValue;
        }
        await cfgCtx.update('contextWindowOverride', n, vscode.ConfigurationTarget.Global);
        await this.postState();
        return;
      }
      case 'compactAuto:set': {
        // [A4] ☰ menu「自動壓縮」→ 下拉選閾值。兩種模式互斥（擇一）：
        //   · 百分比（用量達上下文窗口的 50~90%/自訂）→ 寫 compact.autoThresholdPercent
        //   · 固定 token 值（如 256K，絕對 input token 數）→ 寫 compact.autoThresholdTokens（優先）
        //   達閾值時 webview maybeAutoCompact 自動觸發 /compact（防重入旗標在 webview）。
        const cfgC = vscode.workspace.getConfiguration('aiKing');
        const curPct = cfgC.get<number>('compact.autoThresholdPercent') || 0;
        const curTok = cfgC.get<number>('compact.autoThresholdTokens') || 0;
        const fmtTok = (n: number) => (n >= 1000 ? `${Math.round(n / 1000)}K` : String(n));
        const isOff = curPct <= 0 && curTok <= 0;
        // 判別欄位用 `act` 不用 `kind`（QuickPickItem.kind 是保留欄位 QuickPickItemKind，會型別衝突）。
        type AcAct = 'off' | 'pct' | 'pctCustom' | 'tokens';
        type AcItem = vscode.QuickPickItem & { act: AcAct; pct?: number };
        const acItems: AcItem[] = [
          { label: '關閉', description: isOff ? '目前' : '不自動壓縮', act: 'off' },
          ...[50, 60, 70, 80, 90].map(
            (p): AcItem => ({
              label: `${p}%`,
              description: curTok <= 0 && curPct === p ? '目前' : '',
              act: 'pct',
              pct: p,
            }),
          ),
          { label: '自訂百分比…', description: '手動輸入 1~99%', act: 'pctCustom' },
          {
            label: '固定 token 值…',
            description: curTok > 0 ? `目前 ${fmtTok(curTok)}（絕對值，優先於 %）` : '如 256K，達此絕對 token 數就壓縮',
            act: 'tokens',
          },
        ];
        const pick = await showQuickPickEsc(acItems, {
          title: '自動壓縮閾值（% 用量比例 或 固定 token 值）',
          placeHolder: '達閾值自動壓縮較舊訊息；關閉＝只手動 /compact。固定 token 值優先於百分比。',
          ignoreFocusOut: true,
        });
        if (!pick) return;
        if (pick.act === 'off') {
          await cfgC.update('compact.autoThresholdPercent', 0, vscode.ConfigurationTarget.Global);
          await cfgC.update('compact.autoThresholdTokens', 0, vscode.ConfigurationTarget.Global);
        } else if (pick.act === 'pct') {
          // 選百分比 → 清掉固定值（互斥）。
          await cfgC.update('compact.autoThresholdPercent', pick.pct || 0, vscode.ConfigurationTarget.Global);
          await cfgC.update('compact.autoThresholdTokens', 0, vscode.ConfigurationTarget.Global);
        } else if (pick.act === 'pctCustom') {
          const input = await showInputBoxEsc({
            title: '自動壓縮閾值（%）',
            prompt: '輸入 1~99 的百分比（用量達上下文窗口的此比例就自動壓縮）；0 或清空＝關閉。',
            value: curTok <= 0 && curPct > 0 ? String(curPct) : '',
            ignoreFocusOut: true,
            validateInput: (v) => {
              const t = (v || '').trim();
              if (!t) return null;
              const m = parseInt(t.replace(/%$/, ''), 10);
              if (!Number.isFinite(m) || m < 0 || m > 99) return '請輸入 0~99 的百分比（0＝關閉）。';
              return null;
            },
          });
          if (input === undefined) return;
          const t = input.trim();
          const pct = !t ? 0 : Math.max(0, Math.min(99, parseInt(t.replace(/%$/, ''), 10)));
          await cfgC.update('compact.autoThresholdPercent', pct, vscode.ConfigurationTarget.Global);
          await cfgC.update('compact.autoThresholdTokens', 0, vscode.ConfigurationTarget.Global);
        } else {
          // 固定 token 值：接受「256000」或「256k/256K」；0 或清空＝關閉（回到看百分比，但百分比此時通常也 0）。
          const input = await showInputBoxEsc({
            title: '自動壓縮閾值（固定 token 值）',
            prompt: '輸入絕對 token 數（例如 256000 或 256k）；達此用量就壓縮較舊訊息。0 或清空＝不用固定值。',
            value: curTok > 0 ? String(curTok) : '',
            placeHolder: '例如 256k（＝256000）',
            ignoreFocusOut: true,
            validateInput: (v) => {
              const t = (v || '').trim();
              if (!t) return null;
              const m = /^(\d+)\s*[kK]$/.test(t) ? parseInt(t, 10) * 1000 : parseInt(t, 10);
              if (!Number.isFinite(m) || (m !== 0 && m < 1000)) return '請輸入 ≥ 1000 的 token 數（或加 k，如 256k），或清空關閉固定值。';
              return null;
            },
          });
          if (input === undefined) return;
          const t = input.trim();
          const tok = !t ? 0 : /^(\d+)\s*[kK]$/.test(t) ? parseInt(t, 10) * 1000 : parseInt(t, 10);
          await cfgC.update('compact.autoThresholdTokens', tok, vscode.ConfigurationTarget.Global);
          // 設了固定值就清百分比（互斥，避免兩條同時生效混淆）。
          if (tok > 0) await cfgC.update('compact.autoThresholdPercent', 0, vscode.ConfigurationTarget.Global);
        }
        await this.postState();
        return;
      }
      case 'promptCache:set': {
        // [快取] ☰ 選單「快取」勾選 → 寫 config；clean-provider 下次請求即生效（cache_control）。
        await vscode.workspace
          .getConfiguration('aiKing')
          .update(
            'promptCache.enabled',
            !!(msg as { enabled?: boolean }).enabled,
            vscode.ConfigurationTarget.Global,
          );
        await this.postState();
        return;
      }
      case 'expandThinking:set': {
        // [展開思考過程] ☰ 選單勾選 → 寫 config；webview 下次 render thinking 即依此決定回答後是否收起
        //   （關＝自動收起一行、開＝保持展開）。PsycheForge 不顯示思考、不受此影響。
        await vscode.workspace
          .getConfiguration('aiKing')
          .update(
            'expandThinking',
            !!(msg as { enabled?: boolean }).enabled,
            vscode.ConfigurationTarget.Global,
          );
        await this.postState();
        return;
      }
      case 'forceCompact:set': {
        // [強制壓縮 1.24.34] ☰ 選單「強制 95%」勾選 → 寫 config；webview maybeAutoCompact 下次即依此
        //   決定是否啟用 Claude 標準 95% 安全網（不管使用者自選閾值、防爆 context）。
        await vscode.workspace
          .getConfiguration('aiKing')
          .update(
            'compact.forceEnabled',
            !!(msg as { enabled?: boolean }).enabled,
            vscode.ConfigurationTarget.Global,
          );
        await this.postState();
        return;
      }
      case 'msg:delete': {
        // [統一母版 刪除 2026-06-21] 對話訊息刪除：本機 1:1、使用者自己擁有 → 直接從 session
        // 移除該則（用 ts 識別；群組走 authority server、對話走本機 store.replaceAll 原子覆寫）。
        // 改完 store.onDidChange 自動 postState；webview !busy 時 renderMessages 重繪掉該則。
        const delTs = (msg as { ts?: number }).ts;
        if (typeof delTs === 'number' && delTs > 0) {
          const s = await this.store.load(this.sessionId);
          if (s) {
            const kept = s.messages.filter((mm) => mm.ts !== delTs);
            if (kept.length !== s.messages.length) {
              await this.store.replaceAll(this.sessionId, kept);
              await this.postState();
            }
          }
        }
        return;
      }
      case 'model:set':
        if (
          typeof msg.providerId === 'string' &&
          msg.providerId.length > 0 &&
          typeof msg.model === 'string' &&
          msg.model.length > 0
        ) {
          // Switch the active provider + model and persist as the new
          // workspaceState default (PLAN §3.2). workspaceState is the source
          // of truth for postState/handleSend (getActiveProvider/getActiveModel),
          // so the selection takes effect for this session immediately.
          await setActiveProviderId(this.ctx, msg.providerId);
          await setActiveModel(this.ctx, msg.model);
          // [1.13.x 群組連動] 把改過的 LLM 回寫進這個 session（過去只寫 workspaceState
          // active，session.model/providerId 自 create() 凍結 → 群組身份同步永遠讀到舊 LLM）。
          // 寫完通知群組面板立即連動（名稱+簡介不在此 patch、不連動）。
          try {
            await this.store.setIdentity(this.sessionId, { model: msg.model, providerId: msg.providerId });
            void vscode.commands.executeCommand('aiKing.internal.syncGroupIdentity', this.sessionId);
          } catch {
            /* session vanished — non-fatal */
          }
          await this.postState();
          await this.pushAvailableModels();
          await this.refreshConnStatus(true);
        }
        return;
      case 'imageModel:set':
        // [1.8.0 §11.3] ☰ menu「圖像模型」→ 寫 config（格式 providerId:model）.
        if (
          typeof msg.providerId === 'string' &&
          msg.providerId.length > 0 &&
          typeof msg.model === 'string' &&
          msg.model.length > 0
        ) {
          await vscode.workspace
            .getConfiguration('aiKing')
            .update(
              'imageModel',
              `${msg.providerId}:${msg.model}`,
              vscode.ConfigurationTarget.Global,
            );
          await this.pushAvailableModels();
        }
        return;
      case 'slash:execute':
        await this.handleSlash(String(msg.commandId || ''));
        return;
    }
  } catch (e: any) {
    this.panel.webview.postMessage({
      type: 'error',
      message: e?.message || String(e),
    });
  }
}

private async handleSlash(commandId: string): Promise<void> {
  if (!commandId) return;

  // [1.8.0 §11.3] /image — prefill the input with the command prefix; the
  // user types the prompt and Enter routes through the image slot in
  // handleSend. Panel-local (not in BUILTIN_COMMANDS).
  if (commandId === 'image') {
    this.panel.webview.postMessage({
      type: 'slash:inject',
      commandId,
      label: '/image',
      body: '/image ',
    });
    return;
  }

  // Built-in action?
  const builtin = BUILTIN_COMMANDS.find((c) => c.id === commandId);
  if (builtin) {
    if (builtin.id === 'clear') {
      await this.store.truncate(this.sessionId, 0);
      await this.postState();
      return;
    }
    if (builtin.id === 'reset') {
      // 0.14.0: cancel any live stream, drop the CTS, and re-post state.
      // Session history is preserved (use /clear to wipe messages).
      this.currentCts?.cancel();
      this.currentCts = undefined;
      this.panel.webview.postMessage({
        type: 'slash:help',
        lines: ['Reset — live stream cancelled, runtime state refreshed.'],
      });
      await this.postState();
      return;
    }
    if (builtin.id === 'compact') {
      await this.handleCompact();
      return;
    }
    if (builtin.id === 'recall') {
      await this.handleRecall();
      return;
    }
    if (builtin.id === 'recap') {
      await this.handleRecap();
      return;
    }
    if (builtin.id === 'help') {
      this.panel.webview.postMessage({
        type: 'slash:help',
        lines: [
          'AI King slash commands:',
          ...BUILTIN_COMMANDS.map((c) => `  ${c.label} — ${c.description}`),
          '',
          'Custom commands: .claude/commands/*.md',
          'Skills: .claude/skills/<name>/SKILL.md',
          '',
          'Shortcuts: Enter=send · Shift+Enter=newline · Esc=cancel stream · /=open menu',
        ],
      });
      return;
    }
    if (builtin.vscodeCommand) {
      await vscode.commands.executeCommand(builtin.vscodeCommand);
      await this.postState();
    }
    return;
  }

  // Custom command or skill → load body and inject into input box
  const catalog = await getSlashCatalog();
  const entry = catalog.find((c) => c.id === commandId);
  if (!entry || !entry.filePath) return;
  try {
    const body = await loadSlashBody(entry.filePath);
    this.panel.webview.postMessage({
      type: 'slash:inject',
      commandId,
      label: entry.label,
      body,
    });
  } catch (e: any) {
    this.panel.webview.postMessage({
      type: 'error',
      message: `Failed to load ${entry.label}: ${e?.message || String(e)}`,
    });
  }
}

private async handleCompact(): Promise<void> {
  // [願景 1 PoC] switch + 可調參（aiKing.compact.*，走 6-source 鏈）。
  const cfg = vscode.workspace.getConfiguration('aiKing');
  if (cfg.get<boolean>('compact.enabled') === false) {
    this.panel.webview.postMessage({
      type: 'slash:help',
      lines: [th('chat.compact.disabled')],
    });
    return;
  }
  const requestedKeepN = Math.max(1, cfg.get<number>('compact.keepLastN') ?? 4);

  const session = await this.store.load(this.sessionId);
  if (!session) return;

  const originalCount = session.messages.length;
  // 動態保留段：則數少但內容超長時（典型＝少數超長訊息吃掉 84% context），
  // 縮 keepN 保證至少還有 1 則舊段可摘要——否則純「則數判斷」會對「少則數
  // 長內容」誤判太短（84% 用量卻喊「對話太短」，正是 user 回報的 bug）。
  let effectiveKeepN = requestedKeepN;
  if (originalCount <= requestedKeepN && originalCount >= 2) {
    effectiveKeepN = originalCount - 1;
  }
  // 「太短」改用內容量（字元≈token）判斷、不用則數：沒有可摘要舊段、
  // 或舊段內容太少（壓了沒意義）才算真的太短。
  const summarizable = session.messages.slice(0, -effectiveKeepN);
  const summarizableChars = summarizable.reduce(
    (n, m) => n + (m.content ? m.content.length : 0),
    0,
  );
  if (summarizable.length < 1 || summarizableChars < 800) {
    this.panel.webview.postMessage({
      type: 'slash:help',
      lines: [th('chat.compact.tooShort')],
    });
    return;
  }

  const providers = loadProviders();
  const provider = getActiveProvider(this.ctx, providers);
  if (!provider) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.compact.noProvider'),
    });
    return;
  }
  const apiKey = await getProviderKey(this.ctx, provider.id);
  if (providerRequiresKey(provider) && !apiKey) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.compact.noKey').replace('{name}', provider.name),
    });
    return;
  }
  const model = getActiveModel(this.ctx);

  // 保留最後 effectiveKeepN 則；其餘摘要成三層交接（全文層＝原始訊息存 archive）。
  const toSummarize = session.messages.slice(0, -effectiveKeepN);
  const toKeep = session.messages.slice(-effectiveKeepN);
  const conversationText = toSummarize
    .map((m) => `${m.role}: ${m.content}`)
    .join('\n');

  // 三層交接模板：輸出嚴格 JSON（index 一句話路由 + summary 現狀/決策/待辦）。
  // 「全文」層不要 LLM 重述、省 token——全文＝原始訊息，原樣存 archive 可召回。
  const handoffSystemPrompt =
    'You compress a conversation transcript into a structured handoff so the ' +
    'assistant can continue seamlessly after the older messages are physically ' +
    'removed from context. Output ONLY a single JSON object — no preamble, no ' +
    'markdown fence — with exactly these two string keys:\n' +
    '  "index":   one sentence routing summary — what this conversation is about.\n' +
    '  "summary": the current state, key decisions made, open action items, and ' +
    'any constraints/facts needed to continue. Be complete but concise; preserve ' +
    'code references, file paths, names, numbers, and decisions verbatim.\n' +
    'Do not call any tools. Respond with the JSON object only.';

  // 生成 + 驗證 + 一次 retry；驗不過 → 保留原文不壓縮（fail-safe，不 fail-loss）。
  let handoff: CompactHandoff | null = null;
  for (let attempt = 0; attempt < 2 && !handoff; attempt++) {
    let raw: string;
    try {
      raw = await this.callLlmForCompaction(
        provider, apiKey, model, handoffSystemPrompt, conversationText,
      );
    } catch (e: any) {
      // LLM 呼叫失敗 → 原文未動，安全返回。
      this.panel.webview.postMessage({
        type: 'error',
        message: th('chat.compact.llmFail') + (e?.message || String(e)),
      });
      return;
    }
    handoff = parseHandoff(raw);
  }
  if (!handoff) {
    // JSON 驗不過 → 不壓縮、保留原文（fail-safe）。
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.compact.empty'),
    });
    return;
  }

  // ⛔ work-loss 根治第一步：先把舊全文落地 archive、驗 rename 成功，才動 active。
  // archive 沒落地就絕不碰 session（中斷也只是「沒壓縮」，永遠不丟資料）。
  const archive = new ArchiveStore(this.ctx);
  try {
    await archive.archive(this.sessionId, handoff, toSummarize, toKeep.length);
  } catch (e: any) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.compact.archiveFail') + (e?.message || String(e)),
    });
    return;
  }

  // 組壓縮塊（索引 + 摘要 + 召回提示），取代被壓掉的舊訊息。
  const now = Date.now();
  const block =
    `[壓縮交接 Compacted handoff]\n` +
    `索引 Index: ${handoff.index}\n` +
    `摘要 Summary: ${handoff.summary}\n\n` +
    `（已壓縮 ${toSummarize.length} 則、全文存檔，可用 /recall 召回 — ` +
    `${toSummarize.length} messages archived, recall with /recall）`;
  const newMessages: SessionMessage[] = [
    { role: 'assistant', content: block, ts: now },
    ...toKeep,
  ];

  // ⛔ work-loss 根治第二步：單次原子寫取代「truncate(0) + 迴圈 append」，
  // 消滅「已清空、未寫回」的失敗窗。
  await this.store.replaceAll(this.sessionId, newMessages);

  const newCount = newMessages.length;
  this.panel.webview.postMessage({
    type: 'slash:help',
    lines: [
      th('chat.compact.done')
        .replace('{a}', String(originalCount))
        .replace('{b}', String(newCount)),
    ],
  });
  await this.postState();
}

private async handleRecap(): Promise<void> {
  const session = await this.store.load(this.sessionId);
  if (!session || session.messages.length === 0) {
    this.panel.webview.postMessage({
      type: 'slash:help',
      lines: ['這個 session 還沒有任何訊息 (no messages yet)'],
    });
    return;
  }

  const msgs = session.messages;
  const userMsgs = msgs.filter((m) => m.role === 'user');
  const assistantMsgs = msgs.filter((m) => m.role === 'assistant');
  const toolMsgs = msgs.filter((m) => m.role === 'tool');

  const firstUser = userMsgs[0]?.content || '(none)';
  const lastUser = userMsgs[userMsgs.length - 1]?.content || '(none)';
  const lastAssistant =
    assistantMsgs[assistantMsgs.length - 1]?.content || '(none)';

  const startedAt = new Date(session.createdAt).toLocaleString();
  const updatedAt = new Date(session.updatedAt).toLocaleString();

  const truncate = (s: string, n: number) =>
    s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + '…' : s;

  const lines = [
    `📋 Recap — ${session.title}`,
    `   ${startedAt} → ${updatedAt}`,
    `   ${msgs.length} messages (${userMsgs.length} user · ${assistantMsgs.length} assistant · ${toolMsgs.length} tool)`,
    `   model: ${session.model} · mode: ${session.mode} · stack: ${session.stack}`,
    '',
    `🎯 Original ask:`,
    `   ${truncate(firstUser, 200)}`,
    '',
    `💬 Latest user:`,
    `   ${truncate(lastUser, 200)}`,
    '',
    `🤖 Latest assistant:`,
    `   ${truncate(lastAssistant, 300)}`,
  ];

  this.panel.webview.postMessage({
    type: 'slash:help',
    lines,
  });
}

private async handleRecall(): Promise<void> {
  const archive = new ArchiveStore(this.ctx);
  const entry = await archive.latestForSession(this.sessionId);
  if (!entry) {
    this.panel.webview.postMessage({
      type: 'slash:help',
      lines: [th('chat.recall.none')],
    });
    return;
  }
  const when = new Date(entry.ts).toLocaleString();
  const cap = (s: string, n: number) => (s.length > n ? s.slice(0, n) + '…' : s);
  const lines = [
    `📦 召回 Recall — 最近一次壓縮 @ ${when}（${entry.messages.length} 則全文已存檔）`,
    `索引 Index: ${entry.handoff.index}`,
    `摘要 Summary: ${entry.handoff.summary}`,
    '',
    `— 被壓縮的原文 full transcript (${entry.messages.length} msgs) —`,
    ...entry.messages.map((m) => `${m.role}: ${cap(m.content, 500)}`),
  ];
  this.panel.webview.postMessage({ type: 'slash:help', lines });
}

private async callLlmForCompaction(
  provider: NonNullable<ReturnType<typeof getActiveProvider>>,
  apiKey: string,
  model: string,
  systemPrompt: string,
  userContent: string,
): Promise<string> {
  const endpoint = provider.endpoint.replace(/\/+$/, '');
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60_000);

  try {
    if (provider.kind === 'anthropic-direct') {
      const url = `${endpoint}/v1/messages`;
      const res = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
        },
        body: JSON.stringify({
          model,
          max_tokens: 2048,
          system: systemPrompt,
          messages: [{ role: 'user', content: userContent }],
          stream: false,
        }),
        signal: controller.signal,
      });
      if (!res.ok) {
        const body = await res.text().catch(() => '');
        throw new Error(`Anthropic ${res.status}: ${body.slice(0, 200)}`);
      }
      const json = (await res.json()) as {
        content?: Array<{ type: string; text?: string }>;
      };
      return json.content?.find((b) => b.type === 'text')?.text || '';
    }

    // OpenAI-compat (covers openai-compat, ai-king-backend, custom)
    const base = endpoint.endsWith('/v1') ? endpoint : `${endpoint}/v1`;
    const url = `${base}/chat/completions`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;
    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userContent },
        ],
        stream: false,
      }),
      signal: controller.signal,
    });
    if (!res.ok) {
      const body = await res.text().catch(() => '');
      throw new Error(`OpenAI-compat ${res.status}: ${body.slice(0, 200)}`);
    }
    const json = (await res.json()) as {
      choices?: Array<{ message?: { content?: string } }>;
    };
    return json.choices?.[0]?.message?.content || '';
  } finally {
    clearTimeout(timeout);
  }
}

private async handleSend(
  content: string,
  requestedMode?: unknown,
  attachmentsRaw: unknown[] = [],
): Promise<void> {
  const trimmed = content.trim();
  // v0.16.0: allow image-only sends (attachments without text).
  const attachments: Attachment[] = Array.isArray(attachmentsRaw)
    ? attachmentsRaw
        .map(parseAttachment)
        .filter((a): a is Attachment => a !== null)
    : [];
  if (trimmed.length === 0 && attachments.length === 0) return;

  // [1.8.0 §11.3] `/image <prompt>` → 圖像槽位（aiKing.imageModel；空＝自動挑
  // 第一個可用 image 模型）。不依賴對話模型——圖像模型已不在對話選單。
  if (/^\/image(\s|$)/i.test(trimmed)) {
    const prompt = trimmed.replace(/^\/image\s*/i, '').trim();
    const slot = await this.resolveImageSlot();
    if (!slot) {
      this.panel.webview.postMessage({
        type: 'error',
        message: th('chat.image.noModel'),
      });
      return;
    }
    await this.handleImageGeneration(
      slot.provider,
      slot.apiKey,
      slot.model,
      prompt,
      attachments.length,
      trimmed, // persist the full /image command so history matches the bubble
    );
    return;
  }

  const providers = loadProviders();
  // [身分凍結 MF-8] 發訊息用「這個 session」自己的 provider/model，不靠全域 active——
  // 否則多個對話面板同開時，全域被最後切的那個污染，B 對話會用 A 的 model 發送。
  const sendSession = await this.store.load(this.sessionId).catch(() => null);
  const provider =
    (sendSession?.providerId ? findProvider(sendSession.providerId, providers) : undefined) ||
    getActiveProvider(this.ctx, providers);
  if (!provider) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.err.noProvider'),
    });
    return;
  }
  const model = sendSession?.model || getActiveModel(this.ctx);
  const apiKey = await getProviderKey(this.ctx, provider.id);
  if (providerRequiresKey(provider) && (!apiKey || apiKey.length === 0)) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.err.noKey').replace('{name}', provider.name),
    });
    return;
  }

  const mode: ChatMode = isChatMode(requestedMode)
    ? requestedMode
    : getLastMode(this.ctx);

  try {
    await this.store.setMode(this.sessionId, mode);
  } catch {
    /* session vanished mid-write */
  }
  await setLastMode(this.ctx, mode);
  await this.postState();

  // [1.8.0 §11.3] P2 的「對話模型本身是 gpt-image 就走圖像」isImageModel 分流
  // 已移除——圖像模型不在對話選單，生圖一律走 /image 指令的槽位路徑（上方）。

  const config = vscode.workspace.getConfiguration('aiKing');
  // [per-conversation Agent] 派發以 session.stack 為真相（含 'acp:<id>'），全域只是新對話預設。
  // 複用上方已 load 的 sendSession（避免重複讀檔）。
  const stack = sendSession?.stack || config.get<string>('stack') || 'clean';
  // [身分凍結 A] dispatch 前凍結身分（host 權威 MF-6）：assistant 訊息 append 那刻取用，
  // 串流中途切 provider 不影響已 append 訊息。ACP 對話把顯示名 stamp 成代理 label（與
  // postState liveStamp 一致），其餘用 model。
  if (sendSession) {
    const stamp = this.store.resolveCurrentAuthor(sendSession);
    if (stack.startsWith('acp')) {
      const aid = stack.includes(':')
        ? stack.split(':')[1]
        : (config.get<string>('acpAgent') || 'claude').trim();
      const prof = acpAgentProfile(aid);
      // [v3] ACP 供應商/模型＝user 選的純標記（session.providerId/model）；沒選退代理廠牌。
      const pickedProv = sendSession.providerId
        ? findProvider(sendSession.providerId, providers)
        : undefined;
      const modelLabel = (sendSession.model || '').trim();
      if (prof) {
        stamp.authorName = prof.label;
        stamp.authorSub = modelLabel || prof.vendor || stamp.authorSub;
      }
      // [統一母版／v3] 凍結供應商 logo：選了標記用該供應商、沒選退 acpProviderLogo。
      stamp.provLogo = pickedProv ? providerLogoFile(pickedProv.id) : acpProviderLogo(aid);
    } else {
      // [統一母版] 內建：凍結當前 provider 的 logo（複用上方已解析的 provider）。
      stamp.provLogo = providerLogoFile(provider.id);
    }
    this.store.setPendingAuthor(this.sessionId, stamp);
  }
  const thinkingEnabled = config.get<boolean>('thinking') || false;
  const thinkingBudget = config.get<number>('thinkingBudgetTokens') || 8000;
  const effortRaw = config.get<string>('effort') || '';
  const effort: 'low' | 'medium' | 'high' | undefined =
    effortRaw === 'low' || effortRaw === 'medium' || effortRaw === 'high'
      ? effortRaw
      : undefined;
  const systemPrompt = getSystemPrompt(mode);

  // [1.9.21]「設定放路徑就能用 Skill」：私聊 clean 堆疊（Base / AI King Agent）
  // 跟群組 callBaseAgent 一樣注入 AI King 自己的技能（~/.aiking/skills）。
  // 空資料夾 → '' → 提示詞完全不變、零副作用；放了 <名>/SKILL.md 就帶著那技能回話。
  // ⚠ mode-aware：只給 clean 堆疊用（下面兩處 runViaCleanProvider）；digital-human
  //   是 PsycheForge 人格引擎、sancio 是伺服器端自帶技能系統，都不從這裡硬塞。
  const aikingSkills = loadAikingSkillsForPrompt(aikingAgentSkillFolder());
  const cleanSystemPrompt =
    systemPrompt +
    (aikingSkills
      ? `\n\n# 你具備的技能（來自設定的 Skill 資料夾 ~/.aiking/skills，需要時運用）\n${aikingSkills}`
      : '');

  this.currentCts?.cancel();
  const cts = new vscode.CancellationTokenSource();
  this.currentCts = cts;

  // Build wire history from session (before user turn — runViaSancio appends it).
  const loaded = await this.store.load(this.sessionId);
  const history: ChatMessage[] = (loaded?.messages || []).map((m: SessionMessage) => {
    // [A1 上下文分離] assistant 訊息的思考區塊不回送 LLM（user 訊息原樣保留）。
    const wireContent =
      m.role === 'assistant' ? stripThinkingForWire(m.content) : m.content;
    const base: ChatMessage = { role: m.role, content: wireContent };
    if (m.toolCallId) base.tool_call_id = m.toolCallId;
    if (m.toolCalls) {
      base.tool_calls = m.toolCalls.map((tc) => ({
        id: tc.id,
        type: 'function' as const,
        function: { name: tc.name, arguments: tc.arguments },
      }));
    }
    return base;
  });

  // 0.13.0: per-stack endpoint map with sancioEndpoint fallback.
  const stackEndpoints =
    config.get<Record<string, string>>('stackEndpoints') || {};
  const sancioFallback =
    config.get<string>('sancioEndpoint') || 'https://account.ai-king.dev';
  const resolveStackEndpoint = (s: string): string =>
    (typeof stackEndpoints[s] === 'string' && stackEndpoints[s]) ||
    sancioFallback;
  // 0.13.3: default flipped to /api/console/chat (psyche-engine actual route).
  // Old /api/persona/chat still works if user kept custom config value.
  const digitalHumanChatPath =
    config.get<string>('digitalHumanChatPath') || '/api/console/chat';
  const digitalHumanCharacterName =
    config.get<string>('digitalHumanCharacterName') || 'default';
  const digitalHumanTrial = config.get<boolean>('digitalHumanTrial') || false;
  const digitalHumanUserId = config.get<string>('digitalHumanUserId') || '';

  // [1.7.0 §10.7] permission_ask replies must reach whichever server emitted
  // them — for agent stacks that is now the LOCAL Sancio (127.0.0.1:8500).
  const sancioEndpointForGate =
    stack === 'clean' || stack === 'digital-human'
      ? resolveStackEndpoint(stack)
      : sancioBaseUrl();

  // [1.7.0] Auto-loop guard state — only active in Auto mode (PLAN §4.2).
  // The host watches the runner event stream to (a) count agent iterations
  // and surface `auto #N` to the footer, (b) stop at maxIterations, and
  // (c) abort on two consecutive identical tool errors. Esc still cancels
  // via `currentCts` independently.
  const autoActive = mode === 'auto';
  const maxIters = autoMaxIterations();
  let autoRound = 0;
  let sawTextSinceTools = false; // a new iteration starts text→tool_start
  let lastErrFingerprint: string | null = null;
  let autoStopped = false; // we triggered the stop; suppress the cancel noise
  let sawError = false; // [通知根治 F4] 本輪有無 error → done 時不把錯誤誤發成「回應完成」

  const stopAutoLoop = (notice: string) => {
    if (autoStopped) return;
    autoStopped = true;
    // Surface a plain zh-TW notice inline in the conversation, then cancel
    // the live stream. Cancellation may surface a 'cancelled' error from the
    // runner; we drop that below so the user only sees our notice.
    void this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'text', value: `\n\n> ${notice}\n` },
    });
    if (this.currentCts === cts) this.currentCts.cancel();
  };

  const emit = (event: RunnerEvent) => {
    // 0.17.0: intercept server-driven permission asks before surfacing
    // them to the webview. The gate either short-circuits (auto-approve /
    // cached allow) or pops a QuickPick; we POST the decision back to
    // /v1/agent/permission so the server-side runner can unblock.
    if (event.type === 'permission_ask') {
      void handlePermissionAsk(
        this.ctx,
        sancioEndpointForGate,
        event,
      );
      // Still forward to webview so UI can show an inline "asking…" row.
      void this.panel.webview.postMessage({ type: 'runner', event });
      return;
    }

    if (autoActive && !autoStopped) {
      if (event.type === 'text' && event.value) {
        sawTextSinceTools = true;
      } else if (event.type === 'tool_start') {
        // A tool_start that follows fresh assistant text (or the very first
        // one) marks a new agent iteration. Tools within one iteration fire
        // back-to-back with no text in between, so this counts once/round.
        if (sawTextSinceTools || autoRound === 0) {
          autoRound += 1;
          sawTextSinceTools = false;
          // Tell the webview which round we're on for the `auto #N` footer.
          void this.panel.webview.postMessage({
            type: 'autoRound',
            round: autoRound,
            max: maxIters,
          });
          if (autoRound >= maxIters) {
            stopAutoLoop(
              th('chat.auto.limit').replace(/\{n\}/g, String(maxIters)),
            );
            return; // swallow this over-limit tool_start
          }
        }
      } else if (event.type === 'tool_result' && event.ok === false) {
        // Same-error detection: two consecutive tool errors whose normalized
        // fingerprints match → stop the loop (防無限燒 token).
        const fp = normalizeErrorFingerprint(event.output || '');
        if (fp && fp === lastErrFingerprint) {
          void this.panel.webview.postMessage({ type: 'runner', event });
          stopAutoLoop(
            th('chat.auto.sameError') + (event.output || '').slice(0, 200),
          );
          return;
        }
        lastErrFingerprint = fp;
      } else if (event.type === 'tool_result' && event.ok) {
        lastErrFingerprint = null; // streak broken by a success
      }
    }

    // Drop the runner's own 'cancelled' error once WE stopped the loop, so
    // the user sees our friendly notice instead of a scary cancel error.
    if (
      autoStopped &&
      event.type === 'error' &&
      /cancel/i.test(event.message || '')
    ) {
      return;
    }

    // [1.8.4] error 事件用 void postMessage 可能在面板離屏時漏看（紅藍隊定位的
    // 「沒回應」真因之一）。先把對話面板帶回前景再 post，確保錯誤泡泡一定被看到。
    if (event.type === 'error') {
      sawError = true; // [通知根治 F4] 本輪出錯，done 時不發「回應完成」
      try { this.panel.reveal(undefined, true); } catch { /* panel disposed */ }
    }
    void this.panel.webview.postMessage({ type: 'runner', event });
    // [C 黏一起根治 1.24.31] 回應終態（done/error）host 主動推一個 forceRender:true 權威 state，
    //   把樂觀泡泡/live DOM 換成 store 正本。⛔不綁 webview ready 往返（error 回合不發 ready）＝
    //   force 出口與「回合是否終止」直接耦合在 host 單點；webview 端 force 免疫序號閘、必生效。
    //   根治多回合連送樂觀泡泡黏一起、舊對話沒被取代。
    if (event.type === 'done' || event.type === 'error') {
      void this.postState({ forceRender: true });
    }
    // [通知根治 F1/F3/F4/F6] 回應結束（done）→ 統一發「回應完成」通知。主路徑 clean/sancio/
    // digital-human/acp 都經此 emit 閉包（含 ACP，user 擔心的「hook 勾不到」前提不成立）；
    // image/send-error 的裸 postMessage done 不經此處＝天然不發（圖片無文字首句 / sawError）。
    if (event.type === 'done') {
      void this.maybeNotifyResponseComplete(this.sessionId, sawError);
    }
  };
  // v0.16.0: attachments only supported on clean stack + a provider that
  // understands vision. Warn and drop on non-clean or non-vision providers
  // instead of silently omitting them.
  if (attachments.length > 0) {
    const visionOk =
      // ACP 代理（Claude/Gemini 等）多支援看圖 → 用 ACP image content block 把圖送進去。
      stack.startsWith('acp') ||
      (stack === 'clean' &&
        (provider.kind === 'anthropic-direct' ||
          provider.kind === 'openai-compat' ||
          provider.kind === 'ai-king-backend'));
    if (!visionOk) {
      this.panel.webview.postMessage({
        type: 'error',
        message: th('chat.err.attachSkipped')
          .replace('{name}', provider.name)
          .replace('{stack}', stack),
      });
      attachments.length = 0;
    }
  }

  log.info('send:dispatch', {
    provider: provider.name,
    providerId: provider.id,
    model,
    stack,
    mode,
    endpoint: provider.endpoint,
    hasKey: !!apiKey,
  });
  try {
    if (stack.startsWith('acp')) {
      // stack='acp' 或 'acp:<id>'（AGENT 下拉選的外部代理）→ AI King 當 ACP client
      // 起動代理子進程、把它的串流映射成 RunnerEvent。代理 id 從 stack 解析。
      const acpAgentId = stack.includes(':') ? stack.split(':')[1] : undefined;
      const acpSel = resolveAcpLaunch(acpAgentId);
      if (!acpSel) {
        emit({
          type: 'error',
          message: '尚未設定 ACP 代理啟動指令（aiKing.acpAgent / aiKing.acpAgents）。',
        });
        emit({ type: 'done', mode: 'primary' });
      } else {
        // 看圖輸入：把圖片附件抽成 ACP image block（base64 取 dataUrl 逗號後段）。
        const acpImages = attachments
          .filter((a) => a.kind === 'image' && a.dataUrl.includes(','))
          .map((a) => ({
            data: a.dataUrl.slice(a.dataUrl.indexOf(',') + 1),
            mimeType: a.mimeType || 'image/png',
          }));
        await runViaACP({
          ctx: this.ctx,
          store: this.store,
          sessionId: this.sessionId,
          mode,
          launch: acpSel.launch,
          agentLabel: acpSel.label,
          userMessage: trimmed,
          images: acpImages,
          history,
          signal: cts.token,
          emit,
        });
      }
    } else if (stack === 'clean') {
      // 0.12.1: clean stack direct-streams to the selected provider —
      // no Sancio cognitive layer, no /v1/agent/run round-trip.
      await runViaCleanProvider({
        ctx: this.ctx,
        store: this.store,
        sessionId: this.sessionId,
        mode,
        provider,
        apiKey,
        model,
        stack: 'clean',
        systemPrompt: cleanSystemPrompt, // clean 堆疊＝注入 AI King 技能後的提示詞
        userMessage: trimmed,
        history,
        attachments,
        thinking: thinkingEnabled
          ? { enabled: true, budgetTokens: thinkingBudget }
          : undefined,
        effort,
        signal: cts.token,
        prompter: (r) => this.askPermissionInWebview(r), // [F 授權抽屜] 對話面板權限走 webview 抽屜
        emit,
      });
    } else if (stack === 'digital-human') {
      // 0.13.0: digital-human → PSYCHEFORGE psyche-engine via
      // digital-human-stream.ts. Bearer token from SecretStorage.
      await runViaDigitalHuman({
        ctx: this.ctx,
        store: this.store,
        sessionId: this.sessionId,
        mode,
        endpoint: resolveStackEndpoint('digital-human'),
        chatPath: digitalHumanChatPath,
        model,
        systemPrompt,
        userMessage: trimmed,
        history,
        thinking: thinkingEnabled
          ? { enabled: true, budgetTokens: thinkingBudget }
          : undefined,
        effort,
        signal: cts.token,
        emit,
        characterName: digitalHumanCharacterName,
        trial: digitalHumanTrial,
        userId: digitalHumanUserId || undefined,
      });
    } else if (!(await ensureSancioRunning())) {
      // [1.7.0 §10.7] AI King Agent needs the LOCAL Sancio runtime. When it
      // can't start (no venv = someone else's machine) fall back to the
      // clean provider path with an inline notice instead of letting the
      // request die on a 30s connect timeout against a dead endpoint.
      emit({
        type: 'text',
        value: '> ' + th('chat.agent.fallbackBase') + '\n\n',
      });
      await runViaCleanProvider({
        ctx: this.ctx,
        store: this.store,
        sessionId: this.sessionId,
        mode,
        provider,
        apiKey,
        model,
        stack: 'clean',
        systemPrompt: cleanSystemPrompt, // 退回 clean 路徑也帶 AI King 技能
        userMessage: trimmed,
        history,
        attachments,
        thinking: thinkingEnabled
          ? { enabled: true, budgetTokens: thinkingBudget }
          : undefined,
        effort,
        signal: cts.token,
        prompter: (r) => this.askPermissionInWebview(r), // [F 授權抽屜] 對話面板權限走 webview 抽屜
        emit,
      });
    } else {
      // ccc / sancio / redigo / perpetuo → LOCAL Sancio /v1/agent/run
      // (127.0.0.1:8500 — already on the host allow-list; the provider key
      // travels in provider_extra per the bridge-view contract).
      await runViaSancio({
        ctx: this.ctx,
        store: this.store,
        sessionId: this.sessionId,
        mode,
        sancioEndpoint: sancioBaseUrl(),
        apiKey,
        providerId: provider.id,
        model,
        stack,
        systemPrompt,
        userMessage: trimmed,
        history,
        thinking: thinkingEnabled
          ? { enabled: true, budgetTokens: thinkingBudget }
          : undefined,
        effort,
        signal: cts.token,
        emit,
      });
    }
  } catch (e: any) {
    // [1.8.4] log the REAL error to the AI King output channel so the user can
    // see exactly what failed (provider/model/stack/endpoint + message), and
    // surface a clear bubble that points them at the diagnostic log.
    const detail = {
      provider: provider.name,
      providerId: provider.id,
      model,
      stack,
      endpoint: provider.endpoint,
      error: e?.message || String(e),
    };
    log.error('send:failed', detail);
    this.panel.webview.postMessage({
      type: 'runner',
      event: {
        type: 'error',
        message: `送出失敗（${provider.name} · ${model}）：${e?.message || String(e)}`,
      },
    });
    this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'done', mode: 'primary' },
    });
    // [1.7.0] a send failure may mean the provider went offline — force a
    // fresh probe so the footer status reflects reality (PLAN §3.3).
    void this.refreshConnStatus(true);
  } finally {
    if (this.currentCts === cts) {
      this.currentCts = undefined;
    }
    cts.dispose();
  }
}

private async resolveImageSlot(): Promise<
  { provider: Provider; apiKey: string; model: string } | undefined
> {
  let items: AvailableModel[] = [];
  try {
    items = await getAvailableModels({ ctx: this.ctx, store: this.statusStore });
  } catch {
    /* probe failure → treated as no image model below */
  }
  const pick = resolveImageSlotModel(items);
  if (!pick) return undefined;
  const provider = findProvider(pick.providerId);
  if (!provider) return undefined;
  const apiKey = await getProviderKey(this.ctx, provider.id);
  return { provider, apiKey, model: pick.model };
}

private async handleImageGeneration(
  provider: Provider,
  apiKey: string,
  model: string,
  prompt: string,
  attachmentCount: number,
  persistAs?: string,
): Promise<void> {
  if (!prompt) {
    this.panel.webview.postMessage({
      type: 'error',
      message: th('chat.image.needPrompt'),
    });
    return;
  }

  this.currentCts?.cancel();
  const cts = new vscode.CancellationTokenSource();
  this.currentCts = cts;

  // Webview busy label override — shows 「畫圖中…」 instead of 「回應中…」.
  this.panel.webview.postMessage({ type: 'busyLabel', label: th('chat.busy.painting') });
  if (attachmentCount > 0) {
    this.panel.webview.postMessage({
      type: 'runner',
      event: {
        type: 'text',
        value: '> ' + th('chat.image.attachSkipped') + '\n\n',
      },
    });
  }

  // Persist the user turn (the chat runners normally do this themselves).
  await this.store.append(this.sessionId, {
    role: 'user',
    content: persistAs || prompt,
    ts: Date.now(),
  });

  try {
    const { dataUrl } = await runImageGeneration({
      provider,
      apiKey,
      model,
      prompt,
      signal: cts.token,
    });
    const markdown = `![generated](${dataUrl})`;
    await this.store.append(this.sessionId, {
      role: 'assistant',
      content: markdown,
      ts: Date.now(),
    });
    this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'text', value: markdown },
    });
    this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'done', mode: 'primary' },
    });
  } catch (e: any) {
    this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'error', message: e?.message || String(e) },
    });
    this.panel.webview.postMessage({
      type: 'runner',
      event: { type: 'done', mode: 'primary' },
    });
    void this.refreshConnStatus(true);
  } finally {
    if (this.currentCts === cts) {
      this.currentCts = undefined;
    }
    cts.dispose();
  }
}

private async maybeNotifyResponseComplete(
  sessionId: string,
  sawError: boolean,
): Promise<void> {
  try {
    const cfg = vscode.workspace.getConfiguration('aiKing');
    if (cfg.get<boolean>('notify.responseComplete') === false) return; // 預設開
    if (sawError) return; // [F4] 出錯的回合不發「完成」
    // [F6] 焦點 gate：面板正前景且聚焦＝user 正在看 → 不彈（對齊 bridge-view 群組「在看不彈」）。
    try {
      if (this.panel.active) return;
    } catch {
      /* panel disposed */
    }

    const session = await this.store.load(sessionId);
    if (!session) return;
    const msgs = session.messages || [];
    // [F3] 取最後一則 assistant content；無內容（image markdown 之外的空 / ACP thinking-only）→ 不發。
    let lastAssistant: SessionMessage | undefined;
    for (let i = msgs.length - 1; i >= 0; i--) {
      if (msgs[i].role === 'assistant') {
        lastAssistant = msgs[i];
        break;
      }
    }
    if (!lastAssistant || !lastAssistant.content || !lastAssistant.content.trim()) return;

    // [F5] 持久化去重：以「最後 assistant 的 ts」當該輪指紋；同輪只通知一次、跨重開視窗/更新
    // 也不再彈（globalState 落盤）。await 先寫游標再對外發（防 done 後立即關視窗丟去重進度）。
    const turnTs = lastAssistant.ts || 0;
    const DEDUP_KEY = 'aiKing.notify.responseDedup';
    const dedup = this.ctx.globalState.get<Record<string, number>>(DEDUP_KEY) || {};
    if (dedup[sessionId] === turnTs) return; // 這輪已通知過
    dedup[sessionId] = turnTs;
    const dkeys = Object.keys(dedup);
    if (dkeys.length > 200) {
      for (const k of dkeys.slice(0, dkeys.length - 200)) delete dedup[k]; // 有界、防膨脹
    }
    await this.ctx.globalState.update(DEDUP_KEY, dedup);

    // [F7] contentMode：私密 stack（sancio/digital-human/acp）預設 titleOnly 不把首句推到 OS 級。
    const title = session.title || '對話';
    const stack = session.stack || 'clean';
    const isPrivate =
      stack === 'sancio' || stack === 'digital-human' || stack.startsWith('acp');
    const cmRaw = cfg.get<string>('notify.responseComplete.contentMode') || 'auto';
    const contentMode = cmRaw === 'auto' ? (isPrivate ? 'titleOnly' : 'full') : cmRaw;
    let body: string;
    if (contentMode === 'generic') body = '回應完成';
    else if (contentMode === 'titleOnly') body = `${title} — 回應完成`;
    else body = `${title}：${firstSentenceOf(lastAssistant.content)}`;

    // [F2] 系統 toast（含 Logo、失焦也彈）→ 失敗降級 VS Code 內彈窗（無 Logo，誠實）。
    let shown = false;
    if (cfg.get<boolean>('notify.responseComplete.useSystemToast') !== false) {
      shown = await showSystemToast('AI King', body, this.ctx);
    }
    if (!shown) {
      void vscode.window.showInformationMessage(body, '開啟').then((pick) => {
        if (pick) void vscode.commands.executeCommand('aiKing.chat.openSession', sessionId);
      });
    }
  } catch (e) {
    log.error('notify:responseComplete:fail', {
      error: e instanceof Error ? e.message : String(e),
    });
  }
}

function resolveImageSlotModel(items: AvailableModel[]): AvailableModel | undefined {
  const images = items.filter((m) => m.kind === 'image');
  if (images.length === 0) return undefined;
  const cfg =
    vscode.workspace.getConfiguration('aiKing').get<string>('imageModel') || '';
  const sep = cfg.indexOf(':');
  if (sep > 0) {
    const providerId = cfg.slice(0, sep);
    const model = cfg.slice(sep + 1);
    const hit = images.find(
      (m) => m.providerId === providerId && m.model === model,
    );
    if (hit) return hit;
  }
  return images[0];
}

function autoMaxIterations(): number {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const v = cfg.get<number>('autoMode.maxIterations');
  if (typeof v !== 'number' || !isFinite(v)) return 50;
  return Math.min(200, Math.max(1, Math.floor(v)));
}

function normalizeErrorFingerprint(raw: string): string {
  return String(raw || '')
    .toLowerCase()
    // ISO-ish timestamps
    .replace(/\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}:\d{2}(?:\.\d+)?z?/g, '<ts>')
    // long hex blobs (hashes / ids) — 8+ hex chars
    .replace(/\b[0-9a-f]{8,}\b/g, '<hex>')
    // windows + posix absolute paths
    .replace(/[a-z]:\\[^\s"']*/g, '<path>')
    .replace(/\/(?:[^\s/"']+\/)+[^\s/"']*/g, '<path>')
    // line:col coordinates
    .replace(/:\d+:\d+/g, ':<n>:<n>')
    // any remaining standalone numbers
    .replace(/\b\d+\b/g, '<n>')
    .replace(/\s+/g, ' ')
    .trim();
}

async function handlePermissionAsk(
  ctx: vscode.ExtensionContext,
  sancioEndpoint: string,
  event: Extract<RunnerEvent, { type: 'permission_ask' }>,
): Promise<void> {
  try {
    const decision = await askPermission(ctx, {
      tool: event.tool,
      args: event.args,
      context: event.context,
    });
    const token = await getStoredToken(ctx);
    const base = sancioEndpoint.replace(/\/+$/, '');
    const url = /\/v1$/.test(base)
      ? `${base}/agent/permission`
      : `${base}/v1/agent/permission`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (token) headers['Authorization'] = `Bearer ${token}`;
    await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        id: event.id,
        tool: event.tool,
        decision,
      }),
    }).catch((e) => {
      console.warn('[ai-king] permission POST failed', e?.message || e);
    });
  } catch (e: any) {
    console.warn('[ai-king] permission gate failed', e?.message || e);
  }
}

export function registerChatPanel(
  ctx: vscode.ExtensionContext,
  store: SessionStore,
  storeReady?: Promise<void>,
): void {
  // [1.13.x] 跨擴充重載/更新保留對話視窗：註冊 WebviewPanelSerializer，VS Code 重載後
  // 用 webview 存的 sessionId 恢復面板（session 已被刪則 dispose 掉空殼、不留死 tab）。
  ctx.subscriptions.push(
    vscode.window.registerWebviewPanelSerializer(ChatPanel.viewType, {
      async deserializeWebviewPanel(panel, state) {
        // [1.18.9] ⚠ VS Code 還原 serializer panel 時不保留 webview.options——必須在這裡
        // 重設，否則 reload 後 enableScripts=false（script 全擋→卡「載入中」）+ resource
        // root 失效（CSS 載不到→裸版堆疊）＝對話面板破版要關掉重開的根因。與 createOrShow
        // 共用 ChatPanel.webviewOptions 保證還原與首開一致。
        panel.webview.options = ChatPanel.webviewOptions(ctx);
        const raw = (state as { sessionId?: unknown } | undefined)?.sessionId;
        const sessionId = typeof raw === 'string' ? raw : '';
        if (!sessionId) { panel.dispose(); return; }
        // [1.14.0 對抗審查 critical#2] 先等啟動鏈把 profile namespace 定案，再 load——否則登入
        // 使用者的對話檔在 <accountId> profile，這裡卻可能在 setNamespace 切到帳號前先讀 _guest
        // → 找不到 → 誤把使用者上次開著的對話 tab dispose 掉（reload race）。storeReady 內含
        // try/catch、總會 resolve，這裡再包一層保險不卡死。
        if (storeReady) { try { await storeReady; } catch { /* 啟動鏈已自吞錯、照常往下 */ } }
        if (!(await store.load(sessionId))) { panel.dispose(); return; }
        ChatPanel.revive(ctx, store, sessionId, panel);
      },
    }),
  );
  ctx.subscriptions.push(
    vscode.commands.registerCommand('aiKing.chat.open', async () => {
      let sessionId = getActiveSessionId(ctx);
      if (!sessionId || !(await store.load(sessionId))) {
        const provider = getActiveProvider(ctx);
        const stack =
          vscode.workspace.getConfiguration('aiKing').get<string>('stack') || 'clean';
        const model = getActiveModel(ctx);
        const mode = getLastMode(ctx);
        const created = await store.create(undefined, model, stack, mode, provider?.id);
        sessionId = created.id;
        log.info('chat:open:autocreate', { sessionId });
        await setActiveSessionId(ctx, sessionId);
      }
      ChatPanel.createOrShow(ctx, store, sessionId);
    }),
    vscode.commands.registerCommand(
      'aiKing.chat.openSession',
      async (sessionId: string) => {
        if (!sessionId) return;
        const session = await store.load(sessionId);
        if (!session) {
          log.warn('chat:open:session-missing', { sessionId });
          vscode.window.showWarningMessage('AI King: ' + th('chat.session.notFound'));
          return;
        }
        await setActiveSessionId(ctx, sessionId);
        // [2026-06-14] 切到該對話時，連帶把它存的 provider/model 設成 active——否則 chat panel
        // 一律用全域 active（預設 Claude），新創 deepseek 的對話會顯示成 Claude、且發訊息用 Claude
        // （沒設好就「不能對話」）。讓「開哪個對話就用那個對話自己的 LLM」。
        if (session.providerId) await setActiveProviderId(ctx, session.providerId);
        if (session.model) await setActiveModel(ctx, session.model);
        ChatPanel.createOrShow(ctx, store, sessionId);
      },
    ),
  );
}

async deserializeWebviewPanel(panel, state) {
  // [1.18.9] ⚠ VS Code 還原 serializer panel 時不保留 webview.options——必須在這裡
  // 重設，否則 reload 後 enableScripts=false（script 全擋→卡「載入中」）+ resource
  // root 失效（CSS 載不到→裸版堆疊）＝對話面板破版要關掉重開的根因。與 createOrShow
  // 共用 ChatPanel.webviewOptions 保證還原與首開一致。
  panel.webview.options = ChatPanel.webviewOptions(ctx);
  const raw = (state as { sessionId?: unknown } | undefined)?.sessionId;
  const sessionId = typeof raw === 'string' ? raw : '';
  if (!sessionId) { panel.dispose(); return; }
  // [1.14.0 對抗審查 critical#2] 先等啟動鏈把 profile namespace 定案，再 load——否則登入
  // 使用者的對話檔在 <accountId> profile，這裡卻可能在 setNamespace 切到帳號前先讀 _guest
  // → 找不到 → 誤把使用者上次開著的對話 tab dispose 掉（reload race）。storeReady 內含
  // try/catch、總會 resolve，這裡再包一層保險不卡死。
  if (storeReady) { try { await storeReady; } catch { /* 啟動鏈已自吞錯、照常往下 */ } }
  if (!(await store.load(sessionId))) { panel.dispose(); return; }
  ChatPanel.revive(ctx, store, sessionId, panel);
