    const firstConnect = c.lastSeq === undefined;
    try {

start(): void {
  this.scanRooms();
  this.hbTimer = setInterval(() => this.heartbeatAll(), HEARTBEAT_MS);
  this.rescanTimer = setInterval(() => this.scanRooms(), RESCAN_MS);
  this.info(`背景連線管理器啟動 — 追蹤 ${this.conns.size} 個群組`);
}

dispose(): void {
  this.disposed = true;
  if (this.hbTimer) { clearInterval(this.hbTimer); this.hbTimer = undefined; }
  if (this.rescanTimer) { clearInterval(this.rescanTimer); this.rescanTimer = undefined; }
  if (this.pausedNoticeTimer) { clearTimeout(this.pausedNoticeTimer); this.pausedNoticeTimer = undefined; }
  this.pendingPaused.clear();
  for (const c of this.conns.values()) this.teardown(c);
  this.conns.clear();
}

panelOpened(room: string): void {
  const key = resolveRoomId(room);
  if (!key) return;
  this.openPanels.add(key);
  const c = this.conns.get(key);
  if (c) {
    this.teardown(c);
    this.info(`「${key}」面板開啟 → 背景訂閱暫停（面板連線接手）`);
  }
}

panelClosed(room: string): void {
  const key = resolveRoomId(room);
  if (!key) return;
  this.openPanels.delete(key);
  if (this.disposed) return;
  if (!listRooms().includes(key)) {
    // 解散 / 離開群組時面板 dispose 後房間目錄已刪 → 不再追蹤。
    const c = this.conns.get(key);
    if (c) { this.teardown(c); this.conns.delete(key); }
    return;
  }
  // 面板開著的期間 token / 身分可能變了（重新加入、改名）→ 丟掉舊狀態重新登記，
  // 拿最新的 .token / identity 再連，順便清掉先前的 stopped 旗標。
  const prev = this.conns.get(key);
  if (prev) { this.teardown(prev); this.conns.delete(key); }
  const c = this.track(key);
  if (c) {
    this.connect(c);
    this.info(`「${key}」面板關閉 → 背景訂閱恢復`);
  }
}

private scanRooms(): void {
  if (this.disposed) return;
  let rooms: string[] = [];
  try { rooms = listRooms(); } catch { rooms = []; }
  const live = new Set(rooms);
  // 已刪除的房 → 移除追蹤。
  for (const [key, c] of [...this.conns.entries()]) {
    if (!live.has(key)) { this.teardown(c); this.conns.delete(key); }
  }
  // 新房 → 加入追蹤並連線（面板開著的交給面板）。
  for (const room of rooms) {
    if (this.conns.has(room)) continue;
    const c = this.track(room);
    if (c && !this.openPanels.has(room)) this.connect(c);
  }
}

private track(room: string): RoomConn | undefined {
  let token = '';
  try { token = getRoomToken(room); } catch { token = ''; }
  if (!token || !token.trim()) {
    this.info(`「${room}」房間鑰匙讀取失敗或為空 — 背景連線略過此房`);
    return undefined;
  }
  const c: RoomConn = {
    room, token, me: this.selfName(room), sid: '',
    connected: false, stopped: false, backoffMs: BACKOFF_MIN_MS,
    hbUnsupported: false, lastNotifyAt: 0, suppressed: 0,
    failCount: 0, paused: false,
  };
  this.conns.set(room, c);
  return c;
}

private roomBase(room: string): string {
  const cfg = readRelayConfig(room);
  const r = cfg?.relay;
  if (r && /^(?:https?|wss?):\/\//i.test(r)) return this.toHttp(r); // 線上房：用它自己的伺服器
  if (!isOnlineRoom(room)) return `http://127.0.0.1:${AUTHORITY_PORT}`; // 本機房固定本機
  return this.toHttp(authorityUrl());
}

private toHttp(url: string): string {
  return url.replace(/^ws:/i, 'http:').replace(/^wss:/i, 'https:').replace(/\/+$/, '');
}

private selfName(room: string): string {
  const id = readIdentity(room);
  if (id && id.me && id.me.trim()) return id.me.trim();
  const cfg = readRelayConfig(room);
  if (cfg && cfg.me && cfg.me.trim()) return cfg.me.trim();
  return vscode.workspace.getConfiguration('aiKing').get<string>('bridgeUserId')?.trim() || 'user';
}

private connect(c: RoomConn): void {
  // c.paused（連續失敗達上限暫停）也擋：防 RESCAN 重掃／面板關閉恢復訂閱等路徑繞過暫停自動重連。
  // resumeReconnect 會先清 c.paused 才呼叫 connect，所以「重新連線」按鈕能正常恢復。
  if (this.disposed || c.stopped || c.paused || this.openPanels.has(c.room)) return;
  // 房間目錄已被刪（解散/離開）→ 立即停止追蹤，別對伺服器空敲到下次重掃。
  try {
    if (!listRooms().includes(c.room)) {
      this.teardown(c);
      this.conns.delete(c.room);
      return;
    }
  } catch { /* 列表讀不到時照常嘗試連線 */ }
  this.teardownSocket(c);
  const base = this.roomBase(c.room);
  ensureAuthorityServer(base); // 本機房：確保內建伺服器活著（遠端 base 時為 no-op）
  const url = `${base}/sub?room=${encodeURIComponent(c.room)}&token=${encodeURIComponent(c.token)}` +
    `&me=${encodeURIComponent(c.me)}&id=${encodeURIComponent(c.me)}`;
  let u: URL;
  try { u = new URL(url); } catch { this.info(`「${c.room}」伺服器位址無效（${base}）— 停止背景連線`); c.stopped = true; return; }
  const lib = u.protocol === 'https:' ? https : http;
  const req = lib.get(
    { hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search, headers: { Accept: 'text/event-stream' } },
    (res) => {
      if (res.statusCode && res.statusCode >= 400) {
        let body = '';
        res.on('data', (ch) => { body += ch.toString(); });
        res.on('end', () => {
          let reason = '';
          try { reason = (JSON.parse(body || '{}') as { error?: string }).error || ''; } catch { /* */ }
          if (/bad token/i.test(reason)) {
            // 致命：鑰匙跟伺服器不符，重連解不了 → 停止（面板開啟時有自己的引導）。
            c.stopped = true;
            this.info(`「${c.room}」房間鑰匙與伺服器不符（bad token）— 停止背景連線`);
            // [1.8.0 §10.3-2] 背景連線不再靜默躺平：通知一次（每房每 session 只一次，
            // 不重複轟炸），白話原因＋引導走既有「貼邀請碼加入」流程。
            this.notifyBadTokenOnce(c.room);
            return;
          }
          if (/room dissolved/i.test(reason)) {
            c.stopped = true;
            this.info(`「${c.room}」群組已解散 — 停止背景連線`);
            return;
          }
          // not a member / 其他 4xx：背景管理器絕不替使用者改名冊（不自動 join），
          // 走退避重連等面板或對方把我們加回去。
          this.info(`「${c.room}」訂閱被拒（${res.statusCode} ${reason || '未知原因'}）— ${Math.round(c.backoffMs / 1000)} 秒後重試`);
          this.scheduleReconnect(c);
        });
        res.on('error', () => this.scheduleReconnect(c));
        return;
      }
      let buf = '';
      res.on('data', (chunk) => {
        buf += chunk.toString();
        let i: number;
        while ((i = buf.indexOf('\n\n')) >= 0) {
          const block = buf.slice(0, i);
          buf = buf.slice(i + 2);
          const m = block.match(/data: (.+)/);
          if (m) {
            try { this.onEvent(c, JSON.parse(m[1]) as Record<string, unknown>); }
            catch { /* keepalive / partial frame */ }
          }
        }
      });
      res.on('end', () => this.scheduleReconnect(c));
      res.on('error', () => this.scheduleReconnect(c));
    },
  );
  req.on('error', () => this.scheduleReconnect(c));
  c.req = req;
}

private scheduleReconnect(c: RoomConn): void {
  if (this.disposed || c.stopped || c.paused || this.openPanels.has(c.room)) return;
  if (c.retryTimer) return; // 已排程
  c.connected = false;
  c.sid = '';
  if (c.stableTimer) { clearTimeout(c.stableTimer); c.stableTimer = undefined; } // [互踢止血] 斷線清穩定計時器，別讓它事後歸零退避
  // [連線重試上限 2026-06-18 user] 連續「連不上」累計達 MAX_RECONNECT_FAILS → 暫停自動重連、
  // 桌面通知＋「重新連線」按鈕。收到 state frame（真連上）即歸零 failCount＝只有「持續連不上」才累積。
  c.failCount++;
  if (c.failCount >= MAX_RECONNECT_FAILS) {
    c.paused = true;
    this.teardownSocket(c); // [A3] 不需另清 retryTimer/stableTimer：上面 L268 early-return + clear 已保證為空
    this.queuePausedNotice(c);
    return; // ⛔ 不排 retryTimer＝停止自動重連，等使用者手動
  }
  const delay = c.backoffMs;
  c.backoffMs = Math.min(c.backoffMs * 2, BACKOFF_MAX_MS); // 指數退避：5s → 5min
  c.retryTimer = setTimeout(() => {
    c.retryTimer = undefined;
    this.connect(c);
  }, delay);
}

private queuePausedNotice(c: RoomConn): void {
  this.pendingPaused.add(c);
  this.info(`「${c.room}」連續 ${MAX_RECONNECT_FAILS} 次連不上伺服器 — 自動重連已暫停（聚合通知中）`);
  if (this.pausedNoticeTimer) return;
  this.pausedNoticeTimer = setTimeout(() => { this.pausedNoticeTimer = undefined; this.flushPausedNotice(); }, 1500);
}

private flushPausedNotice(): void {
  const rooms = [...this.pendingPaused].filter((c) => c.paused && this.conns.get(c.room) === c);
  this.pendingPaused.clear();
  if (!rooms.length) return;
  const label = rooms.length === 1 ? `「${shortRoom(rooms[0].room)}」` : `${rooms.length} 個`;
  const btn = rooms.length === 1 ? '重新連線' : '全部重新連線';
  void vscode.window.showWarningMessage(
    `AI 群組${label}：連不上伺服器，已連續 ${MAX_RECONNECT_FAILS} 次重連失敗，自動重連已暫停。`,
    btn,
  ).then((pick) => { if (pick === btn) for (const c of rooms) this.resumeReconnect(c); });
}

resumeAllPaused(): void {
  const paused = [...this.conns.values()].filter((c) => c.paused);
  for (const c of paused) this.resumeReconnect(c);
  void vscode.window.showInformationMessage(
    paused.length ? `AI 群組：已恢復 ${paused.length} 個暫停的連線、重新連線中。` : 'AI 群組：目前沒有暫停的連線。',
  );
}

private resumeReconnect(c: RoomConn): void {
  if (this.disposed || c.stopped) return;
  // [B2] identity 校驗：debounce/通知期間該房可能被 panelClosed 換成新 conn 物件、或被刪。只對
  // 「目前在冊的同一物件」操作——舊物件改用在冊的、已不在冊就丟棄（防 connect 建出孤兒 SSE 洩漏）。
  const cur = this.conns.get(c.room);
  if (!cur) return;
  if (cur !== c) { this.resumeReconnect(cur); return; }
  c.paused = false;
  c.failCount = 0;
  c.backoffMs = BACKOFF_MIN_MS;
  if (c.retryTimer) { clearTimeout(c.retryTimer); c.retryTimer = undefined; }
  this.info(`「${c.room}」使用者手動重新連線`);
  this.connect(c);
}

private teardownSocket(c: RoomConn): void {
  try { c.req?.destroy(); } catch { /* */ }
  c.req = undefined;
  c.connected = false;
  c.sid = '';
}

private teardown(c: RoomConn): void {
  if (c.retryTimer) { clearTimeout(c.retryTimer); c.retryTimer = undefined; }
  if (c.stableTimer) { clearTimeout(c.stableTimer); c.stableTimer = undefined; }
  this.teardownSocket(c);
}

private onEvent(c: RoomConn, ev: Record<string, unknown>): void {
  const type = typeof ev.type === 'string' ? ev.type : '';
  if (type === 'state') {
    if (typeof ev.sid === 'string') c.sid = ev.sid;
    if (Array.isArray((ev as { members?: unknown }).members)) c.members = (ev as unknown as { members: Member[] }).members;
    if (!c.connected) this.info(`「${c.room}」背景連線已連上`);
    c.connected = true;
    // [互踢止血 2026-06-16] 不在「一連上」就歸零退避（同身分互踢時每次短暫連上都歸零→狂閃）；
    // 改成撐滿 10 秒還連著才歸零。連線一斷（teardown/scheduleReconnect）會清掉這計時器。
    // [連線重試上限/A2] failCount 也搬進來：穩定連 10 秒才算「真連上」才歸零＝防快速 flapping
    // （連上秒斷）每次短暫連上就歸零、永遠累積不到上限而繞過暫停。
    if (c.stableTimer) clearTimeout(c.stableTimer);
    c.stableTimer = setTimeout(() => { c.backoffMs = BACKOFF_MIN_MS; c.failCount = 0; }, 10000);
    void this.backfillDrive(c); // [永不斷線] 重連/首連後補驅動斷線期間漏接的 @（首連只記進度）
    return;
  }
  if (type === 'room.dissolve') {
    c.stopped = true;
    this.teardown(c);
    this.info(`「${c.room}」群主解散了群組 — 停止背景連線`);
    return;
  }
  if (type === 'msg') {
    const msg = ev.message as { from?: string; text?: string; type?: string; mentions?: unknown; seq?: number } | undefined;
    if (!msg || typeof msg.text !== 'string') return;
    // [1.8.0 §10.3-1] 背景收訊也鏡像：密文原樣（解密前）append 回本機 channel.jsonl。
    appendMirror(c.room, ev.message as Record<string, unknown>);
    const from = typeof msg.from === 'string' ? msg.from : '';
    const plain = decryptText(c.room, c.token, msg.text);
    const seq = typeof msg.seq === 'number' ? msg.seq : 0;
    const mentions = Array.isArray(msg.mentions) ? (msg.mentions as unknown[]).filter((x): x is string => typeof x === 'string') : [];
    // [永不斷線] 維護背景訊息緩衝（給驅動組群組上下文）+ 最大 seq（去重 / backfill）。
    if (seq > 0 && (c.lastSeq === undefined || seq > c.lastSeq)) c.lastSeq = seq;
    if ((msg.type || 'msg') === 'msg' && plain && !plain.startsWith('\u{1F512}')) {
      const tailN = (() => { const n = vscode.workspace.getConfiguration('aiKing').get<number>('bgBaseAgent.bufferTail'); return typeof n === 'number' && n >= 1 ? Math.floor(n) : 30; })();
      if (!c.buf) c.buf = [];
      c.buf.push({ seq, from, text: plain, type: msg.type || 'msg', role: 'agent' });
      if (c.buf.length > tailN) c.buf = c.buf.slice(-tailN);
    }
    this.maybeNotify(c, { from, text: plain, type: typeof msg.type === 'string' ? msg.type : 'msg', mentions });
    // [永不斷線] 面板沒開該房才走到這裡 → 背景驅動被 @ 的內建 AI 回話。
    this.maybeDriveBaseAgents(c, from, plain, seq);
    this.maybeDriveAikingAgents(c, from, plain, seq);
  }
  // 其餘事件（presence / member / cleared / rename / loop.suspect）背景不處理 —
  // 那些是面板的顯示職責，面板開著時本管理器根本不在線。
}

private notifyLevel(room: string): 'all' | 'mention' | 'off' {
  const id = readIdentity(room);
  if (id && (id.notifyLevel === 'all' || id.notifyLevel === 'mention' || id.notifyLevel === 'off')) {
    return id.notifyLevel;
  }
  const g = vscode.workspace.getConfiguration('aiKing').get<string>('groupNotifyLevel', 'mention');
  return g === 'all' || g === 'off' ? g : 'mention';
}

private notifyThrottleMs(): number {
  const sec = vscode.workspace.getConfiguration('aiKing').get<number>('groupNotifyThrottleSec', 8);
  return Math.max(0, sec) * 1000;
}

private mentionsMe(me: string, msg: { text: string; mentions: string[] }): boolean {
  if (!me) return false;
  // 1.8.0: @all / @所有人 broadcast-mentions everyone.
  if (
    msg.mentions.some((m) => m.toLowerCase() === 'all' || m === '所有人') ||
    /(^|\s)@(all|所有人)(?=$|\s|[^\w-])/i.test(msg.text || '')
  ) {
    return true;
  }
  if (msg.mentions.includes(me)) return true;
  const esc = me.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|\\s)@' + esc + '(?=$|\\s|[^\\w-])').test(msg.text || '');
}

private maybeNotify(c: RoomConn, msg: { from: string; text: string; type: string; mentions: string[] }): void {
  if (msg.type !== 'msg' || !msg.text || !msg.text.trim()) return;
  if (msg.from === c.me) return;            // 自己的訊息永不通知
  if (msg.text.startsWith('🔒')) {          // 解密失敗的密文別拿去吵人，記 log 即可
    this.info(`「${c.room}」收到無法解密的訊息（房間鑰匙可能不符）`);
    return;
  }
  const level = this.notifyLevel(c.room);
  if (level === 'off') return;
  const mentioned = this.mentionsMe(c.me, msg);
  if (level === 'mention' && !mentioned) return;
  // 節流 coalesce：@我 直通，不被前一則廣播吞掉。
  const now = Date.now();
  if (now - c.lastNotifyAt < this.notifyThrottleMs() && !mentioned) {
    c.suppressed++;
    return;
  }
  const extra = c.suppressed;
  c.lastNotifyAt = now;
  c.suppressed = 0;
  // §12 通知格式：群組名｜發訊者：節錄。圖片訊息顯示 [圖片]（防 base64 倒進
  // 通知）；節錄壓單行、60 字截斷（VS Code 通知一行可視長度的甜蜜點）。
  const raw = msg.text.startsWith('AIKING_IMG1:')
    ? '[圖片]'
    : msg.text.replace(/\s+/g, ' ').trim();
  const snippet = raw.length > 60 ? `${raw.slice(0, 60)}…` : raw;
  const mark = mentioned ? '（提到你）' : '';
  const tail = extra > 0 ? `（外加 ${extra} 則）` : '';
  const room = c.room;
  // [通知停留策略] 同 bridge-view.maybeNotify：分級＝@我永久(warning)、一般自動消失(info)。
  // 背景常連這條多半是 @我（notifyLevel=mention 時非@根本不通知），故被點名時就該永久停留。
  const persistMode = vscode.workspace
    .getConfiguration('aiKing')
    .get<string>('groupNotifyPersist', 'tiered');
  const persist = persistMode === 'all' || (persistMode !== 'none' && mentioned);
  const text = `「${room}」${msg.from}${mark}：${snippet}${tail}`;
  const pickP = persist
    ? vscode.window.showWarningMessage(text, '開啟')
    : vscode.window.showInformationMessage(text, '開啟');
  void pickP.then((pick) => {
    if (pick === '開啟') void vscode.commands.executeCommand('aiKing.bridge.open', room);
  });
}

private notifyBadTokenOnce(room: string): void {
  if (this.badTokenNotified.has(room)) return;
  this.badTokenNotified.add(room);
  const REJOIN = '重新索取邀請碼';
  void vscode.window
    .showWarningMessage(
      `AI 群組「${room}」：房間鑰匙不符——可能群組已重建或邀請碼失效。` +
        '向群主重新索取邀請碼、重新加入即可恢復（你的本機對話備份不受影響）。',
      REJOIN,
    )
    .then((pick) => {
      if (pick === REJOIN) void vscode.commands.executeCommand('aiKing.bridge.join');
    });
}

private heartbeatAll(): void {
  if (this.disposed) return;
  for (const c of this.conns.values()) {
    if (!c.connected || c.stopped || c.hbUnsupported || !c.sid) continue;
    if (this.openPanels.has(c.room)) continue; // 面板開著 → 背景不重複動作
    void this.heartbeatOne(c);
  }
}

private async heartbeatOne(c: RoomConn): Promise<void> {
  try {
    const base = this.roomBase(c.room);
    const ids = await this.driveableAiIds(c);
    const status = await this.postJson(`${base}/room/${encodeURIComponent(c.room)}/heartbeat`, {
      token: c.token, sid: c.sid, name: c.me, ...(ids.length ? { ids } : {}),
    });
    if (ids.length) this.info(`[bg] heartbeat room="${c.room}" ids=[${ids.join(',')}]`);
    if (status >= 400 && status < 500) {
      // 舊伺服器沒有 heartbeat action（404 unknown action）→ 靜默降級：在線判定
      // 退回既有 presence 邏輯（live SSE），不再重打、只記一次。相容鐵律。
      c.hbUnsupported = true;
      this.info(`「${c.room}」伺服器不支援 heartbeat（HTTP ${status}，可能是舊版）— 已降級，不影響使用`);
    }
  } catch {
    /* 網路抖動 — SSE 層自會重連；心跳失敗不另行處理 */
  }
}

private bgMentionsTarget(member: Member, text: string): boolean {
  if (/(^|\s)@(all|所有人)(?=$|\s|[^\w-])/i.test(text)) return true;
  if (/(^|\s)@(群主|owner)(?=$|\s|[^\w-])/i.test(text) && member.role === 'owner') return true;
  if (/(^|\s)@(管理員|admin)(?=$|\s|[^\w-])/i.test(text) && (member.role === 'owner' || member.role === 'admin')) return true;
  for (const cand of [member.id, member.name]) {
    if (!cand) continue;
    const esc = cand.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    if (new RegExp('(^|\\s)@' + esc + '(?=$|\\s|[^\\w-])').test(text)) return true;
  }
  return false;
}

private maybeDriveBaseAgents(c: RoomConn, from: string, text: string, seq: number): void {
  if (!vscode.workspace.getConfiguration('aiKing').get<boolean>('bgBaseAgent.enabled', true)) return;
  if (!text || !text.trim()) return;
  if (text.startsWith('react:') || text.startsWith('label:') || text.startsWith('\u{1F512}')) return;
  if (!text.includes('@')) return; // 廉價預篩：沒 @ 就沒人被點
  const members = c.members || [];
  const baseAgents = members.filter((m) => m.architecture === 'clean');
  if (!baseAgents.length) return;
  const hit = baseAgents.filter((m) => m.id !== from && this.bgMentionsTarget(m, text));
  if (!hit.length) return;
  this.info(`[bg] route room="${c.room}" from="${from}" seq=${seq} baseHit=[${hit.map((m) => m.id).join(',')}]`);
  for (const m of hit) void this.callBaseAgentBg(c, m, from, text, seq);
}

private async callBaseAgentBg(c: RoomConn, member: Member, from: string, text: string, seq: number): Promise<void> {
  const cfg = vscode.workspace.getConfiguration('aiKing');
  const ctxN = cfg.get<number>('bgBaseAgent.contextMessages');
  const histCount = typeof ctxN === 'number' ? ctxN : (cfg.get<number>('group.aiContextMessages') ?? 30);
  const maxPerMin = (() => { const n = cfg.get<number>('bgBaseAgent.maxCallsPerMin'); return typeof n === 'number' && n >= 1 ? Math.floor(n) : 12; })();
  await driveBaseAgentCore({
    ctx: this.ctx,
    room: c.room,
    member,
    src: { seq, from, text, type: 'msg' },
    buffer: c.buf || [],
    sessionStore: sessionStoreFor(this.ctx),
    linkedSessionId: (id) => this.ctx.globalState.get<string>('aiKing.groupMemberSession.' + c.room + '.' + id),
    authoritySend: (id, t, replyTo) => this.bgPostAs(c, id, t, replyTo),
    maxCallsPerMin: maxPerMin,
    contextMessages: histCount,
    toolsEnabled: false,
    announceNoTools: true,
    glog: (m) => this.info('[bg] ' + m),
    warn: (m) => this.info('[bg] warn: ' + m),
  });
}

private async bgPostAs(c: RoomConn, memberId: string, text: string, replyTo: number): Promise<void> {
  try {
    const base = this.roomBase(c.room);
    const ct = encryptText(c.room, c.token, text);
    const body: Record<string, unknown> = { token: c.token, sid: c.sid, from: memberId, text: ct, senderKind: 'ai', signalKind: '' };
    if (replyTo > 0) body.replyTo = replyTo;
    const { status, json } = await this.postJsonResult(`${base}/room/${encodeURIComponent(c.room)}/msg`, body);
    if (json && typeof json.error === 'string') this.info(`[bg] postAsBg:err id="${memberId}" err=${json.error}`);
    else if (json && json.deduped) this.info(`[bg] postAsBg:deduped id="${memberId}" replyTo=${replyTo}（防雙回生效）`);
    else this.info(`[bg] postAsBg:ok id="${memberId}" len=${text.length} status=${status}`);
  } catch (e) {
    this.info(`[bg] postAsBg:throw id="${memberId}" err=${e instanceof Error ? e.message : String(e)}`);
  }
}

private async driveableAiIds(c: RoomConn): Promise<string[]> {
  if (!c.connected || !c.sid) return [];
  if (!vscode.workspace.getConfiguration('aiKing').get<boolean>('bgBaseAgent.enabled', true)) return [];
  const out: string[] = [];
  for (const m of (c.members || [])) {
    if (m.architecture === 'clean') {
      try {
        const { provider, apiKey } = await resolveBaseAgentBackend(this.ctx, m);
        if (provider && apiKey) out.push(m.id);
      } catch { /* 解不出＝不可驅動，不帶＝誠實離線 */ }
    } else if (m.architecture === 'aiking') {
      out.push(m.id); // aiking：樂觀帶（在 roster 即帶）；驅動時 ensureSancioRunning 決定能否回（閂1 樂觀版＝第一版取捨）
    }
  }
  return out;
}

private postJsonResult(urlStr: string, body: unknown): Promise<{ status: number; json: Record<string, unknown> }> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try { u = new URL(urlStr); } catch { reject(new Error('bad url')); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const data = JSON.stringify(body);
    const req = lib.request(
      { hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      (res) => {
        let raw = '';
        res.on('data', (ch) => { raw += ch.toString(); });
        res.on('end', () => { let json: Record<string, unknown> = {}; try { json = JSON.parse(raw || '{}') as Record<string, unknown>; } catch { /* */ } resolve({ status: res.statusCode || 0, json }); });
        res.on('error', reject);
      },
    );
    req.on('error', reject);
    req.setTimeout(10_000, () => { req.destroy(new Error('timeout')); });
    req.write(data);
    req.end();
  });
}

private async backfillDrive(c: RoomConn): Promise<void> {
  if (!vscode.workspace.getConfiguration('aiKing').get<boolean>('bgBaseAgent.enabled', true)) return;
  const firstConnect = c.lastSeq === undefined;
  try {
    const msgs = await this.bgHistory(c, 50);
    if (!msgs.length) return;
    const maxSeq = msgs.reduce((a, m) => (m.seq > a ? m.seq : a), 0);
    if (firstConnect) { c.lastSeq = maxSeq; return; }
    const since = c.lastSeq || 0;
    const missed = msgs.filter((m) => m.seq > since).sort((a, b) => a.seq - b.seq);
    if (!missed.length) return;
    this.info(`[bg] backfill-drive room="${c.room}" since=${since} hits=${missed.length}`);
    for (const m of missed) {
      this.maybeDriveBaseAgents(c, m.from, m.text, m.seq);
      this.maybeDriveAikingAgents(c, m.from, m.text, m.seq);
      if (m.seq > (c.lastSeq || 0)) c.lastSeq = m.seq;
    }
  } catch (e) {
    this.info(`[bg] backfill-drive:err room="${c.room}" ${e instanceof Error ? e.message : String(e)}`);
  }
}

private bgHistory(c: RoomConn, limit: number): Promise<Array<{ seq: number; from: string; text: string; type: string }>> {
  return new Promise((resolve) => {
    const base = this.roomBase(c.room);
    let u: URL;
    try { u = new URL(`${base}/room/${encodeURIComponent(c.room)}/history?token=${encodeURIComponent(c.token)}&before=0&limit=${limit}`); } catch { resolve([]); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.get({ hostname: u.hostname, port: u.port || (u.protocol === 'https:' ? 443 : 80), path: u.pathname + u.search }, (res) => {
      let raw = '';
      res.on('data', (ch) => { raw += ch.toString(); });
      res.on('end', () => {
        try {
          const j = JSON.parse(raw || '{}') as { messages?: Array<Record<string, unknown>> };
          const list = Array.isArray(j.messages) ? j.messages : [];
          resolve(list.map((m) => ({
            seq: typeof m.seq === 'number' ? (m.seq as number) : 0,
            from: typeof m.from === 'string' ? (m.from as string) : '',
            text: typeof m.text === 'string' ? decryptText(c.room, c.token, m.text as string) : '',
            type: typeof m.type === 'string' ? (m.type as string) : 'msg',
          })));
        } catch { resolve([]); }
      });
      res.on('error', () => resolve([]));
    });
    req.on('error', () => resolve([]));
    req.setTimeout(10_000, () => { try { req.destroy(); } catch { /* */ } resolve([]); });
  });
}

private maybeDriveAikingAgents(c: RoomConn, from: string, text: string, seq: number): void {
  if (!vscode.workspace.getConfiguration('aiKing').get<boolean>('bgBaseAgent.enabled', true)) return;
  if (!text || !text.trim()) return;
  if (text.startsWith('react:') || text.startsWith('label:') || text.startsWith('\u{1F512}')) return;
  if (!text.includes('@')) return;
  const agents = (c.members || []).filter((m) => m.architecture === 'aiking');
  if (!agents.length) return;
  const hit = agents.filter((m) => m.id !== from && this.bgMentionsTarget(m, text));
  if (!hit.length) return;
  this.info(`[bg] route-aiking room="${c.room}" from="${from}" seq=${seq} hit=[${hit.map((m) => m.id).join(',')}]`);
  for (const m of hit) void this.callAIKingAgentBg(c, m, from, text, seq);
}

private aikingRateTake(key: string): boolean {
  const max = vscode.workspace.getConfiguration('aiKing').get<number>('bgBaseAgent.maxCallsPerMin');
  const cap = typeof max === 'number' && max >= 1 ? Math.floor(max) : 12;
  const now = Date.now();
  const prev = (this.aikingRate.get(key) || []).filter((t) => now - t < 60_000);
  if (prev.length >= cap) { this.aikingRate.set(key, prev); return false; }
  prev.push(now); this.aikingRate.set(key, prev); return true;
}

private async callAIKingAgentBg(c: RoomConn, member: Member, from: string, text: string, seq: number): Promise<void> {
  const key = c.room + ' ' + member.id;
  if (this.aikingInflight.has(key)) { this.info(`[bg] aiking:skip inflight id="${member.id}"`); return; }
  if (!this.aikingRateTake(key)) { this.info(`[bg] aiking:skip ratelimit id="${member.id}"`); return; }
  this.aikingInflight.add(key);
  try {
    const ok = await ensureSancioRunning();
    if (!ok) { this.info(`[bg] aiking:backend-down id="${member.id}"（本機 AI King Agent 後端起不來，無法回覆）`); return; }
    const sancioBase = sancioBaseUrl();
    try { assertSancioEndpointAllowed(sancioBase); }
    catch (err) { this.info(`[bg] aiking:ssrf-block id="${member.id}" ${err instanceof Error ? err.message : String(err)}`); return; }
    const model = member.backend || 'anthropic:claude-opus-4-7';
    const { apiKey } = await resolveBaseAgentBackend(this.ctx, member);
    const providerExtra: Record<string, string> = {};
    if (apiKey) providerExtra.api_key = apiKey;
    const body = JSON.stringify({ stack: 'sancio', model, messages: [{ role: 'user', content: text }], provider_extra: providerExtra });
    const resp = await fetch(`${sancioBase}/v1/agent/run`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
    if (!resp.ok) { this.info(`[bg] aiking:http id="${member.id}" status=${resp.status}`); return; }
    const raw = await resp.text();
    let answer = '';
    for (const block of raw.split('\n\n')) {
      const evm = /event: (.+)/.exec(block);
      const dm = /data: (.+)/.exec(block);
      if (!dm) continue;
      const t = evm ? evm[1].trim() : '';
      try { const fr = JSON.parse(dm[1]) as { text?: string; content?: string; delta?: string }; if (t === 'token') answer += fr.text || fr.content || fr.delta || ''; }
      catch { /* skip non-JSON frame */ }
    }
    answer = answer.trim();
    if (answer) { await this.bgPostAs(c, member.id, answer, seq); this.info(`[bg] aiking:answer id="${member.id}" len=${answer.length}`); }
    else this.info(`[bg] aiking:empty id="${member.id}"`);
  } catch (e) {
    this.info(`[bg] aiking:err id="${member.id}" ${e instanceof Error ? e.message : String(e)}`);
  } finally {
    this.aikingInflight.delete(key);
  }
}

private postJson(urlStr: string, body: unknown): Promise<number> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try { u = new URL(urlStr); } catch { reject(new Error('bad url')); return; }
    const lib = u.protocol === 'https:' ? https : http;
    const data = JSON.stringify(body);
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === 'https:' ? 443 : 80),
        path: u.pathname + u.search,
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) },
      },
      (res) => {
        res.resume(); // 排掉 body，釋放 socket
        res.on('end', () => resolve(res.statusCode || 0));
        res.on('error', reject);
      },
    );
    req.on('error', reject);
    req.setTimeout(10_000, () => { req.destroy(new Error('timeout')); });
    req.write(data);
    req.end();
  });
}

private info(msg: string): void {
  try {
    if (!this.log) this.log = vscode.window.createOutputChannel('AI King 群組背景連線');
    const t = new Date();
    const p = (n: number) => String(n).padStart(2, '0');
    this.log.appendLine(`[${p(t.getHours())}:${p(t.getMinutes())}:${p(t.getSeconds())}] ${msg}`);
  } catch { /* */ }
}

export function startGroupConnections(ctx: vscode.ExtensionContext): void {
  if (manager) return;
  manager = new GroupConnectionManager(ctx);
  manager.start();
  ctx.subscriptions.push({ dispose: () => { manager?.dispose(); manager = undefined; } });
}

export function groupPanelOpened(room: string): void {
  manager?.panelOpened(room);
}

export function groupPanelClosed(room: string): void {
  manager?.panelClosed(room);
}

function tf(key: string, vars: Record<string, string | number>): string {
  let s = th(key);
  for (const k of Object.keys(vars)) s = s.split(`{${k}}`).join(String(vars[k]));
  return s;
}

function getNonce(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let out = '';
  for (let i = 0; i < 32; i++) {
    out += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return out;
}

