  // --------------------------------------------------------------------------
  // State push
  // --------------------------------------------------------------------------

  private async postState(): Promise<void> {
    if (!this.view) return;
    // [1.8.0 §13] push the interface language FIRST so the webview renders the
    // state below in the right language. Covers both the initial 'ready' and
    // every aiKing.language change (the config listener funnels into here).
    await this.view.webview.postMessage({ type: 'i18n:lang', lang: uiLang() });
    const providers = loadProviders();
    const provider = getActiveProvider(this.ctx, providers);
    const model = getActiveModel(this.ctx);
    const mode = getLastMode(this.ctx);
    const summaries = await this.store.list();
    const activeId = getActiveSessionId(this.ctx);
    const hasKey = provider ? await hasProviderKey(this.ctx, provider.id) : false;

    const config = vscode.workspace.getConfiguration('aiKing');
    const stack = config.get<string>('stack') || 'clean';
    const effort = config.get<string>('effort') || '';
    const acpAgent = (config.get<string>('acpAgent') || 'claude').trim();
    // [v3 2026-06-21] 全部供應商目錄給側欄「供應商」列下拉（內建選真供應商、ACP 挑標記）；
    //   含各家靜態 models 當「沒有 keyed 模型」時的退路（modelsAvailable 只含已設金鑰的家）。
    const providerCatalog = providers.map((p) => ({
      id: p.id,
      name: p.name,
      logo: providerLogoFile(p.id),
      models: (((p as { models?: string[] }).models) || []).filter((m) => !/image/i.test(m)),
    }));

    // 0.28.0 — bubble the extension version and the signed-in state up
    // into the sidebar so the user can see both at a glance instead of
    // going through the command palette for whoami / checkForUpdates.
    const version =
      (this.ctx.extension.packageJSON &&
        typeof this.ctx.extension.packageJSON.version === 'string'
        ? (this.ctx.extension.packageJSON.version as string)
        : undefined) || 'unknown';
    const token = await getStoredToken(this.ctx);
    const username = token ? await getStoredUsername(this.ctx) : undefined;

    const msg: HomeStateMsg = {
      type: 'state',
      version,
      signedInUsername: username,
      providerName: provider?.name || '(no provider)',
      providerKind: provider?.kind || 'unknown',
      modelName: model || '—',
      providerCatalog,
      providerId: provider?.id,
      model,
      hasKey: provider?.authType === 'none' ? true : hasKey,
      mode,
      stack,
      effort,
      acpAgent,
      activeSessionId: activeId,
      sessions: summaries.map((s: SessionSummary) => ({
        id: s.id,
        title: s.title,
        mode: s.mode || 'edits',
        messageCount: s.messageCount,
        updatedAt: s.updatedAt,
      })),
      rooms: listRooms().map((name) => ({
        name,
        // [統一母版 2026-06-16] label=顯示名（本機 displayName||room key）；name 維持 room key
        // 供 open/操作（顯示與連線鑰匙分離＝改名不影響連線）。webview 渲染用 label、點開傳 name。
        label: roomLabel(name),
        online: isOnlineRoom(name),
        // [2026-06-16] 改名/解散入口已從列表移除（只在群組面板內設定做）；owner 仍留作其他群主判斷。
        owner: ((): boolean => {
          const role = readIdentity(name)?.role ?? readRelayConfig(name)?.role;
          return !(role === 'admin' || role === 'member');
        })(),
      })),
    };
    await this.view.webview.postMessage(msg);
    // Push the probe-gated model list alongside the base state. It arrives as a
    // separate message because probing is async; the dropdown fills in once the
    // results land (and again on every statusStore.onDidChange).
    void this.postModels();
  }

  // --------------------------------------------------------------------------
  // [1.7.0] Probe-gated available-model list → CHAT 預設區 Model dropdown.
  // current = workspaceState default (the model a new chat will inherit).
  // --------------------------------------------------------------------------

  private async postModels(): Promise<void> {
    // [1.8.4] 本地優先：先用 allowNetwork=false 即填下拉（讀快取/curated，零網路、
    // 不等 5s probe），再背景跑 allowNetwork=true 精修。解「啟動下拉空白數秒＝體感
    // 等伺服器」。非登入完全不受影響（這條路徑本就不碰登入伺服器）。
    await this.pushModels(false);
    void this.pushModels(true);
  }

  private async pushModels(allowNetwork: boolean): Promise<void> {
    if (!this.view) return;
    let items: AvailableModel[] = [];
    try {
      items = await getAvailableModels({ ctx: this.ctx, store: this.statusStore, allowNetwork });
    } catch (e: any) {
      log.warn('home:getAvailableModels:fail', { allowNetwork, error: e?.message || String(e) });
    }
    if (!this.view) return;
    await this.view.webview.postMessage({
      type: 'modelsAvailable',
      items,
      current: currentSelection(this.ctx),
    });
  }

  // --------------------------------------------------------------------------
  // Webview → host
  // --------------------------------------------------------------------------

  private async onMessage(msg: any): Promise<void> {
    if (!msg || typeof msg !== 'object') return;
    try {
      switch (msg.type) {
        case 'ready':
          await this.postState();
          return;
        case 'session:open':
          if (typeof msg.id === 'string') {
            await vscode.commands.executeCommand('aiKing.chat.openSession', msg.id);
          }
          return;
        case 'session:rename':
          // 1.7.0: the ✎ button on each session row. webview prompt() is
          // sandbox-blocked, so the host shows a native input box instead.
          if (typeof msg.id === 'string') {
            const sessions = await this.store.list();
            const cur = sessions.find((s) => s.id === msg.id);
            const title = await showInputBoxEsc({
              prompt: th('home.host.newTitlePrompt'),
              value: cur ? cur.title : '',
            });
            if (title && title.trim()) {
              await this.store.rename(msg.id, title.trim());
              await this.postState();
            }
          }
          return;
        case 'session:new': {
          // [1.7.0] guard (PLAN §5.2): no usable model → don't open a dead chat.
          // Open settings + warn so the user knows to fill a key & pass probe.
          // [1.8.0 §11.3] 只算 kind==='chat' — 圖像模型不進對話選單，也不能當
          // 新對話的預設（避免 snap 到 gpt-image-2 之類）。
          log.info('home:session-new:enter', {});
          let avail: AvailableModel[] = [];
          try {
            avail = await getAvailableModels({ ctx: this.ctx, store: this.statusStore });
          } catch (e: any) {
            log.warn('home:session-new:models-fail', { detail: e?.message || String(e) });
            console.warn(`[ai-king] session:new getAvailableModels: ${e?.message || String(e)}`);
          }
          const chatAvail = avail.filter((m) => m.kind === 'chat');
          log.info('home:session-new:models', { chatAvail: chatAvail.length });
          // [v3] 純 ACP（外部代理用自己的登入、不需 keyed 模型）即使沒可用 chat 模型也放行開對話；
          //   其餘內建 stack 仍守「沒模型不開死對話」guard。
          const acpStackNow = (
            vscode.workspace.getConfiguration('aiKing').get<string>('stack') || 'clean'
          ).startsWith('acp');
          if (chatAvail.length === 0 && !acpStackNow) {
            log.warn('home:session-new:no-model', {});
            await vscode.commands.executeCommand('aiKing.settings.open');
            void vscode.window.showWarningMessage(th('home.host.noModelWarn'));
            return;
          }
          // Non-empty but the stored default points at something that no longer
          // resolves (e.g. an old name or an image model) → snap to the first
          // available chat model so the new chat opens against one that works.
          const cur = currentSelection(this.ctx);
          const stillValid = chatAvail.some(
            (m) => m.providerId === cur.providerId && m.model === cur.model,
          );
          if (!stillValid && chatAvail.length > 0) {
            const first = chatAvail[0];
            log.info('home:session-new:snap', { providerId: first.providerId, model: first.model });
            await setActiveProviderId(this.ctx, first.providerId);
            await setActiveModel(this.ctx, first.model);
          }
          log.info('home:session-new:dispatch', {});
          await vscode.commands.executeCommand('aiKing.sessions.new');
          return;
        }
        case 'bridge:open':
          log.info('home:bridge-open', {});
          await vscode.commands.executeCommand('aiKing.bridge.open');
          return;
        case 'bridge:join':
          log.info('home:bridge-join', {});
          await vscode.commands.executeCommand('aiKing.bridge.join');
          return;
        case 'skill:install':
          await vscode.commands.executeCommand('aiKing.skill.install');
          return;
        case 'room:open':
          if (typeof msg.room === 'string') {
            await vscode.commands.executeCommand('aiKing.bridge.open', msg.room);
          }
          return;
        case 'room:create':
          // Unify with the full create wizard: bridge.open WITHOUT a room name runs
          // the 本機/線上 + server-guidance flow (and refreshes Home on success).
          // Previously this built a bare 本機 room and asked the wrong question —
          // inconsistent with the ＋新群組 button. One create path now, no drift.
          log.info('home:room-create', {});
          await vscode.commands.executeCommand('aiKing.bridge.open');
          return;
        case 'room:rename': {
          const room = String(msg.room || '');
          if (!room) return;
          // [2026-06-18 user 防呆按鈕層] 列表「改名」鈕(群主才看得到)→ 開群組面板並觸發群組改名。重用面板內
          // 既有 authority.rename(改 displayName、owner-only、廣播全員、⛔不動 room id/歷史=不會弄丟群組)；
          // ⛔守住舊教訓：絕不退回 renameRoom() 的 fs.renameSync 改 room id 脫鉤大 BUG，走面板的正確路徑。
          void BridgePanel.createOrShow(this.ctx, room).externalRename();
          return;
        }
        case 'room:delete':
          if (typeof msg.room === 'string' && msg.room) {
            // [2026-06-18 user 防呆按鈕層] 列表「解散群組」鈕(群主才看得到)→ 開群組面板並觸發解散。重用面板內
            // 既有 authority.dissolve(真刪整房+廣播 room.dissolve、owner-only)+本機 deleteRoom，不再只導向提示。
            // 列表鈕只對群主顯示，disbandWithConfirm 內仍 selfRole==='owner' 把關＝身分層級 UI + host 雙保險。
            void BridgePanel.createOrShow(this.ctx, msg.room).externalDisband();
          }
          return;
        case 'session:delete':
          if (typeof msg.id === 'string') {
            // [A6] 刪對話＝連同它的「上下文」一併清，不只刪檔：
            //   ① ACP 子進程連線（per-session 長駐；不殺＝孤兒進程 + 下次同 id 對話重用舊
            //      ACP session 記憶，造成「刪了還記得」）。
            //   ② 開著的對話面板（否則殘留指向已刪 session 的殭屍面板、還能發訊息）。
            // 兩者皆 best-effort（disposeAcpConnection 無連線即 no-op、closeForSession 無面板即 no-op）。
            disposeAcpConnection(msg.id);
            ChatPanel.closeForSession(msg.id);
            await this.store.delete(msg.id);
            if (getActiveSessionId(this.ctx) === msg.id) {
              await setActiveSessionId(this.ctx, undefined);
            }
            await this.postState();
          }
          return;
        case 'session:activate':
          if (typeof msg.id === 'string') {
            await setActiveSessionId(this.ctx, msg.id);
            await this.postState();
          }
          return;
        case 'mode:set':
          if (isChatMode(msg.mode)) {
            await setLastMode(this.ctx, msg.mode);
            await this.postState();
          }
          return;
        case 'stack:set':
          if (typeof msg.stack === 'string') {
            const cfg = vscode.workspace.getConfiguration('aiKing');
            // [v3] 末列「＋新增／設定 ACP 代理」→ 跑設定精靈、設成新對話預設代理。
            if (msg.stack === '__acp_add__') {
              const chosen = await acpSetupWizard();
              if (chosen) {
                await cfg.update('acpAgent', chosen, vscode.ConfigurationTarget.Global);
                await cfg.update('stack', `acp:${chosen}`, vscode.ConfigurationTarget.Global);
              }
              await this.postState();
              return;
            }
            let toStore = msg.stack;
            // [v3] Agent 下拉的 ACP 具名選項 'acp:<id>'（選「Claude Code」即 stack=acp:claude）：未設定的代理
            //   （gemini/hermes/goose…）先跑精靈設好；並同步 aiKing.acpAgent 讓對話面板/凍結身分/新對話對得上。
            if (msg.stack.startsWith('acp:')) {
              const aid = msg.stack.split(':')[1];
              if (aid) {
                let chosen = aid;
                if (!acpAgentHasCommand(aid)) {
                  const c = await acpSetupWizard(aid);
                  if (!c) {
                    await this.postState();
                    return;
                  } // 取消設定 → 不切
                  chosen = c;
                }
                await cfg.update('acpAgent', chosen, vscode.ConfigurationTarget.Global);
                toStore = `acp:${chosen}`;
              }
            }
            await cfg.update('stack', toStore, vscode.ConfigurationTarget.Global);
            await this.postState();
          }
          return;
        case 'acpAgent:set': {
          // [CBUA B+] MODEL 槽變身的 ACP 代理下拉 → 設 aiKing.acpAgent（或末列＋新增走精靈）。
          const aid = (msg as { acpAgent?: string }).acpAgent;
          if (typeof aid === 'string') {
            if (aid === '__add__') {
              await acpSetupWizard();
            } else {
              await vscode.workspace
                .getConfiguration('aiKing')
                .update('acpAgent', aid, vscode.ConfigurationTarget.Global);
            }
            await this.postState();
          }
          return;
        }
        case 'model:set':
          // [1.7.0] sidebar Model picker → workspaceState default (= next chat).
          if (typeof msg.providerId === 'string' && typeof msg.model === 'string') {
            // Only accept providers that still exist; ignore stale ids silently.
            if (findProvider(msg.providerId)) {
              await setActiveProviderId(this.ctx, msg.providerId);
              await setActiveModel(this.ctx, msg.model);
              await this.postState();
            }
          }
          return;
        case 'provider:set':
          // [v3] 側欄「供應商」列：選供應商 → 寫 workspaceState active provider（新對話預設）；
          //   webview 同時帶該供應商第一個模型一起 snap，免得換家後模型還停在舊家。
          //   （ACP 時這只是顯示標記，仍走同一條 workspaceState → 新對話 session.providerId/model。）
          if (typeof msg.providerId === 'string' && findProvider(msg.providerId)) {
            await setActiveProviderId(this.ctx, msg.providerId);
            if (typeof msg.model === 'string' && msg.model) {
              await setActiveModel(this.ctx, msg.model);
            }
            await this.postState();
          }
          return;
        case 'effort:set':
          // [1.7.0] sidebar Effort picker → aiKing.effort (= next chat default).
          await vscode.workspace
            .getConfiguration('aiKing')
            .update(
              'effort',
              typeof msg.value === 'string' ? msg.value : '',
              vscode.ConfigurationTarget.Global,
            );
          await this.postState();
          return;
        case 'settings:open':
        case 'openSettings':
          await vscode.commands.executeCommand('aiKing.settings.open');
          return;
        case 'auth:signIn':
          await vscode.commands.executeCommand('aiKing.auth.signIn');
          await this.postState();
          return;
        case 'auth:signOut':
          await vscode.commands.executeCommand('aiKing.auth.signOut');
          await this.postState();
          return;
      }
    } catch (e: any) {
      console.warn(`[ai-king] home view onMessage: ${e?.message || String(e)}`);
    }
  }
}

constructor(
  private readonly ctx: vscode.ExtensionContext,
  private readonly store: SessionStore,
) {
  ctx.subscriptions.push(
    store.onDidChange(() => void this.postState()),
    vscode.workspace.onDidChangeConfiguration((e) => {
      if (e.affectsConfiguration('aiKing')) {
        // Provider list / key edits can change which models are reachable —
        // drop the cache so the next push re-probes.
        if (e.affectsConfiguration('aiKing.providers')) {
          for (const p of loadProviders()) this.statusStore.invalidate(p.id);
        }
        void this.postState();
      }
    }),
    // Re-push the model list whenever a probe result lands so the dropdown
    // fills in as soon as connectivity is known (no manual refresh).
    this.statusStore.onDidChange(() => void this.postModels()),
    // Let other surfaces (e.g. the bridge panel's create-group flow) ask the
    // Home list to re-read rooms immediately, so a freshly created group shows
    // up without waiting for a visibility toggle.
    vscode.commands.registerCommand('aiKing.home.refresh', () => this.refresh()),
    { dispose: () => this.statusStore.dispose() },
  );
}

resolveWebviewView(
  view: vscode.WebviewView,
  _context: vscode.WebviewViewResolveContext,
  _token: vscode.CancellationToken,
): void {
  this.view = view;
  view.webview.options = {
    enableScripts: true,
    localResourceRoots: [vscode.Uri.joinPath(this.ctx.extensionUri, 'media')],
  };
  view.webview.html = this.buildHtml(view.webview);
  view.webview.onDidReceiveMessage((msg) => void this.onMessage(msg));
  view.onDidDispose(() => {
    this.view = undefined;
  });

  // 0.14.0: prevent VS Code/Cursor from auto-opening the secondary
  // (auxiliary) sidebar when our activity-bar icon is first clicked.
  // When the primary sidebar opens, some hosts restore the last auxiliary
  // view (typically Copilot Chat). We close it once, right after our view
  // becomes visible, so the user is not greeted by an unrelated panel.
  //
  // Guarded by a workspace-scoped one-shot flag so we don't repeatedly
  // close an auxiliary bar the user has intentionally reopened later in
  // the session.
  const ONE_SHOT_KEY = 'aiKing.home.auxClosedOnce';
  const suppressAux = (): void => {
    const already = this.ctx.workspaceState.get<boolean>(ONE_SHOT_KEY, false);
    if (already) return;
    // Defer one tick so the host finishes its own sidebar restoration
    // before we issue the close command (otherwise our close can be
    // overridden by the restore).
    setTimeout(() => {
      vscode.commands
        .executeCommand('workbench.action.closeAuxiliaryBar')
        .then(
          () => {
            void this.ctx.workspaceState.update(ONE_SHOT_KEY, true);
          },
          () => {
            // Command may be unavailable in some hosts; never throw.
            void this.ctx.workspaceState.update(ONE_SHOT_KEY, true);
          },
        );
    }, 50);
  };

  if (view.visible) {
    suppressAux();
  }
  view.onDidChangeVisibility(() => {
    if (view.visible) suppressAux();
  });

  void this.postState();
}

refresh(): void {
  void this.postState();
}

