  | { type: 'language:set'; lang: 'zh-TW' | 'en' }
  // [1.8.3] settings page「對話歷史自動清理」switches/params → host writes
  // aiKing.conversation.*. key is the short field name; value bool or number.
  | { type: 'conv:set'; key: 'pruneByCountEnabled' | 'maxCount' | 'pruneByInactivityEnabled' | 'inactivityDays'; value: boolean | number }
  // [1.8.0 §15] per-conversation AI nickname (point-avatar → rename, like a
  // group member). Empty clears it (falls back to the model name).
  | { type: 'session:setAiName'; name: string }
  // [1.8.0 §15] the user's own display name (point-own-avatar → rename).
  | { type: 'user:setDisplayName'; name: string }
  // [1.8.2] avatar upload — pick an image for yourself / this conversation's AI.
  | { type: 'user:setAvatar' }
  | { type: 'session:setAiAvatar' }
  // [1.8.4] reveal the AI King diagnostic output channel (error bubble → 查看診斷紀錄).
  | { type: 'log:show' }
