  | { type: 'tools:set'; id: string; enabled: boolean }
  | { type: 'autoApproveAll:set'; enabled: boolean }
  | { type: 'authMode:set'; mode: string }
  // [1.9.1] webview-side end-to-end trace → AI King diagnostic channel. Lets one
  // test reveal exactly which step of doSend→host→provider→render the flow stalls.
  | { type: 'log:trace'; tag: string; data?: unknown };

export interface TargetRatings {
  raters: Record<string, RatingLevel>;
}

export interface RatingCounts {
  up: number;
  ok: number;
  down: number;
  total: number;
}

function ratingsKey(room: string): string {
  return `aiKing.peerRating.${room}`;
}

export function loadRoomRatings(ctx: vscode.ExtensionContext, room: string): RoomRatings {
  return ctx.globalState.get<RoomRatings>(ratingsKey(room)) || {};
}

async function saveRoomRatings(
  ctx: vscode.ExtensionContext,
  room: string,
  data: RoomRatings,
): Promise<void> {
  await ctx.globalState.update(ratingsKey(room), data);
}

function countsOf(t: TargetRatings | undefined): RatingCounts {
  const c: RatingCounts = { up: 0, ok: 0, down: 0, total: 0 };
  if (!t) return c;
  for (const lv of Object.values(t.raters)) {
    if (lv === 'up') c.up++;
    else if (lv === 'ok') c.ok++;
    else if (lv === 'down') c.down++;
  }
  c.total = c.up + c.ok + c.down;
  return c;
}

export async function setRating(
  ctx: vscode.ExtensionContext,
  room: string,
  raterId: string,
  targetId: string,
  level: RatingLevel,
): Promise<{ counts: RatingCounts; applied: 'set' | 'changed' | 'cleared' }> {
  const data = loadRoomRatings(ctx, room);
  const t: TargetRatings = data[targetId] || { raters: {} };
  const prev = t.raters[raterId];
  let applied: 'set' | 'changed' | 'cleared';
  if (prev === level) {
    delete t.raters[raterId]; // 再按同一個＝取消
    applied = 'cleared';
  } else {
    t.raters[raterId] = level;
    applied = prev ? 'changed' : 'set';
  }
  data[targetId] = t;
  await saveRoomRatings(ctx, room, data);
  return { counts: countsOf(t), applied };
}

export function countsForTarget(
  ctx: vscode.ExtensionContext,
  room: string,
  targetId: string,
): RatingCounts {
  const data = loadRoomRatings(ctx, room);
  return countsOf(data[targetId]);
}

export function myRatingOf(
  ctx: vscode.ExtensionContext,
  room: string,
  raterId: string,
  targetId: string,
): RatingLevel | undefined {
  const data = loadRoomRatings(ctx, room);
  return data[targetId]?.raters[raterId];
}

export function wilsonScore(counts: RatingCounts, minN = 15): number | null {
  const n = counts.total;
  if (n < minN) return null;
  const pHat = (counts.up + 0.5 * counts.ok) / n;
  const z = 1.96;
  const z2 = z * z;
  const denom = 1 + z2 / n;
  const center = pHat + z2 / (2 * n);
  const margin = z * Math.sqrt((pHat * (1 - pHat) + z2 / (4 * n)) / n);
  return (center - margin) / denom;
}

export function trustFromCounts(counts: RatingCounts): number {
  const base = 0.7;
  const raw = base + (counts.up - counts.down) * 0.05;
  let t = Math.max(0.05, Math.min(0.95, raw));
  if (counts.total < 5) {
    // 新手保護：往中值收縮（樣本越少越靠 0.7、不武斷判定能力）。
    const w = counts.total / 5;
    t = base * (1 - w) + t * w;
  }
  return t;
}

export function trustGrade(trust: number): 'A' | 'B' | 'C' | 'D' {
  if (trust > 0.85) return 'A';
  if (trust >= 0.5) return 'B';
  if (trust >= 0.3) return 'C';
  return 'D';
}

function sancioRepo(): string {
  const cfg = vscode.workspace.getConfiguration('aiKing').get<string>('sancioRepoPath');
  return cfg && cfg.trim() ? cfg.trim() : DEFAULT_REPO;
}

function sancioWorkspace(repo: string): string {
  return path.join(repo, '..', '..', '.sancio_workspace');
}

export function sancioBaseUrl(): string {
  return `http://${HOST}:${PORT}`;
}

export function sancioHealthy(): Promise<boolean> {
  return new Promise((resolve) => {
    const req = http.get(`${sancioBaseUrl()}/v1/privacy`, (r) => {
      resolve(r.statusCode === 200);
      r.resume();
    });
    req.on('error', () => resolve(false));
    req.setTimeout(2000, () => {
      req.destroy();
      resolve(false);
    });
  });
}

export async function ensureSancioRunning(): Promise<boolean> {
  if (await sancioHealthy()) return true;
  const repo = sancioRepo();
  const py = path.join(repo, '.venv', 'Scripts', 'python.exe');
  if (!fs.existsSync(py)) {
    void vscode.window.showWarningMessage(
      `AI King Agent：找不到 Sancio venv（${py}）。請先讓後端修好 venv，或用設定 aiKing.sancioRepoPath 指向你的 Sancio 專案，AI 代理才能用 LLM 幹活。`,
    );
    return false;
  }
  const ws = sancioWorkspace(repo);
  try { fs.mkdirSync(ws, { recursive: true }); } catch { /* best-effort */ }

  let stdio: cp.StdioOptions = 'ignore';
  try {
    const out = fs.openSync(path.join(repo, 'sancio_server.log'), 'a');
    stdio = ['ignore', out, out];
  } catch { /* fall back to ignore */ }

  try {
    proc = cp.spawn(
      py,
      ['-m', 'uvicorn', 'persona.api:create_standalone_app', '--factory',
        '--host', HOST, '--port', String(PORT)],
      {
        cwd: repo,
        env: { ...process.env, SANCIO_REQUIRE_AUTH: '0', SANCIO_WORKSPACE_ROOT: ws },
        stdio,
        windowsHide: true,
      },
    );
    proc.on('exit', () => { proc = null; });
    proc.on('error', () => { proc = null; });
  } catch {
    return false;
  }

  for (let i = 0; i < 30; i++) {
    await new Promise((r) => setTimeout(r, 500));
    if (await sancioHealthy()) return true;
  }
  return false;
}

export function stopSancio(): void {
  if (proc && !proc.killed) {
    try { proc.kill(); } catch { /* ignore */ }
  }
  proc = null;
}

function getNonce(): string {
  let text = '';
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  for (let i = 0; i < 32; i++) {
    text += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return text;
}

function defaultSkillFolders(): SkillFolder[] {
  const home = os.homedir();
  return [
    { label: 'AI King Agent', path: path.join(home, '.aiking', 'skills'), locked: true },
    { label: 'Claude', path: path.join(home, '.claude', 'skills') },
    // Codex 讀 ~/.codex/prompts 的「最上層 .md 檔」當自訂提示（不讀子資料夾、無 skills 概念）
    // — 故路徑是 prompts 不是 skills（2026-06-14 查證 developers.openai.com/codex/custom-prompts）。
    { label: 'Codex', path: path.join(home, '.codex', 'prompts') },
  ];
}

function normalizeLockedFirst(list: SkillFolder[]): SkillFolder[] {
  const lockedIdx = list.findIndex((f) => f.locked);
  if (lockedIdx === -1) {
    // config 被外部破壞掉 locked → 補回預設 AI King Agent 當第一個
    return [{ ...defaultSkillFolders()[0] }, ...list.map((f) => ({ ...f, locked: false }))];
  }
  const locked = { ...list[lockedIdx], locked: true };
  const rest = list.filter((_, i) => i !== lockedIdx).map((f) => ({ ...f, locked: false }));
  return [locked, ...rest];
}

function readSkillFolders(): SkillFolder[] {
  const raw = vscode.workspace.getConfiguration('aiKing').get<SkillFolder[]>('skillFolders');
  const list = Array.isArray(raw)
    ? raw.filter((f) => f && typeof f.path === 'string' && typeof f.label === 'string')
    : [];
  if (list.length === 0) return defaultSkillFolders();
  return normalizeLockedFirst(list);
}

async function writeSkillFolders(folders: SkillFolder[]): Promise<SkillFolder[]> {
  const cleaned = (Array.isArray(folders) ? folders : []).filter(
    (f) => f && typeof f.path === 'string' && typeof f.label === 'string',
  );
  const list = normalizeLockedFirst(cleaned);
  await vscode.workspace
    .getConfiguration('aiKing')
    .update('skillFolders', list, vscode.ConfigurationTarget.Global);
  return list;
}

export class SettingsPanel {
  public static currentPanel: SettingsPanel | undefined;

  public static readonly viewType = 'aiKing.settings';

  private readonly panel: vscode.WebviewPanel;
  private readonly ctx: vscode.ExtensionContext;
  private readonly disposables: vscode.Disposable[] = [];
  // 1.7.0 — shared connection-probe store (TTL 60s + onDidChange).
  private readonly statusStore = new ProviderStatusStore();

  public static createOrShow(ctx: vscode.ExtensionContext): void {
    const column = vscode.window.activeTextEditor
      ? vscode.window.activeTextEditor.viewColumn
      : vscode.ViewColumn.One;

    if (SettingsPanel.currentPanel) {
      SettingsPanel.currentPanel.panel.reveal(column);
      void SettingsPanel.currentPanel.postState();
      return;
    }

    const panel = vscode.window.createWebviewPanel(
      SettingsPanel.viewType,
      th('settings.title'),
      column || vscode.ViewColumn.One,
      {
        enableScripts: true,
        retainContextWhenHidden: true,
        localResourceRoots: [vscode.Uri.joinPath(ctx.extensionUri, 'media', 'webview')],
      },
    );

    SettingsPanel.currentPanel = new SettingsPanel(panel, ctx);
  }

  private constructor(panel: vscode.WebviewPanel, ctx: vscode.ExtensionContext) {
    this.panel = panel;
    this.ctx = ctx;

    this.panel.webview.html = this.buildHtml();

    this.panel.onDidDispose(() => this.dispose(), null, this.disposables);
    this.panel.webview.onDidReceiveMessage(
      (msg: WebMessage) => this.handleMessage(msg),
      null,
      this.disposables,
    );
  }

  public dispose(): void {
    SettingsPanel.currentPanel = undefined;
    this.statusStore.dispose();
    this.panel.dispose();
    while (this.disposables.length) {
      const d = this.disposables.pop();
      if (d) d.dispose();
    }
  }

  // --------------------------------------------------------------------------
  // State push
  // --------------------------------------------------------------------------

  private async postState(): Promise<void> {
    const providers = loadProviders();
    const views: ProviderStateView[] = [];
    for (const p of providers) {
      views.push({ provider: p, hasKey: await hasProviderKey(this.ctx, p.id) });
    }
    const cfg = vscode.workspace.getConfiguration('aiKing');
    const msg: HostMessage = {
      type: 'state',
      providers: views,
      activeProviderId: getActiveProviderId(this.ctx),
      activeModel: getActiveModel(this.ctx),
      mode: getLastMode(this.ctx),
      modes: CHAT_MODES,
      conv: {
        pruneByCountEnabled: cfg.get<boolean>('conversation.pruneByCountEnabled') !== false,
        maxCount: cfg.get<number>('conversation.maxCount') ?? 20,
        pruneByInactivityEnabled: cfg.get<boolean>('conversation.pruneByInactivityEnabled') !== false,
        inactivityDays: cfg.get<number>('conversation.inactivityDays') ?? 30,
      },
      // [G 授權與工具頁 1.24.32] AI King Agent(clean) 工具開關生效值 + 授權設定。
      authTools: {
        tools: ALL_TOOL_IDS.map((id) => ({
          id,
          label: TOOL_LABELS[id],
          enabled: enabledToolIdsForStack('clean').includes(id),
        })),
        autoApproveAll: cfg.get<boolean>('autoApproveAll') === true,
        defaultMode: getLastMode(this.ctx),
      },
    };
    await this.panel.webview.postMessage(msg);
  }

  private async postError(message: string): Promise<void> {
    const msg: HostMessage = { type: 'error', message };
    await this.panel.webview.postMessage(msg);
  }

  private async postSuccess(message: string): Promise<void> {
    const msg: HostMessage = { type: 'success', message };
    await this.panel.webview.postMessage(msg);
  }

  private async postSkillFolders(folders?: SkillFolder[]): Promise<void> {
    const list = folders || readSkillFolders();
    const msg: HostMessage = { type: 'skillFolders', folders: list };
    await this.panel.webview.postMessage(msg);
  }

  // [1.8.0 §13] push the current interface language (single source of truth =
  // `aiKing.language`) so the webview's AiKingI18n switches dictionaries.
  private async postLang(): Promise<void> {
    const msg: HostMessage = { type: 'i18n:lang', lang: uiLang() };
    await this.panel.webview.postMessage(msg);
  }

  // --------------------------------------------------------------------------
  // Message handlers
  // --------------------------------------------------------------------------

  private async handleMessage(msg: WebMessage): Promise<void> {
    try {
      switch (msg.type) {
        case 'ready':
        case 'refresh':
          // [1.8.0 §13] language first, so the first renders use the right
          // dictionary (a later switch re-renders via aiking-lang-changed).
          await this.postLang();
          await this.postState();
          await this.postSkillFolders();
          // 1.7.0 — auto-probe every provider that has a key or is none-auth,
          // so each row shows a live connection status capsule on open.
          void this.probeAllProviders();
          return;
        case 'language:set': {
          // [1.8.0 §13] settings page「介面語言」segmented control → persist
          // to aiKing.language (Global) and re-push to this webview.
          const lang = msg.lang === 'en' ? 'en' : 'zh-TW';
          await vscode.workspace
            .getConfiguration('aiKing')
            .update('language', lang, vscode.ConfigurationTarget.Global);
          await this.postLang();
          return;
        }
        case 'tools:set': {
          // [G 授權與工具頁 1.24.32] AI King Agent(clean) 工具開關 → aiKing.tools.byStack.clean.<id>。
          //   讀回整個 byStack object 改子鍵再寫回（⛔不用 update(dotted-key, ...) 會炸巢狀鍵）。
          const cfg2 = vscode.workspace.getConfiguration('aiKing');
          const byStack = JSON.parse(
            JSON.stringify(cfg2.get<Record<string, Record<string, boolean>>>('tools.byStack') || {}),
          );
          if (!byStack.clean) byStack.clean = {};
          byStack.clean[msg.id] = !!msg.enabled;
          await cfg2.update('tools.byStack', byStack, vscode.ConfigurationTarget.Global);
          await this.postState();
          return;
        }
        case 'autoApproveAll:set':
          await vscode.workspace
            .getConfiguration('aiKing')
            .update('autoApproveAll', !!msg.enabled, vscode.ConfigurationTarget.Global);
          await this.postState();
          return;
        case 'authMode:set': {
          // [G 授權與工具頁 1.24.32] 預設權限模式 → setLastMode（gate currentMode 讀的同源、與對話 ☰ 一致）。
          const m = isChatMode(msg.mode) ? msg.mode : ('auto' as ChatMode);
          await setLastMode(this.ctx, m);
          await this.postState();
          return;
        }
        case 'conv:set': {
          // [1.8.3]「對話歷史自動清理」switches/params → persist to
          // aiKing.conversation.* (Global). Number params clamp to >= 1.
          const key = msg.key;
          let value = msg.value;
          if ((key === 'maxCount' || key === 'inactivityDays') && typeof value === 'number') {
            value = Math.max(1, Math.round(value));
          }
          await vscode.workspace
            .getConfiguration('aiKing')
            .update(`conversation.${key}`, value, vscode.ConfigurationTarget.Global);
          await this.postState();
          return;
        }
        case 'provider:add':
          await upsertProvider(msg.provider);
          await this.postSuccess(`${th('settings.toast.providerAdded')}: ${msg.provider.name}`);
          await this.postState();
          // 1.7.0 (PLAN §9.2) — immediately probe the new provider so its
          // status capsule shows a live result the moment it appears.
          this.statusStore.invalidate(msg.provider.id);
          void this.probeProviderById(msg.provider.id);
          return;
        case 'provider:update': {
          await patchProvider(msg.id, msg.patch);
          // [1.8.0 §11.2] curation-only patch（「移除」/「＋ 加入」改 models、
          // 或備註改 modelNotes）— endpoint/金鑰沒變，跳過 invalidate + re-probe
          // （保留 webview 端 detectedModels，✓/？與偵測清單不閃「測試中」），
          // 也不跳 toast（清單本身的增減就是回饋，比照 setModelNote 靜默自動存）。
          const patchKeys = Object.keys(msg.patch);
          const curationOnly =
            patchKeys.length > 0 &&
            patchKeys.every((k) => k === 'models' || k === 'modelNotes');
          if (!curationOnly) {
            await this.postSuccess(`${th('settings.toast.providerUpdated')}: ${msg.id}`);
          }
          await this.postState();
          if (!curationOnly) {
            // 1.7.0 — endpoint / authType may have changed → invalidate + re-probe.
            this.statusStore.invalidate(msg.id);
            void this.probeProviderById(msg.id);
          }
          return;
        }
        case 'provider:delete': {
          // 1.8.0: webview confirm() is sandbox-blocked (no-op), so the
          // confirmation happens here with a native modal instead.
          const victim = findProvider(msg.id);
          const deleteBtn = th('settings.confirmDeleteBtn');
          const ok = await vscode.window.showWarningMessage(
            th('settings.confirmDelete').replace('{name}', victim ? victim.name : msg.id),
            { modal: true },
            deleteBtn,
          );
          if (ok !== deleteBtn) return;
          await deleteProvider(this.ctx, msg.id);
          await this.postSuccess(`${th('settings.toast.providerDeleted')}: ${msg.id}`);
          await this.postState();
          return;
        }
        case 'provider:setKey':
          await setProviderKey(this.ctx, msg.id, msg.key);
          await this.postSuccess(`${th('settings.toast.keySaved')}: ${msg.id}`);
          await this.postState();
          // 1.7.0 — key changed → invalidate cached status + re-probe.
          this.statusStore.invalidate(msg.id);
          void this.probeProviderById(msg.id);
          return;
        case 'provider:setKeyNative': {
          // [2026-06-21 user directive] API 金鑰一律走 VS Code 原生 masked 對話框（做法對齊 CC）：
          //   金鑰直接從原生輸入框 → SecretStorage，⛔ 不經 webview DOM、⛔ 不經對話 transcript。
          //   webview 只送 provider id、host 這裡彈原生 showInputBox 收金鑰（memory
          //   `feedback-credentials-auto-vault-native-input`）。
          if (typeof msg.id !== 'string') return;
          const prov = loadProviders().find((p) => p.id === msg.id);
          const key = await showInputBoxEsc({
            title: `API 金鑰 — ${prov?.name || msg.id}`,
            prompt: '貼上 API 金鑰（遮蔽輸入、不經網頁、不留對話）。留空取消。',
            password: true,
            ignoreFocusOut: true,
          });
          if (key === undefined) return; // 使用者按 Esc/取消
          const trimmed = key.trim();
          if (!trimmed) return;
          await setProviderKey(this.ctx, msg.id, trimmed);
          await this.postSuccess(`${th('settings.toast.keySaved')}: ${msg.id}`);
          await this.postState();
          this.statusStore.invalidate(msg.id);
          void this.probeProviderById(msg.id);
          return;
        }
        case 'provider:clearKey':
          await clearProviderKey(this.ctx, msg.id);
          await this.postSuccess(`${th('settings.toast.keyCleared')}: ${msg.id}`);
          await this.postState();
          // 1.7.0 — key removed → invalidate + re-probe (likely now unset).
          this.statusStore.invalidate(msg.id);
          void this.probeProviderById(msg.id);
          return;
        case 'provider:setModelNote': {
          // 1.7.0 — per-model note (coexists with provider.notes). Empty = delete.
          const providers = loadProviders();
          const p = providers.find((x) => x.id === msg.id);
          if (p) {
            const notes: Record<string, string> = { ...(p.modelNotes || {}) };
            const trimmed = (msg.note || '').trim();
            if (trimmed) {
              notes[msg.model] = trimmed;
            } else {
              delete notes[msg.model];
            }
            await patchProvider(msg.id, { modelNotes: notes });
            await this.postState();
          }
          return;
        }
        case 'provider:setActive': {
          await setActiveProviderId(this.ctx, msg.id);
          await setActiveModel(this.ctx, msg.model);
          await this.postSuccess(`${th('settings.toast.activeSwitched')}: ${msg.id} · ${msg.model}`);
          await this.postState();
          return;
        }
        case 'provider:test':
          await this.testProvider(msg.id);
          return;
        case 'mode:setActive':
          if (isChatMode(msg.mode)) {
            await setLastMode(this.ctx, msg.mode);
            await this.postSuccess(`${th('settings.toast.modeSwitched')}: ${msg.mode}`);
            await this.postState();
          }
          return;
        case 'skillFolders:get':
          await this.postSkillFolders();
          return;
        case 'skillFolders:set': {
          const saved = await writeSkillFolders(msg.folders);
          await this.postSkillFolders(saved);
          return;
        }
        case 'skillFolders:browse': {
          const picked = await vscode.window.showOpenDialog({
            canSelectFolders: true,
            canSelectFiles: false,
            canSelectMany: false,
            openLabel: th('settings.dialog.pickFolderLabel'),
            title: th('settings.dialog.pickFolderTitle'),
          });
          if (picked && picked[0]) {
            const out: HostMessage = {
              type: 'skillFolders:browsed',
              index: msg.index,
              path: picked[0].fsPath,
            };
            await this.panel.webview.postMessage(out);
          }
          return;
        }
      }
    } catch (e: any) {
      await this.postError(e?.message || String(e));
    }
  }

  private async testProvider(id: string): Promise<void> {
    // A manual "測試" click is a force re-probe (skip the TTL cache).
    await this.probeProviderById(id, true);
  }

  /**
   * 1.7.0 — probe one provider via the shared store (status.ts) and push a
   * `testResult` (with detectedModels) to the webview. `force` skips the TTL
   * cache (manual 測試 / key-or-endpoint change). For none-auth providers we
   * still probe (Ollama-type local endpoints are reachable without a key).
   */
  private async probeProviderById(id: string, force = false): Promise<void> {
    const providers = loadProviders();
    const p = providers.find((x) => x.id === id);
    if (!p) {
      if (force) await this.postError(`${th('settings.error.providerNotFound')}: ${id}`);
      return;
    }
    const keyless = p.authType === 'none';
    if (!keyless && !(await hasProviderKey(this.ctx, id))) {
      // No key and not none-auth → nothing to probe; the row shows 未設定金鑰.
      return;
    }
    const key = keyless ? '' : await getProviderKey(this.ctx, id);
    const res = await this.statusStore.probe(p, key, force);
    const out: HostMessage = {
      type: 'testResult',
      providerId: id,
      ok: res.ok,
      message: res.message,
      detectedModels: res.detectedModels,
    };
    await this.panel.webview.postMessage(out);
  }

  /**
   * 1.7.0 — on panel open / refresh, probe every provider that has a key or is
   * none-auth so each row shows a live status capsule. Keyless providers with
   * no upstream are simply marked offline by their result.
   * [M10] Concurrency is capped (worker pool) so opening Settings doesn't fire
   * 7-8 simultaneous network probes (each a 5s-timeout fetch) at every
   * configured endpoint at once. Tunable via aiKing.settings.probeConcurrency.
   */
  private async probeAllProviders(): Promise<void> {
    const providers = loadProviders();
    const limit = Math.min(
      16,
      Math.max(
        1,
        vscode.workspace.getConfiguration('aiKing').get<number>('settings.probeConcurrency') ?? 4,
      ),
    );
    const queue = [...providers];
    const worker = async (): Promise<void> => {
      for (;;) {
        const p = queue.shift();
        if (!p) return;
        await this.probeProviderById(p.id);
      }
    };
    await Promise.all(Array.from({ length: Math.min(limit, queue.length) }, () => worker()));
  }

  // --------------------------------------------------------------------------
  // HTML
  // --------------------------------------------------------------------------

  private buildHtml(): string {
    const nonce = getNonce();
    const webview = this.panel.webview;
    const htmlUri = vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'webview', 'settings.html');
    const cssUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'webview', 'settings.css'),
    );
    const dropdownCssUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'webview', 'dropdown.css'),
    );
    const dropdownJsUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this.ctx.extensionUri, 'media', 'webview', 'dropdown.js'),
    );
